fn read_secret_file_arg(value: &str) -> std::result::Result<String, String> {
    let path = Path::new(value);
    let mut secret =
        fs::read_to_string(path).map_err(|err| format!("reading {}: {err}", path.display()))?;
    if secret.ends_with('\n') {
        secret.pop();
        if secret.ends_with('\r') {
            secret.pop();
        }
    }
    Ok(secret)
}

