struct PayTnkArgs {
    /// USD amount of Mayhem credit to target, for example 10 or 10.25.
    #[arg(long)]
    amount: String,

    /// 32-byte hex nonce used with the wallet public key to derive the deposit binding.
    #[arg(long)]
    nonce: Option<String>,

    /// Peer JSON-RPC base URL, including /v1. Defaults to config.toml or local dev-net.
    #[arg(long)]
    rpc_url: Option<String>,

    /// Mayhem home directory. Defaults to MAYHEM_HOME or ~/.mayhem.
    #[arg(long, value_name = "PATH")]
    home: Option<PathBuf>,

    /// Exact keypair.json path for the local Trac wallet. Overrides config.toml and --peer-store-name.
    #[arg(long, value_name = "PATH")]
    keypair: Option<PathBuf>,

    /// Intercom peer store name under <home>/stores when config.toml has no identity store.
    #[arg(long, default_value = "main")]
    peer_store_name: String,

    /// File containing the encrypted keypair.json password.
    #[arg(long = "wallet-password-file", value_name = "PATH", value_parser = read_secret_file_arg)]
    wallet_password: Option<String>,

    /// Sign and submit the free TNK deposit intent feature through peer RPC.
    #[arg(long)]
    submit_intent: bool,

    /// Broadcast the matching MSB transfer from this local wallet. Requires --submit-intent.
    #[arg(long)]
    submit_transfer: bool,

    /// Confirm the pinned TNK destination without an interactive prompt.
    #[arg(long)]
    yes: bool,

    /// Maximum seconds to wait for MSB account sync and validator connection when --submit-transfer is used.
    #[arg(long, default_value_t = 180)]
    msb_transfer_timeout_seconds: u64,

    /// Submit with peer RPC sim mode when --submit-intent is used.
    #[arg(long)]
    sim: bool,

    /// Wait for the contract ledger balance to reflect the TNK credit.
    #[arg(long)]
    wait: bool,

    /// Maximum seconds to wait for ledger credit when --wait is used.
    #[arg(long, default_value_t = 900)]
    timeout_seconds: u64,

    /// Poll interval in milliseconds while waiting for ledger credit.
    #[arg(long, default_value_t = 2_000)]
    poll_interval_ms: u64,

    /// Print a machine-readable TNK payment report.
    #[arg(long)]
    json: bool,
}

#[derive(Debug, Parser)]
struct DepositTapArgs {
    #[command(flatten)]
    wallet: WalletLocatorArgs,

    /// TAP amount to deposit, for example 10 or 10.25.
    #[arg(long, alias = "amount")]
    amount_tap: Option<String>,

    /// TAP amount as a raw 18-decimal integer wei string.
    #[arg(long)]
    amount_wei: Option<String>,

    /// Ethereum JSON-RPC URL for TAP balance checks, simulation, and broadcast.
    #[arg(long)]
    eth_rpc: Option<String>,

    /// Local Intercom peer JSON-RPC base URL, including /v1.
    #[arg(long)]
    peer_rpc_url: Option<String>,

    /// Bind this wallet's Ethereum account to its Mayhem identity without broadcasting a deposit.
    #[arg(long, conflicts_with_all = ["amount_tap", "amount_wei"])]
    bind_only: bool,

    /// Broadcast after the gas precheck and simulation pass. Without this, only dry-run.
    #[arg(long)]
    confirm: bool,

    /// Print a machine-readable local signing report.
    #[arg(long)]
    json: bool,
}

#[derive(Debug, Parser)]
struct DepositStatusArgs {
    /// Peer JSON-RPC base URL, including /v1. Defaults to config.toml or local dev-net.
    #[arg(long)]
    rpc_url: Option<String>,

    /// Mayhem home directory. Defaults to MAYHEM_HOME or ~/.mayhem.
    #[arg(long, value_name = "PATH")]
    home: Option<PathBuf>,

    /// Intercom peer store name under <home>/stores when config.toml has no identity store.
    #[arg(long, default_value = "main")]
    peer_store_name: String,

    /// File containing the encrypted keypair.json password.
    #[arg(long = "wallet-password-file", value_name = "PATH", value_parser = read_secret_file_arg)]
    wallet_password: Option<String>,

    /// Account to inspect. Defaults to the local Mayhem wallet public key.
    #[arg(long)]
    who: Option<String>,

    /// Ledger rail to inspect. Defaults to tnk for --deposit-binding, tap for --eth-tx-hash, otherwise fiat.
    #[arg(long, value_enum)]
    rail: Option<GatewayLedgerRail>,

    /// TNK deposit binding hash to check for a pending intent.
    #[arg(long = "deposit-binding", alias = "memo-hash")]
    memo_hash: Option<String>,

    /// TAP escrow transaction hash to check for admin-oracle confirmation.
    #[arg(long)]
    eth_tx_hash: Option<String>,

    /// TAP escrow Deposit log index. Auto-discovered from the ledger when omitted.
    #[arg(long)]
    log_index: Option<u64>,

    /// Balance threshold in au_usd that counts as confirmed.
    #[arg(long)]
    target_au: Option<MoneyAu>,

    /// Wait until --target-au is reached.
    #[arg(long)]
    wait: bool,

    /// Maximum seconds to wait for --target-au.
    #[arg(long, default_value_t = 900)]
    timeout_seconds: u64,

    /// Poll interval in milliseconds while waiting.
    #[arg(long, default_value_t = 2_000)]
    poll_interval_ms: u64,

    /// Print a machine-readable status report.
    #[arg(long)]
    json: bool,
}

