fn deserialize_optional_money_au<'de, D>(
    deserializer: D,
) -> std::result::Result<Option<MoneyAu>, D::Error>
where
    D: Deserializer<'de>,
{
    let value = Option::<String>::deserialize(deserializer)?;
    value
        .as_deref()
        .map(parse_decimal_money_au)
        .transpose()
        .map_err(serde::de::Error::custom)
}

fn deserialize_optional_money_au_map<'de, D>(
    deserializer: D,
) -> std::result::Result<Option<BTreeMap<String, MoneyAu>>, D::Error>
where
    D: Deserializer<'de>,
{
    let value = Option::<BTreeMap<String, String>>::deserialize(deserializer)?;
    value
        .map(|map| {
            map.into_iter()
                .map(|(key, value)| {
                    parse_decimal_money_au(&value)
                        .map(|au| (key, au))
                        .map_err(serde::de::Error::custom)
                })
                .collect()
        })
        .transpose()
}

#[cfg(not(target_os = "windows"))]
#[tokio::main]
async fn main() -> Result<()> {
    mayhem_main().await
}

#[cfg(target_os = "windows")]
fn main() -> Result<()> {
    std::thread::Builder::new()
        .name("mayhem-main".to_owned())
        .stack_size(16 * 1024 * 1024)
        .spawn(|| {
            tokio::runtime::Builder::new_multi_thread()
                .enable_all()
                .build()
                .context("building Windows CLI runtime")?
                .block_on(mayhem_main())
        })
        .context("spawning Windows CLI main thread")?
        .join()
        .map_err(|panic| {
            if let Some(message) = panic.downcast_ref::<&str>() {
                anyhow!("Windows CLI main thread panicked: {message}")
            } else if let Some(message) = panic.downcast_ref::<String>() {
                anyhow!("Windows CLI main thread panicked: {message}")
            } else {
                anyhow!("Windows CLI main thread panicked")
            }
        })?
}

async fn mayhem_main() -> Result<()> {
    let cli = Cli::parse();
    match cli.command {
        Commands::Setup(args) => setup(args).await,
        Commands::Wallet { command } => wallet_command(command).await,
        Commands::Deposit { command } => deposit_command(command).await,
        Commands::Withdraw(args) => withdraw(args).await,
        Commands::Dispute(args) => dispute(args).await,
        Commands::DisputeExpire(args) => dispute_expire(args).await,
        Commands::FraudProof { command } => match command {
            FraudProofCommands::Submit(args) => fraud_proof_submit(args).await,
            FraudProofCommands::Challenge(args) => fraud_proof_challenge(args).await,
        },
        Commands::Doctor(args) => doctor(args),
        Commands::Catalog { command } => match command {
            CatalogCommands::List(args) => catalog_list(args),
            CatalogCommands::Verify(args) => catalog_verify(args),
            CatalogCommands::Sign(args) => catalog_sign(args),
            CatalogCommands::ApplyAttestationAuthority(args) => {
                catalog_apply_attestation_authority(args)
            }
            CatalogCommands::ArtifactMetadata(args) => catalog_artifact_metadata(args),
            CatalogCommands::ApplyArtifactMetadata(args) => catalog_apply_artifact_metadata(args),
            CatalogCommands::ArtifactPlan(args) => catalog_artifact_plan(args),
            CatalogCommands::ArtifactStagePlan(args) => catalog_artifact_stage_plan(args),
            CatalogCommands::ArtifactPublishPlan(args) => catalog_artifact_publish_plan(args),
            CatalogCommands::CalibrateCanary(args) => catalog_calibrate_canary(args),
            CatalogCommands::MergeCanaryReports(args) => catalog_merge_canary_reports(args),
            CatalogCommands::CanaryEvidence(args) => catalog_canary_evidence(args),
            CatalogCommands::ApplyCanaryReports(args) => catalog_apply_canary_reports(args),
            CatalogCommands::CanaryMatrix(args) => catalog_canary_matrix(args),
            CatalogCommands::CanaryPlan(args) => catalog_canary_plan(args),
        },
        Commands::Provider { verbose, command } => provider_command(*command, verbose).await,
        Commands::Providers { command } => user_providers_command(command),
        Commands::Admin { command } => admin(*command).await,
        Commands::Up(args) => up(args).await,
        Commands::Use(args) => use_gateway(args).await,
        Commands::Tokens { command } => tokens_command(command),
        Commands::Models(args) => models(args).await,
        Commands::Price { command } => match command {
            PriceCommands::Show(args) => price_show(args).await,
        },
        Commands::Payments(args) => payments(args).await,
        Commands::Pay { command } => match command {
            PayCommands::Tnk(args) => pay_tnk(args).await,
            PayCommands::Stripe(args) => pay(PayRail::Stripe, args).await,
            PayCommands::Tap(args) => deposit_tap(args).await,
        },
        Commands::Balance(args) => balance(args).await,
        Commands::Status(args) => status(args).await,
        Commands::History(args) => session_history(args, false).await,
        Commands::Sessions(args) => session_history(args, true).await,
        Commands::Payouts(args) => payouts(args).await,
        Commands::Earnings(args) => earnings(args).await,
        Commands::Reputation(args) => reputation(args).await,
        Commands::Config { command } => match command {
            ConfigCommands::Get(args) => config_get(args),
            ConfigCommands::Set(args) => config_set(args),
            ConfigCommands::MaxPrice(args) => config_max_price(args),
        },
        Commands::Down(args) => down(args).await,
        Commands::Reset(args) => reset(args, "reset").await,
        Commands::Uninstall(args) => reset(args, "uninstall").await,
        Commands::Opencode(args) => opencode(args).await,
        Commands::Auditor { command } => match command {
            AuditorCommands::Canary(args) => auditor_canary(args).await,
        },
        Commands::Receipts { command } => match command {
            ReceiptsCommands::Export(args) => receipts_export(args).await,
            ReceiptsCommands::Publish(args) => receipts_publish(args).await,
            ReceiptsCommands::Collect(args) => receipts_collect(args).await,
        },
        Commands::Rules { command } => match command {
            RulesCommands::Hash(args) => rules_hash(args),
            RulesCommands::Review(args) => rules_review(args).await,
        },
        Commands::Test(args) => mayhem_test(args).await,
        Commands::Update(args) => update(args).await,
        Commands::ReleaseSign(args) => release_sign(args),
    }
}

async fn provider_command(command: ProviderCommands, verbose: bool) -> Result<()> {
    let result = match command {
        ProviderCommands::List(args) => provider_list(args).await,
        ProviderCommands::Health(args) => provider_health(args).await,
        ProviderCommands::Rails { command } => match command {
            ProviderRailsCommands::Get(args) => provider_rails_get(args).await,
            ProviderRailsCommands::Set(args) => provider_rails_set(args).await,
        },
        ProviderCommands::Payout { command } => match command {
            ProviderPayoutCommands::Get(args) => provider_payout_get(args).await,
            ProviderPayoutCommands::Set(args) => provider_payout_set(args, false).await,
            ProviderPayoutCommands::Rotate(args) => provider_payout_set(args, true).await,
        },
        ProviderCommands::Stripe { command } => match command {
            ProviderStripeCommands::Onboard(args) => provider_stripe_onboard(args, false).await,
            ProviderStripeCommands::Rotate(args) => provider_stripe_onboard(args, true).await,
            ProviderStripeCommands::Relink(args) => provider_stripe_relink(args).await,
            ProviderStripeCommands::Adopt(args) => provider_stripe_adopt(args).await,
            ProviderStripeCommands::Status(args) => provider_stripe_status(args).await,
        },
        ProviderCommands::MinAsk { command } => match command {
            ProviderMinAskCommands::Get(args) => provider_min_ask_get(args),
            ProviderMinAskCommands::Set(args) => provider_min_ask_set(args),
        },
        ProviderCommands::Limits { command } => match command {
            ProviderLimitsCommands::Get(args) => provider_limits_get(args),
            ProviderLimitsCommands::Set(args) => provider_limits_set(args),
        },
        ProviderCommands::Drain(args) => provider_drain(args).await,
        ProviderCommands::Earnings(args) => provider_earnings(args).await,
        ProviderCommands::Start(args) => provider_start(*args).await,
        ProviderCommands::Serve { command } => match command {
            ProviderServeCommands::Plan(args) => provider_serve_plan(args).await,
            ProviderServeCommands::Add(args) => provider_serve_add(args).await,
            ProviderServeCommands::Remove(args) => provider_serve_remove(args).await,
            ProviderServeCommands::Switch(args) => provider_serve_switch(args).await,
        },
        ProviderCommands::Join(args) => provider_join(args).await,
        ProviderCommands::Leave(args) => provider_leave(args).await,
        ProviderCommands::Stop(args) => provider_stop(args).await,
        ProviderCommands::Rooms { command } => match command {
            ProviderRoomsCommands::Join(args) => provider_room_join(args).await,
            ProviderRoomsCommands::Leave(args) => provider_room_leave(args).await,
        },
    };
    if verbose {
        result
    } else {
        result.map_err(|err| anyhow::anyhow!(provider_friendly_error(&err)))
    }
}

fn provider_friendly_error(error: &anyhow::Error) -> String {
    let raw = format!("{error:#}");
    let lower = raw.to_lowercase();
    let detail = |message: &str| {
        format!("{message} Run the same provider command with `--verbose` for technical details.")
    };
    if lower.contains("outofmemory")
        || lower.contains("out of memory")
        || lower.contains("cuda oom")
        || lower.contains("cuda out of memory")
        || lower.contains("not enough memory")
    {
        return detail(
            "Not enough memory to load this admin-approved model; close other GPU jobs or choose a smaller model from `mayhem models`.",
        );
    }
    if lower.contains("no space left")
        || lower.contains("disk full")
        || lower.contains("not enough disk")
        || lower.contains("insufficient disk")
    {
        return detail(
            "Not enough disk space to prepare this enclave; free space in the Mayhem home/downloads directory or choose another disk path.",
        );
    }
    if lower.contains("address already in use")
        || lower.contains("eaddrinuse")
        || lower.contains("port already in use")
        || (lower.contains("bind")
            && (lower.contains("in use") || lower.contains("permission denied")))
    {
        return detail(
            "A local Mayhem port is already in use; stop the other Mayhem process with `mayhem down` or choose different ports.",
        );
    }
    if lower.contains("wallet")
        || lower.contains("keypair")
        || lower.contains("password")
        || lower.contains("credential")
        || lower.contains("sc-bridge token")
        || lower.contains("token is required")
    {
        return detail(
            "Mayhem could not unlock the provider credentials; check the wallet password, keypair path, and local bridge token.",
        );
    }
    if lower.contains("hash")
        && (lower.contains("does not match")
            || lower.contains("mismatch")
            || lower.contains("artifact_root")
            || lower.contains("merkle")
            || lower.contains("sha"))
    {
        return detail(
            "The model artifact does not match the admin-signed enclave; delete the partial download/cache and try again.",
        );
    }
    if lower.contains("download")
        || lower.contains("huggingface")
        || lower.contains("http status")
        || lower.contains("fetching")
        || lower.contains("request failed")
    {
        return detail(
            "Mayhem could not download the admin-approved model artifact; check network access or provide an HF token file.",
        );
    }
    if lower.contains("mlx requires")
        || lower.contains("tensorrt-llm requires")
        || lower.contains("vllm launch artifacts require")
        || lower.contains("unsupported backend")
        || lower.contains("no feasible provider candidate")
        || lower.contains("backend mismatch")
        || lower.contains("architecture mismatch")
    {
        return detail(
            "This machine cannot serve the selected enclave/backend; run `mayhem models` to pick a compatible admin-approved model.",
        );
    }
    if lower.contains("sc-bridge")
        || lower.contains("websocket")
        || lower.contains("connection refused")
        || lower.contains("timed out")
        || lower.contains("timeout")
        || lower.contains("peer")
        || lower.contains("rpc")
        || lower.contains("unreachable")
    {
        return detail(
            "Mayhem could not reach the local peer or bridge; run `mayhem status`, then `mayhem up --provider --yes` after it is healthy.",
        );
    }
    if lower.contains("no open admin-created canonical rooms") {
        return detail(
            "No canonical room is open for this admin enclave; ask the admin to open a room before serving.",
        );
    }
    detail("Provider setup could not complete.")
}

async fn setup(args: SetupArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let role = select_role(args.role)?;
    let rpc_url = args
        .rpc_url
        .clone()
        .unwrap_or_else(|| DEFAULT_RPC_URL.to_owned());
    let store_path = home.join("stores").join(&args.peer_store_name);
    let keypair_path = store_path.join("db").join("keypair.json");
    let password = args.wallet_password.clone().unwrap_or_default();

    fs::create_dir_all(&home).with_context(|| format!("creating {}", home.display()))?;
    load_or_create_paygate_internal_auth_secret(&home)?;
    fs::create_dir_all(keypair_path.parent().expect("keypair has parent"))
        .with_context(|| format!("creating {}", keypair_path.display()))?;

    let wallet = materialize_wallet(&args, &keypair_path, &password).await?;
    let config_path = write_config(
        &home,
        &store_path,
        &wallet,
        role,
        &args.peer_store_name,
        &rpc_url,
    )?;
    let opencode_config_path = default_opencode_config_path()?;
    let opencode_api_key = ensure_opencode_gateway_token(&home, &opencode_config_path)?;
    let opencode_config = merge_mayhem_opencode_config(
        &opencode_config_path,
        DEFAULT_GATEWAY_URL,
        None,
        false,
        &opencode_api_key,
    )?;

    let consent = if args.no_consent {
        ConsentReport {
            skipped: true,
            simulated: args.sim,
            rules: None,
            tx: None,
            command_hash: None,
            feature: None,
            result: None,
            state: None,
        }
    } else {
        let rpc = PeerRpcClient::new(&rpc_url)?;
        let rules_doc = read_rules_doc(args.rules_path.as_deref())?;
        let rules = resolve_rules(
            args.rules_ver,
            args.rules_hash.as_deref(),
            &rpc,
            Some(&rules_doc),
        )
        .await?;
        if !args.print_json {
            print_rules_review(&home, &rules_doc, &rules, None, None)?;
        }
        confirm_rules_acceptance(args.yes)?;
        let consent = submit_consent(
            &rpc,
            &keypair_path,
            &password,
            &wallet,
            rules.clone(),
            args.sim,
        )
        .await?;
        if !args.sim {
            persist_rules_acceptance(&home, &rules_doc, &rules)?;
        }
        consent
    };

    let report = json!({
        "home": home,
        "role": role.as_str(),
        "config_path": config_path,
        "wallet": wallet,
        "network": {
            "rpc_url": rpc_url,
            "gateway_url": DEFAULT_GATEWAY_URL,
        },
        "opencode": opencode_config,
        "consent": consent,
    });

    if args.print_json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_human_report(&report)?;
    }

    Ok(())
}

async fn wallet_command(command: WalletCommands) -> Result<()> {
    match command {
        WalletCommands::Show(args) => wallet_show(args).await,
        WalletCommands::Backup(args) | WalletCommands::ExportMnemonic(args) => {
            wallet_backup(args).await
        }
        WalletCommands::Import(args) => wallet_import(args).await,
        WalletCommands::Passwd(args) => wallet_passwd(args).await,
    }
}

async fn wallet_show(args: WalletShowArgs) -> Result<()> {
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    let password = args.wallet.wallet_password.clone().unwrap_or_default();
    let wallet = inspect_wallet(&keypair_path, &password)
        .await
        .with_context(|| format!("reading wallet {}", keypair_path.display()))?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&wallet)?);
    } else {
        print_wallet_show(&wallet);
    }
    Ok(())
}

async fn wallet_backup(args: WalletBackupArgs) -> Result<()> {
    confirm_wallet_backup_reveal(args.yes)?;
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    let password = args.wallet.wallet_password.clone().unwrap_or_default();
    let wallet = backup_wallet(&keypair_path, &password)
        .await
        .with_context(|| format!("backing up wallet {}", keypair_path.display()))?;
    if wallet.mnemonic.as_deref().unwrap_or_default().is_empty() {
        bail!(
            "wallet {} did not contain a restorable mnemonic",
            keypair_path.display()
        );
    }

    if args.json {
        println!("{}", serde_json::to_string_pretty(&wallet)?);
    } else {
        print_wallet_backup(&wallet);
    }
    Ok(())
}

async fn wallet_import(args: WalletImportArgs) -> Result<()> {
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    if keypair_path.exists() && !args.force {
        bail!(
            "{} already exists; pass --force to overwrite it.",
            keypair_path.display()
        );
    }
    if let Some(parent) = keypair_path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    let password = args.wallet.wallet_password.clone().unwrap_or_default();
    let mnemonic = args
        .mnemonic
        .or_else(|| env::var("MAYHEM_WALLET_MNEMONIC").ok())
        .context("wallet import requires --mnemonic-file or MAYHEM_WALLET_MNEMONIC")?;
    let ethereum_private_key = args
        .ethereum_private_key
        .or_else(|| env::var("MAYHEM_ETHEREUM_PRIVATE_KEY").ok());
    let ethereum_mnemonic = args
        .ethereum_mnemonic
        .or_else(|| env::var("MAYHEM_ETHEREUM_MNEMONIC").ok());
    if ethereum_private_key.is_some() && ethereum_mnemonic.is_some() {
        bail!("set only one of the Ethereum private-key or mnemonic secret inputs");
    }
    let wallet = create_wallet(
        &keypair_path,
        &password,
        Some(&mnemonic),
        true,
        ethereum_private_key.as_deref(),
        ethereum_mnemonic.as_deref(),
    )
    .await
    .with_context(|| format!("importing wallet {}", keypair_path.display()))?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&wallet)?);
    } else {
        println!("Wallet imported.");
        print_wallet_show(&wallet);
    }
    Ok(())
}

async fn wallet_passwd(args: WalletPasswdArgs) -> Result<()> {
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    let old_password = args.wallet.wallet_password.clone().unwrap_or_default();
    let new_password = args
        .new_wallet_password
        .clone()
        .or_else(|| env::var("MAYHEM_NEW_WALLET_PASSWORD").ok())
        .context(
            "missing --new-wallet-password-file (or MAYHEM_NEW_WALLET_PASSWORD); use an empty file or empty environment value to remove the password",
        )?;
    let wallet = rotate_wallet_password(&keypair_path, &old_password, &new_password)
        .await
        .with_context(|| format!("re-encrypting wallet {}", keypair_path.display()))?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&wallet)?);
    } else {
        println!("Wallet password updated.");
        print_wallet_show(&wallet);
    }
    Ok(())
}

fn resolve_wallet_keypair_path(args: &WalletLocatorArgs) -> Result<PathBuf> {
    if let Some(keypair) = &args.keypair {
        return Ok(keypair.clone());
    }

    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let store_name = config
        .as_ref()
        .and_then(|config| config.identity.as_ref())
        .and_then(|identity| identity.store_name.as_deref())
        .unwrap_or(&args.peer_store_name);
    Ok(config
        .as_ref()
        .and_then(|config| config.identity.as_ref())
        .and_then(|identity| identity.keypair_path.as_deref())
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            home.join("stores")
                .join(store_name)
                .join("db")
                .join("keypair.json")
        }))
}

fn confirm_wallet_backup_reveal(yes: bool) -> Result<()> {
    if yes {
        return Ok(());
    }
    if !io::stdin().is_terminal() {
        bail!("refusing to reveal a mnemonic without --yes in a non-interactive shell");
    }

    println!("This will print the wallet mnemonic. Anyone who sees it can restore this wallet.");
    print!("Type REVEAL to continue: ");
    io::stdout().flush()?;
    let mut answer = String::new();
    io::stdin().read_line(&mut answer)?;
    if answer.trim() != "REVEAL" {
        bail!("wallet backup cancelled");
    }
    Ok(())
}

fn print_wallet_show(wallet: &WalletInfo) {
    println!("Public key: {}", wallet.public_key);
    if let Some(address) = wallet.address.as_deref() {
        println!("Trac address: {address}");
    }
    if let Some(address) = wallet.ethereum_address.as_deref() {
        println!("Ethereum address: {address}");
    }
    if let Some(derivation_path) = wallet.derivation_path.as_deref() {
        println!("Trac derivation path: {derivation_path}");
    }
    if let Some(derivation_path) = wallet.ethereum_derivation_path.as_deref() {
        println!("Ethereum derivation path: {derivation_path}");
    }
    if let Some(source) = wallet.ethereum_source.as_deref() {
        println!("Ethereum key source: {source}");
    }
    println!("Keypair: {}", wallet.keypair_path);
}

fn print_wallet_backup(wallet: &WalletInfo) {
    print_wallet_show(wallet);
    if let Some(mnemonic) = wallet.mnemonic.as_deref() {
        println!("Mnemonic: {mnemonic}");
        println!(
            "Restore command: mayhem wallet import --keypair {} --mnemonic-file <private-mnemonic-file>",
            wallet.keypair_path
        );
    }
    if let Some(private_key) = wallet.ethereum_private_key.as_deref() {
        println!("Ethereum private key: {private_key}");
        println!(
            "Restore Ethereum key with: mayhem wallet import --keypair {} --mnemonic-file <private-mnemonic-file> --ethereum-private-key-file <private-key-file>",
            wallet.keypair_path
        );
    }
}

fn rules_hash(args: RulesHashArgs) -> Result<()> {
    let rules_doc = read_rules_doc(args.rules_path.as_deref())?;
    if args.print_json {
        println!(
            "{}",
            serde_json::to_string_pretty(&json!({
                "rules_path": rules_doc.path,
                "hash": rules_doc.hash,
                "bytes": rules_doc.bytes,
            }))?
        );
    } else {
        println!("{}", rules_doc.hash);
    }
    Ok(())
}

async fn rules_review(args: RulesReviewArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let rpc_url = args
        .rpc_url
        .clone()
        .or_else(|| {
            config
                .as_ref()
                .and_then(|config| config.network.as_ref())
                .and_then(|network| network.rpc_url.clone())
        })
        .unwrap_or_else(|| DEFAULT_RPC_URL.to_owned());
    let store_name = config
        .as_ref()
        .and_then(|config| config.identity.as_ref())
        .and_then(|identity| identity.store_name.clone())
        .unwrap_or_else(|| args.peer_store_name.clone());
    let keypair_path = if let Some(path) = args.keypair.clone() {
        absolutize(path)?
    } else {
        config
            .as_ref()
            .and_then(|config| config.identity.as_ref())
            .and_then(|identity| identity.keypair_path.as_ref())
            .map(PathBuf::from)
            .unwrap_or_else(|| {
                home.join("stores")
                    .join(&store_name)
                    .join("db")
                    .join("keypair.json")
            })
    };
    let password = args.wallet_password.clone().unwrap_or_default();
    let wallet = inspect_wallet(&keypair_path, &password).await?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let rules_doc = read_rules_doc(args.rules_path.as_deref())?;
    let rules = resolve_rules(None, None, &rpc, Some(&rules_doc)).await?;
    let prior_consent = read_consent_state(&rpc, &wallet.public_key).await?;
    let already_consented = consent_matches(prior_consent.as_ref(), &rules);
    let previous_rules = read_current_accepted_rules(&home)?;

    if !args.print_json {
        print_rules_review(
            &home,
            &rules_doc,
            &rules,
            previous_rules.as_deref(),
            prior_consent.as_ref(),
        )?;
    }

    let consent = if already_consented && !args.sim {
        if previous_rules.as_deref() != Some(rules_doc.text.as_str()) {
            confirm_rules_acceptance(args.yes)?;
            persist_rules_acceptance(&home, &rules_doc, &rules)?;
        }
        ConsentReport {
            skipped: true,
            simulated: false,
            rules: Some(rules.clone()),
            tx: None,
            command_hash: None,
            feature: None,
            result: None,
            state: prior_consent.clone(),
        }
    } else {
        confirm_rules_acceptance(args.yes)?;
        let consent = submit_consent(
            &rpc,
            &keypair_path,
            &password,
            &wallet,
            rules.clone(),
            args.sim,
        )
        .await?;
        if !args.sim {
            persist_rules_acceptance(&home, &rules_doc, &rules)?;
        }
        consent
    };
    let consent_skipped = consent.skipped;
    let consent_simulated = consent.simulated;
    let rules_ver = rules.ver;

    let report = json!({
        "home": home,
        "wallet": {
            "public_key": wallet.public_key,
            "address": wallet.address,
            "keypair_path": wallet.keypair_path,
        },
        "network": {
            "rpc_url": rpc_url,
        },
        "rules": {
            "ver": rules.ver,
            "hash": rules.hash,
            "local_hash": rules_doc.hash,
            "path": rules_doc.path,
            "bytes": rules_doc.bytes,
        },
        "prior_consent": prior_consent,
        "already_consented": already_consented,
        "consent": consent,
    });

    if args.print_json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if consent_skipped {
        println!("Consent: already current for rules v{rules_ver}");
    } else if consent_simulated {
        println!("Consent: simulated for rules v{rules_ver}");
    } else {
        println!("Consent: submitted and observed for rules v{rules_ver}");
    }

    Ok(())
}

fn doctor(args: DoctorArgs) -> Result<()> {
    let fixture = args
        .fixture
        .as_deref()
        .map(|value| {
            FixtureProfile::parse(value).with_context(|| {
                format!(
                    "unknown fixture {value}; expected apple-silicon, linux-nvidia, or cpu-only"
                )
            })
        })
        .transpose()?;

    let mut options = ProbeOptions::default();
    if let Some(path) = args.disk_path {
        options.disk_path = absolutize(path)?;
    }
    options.run_disk_bench = !args.skip_disk_bench;
    options.disk_bench_mib = args.disk_bench_mib;
    options.fixture = fixture;

    let report = probe(options);
    let provider_runtime = if let Some(requested) = args.provider_backend.as_deref() {
        let backend = resolve_doctor_provider_backend(requested, &report)?;
        let verdict = report
            .backend_verdicts
            .iter()
            .find(|verdict| verdict.backend == backend)
            .with_context(|| format!("hwprobe did not report backend {backend}"))?;
        ensure!(
            verdict.status != VerdictStatus::Insufficient,
            "{backend} is not feasible on this host: {}",
            verdict
                .reason
                .as_deref()
                .unwrap_or("hwprobe marked it insufficient")
        );
        let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
        let home = absolutize(home)?;
        fs::create_dir_all(&home).with_context(|| format!("creating {}", home.display()))?;
        let runtime = provider_backend_runtime_preflight_for_backend(
            &home,
            &backend,
            None,
            Some(verdict),
            &report,
            args.gpu_layers,
        )?;
        Some((backend, home, runtime))
    } else {
        None
    };
    if args.json {
        if let Some((backend, home, runtime)) = provider_runtime {
            println!(
                "{}",
                serde_json::to_string_pretty(&json!({
                    "hardware": report,
                    "provider_preflight": {
                        "ok": true,
                        "backend": backend,
                        "home": home,
                        "runtime": runtime,
                    },
                }))?
            );
        } else {
            println!("{}", serde_json::to_string_pretty(&report)?);
        }
    } else {
        print!("{}", human_report(&report));
        if let Some((backend, home, runtime)) = provider_runtime {
            println!("Provider backend preflight: {backend} ready");
            println!("Managed home: {}", home.display());
            if let Some(python) = runtime.python {
                println!("Python: {}", python.display());
            }
            if let Some(cuda_home) = runtime.cuda_home {
                println!("CUDA toolkit: {}", cuda_home.display());
            }
            if let Some(binary) = runtime.external_binary {
                println!("Backend binary: {}", binary.display());
            }
        }
    }
    Ok(())
}

fn resolve_doctor_provider_backend(requested: &str, report: &HardwareReport) -> Result<String> {
    if requested == "auto" {
        return report
            .selected_backend
            .clone()
            .context("hwprobe did not select a provider backend on this host");
    }
    ensure!(
        matches!(
            requested,
            "llama.cpp"
                | "mlx"
                | "vllm"
                | "trt-llm"
                | "stable-diffusion.cpp"
                | "ace-step"
                | "chatterbox"
                | "needle-cpu"
                | "needle-gpu"
                | "sulphur"
                | "transformers-asr"
                | "whisper.cpp"
                | "piper"
        ),
        "unsupported provider backend {requested}"
    );
    Ok(requested.to_owned())
}

