fn catalog_list(args: CatalogListArgs) -> Result<()> {
    let catalog_path = args
        .catalog_path
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let signature_path = args
        .signature_path
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
    let signature_path = absolutize(signature_path)?;
    let keys_dir = args
        .keys_dir
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let keys_dir = absolutize(keys_dir)?;
    let canaries_dir = args
        .canaries_dir
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let canaries_dir = absolutize(canaries_dir)?;

    let verification = catalog::verify(catalog::VerifyOptions {
        catalog_path: catalog_path.clone(),
        signature_path: signature_path.clone(),
        keys_dir,
        canaries_dir: canaries_dir.clone(),
        check_dev_downloads: false,
        check_launch_sources: false,
        hf_token_file: None,
    })?;
    if !verification.ok {
        if args.json {
            println!("{}", serde_json::to_string_pretty(&verification)?);
        } else {
            for error in &verification.errors {
                eprintln!("Catalog error: {error}");
            }
        }
        bail!("catalog verification failed");
    }

    let catalog_doc = catalog::load_document(&catalog_path)?;
    let report = catalog_list_report(
        &catalog_doc,
        catalog_path,
        signature_path,
        verification.catalog_hash,
        verification.key_id,
        args.tier,
        None,
        None,
    );
    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_catalog_list_report(&report);
    }
    Ok(())
}

fn catalog_list_report(
    catalog_doc: &catalog::CatalogDocument,
    catalog_path: PathBuf,
    signature_path: PathBuf,
    catalog_hash: String,
    key_id: String,
    tier: CatalogListTier,
    hardware: Option<&HardwareReport>,
    local_run: Option<CatalogListLocalRunContext<'_>>,
) -> CatalogListReport {
    let local_run = local_run.as_ref();
    let models = catalog_doc
        .models
        .iter()
        .filter(|model| catalog_list_tier_matches(model.tier.as_str(), tier))
        .map(|model| catalog_list_model(model, hardware, local_run))
        .collect::<Vec<_>>();
    let artifact_count = models.iter().map(|model| model.artifacts.len()).sum();
    CatalogListReport {
        ok: true,
        catalog_path,
        signature_path,
        catalog_hash,
        key_id,
        tier_filter: catalog_list_tier_name(tier).to_owned(),
        local_hardware: hardware.map(catalog_list_hardware),
        authority: "admin-signed catalog; live routability still requires active contract ledger enclave, room, admin price, and provider join".to_owned(),
        model_count: models.len(),
        artifact_count,
        models,
    }
}

fn filter_catalog_list_report_by_modality(
    mut report: CatalogListReport,
    modality: Option<&str>,
) -> CatalogListReport {
    let Some(modality) = modality else {
        return report;
    };
    report.models.retain(|model| {
        model
            .adapter
            .modality_set
            .iter()
            .any(|entry| entry == modality)
    });
    report.model_count = report.models.len();
    report.artifact_count = report
        .models
        .iter()
        .map(|model| model.artifacts.len())
        .sum();
    report
}

fn filter_catalog_list_report_by_speciality(
    mut report: CatalogListReport,
    speciality: Option<&(String, String)>,
) -> CatalogListReport {
    let Some((name, level)) = speciality else {
        return report;
    };
    report.models.retain(|model| {
        model.adapter.specialities.iter().any(|descriptor| {
            descriptor.name == *name
                && descriptor
                    .levels
                    .iter()
                    .any(|descriptor_level| descriptor_level.name == *level)
        })
    });
    report.model_count = report.models.len();
    report.artifact_count = report
        .models
        .iter()
        .map(|model| model.artifacts.len())
        .sum();
    report
}

fn catalog_list_tier_matches(model_tier: &str, filter: CatalogListTier) -> bool {
    match filter {
        CatalogListTier::Launch => model_tier == "launch",
        CatalogListTier::Dev => model_tier == "dev",
        CatalogListTier::All => true,
    }
}

fn catalog_list_tier_name(tier: CatalogListTier) -> &'static str {
    match tier {
        CatalogListTier::Launch => "launch",
        CatalogListTier::Dev => "dev",
        CatalogListTier::All => "all",
    }
}

fn catalog_list_hardware(hardware: &HardwareReport) -> CatalogListHardware {
    CatalogListHardware {
        source: hardware.source.kind.clone(),
        fixture: hardware.source.fixture.clone(),
        host: format!("{}/{}", hardware.host.os, hardware.host.arch),
        selected_backend: hardware.selected_backend.clone(),
    }
}

fn catalog_list_model(
    model: &catalog::CatalogModel,
    hardware: Option<&HardwareReport>,
    local_run: Option<&CatalogListLocalRunContext<'_>>,
) -> CatalogListModel {
    let artifacts = model
        .artifacts
        .iter()
        .map(|(artifact_name, artifact)| CatalogListArtifact {
            artifact: artifact_name.clone(),
            engine: artifact.engine.clone(),
            compatibility: hardware.map(|hardware| {
                artifact_hardware_compatibility(model, artifact_name, artifact, hardware)
            }),
            artifact_root: artifact.artifact_root.clone(),
            artifact_root_kind: artifact.artifact_root_kind.clone(),
            weights_bytes: artifact.weights_bytes,
            weights_human: human_bytes(artifact.weights_bytes),
            source_kind: artifact.source.kind.clone(),
            source_repo: artifact.source.repo.clone(),
            source_revision: artifact.source.revision.clone(),
            source_path: artifact.path.clone(),
            source_url: catalog::huggingface_resolve_url(&artifact.source, &artifact.path).ok(),
            source_sha256: artifact.source_sha256.clone(),
            canary_fingerprint: model.canary.fingerprints.get(artifact_name).cloned(),
            notes: artifact.notes.clone(),
        })
        .collect();
    CatalogListModel {
        model_id: model.model_id.clone(),
        model_class: model.model_class.clone(),
        family: model.family.clone(),
        params_b: model.params_b,
        tier: model.tier.clone(),
        min_app_version: model.min_app_version.clone(),
        license: model.provenance.license.clone(),
        price_ref_au: CatalogListPrice {
            denom: model.price_ref_au.denom.clone(),
            rate_map: catalog_model_price_rate_map(model),
        },
        caps: CatalogListCaps {
            tools: model.caps.tools,
            json: model.caps.json,
            ctx_max: model.caps.ctx_max,
            vision: model.caps.vision,
            image: model.caps.image,
            video: model.caps.video,
            audio: model.caps.audio,
            output_modality: model.caps.output_modality.clone(),
            output_modalities: model.caps.output_modalities.clone(),
        },
        requirements: CatalogListRequirements {
            min_ram_gb: model.requirements.min_ram_gb,
            min_vram_gb_full_offload: model.requirements.min_vram_gb_full_offload,
            backends: model.requirements.backends.clone(),
        },
        adapter: model.adapter.clone(),
        modality_assessment: model.modality_assessment.clone(),
        speciality_assessment: model.speciality_assessment.clone(),
        sampling: model.sampling.clone(),
        canary_set: model.canary.set_id.clone(),
        canary_match_min: model.canary.match_min,
        canary_verification_method: model.canary.verification_method.clone(),
        canary_verification_tolerance_bps: model.canary.verification_tolerance_bps,
        artifacts,
        local_runs: local_run
            .map(|context| catalog_model_local_runs(model, context))
            .unwrap_or_default(),
    }
}

fn catalog_model_price_rate_map(model: &catalog::CatalogModel) -> Vec<RateMapEntry> {
    if model.price_ref_au.rate_map.is_empty() {
        text_generation_rate_map(model.price_ref_au.in_per_1k, model.price_ref_au.out_per_1k)
    } else {
        normalize_rate_map(
            model
                .price_ref_au
                .rate_map
                .iter()
                .map(|entry| RateMapEntry {
                    unit: entry.unit.clone(),
                    per_unit_au: entry.per_unit_au,
                    granularity: entry.granularity,
                })
                .collect(),
        )
    }
}

fn catalog_model_local_runs(
    model: &catalog::CatalogModel,
    context: &CatalogListLocalRunContext<'_>,
) -> Vec<CatalogListLocalRun> {
    let mut enclaves = context
        .contract
        .enclaves
        .iter()
        .filter(|enclave| {
            enclave.model_id == model.model_id
                && enclave.status == "active"
                && admin_role_marker_ok(enclave.created_by_role.as_deref())
        })
        .collect::<Vec<_>>();
    enclaves.sort_by(|a, b| a.enclave_id.cmp(&b.enclave_id));

    let args = provider_start_args_for_local_run_display(context.home);
    let at = unix_epoch_seconds().unwrap_or(0);
    enclaves
        .into_iter()
        .filter_map(|enclave| {
            let (artifact_name, artifact) = model.artifacts.iter().find(|(_, artifact)| {
                artifact.engine == enclave.backend
                    && ledger_enclave_matches_catalog_artifact(enclave, artifact)
            })?;
            Some(catalog_enclave_local_run(
                model,
                enclave,
                artifact_name,
                artifact,
                context,
                &args,
                at,
            ))
        })
        .collect()
}

fn catalog_enclave_local_run(
    model: &catalog::CatalogModel,
    enclave: &LedgerEnclave,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    context: &CatalogListLocalRunContext<'_>,
    args: &ProviderStartArgs,
    at: u64,
) -> CatalogListLocalRun {
    let download = catalog_download_estimate(artifact);
    let Some(verdict) = context
        .hardware
        .backend_verdicts
        .iter()
        .find(|verdict| verdict.backend == enclave.backend)
    else {
        return catalog_local_run_cannot_run(
            enclave,
            artifact_name,
            artifact,
            download,
            "cannot_run",
            format!(
                "backend {} is not reported by hwprobe on this host",
                enclave.backend
            ),
        );
    };

    let compatibility =
        artifact_hardware_compatibility_base(model, artifact_name, artifact, context.hardware);
    if !compatibility.compatible {
        let status = if compatibility.reason.contains("needs at least") {
            "too_big"
        } else {
            "cannot_run"
        };
        return catalog_local_run_cannot_run(
            enclave,
            artifact_name,
            artifact,
            download,
            status,
            compatibility.reason,
        );
    }

    let served_modalities = match provider_served_modalities(model, &args.disable_modalities) {
        Ok(modalities) => modalities,
        Err(err) => {
            return catalog_local_run_cannot_run(
                enclave,
                artifact_name,
                artifact,
                download,
                "cannot_run",
                format!("resolving served modalities: {err:#}"),
            );
        }
    };
    match provider_context_feasibility(
        enclave,
        model,
        artifact_name,
        artifact,
        &served_modalities,
        verdict,
        context.hardware,
        args,
        &context.contract.ctx_bracket_schedule,
        at,
    ) {
        Ok(feasibility) => {
            let reduced =
                feasibility.fallback_applied || verdict.status != VerdictStatus::FullOffload;
            let (marker, status, label) = if reduced {
                ("◐", "runs_reduced", "runs reduced")
            } else {
                ("✓", "runs", "runs")
            };
            let mut details = Vec::new();
            details.push(format!(
                "ctx {} of requested/default {}",
                feasibility.served_ctx, feasibility.requested_ctx
            ));
            details.push(format!(
                "needs {} against {} budget",
                human_bytes(feasibility.estimated_required_bytes),
                human_bytes(feasibility.memory_budget.budget_bytes)
            ));
            if let Some(layers) = verdict.n_layers_gpu {
                details.push(format!("{layers} GPU layer(s) estimated"));
            }
            if let Some(message) = feasibility.message.as_deref() {
                details.push(message.to_owned());
            }
            CatalogListLocalRun {
                enclave_id: enclave.enclave_id.clone(),
                artifact: artifact_name.to_owned(),
                engine: enclave.backend.clone(),
                quant: normalize_ledger_quant(&enclave.quant),
                att_tier: enclave.att_tier,
                marker: marker.to_owned(),
                status: status.to_owned(),
                label: label.to_owned(),
                reason: details.join("; "),
                requested_ctx: feasibility.requested_ctx,
                served_ctx: feasibility.served_ctx,
                catalog_ctx_max: feasibility.catalog_ctx_max,
                estimated_tok_s: verdict.est_tok_s,
                estimated_tok_s_source: "hwprobe estimate until measured by live heartbeat/canary"
                    .to_owned(),
                n_layers_gpu: verdict.n_layers_gpu,
                memory: catalog_local_run_memory(&feasibility),
                download,
            }
        }
        Err(err) => {
            let reason = format!("{err:#}");
            let status = if reason.contains("cannot fit") || reason.contains("exceeds usable") {
                "too_big"
            } else {
                "cannot_run"
            };
            catalog_local_run_cannot_run(enclave, artifact_name, artifact, download, status, reason)
        }
    }
}

fn catalog_local_run_cannot_run(
    enclave: &LedgerEnclave,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    download: CatalogListDownloadEstimate,
    status: &str,
    reason: String,
) -> CatalogListLocalRun {
    CatalogListLocalRun {
        enclave_id: enclave.enclave_id.clone(),
        artifact: artifact_name.to_owned(),
        engine: enclave.backend.clone(),
        quant: normalize_ledger_quant(&enclave.quant),
        att_tier: enclave.att_tier,
        marker: "✗".to_owned(),
        status: status.to_owned(),
        label: if status == "too_big" {
            "too big".to_owned()
        } else {
            "cannot run".to_owned()
        },
        reason,
        requested_ctx: 0,
        served_ctx: 0,
        catalog_ctx_max: 0,
        estimated_tok_s: None,
        estimated_tok_s_source: "not estimated because the local load gate failed".to_owned(),
        n_layers_gpu: None,
        memory: CatalogListLocalRunMemory {
            required_bytes: artifact.weights_bytes,
            required_human: human_bytes(artifact.weights_bytes),
            weights_bytes: artifact.weights_bytes,
            weights_human: human_bytes(artifact.weights_bytes),
            kv_bytes: 0,
            kv_human: human_bytes(0),
            overhead_bytes: 0,
            overhead_human: human_bytes(0),
            media_bytes: 0,
            media_human: human_bytes(0),
            budget_bytes: 0,
            budget_human: human_bytes(0),
            reserve_bytes: 0,
            reserve_human: human_bytes(0),
            claimed_bytes: 0,
            claimed_human: human_bytes(0),
            pool: "unavailable".to_owned(),
        },
        download,
    }
}

fn catalog_local_run_memory(feasibility: &ProviderCtxFeasibility) -> CatalogListLocalRunMemory {
    CatalogListLocalRunMemory {
        required_bytes: feasibility.estimated_required_bytes,
        required_human: human_bytes(feasibility.estimated_required_bytes),
        weights_bytes: feasibility.estimated_weights_bytes,
        weights_human: human_bytes(feasibility.estimated_weights_bytes),
        kv_bytes: feasibility.estimated_kv_bytes,
        kv_human: human_bytes(feasibility.estimated_kv_bytes),
        overhead_bytes: feasibility.estimated_overhead_bytes,
        overhead_human: human_bytes(feasibility.estimated_overhead_bytes),
        media_bytes: feasibility.estimated_media_bytes,
        media_human: human_bytes(feasibility.estimated_media_bytes),
        budget_bytes: feasibility.memory_budget.budget_bytes,
        budget_human: human_bytes(feasibility.memory_budget.budget_bytes),
        reserve_bytes: feasibility.memory_budget.reserve_bytes,
        reserve_human: human_bytes(feasibility.memory_budget.reserve_bytes),
        claimed_bytes: feasibility.memory_budget.claimed_bytes,
        claimed_human: human_bytes(feasibility.memory_budget.claimed_bytes),
        pool: feasibility.memory_budget.pool.clone(),
    }
}

fn catalog_download_estimate(artifact: &catalog::CatalogArtifact) -> CatalogListDownloadEstimate {
    let bytes = catalog_artifact_resident_bytes(artifact);
    CatalogListDownloadEstimate {
        bytes,
        human: human_bytes(bytes),
        eta: "measured after the first download chunk".to_owned(),
        eta_source: "provider download progress refines ETA from observed link speed; no pre-download fake precision".to_owned(),
    }
}

fn catalog_artifact_resident_bytes(artifact: &catalog::CatalogArtifact) -> u64 {
    artifact
        .sidecars
        .values()
        .fold(artifact.weights_bytes, |total, sidecar| {
            total.saturating_add(sidecar.weights_bytes)
        })
}

