fn annotate_gateway_models_with_local_runs(
    mut models: Vec<GatewayModel>,
    contract: &ContractCatalog,
    catalog_doc: &catalog::CatalogDocument,
    hardware: &HardwareReport,
    home: &Path,
) -> Vec<GatewayModel> {
    let context = CatalogListLocalRunContext {
        contract,
        hardware,
        home,
    };
    let mut by_enclave = BTreeMap::<String, GatewayLocalRunBadge>::new();
    for model in &catalog_doc.models {
        for local_run in catalog_model_local_runs(model, &context) {
            by_enclave.insert(
                local_run.enclave_id.clone(),
                gateway_local_run_badge(local_run),
            );
        }
    }
    for model in &mut models {
        for candidate in &mut model.mayhem.route_candidates {
            candidate.local_run = by_enclave.get(&candidate.enclave_id).cloned();
        }
    }
    models
}

fn gateway_local_run_badge(local_run: CatalogListLocalRun) -> GatewayLocalRunBadge {
    GatewayLocalRunBadge {
        marker: local_run.marker,
        status: local_run.status,
        label: local_run.label,
        reason: local_run.reason,
        requested_ctx: local_run.requested_ctx,
        served_ctx: local_run.served_ctx,
        estimated_tok_s: local_run
            .estimated_tok_s
            .filter(|value| value.is_finite())
            .map(|value| format!("{value:.1}")),
        memory_required_human: local_run.memory.required_human,
        memory_budget_human: local_run.memory.budget_human,
        download_human: local_run.download.human,
        eta: local_run.download.eta,
    }
}

fn artifact_hardware_compatibility(
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    hardware: &HardwareReport,
) -> CatalogArtifactCompatibility {
    let mut compatibility =
        artifact_hardware_compatibility_base(model, artifact_name, artifact, hardware);
    if !compatibility.compatible {
        compatibility.suggestion =
            compatible_catalog_artifact_suggestion(model, hardware, Some(artifact_name));
    }
    compatibility
}

fn artifact_hardware_compatibility_base(
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    hardware: &HardwareReport,
) -> CatalogArtifactCompatibility {
    if !model
        .requirements
        .backends
        .iter()
        .any(|backend| backend == &artifact.engine)
    {
        return incompatible_artifact(format!(
            "artifact backend {} is not listed in model requirements",
            artifact.engine
        ));
    }
    if let Some(reason) = sulphur_artifact_platform_incompatibility(artifact, hardware) {
        return incompatible_artifact(reason);
    }
    let min_ram_bytes = gib_u64(model.requirements.min_ram_gb);
    if hardware.memory.total_bytes < min_ram_bytes {
        return incompatible_artifact(format!(
            "needs at least {} GiB RAM; local host has {}",
            model.requirements.min_ram_gb,
            human_bytes(hardware.memory.total_bytes)
        ));
    }
    if let Some(requirement) =
        unsatisfied_cpu_flag_requirement(&model.requirements.cpu_flags, hardware)
    {
        return incompatible_artifact(format!(
            "missing required CPU feature expression {requirement}"
        ));
    }
    let Some(verdict) = hardware
        .backend_verdicts
        .iter()
        .find(|verdict| verdict.backend == artifact.engine)
    else {
        return incompatible_artifact(format!(
            "backend {} is not reported by hwprobe on this host",
            artifact.engine
        ));
    };
    if verdict.status == VerdictStatus::Insufficient {
        return incompatible_artifact(format!(
            "{}; {}",
            backend_requirement_hint(&artifact.engine),
            verdict
                .reason
                .as_deref()
                .unwrap_or("hwprobe marked this backend insufficient")
        ));
    }
    if let Some(min_compute_cap) = artifact.min_compute_cap.as_deref() {
        if !hardware_supports_compute_cap(hardware, min_compute_cap) {
            return incompatible_artifact(format!(
                "artifact {artifact_name} requires NVIDIA compute capability >= {min_compute_cap}; local best is {}",
                best_compute_capability_label(hardware)
            ));
        }
    }
    if artifact.engine == "trt-llm" {
        let min_vram_bytes = gib_u64(model.requirements.min_vram_gb_full_offload);
        if min_vram_bytes > 0 && dedicated_vram_known_below(hardware, min_vram_bytes) {
            return incompatible_artifact(format!(
                "needs at least {} GiB dedicated VRAM for {}; local dedicated VRAM is {}",
                model.requirements.min_vram_gb_full_offload,
                artifact.engine,
                dedicated_vram_label(hardware)
            ));
        }
    } else if artifact.engine == "vllm" {
        let min_memory_bytes = gib_u64(model.requirements.min_vram_gb_full_offload);
        if min_memory_bytes > 0 && nvidia_vllm_memory_known_below(hardware, min_memory_bytes) {
            return incompatible_artifact(format!(
                "needs at least {} GiB NVIDIA dedicated or unified memory for {}; local NVIDIA memory is {}",
                model.requirements.min_vram_gb_full_offload,
                artifact.engine,
                nvidia_vllm_memory_label(hardware)
            ));
        }
    }
    compatible_artifact(format!("{:?}", verdict.status))
}

fn compatible_artifact(status: String) -> CatalogArtifactCompatibility {
    CatalogArtifactCompatibility {
        compatible: true,
        status,
        reason: "local hardware can run this artifact".to_owned(),
        suggestion: None,
    }
}

fn incompatible_artifact(reason: String) -> CatalogArtifactCompatibility {
    CatalogArtifactCompatibility {
        compatible: false,
        status: "incompatible".to_owned(),
        reason,
        suggestion: None,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SulphurExecutionFlavor {
    CudaGguf,
    AppleMlx,
}

impl SulphurExecutionFlavor {
    fn runtime_manifest_path(self) -> &'static str {
        match self {
            Self::CudaGguf => SULPHUR_CUDA_RUNTIME_MANIFEST_PATH,
            Self::AppleMlx => SULPHUR_MLX_RUNTIME_MANIFEST_PATH,
        }
    }

    fn primary_extension(self) -> &'static str {
        match self {
            Self::CudaGguf => "gguf",
            Self::AppleMlx => "safetensors",
        }
    }
}

fn sulphur_execution_flavor(artifact: &catalog::CatalogArtifact) -> Result<SulphurExecutionFlavor> {
    ensure!(
        artifact.engine == "sulphur",
        "artifact backend {} is not Sulphur",
        artifact.engine
    );
    let manifest = artifact
        .sidecars
        .get(SULPHUR_RUNTIME_MANIFEST_SIDECAR)
        .context("Sulphur artifact is missing its admin-signed runtime manifest")?;
    match manifest.path.as_str() {
        SULPHUR_CUDA_RUNTIME_MANIFEST_PATH => Ok(SulphurExecutionFlavor::CudaGguf),
        SULPHUR_MLX_RUNTIME_MANIFEST_PATH => Ok(SulphurExecutionFlavor::AppleMlx),
        path => bail!("unrecognized signed Sulphur runtime manifest path {path}"),
    }
}

fn sulphur_artifact_platform_incompatibility(
    artifact: &catalog::CatalogArtifact,
    hardware: &HardwareReport,
) -> Option<String> {
    if artifact.engine != "sulphur" {
        return None;
    }
    let flavor = match sulphur_execution_flavor(artifact) {
        Ok(flavor) => flavor,
        Err(err) => {
            return Some(format!(
                "Sulphur artifact has no recognized signed execution flavor: {err:#}"
            ));
        }
    };
    let host = format!("{}/{}", hardware.host.os, hardware.host.arch);
    match flavor {
        SulphurExecutionFlavor::AppleMlx
            if !(hardware.host.os == "macos"
                && matches!(hardware.host.arch.as_str(), "aarch64" | "arm64")) =>
        {
            Some(format!(
                "signed Sulphur artifact selects the Apple MLX execution flavor, which is unavailable on {host}"
            ))
        }
        SulphurExecutionFlavor::CudaGguf
            if !matches!(
                (hardware.host.os.as_str(), hardware.host.arch.as_str()),
                ("linux", "x86_64")
                    | ("linux", "aarch64")
                    | ("linux", "arm64")
                    | ("windows", "x86_64")
            ) =>
        {
            Some(format!(
                "signed Sulphur artifact selects the CUDA/GGUF execution flavor, which is unavailable on {host}"
            ))
        }
        _ => None,
    }
}

fn compatible_catalog_artifact_suggestion(
    model: &catalog::CatalogModel,
    hardware: &HardwareReport,
    exclude_artifact: Option<&str>,
) -> Option<String> {
    model
        .artifacts
        .iter()
        .filter(|(name, _)| exclude_artifact != Some(name.as_str()))
        .filter_map(|(name, artifact)| {
            let compatibility =
                artifact_hardware_compatibility_base(model, name, artifact, hardware);
            compatibility
                .compatible
                .then_some((name, artifact, backend_rank(&artifact.engine)))
        })
        .max_by_key(|(_, _, rank)| *rank)
        .map(|(name, artifact, _)| {
            format!(
                "use catalog artifact {name} via {} for model {}",
                artifact.engine, model.model_id
            )
        })
}

fn backend_requirement_hint(backend: &str) -> &'static str {
    match backend {
        "mlx" => "MLX requires Apple Silicon with a Metal unified-memory GPU",
        "trt-llm" => {
            "TensorRT-LLM requires a compatible NVIDIA GPU; NVFP4 artifacts require Blackwell-class compute capability"
        }
        "vllm" => "vLLM launch artifacts require a compatible NVIDIA GPU",
        "llama.cpp" => "llama.cpp requires enough RAM and a compatible CPU/GPU runtime",
        "stable-diffusion.cpp" => {
            "stable-diffusion.cpp requires enough local RAM and preferably a local accelerator"
        }
        "ace-step" => {
            "ACE-Step requires its pinned local Python runtime and enough RAM or accelerator memory for the signed artifact"
        }
        "chatterbox" => {
            "Chatterbox requires its pinned offline Python runtime and enough RAM or CUDA/Metal memory for the signed five-file artifact"
        }
        "needle-cpu" => {
            "Needle CPU requires its pinned offline Python runtime and the exact signed tools-only model inventory"
        }
        "needle-gpu" => {
            "Needle GPU requires a supported NVIDIA CUDA host and its matching pinned offline runtime"
        }
        "sulphur" => {
            "Sulphur requires its pinned local joint audio-video runtime and a calibrated CUDA or Apple Silicon artifact"
        }
        "transformers-asr" => {
            "Transformers ASR requires at least 8 GiB RAM and supports CUDA, Metal/MPS, or CPU execution"
        }
        "whisper.cpp" => "whisper.cpp requires enough local RAM and CPU SIMD support",
        "piper" => "Piper requires enough local RAM for the voice artifact",
        _ => "backend is not compatible with this host",
    }
}

fn unsatisfied_cpu_flag_requirement(
    requirements: &[String],
    hardware: &HardwareReport,
) -> Option<String> {
    requirements
        .iter()
        .find(|requirement| !cpu_flag_expression_satisfied(requirement, hardware))
        .cloned()
}

fn cpu_flag_expression_satisfied(requirement: &str, hardware: &HardwareReport) -> bool {
    requirement
        .split('|')
        .map(str::trim)
        .filter(|flag| !flag.is_empty())
        .any(|flag| match flag.to_ascii_lowercase().as_str() {
            "avx2" => hardware.cpu.flags.avx2,
            "avx512" | "avx512f" => hardware.cpu.flags.avx512,
            "neon" => hardware.cpu.flags.neon,
            _ => false,
        })
}

fn hardware_supports_compute_cap(hardware: &HardwareReport, min_compute_cap: &str) -> bool {
    let Some(minimum) = parse_compute_capability_pair(min_compute_cap) else {
        return false;
    };
    hardware
        .gpus
        .iter()
        .filter_map(|gpu| gpu.compute_capability.as_deref())
        .filter_map(parse_compute_capability_pair)
        .any(|capability| capability >= minimum)
}

fn best_compute_capability_label(hardware: &HardwareReport) -> String {
    hardware
        .gpus
        .iter()
        .filter_map(|gpu| gpu.compute_capability.as_deref())
        .filter_map(parse_compute_capability_pair)
        .max()
        .map(|(major, minor)| format!("{major}.{minor}"))
        .unwrap_or_else(|| "none".to_owned())
}

fn parse_compute_capability_pair(value: &str) -> Option<(u32, u32)> {
    let (major, minor) = value.trim().split_once('.')?;
    Some((major.parse().ok()?, minor.parse().ok()?))
}

fn known_total_dedicated_vram_bytes(hardware: &HardwareReport) -> Option<u64> {
    let mut saw_dedicated_gpu = false;
    let mut total = 0u64;
    for gpu in hardware.gpus.iter().filter(|gpu| !gpu.unified_memory) {
        saw_dedicated_gpu = true;
        let memory = gpu.memory_bytes?;
        total = total.saturating_add(memory);
    }
    saw_dedicated_gpu.then_some(total).or(Some(0))
}

fn dedicated_vram_label(hardware: &HardwareReport) -> String {
    known_total_dedicated_vram_bytes(hardware)
        .map(human_bytes)
        .unwrap_or_else(|| "unknown".to_owned())
}

fn dedicated_vram_known_below(hardware: &HardwareReport, min_vram_bytes: u64) -> bool {
    known_total_dedicated_vram_bytes(hardware).is_some_and(|total| total < min_vram_bytes)
}

fn known_total_nvidia_vllm_memory_bytes(hardware: &HardwareReport) -> Option<u64> {
    let mut saw_nvidia = false;
    let mut total = 0u64;
    for gpu in hardware
        .gpus
        .iter()
        .filter(|gpu| gpu.vendor == GpuVendor::Nvidia)
    {
        saw_nvidia = true;
        let memory = match gpu.memory_bytes {
            Some(memory) => memory,
            None if nvidia_gpu_uses_host_unified_memory(hardware, gpu) => hardware
                .memory
                .available_bytes
                .unwrap_or(hardware.memory.total_bytes),
            None => return None,
        };
        total = total.saturating_add(memory);
    }
    saw_nvidia.then_some(total)
}

fn nvidia_gpu_uses_host_unified_memory(hardware: &HardwareReport, gpu: &GpuInfo) -> bool {
    gpu.unified_memory
        || (gpu.vendor == GpuVendor::Nvidia
            && gpu.memory_bytes.is_none()
            && hardware.host.os == "linux"
            && matches!(hardware.host.arch.as_str(), "aarch64" | "arm64"))
}

fn nvidia_vllm_memory_label(hardware: &HardwareReport) -> String {
    known_total_nvidia_vllm_memory_bytes(hardware)
        .map(human_bytes)
        .unwrap_or_else(|| "unknown".to_owned())
}

fn nvidia_vllm_memory_known_below(hardware: &HardwareReport, min_memory_bytes: u64) -> bool {
    known_total_nvidia_vllm_memory_bytes(hardware).is_some_and(|total| total < min_memory_bytes)
}

fn gib_u64(gib: u64) -> u64 {
    gib.saturating_mul(1024 * 1024 * 1024)
}

fn print_catalog_list_report(report: &CatalogListReport) {
    println!(
        "Signed catalog: {} (hash {}, key {})",
        report.catalog_path.display(),
        report.catalog_hash,
        report.key_id
    );
    println!(
        "Scope: {} models, {} artifacts, tier filter {}",
        report.model_count, report.artifact_count, report.tier_filter
    );
    println!(
            "Authority: catalog approval is admin-signed; live routing comes from contract ledger state."
        );
    if let Some(hardware) = &report.local_hardware {
        println!(
            "Local hardware: {} selected_backend={}",
            hardware.host,
            hardware.selected_backend.as_deref().unwrap_or("none")
        );
    }

    for model in &report.models {
        println!();
        let params = if model.params_b < 0.1 {
            format!("{:.3}B", model.params_b)
        } else {
            format!("{:.1}B", model.params_b)
        };
        println!(
            "{} [{}] {} {}",
            model.model_id, model.tier, params, model.family
        );
        println!(
            "  price ref: {} {}",
            model.price_ref_au.denom,
            format_rate_map(&model.price_ref_au.rate_map)
        );
        if let Some(min_app_version) = model.min_app_version.as_deref() {
            println!("  min app version: Mayhem >= {min_app_version}");
        }
        let output = if model.caps.output_modalities.is_empty() {
            model
                .caps
                .output_modality
                .as_deref()
                .unwrap_or("unspecified")
                .to_owned()
        } else {
            model.caps.output_modalities.join(",")
        };
        println!(
            "  caps: ctx_max={} output={} tools={} json={} vision={} image={} video={} audio={}",
            model.caps.ctx_max,
            output,
            model.caps.tools,
            model.caps.json,
            model.caps.vision,
            model.caps.image,
            model.caps.video,
            model.caps.audio
        );
        println!(
            "  requirements: ram>={}GB vram_full_offload>={}GB backends={}",
            model.requirements.min_ram_gb,
            model.requirements.min_vram_gb_full_offload,
            model.requirements.backends.join(",")
        );
        println!(
            "  adapter: endpoint_families={} template={} tool_call={} reasoning={} modalities={}",
            model
                .adapter
                .endpoint_families
                .iter()
                .map(|contract| contract.family.as_str())
                .collect::<Vec<_>>()
                .join(","),
            model.adapter.chat_template_id,
            model.adapter.tool_call_strategy,
            model.adapter.reasoning_passthrough,
            model.adapter.modality_set.join(",")
        );
        if !model.adapter.specialities.is_empty() {
            println!(
                "  specialities: {}",
                model
                    .adapter
                    .specialities
                    .iter()
                    .map(|descriptor| format!(
                        "{}(default={}; levels={})",
                        descriptor.name,
                        descriptor.default_level,
                        descriptor
                            .levels
                            .iter()
                            .map(|level| level.name.as_str())
                            .collect::<Vec<_>>()
                            .join(",")
                    ))
                    .collect::<Vec<_>>()
                    .join("; ")
            );
        }
        println!(
            "  canary: {} method={} match_min={} tolerance_bps={}",
            model.canary_set,
            model.canary_verification_method,
            model.canary_match_min,
            model
                .canary_verification_tolerance_bps
                .map(|value| value.to_string())
                .unwrap_or_else(|| "none".to_owned())
        );
        for artifact in &model.artifacts {
            let canary = match (
                model.canary_verification_method.as_str(),
                artifact.canary_fingerprint.as_deref(),
            ) {
                ("token_fingerprint", Some(fingerprint)) => short_hash(fingerprint),
                ("token_fingerprint", None) => "missing",
                _ => "n/a",
            };
            let compatibility = artifact
                .compatibility
                .as_ref()
                .map(|compat| {
                    let marker = if compat.compatible { "yes" } else { "no" };
                    format!("{marker} {}", compat.reason)
                })
                .unwrap_or_else(|| "n/a".to_owned());
            println!(
                "  - {} ({}) {} root={} canary={} compat={}",
                artifact.artifact,
                artifact.engine,
                artifact.weights_human,
                short_hash(&artifact.artifact_root),
                canary,
                compatibility
            );
            if let Some(suggestion) = artifact
                .compatibility
                .as_ref()
                .and_then(|compat| compat.suggestion.as_deref())
            {
                println!("    suggestion: {suggestion}");
            }
            println!(
                "    source: {}@{} {}",
                artifact.source_repo, artifact.source_revision, artifact.source_path
            );
        }
        for local_run in &model.local_runs {
            let tok_s = local_run
                .estimated_tok_s
                .map(|value| format!("{value:.1} tok/s est"))
                .unwrap_or_else(|| "tok/s n/a".to_owned());
            let layers = local_run
                .n_layers_gpu
                .map(|layers| format!(" layers={layers}"))
                .unwrap_or_default();
            println!(
                "    {} {}: enclave={} artifact={} backend={} quant={} T{} ctx={}/{} {}{} mem={} budget={} download={} eta={}",
                local_run.marker,
                local_run.label,
                short_hash(&local_run.enclave_id),
                local_run.artifact,
                local_run.engine,
                local_run.quant,
                local_run.att_tier,
                local_run.served_ctx,
                local_run.requested_ctx,
                tok_s,
                layers,
                local_run.memory.required_human,
                local_run.memory.budget_human,
                local_run.download.human,
                local_run.download.eta
            );
            println!("      {}", local_run.reason);
        }
    }
}

fn format_rate_map(rate_map: &[RateMapEntry]) -> String {
    normalize_rate_map(rate_map.to_vec())
        .into_iter()
        .map(|entry| {
            format!(
                "{}=${}/{}",
                entry.unit,
                au_to_usd_amount(entry.per_unit_au),
                entry.granularity
            )
        })
        .collect::<Vec<_>>()
        .join(",")
}

fn short_hash(value: &str) -> &str {
    value.get(..12).unwrap_or(value)
}

fn human_bytes(bytes: u64) -> String {
    const GIB: f64 = 1024.0 * 1024.0 * 1024.0;
    const MIB: f64 = 1024.0 * 1024.0;
    if bytes >= 1024 * 1024 * 1024 {
        format!("{:.2}GiB", bytes as f64 / GIB)
    } else if bytes >= 1024 * 1024 {
        format!("{:.2}MiB", bytes as f64 / MIB)
    } else {
        format!("{bytes}B")
    }
}

fn catalog_verify(args: CatalogVerifyArgs) -> Result<()> {
    let catalog_path = args
        .catalog_path
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let signature_path = args
        .signature_path
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
    let signature_path = absolutize(signature_path)?;
    let keys_dir = args
        .keys_dir
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let keys_dir = absolutize(keys_dir)?;
    let canaries_dir = args
        .canaries_dir
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let canaries_dir = absolutize(canaries_dir)?;
    let hf_token_file = args.hf_token_file.map(absolutize).transpose()?;

    let report = catalog::verify(catalog::VerifyOptions {
        catalog_path,
        signature_path,
        keys_dir,
        canaries_dir: canaries_dir.clone(),
        check_dev_downloads: args.check_dev_downloads,
        check_launch_sources: args.check_launch_sources,
        hf_token_file,
    })?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
        if !report.ok {
            bail!("catalog verification failed");
        }
    } else if report.ok {
        println!(
            "Catalog OK: {} models ({} dev, {} launch), {} artifacts, hash {}",
            report.model_count,
            report.dev_model_count,
            report.launch_model_count,
            report.artifact_count,
            report.catalog_hash
        );
        if !report.download_checks.is_empty() {
            println!("Dev downloads checked: {}", report.download_checks.len());
        }
        if !report.source_checks.is_empty() {
            println!("Launch sources checked: {}", report.source_checks.len());
        }
    } else {
        for error in &report.errors {
            eprintln!("Catalog error: {error}");
        }
        for error in &report.attestation_policy_errors {
            eprintln!("Catalog attestation authority error: {error}");
        }
        for check in report.source_checks.iter().filter(|check| !check.ok) {
            let metadata_errors = if check.metadata_errors.is_empty() {
                String::new()
            } else {
                format!(" metadata={}", check.metadata_errors.join(" | "))
            };
            eprintln!(
                "Catalog source error: {} / {} {}@{} {} status={}{}",
                check.model_id,
                check.artifact,
                check.repo,
                check.revision,
                check.path,
                check
                    .status
                    .map(|status| status.to_string())
                    .unwrap_or_else(|| check.error.as_deref().unwrap_or("error").to_owned()),
                metadata_errors
            );
        }
        bail!("catalog verification failed");
    }
    Ok(())
}

