struct CatalogArtifactPlanInput<'a> {
    catalog_doc: &'a catalog::CatalogDocument,
    catalog_path: PathBuf,
    artifact_base: PathBuf,
    report_dir: PathBuf,
    catalog_output: PathBuf,
    catalog_sign: Option<CatalogCanaryPlanSignOptions>,
    hf_token_file: Option<PathBuf>,
    launch_only: bool,
}

fn catalog_artifact_plan_report(input: CatalogArtifactPlanInput<'_>) -> CatalogArtifactPlanReport {
    let CatalogArtifactPlanInput {
        catalog_doc,
        catalog_path,
        artifact_base,
        report_dir,
        catalog_output,
        catalog_sign,
        hf_token_file,
        launch_only,
    } = input;
    let mut entries = Vec::new();
    let mut errors = Vec::new();

    for model in &catalog_doc.models {
        if launch_only && model.tier != "launch" {
            continue;
        }
        for (artifact_name, artifact) in &model.artifacts {
            let mut entry_errors = Vec::new();
            let artifact_rel_path = PathBuf::from(&artifact.path);
            if artifact_rel_path.is_absolute() {
                entry_errors.push(format!(
                    "catalog artifact path {} must be relative to --artifact-base",
                    artifact.path
                ));
            }
            if artifact.source.kind != "huggingface" {
                entry_errors.push(format!(
                    "artifact source kind {} is not supported by launch-source verification",
                    artifact.source.kind
                ));
            }
            let artifact_path = catalog_canary_plan_artifact_path(&artifact_base, artifact);
            let report_path = report_dir
                .join(safe_path_component(&model.model_id))
                .join(format!(
                    "{}.artifact-metadata.json",
                    safe_path_component(artifact_name)
                ));
            let command = catalog_artifact_metadata_plan_command(
                &catalog_path,
                model,
                artifact_name,
                &artifact_path,
                &report_path,
                None,
            );
            let ok = entry_errors.is_empty();
            let entry = CatalogArtifactPlanEntry {
                model_id: model.model_id.clone(),
                tier: model.tier.clone(),
                artifact: artifact_name.clone(),
                engine: artifact.engine.clone(),
                source_kind: artifact.source.kind.clone(),
                source_repo: artifact.source.repo.clone(),
                source_revision: artifact.source.revision.clone(),
                source_path: artifact.path.clone(),
                artifact_path,
                report_path,
                command,
                ok,
                errors: entry_errors,
            };
            if !entry.ok {
                errors.extend(
                    entry
                        .errors
                        .iter()
                        .map(|error| format!("{} {}: {error}", entry.model_id, entry.artifact)),
                );
            }
            entries.push(entry);
        }
    }

    if entries.is_empty() {
        errors.push(if launch_only {
            "catalog has no launch model artifacts to plan".to_owned()
        } else {
            "catalog has no model artifacts to plan".to_owned()
        });
    }

    let report_paths = entries
        .iter()
        .map(|entry| entry.report_path.clone())
        .collect::<Vec<_>>();
    let apply_command = catalog_artifact_plan_apply_command(
        &catalog_path,
        &catalog_output,
        launch_only,
        &report_paths,
    );
    let signature_command = catalog_sign
        .as_ref()
        .map(|sign| catalog_canary_plan_sign_command(&catalog_output, sign));
    let verify_command = catalog_sign.as_ref().map(|sign| {
        catalog_artifact_plan_verify_command(&catalog_output, sign, hf_token_file.as_deref())
    });
    let model_count = entries
        .iter()
        .map(|entry| entry.model_id.as_str())
        .collect::<BTreeSet<_>>()
        .len();
    CatalogArtifactPlanReport {
        catalog_path,
        artifact_base,
        report_dir,
        catalog_output,
        launch_only,
        model_count,
        artifact_count: entries.len(),
        ok: errors.is_empty(),
        metadata_commands: entries,
        apply_command,
        signature_command,
        verify_command,
        errors,
    }
}

struct CatalogArtifactStagePlanInput<'a> {
    catalog_doc: &'a catalog::CatalogDocument,
    catalog_path: PathBuf,
    artifact_base: PathBuf,
    source_cache_dir: PathBuf,
    hf_token_file: Option<PathBuf>,
    launch_only: bool,
    model_filter: Option<String>,
    artifact_filter: Option<String>,
}

fn catalog_artifact_stage_plan_report(
    input: CatalogArtifactStagePlanInput<'_>,
) -> CatalogArtifactStagePlanReport {
    let CatalogArtifactStagePlanInput {
        catalog_doc,
        catalog_path,
        artifact_base,
        source_cache_dir,
        hf_token_file,
        launch_only,
        model_filter,
        artifact_filter,
    } = input;
    let mut source_commands = Vec::new();
    let mut stage_commands = Vec::new();
    let mut errors = Vec::new();
    let mut planned_sources = BTreeSet::new();
    let artifact_base_available_bytes = available_bytes_for_path(&artifact_base).ok().flatten();
    let mut catalog_expected_bytes = 0u64;
    let mut current_artifact_bytes_total = 0u64;
    let mut missing_artifact_bytes = 0u64;

    for model in &catalog_doc.models {
        if launch_only && model.tier != "launch" {
            continue;
        }
        if model_filter
            .as_deref()
            .is_some_and(|selected| selected != model.model_id)
        {
            continue;
        }
        for (artifact_name, artifact) in &model.artifacts {
            if artifact_filter
                .as_deref()
                .is_some_and(|selected| selected != artifact_name)
            {
                continue;
            }
            let mut entry_errors = Vec::new();
            let upstream_source = catalog_artifact_primary_upstream_source(model, artifact);
            let source_dir = catalog_artifact_stage_source_dir(&source_cache_dir, upstream_source);
            for source in catalog_artifact_stage_sources(model, artifact) {
                let source_key = (
                    source.kind.clone(),
                    source.repo.clone(),
                    source.revision.clone(),
                );
                if !planned_sources.insert(source_key) {
                    continue;
                }
                let source_dir = catalog_artifact_stage_source_dir(&source_cache_dir, source);
                let mut source_errors = Vec::new();
                if source.kind != "huggingface" {
                    source_errors.push(format!(
                        "upstream source kind {} is not supported by artifact staging",
                        source.kind
                    ));
                }
                let allow_patterns = catalog_artifact_stage_source_patterns(
                    catalog_doc,
                    source,
                    launch_only,
                    model_filter.as_deref(),
                    artifact_filter.as_deref(),
                );
                let command = catalog_artifact_stage_source_download_command(
                    source,
                    &source_dir,
                    hf_token_file.as_deref(),
                    allow_patterns.as_deref(),
                );
                let ok = source_errors.is_empty();
                let entry = CatalogArtifactStageSourceEntry {
                    model_id: model.model_id.clone(),
                    tier: model.tier.clone(),
                    source_kind: source.kind.clone(),
                    source_repo: source.repo.clone(),
                    source_revision: source.revision.clone(),
                    source_dir,
                    command,
                    ok,
                    errors: source_errors,
                };
                if !entry.ok {
                    errors.extend(
                        entry
                            .errors
                            .iter()
                            .map(|error| format!("{} source: {error}", entry.model_id)),
                    );
                }
                source_commands.push(entry);
            }
            catalog_expected_bytes = catalog_expected_bytes.saturating_add(artifact.weights_bytes);
            let artifact_rel_path = PathBuf::from(&artifact.path);
            if artifact_rel_path.is_absolute() {
                entry_errors.push(format!(
                    "catalog artifact path {} must be relative to --artifact-base",
                    artifact.path
                ));
            }
            if artifact.source.kind != "huggingface" {
                entry_errors.push(format!(
                    "artifact source kind {} cannot be published with Hugging Face upload",
                    artifact.source.kind
                ));
            }
            let artifact_path = catalog_canary_plan_artifact_path(&artifact_base, artifact);
            let (current_artifact_exists, current_artifact_is_file, current_artifact_bytes) =
                match fs::metadata(&artifact_path) {
                    Ok(metadata) => {
                        let is_file = metadata.is_file();
                        if !is_file {
                            entry_errors.push(format!(
                                "local artifact path {} exists but is not a file",
                                artifact_path.display()
                            ));
                        }
                        (true, is_file, is_file.then_some(metadata.len()))
                    }
                    Err(err) if err.kind() == std::io::ErrorKind::NotFound => (false, false, None),
                    Err(err) => {
                        entry_errors.push(format!(
                            "could not stat local artifact path {}: {err}",
                            artifact_path.display()
                        ));
                        (false, false, None)
                    }
                };
            if let Some(bytes) = current_artifact_bytes {
                current_artifact_bytes_total = current_artifact_bytes_total.saturating_add(bytes);
            } else {
                missing_artifact_bytes =
                    missing_artifact_bytes.saturating_add(artifact.weights_bytes);
            }
            let stage_command = match catalog_artifact_stage_command(
                model,
                artifact_name,
                artifact,
                &source_dir,
                &source_cache_dir,
                upstream_source,
                &artifact_base,
                &artifact_path,
            ) {
                Ok(command) => command,
                Err(err) => {
                    entry_errors.push(err.to_string());
                    catalog_canary_plan_command(vec![
                        "false".to_owned(),
                        format!(
                            "unsupported artifact staging command for {} {}",
                            model.model_id, artifact_name
                        ),
                    ])
                }
            };
            let follow_up_publish_plan = catalog_artifact_stage_follow_up_command(
                &catalog_path,
                &artifact_base,
                hf_token_file.as_deref(),
                model_filter.as_deref(),
                artifact_filter.as_deref(),
            );
            let ok = entry_errors.is_empty();
            let entry = CatalogArtifactStagePlanEntry {
                model_id: model.model_id.clone(),
                tier: model.tier.clone(),
                artifact: artifact_name.clone(),
                engine: artifact.engine.clone(),
                source_kind: artifact.source.kind.clone(),
                source_repo: artifact.source.repo.clone(),
                source_revision: artifact.source.revision.clone(),
                source_path: artifact.path.clone(),
                upstream_source_kind: upstream_source.kind.clone(),
                upstream_source_repo: upstream_source.repo.clone(),
                upstream_source_revision: upstream_source.revision.clone(),
                upstream_source_dir: source_dir.clone(),
                artifact_path,
                catalog_weights_bytes: artifact.weights_bytes,
                current_artifact_exists,
                current_artifact_is_file,
                current_artifact_bytes,
                stage_command,
                follow_up_publish_plan,
                ok,
                errors: entry_errors,
            };
            if !entry.ok {
                errors.extend(
                    entry
                        .errors
                        .iter()
                        .map(|error| format!("{} {}: {error}", entry.model_id, entry.artifact)),
                );
            }
            stage_commands.push(entry);
        }
    }

    if stage_commands.is_empty() {
        errors.push(
            match (model_filter.as_deref(), artifact_filter.as_deref()) {
                (Some(model), Some(artifact)) => format!(
                    "catalog selection matched no {} artifact {artifact} for model {model}",
                    if launch_only { "launch" } else { "model" }
                ),
                (Some(model), None) => format!(
                    "catalog selection matched no {} artifacts for model {model}",
                    if launch_only { "launch" } else { "model" }
                ),
                (None, _) if launch_only => {
                    "catalog has no launch model artifacts to stage".to_owned()
                }
                (None, _) => "catalog has no model artifacts to stage".to_owned(),
            },
        );
    }

    let artifact_base_space_ok = artifact_base_available_bytes
        .map(|available| available >= missing_artifact_bytes || missing_artifact_bytes == 0);
    if artifact_base_space_ok == Some(false) {
        errors.push(format!(
            "artifact base filesystem has {} byte(s) available but {} byte(s) are still missing by catalog estimate",
            artifact_base_available_bytes.unwrap_or(0),
            missing_artifact_bytes
        ));
    }

    let model_count = stage_commands
        .iter()
        .map(|entry| entry.model_id.as_str())
        .collect::<BTreeSet<_>>()
        .len();
    let needs_llama_cpp = stage_commands.iter().any(|entry| {
        entry.engine == "llama.cpp"
            && catalog_doc
                .models
                .iter()
                .find(|model| model.model_id == entry.model_id)
                .and_then(|model| model.artifacts.get(&entry.artifact))
                .is_some_and(|artifact| artifact.upstream_source.is_none())
    });
    let preflight_command =
        catalog_artifact_stage_preflight_command(hf_token_file.as_deref(), needs_llama_cpp);
    CatalogArtifactStagePlanReport {
        catalog_path,
        artifact_base,
        source_cache_dir,
        launch_only,
        model_filter,
        artifact_filter,
        hf_token_file,
        model_count,
        artifact_count: stage_commands.len(),
        source_count: source_commands.len(),
        catalog_expected_bytes,
        current_artifact_bytes: current_artifact_bytes_total,
        missing_artifact_bytes,
        artifact_base_available_bytes,
        artifact_base_space_ok,
        ok: errors.is_empty(),
        preflight_command,
        source_commands,
        stage_commands,
        errors,
    }
}

struct CatalogArtifactPublishPlanInput<'a> {
    catalog_doc: &'a catalog::CatalogDocument,
    catalog_path: PathBuf,
    artifact_base: PathBuf,
    report_dir: PathBuf,
    catalog_output: PathBuf,
    catalog_sign: Option<CatalogCanaryPlanSignOptions>,
    hf_token_file: Option<PathBuf>,
    launch_only: bool,
    model_filter: Option<String>,
    artifact_filter: Option<String>,
}

fn catalog_artifact_publish_plan_report(
    input: CatalogArtifactPublishPlanInput<'_>,
) -> CatalogArtifactPublishPlanReport {
    let CatalogArtifactPublishPlanInput {
        catalog_doc,
        catalog_path,
        artifact_base,
        report_dir,
        catalog_output,
        catalog_sign,
        hf_token_file,
        launch_only,
        model_filter,
        artifact_filter,
    } = input;
    let mut entries = Vec::new();
    let mut errors = Vec::new();
    let artifact_base_available_bytes = available_bytes_for_path(&artifact_base).ok().flatten();
    let mut catalog_expected_bytes = 0u64;
    let mut current_artifact_bytes_total = 0u64;
    let mut missing_artifact_bytes = 0u64;

    for model in &catalog_doc.models {
        if launch_only && model.tier != "launch" {
            continue;
        }
        if model_filter
            .as_deref()
            .is_some_and(|selected| selected != model.model_id)
        {
            continue;
        }
        for (artifact_name, artifact) in &model.artifacts {
            if artifact_filter
                .as_deref()
                .is_some_and(|selected| selected != artifact_name)
            {
                continue;
            }
            let mut entry_errors = Vec::new();
            catalog_expected_bytes = catalog_expected_bytes.saturating_add(artifact.weights_bytes);
            let artifact_rel_path = PathBuf::from(&artifact.path);
            if artifact_rel_path.is_absolute() {
                entry_errors.push(format!(
                    "catalog artifact path {} must be relative to --artifact-base",
                    artifact.path
                ));
            }
            if artifact.source.kind != "huggingface" {
                entry_errors.push(format!(
                    "artifact source kind {} cannot be published with Hugging Face upload",
                    artifact.source.kind
                ));
            }
            let current_artifact_path = catalog_canary_plan_artifact_path(&artifact_base, artifact);
            let (current_artifact_exists, current_artifact_is_file, current_artifact_bytes) =
                match fs::metadata(&current_artifact_path) {
                    Ok(metadata) => {
                        let is_file = metadata.is_file();
                        if !is_file {
                            entry_errors.push(format!(
                                "local artifact path {} exists but is not a file",
                                current_artifact_path.display()
                            ));
                        }
                        (true, is_file, is_file.then_some(metadata.len()))
                    }
                    Err(err) if err.kind() == std::io::ErrorKind::NotFound => {
                        entry_errors.push(format!(
                            "local artifact file is missing at {}",
                            current_artifact_path.display()
                        ));
                        (false, false, None)
                    }
                    Err(err) => {
                        entry_errors.push(format!(
                            "could not stat local artifact path {}: {err}",
                            current_artifact_path.display()
                        ));
                        (false, false, None)
                    }
                };
            if let Some(bytes) = current_artifact_bytes {
                current_artifact_bytes_total = current_artifact_bytes_total.saturating_add(bytes);
            } else {
                missing_artifact_bytes =
                    missing_artifact_bytes.saturating_add(artifact.weights_bytes);
            }
            let published_artifact_path_template =
                catalog_artifact_published_template_path(&artifact_base, artifact);
            let report_path = report_dir
                .join(safe_path_component(&model.model_id))
                .join(format!(
                    "{}.artifact-metadata.json",
                    safe_path_component(artifact_name)
                ));
            let upload_command = match catalog_artifact_upload_command(
                model,
                artifact_name,
                artifact,
                &current_artifact_path,
                hf_token_file.as_deref(),
            ) {
                Ok(command) => command,
                Err(err) => {
                    entry_errors.push(err.to_string());
                    catalog_canary_plan_command(vec![
                        "false".to_owned(),
                        format!(
                            "invalid artifact upload command for {} {}",
                            model.model_id, artifact_name
                        ),
                    ])
                }
            };
            let revision_command =
                catalog_artifact_revision_command(&artifact.source.repo, hf_token_file.as_deref());
            let metadata_command_template = catalog_artifact_metadata_plan_command(
                &catalog_path,
                model,
                artifact_name,
                &published_artifact_path_template,
                &report_path,
                Some("<published-hf-commit-40-hex>"),
            );
            let metadata_after_publish_shell = catalog_artifact_metadata_after_publish_shell(
                CatalogArtifactMetadataAfterPublishInput {
                    catalog_path: &catalog_path,
                    model,
                    artifact_name,
                    artifact,
                    current_artifact_path: &current_artifact_path,
                    artifact_base: &artifact_base,
                    report_path: &report_path,
                    revision_command: &revision_command,
                },
            );
            let ok = entry_errors.is_empty();
            let entry = CatalogArtifactPublishPlanEntry {
                model_id: model.model_id.clone(),
                tier: model.tier.clone(),
                artifact: artifact_name.clone(),
                engine: artifact.engine.clone(),
                source_kind: artifact.source.kind.clone(),
                source_repo: artifact.source.repo.clone(),
                current_source_revision: artifact.source.revision.clone(),
                source_path: artifact.path.clone(),
                catalog_weights_bytes: artifact.weights_bytes,
                current_artifact_path,
                current_artifact_exists,
                current_artifact_is_file,
                current_artifact_bytes,
                published_artifact_path_template,
                report_path,
                upload_command,
                revision_command,
                metadata_command_template,
                metadata_after_publish_shell,
                ok,
                errors: entry_errors,
            };
            if !entry.ok {
                errors.extend(
                    entry
                        .errors
                        .iter()
                        .map(|error| format!("{} {}: {error}", entry.model_id, entry.artifact)),
                );
            }
            entries.push(entry);
        }
    }

    if entries.is_empty() {
        errors.push(
            match (model_filter.as_deref(), artifact_filter.as_deref()) {
                (Some(model), Some(artifact)) => format!(
                    "catalog selection matched no {} artifact {artifact} for model {model}",
                    if launch_only { "launch" } else { "model" }
                ),
                (Some(model), None) => format!(
                    "catalog selection matched no {} artifacts for model {model}",
                    if launch_only { "launch" } else { "model" }
                ),
                (None, _) if launch_only => {
                    "catalog has no launch model artifacts to publish".to_owned()
                }
                (None, _) => "catalog has no model artifacts to publish".to_owned(),
            },
        );
    }
    let artifact_base_space_ok = artifact_base_available_bytes
        .map(|available| available >= missing_artifact_bytes || missing_artifact_bytes == 0);
    if artifact_base_space_ok == Some(false) {
        errors.push(format!(
            "artifact base filesystem has {} byte(s) available but {} byte(s) are still missing by catalog estimate",
            artifact_base_available_bytes.unwrap_or(0),
            missing_artifact_bytes
        ));
    }

    let report_paths = entries
        .iter()
        .map(|entry| entry.report_path.clone())
        .collect::<Vec<_>>();
    let apply_command = catalog_artifact_plan_apply_command(
        &catalog_path,
        &catalog_output,
        launch_only,
        &report_paths,
    );
    let signature_command = catalog_sign
        .as_ref()
        .map(|sign| catalog_canary_plan_sign_command(&catalog_output, sign));
    let verify_command = catalog_sign.as_ref().map(|sign| {
        catalog_artifact_plan_verify_command(&catalog_output, sign, hf_token_file.as_deref())
    });
    let model_count = entries
        .iter()
        .map(|entry| entry.model_id.as_str())
        .collect::<BTreeSet<_>>()
        .len();
    let preflight_command = catalog_artifact_publish_preflight_command(hf_token_file.as_deref());
    CatalogArtifactPublishPlanReport {
        catalog_path,
        artifact_base,
        report_dir,
        catalog_output,
        launch_only,
        model_filter,
        artifact_filter,
        hf_token_file,
        model_count,
        artifact_count: entries.len(),
        catalog_expected_bytes,
        current_artifact_bytes: current_artifact_bytes_total,
        missing_artifact_bytes,
        artifact_base_available_bytes,
        artifact_base_space_ok,
        ok: errors.is_empty(),
        preflight_command,
        publish_commands: entries,
        apply_command,
        signature_command,
        verify_command,
        errors,
    }
}

fn catalog_artifact_metadata_plan_command(
    catalog_path: &Path,
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact_path: &Path,
    report_path: &Path,
    source_revision: Option<&str>,
) -> CatalogCanaryPlanCommand {
    let mut argv = vec![
        "mayhem".to_owned(),
        "catalog".to_owned(),
        "artifact-metadata".to_owned(),
    ];
    push_plan_path_arg(&mut argv, "--catalog-path", catalog_path);
    push_plan_value_arg(&mut argv, "--model", &model.model_id);
    push_plan_value_arg(&mut argv, "--artifact", artifact_name);
    push_plan_path_arg(&mut argv, "--artifact-path", artifact_path);
    push_plan_path_arg(&mut argv, "--report-output", report_path);
    if let Some(source_revision) = source_revision {
        push_plan_value_arg(&mut argv, "--source-revision", source_revision);
    }
    argv.push("--json".to_owned());
    catalog_canary_plan_command(argv)
}

fn catalog_artifact_primary_upstream_source<'a>(
    model: &'a catalog::CatalogModel,
    artifact: &'a catalog::CatalogArtifact,
) -> &'a catalog::SourceRef {
    artifact
        .upstream_source
        .as_ref()
        .unwrap_or(&model.provenance.source)
}

fn catalog_artifact_stage_sources<'a>(
    model: &'a catalog::CatalogModel,
    artifact: &'a catalog::CatalogArtifact,
) -> Vec<&'a catalog::SourceRef> {
    let primary = catalog_artifact_primary_upstream_source(model, artifact);
    let mut sources = vec![primary];
    for sidecar in artifact.sidecars.values() {
        if let Some(source) = &sidecar.upstream_source {
            if !sources.contains(&source) {
                sources.push(source);
            }
        }
    }
    sources
}

fn catalog_artifact_stage_source_dir(
    source_cache_dir: &Path,
    source: &catalog::SourceRef,
) -> PathBuf {
    source_cache_dir
        .join(safe_path_component(&source.kind))
        .join(safe_path_component(&source.repo))
        .join(safe_path_component(&source.revision))
}

fn catalog_artifact_stage_preflight_command(
    hf_token_file: Option<&Path>,
    needs_llama_cpp: bool,
) -> CatalogCanaryPlanCommand {
    let mut checks = vec![
        hf_cli_path_assignment(),
        llama_cpp_venv_path_assignment(),
        "python3 -c 'import huggingface_hub' || { echo \"missing Python huggingface_hub module: install with python3 -m pip install --user huggingface_hub[hf_xet]\" >&2; exit 1; }".to_owned(),
    ];
    if let Some(hf_token_file) = hf_token_file {
        checks.push(format!(
            "test -r {} || {{ echo \"HF token file is not readable: {}\" >&2; exit 1; }}",
            shell_single_quote(&hf_token_file.display().to_string()),
            hf_token_file.display()
        ));
    }
    if needs_llama_cpp {
        checks.push("test -n \"${MAYHEM_LLAMA_CPP_DIR:-}\" || { echo \"GGUF staging needs MAYHEM_LLAMA_CPP_DIR pointing at a llama.cpp checkout\" >&2; exit 1; }".to_owned());
    }
    checks.push("command -v python3 >/dev/null".to_owned());
    let script = checks.join(" && ");
    let mut command =
        catalog_canary_plan_command(vec!["sh".to_owned(), "-lc".to_owned(), script.clone()]);
    command.shell = script;
    command
}

fn catalog_artifact_stage_source_download_command(
    source: &catalog::SourceRef,
    source_dir: &Path,
    hf_token_file: Option<&Path>,
    allow_patterns: Option<&[String]>,
) -> CatalogCanaryPlanCommand {
    let repo = serde_json::to_string(&source.repo).expect("repo string serializes");
    let revision = serde_json::to_string(&source.revision).expect("revision string serializes");
    let local_dir =
        serde_json::to_string(&source_dir.display().to_string()).expect("path string serializes");
    let allow_patterns = allow_patterns
        .map(|patterns| {
            format!(
                ", allow_patterns={}",
                serde_json::to_string(patterns).expect("allow patterns serialize")
            )
        })
        .unwrap_or_default();
    let script = format!(
        "from huggingface_hub import snapshot_download; import os; snapshot_download(repo_id={repo}, revision={revision}, local_dir={local_dir}, token=os.environ.get('HF_TOKEN'){allow_patterns})"
    );
    let mut command =
        catalog_canary_plan_command(vec!["python3".to_owned(), "-c".to_owned(), script]);
    command.shell = with_hf_shell_prefix(command.shell, hf_token_file, false);
    command
}

fn catalog_artifact_stage_source_patterns(
    catalog_doc: &catalog::CatalogDocument,
    source: &catalog::SourceRef,
    launch_only: bool,
    model_filter: Option<&str>,
    artifact_filter: Option<&str>,
) -> Option<Vec<String>> {
    let mut patterns = BTreeSet::new();
    let mut selected = false;
    for model in &catalog_doc.models {
        if launch_only && model.tier != "launch" {
            continue;
        }
        if model_filter.is_some_and(|selected| selected != model.model_id) {
            continue;
        }
        for (artifact_name, artifact) in &model.artifacts {
            if artifact_filter.is_some_and(|selected| selected != artifact_name) {
                continue;
            }
            let primary_source = catalog_artifact_primary_upstream_source(model, artifact);
            if primary_source == source {
                if artifact.upstream_source.is_none() {
                    return None;
                }
                selected = true;
                patterns.insert(artifact.path.clone());
            }
            for sidecar in artifact.sidecars.values() {
                let sidecar_source = sidecar.upstream_source.as_ref().unwrap_or(primary_source);
                if sidecar_source == source {
                    selected = true;
                    patterns.insert(sidecar.path.clone());
                }
            }
        }
    }
    if !selected {
        return None;
    }
    patterns.extend(
        [
            ".gitattributes",
            "README.md",
            "LICENSE",
            "LICENSE.md",
            "LICENSE.txt",
        ]
        .into_iter()
        .map(str::to_owned),
    );
    Some(patterns.into_iter().collect())
}

fn catalog_artifact_stage_command(
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    source_dir: &Path,
    source_cache_dir: &Path,
    upstream_source: &catalog::SourceRef,
    artifact_base: &Path,
    artifact_path: &Path,
) -> Result<CatalogCanaryPlanCommand> {
    if artifact.upstream_source.is_some() {
        return catalog_artifact_stage_mirror_command(
            source_cache_dir,
            upstream_source,
            artifact,
            artifact_path,
        );
    }
    match artifact.engine.as_str() {
        "llama.cpp" => Ok(catalog_artifact_stage_gguf_command(
            model,
            artifact_name,
            source_dir,
            artifact_base,
            artifact_path,
        )),
        "mlx" => Ok(catalog_artifact_stage_mlx_command(
            source_dir,
            artifact_path,
        )),
        "trt-llm" => Ok(catalog_artifact_stage_trt_command(
            model,
            artifact_name,
            source_dir,
            artifact_base,
            artifact_path,
        )?),
        "vllm" => Ok(catalog_artifact_stage_mirror_command(
            source_cache_dir,
            upstream_source,
            artifact,
            artifact_path,
        )?),
        other => bail!("unsupported artifact engine {other} for staging"),
    }
}

fn catalog_artifact_stage_gguf_command(
    model: &catalog::CatalogModel,
    artifact_name: &str,
    source_dir: &Path,
    artifact_base: &Path,
    artifact_path: &Path,
) -> CatalogCanaryPlanCommand {
    let build_dir = artifact_base
        .join(".build")
        .join(safe_path_component(&model.model_id))
        .join(safe_path_component(artifact_name));
    let f16_path = build_dir.join("model.f16.gguf");
    let script = format!(
        "{} && export PATH && test -n \"${{MAYHEM_LLAMA_CPP_DIR:-}}\" || {{ echo \"set MAYHEM_LLAMA_CPP_DIR to a llama.cpp checkout\" >&2; exit 1; }} && LLAMA_QUANTIZE=\"${{MAYHEM_LLAMA_QUANTIZE_BIN:-$MAYHEM_LLAMA_CPP_DIR/build/bin/llama-quantize}}\" && if [ ! -x \"$LLAMA_QUANTIZE\" ]; then LLAMA_QUANTIZE=\"$(find \"$MAYHEM_LLAMA_CPP_DIR\" -path '*/bin/llama-quantize' -type f -perm -111 | sort | head -n 1)\"; fi && test -x \"$LLAMA_QUANTIZE\" || {{ echo \"missing llama-quantize; set MAYHEM_LLAMA_QUANTIZE_BIN\" >&2; exit 1; }} && mkdir -p {} {} && python3 \"$MAYHEM_LLAMA_CPP_DIR/convert_hf_to_gguf.py\" {} --outfile {} --outtype f16 && \"$LLAMA_QUANTIZE\" {} {} Q4_K_M && test -s {}",
        llama_cpp_venv_path_assignment(),
        shell_single_quote(&artifact_path.parent().unwrap_or_else(|| Path::new(".")).display().to_string()),
        shell_single_quote(&build_dir.display().to_string()),
        shell_single_quote(&source_dir.display().to_string()),
        shell_single_quote(&f16_path.display().to_string()),
        shell_single_quote(&f16_path.display().to_string()),
        shell_single_quote(&artifact_path.display().to_string()),
        shell_single_quote(&artifact_path.display().to_string())
    );
    let mut command =
        catalog_canary_plan_command(vec!["sh".to_owned(), "-lc".to_owned(), script.clone()]);
    command.shell = script;
    command
}

fn catalog_artifact_stage_mlx_command(
    source_dir: &Path,
    artifact_path: &Path,
) -> CatalogCanaryPlanCommand {
    let target_dir = artifact_path.parent().unwrap_or_else(|| Path::new("."));
    let parent_dir = target_dir.parent().unwrap_or_else(|| Path::new("."));
    let script = format!(
        "PATH=\"${{MAYHEM_MLX_VENV:+$MAYHEM_MLX_VENV/bin:}}$HOME/.local/bin:$PATH\" && export PATH && command -v python3 >/dev/null && mkdir -p {} && test ! -e {} || {{ echo \"MLX output path already exists; remove it or choose a clean artifact base: {}\" >&2; exit 1; }} && python3 -m mlx_lm convert --hf-path {} --mlx-path {} --quantize && test -s {}",
        shell_single_quote(&parent_dir.display().to_string()),
        shell_single_quote(&target_dir.display().to_string()),
        shell_single_quote(&target_dir.display().to_string()),
        shell_single_quote(&source_dir.display().to_string()),
        shell_single_quote(&target_dir.display().to_string()),
        shell_single_quote(&artifact_path.display().to_string())
    );
    let mut command =
        catalog_canary_plan_command(vec!["sh".to_owned(), "-lc".to_owned(), script.clone()]);
    command.shell = script;
    command
}

fn catalog_artifact_stage_trt_command(
    model: &catalog::CatalogModel,
    artifact_name: &str,
    source_dir: &Path,
    artifact_base: &Path,
    artifact_path: &Path,
) -> Result<CatalogCanaryPlanCommand> {
    let qformat = match artifact_name {
        "nvfp4" => "nvfp4",
        "trt-fp8" => "fp8",
        other => bail!("unsupported TensorRT artifact {other}; expected nvfp4 or trt-fp8"),
    };
    let trt_base = artifact_base.join(".trtllm-build");
    let safe_model = safe_path_component(&model.model_id);
    let safe_artifact = safe_path_component(artifact_name);
    let checkpoint_dir = trt_base
        .join("checkpoints")
        .join(&safe_model)
        .join(&safe_artifact);
    let engine_dir = trt_base
        .join("engines")
        .join(&safe_model)
        .join(&safe_artifact);
    let script = format!(
        "SCRIPT=\"${{MAYHEM_TRTLLM_BUILD_SCRIPT:-scripts/trtllm-engine-build.sh}}\" && test -x \"$SCRIPT\" || {{ echo \"set MAYHEM_TRTLLM_BUILD_SCRIPT or run from the Mayhem repo root\" >&2; exit 1; }} && mkdir -p {} && \"$SCRIPT\" --model-dir {} --checkpoint-dir {} --engine-dir {} --qformat {} && PAYLOAD=\"$(find {} -maxdepth 1 -type f -name 'rank*.safetensors' | sort | head -n 1)\" && test -n \"$PAYLOAD\" && cp -f \"$PAYLOAD\" {} && test -s {}",
        shell_single_quote(&artifact_path.parent().unwrap_or_else(|| Path::new(".")).display().to_string()),
        shell_single_quote(&source_dir.display().to_string()),
        shell_single_quote(&checkpoint_dir.display().to_string()),
        shell_single_quote(&engine_dir.display().to_string()),
        shell_single_quote(qformat),
        shell_single_quote(&checkpoint_dir.display().to_string()),
        shell_single_quote(&artifact_path.display().to_string()),
        shell_single_quote(&artifact_path.display().to_string())
    );
    let mut command =
        catalog_canary_plan_command(vec!["sh".to_owned(), "-lc".to_owned(), script.clone()]);
    command.shell = script;
    Ok(command)
}

fn catalog_artifact_stage_mirror_command(
    source_cache_dir: &Path,
    primary_source: &catalog::SourceRef,
    artifact: &catalog::CatalogArtifact,
    artifact_path: &Path,
) -> Result<CatalogCanaryPlanCommand> {
    let target_root = catalog_artifact_local_root(artifact_path, &artifact.path)?;
    let primary_source_dir = catalog_artifact_stage_source_dir(source_cache_dir, primary_source);
    let mut files = vec![(
        "weights".to_owned(),
        artifact.path.clone(),
        primary_source_dir.clone(),
    )];
    files.extend(artifact.sidecars.iter().map(|(name, sidecar)| {
        let source = sidecar.upstream_source.as_ref().unwrap_or(primary_source);
        (
            name.clone(),
            sidecar.path.clone(),
            catalog_artifact_stage_source_dir(source_cache_dir, source),
        )
    }));
    let mut seen_paths = BTreeSet::new();
    let mut steps = Vec::new();
    for (label, relative, source_dir) in files {
        let relative = validate_catalog_artifact_relative_path(&relative)?;
        if !seen_paths.insert(relative.clone()) {
            bail!("artifact has duplicate staged path {}", relative.display());
        }
        let source_file = source_dir.join(&relative);
        let target_file = target_root.join(&relative);
        let target_parent = target_file.parent().unwrap_or_else(|| Path::new("."));
        steps.push(format!(
            "mkdir -p {} && test -s {} || {{ echo \"prebuilt {label} source file not found: {}\" >&2; exit 1; }} && cp -f {} {} && test -s {}",
            shell_single_quote(&target_parent.display().to_string()),
            shell_single_quote(&source_file.display().to_string()),
            source_file.display(),
            shell_single_quote(&source_file.display().to_string()),
            shell_single_quote(&target_file.display().to_string()),
            shell_single_quote(&target_file.display().to_string())
        ));
    }
    steps.push(format!(
        "for MAYHEM_METADATA in .gitattributes README.md LICENSE LICENSE.md LICENSE.txt; do if [ -f {}/\"$MAYHEM_METADATA\" ]; then cp -f {}/\"$MAYHEM_METADATA\" {}/\"$MAYHEM_METADATA\"; fi; done",
        shell_single_quote(&primary_source_dir.display().to_string()),
        shell_single_quote(&primary_source_dir.display().to_string()),
        shell_single_quote(&target_root.display().to_string()),
    ));
    let script = steps.join(" && ");
    let mut command =
        catalog_canary_plan_command(vec!["sh".to_owned(), "-lc".to_owned(), script.clone()]);
    command.shell = script;
    Ok(command)
}

fn validate_catalog_artifact_relative_path(relative: &str) -> Result<PathBuf> {
    let path = PathBuf::from(relative);
    if path.as_os_str().is_empty() || path.is_absolute() {
        bail!("catalog artifact path must be relative: {relative:?}");
    }
    if path
        .components()
        .any(|component| !matches!(component, Component::Normal(_)))
    {
        bail!("catalog artifact path must not contain traversal: {relative:?}");
    }
    Ok(path)
}

fn catalog_artifact_local_root(artifact_path: &Path, relative: &str) -> Result<PathBuf> {
    let relative = validate_catalog_artifact_relative_path(relative)?;
    let mut root = artifact_path.to_path_buf();
    for _ in relative.components() {
        if !root.pop() {
            bail!(
                "artifact path {} cannot contain catalog-relative path {}",
                artifact_path.display(),
                relative.display()
            );
        }
    }
    Ok(root)
}

fn catalog_artifact_stage_follow_up_command(
    catalog_path: &Path,
    artifact_base: &Path,
    hf_token_file: Option<&Path>,
    model_filter: Option<&str>,
    artifact_filter: Option<&str>,
) -> CatalogCanaryPlanCommand {
    let report_dir = artifact_base.join(".publish-reports");
    let mut argv = vec![
        "mayhem".to_owned(),
        "catalog".to_owned(),
        "artifact-publish-plan".to_owned(),
    ];
    push_plan_path_arg(&mut argv, "--catalog-path", catalog_path);
    push_plan_path_arg(&mut argv, "--artifact-base", artifact_base);
    push_plan_path_arg(&mut argv, "--report-dir", &report_dir);
    if let Some(hf_token_file) = hf_token_file {
        push_plan_path_arg(&mut argv, "--hf-token-file", hf_token_file);
    }
    if let Some(model_filter) = model_filter {
        push_plan_value_arg(&mut argv, "--model", model_filter);
    }
    if let Some(artifact_filter) = artifact_filter {
        push_plan_value_arg(&mut argv, "--artifact", artifact_filter);
    }
    argv.push("--json".to_owned());
    catalog_canary_plan_command(argv)
}

fn catalog_artifact_upload_command(
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    current_artifact_path: &Path,
    hf_token_file: Option<&Path>,
) -> Result<CatalogCanaryPlanCommand> {
    validate_catalog_artifact_relative_path(&artifact.path)?;
    let upload_directory = artifact.engine == "mlx"
        || artifact.upstream_source.is_some()
        || !artifact.sidecars.is_empty();
    let upload_root;
    let (upload_path, repo_path) = if upload_directory {
        upload_root = catalog_artifact_local_root(current_artifact_path, &artifact.path)?;
        (upload_root.as_path(), ".".to_owned())
    } else {
        (current_artifact_path, artifact.path.clone())
    };
    let argv = vec![
        "hf".to_owned(),
        "upload".to_owned(),
        "--repo-type".to_owned(),
        "model".to_owned(),
        "--commit-message".to_owned(),
        format!("Mayhem admin artifact {} {}", model.model_id, artifact_name),
        artifact.source.repo.clone(),
        upload_path.display().to_string(),
        repo_path,
    ];
    let mut command = catalog_canary_plan_command(argv);
    command.shell = with_hf_shell_prefix(command.shell, hf_token_file, true);
    Ok(command)
}

fn catalog_artifact_publish_preflight_command(
    hf_token_file: Option<&Path>,
) -> CatalogCanaryPlanCommand {
    let mut checks = vec![
        hf_cli_path_assignment(),
        "command -v hf >/dev/null || { echo \"missing Hugging Face CLI: install with python3 -m pip install --user huggingface_hub[hf_xet]\" >&2; exit 1; }".to_owned(),
        "python3 -c 'import huggingface_hub' || { echo \"missing Python huggingface_hub module: install with python3 -m pip install --user huggingface_hub\" >&2; exit 1; }".to_owned(),
    ];
    if let Some(hf_token_file) = hf_token_file {
        checks.push(format!(
            "test -r {} || {{ echo \"HF token file is not readable: {}\" >&2; exit 1; }}",
            shell_single_quote(&hf_token_file.display().to_string()),
            hf_token_file.display()
        ));
    }
    let script = checks.join(" && ");
    let mut command =
        catalog_canary_plan_command(vec!["sh".to_owned(), "-lc".to_owned(), script.clone()]);
    command.shell = script;
    command
}

fn catalog_artifact_revision_command(
    source_repo: &str,
    hf_token_file: Option<&Path>,
) -> CatalogCanaryPlanCommand {
    let repo_literal = serde_json::to_string(source_repo).expect("repo string serializes");
    let script = format!(
        "from huggingface_hub import HfApi; import os; print(HfApi(token=os.environ.get('HF_TOKEN')).model_info({repo_literal}).sha)"
    );
    let mut command =
        catalog_canary_plan_command(vec!["python3".to_owned(), "-c".to_owned(), script]);
    command.shell = with_hf_shell_prefix(command.shell, hf_token_file, false);
    command
}

struct CatalogArtifactMetadataAfterPublishInput<'a> {
    catalog_path: &'a Path,
    model: &'a catalog::CatalogModel,
    artifact_name: &'a str,
    artifact: &'a catalog::CatalogArtifact,
    current_artifact_path: &'a Path,
    artifact_base: &'a Path,
    report_path: &'a Path,
    revision_command: &'a CatalogCanaryPlanCommand,
}

fn catalog_artifact_metadata_after_publish_shell(
    input: CatalogArtifactMetadataAfterPublishInput<'_>,
) -> String {
    let CatalogArtifactMetadataAfterPublishInput {
        catalog_path,
        model,
        artifact_name,
        artifact,
        current_artifact_path,
        artifact_base,
        report_path,
        revision_command,
    } = input;
    let published_prefix = artifact_base
        .join(safe_path_component(&artifact.source.kind))
        .join(safe_path_component(&artifact.source.repo));
    let current_root = catalog_artifact_local_root(current_artifact_path, &artifact.path)
        .expect("catalog artifact path was validated before publish planning");
    let mut metadata_argv = vec![
        "mayhem".to_owned(),
        "catalog".to_owned(),
        "artifact-metadata".to_owned(),
    ];
    push_plan_path_arg(&mut metadata_argv, "--catalog-path", catalog_path);
    push_plan_value_arg(&mut metadata_argv, "--model", &model.model_id);
    push_plan_value_arg(&mut metadata_argv, "--artifact", artifact_name);
    metadata_argv.push("--artifact-path".to_owned());
    metadata_argv.push("$PUBLISHED_ARTIFACT_PATH".to_owned());
    push_plan_path_arg(&mut metadata_argv, "--report-output", report_path);
    metadata_argv.push("--source-revision".to_owned());
    metadata_argv.push("$PUBLISHED_REVISION".to_owned());
    metadata_argv.push("--json".to_owned());
    let metadata_shell = metadata_argv
        .iter()
        .map(|arg| {
            if arg == "$PUBLISHED_ARTIFACT_PATH" || arg == "$PUBLISHED_REVISION" {
                format!("\"{arg}\"")
            } else {
                shell_single_quote(arg)
            }
        })
        .collect::<Vec<_>>()
        .join(" ");
    let mut link_steps = vec![format!(
        "PUBLISHED_ARTIFACT_PATH={}/\"$PUBLISHED_REVISION\"/{} && mkdir -p \"$(dirname \"$PUBLISHED_ARTIFACT_PATH\")\" && ln -sfn {} \"$PUBLISHED_ARTIFACT_PATH\"",
        shell_single_quote(&published_prefix.display().to_string()),
        shell_single_quote(&artifact.path),
        shell_single_quote(&current_artifact_path.display().to_string()),
    )];
    for sidecar in artifact.sidecars.values().filter(|sidecar| {
        sidecar.source.kind == artifact.source.kind
            && sidecar.source.repo == artifact.source.repo
            && sidecar.source.revision == artifact.source.revision
    }) {
        let current_sidecar = current_root.join(&sidecar.path);
        link_steps.push(format!(
            "PUBLISHED_SIDECAR_PATH={}/\"$PUBLISHED_REVISION\"/{} && mkdir -p \"$(dirname \"$PUBLISHED_SIDECAR_PATH\")\" && ln -sfn {} \"$PUBLISHED_SIDECAR_PATH\"",
            shell_single_quote(&published_prefix.display().to_string()),
            shell_single_quote(&sidecar.path),
            shell_single_quote(&current_sidecar.display().to_string()),
        ));
    }
    format!(
        "PUBLISHED_REVISION=$({}) && test -n \"$PUBLISHED_REVISION\" && {} && {}",
        revision_command.shell,
        link_steps.join(" && "),
        metadata_shell
    )
}

fn catalog_artifact_published_template_path(
    artifact_base: &Path,
    artifact: &catalog::CatalogArtifact,
) -> PathBuf {
    artifact_base
        .join(safe_path_component(&artifact.source.kind))
        .join(safe_path_component(&artifact.source.repo))
        .join("<published-hf-commit-40-hex>")
        .join(&artifact.path)
}

fn available_bytes_for_path(path: &Path) -> Result<Option<u64>> {
    let mut candidate = if path.exists() {
        path.to_path_buf()
    } else {
        path.parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."))
    };
    loop {
        if candidate.exists() {
            return fs2::available_space(&candidate)
                .map(Some)
                .with_context(|| format!("checking available space for {}", candidate.display()));
        }
        if !candidate.pop() {
            return Ok(None);
        }
    }
}

fn with_hf_shell_prefix(
    shell: String,
    hf_token_file: Option<&Path>,
    high_performance_upload: bool,
) -> String {
    let mut assignments = Vec::new();
    assignments.push(hf_cli_path_assignment());
    if let Some(hf_token_file) = hf_token_file {
        assignments.push(format!(
            "HF_TOKEN=\"$(tr -d '\\r\\n' < {})\"",
            shell_single_quote(&hf_token_file.display().to_string())
        ));
    }
    if high_performance_upload {
        assignments.push("HF_XET_HIGH_PERFORMANCE=1".to_owned());
    }
    format!("{} {}", assignments.join(" "), shell)
}

fn hf_cli_path_assignment() -> String {
    "PATH=\"${MAYHEM_HF_VENV:+$MAYHEM_HF_VENV/bin:}$HOME/.local/bin:$PATH\"".to_owned()
}

fn llama_cpp_venv_path_assignment() -> String {
    "PATH=\"${MAYHEM_LLAMA_CPP_VENV:+$MAYHEM_LLAMA_CPP_VENV/bin:}$PATH\"".to_owned()
}

