async fn admin_read_rpc(args: &AdminReadArgs) -> Result<(String, PeerRpcClient)> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    Ok((rpc_url.clone(), PeerRpcClient::new(&rpc_url)?))
}

async fn admin_init_subnet(args: &AdminInitSubnetArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let status = rpc
        .status()
        .await
        .context("reading bootstrap peer status")?;
    let peer = status
        .get("peer")
        .and_then(Value::as_object)
        .context("peer status is missing peer")?;
    let msb = status
        .get("msb")
        .and_then(Value::as_object)
        .context("peer status is missing msb")?;
    let peer_pubkey = peer
        .get("pubKeyHex")
        .and_then(Value::as_str)
        .filter(|value| is_hex_len(value, 64))
        .context("peer status is missing a 32-byte peer public key")?
        .to_ascii_lowercase();
    let peer_msb_address = peer
        .get("msbAddress")
        .and_then(Value::as_str)
        .context("peer status is missing the peer MSB address")?;
    let base_writable = peer
        .get("baseWritable")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let is_indexer = peer
        .get("isIndexer")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let network_id = msb.get("networkId").and_then(Value::as_u64);
    let msb_bootstrap = msb
        .get("bootstrapHex")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_ascii_lowercase();
    let msb_channel = msb.get("channel").and_then(Value::as_str).unwrap_or("");
    let validators = msb
        .get("connectedValidators")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    if network_id != Some(MAINNET_MSB_NETWORK_ID)
        || msb_bootstrap != MAINNET_MSB_BOOTSTRAP
        || msb_channel != MAINNET_MSB_CHANNEL
        || validators == 0
    {
        bail!(
            "fresh subnet initialization requires a synced official MSB mainnet peer with a validator connection"
        );
    }
    let existing_admin = read_state_value(&rpc, "admin").await?;
    if existing_admin
        .as_ref()
        .and_then(Value::as_str)
        .is_some_and(|admin| !admin.eq_ignore_ascii_case(&peer_pubkey))
    {
        bail!("subnet already has a different admin; refusing fresh initialization");
    }
    let copy_paste = format!(
        "mayhem admin init-subnet --home {} --confirm --json",
        shell_single_quote(&home.display().to_string())
    );
    let mut report = json!({
        "ok": true,
        "confirmed": false,
        "rpc_url": rpc_url,
        "peer_pubkey": peer_pubkey,
        "peer_msb_address": peer_msb_address,
        "base_writable": base_writable,
        "is_indexer": is_indexer,
        "existing_admin": existing_admin,
        "msb": {
            "network_id": network_id,
            "bootstrap": msb_bootstrap,
            "channel": msb_channel,
            "connected_validators": validators,
        },
        "copy_paste_confirm_command": copy_paste,
    });
    if !args.confirm {
        if args.json {
            println!("{}", serde_json::to_string_pretty(&report)?);
        } else {
            println!("Fresh mainnet subnet preflight ready.");
            println!("Peer MSB address: {peer_msb_address}");
            println!("Bootstrap writer: {base_writable}; indexer: {is_indexer}");
            println!("Copy/paste confirm command:");
            println!("{copy_paste}");
        }
        return Ok(());
    }
    if !base_writable || !is_indexer {
        bail!(
            "peer is not the fresh writable bootstrap/indexer; restart it without an existing subnet bootstrap before confirming"
        );
    }

    let (sc_bridge_url, sc_bridge_token) = resolve_cli_sc_bridge(
        Some(&home),
        args.sc_bridge_url.as_deref(),
        args.sc_bridge_token.as_deref(),
    )?;
    let mut bridge = ScBridgeClient::connect(ScBridgeConfig::new(&sc_bridge_url, sc_bridge_token)?)
        .await
        .context("connecting to bootstrap SC-Bridge")?;
    let deployment = bridge
        .cli("/deploy_subnet")
        .await
        .context("broadcasting mainnet subnet deployment")?;
    let deployment_result = deployment
        .get("result")
        .context("subnet deployment did not return a result")?;
    let deployment_body = deployment_result
        .get("bdo")
        .and_then(Value::as_object)
        .context("subnet deployment result is missing bdo")?;
    let deployment_tx = deployment_body
        .get("tx")
        .and_then(Value::as_str)
        .filter(|value| is_hex_len(value, 64))
        .context("subnet deployment result is missing a transaction hash")?
        .to_ascii_lowercase();
    let subnet_bootstrap = deployment_body
        .get("bs")
        .and_then(Value::as_str)
        .filter(|value| is_hex_len(value, 64))
        .context("subnet deployment result is missing a bootstrap")?
        .to_ascii_lowercase();

    if existing_admin.is_none() {
        bridge
            .cli(format!("/add_admin --address {peer_pubkey}"))
            .await
            .context("setting the sole initial subnet admin")?;
    }
    let deadline = Instant::now() + Duration::from_secs(args.timeout_seconds);
    let admin_state = loop {
        let current = read_state_value(&rpc, "admin").await?;
        if current
            .as_ref()
            .and_then(Value::as_str)
            .is_some_and(|admin| admin.eq_ignore_ascii_case(&peer_pubkey))
        {
            break current;
        }
        if Instant::now() >= deadline {
            bail!("timed out waiting for the initial admin state");
        }
        sleep(Duration::from_millis(500)).await;
    };
    report["confirmed"] = json!(true);
    report["subnet_bootstrap"] = json!(subnet_bootstrap);
    report["subnet_deployment_tx"] = json!(deployment_tx);
    report["admin"] = admin_state.unwrap_or(Value::Null);

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("Fresh mainnet Intercom subnet initialized.");
        println!("Subnet bootstrap: {}", report["subnet_bootstrap"]);
        println!(
            "MSB deployment transaction: {}",
            report["subnet_deployment_tx"]
        );
        println!("Initial admin: {peer_pubkey}");
    }
    Ok(())
}

async fn admin_tier3_list(args: &AdminTier3ListArgs) -> Result<()> {
    if let Some(platform) = args.platform.as_deref() {
        validate_tier3_platform(platform)?;
    }
    let (rpc_url, rpc) = admin_read_rpc(&args.read).await?;
    let mut records = Vec::new();
    for entry in read_prefix_entries(&rpc, "tier3/measurement/").await? {
        let tail = entry
            .key
            .strip_prefix("tier3/measurement/")
            .unwrap_or(entry.key.as_str());
        if tail.contains('/') {
            continue;
        }
        if args
            .platform
            .as_deref()
            .is_some_and(|platform| platform != tail)
        {
            continue;
        }
        records.push(json!({
            "platform": tail,
            "key": entry.key,
            "record": entry.value,
        }));
    }
    records.sort_by(|left, right| {
        left["platform"]
            .as_str()
            .unwrap_or("")
            .cmp(right["platform"].as_str().unwrap_or(""))
    });
    let count = records.len();
    let report = json!({
        "ok": true,
        "action": "admin.tier3.list",
        "rpc_url": rpc_url,
        "platform": args.platform,
        "count": count,
        "records": records,
    });
    if args.read.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if count == 0 {
        println!("No Tier-3 measurement sets found.");
    } else {
        println!("Tier-3 measurement sets:");
        for record in report["records"].as_array().into_iter().flatten() {
            let platform = record["platform"].as_str().unwrap_or("");
            let entries = record["record"]
                .get("entries")
                .and_then(Value::as_array)
                .map(Vec::len)
                .unwrap_or(0);
            println!("{platform}: {entries} blessed measurement(s)");
        }
    }
    Ok(())
}

async fn admin_tier3_derive(args: &AdminTier3DeriveArgs) -> Result<()> {
    validate_tier3_platform(&args.platform)?;
    validate_tier3_measurement_name(&args.measurement_name)?;
    validate_tier3_measurement_layer(&args.layer)?;
    if args.measurement.is_some() && args.derive_command.is_some() {
        bail!("pass only one of --measurement or --derive-command");
    }
    if args.endorsement_file.is_some()
        && args.source_kind != Tier3DeriveSourceKind::VendorEndorsement
    {
        bail!("--endorsement-file requires --source-kind vendor-endorsement");
    }
    let mut command_output = None;
    let (measurement, source) = if let Some(measurement) = args.measurement.as_deref() {
        let source = match args.source_kind {
            Tier3DeriveSourceKind::AdminBoot => "admin-provided-measurement",
            Tier3DeriveSourceKind::OfflineCompute => "offline-compute",
            Tier3DeriveSourceKind::VendorEndorsement => "vendor-endorsement",
        };
        (normalize_tier3_measurement(measurement)?, source.to_owned())
    } else if let Some(command) = args.derive_command.as_ref() {
        let output = run_tier3_derive_command(command, args)?;
        if let Some(layer) = output.layer.as_deref() {
            if layer != args.layer {
                bail!(
                    "Tier-3 derive command returned layer {layer}, expected {}",
                    args.layer
                );
            }
        }
        if let Some(source_kind) = output.source_kind.as_deref() {
            if source_kind != args.source_kind.as_str() {
                bail!(
                    "Tier-3 derive command returned source_kind {source_kind}, expected {}",
                    args.source_kind.as_str()
                );
            }
        }
        let source = output
            .source
            .clone()
            .unwrap_or_else(|| format!("derive-command:{}", command.display()));
        let measurement = normalize_tier3_measurement(&output.measurement)?;
        command_output = Some(output);
        (measurement, source)
    } else {
        bail!("Tier-3 derive needs --measurement or --derive-command for this platform recipe");
    };
    let endorsement_sha256 = tier3_derivation_endorsement_sha256(args, command_output.as_ref())?;
    if args.source_kind == Tier3DeriveSourceKind::VendorEndorsement && endorsement_sha256.is_none()
    {
        bail!(
            "--source-kind vendor-endorsement requires --endorsement-file or derive-command JSON endorsement_sha256"
        );
    }
    let alert_measurement = args
        .alert_measurement
        .as_deref()
        .map(normalize_tier3_measurement)
        .transpose()?;
    let match_alert = alert_measurement
        .as_deref()
        .map(|alert| alert == measurement.as_str());
    let home = args
        .read
        .home
        .clone()
        .map(Ok)
        .unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let mut record = Tier3DerivationRecord {
        schema_version: 1,
        platform: args.platform.clone(),
        region: args.region.clone(),
        layer: args.layer.clone(),
        measurement_name: args.measurement_name.clone(),
        measurement,
        alert_measurement,
        match_alert,
        derived_at: unix_epoch_seconds()?,
        source_kind: Some(args.source_kind.as_str().to_owned()),
        source,
        endorsement_sha256,
        derivation_hash: String::new(),
    };
    record.derivation_hash = tier3_derivation_hash(&record);
    let store_path = tier3_derivation_store_path(&home);
    let mut records = read_tier3_derivations(&store_path)?;
    records.retain(|existing| {
        !(existing.platform == record.platform
            && existing.layer == record.layer
            && existing.measurement_name == record.measurement_name
            && existing.measurement == record.measurement)
    });
    records.push(record.clone());
    write_tier3_derivations(&store_path, &records)?;

    let report = json!({
        "ok": true,
        "action": "admin.tier3.derive",
        "record": record,
        "store": store_path,
    });
    if let Some(output) = args.output.as_ref() {
        if let Some(parent) = output
            .parent()
            .filter(|parent| !parent.as_os_str().is_empty())
        {
            fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
        }
        fs::write(output, serde_json::to_vec_pretty(&report)?)
            .with_context(|| format!("writing {}", output.display()))?;
    }
    if args.read.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("Tier-3 measurement derived.");
        println!(
            "Platform: {}",
            report["record"]["platform"].as_str().unwrap_or("")
        );
        println!(
            "Measurement: {}/{}={}",
            report["record"]["layer"].as_str().unwrap_or(""),
            report["record"]["measurement_name"].as_str().unwrap_or(""),
            report["record"]["measurement"].as_str().unwrap_or("")
        );
        if let Some(match_alert) = report["record"]["match_alert"].as_bool() {
            println!(
                "Alert match: {}",
                if match_alert { "MATCH" } else { "NO-MATCH" }
            );
        }
        println!("Source: {}", record.source);
        if let Some(endorsement_sha256) = record.endorsement_sha256.as_deref() {
            println!("Endorsement SHA-256: {endorsement_sha256}");
        }
        println!("Derivation hash: {}", record.derivation_hash);
        println!("Stored: {}", store_path.display());
    }
    Ok(())
}

async fn admin_tier3_bless(args: &AdminTier3BlessArgs) -> Result<()> {
    let mut tx = args.tx.clone();
    if args.confirm && tx.sim {
        bail!("do not combine --confirm with --sim");
    }
    if args.confirm {
        tx.submit = true;
        tx.sim = false;
    } else if tx.sim && !tx.submit {
        tx.submit = true;
    }
    if tx.submit && !tx.sim && !args.confirm {
        bail!(
            "real Tier-3 measurement blessing requires reviewing `mayhem admin tier3 bless --sim` first, then rerun with --confirm"
        );
    }
    let home = tx.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let measurement = normalize_tier3_measurement(&args.measurement)?;
    validate_tier3_platform(&args.platform)?;
    validate_tier3_measurement_name(&args.measurement_name)?;
    validate_tier3_measurement_layer(&args.layer)?;
    if let Some(region) = args.region.as_deref() {
        validate_tier3_platform(region)?;
    }
    if let Some(hash) = args.derivation_hash.as_deref() {
        validate_hex32_config("--derivation-hash", Some(hash))?;
    }
    let store_path = tier3_derivation_store_path(&home);
    let derivations = read_tier3_derivations(&store_path)?;
    let local = derivations.iter().find(|record| {
        record.platform == args.platform
            && record.layer == args.layer
            && record.measurement_name == args.measurement_name
            && record.measurement == measurement
            && args
                .region
                .as_deref()
                .map_or(true, |region| record.region.as_deref() == Some(region))
    });
    if local.is_none() && !args.allow_unconfirmed {
        bail!(
            "Tier-3 measurement has not been confirmed by `mayhem admin tier3 derive`; run derive first or pass --allow-unconfirmed for an explicit emergency override"
        );
    }
    let derivation_hash = args
        .derivation_hash
        .clone()
        .or_else(|| local.map(|record| record.derivation_hash.clone()));
    let value = admin_tier3_bless_payload(args, &measurement, derivation_hash.as_deref())?;
    let key = tier3_measurement_feature_key(&value)?;
    run_admin_feature_command(&tx, "tier3Measurement", key, value).await
}

#[derive(Debug, Deserialize)]
struct Tier3DeriveCommandOutput {
    #[serde(default)]
    measurement: String,
    #[serde(default)]
    measurement_name: Option<String>,
    #[serde(default)]
    layer: Option<String>,
    #[serde(default)]
    measurements: Value,
    #[serde(default)]
    source: Option<String>,
    #[serde(default)]
    source_kind: Option<String>,
    #[serde(default)]
    endorsement_sha256: Option<String>,
}

fn run_tier3_derive_command(
    command: &Path,
    args: &AdminTier3DeriveArgs,
) -> Result<Tier3DeriveCommandOutput> {
    let endorsement_file_env = args
        .endorsement_file
        .as_ref()
        .map(|path| path.display().to_string())
        .unwrap_or_default();
    let output = std::process::Command::new(command)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .env("MAYHEM_TIER3_PLATFORM", &args.platform)
        .env("MAYHEM_TIER3_LAYER", &args.layer)
        .env("MAYHEM_TIER3_MEASUREMENT_NAME", &args.measurement_name)
        .env("MAYHEM_TIER3_REGION", args.region.as_deref().unwrap_or(""))
        .env("MAYHEM_TIER3_SOURCE_KIND", args.source_kind.as_str())
        .env("MAYHEM_TIER3_ENDORSEMENT_FILE", endorsement_file_env)
        .output()
        .with_context(|| format!("running Tier-3 derive command {}", command.display()))?;
    if !output.status.success() {
        bail!(
            "Tier-3 derive command {} exited with {}; stderr: {}",
            command.display(),
            output.status,
            String::from_utf8_lossy(&output.stderr).trim()
        );
    }
    let stdout = String::from_utf8(output.stdout).context("Tier-3 derive command stdout UTF-8")?;
    let mut parsed: Tier3DeriveCommandOutput =
        serde_json::from_str(stdout.trim()).with_context(|| {
            format!(
                "parsing Tier-3 derive command JSON from {}",
                command.display()
            )
        })?;
    if parsed.measurement.is_empty() {
        if let Some(value) = parsed
            .measurements
            .get(&args.layer)
            .and_then(|layer| layer.get(&args.measurement_name))
            .and_then(measurement_value_first_string)
            .or_else(|| {
                parsed
                    .measurements
                    .get(&args.measurement_name)
                    .and_then(measurement_value_first_string)
            })
        {
            parsed.measurement = value.to_owned();
        }
    }
    if let Some(layer) = parsed.layer.as_deref() {
        validate_tier3_measurement_layer(layer)?;
        if layer != args.layer {
            bail!(
                "Tier-3 derive command returned layer {layer}, expected {}",
                args.layer
            );
        }
    }
    if parsed.measurement.is_empty() {
        if let Some(value) = parsed
            .measurements
            .get(&args.measurement_name)
            .and_then(measurement_value_first_string)
        {
            parsed.measurement = value.to_owned();
        }
    }
    if let Some(name) = parsed.measurement_name.as_deref() {
        validate_tier3_measurement_name(name)?;
        if name != args.measurement_name {
            bail!(
                "Tier-3 derive command returned measurement_name {name}, expected {}",
                args.measurement_name
            );
        }
    }
    if parsed.measurement.is_empty() {
        bail!("Tier-3 derive command did not return measurement or measurements.<name>");
    }
    Ok(parsed)
}

fn tier3_derivation_endorsement_sha256(
    args: &AdminTier3DeriveArgs,
    command_output: Option<&Tier3DeriveCommandOutput>,
) -> Result<Option<String>> {
    if let Some(path) = args.endorsement_file.as_ref() {
        let path = absolutize(path.clone())?;
        return file_sha256_hex(&path)
            .with_context(|| format!("hashing Tier-3 endorsement {}", path.display()))
            .map(Some);
    }
    let Some(hash) = command_output.and_then(|output| output.endorsement_sha256.as_deref()) else {
        return Ok(None);
    };
    validate_hex32_config("endorsement_sha256", Some(hash))?;
    Ok(Some(hash.to_ascii_lowercase()))
}

fn measurement_value_first_string(value: &Value) -> Option<&str> {
    if let Some(value) = value.as_str() {
        return Some(value);
    }
    if let Some(values) = value.as_array() {
        return values.iter().find_map(measurement_value_first_string);
    }
    if let Some(object) = value.as_object() {
        return object
            .get("measurement")
            .and_then(Value::as_str)
            .or_else(|| {
                object
                    .get("values")
                    .and_then(measurement_value_first_string)
            });
    }
    None
}

fn admin_tier3_bless_payload(
    args: &AdminTier3BlessArgs,
    measurement: &str,
    derivation_hash: Option<&str>,
) -> Result<Value> {
    validate_tier3_platform(&args.platform)?;
    validate_tier3_measurement_name(&args.measurement_name)?;
    if let Some(region) = args.region.as_deref() {
        validate_tier3_platform(region)?;
    }
    if let Some(hash) = derivation_hash {
        validate_hex32_config("derivation_hash", Some(hash))?;
    }
    if args.source.is_empty() || args.source.len() > 64 {
        bail!("--source must be 1-64 characters");
    }
    let mut value = json!({
        "op": "tier3_bless_measurement",
        "platform": &args.platform,
        "layer": &args.layer,
        "measurement_name": &args.measurement_name,
        "measurement": measurement,
        "effective_epoch": args.effective_epoch,
        "at": unix_epoch_seconds()?,
        "source": &args.source,
    });
    if let Some(region) = args.region.as_deref() {
        value["region"] = json!(region);
    }
    if let Some(derivation_hash) = derivation_hash {
        value["derivation_hash"] = json!(derivation_hash);
    }
    Ok(value)
}

fn tier3_measurement_feature_key(value: &Value) -> Result<String> {
    let platform = value
        .get("platform")
        .and_then(Value::as_str)
        .context("Tier-3 measurement payload missing platform")?;
    validate_tier3_platform(platform)?;
    let digest = stable_value_hash(&json!({
        "domain": "mayhem-tier3-measurement-feature-v1",
        "value": value,
    }));
    Ok(format!("tier3/measurement/{platform}/{digest}"))
}

fn tier3_derivation_store_path(home: &Path) -> PathBuf {
    home.join("tier3").join("derivations.json")
}

fn read_tier3_derivations(path: &Path) -> Result<Vec<Tier3DerivationRecord>> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let value = read_json_file(&path.to_path_buf())
        .with_context(|| format!("reading Tier-3 derivations from {}", path.display()))?;
    serde_json::from_value(value)
        .with_context(|| format!("parsing Tier-3 derivations from {}", path.display()))
}

fn write_tier3_derivations(path: &Path, records: &[Tier3DerivationRecord]) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    fs::write(path, serde_json::to_vec_pretty(records)?)
        .with_context(|| format!("writing {}", path.display()))
}

fn tier3_derivation_hash(record: &Tier3DerivationRecord) -> String {
    stable_value_hash(&json!({
        "schema_version": record.schema_version,
        "platform": record.platform,
        "region": record.region,
        "layer": record.layer,
        "measurement_name": record.measurement_name,
        "measurement": record.measurement,
        "alert_measurement": record.alert_measurement,
        "match_alert": record.match_alert,
        "derived_at": record.derived_at,
        "source_kind": record.source_kind,
        "source": record.source,
        "endorsement_sha256": record.endorsement_sha256,
    }))
}

fn validate_tier3_platform(value: &str) -> Result<()> {
    if !is_safe_key_part(value) {
        bail!("Tier-3 platform/region must be a non-empty safe label");
    }
    Ok(())
}

fn validate_tier3_measurement_name(value: &str) -> Result<()> {
    if value.is_empty()
        || value.len() > 64
        || !value
            .as_bytes()
            .iter()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b':' | b'-'))
    {
        bail!("Tier-3 measurement name must be a non-empty safe label");
    }
    Ok(())
}

fn validate_tier3_measurement_layer(value: &str) -> Result<()> {
    if !matches!(value, "vendor" | "workload") {
        bail!("Tier-3 measurement layer must be vendor or workload");
    }
    Ok(())
}

fn normalize_tier3_measurement(value: &str) -> Result<String> {
    let value = value.trim().trim_start_matches("0x").to_ascii_lowercase();
    if value.len() < 64
        || value.len() > 256
        || value.len() % 2 != 0
        || !value.as_bytes().iter().all(|byte| byte.is_ascii_hexdigit())
    {
        bail!("Tier-3 measurement must be 32-128 bytes of hex");
    }
    Ok(value)
}

async fn admin_ban_list(args: &AdminBanListArgs) -> Result<()> {
    let (rpc_url, rpc) = admin_read_rpc(&args.read).await?;
    let wanted = args.target_type.map(AdminBanTargetType::as_str);
    let mut records = Vec::new();
    let prefixes = [
        ("provider", "ban/provider/"),
        ("device", "ban/device/"),
        ("fingerprint", "ban/fingerprint/"),
        ("committer", "committer/ban/"),
    ];
    for (target_type, prefix) in prefixes {
        if wanted.is_some_and(|wanted| wanted != target_type) {
            continue;
        }
        for entry in read_prefix_entries(&rpc, prefix).await? {
            let target = entry
                .key
                .strip_prefix(prefix)
                .unwrap_or(entry.key.as_str())
                .to_owned();
            records.push(json!({
                "type": target_type,
                "target": target,
                "key": entry.key,
                "record": entry.value,
            }));
        }
    }
    records.sort_by(|left, right| {
        let left_key = left.get("key").and_then(Value::as_str).unwrap_or("");
        let right_key = right.get("key").and_then(Value::as_str).unwrap_or("");
        left_key.cmp(right_key)
    });
    let count = records.len();
    let report = json!({
        "ok": true,
        "action": "admin.ban.list",
        "rpc_url": rpc_url,
        "type": wanted,
        "count": count,
        "records": records,
    });
    if args.read.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if count == 0 {
        println!("No ban records found.");
    } else {
        println!("Ban records:");
        for record in report["records"].as_array().into_iter().flatten() {
            let status = record["record"]
                .get("status")
                .and_then(Value::as_str)
                .unwrap_or("unknown");
            println!(
                "- {} {} {}",
                record["type"].as_str().unwrap_or("unknown"),
                short_hash(record["target"].as_str().unwrap_or("")),
                status
            );
        }
    }
    Ok(())
}

async fn admin_disputes_list(args: &AdminDisputesListArgs) -> Result<()> {
    let (rpc_url, rpc) = admin_read_rpc(&args.read).await?;
    let now = args.now.unwrap_or(unix_epoch_seconds()?);
    let disputes = read_dispute_records(&rpc).await?;
    let records = disputes
        .iter()
        .filter(|record| !args.open || record.get("status").and_then(Value::as_str) == Some("open"))
        .map(|record| dispute_summary(record, now))
        .collect::<Vec<_>>();
    let report = json!({
        "ok": true,
        "rpc_url": rpc_url,
        "open_only": args.open,
        "now": now,
        "count": records.len(),
        "disputes": records,
    });
    if args.read.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_dispute_list_report(&report)?;
    }
    Ok(())
}

async fn admin_disputes_show(args: &AdminDisputesShowArgs) -> Result<()> {
    if args.dispute_id == 0 {
        bail!("dispute id must be positive");
    }
    let (rpc_url, rpc) = admin_read_rpc(&args.read).await?;
    let key = format!("disp/{}", args.dispute_id);
    let record = read_state_value(&rpc, &key)
        .await?
        .with_context(|| format!("dispute #{} not found", args.dispute_id))?;
    let now = args.now.unwrap_or(unix_epoch_seconds()?);
    let report = json!({
        "ok": true,
        "rpc_url": rpc_url,
        "key": key,
        "summary": dispute_summary(&record, now),
        "dispute": record,
    });
    if args.read.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_dispute_show_report(&report)?;
    }
    Ok(())
}

async fn admin_disputes_resolve(args: &AdminDisputesResolveArgs) -> Result<()> {
    if args.tx.submit && !args.tx.sim && !args.sim_reviewed {
        bail!(
            "real dispute resolution requires reviewing `mayhem admin disputes resolve ... --submit --sim` first, then rerun with --sim-reviewed"
        );
    }
    let value = admin_dispute_resolve_payload(args)?;
    let compact_command = serde_json::to_string(&value)?;
    let copy_paste = format!(
        "/tx --command {} --sim 1",
        shell_single_quote(&compact_command)
    );
    let mut report = json!({
        "ok": true,
        "submitted": false,
        "tx_type": "disputeResolve",
        "dispute_id": args.dispute_id,
        "outcome": format!("{:?}", args.outcome).to_ascii_lowercase(),
        "command": value,
        "copy_paste": {
            "intercom_sim": copy_paste,
        },
    });

    if args.tx.submit {
        let home = args.tx.home.clone().map(Ok).unwrap_or_else(default_home)?;
        let home = absolutize(home)?;
        let config = read_mayhem_config(&home)?;
        let rpc_url = resolve_cli_rpc_url(Some(&home), args.tx.rpc_url.as_deref())?;
        let wallet_password = args.tx.wallet_password.as_deref().unwrap_or("");
        let wallet = resolve_cli_wallet_with_keypair(
            &home,
            config.as_ref(),
            args.tx.keypair.as_deref(),
            &args.tx.peer_store_name,
            wallet_password,
        )
        .await?;
        let keypair_path = PathBuf::from(&wallet.keypair_path);
        let rpc = PeerRpcClient::new(&rpc_url)?;
        let before = read_state_value(&rpc, &format!("disp/{}", args.dispute_id)).await?;
        let submitted = submit_contract_command(
            &rpc,
            &keypair_path,
            wallet_password,
            &wallet,
            "disputeResolve",
            report["command"].clone(),
            args.tx.sim,
        )
        .await?;
        report["submitted"] = json!(true);
        report["sim"] = json!(args.tx.sim);
        report["rpc_url"] = json!(rpc_url);
        report["wallet"] = json!({
            "public_key": wallet.public_key,
        });
        report["before"] = before.unwrap_or(Value::Null);
        report["tx"] = submitted;
        if !args.tx.sim {
            let key = format!("disp/{}", args.dispute_id);
            report["resolved_state"] = wait_for_state(&rpc, &key, |value| {
                value.get("status").and_then(Value::as_str) == Some("resolved")
                    && value
                        .get("resolution_hash")
                        .and_then(Value::as_str)
                        .is_some_and(|hash| is_hex_len(hash, 64))
            })
            .await?;
        }
    }

    if args.tx.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_dispute_resolve_report(&report)?;
    }
    Ok(())
}

async fn admin_disputes_watch(args: &AdminDisputesWatchArgs) -> Result<()> {
    if args.watch && args.poll_interval_seconds == 0 {
        bail!("--poll-interval-seconds must be positive when --watch is set");
    }
    let (rpc_url, rpc) = admin_read_rpc(&args.read).await?;
    let client = reqwest::Client::new();
    let mut seen = BTreeSet::new();
    loop {
        let now = args.now.unwrap_or(unix_epoch_seconds()?);
        let alerts = scan_dispute_alerts(&rpc, now, args.aging_seconds, &mut seen).await?;
        let webhook = if let Some(url) = args.webhook_url.as_deref() {
            Some(send_dispute_alert_webhook(&client, url, &alerts).await?)
        } else {
            None
        };
        let report = json!({
            "ok": true,
            "rpc_url": rpc_url,
            "now": now,
            "aging_seconds": args.aging_seconds,
            "alert_count": alerts.len(),
            "alerts": alerts,
            "webhook": webhook,
        });
        if args.read.json {
            if args.watch {
                println!("{}", serde_json::to_string(&report)?);
            } else {
                println!("{}", serde_json::to_string_pretty(&report)?);
            }
        } else {
            print_dispute_alert_report(&report)?;
        }
        if !args.watch {
            break;
        }
        sleep(Duration::from_secs(args.poll_interval_seconds)).await;
    }
    Ok(())
}

async fn read_dispute_records(rpc: &PeerRpcClient) -> Result<Vec<Value>> {
    let mut records = Vec::new();
    if let Some(next) = read_state_value(rpc, "disp/next")
        .await?
        .and_then(|value| value.get("next").and_then(Value::as_u64))
    {
        for id in 1..next {
            if let Some(record) = read_state_value(rpc, &format!("disp/{id}")).await? {
                if record.get("type").and_then(Value::as_str) == Some("dispute") {
                    records.push(record);
                }
            }
        }
    } else {
        records = read_prefix_entries(rpc, "disp/")
            .await?
            .into_iter()
            .filter(|entry| entry.key != "disp/next")
            .filter_map(|entry| {
                (entry.value.get("type").and_then(Value::as_str) == Some("dispute"))
                    .then_some(entry.value)
            })
            .collect();
    }
    records.sort_by_key(|record| dispute_record_id(record).unwrap_or(u64::MAX));
    Ok(records)
}

fn dispute_record_id(record: &Value) -> Option<u64> {
    record.get("dispute_id").and_then(Value::as_u64)
}

fn dispute_record_age_seconds(record: &Value, now: u64) -> Option<u64> {
    record
        .get("at")
        .and_then(Value::as_u64)
        .map(|at| now.saturating_sub(at))
}

fn dispute_summary(record: &Value, now: u64) -> Value {
    json!({
        "dispute_id": dispute_record_id(record),
        "status": record.get("status").and_then(Value::as_str),
        "age_seconds": dispute_record_age_seconds(record, now),
        "rail": record.get("rail").and_then(Value::as_str),
        "opened_by": record.get("opened_by").and_then(Value::as_str),
        "provider": record.get("provider").and_then(Value::as_str),
        "counterparty": record.get("counterparty").and_then(Value::as_str),
        "enclave_id": record.get("enclave_id").and_then(Value::as_str),
        "epoch": record.get("epoch").and_then(Value::as_u64),
        "session_id": record.get("session_id").and_then(Value::as_str),
        "reason": record.get("reason").and_then(Value::as_str),
        "deposit_au": record.get("deposit_au").and_then(value_money_au).map(money_au_json),
        "evidence_hash": record.get("evidence_hash").and_then(Value::as_str),
        "dispute_hash": record.get("dispute_hash").and_then(Value::as_str),
        "resolution_hash": record.get("resolution_hash").and_then(Value::as_str),
    })
}

fn admin_dispute_resolve_payload(args: &AdminDisputesResolveArgs) -> Result<Value> {
    if args.dispute_id == 0 {
        bail!("dispute id must be positive");
    }
    if args.reason.is_some() && args.rationale_hash.is_some() {
        bail!("pass only one of --reason or --rationale-hash");
    }
    let rationale_hash = args
        .rationale_hash
        .clone()
        .or_else(|| {
            args.reason
                .as_ref()
                .map(|reason| blake3::hash(reason.as_bytes()).to_hex().to_string())
        })
        .context("--reason or --rationale-hash is required")?;
    if !is_hex_len(&rationale_hash, 64) {
        bail!("--rationale-hash must be a 32-byte BLAKE3 hex digest");
    }
    let mut payload = json!({
        "op": "dispute_resolve",
        "dispute_id": args.dispute_id,
        "outcome": args.outcome.contract_outcome(),
        "deposit_action": args.outcome.deposit_action(),
        "rationale_hash": rationale_hash.to_ascii_lowercase(),
        "at": args.at.unwrap_or(unix_epoch_seconds()?),
    });
    if args.outcome == AdminDisputeOutcome::Upheld && !args.no_slash {
        payload["slash"] = json!(true);
    }
    if let Some(beneficiary) = args.beneficiary.as_deref() {
        payload["beneficiary"] = json!(beneficiary);
    }
    Ok(payload)
}

async fn scan_dispute_alerts(
    rpc: &PeerRpcClient,
    now: u64,
    aging_seconds: u64,
    seen: &mut BTreeSet<u64>,
) -> Result<Vec<Value>> {
    let records = read_dispute_records(rpc).await?;
    let mut alerts = Vec::new();
    for record in records {
        if record.get("status").and_then(Value::as_str) != Some("open") {
            continue;
        }
        let id = dispute_record_id(&record).unwrap_or(0);
        let summary = dispute_summary(&record, now);
        if id != 0 && seen.insert(id) {
            alerts.push(json!({
                "kind": "new_dispute",
                "level": "warning",
                "message": format!("new Mayhem dispute #{id} is open"),
                "dispute": summary,
            }));
        }
        if aging_seconds > 0
            && summary
                .get("age_seconds")
                .and_then(Value::as_u64)
                .is_some_and(|age| age >= aging_seconds)
        {
            alerts.push(json!({
                "kind": "aging_dispute",
                "level": "critical",
                "message": format!("Mayhem dispute #{id} has been open for at least {aging_seconds} seconds"),
                "dispute": summary,
            }));
        }
    }
    Ok(alerts)
}

async fn send_dispute_alert_webhook(
    client: &reqwest::Client,
    url: &str,
    alerts: &[Value],
) -> Result<Value> {
    if alerts.is_empty() {
        return Ok(json!({ "sent": false, "reason": "no_alerts" }));
    }
    let response = client
        .post(url)
        .json(&json!({
            "type": "mayhem_dispute_alerts",
            "alerts": alerts,
        }))
        .send()
        .await
        .with_context(|| format!("posting dispute alerts to {url}"))?;
    let status = response.status();
    if !status.is_success() {
        bail!("dispute alert webhook {url} returned HTTP {status}");
    }
    Ok(json!({
        "sent": true,
        "url": url,
        "status": status.as_u16(),
    }))
}

