fn print_reputation_anchor_report(report: &Value) -> Result<()> {
    println!("Reputation oracle report.");
    println!("RPC: {}", report["rpc_url"].as_str().unwrap_or(""));
    println!(
        "Submitted: {}",
        report["submitted"].as_bool().unwrap_or(false)
    );
    if let Some(scans) = report["scans"].as_array() {
        for scan in scans {
            print_reputation_anchor_scan_report(scan)?;
        }
    }
    Ok(())
}

fn print_reputation_anchor_scan_report(scan: &Value) -> Result<()> {
    println!(
        "Scan epoch={} at={} providers={}",
        scan["epoch"].as_u64().unwrap_or(0),
        scan["at"].as_u64().unwrap_or(0),
        scan["providers_scanned"].as_u64().unwrap_or(0)
    );
    for anchor in scan["anchors"].as_array().into_iter().flatten() {
        println!(
            "  provider={} events={} r_bps={} raw_milli={} head={}",
            anchor["provider"].as_str().unwrap_or(""),
            anchor["event_count"].as_u64().unwrap_or(0),
            anchor["snapshot"]["r_bps"].as_u64().unwrap_or(0),
            anchor["snapshot"]["raw_milli"].as_i64().unwrap_or(0),
            anchor["events_head"].as_str().unwrap_or("")
        );
        println!(
            "    key={}",
            anchor["feature"]["key"].as_str().unwrap_or("")
        );
        println!(
            "    copy/paste={}",
            anchor["copy_paste"]["peer_rpc"].as_str().unwrap_or("")
        );
    }
    for skipped in scan["skipped"].as_array().into_iter().flatten() {
        println!(
            "  skipped provider={} reason={}",
            skipped["provider"].as_str().unwrap_or(""),
            skipped["reason"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

fn print_tnk_settlement_runner_report(report: &Value) -> Result<()> {
    println!("TNK settlement runner report.");
    println!("Epoch: {}", report["epoch"].as_u64().unwrap_or(0));
    println!("Network: {}", report["network"].as_str().unwrap_or(""));
    println!(
        "Treasury: {}",
        report["treasury_from"].as_str().unwrap_or("")
    );
    println!("Operator: {}", report["operator_to"].as_str().unwrap_or(""));
    if !report["already_settled"].is_null() {
        println!("Already settled: true");
        let transfers = report["already_settled"]["msb_transfers"]
            .as_array()
            .map(Vec::len)
            .unwrap_or(0);
        if transfers > 0 {
            println!("Confirmed MSB transfers: {transfers}");
        }
        return Ok(());
    }
    println!("Already settled: false");
    if report["nothing_to_settle"].as_bool() == Some(true) {
        println!("Nothing to settle: true (no whole-minor-unit fiat outputs)");
    }
    if let Some(settlement) = report.get("settlement").filter(|value| !value.is_null()) {
        println!(
            "Gross: {} au_usd",
            settlement["gross_au"].as_str().unwrap_or("0")
        );
        println!(
            "Providers: {} / provider_au: {} / operator_fee_au: {}",
            settlement["provider_count"].as_u64().unwrap_or(0),
            settlement["provider_au"].as_str().unwrap_or("0"),
            settlement["operator_fee_au"].as_str().unwrap_or("0")
        );
        println!("TNK e18: {}", settlement["tnk_e18"].as_str().unwrap_or(""));
        println!(
            "Transfer root: {}",
            settlement["transfer_root"].as_str().unwrap_or("")
        );
        if let Some(transfers) = settlement["msb_transfers"].as_array() {
            if transfers.is_empty() {
                println!("Confirmed MSB transfers: pending (dry plan only)");
            } else {
                println!("Confirmed MSB transfers: {}", transfers.len());
                for (index, transfer) in transfers.iter().enumerate() {
                    if let Some(hash) = transfer.get("tx_hash").and_then(Value::as_str) {
                        println!("  {}: {}", index + 1, hash);
                    }
                }
            }
        } else {
            println!("Confirmed MSB transfers: pending (dry plan only)");
        }
    }
    println!(
        "Skipped providers: {}",
        report["skipped_providers"]
            .as_array()
            .map(Vec::len)
            .unwrap_or(0)
    );
    if let Some(feature) = report.get("feature").filter(|value| !value.is_null()) {
        println!("Feature key: {}", feature["key"].as_str().unwrap_or(""));
    }
    if report["submitted"].as_bool() == Some(true) {
        println!("Submitted: true");
    } else if report["sim"].as_bool() == Some(true) {
        println!("Submitted: false (--sim dry-run)");
    } else {
        println!("Submitted: false");
    }
    println!("Copy/paste full settlement command:");
    println!(
        "{}",
        report["copy_paste"]["submit_settlement"]
            .as_str()
            .unwrap_or("")
    );
    println!("Copy/paste Pear MSB transfer helper commands:");
    for command in report["copy_paste"]["msb_transfer_helpers"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
    {
        println!("{command}");
    }
    if let Some(command) = report["copy_paste"]["feature_rpc"].as_str() {
        println!("Copy/paste feature RPC command:");
        println!("{command}");
    }
    Ok(())
}

