async fn deposit_command(command: DepositCommands) -> Result<()> {
    match command {
        DepositCommands::Tnk(args) => pay_tnk(args).await,
        DepositCommands::Stripe(args) => pay(PayRail::Stripe, args).await,
        DepositCommands::Tap(args) => deposit_tap(args).await,
        DepositCommands::Status(args) => deposit_status(args).await,
    }
}

fn tap_account_binding_message(
    user: &str,
    ethereum_address: &str,
    chain_id: u64,
    pool_address: &str,
) -> String {
    format!(
        "mayhem-tap-account-bind-v1{{\"chain_id\":{chain_id},\"ethereum_address\":\"{}\",\"pool_address\":\"{}\",\"user\":\"{}\"}}",
        ethereum_address.to_ascii_lowercase(),
        pool_address.to_ascii_lowercase(),
        user.to_ascii_lowercase(),
    )
}

fn is_eth_address(value: &str) -> bool {
    value.len() == 42
        && value.starts_with("0x")
        && value[2..].as_bytes().iter().all(u8::is_ascii_hexdigit)
}

fn tap_account_binding_state_key(user: &str, chain_id: u64, pool_address: &str) -> String {
    format!(
        "tap/account/{chain_id}/{}/{}",
        pool_address.to_ascii_lowercase(),
        user.to_ascii_lowercase()
    )
}

fn tap_account_address_state_key(
    ethereum_address: &str,
    chain_id: u64,
    pool_address: &str,
) -> String {
    format!(
        "tap/account-by-address/{chain_id}/{}/{}",
        pool_address.to_ascii_lowercase(),
        ethereum_address.to_ascii_lowercase()
    )
}

fn tap_account_binding_identity_matches(
    record: Option<&Value>,
    user: &str,
    ethereum_address: &str,
) -> bool {
    record.is_some_and(|record| {
        record.get("status").and_then(Value::as_str) == Some("active")
            && record.get("user").and_then(Value::as_str) == Some(user)
            && record.get("ethereum_address").and_then(Value::as_str) == Some(ethereum_address)
    })
}

fn tap_account_binding_is_complete(
    record: Option<&Value>,
    user: &str,
    ethereum_address: &str,
    feature_key: &str,
) -> bool {
    tap_account_binding_identity_matches(record, user, ethereum_address)
        && record
            .and_then(|record| record.get("bound_at"))
            .and_then(Value::as_str)
            == Some(feature_key)
}

async fn ensure_tap_account_binding(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    ethereum_address: &str,
    chain_id: u64,
    pool_address: &str,
    submit: bool,
) -> Result<Value> {
    let user = wallet.public_key.to_ascii_lowercase();
    let ethereum_address = ethereum_address.to_ascii_lowercase();
    let pool_address = pool_address.to_ascii_lowercase();
    if !is_hex_len(&user, 64) {
        bail!("wallet public key is not a 32-byte hex Mayhem identity");
    }
    if !is_eth_address(&ethereum_address) {
        bail!("wallet Ethereum account is invalid");
    }
    if !is_eth_address(&pool_address) {
        bail!("TAP pool address is invalid");
    }
    let message = tap_account_binding_message(&user, &ethereum_address, chain_id, &pool_address);
    let feature_key = format!(
        "tap_account/{}/{}",
        wallet.public_key.to_ascii_lowercase(),
        blake3::hash(message.as_bytes()).to_hex()
    );
    let binding_key = tap_account_binding_state_key(&user, chain_id, &pool_address);
    let address_key = tap_account_address_state_key(&ethereum_address, chain_id, &pool_address);
    let binding = read_state_value(rpc, &binding_key).await?;
    let reverse = read_state_value(rpc, &address_key).await?;
    let binding_identity_matches =
        tap_account_binding_identity_matches(binding.as_ref(), &user, &ethereum_address);
    let reverse_identity_matches =
        tap_account_binding_identity_matches(reverse.as_ref(), &user, &ethereum_address);
    if binding.is_some() && !binding_identity_matches {
        bail!("Mayhem wallet is already bound to a different TAP account for this pool");
    }
    if reverse.is_some() && !reverse_identity_matches {
        bail!("TAP account is already bound to a different Mayhem wallet for this pool");
    }
    let was_existing = binding_identity_matches && reverse_identity_matches;
    let binding_complete =
        tap_account_binding_is_complete(binding.as_ref(), &user, &ethereum_address, &feature_key)
            && tap_account_binding_is_complete(
                reverse.as_ref(),
                &user,
                &ethereum_address,
                &feature_key,
            );
    if binding_complete {
        return Ok(json!({
            "ok": true,
            "status": "active",
            "existing": true,
            "submitted": false,
            "user": user,
            "ethereum_address": ethereum_address,
            "chain_id": chain_id,
            "pool_address": pool_address,
            "state_key": binding_key,
        }));
    }

    let user_sig = sign_message(keypair_path, password, &message).await?;
    let ethereum = sign_ethereum_message(keypair_path, password, &message).await?;
    if !ethereum.address.eq_ignore_ascii_case(&ethereum_address) {
        bail!(
            "Ethereum binding signature came from {}, expected {}",
            ethereum.address,
            ethereum_address
        );
    }
    let value = json!({
        "op": "tap_account_bind",
        "user": user,
        "ethereum_address": ethereum_address,
        "chain_id": chain_id,
        "pool_address": pool_address,
        "user_sig": user_sig,
        "ethereum_sig": ethereum.signature,
    });
    let feature = json!({
        "feature": "mayhem",
        "key": feature_key,
        "value": value,
    });
    if !submit {
        return Ok(json!({
            "ok": true,
            "status": "ready",
            "existing": was_existing,
            "reasserted": false,
            "submitted": false,
            "user": wallet.public_key.to_ascii_lowercase(),
            "ethereum_address": ethereum_address,
            "chain_id": chain_id,
            "pool_address": pool_address,
            "state_key": binding_key,
        }));
    }

    let response = rpc
        .submit_feature(&feature)
        .await
        .context("submitting free dual-signed TAP account binding")?;
    if response.get("ok").and_then(Value::as_bool) != Some(true) {
        bail!("TAP account binding was not accepted: {response}");
    }
    let mut applied = None;
    for _ in 0..200 {
        let current = read_state_value(rpc, &binding_key).await?;
        if current.as_ref().is_some_and(|record| {
            record.get("status").and_then(Value::as_str) == Some("active")
                && record.get("user").and_then(Value::as_str)
                    == Some(wallet.public_key.to_ascii_lowercase().as_str())
                && record.get("ethereum_address").and_then(Value::as_str)
                    == Some(ethereum_address.as_str())
                && record.get("bound_at").and_then(Value::as_str) == Some(feature_key.as_str())
        }) {
            applied = current;
            break;
        }
        sleep(Duration::from_millis(100)).await;
    }
    let state = applied.context("TAP account binding was accepted but did not become visible")?;
    Ok(json!({
        "ok": true,
        "status": "active",
        "existing": was_existing,
        "reasserted": was_existing,
        "submitted": true,
        "user": wallet.public_key.to_ascii_lowercase(),
        "ethereum_address": ethereum_address,
        "chain_id": chain_id,
        "pool_address": pool_address,
        "state_key": binding_key,
        "result": response,
        "state": state,
    }))
}

async fn deposit_tap(args: DepositTapArgs) -> Result<()> {
    match (&args.amount_tap, &args.amount_wei) {
        (Some(_), Some(_)) => bail!("pass only one of --amount-tap or --amount-wei"),
        (None, None) if !args.bind_only => bail!("pass --amount-tap or --amount-wei"),
        _ => {}
    }

    let home = args
        .wallet
        .home
        .clone()
        .map(Ok)
        .unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let peer_rpc_url = resolve_cli_rpc_url(Some(&home), args.peer_rpc_url.as_deref())?;
    if args.confirm {
        require_secure_fund_rpc_url(&peer_rpc_url)?;
        if let Some(eth_rpc) = args.eth_rpc.as_deref() {
            require_secure_fund_rpc_url(eth_rpc)?;
        }
    }
    let peer_rpc = PeerRpcClient::new(&peer_rpc_url)?;
    let payment_state = read_canonical_payment_state(&peer_rpc).await?;
    let tap = payment_state.payments.tap.clone();
    let tap_rate = payment_state.tap_rate.clone();
    let tap_rate_age = require_fresh_payment_rate(
        payment_state.observed_at,
        tap_rate.ts,
        payment_state.rate_staleness_seconds,
        "TAP/USD rate",
    )?;
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    let password = args.wallet.wallet_password.clone().unwrap_or_default();
    let wallet = inspect_wallet(&keypair_path, &password)
        .await
        .with_context(|| format!("reading wallet {}", keypair_path.display()))?;
    let rules_consent = if args.confirm {
        Some(
            ensure_current_rules_consent(&peer_rpc, &keypair_path, &password, &wallet, false)
                .await?,
        )
    } else {
        None
    };
    let eth_key = ethereum_wallet_key(&keypair_path, &password)
        .await
        .with_context(|| {
            format!(
                "reading Ethereum account from wallet {}",
                keypair_path.display()
            )
        })?;
    if wallet.ethereum_address.as_deref() != Some(eth_key.address.as_str()) {
        bail!(
            "wallet Ethereum address {} does not match signing key {}",
            wallet.ethereum_address.as_deref().unwrap_or("<missing>"),
            eth_key.address
        );
    }

    let mut script_args = vec![
        "deposit".to_owned(),
        "--local-wallet".to_owned(),
        "--json".to_owned(),
    ];
    if let Some(amount_tap) = &args.amount_tap {
        script_args.extend(["--amount-tap".to_owned(), amount_tap.clone()]);
    }
    if let Some(amount_wei) = &args.amount_wei {
        script_args.extend(["--amount-wei".to_owned(), amount_wei.clone()]);
    }
    if args.bind_only {
        script_args.extend(["--amount-wei".to_owned(), "1".to_owned()]);
    }
    push_tap_contract_args(&mut script_args, &tap);
    if let Some(eth_rpc) = &args.eth_rpc {
        script_args.extend(["--eth-rpc".to_owned(), eth_rpc.clone()]);
    }
    let preflight = run_contracts_script_json_with_env(
        "contracts/scripts/tap-calldata-builder.mjs",
        script_args.clone(),
        [(
            "MAYHEM_TAP_WALLET_PRIVATE_KEY".to_owned(),
            eth_key.private_key.clone(),
        )],
    )
    .await?;
    let resolved_from = preflight
        .get("from")
        .and_then(Value::as_str)
        .context("TAP deposit preflight missing sender address")?;
    if !resolved_from.eq_ignore_ascii_case(&eth_key.address) {
        bail!(
            "TAP deposit preflight sender {} does not match wallet {}",
            resolved_from,
            eth_key.address
        );
    }
    let pool_address = preflight
        .get("pool")
        .and_then(Value::as_str)
        .context("TAP deposit preflight missing pool address")?;
    let chain_id = preflight
        .get("chain_id")
        .and_then(Value::as_u64)
        .context("TAP deposit preflight missing chain id")?;
    let token_address = preflight
        .get("token")
        .and_then(Value::as_str)
        .context("TAP deposit preflight missing token address")?;
    ensure!(
        token_address.eq_ignore_ascii_case(&tap.token_address)
            && pool_address.eq_ignore_ascii_case(&tap.pool_address)
            && chain_id == tap.chain_id,
        "TAP deposit preflight did not preserve canonical payments/current addresses"
    );
    let binding = ensure_tap_account_binding(
        &peer_rpc,
        &keypair_path,
        &password,
        &wallet,
        &eth_key.address,
        chain_id,
        pool_address,
        args.confirm,
    )
    .await?;

    if args.bind_only {
        let report = json!({
            "ok": true,
            "bind_only": true,
            "submitted": binding.get("submitted").and_then(Value::as_bool).unwrap_or(false),
            "payment_config": {
                "source": "payments/current",
                "peer_rpc_url": peer_rpc_url,
                "chain_id": tap.chain_id,
                "token_address": tap.token_address,
                "pool_address": tap.pool_address,
            },
            "rules_consent": rules_consent,
            "tap_account_binding": binding,
        });
        if args.json {
            println!("{}", serde_json::to_string_pretty(&report)?);
        } else {
            println!(
                "TAP account binding: {}",
                report["tap_account_binding"]["status"]
                    .as_str()
                    .unwrap_or("unknown")
            );
            println!(
                "Mayhem wallet: {}",
                report["tap_account_binding"]["user"].as_str().unwrap_or("")
            );
            println!(
                "Ethereum account: {}",
                report["tap_account_binding"]["ethereum_address"]
                    .as_str()
                    .unwrap_or("")
            );
        }
        return Ok(());
    }

    let mut report = if args.confirm {
        script_args.push("--confirm".to_owned());
        run_contracts_script_json_with_env(
            "contracts/scripts/tap-calldata-builder.mjs",
            script_args,
            [(
                "MAYHEM_TAP_WALLET_PRIVATE_KEY".to_owned(),
                eth_key.private_key,
            )],
        )
        .await?
    } else {
        preflight
    };
    report["tap_account_binding"] = binding;
    if let Some(consent) = rules_consent {
        report["rules_consent"] = serde_json::to_value(consent)?;
    }
    let amount_wei = report
        .get("amount_wei")
        .and_then(Value::as_str)
        .context("TAP deposit report missing amount_wei")?
        .parse::<u128>()
        .context("TAP deposit amount_wei exceeds u128")?;
    let quoted_credit_au = token_e18_to_au_floor(amount_wei, tap_rate.tap_usd_au)?;
    report["payment_config"] = json!({
        "source": "payments/current",
        "peer_rpc_url": peer_rpc_url,
        "chain_id": tap.chain_id,
        "token_address": tap.token_address,
        "pool_address": tap.pool_address,
    });
    report["rate"] = json!({
        "source_key": "tap/rate/latest",
        "denom": tap_rate.denom,
        "tap_usd_au": money_au_json(tap_rate.tap_usd_au),
        "usd": au_to_usd_decimal(tap_rate.tap_usd_au),
        "source": tap_rate.source,
        "ts": tap_rate.ts,
        "age_seconds": tap_rate_age,
    });
    report["quoted_credit_au"] = money_au_json(quoted_credit_au);

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_tap_deposit_report(&report)?;
    }
    Ok(())
}

async fn deposit_status(args: DepositStatusArgs) -> Result<()> {
    if args.poll_interval_ms == 0 {
        bail!("--poll-interval-ms must be positive");
    }
    if args.wait && args.target_au.is_none() {
        bail!("--wait requires --target-au");
    }
    if args.log_index.is_some() && args.eth_tx_hash.is_none() {
        bail!("--log-index requires --eth-tx-hash");
    }

    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let who = if let Some(who) = args.who.clone() {
        who
    } else {
        resolve_cli_wallet(
            &home,
            config.as_ref(),
            &args.peer_store_name,
            args.wallet_password.as_deref().unwrap_or(""),
        )
        .await?
        .public_key
    };
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let rail = deposit_status_rail(&args);
    let rail_name = rail.as_str();
    let requested_who = who;
    let mut before_balance = read_balance_record(&rpc, &requested_who, rail_name).await?;
    let balance_who = if rail == GatewayLedgerRail::Tap {
        canonical_tap_balance_who(&requested_who, &before_balance)
    } else {
        requested_who.clone()
    };
    if balance_who != requested_who {
        before_balance = read_balance_record(&rpc, &balance_who, rail_name).await?;
    }
    let before_au = before_balance
        .get("au")
        .and_then(value_money_au)
        .context("normalized balance record missing au")?;

    let credit_wait = if args.wait {
        Some(
            wait_for_credit(
                &rpc,
                &balance_who,
                rail_name,
                before_au,
                args.target_au.expect("--wait checked target_au"),
                Duration::from_secs(args.timeout_seconds),
                Duration::from_millis(args.poll_interval_ms),
            )
            .await?,
        )
    } else {
        None
    };
    let balance = read_balance_record(&rpc, &balance_who, rail_name).await?;
    let current_au = balance
        .get("au")
        .and_then(value_money_au)
        .context("normalized balance record missing au")?;
    let pending_tnk = match args.memo_hash.as_deref() {
        Some(memo_hash) => read_state_value(&rpc, &format!("dep/pending/{memo_hash}")).await?,
        None => None,
    };
    let (tap_log_index, tap_seen) = match args.eth_tx_hash.as_deref() {
        Some(hash) => {
            let payments: CanonicalPayments = serde_json::from_value(
                read_state_value(&rpc, "payments/current")
                    .await?
                    .context("payments/current is required to identify a TAP deposit")?,
            )
            .context("payments/current has an invalid schema")?;
            read_tap_deposit_confirmation(
                &rpc,
                payments.tap.chain_id,
                &payments.tap.pool_address,
                hash,
                args.log_index,
                &balance_who,
            )
            .await?
        }
        None => (None, None),
    };
    let status = classify_deposit_status(
        current_au,
        args.target_au,
        pending_tnk.as_ref(),
        tap_seen.as_ref(),
        args.eth_tx_hash.is_some(),
    );
    let report = json!({
        "ok": status != "unknown",
        "status": status,
        "rpc_url": rpc_url,
        "who": balance_who,
        "requested_who": (requested_who != balance_who).then_some(requested_who),
        "rail": rail_name,
        "target_au": args.target_au.map(money_au_json),
        "balance": balance,
        "credit": credit_wait.as_ref().map(|status| json!({
            "credited": status.credited,
            "before_au": money_au_json(status.before_au),
            "current_au": money_au_json(status.current_au),
            "target_au": money_au_json(status.target_au),
            "waited_ms": status.waited_ms,
        })),
        "tnk": {
            "memo_hash": args.memo_hash,
            "pending": pending_tnk,
        },
        "tap": {
            "eth_tx_hash": args.eth_tx_hash.as_ref().map(|value| value.to_ascii_lowercase()),
            "log_index": tap_log_index,
            "confirmed_event": tap_seen,
        },
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_deposit_status_report(&report)?;
    }

    if let Some(wait) = credit_wait.as_ref().filter(|status| !status.credited) {
        bail!(
            "timed out waiting for target balance {} au_usd; current balance {} au_usd",
            wait.target_au,
            wait.current_au
        );
    }
    Ok(())
}

fn canonical_tap_balance_who(requested_who: &str, balance: &Value) -> String {
    balance
        .get("tap_account_bound_to")
        .and_then(Value::as_str)
        .filter(|value| is_hex_len(value, 64))
        .unwrap_or(requested_who)
        .to_owned()
}

fn deposit_status_rail(args: &DepositStatusArgs) -> GatewayLedgerRail {
    if let Some(rail) = args.rail {
        return rail;
    }
    if args.eth_tx_hash.is_some() {
        GatewayLedgerRail::Tap
    } else if args.memo_hash.is_some() {
        GatewayLedgerRail::Tnk
    } else {
        GatewayLedgerRail::Fiat
    }
}

async fn withdraw(args: WithdrawArgs) -> Result<()> {
    let home = args
        .wallet
        .home
        .clone()
        .map(Ok)
        .unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let peer_rpc_url = resolve_cli_rpc_url(Some(&home), args.peer_rpc_url.as_deref())?;
    if args.confirm {
        require_secure_fund_rpc_url(&peer_rpc_url)?;
        if let Some(eth_rpc) = args.eth_rpc.as_deref() {
            require_secure_fund_rpc_url(eth_rpc)?;
        }
    }
    let peer_rpc = PeerRpcClient::new(&peer_rpc_url)?;
    let payment_state = read_canonical_payment_state(&peer_rpc).await?;
    let tap = payment_state.payments.tap.clone();
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    let password = args.wallet.wallet_password.clone().unwrap_or_default();
    let eth_key = ethereum_wallet_key(&keypair_path, &password)
        .await
        .with_context(|| {
            format!(
                "reading Ethereum account from wallet {}",
                keypair_path.display()
            )
        })?;
    let account = args
        .account
        .clone()
        .unwrap_or_else(|| eth_key.address.clone());
    if !account.eq_ignore_ascii_case(&eth_key.address) {
        bail!(
            "local Ethereum wallet {} does not match claim account {}",
            eth_key.address,
            account
        );
    }

    let proof_report = resolve_withdraw_proof(&args, &account, &tap.pool_address).await?;
    if proof_report.get("claimable").and_then(Value::as_bool) == Some(false)
        && !args.allow_not_claimable
    {
        let reason = proof_report
            .get("reason")
            .and_then(Value::as_str)
            .unwrap_or("claim is not currently claimable");
        bail!("{reason}; pass --allow-not-claimable to attempt the simulation anyway");
    }
    let cumulative = proof_report
        .get("cumulative_wei")
        .or_else(|| proof_report.get("cumulative"))
        .and_then(Value::as_str)
        .or(args.cumulative_wei.as_deref())
        .context("withdrawal proof is missing cumulative wei")?
        .to_owned();
    let proof = proof_report
        .get("proof")
        .cloned()
        .or_else(|| {
            args.proof
                .as_ref()
                .map(|proof| Value::String(proof.clone()))
        })
        .context("withdrawal proof is missing proof")?;

    let mut script_args = vec![
        "claim".to_owned(),
        "--account".to_owned(),
        account.clone(),
        "--cumulative-wei".to_owned(),
        cumulative,
        "--proof".to_owned(),
        proof_to_script_arg(&proof)?,
        "--json".to_owned(),
    ];
    push_tap_contract_args(&mut script_args, &tap);
    script_args.push("--local-wallet".to_owned());
    if args.confirm {
        script_args.push("--confirm".to_owned());
    }
    let mut script_env = vec![(
        "MAYHEM_TAP_WALLET_PRIVATE_KEY".to_owned(),
        eth_key.private_key,
    )];
    if let Some(eth_rpc) = &args.eth_rpc {
        script_env.push(("MAYHEM_TAP_ETH_RPC".to_owned(), eth_rpc.clone()));
    }
    let claim = run_contracts_script_json_with_env(
        "contracts/scripts/tap-calldata-builder.mjs",
        script_args,
        script_env,
    )
    .await?;
    let report = json!({
        "ok": true,
        "rail": "tap",
        "custody": "local_wallet",
        "server_signs": false,
        "account": account,
        "payment_config": {
            "source": "payments/current",
            "peer_rpc_url": peer_rpc_url,
            "chain_id": tap.chain_id,
            "token_address": tap.token_address,
            "pool_address": tap.pool_address,
        },
        "submitted": claim.get("submitted").and_then(Value::as_bool).unwrap_or(false),
        "proof": proof_report,
        "claim": claim,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_withdraw_report(&report)?;
    }
    Ok(())
}

async fn dispute(args: DisputeArgs) -> Result<()> {
    let value = dispute_payload(&args)?;
    run_participant_command(&args.tx, "dispute", value).await
}

async fn dispute_expire(args: DisputeExpireArgs) -> Result<()> {
    let value = dispute_expire_payload(&args)?;
    run_participant_command(&args.tx, "disputeExpire", value).await
}

async fn fraud_proof_submit(args: FraudProofSubmitArgs) -> Result<()> {
    let value = fraud_proof_payload(&args)?;
    run_participant_command(&args.tx, "fraudProof", value).await
}

#[derive(Debug, Clone, Serialize)]
struct FraudProofChallengeCandidate {
    epoch: u64,
    proof_epoch: u64,
    commit_hash: Option<String>,
    submitted_by: Option<String>,
    receipt_id: String,
    session_id: Option<String>,
    provider: Option<String>,
    #[serde(with = "mayhem_proto::decimal_u128")]
    actual_au: MoneyAu,
    #[serde(with = "mayhem_proto::decimal_u128")]
    claimed_au: MoneyAu,
    #[serde(with = "mayhem_proto::decimal_u128")]
    claimed_au_owed_cum: MoneyAu,
    #[serde(with = "mayhem_proto::decimal_u128")]
    previous_au_owed_cum: MoneyAu,
    committed_use_root: String,
    proof_hash: String,
    proof_bytes: usize,
    command: Value,
    copy_paste: String,
}

async fn fraud_proof_challenge(args: FraudProofChallengeArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }
    if args.watch && args.poll_interval_seconds == 0 {
        bail!("--poll-interval-seconds must be positive when --watch is set");
    }
    if args.max_challenges == Some(0) {
        bail!("--max-challenges must be positive when set");
    }

    let home = args.tx.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.tx.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let gateway_root = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(args.timeout_seconds))
        .build()?;
    let mut seen_submitted = BTreeSet::new();
    let mut seen_dispute_alerts = BTreeSet::new();
    let mut scans = Vec::new();

    loop {
        let at = args.at.unwrap_or(unix_epoch_seconds()?);
        let commits = read_epoch_commits_for_challenger(&rpc, args.epoch).await?;
        let receipts = read_receipts_for_challenger(&args, &client, &gateway_root).await?;
        let mut candidates = fraud_proof_candidates_from_values(
            &commits,
            &receipts,
            args.proof_epoch,
            at,
            args.max_challenges,
        )?;
        if args.tx.submit {
            candidates.retain(|candidate| seen_submitted.insert(candidate.proof_hash.clone()));
        }
        let submissions = submit_fraud_proof_candidates(&args.tx, &rpc_url, &candidates).await?;
        let dispute_alerts = scan_dispute_alerts(
            &rpc,
            at,
            args.dispute_aging_seconds,
            &mut seen_dispute_alerts,
        )
        .await?;
        let dispute_alert_webhook = if let Some(url) = args.dispute_alert_webhook_url.as_deref() {
            Some(send_dispute_alert_webhook(&client, url, &dispute_alerts).await?)
        } else {
            None
        };
        let scan = json!({
            "rpc_url": rpc_url.clone(),
            "gateway_url": if args.receipts_file.is_none() { Some(gateway_root.clone()) } else { None },
            "receipts_file": args
                .receipts_file
                .as_ref()
                .map(|path| path.display().to_string()),
            "epoch": args.epoch,
            "proof_epoch": args.proof_epoch,
            "commits_scanned": commits.len(),
            "receipts_scanned": receipts.len(),
            "candidates": candidates,
            "submitted": submissions,
            "dispute_alerts": dispute_alerts,
            "dispute_alert_webhook": dispute_alert_webhook,
        });
        let should_stop = !args.watch
            || scan
                .get("candidates")
                .and_then(Value::as_array)
                .is_some_and(|candidates| {
                    args.max_challenges
                        .is_some_and(|max| candidates.len() >= max)
                });
        scans.push(scan);
        if args.watch && !args.tx.json {
            if let Some(last) = scans.last() {
                print_dispute_alerts_inline(last)?;
            }
        }
        if should_stop {
            break;
        }
        sleep(Duration::from_secs(args.poll_interval_seconds)).await;
    }

    let report = json!({
        "ok": true,
        "watch": args.watch,
        "scans": scans,
    });
    if args.tx.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_fraud_proof_challenge_report(&report)?;
    }
    Ok(())
}

fn dispute_payload(args: &DisputeArgs) -> Result<Value> {
    let evidence = optional_json_arg_or_file(
        args.evidence_json.as_deref(),
        args.evidence_file.as_ref(),
        "dispute evidence",
    )?;
    let evidence_hash = args
        .evidence_hash
        .clone()
        .or_else(|| evidence.as_ref().map(stable_value_hash));
    if let Some(hash) = evidence_hash.as_deref() {
        if !is_hex_len(hash, 64) {
            bail!("--evidence-hash must be a 32-byte BLAKE3 hex digest");
        }
    }
    let mut payload = json!({
        "op": "dispute",
        "session_id": &args.session_id,
        "rail": args.rail.as_str(),
        "reason": &args.reason,
        "at": args.at.unwrap_or(unix_epoch_seconds()?),
    });
    if let Some(provider) = &args.provider {
        payload["provider"] = json!(provider);
    }
    if let Some(counterparty) = &args.counterparty {
        payload["counterparty"] = json!(counterparty);
    }
    if let Some(enclave_id) = &args.enclave_id {
        payload["enclave_id"] = json!(enclave_id);
    }
    if let Some(epoch) = args.epoch {
        payload["epoch"] = json!(epoch);
    }
    if let Some(evidence_hash) = evidence_hash {
        payload["evidence_hash"] = json!(evidence_hash.to_ascii_lowercase());
    }
    if let Some(evidence) = evidence {
        payload["evidence"] = evidence;
    }
    Ok(payload)
}

fn dispute_expire_payload(args: &DisputeExpireArgs) -> Result<Value> {
    if args.dispute_id == 0 {
        bail!("--dispute-id must be positive");
    }
    Ok(json!({
        "op": "dispute_expire",
        "dispute_id": args.dispute_id,
        "at": args.at.unwrap_or(unix_epoch_seconds()?),
    }))
}

fn fraud_proof_payload(args: &FraudProofSubmitArgs) -> Result<Value> {
    if args.epoch == 0 {
        bail!("--epoch must be positive");
    }
    if args.proof_epoch == 0 {
        bail!("--proof-epoch must be positive");
    }
    if args.reason != "over_credit" {
        bail!("contract currently supports only --reason over_credit");
    }
    let receipt = json_arg_or_file_object(
        args.receipt_json.as_deref(),
        args.receipt_file.as_ref(),
        None,
        "fraud proof receipt",
    )?;
    let mut payload = json!({
        "op": "fraud_proof",
        "epoch": args.epoch,
        "proof_epoch": args.proof_epoch,
        "at": args.at.unwrap_or(unix_epoch_seconds()?),
        "reason": &args.reason,
        "receipt": receipt,
        "claimed_au_owed_cum": money_au_json(args.claimed_au_owed_cum),
    });
    if let Some(previous) = args.previous_au_owed_cum {
        payload["previous_au_owed_cum"] = money_au_json(previous);
    }
    Ok(payload)
}

async fn read_epoch_commits_for_challenger(
    rpc: &PeerRpcClient,
    epoch: Option<u64>,
) -> Result<Vec<Value>> {
    if let Some(epoch) = epoch {
        let key = format!("epoch/commit/{epoch}");
        return Ok(read_state_value(rpc, &key)
            .await?
            .into_iter()
            .collect::<Vec<_>>());
    }
    Ok(read_prefix_entries(rpc, "epoch/commit/")
        .await?
        .into_iter()
        .map(|entry| entry.value)
        .collect())
}

async fn read_receipts_for_challenger(
    args: &FraudProofChallengeArgs,
    client: &reqwest::Client,
    gateway_root: &str,
) -> Result<Vec<Value>> {
    if let Some(path) = args.receipts_file.as_deref() {
        return read_json_array(path, "receipts");
    }
    let value = fetch_gateway_json(
        client,
        &format!("{}/mayhem/receipts", gateway_root.trim_end_matches('/')),
    )
    .await?;
    Ok(value
        .get("data")
        .and_then(Value::as_array)
        .cloned()
        .context("gateway /mayhem/receipts response did not include data[]")?)
}

fn fraud_proof_candidates_from_values(
    commits: &[Value],
    receipts: &[Value],
    proof_epoch: Option<u64>,
    at: u64,
    max_challenges: Option<usize>,
) -> Result<Vec<FraudProofChallengeCandidate>> {
    let default_proof_epoch = proof_epoch
        .or_else(|| commits.iter().filter_map(commit_epoch).max())
        .unwrap_or(1);
    let mut candidates = Vec::new();

    for commit in commits {
        let Some(epoch) = commit_epoch(commit) else {
            continue;
        };
        let effective_proof_epoch = proof_epoch.unwrap_or(default_proof_epoch);
        if !commit_is_challengeable_over_credit(commit, effective_proof_epoch) {
            continue;
        }
        let Some(claimed_au) = commit
            .get("totals")
            .and_then(|totals| totals.get("use_au"))
            .and_then(value_money_au)
        else {
            continue;
        };
        let Some(committed_use_root) = commit
            .get("roots")
            .and_then(|roots| roots.get("use"))
            .and_then(Value::as_str)
            .map(str::to_owned)
        else {
            continue;
        };

        for receipt in receipts {
            let Some(envelope) = normalized_receipt_envelope(receipt) else {
                continue;
            };
            let Some(body) = envelope.get("body").and_then(Value::as_object) else {
                continue;
            };
            let actual_cum = body
                .get("au_owed_cum")
                .and_then(value_money_au)
                .unwrap_or(0);
            for previous_au in previous_receipt_amounts(receipts, receipt) {
                if previous_au > actual_cum {
                    continue;
                }
                let claimed_au_owed_cum = previous_au.saturating_add(claimed_au);
                if claimed_au_owed_cum <= actual_cum {
                    continue;
                }
                let claimed_envelope =
                    receipt_envelope_with_au_owed_cum(&envelope, claimed_au_owed_cum);
                if usage_leaf_hash_from_envelope(&claimed_envelope)? != committed_use_root {
                    continue;
                }
                let command = json!({
                    "op": "fraud_proof",
                    "epoch": epoch,
                    "proof_epoch": effective_proof_epoch,
                    "at": at,
                    "reason": "over_credit",
                    "receipt": envelope.clone(),
                    "claimed_au_owed_cum": money_au_json(claimed_au_owed_cum),
                    "previous_au_owed_cum": money_au_json(previous_au),
                });
                let proof_hash = fraud_proof_hash_from_command(&command)?;
                let proof_bytes = stable_json_len(&command)?;
                let compact_command = serde_json::to_string(&command)?;
                candidates.push(FraudProofChallengeCandidate {
                    epoch,
                    proof_epoch: effective_proof_epoch,
                    commit_hash: commit
                        .get("commit_hash")
                        .and_then(Value::as_str)
                        .map(str::to_owned),
                    submitted_by: commit
                        .get("submitted_by")
                        .and_then(Value::as_str)
                        .map(str::to_owned),
                    receipt_id: receipt_id(receipt),
                    session_id: body
                        .get("session_id")
                        .and_then(Value::as_str)
                        .map(str::to_owned),
                    provider: body
                        .get("provider")
                        .and_then(Value::as_str)
                        .map(str::to_owned),
                    actual_au: actual_cum - previous_au,
                    claimed_au,
                    claimed_au_owed_cum,
                    previous_au_owed_cum: previous_au,
                    committed_use_root: committed_use_root.clone(),
                    proof_hash,
                    proof_bytes,
                    command,
                    copy_paste: format!(
                        "/tx --command {} --sim 1",
                        shell_single_quote(&compact_command)
                    ),
                });
                if max_challenges.is_some_and(|max| candidates.len() >= max) {
                    return Ok(candidates);
                }
            }
        }
    }
    Ok(candidates)
}

fn commit_epoch(commit: &Value) -> Option<u64> {
    commit.get("epoch").and_then(Value::as_u64)
}

fn commit_is_challengeable_over_credit(commit: &Value, proof_epoch: u64) -> bool {
    commit.get("status").and_then(Value::as_str) == Some("provisional")
        && commit
            .get("totals")
            .and_then(|totals| totals.get("use_count"))
            .and_then(Value::as_u64)
            == Some(1)
        && commit
            .get("totals")
            .and_then(|totals| totals.get("use_au"))
            .and_then(value_money_au)
            .is_some_and(|au| au > 0)
        && commit
            .get("provisional_until_epoch")
            .and_then(Value::as_u64)
            .is_some_and(|until| proof_epoch <= until)
}

fn normalized_receipt_envelope(value: &Value) -> Option<Value> {
    let receipt = value.get("receipt").unwrap_or(value);
    let body_source = receipt.get("body").unwrap_or(receipt);
    let mut body = Map::new();
    for field in [
        "schema_version",
        "session_id",
        "seq",
        "final",
        "rail",
        "user",
        "provider",
        "enclave_id",
        "model_id",
        "price_ver",
        "locked_rate_map",
        "locked_per_req_au",
        "locked_min_session_au",
        "served_ctx",
        "rules_ver",
        "usage",
        "au_owed_cum",
        "prompt_hash",
        "ts",
    ] {
        body.insert(field.to_owned(), body_source.get(field)?.clone());
    }
    if let Some(ctx_bracket) = body_source.get("ctx_bracket") {
        body.insert("ctx_bracket".to_owned(), ctx_bracket.clone());
    }
    if let Some(ctx_bracket_table_ver) = body_source.get("ctx_bracket_table_ver") {
        body.insert(
            "ctx_bracket_table_ver".to_owned(),
            ctx_bracket_table_ver.clone(),
        );
    }
    Some(json!({
        "body": Value::Object(body),
        "enclave_sig": receipt.get("enclave_sig").or_else(|| value.get("enclave_sig"))?.clone(),
        "user_sig": receipt.get("user_sig").or_else(|| value.get("user_sig"))?.clone(),
        "enclave_pubkey": receipt
            .get("enclave_pubkey")
            .or_else(|| value.get("enclave_pubkey"))
            .or_else(|| body_source.get("enclave_pubkey"))
            .cloned()
            .unwrap_or(Value::Null),
    }))
}

fn previous_receipt_amounts(receipts: &[Value], receipt: &Value) -> BTreeSet<MoneyAu> {
    let mut amounts = BTreeSet::from([0]);
    let Some(body) = receipt_body(receipt) else {
        return amounts;
    };
    let Some(session_id) = body.get("session_id").and_then(Value::as_str) else {
        return amounts;
    };
    let actual_cum = body
        .get("au_owed_cum")
        .and_then(value_money_au)
        .unwrap_or(0);
    for other in receipts {
        let Some(other_body) = receipt_body(other) else {
            continue;
        };
        if other_body.get("session_id").and_then(Value::as_str) != Some(session_id) {
            continue;
        }
        if let Some(au) = other_body.get("au_owed_cum").and_then(value_money_au) {
            if au < actual_cum {
                amounts.insert(au);
            }
        }
    }
    amounts
}

fn receipt_envelope_with_au_owed_cum(envelope: &Value, au_owed_cum: MoneyAu) -> Value {
    let mut claimed = envelope.clone();
    if let Some(body) = claimed.get_mut("body").and_then(Value::as_object_mut) {
        body.insert("au_owed_cum".to_owned(), money_au_json(au_owed_cum));
    }
    claimed
}

fn usage_leaf_hash_from_envelope(envelope: &Value) -> Result<String> {
    let leaf = json!({
        "body": envelope.get("body").cloned().context("receipt envelope missing body")?,
        "enclave_sig": envelope
            .get("enclave_sig")
            .cloned()
            .context("receipt envelope missing enclave_sig")?,
        "user_sig": envelope
            .get("user_sig")
            .cloned()
            .context("receipt envelope missing user_sig")?,
    });
    Ok(opaque_hash("mayhem-usage-leaf-v1", &leaf))
}

fn fraud_proof_hash_from_command(command: &Value) -> Result<String> {
    let value = json!({
        "epoch": command.get("epoch").cloned().context("fraud command missing epoch")?,
        "proof_epoch": command
            .get("proof_epoch")
            .cloned()
            .context("fraud command missing proof_epoch")?,
        "reason": command
            .get("reason")
            .cloned()
            .context("fraud command missing reason")?,
        "receipt": command
            .get("receipt")
            .cloned()
            .context("fraud command missing receipt")?,
        "claimed_au_owed_cum": command
            .get("claimed_au_owed_cum")
            .cloned()
            .context("fraud command missing claimed_au_owed_cum")?,
        "previous_au_owed_cum": command
            .get("previous_au_owed_cum")
            .cloned()
            .unwrap_or_else(|| money_au_json(0)),
    });
    Ok(opaque_hash("mayhem-fraud-proof-v1", &value))
}

fn opaque_hash(domain: &str, value: &Value) -> String {
    stable_value_hash(&json!({
        "domain": domain,
        "value": value,
    }))
}

fn stable_json_len(value: &Value) -> Result<usize> {
    Ok(serde_json::to_vec(&stable_json_value(value))?.len())
}

async fn submit_fraud_proof_candidates(
    args: &ParticipantTxArgs,
    rpc_url: &str,
    candidates: &[FraudProofChallengeCandidate],
) -> Result<Vec<Value>> {
    if !args.submit || candidates.is_empty() {
        return Ok(Vec::new());
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let wallet_password = args.wallet_password.as_deref().unwrap_or("");
    let wallet = resolve_cli_wallet(
        &home,
        config.as_ref(),
        &args.peer_store_name,
        wallet_password,
    )
    .await?;
    let keypair_path = PathBuf::from(&wallet.keypair_path);
    let rpc = PeerRpcClient::new(rpc_url)?;
    let mut submitted = Vec::new();
    for candidate in candidates {
        let preflight = submit_contract_command(
            &rpc,
            &keypair_path,
            wallet_password,
            &wallet,
            "fraudProof",
            candidate.command.clone(),
            true,
        )
        .await
        .with_context(|| format!("simulating fraud proof {}", candidate.proof_hash))?;
        let real = if args.sim {
            None
        } else {
            Some(
                submit_contract_command(
                    &rpc,
                    &keypair_path,
                    wallet_password,
                    &wallet,
                    "fraudProof",
                    candidate.command.clone(),
                    false,
                )
                .await
                .with_context(|| format!("submitting fraud proof {}", candidate.proof_hash))?,
            )
        };
        submitted.push(json!({
            "proof_hash": candidate.proof_hash,
            "wallet": {
                "public_key": wallet.public_key,
                "keypair_path": wallet.keypair_path,
            },
            "preflight_sim": preflight,
            "real_tx": real,
        }));
    }
    Ok(submitted)
}

fn print_fraud_proof_challenge_report(report: &Value) -> Result<()> {
    println!("Fraud-proof challenger scan complete.");
    for (index, scan) in report
        .get("scans")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .enumerate()
    {
        println!("Scan: {}", index + 1);
        println!(
            "RPC: {}",
            scan.get("rpc_url").and_then(Value::as_str).unwrap_or("")
        );
        if let Some(gateway_url) = scan.get("gateway_url").and_then(Value::as_str) {
            println!("Gateway receipts: {gateway_url}/mayhem/receipts");
        }
        if let Some(path) = scan.get("receipts_file").and_then(Value::as_str) {
            println!("Receipts file: {path}");
        }
        println!(
            "Commits scanned: {}",
            scan.get("commits_scanned")
                .and_then(Value::as_u64)
                .unwrap_or(0)
        );
        println!(
            "Receipts scanned: {}",
            scan.get("receipts_scanned")
                .and_then(Value::as_u64)
                .unwrap_or(0)
        );
        let candidates = scan
            .get("candidates")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        println!("Challenges found: {}", candidates.len());
        for candidate in candidates {
            println!(
                "Candidate epoch {} receipt {} proof {}",
                candidate.get("epoch").and_then(Value::as_u64).unwrap_or(0),
                candidate
                    .get("receipt_id")
                    .and_then(Value::as_str)
                    .unwrap_or(""),
                candidate
                    .get("proof_hash")
                    .and_then(Value::as_str)
                    .unwrap_or("")
            );
            println!("Copy/paste Intercom sim command:");
            println!(
                "{}",
                candidate
                    .get("copy_paste")
                    .and_then(Value::as_str)
                    .unwrap_or("")
            );
        }
        let submissions = scan
            .get("submitted")
            .and_then(Value::as_array)
            .map(Vec::len)
            .unwrap_or(0);
        println!("Submitted proofs: {submissions}");
        print_dispute_alerts_inline(scan)?;
    }
    Ok(())
}

fn print_dispute_alerts_inline(scan: &Value) -> Result<()> {
    let alerts = scan
        .get("dispute_alerts")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    if alerts.is_empty() {
        return Ok(());
    }
    println!("Dispute alerts: {}", alerts.len());
    for alert in alerts {
        println!(
            "[{}] {}",
            alert.get("level").and_then(Value::as_str).unwrap_or("info"),
            alert.get("message").and_then(Value::as_str).unwrap_or("")
        );
    }
    Ok(())
}

async fn run_participant_command(
    args: &ParticipantTxArgs,
    tx_type: &'static str,
    value: Value,
) -> Result<()> {
    let compact_command = serde_json::to_string(&value)?;
    let copy_paste = format!(
        "/tx --command {} --sim 1",
        shell_single_quote(&compact_command)
    );
    let mut report = json!({
        "ok": true,
        "submitted": false,
        "tx_type": tx_type,
        "command": value,
        "copy_paste": {
            "intercom_sim": copy_paste,
        },
    });

    if args.submit {
        let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
        let home = absolutize(home)?;
        let config = read_mayhem_config(&home)?;
        let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
        let wallet_password = args.wallet_password.as_deref().unwrap_or("");
        let wallet = resolve_cli_wallet(
            &home,
            config.as_ref(),
            &args.peer_store_name,
            wallet_password,
        )
        .await?;
        let keypair_path = PathBuf::from(&wallet.keypair_path);
        let rpc = PeerRpcClient::new(&rpc_url)?;
        let submitted = submit_contract_command(
            &rpc,
            &keypair_path,
            wallet_password,
            &wallet,
            tx_type,
            report["command"].clone(),
            args.sim,
        )
        .await?;
        report["submitted"] = json!(true);
        report["sim"] = json!(args.sim);
        report["rpc_url"] = json!(rpc_url);
        report["wallet"] = json!({
            "public_key": wallet.public_key,
            "keypair_path": wallet.keypair_path,
        });
        report["tx"] = submitted;
    }

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_participant_report(&report)?;
    }
    Ok(())
}

fn print_participant_report(report: &Value) -> Result<()> {
    println!("Participant contract command ready.");
    println!("Tx type: {}", report["tx_type"].as_str().unwrap_or(""));
    println!("Command JSON:");
    println!("{}", serde_json::to_string_pretty(&report["command"])?);
    println!("Copy/paste Intercom sim command:");
    println!(
        "{}",
        report["copy_paste"]["intercom_sim"].as_str().unwrap_or("")
    );
    if report["submitted"].as_bool() == Some(true) {
        println!("Submitted: true");
        if let Some(tx) = report["tx"]["tx"].as_str() {
            println!("Tx: {tx}");
        }
        if let Some(command_hash) = report["tx"]["command_hash"].as_str() {
            println!("Command hash: {command_hash}");
        }
    } else {
        println!("Submitted: false (pass --submit to sign and send through peer RPC)");
    }
    Ok(())
}

async fn resolve_withdraw_proof(
    args: &WithdrawArgs,
    account: &str,
    pool_address: &str,
) -> Result<Value> {
    match (&args.settlement, &args.claim_proof) {
        (Some(_), Some(_)) => bail!("pass only one of --settlement or --claim-proof"),
        (None, Some(path)) => read_json_file(path)
            .with_context(|| format!("reading claim proof from {}", path.display())),
        (Some(path), None) => {
            let mut script_args = vec![
                "--settlement".to_owned(),
                path.display().to_string(),
                "--account".to_owned(),
                account.to_owned(),
                "--json".to_owned(),
            ];
            script_args.extend(["--pool".to_owned(), pool_address.to_owned()]);
            let script_env = args
                .eth_rpc
                .as_ref()
                .map(|eth_rpc| vec![("MAYHEM_TAP_ETH_RPC".to_owned(), eth_rpc.clone())])
                .unwrap_or_default();
            run_contracts_script_json_with_env(
                "contracts/scripts/tap-claim-proof.mjs",
                script_args,
                script_env,
            )
            .await
        }
        (None, None) => {
            let cumulative = args
                .cumulative_wei
                .as_deref()
                .context("withdraw requires --settlement, --claim-proof, or --cumulative-wei")?;
            let proof = args
                .proof
                .as_deref()
                .context("withdraw requires --proof when using --cumulative-wei")?;
            Ok(json!({
                "claimable": true,
                "account": args.account,
                "cumulative_wei": cumulative,
                "proof": serde_json::from_str::<Value>(proof).unwrap_or_else(|_| Value::String(proof.to_owned())),
            }))
        }
    }
}

fn push_tap_contract_args(out: &mut Vec<String>, tap: &CanonicalTapRail) {
    out.extend(["--token".to_owned(), tap.token_address.clone()]);
    out.extend(["--pool".to_owned(), tap.pool_address.clone()]);
    out.extend(["--chain-id".to_owned(), tap.chain_id.to_string()]);
}

async fn run_contracts_script_json_with_env<I>(
    relative_script: &str,
    args: Vec<String>,
    envs: I,
) -> Result<Value>
where
    I: IntoIterator<Item = (String, String)>,
{
    let script = repo_path(relative_script)?;
    let node = env::var_os("MAYHEM_NODE_BIN").unwrap_or_else(|| "node".into());
    let mut command = Command::new(&node);
    command.arg(&script).args(args);
    for (key, value) in envs {
        command.env(key, value);
    }
    let output = command.output().await.with_context(|| {
        format!(
            "running {} with {}",
            script.display(),
            PathBuf::from(&node).display()
        )
    })?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        let stdout = String::from_utf8_lossy(&output.stdout);
        bail!(
            "{} failed: {}{}{}",
            script.display(),
            stderr.trim(),
            if stderr.trim().is_empty() || stdout.trim().is_empty() {
                ""
            } else {
                "; stdout: "
            },
            stdout.trim()
        );
    }
    serde_json::from_slice(&output.stdout)
        .with_context(|| format!("parsing {} JSON output", script.display()))
}

fn proof_to_script_arg(proof: &Value) -> Result<String> {
    match proof {
        Value::Array(_) => Ok(serde_json::to_string(proof)?),
        Value::String(value) => Ok(value.clone()),
        _ => bail!("withdrawal proof must be a JSON array or string"),
    }
}

fn tap_deposit_identity_key(
    chain_id: u64,
    pool_address: &str,
    eth_tx_hash: &str,
    log_index: u64,
    block_hash: &str,
) -> Result<String> {
    ensure!(chain_id > 0, "TAP deposit chain id must be positive");
    ensure!(
        is_eth_address(pool_address),
        "TAP deposit pool address is invalid"
    );
    ensure!(
        eth_tx_hash.len() == 66
            && eth_tx_hash.starts_with("0x")
            && eth_tx_hash[2..]
                .as_bytes()
                .iter()
                .all(u8::is_ascii_hexdigit),
        "TAP deposit transaction hash is invalid"
    );
    ensure!(
        block_hash.len() == 66
            && block_hash.starts_with("0x")
            && block_hash[2..].as_bytes().iter().all(u8::is_ascii_hexdigit),
        "TAP deposit block hash is invalid"
    );
    Ok(format!(
        "dep/tap/{}/{}/{}/{}/{}",
        chain_id,
        pool_address.to_ascii_lowercase(),
        eth_tx_hash.to_ascii_lowercase(),
        log_index,
        block_hash.to_ascii_lowercase(),
    ))
}

async fn read_tap_deposit_confirmation(
    rpc: &PeerRpcClient,
    chain_id: u64,
    pool_address: &str,
    eth_tx_hash: &str,
    log_index: Option<u64>,
    who: &str,
) -> Result<(Option<u64>, Option<Value>)> {
    let normalized_hash = eth_tx_hash.to_ascii_lowercase();
    let normalized_pool = pool_address.to_ascii_lowercase();
    ensure!(chain_id > 0, "canonical TAP chain id must be positive");
    ensure!(
        is_eth_address(&normalized_pool),
        "canonical TAP pool address is invalid"
    );
    ensure!(
        normalized_hash.len() == 66
            && normalized_hash.starts_with("0x")
            && normalized_hash[2..]
                .as_bytes()
                .iter()
                .all(u8::is_ascii_hexdigit),
        "TAP transaction hash is invalid"
    );
    let prefix = match log_index {
        Some(log_index) => {
            format!("dep/tap/{chain_id}/{normalized_pool}/{normalized_hash}/{log_index}/")
        }
        None => format!("dep/tap/{chain_id}/{normalized_pool}/{normalized_hash}/"),
    };
    let mut matches = read_prefix_entries(rpc, &prefix)
        .await?
        .into_iter()
        .filter(|entry| {
            entry.value.get("who").and_then(Value::as_str) == Some(who)
                && entry.value.get("chain_id").and_then(Value::as_u64) == Some(chain_id)
                && entry
                    .value
                    .get("pool_address")
                    .and_then(Value::as_str)
                    .is_some_and(|value| value.eq_ignore_ascii_case(&normalized_pool))
                && entry
                    .value
                    .get("eth_tx_hash")
                    .and_then(Value::as_str)
                    .is_some_and(|value| value.eq_ignore_ascii_case(&normalized_hash))
        })
        .collect::<Vec<_>>();
    matches.sort_by(|left, right| left.key.cmp(&right.key));
    if matches.len() > 1 {
        if log_index.is_some() {
            bail!(
                "TAP transaction {eth_tx_hash} has multiple block identities for the requested log; inspect the watcher for a reorg"
            );
        }
        bail!(
            "TAP transaction {eth_tx_hash} contains multiple deposits for this wallet; pass --log-index"
        );
    }
    let Some(entry) = matches.pop() else {
        return Ok((log_index, None));
    };
    let log_index = entry
        .value
        .get("log_index")
        .and_then(Value::as_u64)
        .with_context(|| format!("TAP deposit record {} is missing log_index", entry.key))?;
    Ok((Some(log_index), Some(entry.value)))
}

fn classify_deposit_status(
    balance_au: MoneyAu,
    target_au: Option<MoneyAu>,
    pending_tnk: Option<&Value>,
    tap_seen: Option<&Value>,
    tap_submitted: bool,
) -> &'static str {
    if target_au.is_some_and(|target| balance_au >= target) || tap_seen.is_some() {
        "confirmed"
    } else if pending_tnk.is_some() || target_au.is_some() || tap_submitted {
        "pending"
    } else {
        "unknown"
    }
}

fn print_tap_deposit_report(report: &Value) -> Result<()> {
    if report["submitted"].as_bool() == Some(true) {
        println!("TAP deposit submitted.");
    } else {
        println!("TAP deposit dry-run complete.");
    }
    println!("From: {}", report["from"].as_str().unwrap_or(""));
    println!("TAP token: {}", report["token"].as_str().unwrap_or(""));
    println!("Deposit address: {}", report["pool"].as_str().unwrap_or(""));
    if let Some(rate) = report.get("rate") {
        println!(
            "TAP/USD: ${} ({}; age {}s)",
            rate.get("usd").and_then(Value::as_str).unwrap_or(""),
            rate.get("source").and_then(Value::as_str).unwrap_or(""),
            rate.get("age_seconds").and_then(Value::as_u64).unwrap_or(0)
        );
        println!(
            "Quoted credit: {} au_usd",
            report["quoted_credit_au"].as_str().unwrap_or("0")
        );
    }
    println!(
        "Amount wei: {}",
        report["amount_wei"].as_str().unwrap_or("")
    );
    if let Some(precheck) = report["gas_precheck"].as_object() {
        println!(
            "Gas precheck: {} (estimated max {} ETH)",
            if precheck.get("ok").and_then(Value::as_bool) == Some(true) {
                "ok"
            } else {
                "failed"
            },
            precheck
                .get("estimated_max_cost_eth")
                .and_then(Value::as_str)
                .unwrap_or("unknown")
        );
    }
    if let Some(gas) = report["simulation"]["approve"]["gas_estimate"].as_str() {
        println!("Approve simulation gas: {gas}");
    }
    if let Some(gas) = report["simulation"]["deposit"]["gas_estimate"].as_str() {
        println!("Deposit simulation gas: {gas}");
    } else if report["simulation"]["deposit"]["deferred_until_after_approval"].as_bool()
        == Some(true)
    {
        println!("Deposit simulation: deferred until approve confirms, before value moves");
    }
    if let Some(transactions) = report["transactions"].as_array() {
        for tx in transactions {
            println!(
                "{} tx: {}",
                tx["step"].as_str().unwrap_or("tap"),
                tx["tx_hash"].as_str().unwrap_or("")
            );
        }
    }
    if report["submitted"].as_bool() != Some(true) {
        println!(
            "Dry run only. Re-run with --confirm to broadcast after reviewing the simulation."
        );
    }
    println!(
        "After the deposit transaction finalizes, check credit with: mayhem deposit status --who {} --eth-tx-hash <tx-hash> --log-index <log-index>",
        report["from"].as_str().unwrap_or("<address>")
    );
    Ok(())
}

fn print_deposit_status_report(report: &Value) -> Result<()> {
    println!(
        "Deposit status: {}",
        report["status"].as_str().unwrap_or("")
    );
    println!("Account: {}", report["who"].as_str().unwrap_or(""));
    println!("Rail: {}", report["rail"].as_str().unwrap_or(""));
    println!(
        "Balance: {} au_usd ({})",
        report["balance"]["au"].as_str().unwrap_or("0"),
        au_to_usd_amount(value_money_au(&report["balance"]["au"]).unwrap_or(0))
    );
    if let Some(target) = report["target_au"].as_str() {
        println!("Target: {target} au_usd");
    }
    if !report["tnk"]["pending"].is_null() {
        println!("TNK intent: pending");
    }
    if !report["tap"]["confirmed_event"].is_null() {
        println!("TAP event: confirmed by admin oracle");
    }
    Ok(())
}

fn print_withdraw_report(report: &Value) -> Result<()> {
    println!(
        "TAP withdrawal {}.",
        if report["submitted"].as_bool() == Some(true) {
            "submitted"
        } else {
            "dry-run complete"
        }
    );
    println!("Account: {}", report["account"].as_str().unwrap_or(""));
    println!(
        "Claimable wei: {}",
        report["proof"]["claimable_wei"]
            .as_str()
            .unwrap_or("unknown")
    );
    println!(
        "Cumulative wei: {}",
        report["claim"]["cumulative_wei"].as_str().unwrap_or("")
    );
    println!("Pool: {}", report["claim"]["pool"].as_str().unwrap_or(""));
    if let Some(gas) = report["claim"]["simulation"]["gas_estimate"].as_str() {
        println!("Claim simulation gas: {gas}");
    }
    if let Some(tx) = report["claim"]["claim_tx_hash"].as_str() {
        println!("Claim tx: {tx}");
    } else {
        println!(
            "Dry run only. Re-run with --confirm to broadcast after reviewing the simulation."
        );
    }
    Ok(())
}

async fn pay_tnk(args: PayTnkArgs) -> Result<()> {
    if args.poll_interval_ms == 0 {
        bail!("--poll-interval-ms must be positive");
    }
    if args.submit_transfer && !args.submit_intent {
        bail!("--submit-transfer requires --submit-intent so the contract deposit intent exists before TNK moves");
    }
    if args.submit_transfer && args.sim {
        bail!("--submit-transfer cannot be combined with --sim");
    }
    if args.submit_transfer && args.msb_transfer_timeout_seconds == 0 {
        bail!("--msb-transfer-timeout-seconds must be positive");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let wallet_password = args.wallet_password.as_deref().unwrap_or("");
    let wallet = resolve_cli_wallet_with_keypair(
        &home,
        config.as_ref(),
        args.keypair.as_deref(),
        &args.peer_store_name,
        wallet_password,
    )
    .await?;
    let amount_au = parse_usd_amount_to_au(&args.amount)?;
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    if args.submit_intent || args.submit_transfer {
        require_secure_fund_rpc_url(&rpc_url)?;
    }
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let payment_state = read_canonical_payment_state(&rpc).await?;
    let trust_anchor = (args.submit_intent || args.submit_transfer)
        .then(|| validate_tnk_fund_trust_anchor(config.as_ref(), &payment_state))
        .transpose()?;
    let treasury_address = payment_state.payments.tnk.treasury_address.clone();
    let msb_network = payment_state.payments.tnk.network.clone();
    let rate_age = require_fresh_payment_rate(
        payment_state.observed_at,
        payment_state.tnk_rate.ts,
        payment_state.rate_staleness_seconds,
        "TNK/USD rate",
    )?;
    let rate = PayTnkRate {
        tnk_usd_au: payment_state.tnk_rate.tnk_usd_au,
        source: payment_state.tnk_rate.source.clone(),
        ts: Some(payment_state.tnk_rate.ts),
    };
    let nonce = resolve_tnk_nonce(
        &wallet.public_key,
        amount_au,
        &treasury_address,
        &rate,
        &args,
    )?;
    let memo_hash = derive_tnk_memo_hash(&wallet.public_key, &nonce)?;
    let tnk_e18 = au_to_tnk_e18_ceil_u128(amount_au, rate.tnk_usd_au)?;
    let tnk_decimal = tnk_e18_to_decimal(tnk_e18);
    let quoted_credit_au = tnk_e18_to_au_floor(tnk_e18, rate.tnk_usd_au)?;
    let intent_payload = pay_tnk_deposit_intent_payload(
        &memo_hash,
        &treasury_address,
        tnk_e18,
        quoted_credit_au,
        &rate,
    );
    let msb_transfer_command = format!("/transfer {} {}", treasury_address, tnk_decimal);
    let deposit_intent_command = pay_tnk_deposit_intent_command(
        &args.amount,
        &nonce,
        args.keypair.as_deref(),
        Some(&rpc_url),
    );
    let keypair_path = PathBuf::from(wallet.keypair_path.clone());
    let intent_sig = sign_message(
        &keypair_path,
        wallet_password,
        &deposit_tnk_intent_message(&intent_payload),
    )
    .await?;
    let intent_feature_value = json!({
        "op": "deposit_tnk",
        "sender": wallet.public_key,
        "intent": intent_payload,
        "sig": intent_sig,
    });
    let intent_feature = json!({
        "feature": "mayhem",
        "key": deposit_feature_key(&intent_feature_value)?,
        "value": intent_feature_value,
    });
    let intent_feature_json = serde_json::to_string(&intent_feature)?;
    let intent_feature_rpc_command = Some(format!(
        "curl -sS -X POST {} -H 'content-type: application/json' --data {}",
        shell_single_quote(&format!(
            "{}/contract/feature",
            rpc_url.trim_end_matches('/')
        )),
        shell_single_quote(&intent_feature_json)
    ));
    let admin_confirm_command = format!(
        "mayhem admin tnk-deposit --deposit-binding {} --tnk-e18 {} --msb-tx-hash <msb-tx-hash> --msb-network {} --msb-from <confirmed-from> --msb-to {} --msb-confirmed-length <confirmed-length> --msb-observed-signed-length <signed-length> --epoch <epoch> --at <unix-seconds>",
        shell_single_quote(&memo_hash),
        tnk_e18,
        shell_single_quote(&msb_network),
        shell_single_quote(&treasury_address),
    );

    emit_tnk_handoff(
        args.json,
        amount_au,
        &msb_transfer_command,
        &memo_hash,
        &deposit_intent_command,
    )?;
    let depositor_address = if args.submit_transfer {
        let depositor = wallet
            .address
            .as_deref()
            .context("local wallet did not expose a TNK/MSB source address")?;
        confirm_tnk_transfer_destination(
            args.yes,
            depositor,
            &treasury_address,
            &tnk_decimal,
            &msb_network,
        )?;
        Some(depositor.to_owned())
    } else {
        None
    };

    let before_au = if args.wait {
        Some(read_user_balance_au(&rpc, &wallet.public_key, "tnk").await?)
    } else {
        None
    };

    let rules_consent = if args.submit_intent {
        Some(
            ensure_current_rules_consent(&rpc, &keypair_path, wallet_password, &wallet, args.sim)
                .await?,
        )
    } else {
        None
    };

    let submitted = if args.submit_intent {
        if args.sim {
            Some(json!({ "sim": true, "submitted": false }))
        } else {
            let response = rpc
                .submit_feature(&intent_feature)
                .await
                .context("submitting free TNK deposit intent feature")?;
            if response.get("ok").and_then(Value::as_bool) != Some(true) {
                bail!("TNK deposit intent feature was not accepted: {response}");
            }
            Some(response)
        }
    } else {
        None
    };

    let msb_transfer = if args.submit_transfer {
        let keypair_path = PathBuf::from(wallet.keypair_path.clone());
        let (stores_directory, store_name) = msb_store_from_keypair_path(&keypair_path)?;
        let transfer = submit_msb_transfer(
            &msb_network,
            &stores_directory,
            &store_name,
            &treasury_address,
            &tnk_decimal,
            args.msb_transfer_timeout_seconds,
            3,
            None,
            Some(wallet_password),
        )
        .await?;
        verify_tnk_transfer_result(
            &transfer,
            &msb_network,
            depositor_address
                .as_deref()
                .context("TNK depositor address missing after confirmation")?,
            &treasury_address,
            &tnk_decimal,
        )?;
        Some(transfer)
    } else {
        None
    };

    let credit = if args.wait {
        let before_au = before_au.context("--wait balance snapshot missing")?;
        let target_au = before_au
            .checked_add(amount_au)
            .context("target balance overflowed")?;
        let status = wait_for_credit(
            &rpc,
            &wallet.public_key,
            "tnk",
            before_au,
            target_au,
            Duration::from_secs(args.timeout_seconds),
            Duration::from_millis(args.poll_interval_ms),
        )
        .await?;
        Some(status)
    } else {
        None
    };

    let report = json!({
        "ok": (submitted.is_some() || !args.submit_intent) && (msb_transfer.is_some() || !args.submit_transfer),
        "rail": "tnk",
        "denom": "au_usd",
        "amount_au": money_au_json(amount_au),
        "amount_usd": au_to_usd_amount(amount_au),
        "quoted_credit_au": money_au_json(quoted_credit_au),
        "who": wallet.public_key,
        "rpc_url": rpc_url,
        "treasury_address": treasury_address,
        "payment_config": {
            "source": "payments/current",
            "msb_network": msb_network,
            "treasury_address": treasury_address,
        },
        "local_trust_anchor": trust_anchor,
        "rate": {
            "source_key": "rate/latest",
            "denom": "tnk_usd_au",
            "tnk_usd_au": money_au_json(rate.tnk_usd_au),
            "source": rate.source,
            "ts": rate.ts,
            "age_seconds": rate_age,
        },
        "deposit_intent": {
            "feature": intent_feature,
            "submitted": args.submit_intent && !args.sim,
            "sim": args.submit_intent && args.sim,
            "rules_consent": rules_consent,
            "result": submitted,
        },
        "tnk": {
            "tnk_e18": tnk_e18.to_string(),
            "amount": tnk_decimal,
        },
        "msb_transfer": msb_transfer,
        "memo_hash": memo_hash,
        "nonce": nonce,
        "copy_paste": {
            "msb_transfer_command": msb_transfer_command,
            "deposit_binding": memo_hash,
            "deposit_intent_command": deposit_intent_command,
            "deposit_intent_rpc_command": intent_feature_rpc_command,
            "admin_confirm_command": admin_confirm_command,
        },
        "credit": credit.as_ref().map(|status| json!({
            "credited": status.credited,
            "before_au": money_au_json(status.before_au),
            "current_au": money_au_json(status.current_au),
            "target_au": money_au_json(status.target_au),
            "waited_ms": status.waited_ms,
        })),
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
        if let Some(status) = credit.as_ref().filter(|status| !status.credited) {
            bail!(
                "timed out waiting for {} au_usd credit; current balance {} au_usd, target {} au_usd",
                amount_au,
                status.current_au,
                status.target_au
            );
        }
    } else {
        println!("TNK amount: {tnk_decimal} ({tnk_e18} e18)");
        println!("Treasury address: {treasury_address}");
        println!("Rate: {} tnk_usd_au ({})", rate.tnk_usd_au, rate.source);
        if let Some(ts) = rate.ts {
            println!("Rate timestamp: {ts}");
        }
        if args.submit_intent {
            if args.sim {
                println!("Submitted deposit intent: false (--sim dry-run)");
            } else {
                println!("Submitted deposit intent: true");
            }
            if let Some(key) = report["deposit_intent"]["feature"]["key"].as_str() {
                println!("Deposit intent feature key: {key}");
            }
        } else {
            println!(
                "Submitted deposit intent: false (pass --submit-intent to sign and send through peer RPC)"
            );
        }
        if let Some(transfer) = report["msb_transfer"].as_object() {
            if let Some(tx_hash) = transfer.get("tx_hash").and_then(Value::as_str) {
                println!("Submitted MSB transfer: true");
                println!("MSB tx: {tx_hash}");
            }
        } else if args.submit_transfer {
            println!("Submitted MSB transfer: false");
        }
        if let Some(command) = report["copy_paste"]["deposit_intent_rpc_command"].as_str() {
            println!("Copy/paste deposit intent feature RPC command:");
            println!("{command}");
        }
        println!("Copy/paste admin/oracle confirmation command after MSB finality:");
        println!(
            "{}",
            report["copy_paste"]["admin_confirm_command"]
                .as_str()
                .unwrap_or("")
        );
        if let Some(status) = credit {
            if status.credited {
                println!(
                    "Credited: balance {} -> {} au_usd.",
                    status.before_au, status.current_au
                );
            } else {
                bail!(
                    "timed out waiting for {} au_usd credit; current balance {} au_usd, target {} au_usd",
                    amount_au,
                    status.current_au,
                    status.target_au
                );
            }
        }
    }

    Ok(())
}

async fn pay(rail: PayRail, args: PayRailArgs) -> Result<()> {
    if args.poll_interval_ms == 0 {
        bail!("--poll-interval-ms must be positive");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let wallet_password = args.wallet_password.as_deref().unwrap_or("").to_owned();
    let wallet = resolve_cli_wallet(
        &home,
        config.as_ref(),
        &args.peer_store_name,
        &wallet_password,
    )
    .await?;
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    require_secure_fund_rpc_url(&rpc_url)?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let payment_state = read_canonical_payment_state(&rpc).await?;
    let presentation = args.presentation.trim().to_ascii_lowercase();
    let locale = args.locale.trim().to_ascii_lowercase();
    ensure!(
        presentation == "auto",
        "Stripe presentation must be auto; Stripe Adaptive Pricing selects the buyer currency"
    );
    ensure!(
        locale == payment_state.payments.fiat.locale,
        "Stripe locale {locale} is not enabled by the admin"
    );
    let amount_au = parse_usd_amount_to_au(&args.amount)?;
    let before_au = read_user_balance_au(&rpc, &wallet.public_key, rail.balance_rail()).await?;
    let checkout = create_pay_checkout(PayCheckoutRequest {
        rail,
        rpc: &rpc,
        who: &wallet.public_key,
        amount_au,
        presentation: &presentation,
        locale: &locale,
        idempotency_key: args.idempotency_key.as_deref(),
        success_url: args.success_url.as_deref(),
        cancel_url: args.cancel_url.as_deref(),
        wallet: &wallet,
        wallet_password: &wallet_password,
    })
    .await?;
    emit_checkout_handoff(args.json, rail, amount_au, &presentation, &checkout.url)?;
    let opened = open_checkout_url(&checkout.url, args.no_open).await;
    let target_au = before_au
        .checked_add(amount_au)
        .context("target balance overflowed")?;
    let status = if args.no_wait {
        PayCreditStatus {
            credited: false,
            before_au,
            current_au: before_au,
            target_au,
            waited_ms: 0,
        }
    } else {
        wait_for_credit(
            &rpc,
            &wallet.public_key,
            rail.balance_rail(),
            before_au,
            target_au,
            Duration::from_secs(args.timeout_seconds),
            Duration::from_millis(args.poll_interval_ms),
        )
        .await?
    };

    let report = json!({
        "ok": status.credited || args.no_wait,
        "rail": rail.as_str(),
        "denom": "au_usd",
        "amount_au": money_au_json(amount_au),
        "amount_usd": au_to_usd_amount(amount_au),
        "presentation": presentation,
        "who": wallet.public_key,
        "rpc_url": rpc_url,
        "payment_config": {
            "source": "payments/current",
            "processor": payment_state.payments.fiat.processor,
            "integration_currency": payment_state.payments.fiat.integration_currency,
            "adaptive_pricing": payment_state.payments.fiat.adaptive_pricing,
            "payout_currencies": payment_state.payments.fiat.payout_currencies,
            "locale": payment_state.payments.fiat.locale,
            "checkout_host": "checkout.stripe.com",
        },
        "checkout": {
            "id": checkout.id,
            "url": checkout.url,
            "reference": checkout.reference,
        },
        "copy_paste": checkout_copy_paste_value(&checkout.url),
        "opened": opened,
        "credit": {
            "credited": status.credited,
            "before_au": money_au_json(status.before_au),
            "current_au": money_au_json(status.current_au),
            "target_au": money_au_json(status.target_au),
            "waited_ms": status.waited_ms,
        },
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        if opened {
            println!("Opened checkout in your browser.");
        } else if !args.no_open {
            println!("Could not open a browser automatically; use the URL above.");
        }
        if args.no_wait {
            println!("Not waiting for ledger credit (--no-wait).");
        } else if status.credited {
            println!(
                "Credited: balance {} -> {} au_usd.",
                status.before_au, status.current_au
            );
        }
    }

    if !args.no_wait && !status.credited {
        bail!(
            "timed out waiting for {} au_usd credit; current balance {} au_usd, target {} au_usd",
            amount_au,
            status.current_au,
            status.target_au
        );
    }

    Ok(())
}

