async fn auditor_canary(args: AuditorCanaryArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }
    if args.min_match_bps > 10_000 {
        bail!("--min-match-bps must be <= 10000");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let gateway_root = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let timeout = Duration::from_secs(args.timeout_seconds);
    let client = reqwest::Client::builder().timeout(timeout).build()?;
    let wallet = resolve_cli_wallet(
        &home,
        config.as_ref(),
        &args.peer_store_name,
        args.wallet_password.as_deref().unwrap_or(""),
    )
    .await?;
    let keypair_path = PathBuf::from(wallet.keypair_path.clone());
    let provider = args.provider.to_ascii_lowercase();
    let enclave_id = args.enclave_id.to_ascii_lowercase();
    if !is_hex_len(&provider, 64) {
        bail!("--provider must be a 32-byte hexadecimal public key");
    }
    if !is_hex_len(&enclave_id, 64) {
        bail!("--enclave-id must be a 32-byte hexadecimal enclave id");
    }
    let challenge_epoch = args
        .epoch
        .checked_sub(1)
        .context("--epoch must be at least 1 so it follows a finalized challenge epoch")?;
    let release = read_catalog_release_anchor(&rpc).await?;
    let canary_ref = release
        .canaries
        .iter()
        .find(|canary| canary.set_id == args.canary_set)
        .with_context(|| {
            format!(
                "canary set {} is not published in catalog/current",
                args.canary_set
            )
        })?;
    validate_catalog_canary_prompt_ids(&canary_ref.prompt_ids, &args.canary_set)?;
    let challenge_apply_hash = read_canary_challenge_apply_hash(&rpc, challenge_epoch).await?;
    let challenge_seed = opaque_value_hash(
        "mayhem-canary-challenge-v1",
        &json!({
            "challenge_epoch": challenge_epoch,
            "challenge_apply_hash": challenge_apply_hash,
            "probe_epoch": args.epoch,
            "auditor": wallet.public_key,
            "provider": provider,
            "enclave_id": enclave_id,
            "canary_set": args.canary_set,
            "catalog_hash": release.catalog_hash,
        }),
    );
    let selected_index = hexadecimal_modulo(&challenge_seed, canary_ref.prompt_ids.len())?;
    let selected_prompt_id = canary_ref.prompt_ids[selected_index].clone();
    let fetched_release;
    let canaries_dir = if let Some(path) = args.canaries_dir.as_deref() {
        Some(absolutize(path.to_path_buf())?)
    } else {
        fetched_release = fetch_catalog_release_files(&client, &home, &release).await?;
        Some(fetched_release.canaries_dir)
    };

    let models = fetch_gateway_models(&client, &gateway_root).await?;
    let model = select_test_model(&models, args.model.as_deref())?;
    let canary = load_canary_prompt(
        canaries_dir.as_deref(),
        &args.canary_set,
        Some(&selected_prompt_id),
    )?;
    let expected_text = read_expected_canary_text(&args)?;
    let request = canary_probe_request(&model.id, &canary);
    let response = post_gateway_json_for_provider(
        &client,
        &format!("{gateway_root}/v1/chat/completions"),
        &request,
        &provider,
    )
    .await?;
    let observed_text = gateway_chat_observed_text(&response)?;
    let evaluation = evaluate_text_match(&expected_text, &observed_text, args.min_match_bps);
    let receipts = fetch_gateway_json(&client, &format!("{gateway_root}/mayhem/receipts")).await?;
    let latest_receipt = latest_gateway_receipt(&receipts).context(
        "canary probes must leave a gateway receipt; run the probe through the normal paid gateway path",
    )?;
    let session_receipt_hash = stable_value_hash(&latest_receipt);
    let receipt_body = receipt_body(&latest_receipt);
    let receipt_provider = receipt_body
        .and_then(|body| body.get("provider"))
        .and_then(Value::as_str)
        .context("gateway receipt does not expose the challenged provider")?;
    let receipt_enclave_id = receipt_body
        .and_then(|body| body.get("enclave_id"))
        .and_then(Value::as_str)
        .context("gateway receipt does not expose the challenged enclave_id")?;
    ensure!(
        receipt_provider.eq_ignore_ascii_case(&provider),
        "gateway routed the canary to provider {receipt_provider}, not challenged provider {provider}"
    );
    ensure!(
        receipt_enclave_id.eq_ignore_ascii_case(&enclave_id),
        "gateway routed the canary to enclave {receipt_enclave_id}, not challenged enclave {enclave_id}"
    );
    let binary_hash = model
        .binary_hashes_by_enclave
        .get(&enclave_id)
        .cloned()
        .context("selected gateway model does not expose a binary_hash for the probed enclave")?;
    let at = args.at.unwrap_or(unix_epoch_seconds()?);
    let verification_method = "token_fingerprint";
    let evidence = json!({
        "schema_version": 1,
        "kind": "mayhem-canary-probe-evidence",
        "gateway_url": gateway_root,
        "model": model.id,
        "canary_set": args.canary_set,
        "canary_prompt_id": canary.id,
        "challenge_epoch": challenge_epoch,
        "challenge_apply_hash": challenge_apply_hash,
        "challenge_seed": challenge_seed,
        "verification_method": verification_method,
        "prompt_id": canary.id,
        "request": request,
        "response": response,
        "observed_text": observed_text,
        "expected_text_hash": evaluation.expected_text_hash,
        "evaluation": evaluation,
        "latest_receipt": latest_receipt,
    });
    let evidence_hash = stable_value_hash(&evidence);
    let probe_id = args.probe_id.unwrap_or_else(|| {
        stable_value_hash(&json!({
            "provider": provider,
            "enclave_id": enclave_id,
            "canary_set": args.canary_set,
            "prompt_id": canary.id,
            "challenge_seed": challenge_seed,
            "epoch": args.epoch,
            "evidence_hash": evidence_hash,
        }))
    });
    let mut probe_command = canary_probe_command(CanaryProbeCommandInput {
        probe_id: probe_id.clone(),
        provider: provider.clone(),
        enclave_id: enclave_id.clone(),
        binary_hash,
        epoch: args.epoch,
        at,
        canary_set: args.canary_set.clone(),
        canary_prompt_id: canary.id.clone(),
        challenge_epoch,
        challenge_apply_hash: challenge_apply_hash.clone(),
        challenge_seed: challenge_seed.clone(),
        verification_method: verification_method.to_owned(),
        match_bps: evaluation.match_bps,
        pass: evaluation.pass,
        session_receipt_hash,
        evidence_hash: evidence_hash.clone(),
        auditor_sig: String::new(),
    });
    let auditor_sig = sign_probe_result_command(
        &keypair_path,
        args.wallet_password.as_deref().unwrap_or(""),
        &wallet.public_key,
        &probe_command,
    )
    .await?;
    probe_command["auditor_sig"] = json!(auditor_sig);

    let evidence_output = args
        .evidence_output
        .as_ref()
        .map(|path| absolutize(path.clone()))
        .transpose()?;
    if let Some(path) = &evidence_output {
        let evidence_file = json!({
            "evidence": evidence,
            "probe_command": probe_command,
        });
        write_json_file(path, &evidence_file)?;
    }

    let tx = if args.submit {
        Some(
            submit_contract_command(
                &rpc,
                &keypair_path,
                args.wallet_password.as_deref().unwrap_or(""),
                &wallet,
                "probeResult",
                probe_command.clone(),
                args.sim,
            )
            .await?,
        )
    } else {
        None
    };

    let report = json!({
        "ok": evaluation.pass,
        "gateway_url": gateway_root,
        "model": model,
        "canary": {
            "set_id": args.canary_set,
            "prompt_id": canary.id,
        },
        "evaluation": evaluation,
        "provider": probe_command["provider"],
        "enclave_id": probe_command["enclave_id"],
        "probe_command": probe_command,
        "evidence_hash": evidence_hash,
        "evidence_output": evidence_output,
        "submitted": tx,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "Canary probe {}: match {} bps.",
            if report["ok"].as_bool().unwrap_or(false) {
                "passed"
            } else {
                "failed"
            },
            report["evaluation"]["match_bps"]
                .as_u64()
                .unwrap_or_default()
        );
        println!(
            "Probe id: {}",
            report["probe_command"]["probe_id"].as_str().unwrap_or("")
        );
        println!("Evidence hash: {evidence_hash}");
        if let Some(path) = evidence_output {
            println!("Copy/paste evidence path: {}", path.display());
        }
        if !args.submit {
            println!("Copy/paste probe_result command:");
            println!(
                "{}",
                serde_json::to_string_pretty(&report["probe_command"])?
            );
        }
    }
    Ok(())
}

fn load_canary_prompt(
    canaries_dir: Option<&Path>,
    set_id: &str,
    prompt_id: Option<&str>,
) -> Result<CanaryPrompt> {
    let prompts = load_canary_prompts(canaries_dir, set_id, prompt_id)?;
    prompts
        .into_iter()
        .next()
        .with_context(|| format!("canary set {set_id} has no prompts"))
}

fn load_canary_prompts(
    canaries_dir: Option<&Path>,
    set_id: &str,
    prompt_id: Option<&str>,
) -> Result<Vec<CanaryPrompt>> {
    load_canary_prompts_checked(canaries_dir, set_id, prompt_id, true)
}

fn load_canary_prompts_checked(
    canaries_dir: Option<&Path>,
    set_id: &str,
    prompt_id: Option<&str>,
    require_messages: bool,
) -> Result<Vec<CanaryPrompt>> {
    let canaries_dir = canaries_dir
        .map(PathBuf::from)
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let path = absolutize(canaries_dir)?.join(format!("{set_id}.json"));
    let doc: CanarySetDocument = serde_json::from_value(read_json_file(&path)?)
        .with_context(|| format!("parsing canary set {}", path.display()))?;
    if doc.set_id != set_id {
        bail!("canary file {} declares set {}", path.display(), doc.set_id);
    }
    let prompts = if let Some(prompt_id) = prompt_id {
        vec![doc
            .prompts
            .into_iter()
            .find(|prompt| prompt.id == prompt_id)
            .with_context(|| format!("canary prompt {prompt_id} not found in {set_id}"))?]
    } else {
        doc.prompts
    };
    if prompts.is_empty() {
        bail!("canary set {set_id} has no prompts");
    }
    for prompt in &prompts {
        if require_messages && prompt.messages.is_empty() {
            bail!("canary prompt {} has no messages", prompt.id);
        }
    }
    Ok(prompts)
}

fn read_expected_canary_text(args: &AuditorCanaryArgs) -> Result<String> {
    match (&args.expected_text, &args.expected_file) {
        (Some(text), None) if !text.is_empty() => Ok(text.clone()),
        (None, Some(path)) => fs::read_to_string(path)
            .with_context(|| format!("reading expected canary text {}", path.display())),
        (Some(_), Some(_)) => bail!("use either --expected-text or --expected-file, not both"),
        _ => bail!("--expected-text or --expected-file is required for canary scoring"),
    }
}

fn canary_probe_request(model_id: &str, prompt: &CanaryPrompt) -> Value {
    let mut request = json!({
        "model": model_id,
        "messages": &prompt.messages,
        "max_tokens": prompt.max_tokens.unwrap_or(128),
        "stream": false,
    });
    if let Some(tools) = &prompt.tools {
        request["tools"] = json!(tools);
    }
    if !prompt.specialities.is_empty() {
        request["specialities"] = json!(&prompt.specialities);
    }
    if let Some(temperature) = prompt.temperature {
        request["temperature"] = json!(temperature);
    }
    if let Some(top_p) = prompt.top_p {
        request["top_p"] = json!(top_p);
    }
    if let Some(top_k) = prompt.top_k {
        request["top_k"] = json!(top_k);
    }
    if let Some(min_p) = prompt.min_p {
        request["min_p"] = json!(min_p);
    }
    if let Some(repeat_penalty) = prompt.repeat_penalty {
        request["repeat_penalty"] = json!(repeat_penalty);
    }
    if let Some(frequency_penalty) = prompt.frequency_penalty {
        request["frequency_penalty"] = json!(frequency_penalty);
    }
    if let Some(presence_penalty) = prompt.presence_penalty {
        request["presence_penalty"] = json!(presence_penalty);
    }
    if let Some(seed) = prompt.seed {
        request["seed"] = json!(seed);
    }
    request
}

