trait ProviderSessionResponder {
    fn mode(&self) -> &'static str;
    /// Independently dispatchable requests, not the engine's theoretical batch capacity.
    fn concurrent_session_capacity(&self) -> u32 {
        1
    }
    fn component_healthy(&mut self) -> bool {
        true
    }
    fn supports_live_text_streaming(&self) -> bool {
        false
    }
    fn process_ids(&self) -> Vec<u32> {
        Vec::new()
    }
    fn respond(
        &mut self,
        terms: &ProviderSessionTerms,
        body: &Value,
        cancellation: &CancellationToken,
    ) -> Result<ProviderSessionOutput>;
    fn respond_streaming(
        &mut self,
        terms: &ProviderSessionTerms,
        body: &Value,
        _stream: Option<&mut ProviderSessionLiveStream<'_>>,
        cancellation: &CancellationToken,
    ) -> Result<ProviderSessionOutput> {
        self.respond(terms, body, cancellation)
    }
}

struct DeterministicProviderSessionResponder;

impl ProviderSessionResponder for DeterministicProviderSessionResponder {
    fn mode(&self) -> &'static str {
        "deterministic-dev-shim"
    }

    fn respond(
        &mut self,
        terms: &ProviderSessionTerms,
        body: &Value,
        cancellation: &CancellationToken,
    ) -> Result<ProviderSessionOutput> {
        cancellation.check().context("provider request cancelled")?;
        Ok(provider_session_response(terms, body))
    }
}

