#[derive(Clone, Debug)]
struct ProviderEngineRecovery {
    reason: Option<String>,
    retry_at: Option<Instant>,
    initial_delay: Duration,
    max_delay: Duration,
    next_delay: Duration,
}

impl ProviderEngineRecovery {
    fn new(initial_delay: Duration, max_delay: Duration) -> Self {
        Self {
            reason: None,
            retry_at: None,
            initial_delay,
            max_delay,
            next_delay: initial_delay,
        }
    }

    fn mark_failed(&mut self, reason: impl Into<String>) {
        if self.reason.is_none() {
            self.retry_at = Some(Instant::now());
            self.next_delay = self.initial_delay;
        }
        self.reason = Some(reason.into());
    }

    fn mark_reload_failed(&mut self, reason: impl Into<String>, now: Instant) {
        self.reason = Some(reason.into());
        self.retry_at = Some(now + self.next_delay);
        self.next_delay = (self.next_delay * 2).min(self.max_delay);
    }

    fn mark_recovered(&mut self) {
        self.reason = None;
        self.retry_at = None;
        self.next_delay = self.initial_delay;
    }

    fn pending(&self) -> bool {
        self.reason.is_some()
    }

    fn retry_due(&self, now: Instant) -> bool {
        self.pending() && self.retry_at.is_some_and(|retry_at| now >= retry_at)
    }

    fn reason(&self) -> Option<&str> {
        self.reason.as_deref()
    }

    fn rejection(&self) -> Option<ProviderRuntimeFloorRejection> {
        self.reason
            .as_ref()
            .map(|reason| ProviderRuntimeFloorRejection {
                code: "ENGINE_UNAVAILABLE",
                reason: format!(
                    "provider engine component is reloading after a contained failure: {reason}"
                ),
            })
    }
}

fn provider_engine_component_failure(
    responder: &mut dyn ProviderSessionResponder,
    error: &anyhow::Error,
) -> Option<String> {
    let reason = format!("{error:#}");
    (reason.contains("provider engine panicked") || !responder.component_healthy())
        .then_some(reason)
}

fn provider_engine_component_failure_after_cancel(
    responder: &mut dyn ProviderSessionResponder,
    error: &anyhow::Error,
) -> Option<String> {
    let reason = format!("{error:#}");
    if reason.contains(PROVIDER_ENGINE_REQUEST_CANCELLED)
        && !reason.contains("provider engine panicked")
        && responder.component_healthy()
    {
        return None;
    }
    (reason.contains("provider engine panicked") || !responder.component_healthy())
        .then_some(reason)
}

fn reload_provider_session_responder(
    responder: &mut Box<dyn ProviderSessionResponder>,
    reason: String,
    loader: impl FnOnce() -> Result<Box<dyn ProviderSessionResponder>>,
) -> Result<()> {
    let old_responder = std::mem::replace(
        responder,
        Box::new(UnavailableProviderSessionResponder { reason }),
    );
    drop(old_responder);
    *responder = loader()?;
    Ok(())
}

struct ProviderServePlanComputed {
    rpc_url: String,
    provider_catalog: ProviderResolvedCatalog,
    hardware: HardwareReport,
    candidates: Vec<ProviderCandidate>,
    selection: ProviderAutoFitSelection,
    gpu_layers: Option<u32>,
    hardware_quote_config: Option<ProviderHardwareQuoteConfig>,
}

struct ProviderServeCandidatesComputed {
    rpc_url: String,
    provider_catalog: ProviderResolvedCatalog,
    contract: ContractCatalog,
    config: Option<MayhemConfig>,
    hardware: HardwareReport,
    candidates: Vec<ProviderCandidate>,
    start_args: ProviderStartArgs,
}

async fn compute_provider_serve_plan(
    home: &Path,
    args: &ProviderServePlanArgs,
) -> Result<ProviderServePlanComputed> {
    let computed = compute_provider_serve_candidates(home, args).await?;
    let candidates = provider_candidates_with_config_defaults(
        &computed.contract,
        &computed.provider_catalog.catalog_doc,
        &computed.hardware,
        &computed.start_args,
        computed.config.as_ref(),
        &computed.candidates,
    )?;
    let selection = select_provider_auto_fit_set(&candidates)?;
    let hardware_quote_config = provider_hardware_quote_config(&computed.start_args)?;
    Ok(ProviderServePlanComputed {
        rpc_url: computed.rpc_url,
        provider_catalog: computed.provider_catalog,
        hardware: computed.hardware,
        candidates,
        selection,
        gpu_layers: computed.start_args.gpu_layers,
        hardware_quote_config,
    })
}

async fn compute_provider_explicit_serve_plan(
    home: &Path,
    args: &ProviderServePlanArgs,
    requested: &[String],
) -> Result<ProviderServePlanComputed> {
    if requested.is_empty() {
        bail!("explicit provider serve plan requires at least one admin enclave/model id");
    }
    let computed = compute_provider_serve_candidates(home, args).await?;
    let mut selected = Vec::with_capacity(requested.len());
    for request in requested {
        let mut scoped_args = computed.start_args.clone();
        scoped_args.enclave = Some(request.clone());
        let candidate = select_provider_candidate_with_config_defaults(
            &computed.contract,
            &computed.provider_catalog.catalog_doc,
            &computed.hardware,
            &mut scoped_args,
            computed.config.as_ref(),
            Some(request),
        )?;
        selected.push(candidate);
    }
    let selected_ids = selected
        .iter()
        .map(|candidate| candidate.enclave.enclave_id.clone())
        .collect::<Vec<_>>();
    let selection = select_provider_explicit_set(&selected, &selected_ids)?;
    let hardware_quote_config = provider_hardware_quote_config(&computed.start_args)?;
    Ok(ProviderServePlanComputed {
        rpc_url: computed.rpc_url,
        provider_catalog: computed.provider_catalog,
        hardware: computed.hardware,
        candidates: selected,
        selection,
        gpu_layers: computed.start_args.gpu_layers,
        hardware_quote_config,
    })
}

async fn compute_provider_default_serve_plan(
    home: &Path,
    args: &ProviderServePlanArgs,
) -> Result<ProviderServePlanComputed> {
    let computed = compute_provider_serve_candidates(home, args).await?;
    let initial_selected = select_provider_candidate(&computed.candidates, None)?;
    let requested = initial_selected.enclave.enclave_id.clone();
    let mut scoped_args = computed.start_args.clone();
    scoped_args.enclave = Some(requested.clone());
    let selected = select_provider_candidate_with_config_defaults(
        &computed.contract,
        &computed.provider_catalog.catalog_doc,
        &computed.hardware,
        &mut scoped_args,
        computed.config.as_ref(),
        Some(&requested),
    )?;
    let candidates = vec![selected];
    let selection = select_provider_explicit_set(&candidates, &[requested])?;
    let hardware_quote_config = provider_hardware_quote_config(&computed.start_args)?;
    Ok(ProviderServePlanComputed {
        rpc_url: computed.rpc_url,
        provider_catalog: computed.provider_catalog,
        hardware: computed.hardware,
        candidates,
        selection,
        gpu_layers: computed.start_args.gpu_layers,
        hardware_quote_config,
    })
}

async fn compute_provider_serve_candidates(
    home: &Path,
    args: &ProviderServePlanArgs,
) -> Result<ProviderServeCandidatesComputed> {
    let config = read_mayhem_config(home)?;
    let mut start_args = provider_start_args_for_serve_plan(args, home);
    if start_args.engine_backend == "auto" {
        if let Some(config_backend) = config
            .as_ref()
            .and_then(|config| config.provider.as_ref())
            .and_then(|provider| provider.engine_backend.clone())
            .filter(|backend| !backend.trim().is_empty())
        {
            start_args.engine_backend = config_backend;
        }
    }
    if start_args.gpu_layers.is_none() {
        start_args.gpu_layers = config
            .as_ref()
            .and_then(|config| config.provider.as_ref())
            .and_then(|provider| provider.gpu_layers);
    }
    apply_provider_resource_config_defaults(&mut start_args, config.as_ref());
    let rpc_url = start_args
        .rpc_url
        .clone()
        .or_else(|| {
            config
                .as_ref()
                .and_then(|config| config.network.as_ref())
                .and_then(|network| network.rpc_url.clone())
        })
        .unwrap_or_else(|| DEFAULT_RPC_URL.to_owned());
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let contract = read_contract_catalog(&rpc).await?;
    let provider_catalog =
        resolve_provider_start_catalog(&start_args, &home, &rpc, &rpc_url).await?;
    let hardware = provider_hwprobe(&start_args)?;
    let candidates = build_provider_candidates(
        &contract,
        &provider_catalog.catalog_doc,
        &hardware,
        &start_args,
    )?;
    Ok(ProviderServeCandidatesComputed {
        rpc_url,
        provider_catalog,
        contract,
        config,
        hardware,
        candidates,
        start_args,
    })
}

async fn provider_serve_plan(args: ProviderServePlanArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let computed = compute_provider_serve_plan(&home, &args).await?;
    let selection = &computed.selection;
    let up_command = provider_auto_fit_up_command(
        &home,
        selection,
        computed.gpu_layers,
        &args.disable_modalities,
        computed.hardware_quote_config.as_ref(),
    );
    let selected = selection
        .candidates
        .iter()
        .map(|candidate| {
            let price = candidate
                .price
                .as_ref()
                .and_then(|price| price.current.as_ref());
            json!({
                "enclave_id": &candidate.enclave.enclave_id,
                "model_id": &candidate.enclave.model_id,
                "backend": &candidate.enclave.backend,
                "artifact": &candidate.artifact_name,
                "model_class": &candidate.enclave.model_class,
                "served_ctx": candidate.served_ctx,
                "required_bytes": candidate.feasibility.estimated_required_bytes,
                "required_human": human_bytes(candidate.feasibility.estimated_required_bytes),
                "budget_pool": candidate.feasibility.memory_budget.pool,
                "budget_bytes": candidate.feasibility.memory_budget.budget_bytes,
                "budget_human": human_bytes(candidate.feasibility.memory_budget.budget_bytes),
                "estimated_tok_s": candidate.verdict.est_tok_s,
                "score": provider_auto_fit_candidate_score(candidate),
                "price_ver": price.map(|price| price.ver),
                "rate_map": price.map(|price| price.rate_map.clone()).unwrap_or_default(),
            })
        })
        .collect::<Vec<_>>();
    let report = json!({
        "ok": true,
        "mode": "provider-serve-plan",
        "home": home,
        "rpc_url": computed.rpc_url,
        "catalog": {
            "source": computed.provider_catalog.source,
            "path": computed.provider_catalog.catalog_path,
            "hash": computed.provider_catalog.catalog_hash,
        },
        "candidate_count": computed.candidates.len(),
        "selected_count": selection.candidates.len(),
        "selected": selected,
        "total_required_bytes": selection.total_required_bytes,
        "total_required_human": human_bytes(selection.total_required_bytes),
        "total_budget_bytes": selection.total_budget_bytes,
        "total_budget_human": human_bytes(selection.total_budget_bytes),
        "modalities": selection.modalities,
        "score": selection.score,
        "rationale": selection.rationale,
        "copy_paste": {
            "up": up_command,
        },
    });
    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "{}",
            report["rationale"]
                .as_str()
                .unwrap_or("auto-fit plan ready")
        );
        println!("Selected enclaves:");
        for item in report["selected"].as_array().into_iter().flatten() {
            println!(
                "- {} via {} ({})",
                item["model_id"].as_str().unwrap_or("unknown"),
                item["backend"].as_str().unwrap_or("unknown"),
                short_hash(item["enclave_id"].as_str().unwrap_or(""))
            );
        }
        println!(
            "Copy/paste start command: {}",
            report["copy_paste"]["up"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

async fn provider_serve_add(args: ProviderServeAddArgs) -> Result<()> {
    let prepared = prepare_provider_serve_worker(&args, None).await?;
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(10))
        .build()
        .context("building mayhemd control HTTP client")?;
    let report = add_prepared_provider_worker(&client, prepared).await?;
    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "Provider worker added: {}",
            report["response"]["name"].as_str().unwrap_or("provider")
        );
        println!(
            "Copy/paste status command: mayhem status --home {}",
            report["home"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

struct PreparedProviderServeWorker {
    home: PathBuf,
    supervisor_url: String,
    requested: String,
    enclave_id: String,
    model_id: String,
    served_ctx: u64,
    serve_terms: ProviderJoinContextTerms,
    vllm_memory_utilization: Option<VllmMemoryUtilizationPlan>,
    runtime: ProviderBackendRuntime,
    reactivation_drain_cleanup: Value,
    child: Value,
}

async fn prepare_provider_serve_worker(
    args: &ProviderServeAddArgs,
    name: Option<String>,
) -> Result<PreparedProviderServeWorker> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let supervisor_url = mayhemd_control_url(&home)?;
    let serve_plan_args = ProviderServePlanArgs {
        home: Some(home.clone()),
        rpc_url: None,
        catalog_path: None,
        signature_path: None,
        keys_dir: None,
        canaries_dir: None,
        engine_backend: "auto".to_owned(),
        gpu_layers: args.gpu_layers,
        fixture: None,
        disk_path: None,
        skip_disk_bench: false,
        ctx: args.ctx,
        disable_modalities: args.disable_modalities.clone(),
        speciality_levels: args.speciality_levels.clone(),
        memory_reserve: None,
        hardware_quote_kind: args.hardware_quote_kind.clone(),
        hardware_quote_command: args.hardware_quote_command.clone(),
        hardware_quote_timeout_seconds: args.hardware_quote_timeout_seconds,
        json: true,
        dev_skip_catalog_verify: false,
    };
    let requested = vec![args.enclave.clone()];
    let computed =
        compute_provider_explicit_serve_plan(&home, &serve_plan_args, &requested).await?;
    let selected = computed
        .selection
        .candidates
        .first()
        .context("explicit provider add did not select a candidate")?;
    let mut reactivation_drain_cleanup = Value::Null;
    if let Some(path) = provider_serve_active_drain_flag(&home, &selected.enclave.enclave_id)? {
        let rpc = PeerRpcClient::new(&computed.rpc_url)?;
        match clear_completed_provider_drain_for_reactivation(
            &home,
            &rpc,
            &selected.enclave.enclave_id,
            &path,
        )
        .await?
        {
            Some(report) => reactivation_drain_cleanup = report,
            None => bail_provider_start_drained(&home, &selected.enclave.enclave_id, &path)?,
        }
    }
    let runtime = provider_backend_runtime_preflight(
        &home,
        selected,
        &computed.hardware,
        computed.gpu_layers,
    )
    .with_context(|| {
        format!(
            "provider runtime preflight failed for {} ({})",
            selected.model.model_id, selected.artifact.engine
        )
    })?;
    let vllm_memory_utilization = ensure_provider_vllm_memory_utilization_config(
        &home,
        std::slice::from_ref(selected),
        None,
    )?;
    let child = provider_serve_child_config(
        &home,
        &selected.enclave.enclave_id,
        &selected.artifact.engine,
        &runtime,
        vllm_memory_utilization.as_ref(),
        computed.gpu_layers,
        Some(selected.served_ctx),
        &selected.served_modalities,
        &selected.served_specialities,
        computed.hardware_quote_config.as_ref(),
        name,
    )?;
    let serve_terms = provider_join_context_terms_for_candidate(selected)?;
    Ok(PreparedProviderServeWorker {
        home,
        supervisor_url,
        requested: args.enclave.clone(),
        enclave_id: selected.enclave.enclave_id.clone(),
        model_id: selected.enclave.model_id.clone(),
        served_ctx: selected.served_ctx,
        serve_terms,
        vllm_memory_utilization,
        runtime,
        reactivation_drain_cleanup,
        child,
    })
}

async fn add_prepared_provider_worker(
    client: &reqwest::Client,
    prepared: PreparedProviderServeWorker,
) -> Result<Value> {
    let rpc_url = resolve_cli_rpc_url(Some(&prepared.home), None)?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let activation_leave_replay = replay_provider_leaves_before_activation(
        &prepared.home,
        &rpc,
        &ProviderActivationLeaveScope {
            provider: None,
            enclave_id: prepared.enclave_id.clone(),
            room_ids: None,
        },
        false,
    )
    .await
    .context("replaying pending signed leaves before adding provider worker")?;
    let control_token = load_or_create_mayhemd_control_token(&prepared.home)?;
    let response = post_mayhemd_json(
        client,
        &format!("{}/children/add", prepared.supervisor_url),
        &prepared.child,
        &control_token,
    )
    .await
    .context("adding provider worker to mayhemd")?;
    Ok(json!({
        "ok": true,
        "home": prepared.home,
        "supervisor_url": prepared.supervisor_url,
        "requested": prepared.requested,
        "enclave": prepared.enclave_id,
        "model_id": prepared.model_id,
        "served_ctx": prepared.served_ctx,
        "vllm_memory_utilization": prepared.vllm_memory_utilization,
        "runtime": prepared.runtime,
        "reactivation_drain_cleanup": prepared.reactivation_drain_cleanup,
        "activation_leave_replay": activation_leave_replay,
        "child": provider_serve_public_child_report(&prepared.child),
        "response": response,
    }))
}

async fn provider_serve_remove(args: ProviderServeRemoveArgs) -> Result<()> {
    ensure!(
        args.timeout_seconds > 0,
        "--timeout-seconds must be positive"
    );
    let ctx = provider_tx_context(&args.tx).await?;
    let home = ctx.home.clone();
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(10))
        .build()
        .context("building mayhemd control HTTP client")?;
    let supervisor_url = mayhemd_control_url(&home)?;
    let control_token = load_or_create_mayhemd_control_token(&home)?;
    let status = fetch_gateway_json(&client, &format!("{supervisor_url}/status")).await?;
    let serves = read_active_provider_serves(&ctx.rpc, &ctx.wallet.public_key).await?;
    let worker = provider_serve_worker_for_target(&status, &serves, &args.target)?;
    let contract = read_contract_catalog(&ctx.rpc).await?;
    let drain = if args.tx.sim {
        Value::Null
    } else {
        drain_supervised_provider_workers(
            &home,
            &ctx.wallet.public_key,
            std::slice::from_ref(&worker),
            Some(&worker.enclave_id),
            Duration::from_secs(args.timeout_seconds),
        )
        .await?
    };
    let retirement = retire_provider_registrations(
        &ctx,
        &contract,
        std::slice::from_ref(&worker.enclave_id),
        ProviderWorkerRetirement::DeliberateRemove,
        args.tx.sim,
    )
    .await?;
    let response = if args.tx.sim {
        Value::Null
    } else {
        remove_supervised_provider_worker(&client, &supervisor_url, &control_token, &worker).await?
    };
    let report = json!({
        "ok": true,
        "home": home,
        "supervisor_url": supervisor_url,
        "target": args.target,
        "child_name": worker.name,
        "enclave_id": worker.enclave_id,
        "sim": args.tx.sim,
        "drain": drain,
        "retirement": retirement,
        "response": response,
    });
    if args.tx.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "Provider worker {}: {}",
            if args.tx.sim {
                "removal simulated"
            } else {
                "removed"
            },
            report["child_name"].as_str().unwrap_or("provider")
        );
        println!(
            "Copy/paste status command: mayhem status --home {}",
            report["home"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

async fn provider_serve_switch(args: ProviderServeSwitchArgs) -> Result<()> {
    ensure!(
        args.timeout_seconds > 0,
        "--timeout-seconds must be positive"
    );
    let ctx = provider_tx_context(&args.tx).await?;
    let home = ctx.home.clone();
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(10))
        .build()
        .context("building mayhemd control HTTP client")?;
    let supervisor_url = mayhemd_control_url(&home)?;
    let control_token = load_or_create_mayhemd_control_token(&home)?;
    let status = fetch_gateway_json(&client, &format!("{supervisor_url}/status")).await?;
    let serves = read_active_provider_serves(&ctx.rpc, &ctx.wallet.public_key).await?;
    let old_worker = provider_serve_worker_for_target(&status, &serves, &args.target)?;
    let contract = read_contract_catalog(&ctx.rpc).await?;
    let requested_enclave = resolve_provider_lifecycle_enclave(&contract.enclaves, &args.enclave)?;
    let sequencing =
        provider_switch_sequencing_policy(&old_worker.enclave_id, &requested_enclave.enclave_id);
    let existing_serve_row = serves
        .iter()
        .find(|serve| serve.enclave_id == old_worker.enclave_id);
    let preserving_same_enclave = sequencing.clear_completed_scoped_drain_before_add;
    let inherited_disabled_modalities = preserving_same_enclave
        .then(|| {
            existing_serve_row.map(|serve| {
                ["text", "embedding", "image", "video", "audio"]
                    .into_iter()
                    .filter(|modality| {
                        !serve
                            .served_modalities
                            .iter()
                            .any(|served| served == *modality)
                    })
                    .map(str::to_owned)
                    .collect::<Vec<_>>()
            })
        })
        .flatten()
        .unwrap_or_default();
    let inherited_speciality_levels = preserving_same_enclave
        .then(|| {
            existing_serve_row.map(|serve| {
                serve
                    .served_specialities
                    .iter()
                    .map(|(name, levels)| format!("{name}={}", levels.join(",")))
                    .collect::<Vec<_>>()
            })
        })
        .flatten()
        .unwrap_or_default();
    let add_args = ProviderServeAddArgs {
        home: Some(home.clone()),
        enclave: args.enclave.clone(),
        gpu_layers: args.gpu_layers,
        ctx: args.ctx.or_else(|| {
            preserving_same_enclave
                .then_some(existing_serve_row?.served_ctx)
                .flatten()
        }),
        disable_modalities: if preserving_same_enclave && args.disable_modalities.is_empty() {
            inherited_disabled_modalities
        } else {
            args.disable_modalities.clone()
        },
        speciality_levels: if preserving_same_enclave && args.speciality_levels.is_empty() {
            inherited_speciality_levels
        } else {
            args.speciality_levels.clone()
        },
        hardware_quote_kind: args.hardware_quote_kind.clone(),
        hardware_quote_command: args.hardware_quote_command.clone(),
        hardware_quote_timeout_seconds: args.hardware_quote_timeout_seconds,
        json: true,
    };
    let existing_serve = read_state_value(
        &ctx.rpc,
        &format!("serve/{}/{}", ctx.wallet.public_key, old_worker.enclave_id),
    )
    .await?;
    let prepared = prepare_provider_serve_worker(&add_args, Some(old_worker.name.clone())).await?;
    let temporary_update = provider_switch_preserves_durable_registration(
        &old_worker.enclave_id,
        &prepared.enclave_id,
        existing_serve.as_ref(),
        &prepared.serve_terms,
    );
    let retirement_reason = if temporary_update {
        ProviderWorkerRetirement::TemporaryUpdate
    } else {
        ProviderWorkerRetirement::EnclaveSwitch
    };
    let drain = if args.tx.sim {
        Value::Null
    } else {
        drain_supervised_provider_workers(
            &home,
            &ctx.wallet.public_key,
            std::slice::from_ref(&old_worker),
            Some(&old_worker.enclave_id),
            Duration::from_secs(args.timeout_seconds),
        )
        .await?
    };
    let retirement = retire_provider_registrations(
        &ctx,
        &contract,
        std::slice::from_ref(&old_worker.enclave_id),
        retirement_reason,
        args.tx.sim,
    )
    .await?;
    let (removed, added) = if args.tx.sim {
        (Value::Null, Value::Null)
    } else {
        let removed = remove_supervised_provider_worker(
            &client,
            &supervisor_url,
            &control_token,
            &old_worker,
        )
        .await?;
        if sequencing.clear_completed_scoped_drain_before_add {
            clear_completed_provider_drain_request(
                &home,
                &ctx.wallet.public_key,
                &old_worker,
                &drain,
            )?;
        }
        let added = add_prepared_provider_worker(&client, prepared).await?;
        (removed, added)
    };
    let report = json!({
        "ok": true,
        "action": "provider.serve.switch",
        "home": home,
        "supervisor_url": supervisor_url,
        "target": args.target,
        "old_worker": old_worker,
        "new_enclave_id": requested_enclave.enclave_id,
        "temporary_update": temporary_update,
        "durable_registration_preserved": temporary_update,
        "sequencing": sequencing,
        "sim": args.tx.sim,
        "drain": drain,
        "retirement": retirement,
        "removed": removed,
        "added": added,
    });
    if args.tx.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "Provider worker switched: {} -> {}",
            report["old_worker"]["enclave_id"].as_str().unwrap_or(""),
            report["added"]["enclave"]
                .as_str()
                .unwrap_or_else(|| { report["new_enclave_id"].as_str().unwrap_or("") })
        );
    }
    Ok(())
}

fn mayhemd_control_url(home: &Path) -> Result<String> {
    mayhemd_control_url_if_running(home)?
        .context("mayhemd is not running; start it with `mayhem up` first")
}

fn mayhemd_control_url_if_running(home: &Path) -> Result<Option<String>> {
    let Some(_pid) = read_pid_file(&mayhemd_pid_path(home))?.filter(|pid| process_is_running(*pid))
    else {
        return Ok(None);
    };
    let state = read_json_file_if_exists(&mayhemd_state_path(home))?;
    let bind = supervisor_bind_from_home(home, state.as_ref())
        .context("could not determine mayhemd supervisor bind address")?;
    Ok(Some(format!("http://{bind}")))
}

fn provider_serve_child_config(
    home: &Path,
    enclave: &str,
    backend: &str,
    runtime: &ProviderBackendRuntime,
    vllm_memory_utilization: Option<&VllmMemoryUtilizationPlan>,
    gpu_layers: Option<u32>,
    ctx: Option<u64>,
    served_modalities: &[String],
    served_specialities: &BTreeMap<String, Vec<String>>,
    hardware_quote_config: Option<&ProviderHardwareQuoteConfig>,
    name: Option<String>,
) -> Result<Value> {
    let pear_runtime = resolve_pear_runtime_path()
        .context("resolving Pear runtime for supervised provider worker")?;
    provider_serve_child_config_with_pear_runtime(
        home,
        enclave,
        backend,
        runtime,
        vllm_memory_utilization,
        gpu_layers,
        ctx,
        served_modalities,
        served_specialities,
        hardware_quote_config,
        name,
        &pear_runtime,
    )
}

fn provider_serve_child_config_with_pear_runtime(
    home: &Path,
    enclave: &str,
    backend: &str,
    runtime: &ProviderBackendRuntime,
    vllm_memory_utilization: Option<&VllmMemoryUtilizationPlan>,
    gpu_layers: Option<u32>,
    ctx: Option<u64>,
    served_modalities: &[String],
    served_specialities: &BTreeMap<String, Vec<String>>,
    hardware_quote_config: Option<&ProviderHardwareQuoteConfig>,
    name: Option<String>,
    pear_runtime: &Path,
) -> Result<Value> {
    debug_assert!(
        !ProviderWorkerRetirement::Crash.leaves_durable_registration(),
        "supervisor crash restarts must preserve durable provider registration"
    );
    let config_path = config_path_for_home(home);
    let config = read_config_toml_value(&config_path)
        .with_context(|| format!("reading {}", config_path.display()))?;
    let rpc_url = toml_get_path(&config, "network.rpc_url")
        .and_then(toml::Value::as_str)
        .and_then(non_empty_string)
        .unwrap_or_else(|| DEFAULT_RPC_URL.to_owned());
    let sc_bridge_url = toml_get_path(&config, "network.sc_bridge_url")
        .and_then(toml::Value::as_str)
        .and_then(non_empty_string)
        .context("network.sc_bridge_url missing; run `mayhem up` before live provider serve add")?;
    let sc_bridge_token = toml_get_path(&config, "network.sc_bridge_token")
        .and_then(toml::Value::as_str)
        .and_then(non_empty_string)
        .context(
            "network.sc_bridge_token missing; run `mayhem up` before live provider serve add",
        )?;
    let startup_probes = vec![
        format!("{}/health", rpc_url.trim_end_matches('/')),
        format!(
            "tcp://127.0.0.1:{}",
            sc_bridge_port_from_url(&sc_bridge_url)?
        ),
    ];
    let configured_gpu_layers = toml_get_path(&config, "provider.gpu_layers")
        .and_then(toml::Value::as_integer)
        .and_then(|value| u32::try_from(value).ok());
    let mut args = vec![
        "provider".to_owned(),
        "start".to_owned(),
        "--home".to_owned(),
        home.display().to_string(),
        "--rpc-url".to_owned(),
        rpc_url,
        "--sc-bridge-url".to_owned(),
        sc_bridge_url,
        "--serve-sessions".to_owned(),
        "--enclave".to_owned(),
        enclave.to_owned(),
    ];
    append_provider_hardware_quote_args(&mut args, hardware_quote_config);
    if backend == "vllm" {
        let admitted = vllm_memory_utilization.context(
            "vLLM worker is missing its admitted memory utilization; rerun `mayhem up --provider`",
        )?;
        let persisted = configured_provider_vllm_memory_utilization_pct(&config)?.context(
            "provider.limits.vllm_memory_utilization_pct is missing after vLLM admission",
        )?;
        ensure!(
            persisted == admitted.target_pct,
            "persisted vLLM memory utilization {persisted}% does not match the admitted {}%",
            admitted.target_pct
        );
        args.extend([
            "--vllm-memory-utilization".to_owned(),
            persisted.to_string(),
        ]);
    }
    if let Some(gpu_layers) = gpu_layers.or(configured_gpu_layers) {
        args.extend(["--gpu-layers".to_owned(), gpu_layers.to_string()]);
    }
    if let Some(ctx) = ctx.filter(|ctx| *ctx > 0) {
        args.extend(["--ctx".to_owned(), ctx.to_string()]);
    }
    let catalog_modalities = served_modalities
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    for modality in ["text", "embedding", "image", "video", "audio"] {
        if !catalog_modalities.contains(modality) {
            args.extend(["--disable-modality".to_owned(), modality.to_owned()]);
        }
    }
    for (speciality, levels) in served_specialities {
        ensure!(
            !levels.is_empty(),
            "provider speciality {speciality} has no served levels"
        );
        args.extend([
            "--speciality-levels".to_owned(),
            format!("{speciality}={}", levels.join(",")),
        ]);
    }
    let mayhem_path = env::current_exe().context("resolving current mayhem binary")?;
    let mut runtime_env = provider_backend_runtime_child_env(backend, runtime);
    runtime_env.insert(
        "MAYHEM_PEAR_RUNTIME".to_owned(),
        pear_runtime.display().to_string(),
    );
    runtime_env.insert("MAYHEM_SC_BRIDGE_TOKEN".to_owned(), sc_bridge_token);
    Ok(json!({
        "name": name.unwrap_or_else(|| format!("provider-live-{}", up_provider_worker_slug(enclave))),
        "command": mayhem_path.display().to_string(),
        "args": args,
        "env": runtime_env,
        "restart": true,
        "restart_backoff_ms": 1000,
        "restart_stable_after_ms": MAYHEMD_RESTART_STABLE_AFTER_MILLIS,
        "crash_loop_threshold": MAYHEMD_CRASH_LOOP_THRESHOLD,
        "startup_probes": startup_probes,
    }))
}

fn append_provider_hardware_quote_args(
    args: &mut Vec<String>,
    config: Option<&ProviderHardwareQuoteConfig>,
) {
    let Some(config) = config else {
        return;
    };
    args.extend([
        "--hardware-quote-kind".to_owned(),
        hardware_quote_kind_name(&config.kind),
        "--hardware-quote-command".to_owned(),
        config.command.display().to_string(),
        "--hardware-quote-timeout-seconds".to_owned(),
        config.timeout.as_secs().to_string(),
    ]);
}

fn provider_backend_runtime_child_env(
    backend: &str,
    runtime: &ProviderBackendRuntime,
) -> BTreeMap<String, String> {
    let mut child_env = BTreeMap::new();
    let mut insert_path = |name: &str, path: Option<&Path>| {
        if let Some(path) = path {
            child_env.insert(name.to_owned(), path.display().to_string());
        }
    };
    match backend {
        "llama.cpp" => {
            insert_path("MAYHEM_LLAMA_MEDIA_PYTHON", runtime.python.as_deref());
        }
        "vllm" => {
            insert_path("MAYHEM_VLLM_PYTHON", runtime.python.as_deref());
            insert_path("MAYHEM_VLLM_CACHE_DIR", runtime.cache_dir.as_deref());
            insert_path("MAYHEM_VLLM_CUDA_HOME", runtime.cuda_home.as_deref());
        }
        "trt-llm" => {
            insert_path("MAYHEM_TRTLLM_PYTHON", runtime.python.as_deref());
            insert_path("MAYHEM_TRTLLM_CACHE_DIR", runtime.cache_dir.as_deref());
            insert_path("MAYHEM_TRTLLM_CUDA_HOME", runtime.cuda_home.as_deref());
        }
        "mlx" => insert_path("MAYHEM_MLX_PYTHON", runtime.python.as_deref()),
        "ace-step" => insert_path("MAYHEM_ACE_STEP_PYTHON", runtime.python.as_deref()),
        "chatterbox" => {
            if runtime.python_source.as_deref() == Some("explicit MAYHEM_CHATTERBOX_PYTHON") {
                insert_path("MAYHEM_CHATTERBOX_PYTHON", runtime.python.as_deref());
            }
            if let Some(device) = runtime.chatterbox_device {
                child_env.insert(
                    "MAYHEM_CHATTERBOX_DEVICE".to_owned(),
                    device.as_str().to_owned(),
                );
            }
        }
        "needle-cpu" | "needle-gpu" => {
            insert_path("MAYHEM_NEEDLE_PYTHON", runtime.python.as_deref());
            if let Some(device) = needle_device_for_engine(backend) {
                child_env.insert("MAYHEM_NEEDLE_DEVICE".to_owned(), device.to_owned());
            }
        }
        "sulphur" => insert_path("MAYHEM_SULPHUR_PYTHON", runtime.python.as_deref()),
        "transformers-asr" => {
            insert_path("MAYHEM_TRANSFORMERS_ASR_PYTHON", runtime.python.as_deref());
        }
        "stable-diffusion.cpp" => {
            insert_path(
                "MAYHEM_STABLE_DIFFUSION_CPP_BIN",
                runtime.external_binary.as_deref(),
            );
            if let Some(accelerator) = runtime.stable_diffusion_backend.as_ref() {
                child_env.insert(
                    "MAYHEM_STABLE_DIFFUSION_CPP_BACKEND".to_owned(),
                    accelerator.clone(),
                );
            }
        }
        "whisper.cpp" => insert_path("MAYHEM_WHISPER_CPP_BIN", runtime.external_binary.as_deref()),
        "piper" => insert_path("MAYHEM_PIPER_BIN", runtime.external_binary.as_deref()),
        _ => {}
    }
    child_env
}

fn provider_serve_public_child_report(child: &Value) -> Value {
    json!({
        "name": child.get("name"),
        "restart": child.get("restart"),
        "restart_backoff_ms": child.get("restart_backoff_ms"),
        "restart_stable_after_ms": child.get("restart_stable_after_ms"),
        "crash_loop_threshold": child.get("crash_loop_threshold"),
        "startup_probes": child.get("startup_probes"),
    })
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
struct SupervisedProviderWorker {
    name: String,
    enclave_id: String,
    running: bool,
    pid: Option<u32>,
}

fn supervisor_child_is_provider_start(child: &Value) -> bool {
    let args = child
        .get("args")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .take(2)
        .collect::<Vec<_>>();
    args.as_slice() == ["provider", "start"]
}

fn supervised_running_provider_child_count(status: &Value) -> usize {
    status
        .get("children")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|children| children.values())
        .filter(|child| {
            supervisor_child_is_provider_start(child)
                && child.get("running").and_then(Value::as_bool) == Some(true)
        })
        .count()
}

fn supervised_provider_workers(status: &Value) -> Vec<SupervisedProviderWorker> {
    let children = status
        .get("children")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|children| children.values());
    let mut workers = children
        .filter_map(|child| {
            if !supervisor_child_is_provider_start(child) {
                return None;
            }
            let name = child.get("name").and_then(Value::as_str)?.to_owned();
            let args = child
                .get("args")
                .and_then(Value::as_array)?
                .iter()
                .filter_map(Value::as_str)
                .collect::<Vec<_>>();
            let enclave_id = args
                .windows(2)
                .find(|pair| pair[0] == "--enclave")
                .map(|pair| pair[1].to_owned())?;
            Some(SupervisedProviderWorker {
                name,
                enclave_id,
                running: child.get("running").and_then(Value::as_bool) == Some(true),
                pid: child
                    .get("pid")
                    .and_then(Value::as_u64)
                    .and_then(|pid| u32::try_from(pid).ok())
                    .filter(|pid| *pid > 0),
            })
        })
        .collect::<Vec<_>>();
    workers.sort_by(|a, b| {
        a.enclave_id
            .cmp(&b.enclave_id)
            .then_with(|| a.name.cmp(&b.name))
    });
    workers
}

fn provider_serve_worker_for_target(
    status: &Value,
    serves: &[LedgerServe],
    target: &str,
) -> Result<SupervisedProviderWorker> {
    let workers = supervised_provider_workers(status);
    let model_enclaves = serves
        .iter()
        .filter(|serve| serve.status == "active" && serve.model_id == target)
        .map(|serve| serve.enclave_id.as_str())
        .collect::<BTreeSet<_>>();
    let matches = workers
        .into_iter()
        .filter(|worker| {
            worker.name == target
                || worker.enclave_id == target
                || model_enclaves.contains(worker.enclave_id.as_str())
        })
        .collect::<Vec<_>>();
    match matches.as_slice() {
        [worker] => Ok(worker.clone()),
        [] => bail!("no running supervised provider worker found for {target}"),
        _ => bail!("multiple supervised provider workers matched {target}"),
    }
}

async fn remove_supervised_provider_worker(
    client: &reqwest::Client,
    supervisor_url: &str,
    control_token: &str,
    worker: &SupervisedProviderWorker,
) -> Result<Value> {
    let response = post_mayhemd_json(
        client,
        &format!("{supervisor_url}/children/remove"),
        &json!({ "name": worker.name }),
        control_token,
    )
    .await
    .with_context(|| format!("removing provider worker {} from mayhemd", worker.name))?;
    if let Some(pid) = worker.pid {
        ensure!(
            wait_for_process_stop(pid, Duration::from_secs(10)).await,
            "provider worker {} pid {} did not stop after supervisor removal",
            worker.name,
            pid
        );
    }
    Ok(response)
}

