fn provider_progress_enabled(args: &ProviderStartArgs) -> bool {
    !args.print_json
        && (io::stderr().is_terminal() || env::var_os("MAYHEM_PROVIDER_START_PROGRESS").is_some())
}

struct ProviderProgressBars {
    enabled: bool,
    label: String,
    load_progress: Option<ProviderLoadProgressContext>,
    phase: Option<ProgressPhase>,
    bar: Option<ProgressBar>,
    last_position: u64,
    last_total: Option<u64>,
}

impl ProviderProgressBars {
    fn new(args: &ProviderStartArgs, label: impl Into<String>) -> Self {
        Self {
            enabled: provider_progress_enabled(args),
            label: label.into(),
            load_progress: args.load_progress.clone(),
            phase: None,
            bar: None,
            last_position: 0,
            last_total: None,
        }
    }

    fn update(&mut self, event: ProgressEvent) {
        if self.phase != Some(event.phase) {
            self.finish_current();
            self.phase = Some(event.phase);
            if self.enabled {
                self.bar = Some(provider_progress_bar(
                    event.total,
                    format!("{} {}", self.label, progress_phase_label(event.phase)),
                ));
            }
        }
        let phase_label = progress_phase_label(event.phase);
        if let Some(load_progress) = &self.load_progress {
            let _ = write_provider_load_progress(
                load_progress,
                &self.label,
                phase_label,
                "running",
                Some(event.position),
                event.total,
            );
        }
        self.last_position = event.position;
        self.last_total = event.total;
        if !self.enabled {
            return;
        }
        if let Some(bar) = &self.bar {
            if let Some(total) = event.total {
                bar.set_length(total);
            }
            bar.set_position(event.position);
        }
    }

    fn finish_current(&mut self) {
        if let Some(phase) = self.phase.take() {
            if let Some(load_progress) = &self.load_progress {
                let _ = write_provider_load_progress(
                    load_progress,
                    &self.label,
                    progress_phase_label(phase),
                    "complete",
                    Some(self.last_position),
                    self.last_total,
                );
            }
        }
        if let Some(bar) = self.bar.take() {
            bar.finish_and_clear();
        }
    }

    fn finish(mut self) {
        self.finish_current();
    }
}

struct HuggingFaceProviderProgress {
    label: String,
    load_progress: Option<ProviderLoadProgressContext>,
    bar: Option<ProgressBar>,
    position: AtomicU64,
    total: AtomicU64,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct HuggingFaceXetConnection {
    access_token: String,
    cas_url: String,
    exp: u64,
}

impl HuggingFaceProviderProgress {
    fn new(args: &ProviderStartArgs, label: impl Into<String>, expected_total: u64) -> Self {
        let label = label.into();
        let progress = Self {
            bar: provider_progress_enabled(args)
                .then(|| provider_progress_bar(Some(expected_total), format!("{label} download"))),
            label,
            load_progress: args.load_progress.clone(),
            position: AtomicU64::new(0),
            total: AtomicU64::new(expected_total),
        };
        progress.record(0, expected_total, "running");
        progress
    }

    fn record(&self, position: u64, total: u64, status: &str) {
        let total = total.max(self.total.load(Ordering::Relaxed));
        self.total.store(total, Ordering::Relaxed);
        let previous = self.position.fetch_max(position, Ordering::Relaxed);
        let position = position.max(previous);
        if let Some(bar) = &self.bar {
            if total > 0 {
                bar.set_length(total);
            }
            bar.set_position(position);
        }
        if let Some(load_progress) = &self.load_progress {
            let _ = write_provider_load_progress(
                load_progress,
                &self.label,
                "download",
                status,
                Some(position),
                (total > 0).then_some(total),
            );
        }
    }

    fn finish(&self, succeeded: bool) {
        let total = self.total.load(Ordering::Relaxed);
        let position = if succeeded {
            total
        } else {
            self.position.load(Ordering::Relaxed)
        };
        self.record(
            position,
            total,
            if succeeded { "complete" } else { "failed" },
        );
        if let Some(bar) = &self.bar {
            if succeeded {
                bar.finish_and_clear();
            } else {
                bar.abandon_with_message(format!("{} download failed", self.label));
            }
        }
    }
}

impl HfProgressHandler for HuggingFaceProviderProgress {
    fn on_progress(&self, event: &HfProgressEvent) {
        let HfProgressEvent::Download(event) = event else {
            return;
        };
        match event {
            HfDownloadEvent::Start { total_bytes, .. } => self.record(0, *total_bytes, "running"),
            HfDownloadEvent::Progress { files } => {
                if let Some(file) = files.iter().max_by_key(|file| file.bytes_completed) {
                    self.record(file.bytes_completed, file.total_bytes, "running");
                }
            }
            HfDownloadEvent::AggregateProgress {
                bytes_completed,
                total_bytes,
                ..
            } => self.record(*bytes_completed, *total_bytes, "running"),
            HfDownloadEvent::Complete => {
                let total = self.total.load(Ordering::Relaxed);
                self.record(total, total, "complete");
            }
        }
    }
}

fn progress_phase_label(phase: ProgressPhase) -> &'static str {
    match phase {
        ProgressPhase::Download => "download",
        ProgressPhase::Verify => "verify",
    }
}

fn provider_progress_bar(total: Option<u64>, message: String) -> ProgressBar {
    let bar = match total {
        Some(total) => ProgressBar::new(total),
        None => ProgressBar::new_spinner(),
    };
    if total.is_some() {
        let style = ProgressStyle::with_template(
            "{spinner:.green} {msg} [{bar:40.cyan/blue}] {bytes}/{total_bytes} eta {eta_precise}",
        )
        .unwrap_or_else(|_| ProgressStyle::default_bar())
        .progress_chars("=> ");
        bar.set_style(style);
    } else {
        let style =
            ProgressStyle::with_template("{spinner:.green} {msg} {bytes} {elapsed_precise}")
                .unwrap_or_else(|_| ProgressStyle::default_spinner());
        bar.set_style(style);
        bar.enable_steady_tick(Duration::from_millis(100));
    }
    bar.set_message(message);
    bar
}

fn provider_progress_spinner(
    args: &ProviderStartArgs,
    message: impl Into<String>,
) -> Option<ProgressBar> {
    if !provider_progress_enabled(args) {
        return None;
    }
    let bar = ProgressBar::new_spinner();
    let style = ProgressStyle::with_template("{spinner:.green} {msg} {elapsed_precise}")
        .unwrap_or_else(|_| ProgressStyle::default_spinner());
    bar.set_style(style);
    bar.set_message(message.into());
    bar.enable_steady_tick(Duration::from_millis(100));
    Some(bar)
}

fn with_provider_progress_spinner<T, F>(
    args: &ProviderStartArgs,
    message: impl Into<String>,
    run: F,
) -> Result<T>
where
    F: FnOnce() -> Result<T>,
{
    let message = message.into();
    write_provider_load_progress_stage(args, &message, "load", "running", 0);
    let bar = provider_progress_spinner(args, message.clone());
    let result = run();
    write_provider_load_progress_stage(
        args,
        &message,
        "load",
        if result.is_ok() { "complete" } else { "error" },
        if result.is_ok() { 100 } else { 0 },
    );
    if let Some(bar) = bar {
        if result.is_ok() {
            bar.finish_and_clear();
        } else {
            bar.abandon();
        }
    }
    result
}

#[derive(Clone, Debug)]
struct ProviderLoadProgressContext {
    dir: PathBuf,
    provider: String,
    model_id: String,
    enclave_id: String,
    artifact: String,
}

#[derive(Serialize)]
struct ProviderLoadProgressReport<'a> {
    schema: u32,
    pid: u32,
    provider: &'a str,
    model_id: &'a str,
    enclave_id: &'a str,
    artifact: &'a str,
    label: &'a str,
    phase: &'a str,
    status: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    error: Option<&'a str>,
    position: Option<u64>,
    total: Option<u64>,
    percent: Option<u64>,
    updated_at_ms: u64,
}

impl ProviderLoadProgressContext {
    fn new(home: &Path, provider: &str, selected: &ProviderCandidate) -> Self {
        Self {
            dir: home.join("provider-load-progress"),
            provider: provider.to_owned(),
            model_id: selected.enclave.model_id.clone(),
            enclave_id: selected.enclave.enclave_id.clone(),
            artifact: selected.artifact_name.clone(),
        }
    }

    fn path(&self) -> PathBuf {
        self.dir.join(format!(
            "{}-{}.json",
            safe_path_component(&self.provider),
            safe_path_component(&self.enclave_id)
        ))
    }
}

fn write_provider_load_progress_stage(
    args: &ProviderStartArgs,
    label: &str,
    phase: &str,
    status: &str,
    percent: u64,
) {
    if let Some(load_progress) = &args.load_progress {
        let percent = percent.min(100);
        let _ = write_provider_load_progress(
            load_progress,
            label,
            phase,
            status,
            Some(percent),
            Some(100),
        );
    }
}

fn write_provider_load_progress(
    ctx: &ProviderLoadProgressContext,
    label: &str,
    phase: &str,
    status: &str,
    position: Option<u64>,
    total: Option<u64>,
) -> Result<()> {
    write_provider_load_progress_report(ctx, label, phase, status, position, total, None)
}

fn write_provider_load_progress_report(
    ctx: &ProviderLoadProgressContext,
    label: &str,
    phase: &str,
    status: &str,
    position: Option<u64>,
    total: Option<u64>,
    error: Option<&str>,
) -> Result<()> {
    let percent = provider_load_progress_percent(position, total);
    let updated_at_ms = unix_epoch_millis().unwrap_or(0);
    let report = ProviderLoadProgressReport {
        schema: 1,
        pid: std::process::id(),
        provider: &ctx.provider,
        model_id: &ctx.model_id,
        enclave_id: &ctx.enclave_id,
        artifact: &ctx.artifact,
        label,
        phase,
        status,
        error,
        position,
        total,
        percent,
        updated_at_ms,
    };
    write_json_file(&ctx.path(), &report)
}

fn write_provider_load_progress_failure(args: &ProviderStartArgs, error: &anyhow::Error) {
    let Some(ctx) = args.load_progress.as_ref() else {
        return;
    };
    let current = read_json_file(&ctx.path()).unwrap_or(Value::Null);
    let label = current
        .get("label")
        .and_then(Value::as_str)
        .unwrap_or("provider start");
    let phase = current
        .get("phase")
        .and_then(Value::as_str)
        .unwrap_or("prepare");
    let position = current.get("position").and_then(Value::as_u64);
    let total = current.get("total").and_then(Value::as_u64);
    let detail = provider_load_progress_error_detail(ctx, error);
    let _ = write_provider_load_progress_report(
        ctx,
        label,
        phase,
        "error",
        position,
        total,
        Some(&detail),
    );
}

fn provider_load_progress_error_detail(
    ctx: &ProviderLoadProgressContext,
    error: &anyhow::Error,
) -> String {
    let mut detail = error
        .to_string()
        .chars()
        .map(|character| {
            if character.is_control() {
                ' '
            } else {
                character
            }
        })
        .collect::<String>();
    if let Some(home) = ctx.dir.parent().and_then(Path::to_str) {
        detail = detail.replace(home, "$MAYHEM_HOME");
    }
    let detail = detail
        .split_whitespace()
        .map(|part| {
            if part.starts_with("sk-") || part.starts_with("Bearer") {
                "[redacted]"
            } else {
                part
            }
        })
        .collect::<Vec<_>>()
        .join(" ");
    let detail = detail.chars().take(240).collect::<String>();
    if detail.is_empty() {
        "Provider start failed; inspect the CLI output.".to_owned()
    } else {
        detail
    }
}

fn provider_load_progress_percent(position: Option<u64>, total: Option<u64>) -> Option<u64> {
    match (position, total) {
        (Some(position), Some(total)) if total > 0 => {
            Some(((u128::from(position) * 100) / u128::from(total)).min(100) as u64)
        }
        _ => None,
    }
}

fn validate_provider_start_security_mode(
    args: &ProviderStartArgs,
    debug_build: bool,
) -> Result<()> {
    if args.serve_sessions && args.dev_session_shim && !debug_build {
        bail!(
            "--dev-session-shim is debug-build only and cannot serve from an admin-trusted release binary"
        );
    }
    if args.serve_sessions && args.dev_skip_catalog_verify && !debug_build {
        bail!(
            "--serve-sessions requires a signed admin catalog in release builds; --dev-skip-catalog-verify is smoke-test only"
        );
    }
    Ok(())
}

fn provider_session_debug(message: impl AsRef<str>) {
    if std::env::var_os("MAYHEM_PROVIDER_SESSION_DEBUG").is_some() {
        eprintln!("[provider-session] {}", message.as_ref());
    }
}

fn verify_or_hash_catalog(args: &ProviderStartArgs, catalog_path: &Path) -> Result<String> {
    if args.dev_skip_catalog_verify {
        let bytes = fs::read(catalog_path)
            .with_context(|| format!("reading {}", catalog_path.display()))?;
        return Ok(blake3::hash(&bytes).to_hex().to_string());
    }

    let signature_path = args
        .signature_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
    let keys_dir = args
        .keys_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let canaries_dir = args
        .canaries_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let report = catalog::verify(catalog::VerifyOptions {
        catalog_path: catalog_path.to_path_buf(),
        signature_path: absolutize(signature_path)?,
        keys_dir: absolutize(keys_dir)?,
        canaries_dir: absolutize(canaries_dir)?,
        check_dev_downloads: false,
        check_launch_sources: false,
        hf_token_file: None,
    })?;
    if !report.ok {
        bail!("catalog verification failed: {}", report.errors.join("; "));
    }
    Ok(report.catalog_hash)
}

fn provider_start_uses_local_catalog(args: &ProviderStartArgs) -> bool {
    args.dev_skip_catalog_verify
        || args.catalog_path.is_some()
        || args.signature_path.is_some()
        || args.keys_dir.is_some()
        || args.canaries_dir.is_some()
}

async fn resolve_provider_start_catalog(
    args: &ProviderStartArgs,
    home: &Path,
    rpc: &PeerRpcClient,
    rpc_url: &str,
) -> Result<ProviderResolvedCatalog> {
    if provider_start_uses_local_catalog(args) {
        let catalog_path = args
            .catalog_path
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("catalog/models.json"))?;
        let catalog_path = absolutize(catalog_path)?;
        let canaries_dir = args
            .canaries_dir
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("catalog/canaries"))?;
        let canaries_dir = absolutize(canaries_dir)?;
        let catalog_hash = verify_or_hash_catalog(args, &catalog_path)?;
        let catalog_doc = catalog::load_document(&catalog_path)?;
        let trust = if args.dev_skip_catalog_verify {
            "local-unverified-dev"
        } else {
            "local-signed-override"
        };
        return Ok(ProviderResolvedCatalog {
            catalog_path,
            canaries_dir,
            catalog_hash,
            catalog_doc,
            source: format!("{trust}:{rpc_url}"),
        });
    }

    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()
        .context("building provider catalog release HTTP client")?;
    let release = read_catalog_release_anchor(rpc).await?;
    let files = fetch_catalog_release_files(&client, home, &release).await?;
    let catalog_doc = catalog::load_document(&files.catalog_path).with_context(|| {
        format!(
            "loading verified ledger catalog {}",
            files.catalog_path.display()
        )
    })?;
    Ok(ProviderResolvedCatalog {
        catalog_path: files.catalog_path,
        canaries_dir: files.canaries_dir,
        catalog_hash: release.catalog_hash.clone(),
        catalog_doc,
        source: format!("ledger-catalog-current:{rpc_url}:{}", release.catalog_hash),
    })
}

fn provider_hwprobe(args: &ProviderStartArgs) -> Result<HardwareReport> {
    let fixture = args
        .fixture
        .as_deref()
        .map(|value| {
            FixtureProfile::parse(value).with_context(|| {
                format!(
                    "unknown fixture {value}; expected apple-silicon, linux-nvidia, or cpu-only"
                )
            })
        })
        .transpose()?;
    let mut options = ProbeOptions::default();
    if let Some(path) = &args.disk_path {
        options.disk_path = absolutize(path.clone())?;
    }
    options.run_disk_bench = !args.skip_disk_bench;
    options.fixture = fixture;
    Ok(probe(options))
}

fn provider_hardware_fingerprint(hardware: &HardwareReport) -> String {
    let mut gpus = hardware
        .gpus
        .iter()
        .map(|gpu| {
            json!({
                "vendor": gpu.vendor.clone(),
                "name": gpu.name.clone(),
                "backend": gpu.backend.clone(),
                "memory_bytes": gpu.memory_bytes,
                "dedicated_memory_bytes": gpu.dedicated_memory_bytes,
                "shared_memory_bytes": gpu.shared_memory_bytes,
                "unified_memory": gpu.unified_memory,
                "compute_capability": gpu.compute_capability.clone(),
                "supports_nvfp4": gpu.supports_nvfp4,
                "supports_fp8": gpu.supports_fp8,
                "supports_tensor_parallel": gpu.supports_tensor_parallel,
            })
        })
        .collect::<Vec<_>>();
    gpus.sort_by_key(|gpu| stable_json_value(gpu).to_string());
    stable_value_hash(&json!({
        "domain": "mayhem-provider-hw-fingerprint-v1",
        "schema_version": hardware.schema_version,
        "source_kind": hardware.source.kind.clone(),
        "host": {
            "os": hardware.host.os.clone(),
            "arch": hardware.host.arch.clone(),
            "family": hardware.host.family.clone(),
        },
        "cpu": {
            "model": hardware.cpu.model.clone(),
            "physical_cores": hardware.cpu.physical_cores,
            "logical_cores": hardware.cpu.logical_cores,
            "flags": hardware.cpu.flags.clone(),
        },
        "memory": {
            "total_bytes": hardware.memory.total_bytes,
            "unified_memory": hardware.memory.unified_memory,
        },
        "gpus": gpus,
    }))
}

async fn read_contract_catalog(rpc: &PeerRpcClient) -> Result<ContractCatalog> {
    let prices = read_prefix_entries(rpc, "price/")
        .await?
        .into_iter()
        .filter(|entry| {
            entry
                .key
                .strip_prefix("price/")
                .is_some_and(is_price_schedule_tail)
        })
        .map(|entry| serde_json::from_value(entry.value).context("parsing price schedule"))
        .collect::<Result<Vec<LedgerPriceSchedule>>>()?;
    let price_derivations = read_prefix_entries(rpc, "ev/price/")
        .await?
        .into_iter()
        .filter(|entry| {
            entry
                .key
                .strip_prefix("ev/price/")
                .is_some_and(is_price_derivation_tail)
        })
        .map(|entry| entry.value)
        .collect::<Vec<_>>();
    let ctx_bracket_schedule = read_ctx_bracket_schedule(rpc).await?;
    let active_billing_epoch = active_billing_epoch(rpc).await?;
    let active_payout_revisions =
        read_active_provider_payout_revisions(rpc, active_billing_epoch).await?;
    Ok(ContractCatalog {
        enclaves: read_prefix_values_filtered(rpc, "enclave/", |tail| !tail.contains('/')).await?,
        rooms: read_prefix_values_filtered(rpc, "room/", |tail| !tail.contains('/')).await?,
        roomserve: read_prefix_values(rpc, "roomserve/").await?,
        serves: read_prefix_values(rpc, "serve/").await?,
        providers: read_prefix_values_filtered(rpc, "prov/", |tail| !tail.contains('/')).await?,
        reputations: read_prefix_values_filtered(rpc, "rep/", |tail| !tail.contains('/')).await?,
        kyb: read_prefix_values_filtered(rpc, "kyb/", |tail| !tail.contains('/')).await?,
        prices,
        price_derivations,
        tier3_measurements: read_prefix_values_filtered(rpc, "tier3/measurement/", |tail| {
            !tail.contains('/')
        })
        .await?,
        ctx_bracket_schedule,
        rules: read_state_value(rpc, "rules/current")
            .await?
            .map(serde_json::from_value)
            .transpose()
            .context("parsing rules/current")?,
        active_billing_epoch,
        active_payout_revisions,
    })
}

async fn read_active_provider_payout_revisions(
    rpc: &PeerRpcClient,
    active_epoch: u64,
) -> Result<BTreeMap<String, BTreeMap<String, String>>> {
    let mut revisions = BTreeMap::<String, BTreeMap<String, String>>::new();
    for entry in read_prefix_entries(rpc, "payout/current/").await? {
        let Some(tail) = entry.key.strip_prefix("payout/current/") else {
            continue;
        };
        let parts = tail.split('/').collect::<Vec<_>>();
        let [rail, provider] = parts.as_slice() else {
            continue;
        };
        if !matches!(*rail, "fiat" | "tap" | "tnk")
            || !is_hex_len(provider, 64)
            || *provider != provider.to_ascii_lowercase()
        {
            continue;
        }
        let Some(revision) = payout_pointer_revision_at_epoch(&entry.value, active_epoch) else {
            continue;
        };
        if !is_hex_len(revision, 64) || revision != revision.to_ascii_lowercase() {
            continue;
        }
        let binding_key = format!("payout/binding/{rail}/{provider}/{revision}");
        let Some(binding) = read_state_value(rpc, &binding_key).await? else {
            continue;
        };
        if binding.get("verified").and_then(Value::as_bool) != Some(true)
            || binding.get("provider").and_then(Value::as_str) != Some(*provider)
            || binding.get("rail").and_then(Value::as_str) != Some(*rail)
            || binding.get("revision").and_then(Value::as_str) != Some(revision)
            || !binding
                .get("activation_epoch")
                .and_then(Value::as_u64)
                .is_some_and(|activation_epoch| activation_epoch <= active_epoch)
        {
            continue;
        }
        if *rail == "fiat" {
            let Some(target) = binding.get("target").and_then(Value::as_str) else {
                continue;
            };
            let verification_pointer_key =
                format!("payout/stripe-verified/target/{provider}/{target}");
            let Some(verification_pointer) =
                read_state_value(rpc, &verification_pointer_key).await?
            else {
                continue;
            };
            let Some(record_key) = verification_pointer
                .get("record_key")
                .and_then(Value::as_str)
            else {
                continue;
            };
            let Some(verification) = read_state_value(rpc, record_key).await? else {
                continue;
            };
            if verification_pointer.get("ready").and_then(Value::as_bool) != Some(true)
                || verification.get("ready").and_then(Value::as_bool) != Some(true)
                || verification.get("provider").and_then(Value::as_str) != Some(*provider)
                || verification.get("target").and_then(Value::as_str)
                    != binding.get("target").and_then(Value::as_str)
                || verification.get("currency").and_then(Value::as_str)
                    != binding.get("currency").and_then(Value::as_str)
                || verification
                    .get("processor_revision")
                    .and_then(Value::as_str)
                    != binding
                        .get("stripe_processor_revision")
                        .and_then(Value::as_str)
            {
                continue;
            }
        }
        revisions
            .entry((*provider).to_owned())
            .or_default()
            .insert((*rail).to_owned(), revision.to_owned());
    }
    Ok(revisions)
}

fn provider_routable_payout_rails(
    provider: &LedgerProvider,
    active_payout_revisions: &BTreeMap<String, BTreeMap<String, String>>,
) -> Vec<String> {
    let revisions = active_payout_revisions.get(&provider.provider);
    provider
        .accepted_rails
        .iter()
        .filter(|rail| revisions.is_some_and(|entries| entries.contains_key(rail.as_str())))
        .cloned()
        .collect()
}

fn is_price_schedule_tail(tail: &str) -> bool {
    let parts = tail.split('/').collect::<Vec<_>>();
    match parts.as_slice() {
        [enclave] => !enclave.is_empty(),
        [enclave, ctx_bracket] => !enclave.is_empty() && !ctx_bracket.is_empty(),
        _ => false,
    }
}

fn is_price_derivation_tail(tail: &str) -> bool {
    let parts = tail.split('/').collect::<Vec<_>>();
    match parts.as_slice() {
        [epoch, enclave] => epoch.parse::<u64>().is_ok() && !enclave.is_empty(),
        [epoch, enclave, ctx_bracket] => {
            epoch.parse::<u64>().is_ok() && !enclave.is_empty() && !ctx_bracket.is_empty()
        }
        _ => false,
    }
}

async fn read_ctx_bracket_schedule(rpc: &PeerRpcClient) -> Result<CtxBracketSchedule> {
    let schedule = match read_state_value(rpc, "ctx_brackets").await? {
        Some(value) => {
            serde_json::from_value(value).context("parsing contract ctx_brackets schedule")?
        }
        None => default_ctx_bracket_schedule(),
    };
    validate_ctx_bracket_schedule(&schedule)
        .map_err(|err| anyhow::anyhow!("invalid contract ctx_brackets schedule: {err}"))?;
    Ok(schedule)
}

async fn read_prefix_values<T>(rpc: &PeerRpcClient, prefix: &str) -> Result<Vec<T>>
where
    T: DeserializeOwned,
{
    read_prefix_values_filtered(rpc, prefix, |_| true).await
}

async fn read_prefix_values_at<T>(
    rpc: &PeerRpcClient,
    prefix: &str,
    requested_signed_length: Option<u64>,
) -> Result<(u64, Vec<T>)>
where
    T: DeserializeOwned,
{
    let (signed_length, entries) =
        read_prefix_entries_at(rpc, prefix, requested_signed_length).await?;
    let values = entries
        .into_iter()
        .map(|entry| {
            let key = entry.key;
            serde_json::from_value(entry.value)
                .with_context(|| format!("parsing contract state record {key}"))
        })
        .collect::<Result<Vec<_>>>()?;
    Ok((signed_length, values))
}

async fn read_prefix_values_filtered<T, F>(
    rpc: &PeerRpcClient,
    prefix: &str,
    include_tail: F,
) -> Result<Vec<T>>
where
    T: DeserializeOwned,
    F: Fn(&str) -> bool,
{
    read_prefix_entries(rpc, prefix)
        .await?
        .into_iter()
        .filter(|entry| entry.key.strip_prefix(prefix).is_some_and(&include_tail))
        .map(|entry| {
            let key = entry.key;
            serde_json::from_value(entry.value)
                .with_context(|| format!("parsing contract state record {key}"))
        })
        .collect()
}

async fn read_prefix_entries(rpc: &PeerRpcClient, prefix: &str) -> Result<Vec<PrefixStateEntry>> {
    read_prefix_entries_at(rpc, prefix, None)
        .await
        .map(|(_, entries)| entries)
}

async fn read_prefix_entries_at(
    rpc: &PeerRpcClient,
    prefix: &str,
    requested_signed_length: Option<u64>,
) -> Result<(u64, Vec<PrefixStateEntry>)> {
    const PAGE_LIMIT: u64 = 500;

    let mut signed_length = requested_signed_length;
    let mut after = None::<String>;
    let mut entries = Vec::<PrefixStateEntry>::new();
    loop {
        let response = rpc
            .state_prefix_page(
                prefix,
                Some(true),
                Some(PAGE_LIMIT),
                signed_length,
                after.as_deref(),
            )
            .await
            .with_context(|| format!("reading confirmed {prefix}* from peer RPC"))?;
        let parsed: PrefixStateResponse = serde_json::from_value(response)
            .with_context(|| format!("parsing confirmed {prefix}* state response"))?;
        ensure!(
            parsed.prefix == prefix && parsed.confirmed,
            "peer RPC returned a mismatched or unconfirmed {prefix}* page"
        );
        if let Some(expected) = signed_length {
            ensure!(
                parsed.signed_length == expected,
                "peer RPC snapshot drift for {prefix}*: expected signed length {expected}, got {}",
                parsed.signed_length
            );
        } else {
            signed_length = Some(parsed.signed_length);
        }

        for entry in parsed.values {
            ensure!(
                entry.key.starts_with(prefix),
                "peer RPC returned key {} outside prefix {prefix}",
                entry.key
            );
            if let Some(previous) = entries.last() {
                ensure!(
                    entry.key > previous.key,
                    "peer RPC returned a duplicate or non-advancing {prefix}* cursor"
                );
            }
            entries.push(entry);
        }

        if !parsed.truncated {
            ensure!(
                parsed.next_cursor.is_none(),
                "peer RPC returned a cursor for a complete {prefix}* page"
            );
            break;
        }
        let cursor = parsed
            .next_cursor
            .context("peer RPC truncated a state page without a next cursor")?;
        ensure!(
            entries.last().is_some_and(|entry| entry.key == cursor),
            "peer RPC next cursor does not match the last returned key"
        );
        ensure!(
            after.as_ref().is_none_or(|previous| cursor > *previous),
            "peer RPC returned a non-advancing next cursor"
        );
        after = Some(cursor);
    }
    Ok((
        signed_length.context("peer RPC omitted confirmed signed length")?,
        entries,
    ))
}

#[derive(Debug, Clone)]
struct GatewayServedPrice {
    price: LedgerPriceRecord,
    market_key: String,
}

fn gateway_models_from_contract(contract: &ContractCatalog) -> Result<Vec<GatewayModel>> {
    let now = unix_epoch_seconds()?;
    let active_enclaves = contract
        .enclaves
        .iter()
        .filter(|enclave| {
            enclave.status == "active"
                && admin_role_marker_ok(enclave.created_by_role.as_deref())
                && ledger_enclave_identity_is_self_consistent(enclave)
        })
        .map(|enclave| (enclave.enclave_id.clone(), enclave))
        .collect::<BTreeMap<_, _>>();
    let open_rooms = contract
        .rooms
        .iter()
        .filter(|room| {
            room.status == "open"
                && admin_role_marker_ok(room.creator_role.as_deref())
                && canonical_room_transport_ok(room)
        })
        .collect::<Vec<_>>();
    let active_providers = contract
        .providers
        .iter()
        .filter(|provider| provider.status == "active")
        .map(|provider| provider.provider.as_str())
        .collect::<BTreeSet<_>>();
    let active_provider_by_id = contract
        .providers
        .iter()
        .filter(|provider| provider.status == "active")
        .map(|provider| (provider.provider.as_str(), provider))
        .collect::<BTreeMap<_, _>>();
    let reputation_by_provider = contract
        .reputations
        .iter()
        .map(|record| (record.provider.as_str(), record))
        .collect::<BTreeMap<_, _>>();
    let active_kyb_by_provider = contract
        .kyb
        .iter()
        .filter_map(active_provider_kyb_info)
        .filter(|kyb| active_providers.contains(kyb.provider.as_str()))
        .map(|kyb| (kyb.provider.clone(), kyb))
        .collect::<BTreeMap<_, _>>();
    let mut rooms_by_id = BTreeMap::new();
    for room in &open_rooms {
        rooms_by_id.insert(room.room_id.clone(), *room);
    }

    let mut price_history_by_market: BTreeMap<String, Vec<Value>> = BTreeMap::new();
    for derivation in &contract.price_derivations {
        let Some(enclave_id) = derivation.get("enclave_id").and_then(Value::as_str) else {
            continue;
        };
        let ctx_bracket = derivation.get("ctx_bracket").and_then(Value::as_str);
        let market_key = ledger_price_market_key(enclave_id, ctx_bracket);
        price_history_by_market
            .entry(market_key)
            .or_default()
            .push(derivation.clone());
    }
    for history in price_history_by_market.values_mut() {
        history.sort_by_key(price_derivation_sort_key);
        history.dedup_by(|left, right| {
            price_derivation_sort_key(left) == price_derivation_sort_key(right)
        });
        if history.len() > 720 {
            let drop_count = history.len() - 720;
            history.drain(..drop_count);
        }
    }
    let price_derivation_by_market = price_history_by_market
        .iter()
        .filter_map(|(market_key, history)| {
            history
                .last()
                .cloned()
                .map(|derivation| (market_key.clone(), derivation))
        })
        .collect::<BTreeMap<_, _>>();

    let mut prices_by_market = BTreeMap::new();
    for schedule in &contract.prices {
        let Some(price) = current_au_usd_price(schedule) else {
            continue;
        };
        let mut price = price.clone();
        if price.derivation.is_none() {
            let market_key =
                ledger_price_market_key(&schedule.enclave_id, schedule.ctx_bracket.as_deref());
            price.derivation = price_derivation_by_market.get(market_key.as_str()).cloned();
        }
        prices_by_market.insert(
            ledger_price_market_key(&schedule.enclave_id, schedule.ctx_bracket.as_deref()),
            price,
        );
    }

    let active_serves_by_key: BTreeMap<String, &LedgerServe> = contract
        .serves
        .iter()
        .filter(|serve| serve.status == "active")
        .map(|serve| (format!("{}:{}", serve.provider, serve.enclave_id), serve))
        .collect();

    let mut served_price_by_model: BTreeMap<String, GatewayServedPrice> = BTreeMap::new();
    for serving in contract
        .roomserve
        .iter()
        .filter(|serving| serving.status == "active")
    {
        if !active_providers.contains(serving.provider.as_str()) {
            continue;
        }
        let Some(room) = rooms_by_id.get(&serving.room_id) else {
            continue;
        };
        let Some(enclave) = active_enclaves.get(&serving.enclave_id) else {
            continue;
        };
        if !room_matches_enclave(room, enclave) {
            continue;
        }
        let route_caps = gateway_caps_from_contract(&enclave.caps);
        let serving_key = format!("{}:{}", serving.provider, serving.enclave_id);
        let active_serve = active_serves_by_key.get(&serving_key).copied();
        let served_modalities = active_serve
            .map(|serve| serve.served_modalities.clone())
            .unwrap_or_default();
        if served_modalities.is_empty() {
            continue;
        }
        let served_ctx = active_serve
            .and_then(|serve| serve.served_ctx)
            .and_then(|ctx| u32::try_from(ctx).ok())
            .filter(|ctx| *ctx > 0)
            .unwrap_or(route_caps.ctx);
        let price_ctx_bracket = price_ctx_bracket_for_model_class(
            &enclave.model_class,
            u64::from(served_ctx),
            &contract.ctx_bracket_schedule,
            now,
        )?;
        let market_key = ledger_price_market_key(&serving.enclave_id, price_ctx_bracket.as_deref());
        let Some(serving_price) = prices_by_market.get(&market_key) else {
            continue;
        };
        if enclave.model_id != serving.model_id {
            continue;
        }
        served_price_by_model
            .entry(enclave.model_id.clone())
            .and_modify(|existing| {
                if price_sort_key(serving_price) < price_sort_key(&existing.price) {
                    *existing = GatewayServedPrice {
                        price: serving_price.clone(),
                        market_key: market_key.clone(),
                    };
                }
            })
            .or_insert_with(|| GatewayServedPrice {
                price: serving_price.clone(),
                market_key: market_key.clone(),
            });
    }

    let mut providers_by_model: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut tiers_by_model: BTreeMap<String, BTreeMap<String, BTreeSet<String>>> = BTreeMap::new();
    let mut quants_by_model: BTreeMap<String, BTreeMap<String, BTreeSet<String>>> = BTreeMap::new();
    let mut kyb_by_model: BTreeMap<String, BTreeMap<String, ProviderKybInfo>> = BTreeMap::new();
    let mut route_candidates_by_model: BTreeMap<String, BTreeMap<String, GatewayRouteCandidate>> =
        BTreeMap::new();
    for serving in contract
        .roomserve
        .iter()
        .filter(|serving| serving.status == "active")
    {
        if !active_providers.contains(serving.provider.as_str()) {
            continue;
        }
        let Some(room) = rooms_by_id.get(&serving.room_id) else {
            continue;
        };
        let Some(enclave) = active_enclaves.get(&serving.enclave_id) else {
            continue;
        };
        if !room_matches_enclave(room, enclave) {
            continue;
        }
        let route_caps = gateway_caps_from_contract(&enclave.caps);
        let serving_key = format!("{}:{}", serving.provider, serving.enclave_id);
        let active_serve = active_serves_by_key.get(&serving_key).copied();
        let served_modalities = active_serve
            .map(|serve| serve.served_modalities.clone())
            .unwrap_or_default();
        let served_specialities = active_serve
            .map(|serve| serve.served_specialities.clone())
            .unwrap_or_default();
        if served_modalities.is_empty() {
            continue;
        }
        let served_ctx = active_serve
            .and_then(|serve| serve.served_ctx)
            .and_then(|ctx| u32::try_from(ctx).ok())
            .filter(|ctx| *ctx > 0)
            .unwrap_or(route_caps.ctx);
        let price_ctx_bracket = price_ctx_bracket_for_model_class(
            &enclave.model_class,
            u64::from(served_ctx),
            &contract.ctx_bracket_schedule,
            now,
        )?;
        let market_key = ledger_price_market_key(&serving.enclave_id, price_ctx_bracket.as_deref());
        let Some(serving_price) = prices_by_market.get(&market_key) else {
            continue;
        };
        if enclave.model_id != serving.model_id {
            continue;
        }
        let Some(provider_record) = active_provider_by_id.get(serving.provider.as_str()) else {
            continue;
        };
        let accepted_rails =
            provider_routable_payout_rails(provider_record, &contract.active_payout_revisions);
        if accepted_rails.is_empty() {
            continue;
        }
        let payout_revisions = contract
            .active_payout_revisions
            .get(&serving.provider)
            .cloned()
            .unwrap_or_default();
        providers_by_model
            .entry(enclave.model_id.clone())
            .or_default()
            .insert(serving.provider.clone());
        let kyb = active_kyb_by_provider.get(&serving.provider).cloned();
        if let Some(kyb) = &kyb {
            kyb_by_model
                .entry(enclave.model_id.clone())
                .or_default()
                .insert(serving.provider.clone(), kyb.clone());
        }
        let effective_att_tier = kyb.as_ref().map(|_| 4).unwrap_or(enclave.att_tier);
        let reputation = reputation_by_provider.get(serving.provider.as_str());
        route_candidates_by_model
            .entry(enclave.model_id.clone())
            .or_default()
            .insert(
                format!(
                    "{}:{}:{}",
                    serving.provider, serving.room_id, serving.enclave_id
                ),
                GatewayRouteCandidate {
                    provider: serving.provider.clone(),
                    accepted_rails,
                    payout_revisions,
                    served_modalities,
                    served_specialities,
                    enclave_id: serving.enclave_id.clone(),
                    room_id: serving.room_id.clone(),
                    price_ver: serving_price.ver,
                    price_ref_au: Some(gateway_price_ref_from_ledger_with_history(
                        serving_price,
                        price_history_by_market
                            .get(market_key.as_str())
                            .map(Vec::as_slice),
                    )),
                    min_ask_au: 0,
                    att_tier: effective_att_tier,
                    quant: normalize_ledger_quant(&enclave.quant),
                    served_ctx: Some(served_ctx),
                    hardware_fingerprint: active_serve
                        .and_then(|serve| serve.hardware_fingerprint.clone()),
                    device_key: active_serve.and_then(|serve| serve.device_key.clone()),
                    admin_pubkey: enclave.created_by.clone(),
                    artifact_root: enclave.artifact_root.clone(),
                    artifact_sidecar_roots: enclave_artifact_sidecar_roots(enclave),
                    manifest_hash: enclave.manifest_hash.clone(),
                    binary_hash: enclave.binary_hash.clone(),
                    approved_binary_hashes: enclave_approved_binary_hashes(enclave),
                    launch_measurements: launch_measurements_with_tier3_registry(
                        enclave,
                        &contract.tier3_measurements,
                    ),
                    kyb,
                    reputation_bps: reputation
                        .map(|record| record.r_bps.min(10_000))
                        .unwrap_or(10_000),
                    probation: reputation.and_then(|record| record.probation.clone()),
                    caps: enclave.caps.clone(),
                    local_run: None,
                },
            );
        let tier = format!("T{effective_att_tier}");
        tiers_by_model
            .entry(enclave.model_id.clone())
            .or_default()
            .entry(tier)
            .or_default()
            .insert(serving.provider.clone());
        let quant = normalize_ledger_quant(&enclave.quant);
        quants_by_model
            .entry(enclave.model_id.clone())
            .or_default()
            .entry(quant)
            .or_default()
            .insert(serving.provider.clone());
    }

    let mut markets_by_model: BTreeMap<String, BTreeMap<String, GatewayMarketInfo>> =
        BTreeMap::new();
    let mut listed_price_by_model: BTreeMap<String, GatewayServedPrice> = BTreeMap::new();
    let mut market_rooms_by_model: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut caps_by_model: BTreeMap<String, ModelCaps> = BTreeMap::new();
    let mut class_by_model: BTreeMap<String, String> = BTreeMap::new();
    for schedule in &contract.prices {
        let Some(enclave) = active_enclaves.get(&schedule.enclave_id) else {
            continue;
        };
        if schedule.model_id != enclave.model_id {
            continue;
        }
        let market_key =
            ledger_price_market_key(&schedule.enclave_id, schedule.ctx_bracket.as_deref());
        let Some(price) = prices_by_market.get(&market_key) else {
            continue;
        };
        let room_ids = open_rooms
            .iter()
            .filter(|room| room_matches_enclave(room, enclave))
            .map(|room| room.room_id.clone())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        if room_ids.is_empty() {
            continue;
        }

        let enclave_caps = gateway_caps_from_contract(&enclave.caps);
        let mut route_count = 0usize;
        let mut market_providers = BTreeSet::new();
        for candidate in route_candidates_by_model
            .get(&enclave.model_id)
            .into_iter()
            .flat_map(BTreeMap::values)
        {
            if candidate.enclave_id != enclave.enclave_id || !room_ids.contains(&candidate.room_id)
            {
                continue;
            }
            let served_ctx = candidate.served_ctx.unwrap_or(enclave_caps.ctx);
            let candidate_ctx_bracket = price_ctx_bracket_for_model_class(
                &enclave.model_class,
                u64::from(served_ctx),
                &contract.ctx_bracket_schedule,
                now,
            )?;
            if candidate_ctx_bracket.as_deref() != schedule.ctx_bracket.as_deref() {
                continue;
            }
            route_count = route_count.saturating_add(1);
            market_providers.insert(candidate.provider.clone());
        }
        let route_count = usize_to_u32(route_count);
        let providers_online = usize_to_u32(market_providers.len());
        let availability = if route_count > 0 {
            "routable"
        } else {
            "no_eligible_provider_yet"
        };
        let price_ref_au = gateway_price_ref_from_ledger_with_history(
            price,
            price_history_by_market
                .get(market_key.as_str())
                .map(Vec::as_slice),
        );
        markets_by_model
            .entry(enclave.model_id.clone())
            .or_default()
            .insert(
                market_key.clone(),
                GatewayMarketInfo {
                    enclave_id: enclave.enclave_id.clone(),
                    att_tier: enclave.att_tier,
                    quant: normalize_ledger_quant(&enclave.quant),
                    ctx_bracket: schedule.ctx_bracket.clone(),
                    room_ids: room_ids.clone(),
                    providers_online,
                    route_count,
                    availability: availability.to_owned(),
                    price_ref_au,
                },
            );
        market_rooms_by_model
            .entry(enclave.model_id.clone())
            .or_default()
            .extend(room_ids);
        listed_price_by_model
            .entry(enclave.model_id.clone())
            .and_modify(|existing| {
                if price_sort_key(price) < price_sort_key(&existing.price) {
                    *existing = GatewayServedPrice {
                        price: price.clone(),
                        market_key: market_key.clone(),
                    };
                }
            })
            .or_insert_with(|| GatewayServedPrice {
                price: price.clone(),
                market_key: market_key.clone(),
            });
        class_by_model
            .entry(enclave.model_id.clone())
            .or_insert_with(|| enclave.model_class.clone());
        caps_by_model
            .entry(enclave.model_id.clone())
            .and_modify(|caps| merge_model_caps(caps, &enclave_caps))
            .or_insert(enclave_caps);
    }

    let mut models = Vec::new();
    for (model_id, market_map) in markets_by_model {
        let markets = market_map.into_values().collect::<Vec<_>>();
        let price = served_price_by_model
            .remove(&model_id)
            .or_else(|| listed_price_by_model.remove(&model_id))
            .expect("listed contract market has a current price");
        let rooms = market_rooms_by_model
            .get(&model_id)
            .map(|rooms| usize_to_u32(rooms.len()))
            .unwrap_or(0);
        let route_candidates = route_candidates_by_model
            .remove(&model_id)
            .unwrap_or_default()
            .into_values()
            .collect::<Vec<_>>();
        let kyb_identities = kyb_by_model
            .remove(&model_id)
            .unwrap_or_default()
            .into_values()
            .collect::<Vec<_>>();
        let providers_online = providers_by_model
            .get(&model_id)
            .map(|providers| usize_to_u32(providers.len()))
            .unwrap_or(0);
        let mut attestation_tiers = tiers_by_model
            .remove(&model_id)
            .unwrap_or_default()
            .into_iter()
            .map(|(tier, providers)| (tier, usize_to_u32(providers.len())))
            .collect::<BTreeMap<_, _>>();
        let mut quant_buckets = quants_by_model
            .remove(&model_id)
            .unwrap_or_default()
            .into_iter()
            .map(|(quant, providers)| (quant, usize_to_u32(providers.len())))
            .collect::<BTreeMap<_, _>>();
        for market in &markets {
            attestation_tiers
                .entry(format!("T{}", market.att_tier))
                .or_insert(0);
            quant_buckets.entry(market.quant.clone()).or_insert(0);
        }
        models.push(GatewayModel {
            id: model_id.clone(),
            created: 1_782_950_400,
            owned_by: "mayhem".to_owned(),
            mayhem: MayhemModelInfo {
                model_class: class_by_model
                    .remove(&model_id)
                    .unwrap_or_else(|| DEFAULT_MODEL_CLASS.to_owned()),
                family: String::new(),
                providers_online,
                rooms,
                price_ref_au: gateway_price_ref_from_ledger_with_history(
                    &price.price,
                    price_history_by_market
                        .get(price.market_key.as_str())
                        .map(Vec::as_slice),
                ),
                attestation_tier_labels: gateway_attestation_tier_labels_for_counts(
                    &attestation_tiers,
                ),
                attestation_tiers,
                quant_buckets,
                min_app_version: None,
                caps: caps_by_model
                    .remove(&model_id)
                    .unwrap_or_else(empty_gateway_caps),
                adapter: mayhem_gateway::openai::ShapeAdapterInfo::default(),
                speciality_calibrations: BTreeMap::new(),
                sampling: SamplingProfile::default(),
                failover: mayhem_gateway::openai::GatewayFailoverPolicyConfig::default(),
                source: "contract".to_owned(),
                kyb_identities,
                markets,
                route_candidates,
            },
        });
    }
    Ok(models)
}

#[derive(Debug, Clone, Eq, PartialEq, Serialize)]
struct ModelVersionGate {
    model_id: String,
    min_app_version: String,
    installed_app_version: String,
    message: String,
}

fn installed_app_version() -> &'static str {
    env!("CARGO_PKG_VERSION")
}

fn model_app_version_gate(
    model_id: &str,
    min_app_version: Option<&str>,
) -> Result<Option<ModelVersionGate>> {
    let Some(min_app_version) = min_app_version
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(None);
    };
    let installed = installed_app_version();
    if app_version_satisfies_min(installed, min_app_version)? {
        return Ok(None);
    }
    let message = upgrade_required_message(model_id, min_app_version, installed);
    Ok(Some(ModelVersionGate {
        model_id: model_id.to_owned(),
        min_app_version: min_app_version.to_owned(),
        installed_app_version: installed.to_owned(),
        message,
    }))
}

fn app_version_satisfies_min(installed: &str, min_app_version: &str) -> Result<bool> {
    let installed = parse_app_version(installed, "installed Mayhem")?;
    let min_app_version = parse_app_version(min_app_version, "catalog min_app_version")?;
    Ok(installed >= min_app_version)
}

fn parse_app_version(value: &str, label: &str) -> Result<semver::Version> {
    let trimmed = value.trim();
    semver::Version::parse(trimmed)
        .with_context(|| format!("{label} must be a semantic version like 0.1.0, got {trimmed:?}"))
}

fn upgrade_required_message(
    model_id: &str,
    min_app_version: &str,
    installed_app_version: &str,
) -> String {
    format!(
        "upgrade required: model {model_id} requires Mayhem >= {min_app_version}; installed {installed_app_version}; run `mayhem update`"
    )
}

fn version_gate_summary(action: &str, gates: &[ModelVersionGate]) -> String {
    if gates.len() == 1 {
        return format!(
            "{}; this node cannot {action} it until upgraded",
            gates[0].message
        );
    }
    let installed = gates
        .first()
        .map(|gate| gate.installed_app_version.clone())
        .unwrap_or_else(|| installed_app_version().to_owned());
    let details = gates
        .iter()
        .map(|gate| format!("{} >= {}", gate.model_id, gate.min_app_version))
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        "upgrade required: {} models require a newer Mayhem before this node can {action}: {details}; installed {installed}; run `mayhem update`",
        gates.len()
    )
}

fn gateway_update_models_from_version_gates(
    gates: &[ModelVersionGate],
) -> Vec<GatewayUpdateModelNotice> {
    gates
        .iter()
        .map(|gate| GatewayUpdateModelNotice {
            model_id: gate.model_id.clone(),
            min_app_version: gate.min_app_version.clone(),
            installed_app_version: gate.installed_app_version.clone(),
            message: gate.message.clone(),
        })
        .collect()
}

fn filter_gateway_models_by_app_version(
    models: Vec<GatewayModel>,
    catalog_doc: &catalog::CatalogDocument,
) -> Result<(Vec<GatewayModel>, Vec<ModelVersionGate>)> {
    let catalog_models = catalog_doc
        .models
        .iter()
        .map(|model| (model.model_id.as_str(), model))
        .collect::<BTreeMap<_, _>>();
    let mut allowed = Vec::new();
    let mut blocked = Vec::new();
    for mut model in models {
        if let Some(catalog_model) = catalog_models.get(model.id.as_str()).copied() {
            model.mayhem.family = catalog_model.family.clone();
            model.mayhem.adapter = gateway_shape_adapter(&catalog_model.adapter);
            model.mayhem.sampling = gateway_sampling_profile(&catalog_model.sampling);
            if let Some(min_app_version) = catalog_model.min_app_version.as_deref() {
                model.mayhem.min_app_version = Some(min_app_version.to_owned());
                if let Some(gate) = model_app_version_gate(&model.id, Some(min_app_version))? {
                    blocked.push(gate);
                    continue;
                }
            }
        }
        allowed.push(model);
    }
    if allowed.is_empty() && !blocked.is_empty() {
        bail!("{}", version_gate_summary("route", &blocked));
    }
    Ok((allowed, blocked))
}

fn gateway_shape_adapter(adapter: &catalog::CatalogAdapter) -> ShapeAdapterInfo {
    ShapeAdapterInfo {
        endpoint_families: adapter.endpoint_families.clone(),
        chat_template_id: adapter.chat_template_id.clone(),
        tool_call_strategy: adapter.tool_call_strategy.clone(),
        reasoning_passthrough: adapter.reasoning_passthrough.clone(),
        modality_set: adapter.modality_set.clone(),
        specialities: adapter.specialities.clone(),
    }
}

fn gateway_sampling_profile(sampling: &catalog::CatalogSamplingProfile) -> SamplingProfile {
    SamplingProfile {
        temperature: sampling.temperature,
        top_p: sampling.top_p,
        top_k: sampling.top_k,
        min_p: sampling.min_p,
        repeat_penalty: sampling.repeat_penalty,
        frequency_penalty: sampling.frequency_penalty,
        presence_penalty: sampling.presence_penalty,
    }
}

fn price_sort_key(price: &LedgerPriceRecord) -> (MoneyAu, MoneyAu, MoneyAu, MoneyAu, MoneyAu, u64) {
    (
        price.min_session_au,
        price.per_req_au,
        rate_map_cost_basis_per_1k(&price.rate_map),
        text_rate_per_1k_au(&price.rate_map, INPUT_TOKEN_UNIT),
        text_rate_per_1k_au(&price.rate_map, OUTPUT_TOKEN_UNIT),
        price.ver,
    )
}

fn gateway_price_ref_from_ledger_with_history(
    price: &LedgerPriceRecord,
    history: Option<&[Value]>,
) -> PriceRefAu {
    let history = history
        .map(|entries| entries.iter().take(720).cloned().collect::<Vec<_>>())
        .unwrap_or_default();
    PriceRefAu {
        denom: "au_usd".to_owned(),
        ver: price.ver,
        rate_map: normalize_rate_map(price.rate_map.clone()),
        per_req_au: price.per_req_au,
        min_session_au: price.min_session_au,
        derivation: price.derivation.clone().or_else(|| history.last().cloned()),
        history,
    }
}

fn normalize_ledger_quant(value: &str) -> String {
    normalize_quant_bucket(value).unwrap_or_else(|_| DEFAULT_QUANT_BUCKET.to_owned())
}

fn launch_measurements_with_tier3_registry(
    enclave: &LedgerEnclave,
    tier3_sets: &[LedgerTier3MeasurementSet],
) -> Value {
    let mut merged = enclave.launch_measurements.clone();
    let Some(platform) = merged
        .get("platform")
        .and_then(Value::as_str)
        .map(str::to_owned)
    else {
        return merged;
    };
    let Some(registry) = tier3_sets.iter().find(|set| set.platform == platform) else {
        return merged;
    };
    let Some(object) = merged.as_object_mut() else {
        return merged;
    };
    normalize_launch_measurement_layers(object);
    if let Some(source) = registry.measurements.as_object() {
        if source
            .keys()
            .any(|layer| matches!(layer.as_str(), "vendor" | "workload"))
        {
            for (layer, values) in source {
                merge_launch_measurement_layer(object, layer, values);
            }
        } else {
            merge_launch_measurement_layer(object, "workload", &registry.measurements);
        }
    }
    if !registry.entries.is_empty() {
        let entries = object
            .entry("entries".to_owned())
            .or_insert_with(|| Value::Array(Vec::new()));
        if !entries.is_array() {
            *entries = Value::Array(Vec::new());
        }
        if let Some(entries) = entries.as_array_mut() {
            entries.extend(registry.entries.iter().cloned());
        }
    }
    merged
}

fn normalize_launch_measurement_layers(object: &mut Map<String, Value>) {
    if object.get("layers").is_some_and(Value::is_object) {
        return;
    }
    let measurements = object
        .remove("measurements")
        .filter(Value::is_object)
        .unwrap_or_else(|| Value::Object(Map::new()));
    object.insert(
        "layers".to_owned(),
        json!({
            "workload": measurements
        }),
    );
}

fn merge_launch_measurement_layer(object: &mut Map<String, Value>, layer: &str, value: &Value) {
    if !matches!(layer, "vendor" | "workload") {
        return;
    }
    let layers = object
        .entry("layers".to_owned())
        .or_insert_with(|| json!({}));
    if !layers.is_object() {
        *layers = json!({});
    }
    let Some(layers) = layers.as_object_mut() else {
        return;
    };
    let target = layers.entry(layer.to_owned()).or_insert_with(|| json!({}));
    if !target.is_object() {
        *target = json!({});
    }
    if let (Some(target), Some(source)) = (target.as_object_mut(), value.as_object()) {
        for (name, value) in source {
            merge_launch_measurement_value(target, name, value);
        }
    }
}

fn merge_launch_measurement_value(target: &mut Map<String, Value>, name: &str, value: &Value) {
    let mut values = BTreeSet::new();
    if let Some(existing) = target.get(name) {
        collect_launch_measurement_strings(existing, &mut values);
    }
    collect_launch_measurement_strings(value, &mut values);
    if !values.is_empty() {
        target.insert(
            name.to_owned(),
            Value::Array(values.into_iter().map(Value::String).collect()),
        );
    }
}

fn collect_launch_measurement_strings(value: &Value, out: &mut BTreeSet<String>) {
    if let Some(value) = value.as_str() {
        let value = value.trim().to_ascii_lowercase();
        if !value.is_empty() {
            out.insert(value);
        }
        return;
    }
    if let Some(values) = value.as_array() {
        for value in values {
            collect_launch_measurement_strings(value, out);
        }
        return;
    }
    if let Some(object) = value.as_object() {
        if let Some(measurement) = object.get("measurement") {
            collect_launch_measurement_strings(measurement, out);
        }
        if let Some(values) = object.get("values") {
            collect_launch_measurement_strings(values, out);
        }
    }
}

fn price_derivation_sort_key(derivation: &Value) -> (u64, u64, String) {
    (
        derivation.get("epoch").and_then(Value::as_u64).unwrap_or(0),
        derivation
            .get("price_ver")
            .and_then(Value::as_u64)
            .or_else(|| {
                derivation
                    .get("result_price")
                    .and_then(|value| value.get("ver"))
                    .and_then(Value::as_u64)
            })
            .unwrap_or(0),
        derivation
            .get("derivation_hash")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_owned(),
    )
}

fn room_matches_enclave(room: &LedgerRoom, enclave: &LedgerEnclave) -> bool {
    room.model_id == enclave.model_id && room.enclave_id.as_ref() == Some(&enclave.enclave_id)
}

fn canonical_room_transport_ok(room: &LedgerRoom) -> bool {
    is_hex_len(&room.room_id, 32) && room.sidechannel == format!("mx/room/{}", room.room_id)
}

fn require_canonical_room_transport(room: &LedgerRoom) -> Result<()> {
    if canonical_room_transport_ok(room) {
        return Ok(());
    }
    bail!(
        "room {} is not a canonical contract room: room_id must be 32 hex chars and sidechannel must equal mx/room/<room_id>",
        room.room_id
    )
}

fn empty_gateway_caps() -> ModelCaps {
    ModelCaps {
        tools: false,
        json: false,
        ctx: 0,
        vision: false,
        image: false,
        video: false,
        audio: false,
        max_image_width: None,
        max_image_height: None,
        max_image_steps: None,
        output_modality: None,
        output_modalities: Vec::new(),
    }
}

fn gateway_caps_from_contract(caps: &Value) -> ModelCaps {
    ModelCaps {
        tools: caps.get("tools").and_then(Value::as_bool).unwrap_or(false),
        json: caps.get("json").and_then(Value::as_bool).unwrap_or(false),
        ctx: caps
            .get("ctx")
            .or_else(|| caps.get("ctx_max"))
            .and_then(Value::as_u64)
            .and_then(|ctx| u32::try_from(ctx).ok())
            .unwrap_or(0),
        vision: caps.get("vision").and_then(Value::as_bool).unwrap_or(false),
        image: caps.get("image").and_then(Value::as_bool).unwrap_or(false),
        video: caps.get("video").and_then(Value::as_bool).unwrap_or(false),
        audio: caps.get("audio").and_then(Value::as_bool).unwrap_or(false),
        max_image_width: caps
            .get("max_image_width")
            .and_then(Value::as_u64)
            .and_then(|value| u32::try_from(value).ok()),
        max_image_height: caps
            .get("max_image_height")
            .and_then(Value::as_u64)
            .and_then(|value| u32::try_from(value).ok()),
        max_image_steps: caps.get("max_image_steps").and_then(Value::as_u64),
        output_modality: caps
            .get("output_modality")
            .and_then(Value::as_str)
            .map(str::to_owned),
        output_modalities: caps_output_modalities(caps),
    }
}

fn caps_output_modalities(caps: &Value) -> Vec<String> {
    if let Some(entries) = caps.get("output_modalities").and_then(Value::as_array) {
        return entries
            .iter()
            .filter_map(Value::as_str)
            .filter(|modality| !modality.is_empty())
            .map(str::to_owned)
            .collect();
    }
    caps.get("output_modality")
        .and_then(Value::as_str)
        .filter(|modality| !modality.is_empty())
        .map(|modality| vec![modality.to_owned()])
        .unwrap_or_default()
}

fn default_provider_served_ctx(ctx_max: u64) -> u64 {
    if ctx_max == 0 {
        return 0;
    }
    let half = ctx_max.div_ceil(2);
    half.min(128_000).clamp(1, ctx_max)
}

fn resolve_provider_served_ctx(
    model: &catalog::CatalogModel,
    requested_ctx: Option<u64>,
) -> Result<u64> {
    let ctx_max = model.caps.ctx_max;
    if ctx_max == 0 {
        return Ok(0);
    }
    match requested_ctx {
        Some(0) => bail!("--ctx must be greater than zero"),
        Some(requested) if requested > ctx_max => bail!(
            "explicit --ctx {requested} exceeds catalog maximum {ctx_max} for {}",
            model.model_id
        ),
        Some(requested) => Ok(requested),
        None => Ok(default_provider_served_ctx(ctx_max)),
    }
}

fn provider_context_source(args: &ProviderStartArgs, selected: &ProviderCandidate) -> &'static str {
    if args.ctx.is_some() {
        "cli"
    } else if selected.feasibility.fallback_applied {
        "default_auto_memory_fallback"
    } else {
        "default"
    }
}

fn provider_context_budget_label(
    hardware: &HardwareReport,
    budget: &ProviderMemoryBudget,
) -> String {
    let base = match budget.pool.as_str() {
        "dedicated_gpu_memory" | "nvidia_dedicated_memory" => {
            format!(
                "{} dedicated VRAM budget from {}",
                human_bytes(budget.budget_bytes),
                budget.source
            )
        }
        "nvidia_unified_memory" | "unified_memory" => {
            format!(
                "{} unified memory budget from {}",
                human_bytes(budget.budget_bytes),
                budget.source
            )
        }
        _ => format!(
            "{} {} budget from {}",
            human_bytes(budget.budget_bytes),
            budget.pool,
            budget.source
        ),
    };
    let wddm_shared = hardware.host.os == "windows"
        && hardware
            .gpus
            .iter()
            .any(|gpu| gpu.shared_memory_bytes.unwrap_or(0) > 0 && !gpu.unified_memory);
    if wddm_shared && budget.pool.contains("dedicated") {
        format!("{base}; WDDM shared GPU memory is ignored to avoid silent paging")
    } else {
        base
    }
}

fn provider_reserve_bytes_from_gib(
    value: &str,
    flag: &str,
    floor_bytes: u64,
) -> Result<(u64, String)> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        bail!("{flag} must not be empty");
    }
    let lower = trimmed.to_ascii_lowercase();
    let number = lower
        .strip_suffix("gib")
        .or_else(|| lower.strip_suffix("gb"))
        .or_else(|| lower.strip_suffix('g'))
        .unwrap_or(&lower)
        .trim();
    let gib = number
        .parse::<f64>()
        .with_context(|| format!("{flag} must be a GiB value like 4GB or 4"))?;
    if !gib.is_finite() || gib <= 0.0 {
        bail!("{flag} must be greater than zero");
    }
    let raw = (gib * GIB_BYTES as f64).ceil();
    if raw > u64::MAX as f64 {
        bail!("{flag} is too large");
    }
    let raw = raw as u64;
    let bytes = raw.max(floor_bytes);
    Ok((
        bytes,
        if bytes == raw {
            format!("{flag} override {}", human_bytes(bytes))
        } else {
            format!(
                "{flag} override {} raised to floor {}",
                human_bytes(raw),
                human_bytes(bytes)
            )
        },
    ))
}

fn provider_memory_reserve_bytes(
    setting: Option<&str>,
    basis_bytes: u64,
    unified: bool,
) -> Result<(u64, String)> {
    let basis_bytes = basis_bytes.max(GIB_BYTES);
    if let Some(setting) = setting.map(str::trim).filter(|setting| !setting.is_empty()) {
        if let Some(percent) = setting.strip_suffix('%') {
            let percent = percent.trim().parse::<f64>().with_context(|| {
                format!("--memory-reserve percent must be numeric, got {setting:?}")
            })?;
            if !percent.is_finite() || percent <= 0.0 || percent >= 100.0 {
                bail!("--memory-reserve percent must be greater than 0 and less than 100");
            }
            let raw = (basis_bytes as f64 * percent / 100.0).ceil();
            if raw > u64::MAX as f64 {
                bail!("--memory-reserve is too large");
            }
            let raw = raw as u64;
            let bytes = raw.max(F13_MEMORY_RESERVE_FLOOR_BYTES);
            return Ok((
                bytes,
                if bytes == raw {
                    format!(
                        "--memory-reserve override {percent}% = {}",
                        human_bytes(bytes)
                    )
                } else {
                    format!(
                        "--memory-reserve override {percent}% raised to floor {}",
                        human_bytes(bytes)
                    )
                },
            ));
        }
        return provider_reserve_bytes_from_gib(
            setting,
            "--memory-reserve",
            F13_MEMORY_RESERVE_FLOOR_BYTES,
        );
    }

    let (bps, floor, label) = if unified {
        (
            F13_UNIFIED_MEMORY_RESERVE_BPS,
            F13_UNIFIED_MEMORY_RESERVE_MIN_BYTES,
            "default unified",
        )
    } else {
        (
            F13_DEDICATED_MEMORY_RESERVE_BPS,
            F13_DEDICATED_MEMORY_RESERVE_MIN_BYTES,
            "default dedicated/system",
        )
    };
    let pct = ((u128::from(basis_bytes) * u128::from(bps)) / 10_000)
        .try_into()
        .unwrap_or(u64::MAX);
    let bytes = pct.max(floor);
    Ok((
        bytes,
        format!(
            "{label} memory reserve {}bps floor {} = {}",
            bps,
            human_bytes(floor),
            human_bytes(bytes)
        ),
    ))
}

fn provider_disk_reserve_bytes(setting: Option<&str>) -> Result<(u64, String)> {
    if let Some(setting) = setting.map(str::trim).filter(|setting| !setting.is_empty()) {
        return provider_reserve_bytes_from_gib(
            setting,
            "--disk-reserve",
            F13_DISK_RESERVE_FLOOR_BYTES,
        );
    }
    Ok((
        F13_DISK_RESERVE_DEFAULT_BYTES,
        format!(
            "default disk reserve {}",
            human_bytes(F13_DISK_RESERVE_DEFAULT_BYTES)
        ),
    ))
}

fn provider_system_memory_pool(
    hardware: &HardwareReport,
    pool: &str,
    source: &str,
) -> ProviderMemoryPool {
    ProviderMemoryPool {
        pool: pool.to_owned(),
        source: source.to_owned(),
        unified: hardware.memory.unified_memory,
        total_bytes: hardware.memory.total_bytes,
        available_bytes: hardware
            .memory
            .available_bytes
            .unwrap_or(hardware.memory.total_bytes),
    }
}

fn hardware_has_unified_accelerator(hardware: &HardwareReport) -> bool {
    hardware.memory.unified_memory
        || hardware
            .gpus
            .iter()
            .any(|gpu| gpu.unified_memory || nvidia_gpu_uses_host_unified_memory(hardware, gpu))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ProviderLlamaExecutionPlan {
    gpu_layers: Option<u32>,
    explicitly_cpu_only: bool,
}

impl ProviderLlamaExecutionPlan {
    fn uses_cpu_memory(self) -> bool {
        self.gpu_layers.unwrap_or(0) == 0
    }
}

fn resolve_provider_llama_execution_plan(
    backend: &str,
    requested_gpu_layers: Option<u32>,
    verdict: &BackendVerdict,
) -> Option<ProviderLlamaExecutionPlan> {
    (backend == "llama.cpp").then(|| ProviderLlamaExecutionPlan {
        gpu_layers: requested_gpu_layers.or(verdict.n_layers_gpu),
        explicitly_cpu_only: requested_gpu_layers == Some(0),
    })
}

fn provider_memory_pool(
    hardware: &HardwareReport,
    verdict: &BackendVerdict,
    backend: &str,
    requested_gpu_layers: Option<u32>,
) -> ProviderMemoryPool {
    let llama_plan = resolve_provider_llama_execution_plan(backend, requested_gpu_layers, verdict);
    if llama_plan.is_some_and(ProviderLlamaExecutionPlan::uses_cpu_memory) {
        return provider_system_memory_pool(
            hardware,
            "system_memory",
            if llama_plan.is_some_and(|plan| plan.explicitly_cpu_only) {
                "explicit llama.cpp --gpu-layers 0 uses host memory"
            } else {
                "llama.cpp CPU execution uses host memory"
            },
        );
    }
    let effective_gpu_layers = llama_plan
        .and_then(|plan| plan.gpu_layers)
        .or(verdict.n_layers_gpu)
        .unwrap_or(0);
    match backend {
        "chatterbox" => match chatterbox_managed_device(hardware) {
            Some(ChatterboxManagedDevice::Cuda) => {
                if let Some(total) =
                    known_total_dedicated_vram_bytes(hardware).filter(|total| *total > 0)
                {
                    ProviderMemoryPool {
                        pool: "nvidia_dedicated_memory".to_owned(),
                        source: "Chatterbox CUDA dedicated memory from hwprobe".to_owned(),
                        unified: false,
                        total_bytes: total,
                        available_bytes: total,
                    }
                } else {
                    provider_system_memory_pool(
                        hardware,
                        "system_memory",
                        "host available memory fallback for Chatterbox CUDA",
                    )
                }
            }
            Some(ChatterboxManagedDevice::Mps) => ProviderMemoryPool {
                unified: true,
                ..provider_system_memory_pool(
                    hardware,
                    "unified_memory",
                    "Chatterbox MPS uses host unified memory",
                )
            },
            Some(ChatterboxManagedDevice::Cpu) | None => provider_system_memory_pool(
                hardware,
                "system_memory",
                "Chatterbox CPU uses host memory",
            ),
        },
        "mlx" => ProviderMemoryPool {
            unified: true,
            ..provider_system_memory_pool(
                hardware,
                "unified_memory",
                "host available unified memory",
            )
        },
        "vllm" => {
            if let Some(total) =
                known_total_nvidia_vllm_memory_bytes(hardware).filter(|total| *total > 0)
            {
                let unified = hardware
                    .gpus
                    .iter()
                    .filter(|gpu| gpu.vendor == GpuVendor::Nvidia)
                    .any(|gpu| nvidia_gpu_uses_host_unified_memory(hardware, gpu));
                return ProviderMemoryPool {
                    pool: if unified {
                        "nvidia_unified_memory".to_owned()
                    } else {
                        "nvidia_dedicated_memory".to_owned()
                    },
                    source: if unified {
                        "NVIDIA unified memory from hwprobe".to_owned()
                    } else {
                        "NVIDIA dedicated memory from hwprobe".to_owned()
                    },
                    unified,
                    total_bytes: total,
                    available_bytes: if unified {
                        hardware.memory.available_bytes.unwrap_or(total)
                    } else {
                        total
                    },
                };
            }
            provider_system_memory_pool(
                hardware,
                "system_memory",
                "host available memory fallback for vllm",
            )
        }
        "trt-llm" => {
            if let Some(total) =
                known_total_dedicated_vram_bytes(hardware).filter(|total| *total > 0)
            {
                return ProviderMemoryPool {
                    pool: "nvidia_dedicated_memory".to_owned(),
                    source: "NVIDIA dedicated memory from hwprobe".to_owned(),
                    unified: false,
                    total_bytes: total,
                    available_bytes: total,
                };
            }
            provider_system_memory_pool(
                hardware,
                "system_memory",
                "host available memory fallback for trt-llm",
            )
        }
        _ if effective_gpu_layers > 0 && hardware_has_unified_accelerator(hardware) => {
            ProviderMemoryPool {
                unified: true,
                ..provider_system_memory_pool(
                    hardware,
                    "unified_memory",
                    "accelerator uses host unified memory",
                )
            }
        }
        _ if effective_gpu_layers > 0 => {
            if let Some(total) =
                known_total_dedicated_vram_bytes(hardware).filter(|total| *total > 0)
            {
                ProviderMemoryPool {
                    pool: "dedicated_gpu_memory".to_owned(),
                    source: "dedicated GPU memory from hwprobe".to_owned(),
                    unified: false,
                    total_bytes: total,
                    available_bytes: total,
                }
            } else {
                provider_system_memory_pool(
                    hardware,
                    "system_memory",
                    "host available memory fallback for partial offload",
                )
            }
        }
        _ => provider_system_memory_pool(hardware, "system_memory", "host available memory"),
    }
}

fn provider_memory_budget(
    hardware: &HardwareReport,
    verdict: &BackendVerdict,
    enclave: &LedgerEnclave,
    args: &ProviderStartArgs,
) -> Result<ProviderMemoryBudget> {
    let pool = provider_memory_pool(hardware, verdict, &enclave.backend, args.gpu_layers);
    let claimed_bytes = read_provider_memory_claimed_bytes(
        args.home.as_deref(),
        provider_memory_pool_available_reflects_resident_memory(&pool.pool, pool.unified),
    )?;
    let reserve_basis = pool.total_bytes.max(pool.available_bytes);
    let (reserve_bytes, _reserve_source) =
        provider_memory_reserve_bytes(args.memory_reserve.as_deref(), reserve_basis, pool.unified)?;
    let worker_limit_bytes = pool
        .available_bytes
        .saturating_sub(reserve_bytes)
        .saturating_sub(claimed_bytes);
    let mut budget_bytes = worker_limit_bytes;
    if enclave.backend == "vllm" {
        let admin_max_pct = enclave_vllm_gpu_memory_utilization_pct(&enclave.caps)?;
        let admin_max_bytes =
            u64::try_from((u128::from(pool.total_bytes) * u128::from(admin_max_pct)) / 100)
                .unwrap_or(u64::MAX);
        budget_bytes = budget_bytes.min(admin_max_bytes);
    }
    Ok(ProviderMemoryBudget {
        pool: pool.pool,
        source: pool.source,
        unified: pool.unified,
        total_bytes: pool.total_bytes,
        available_bytes: pool.available_bytes,
        reserve_bytes,
        claimed_bytes,
        worker_limit_bytes,
        budget_bytes,
    })
}

fn provider_kv_bytes_per_token(
    enclave: &LedgerEnclave,
    model: &catalog::CatalogModel,
    artifact: &catalog::CatalogArtifact,
) -> Result<u64> {
    if let Some(value) = enclave.caps.get("kv_bytes_per_token") {
        return value
            .as_u64()
            .filter(|value| *value > 0)
            .context("enclave caps kv_bytes_per_token must be a positive integer");
    }
    if let Some(profile) = &artifact.kv_cache {
        return Ok(profile.bytes_per_token);
    }
    let base_per_billion = if matches!(artifact.engine.as_str(), "trt-llm" | "vllm")
        && matches!(enclave.quant.as_str(), "nvfp4" | "fp8" | "int4")
    {
        16 * 1024
    } else {
        24 * 1024
    };
    Ok(((model.params_b.max(0.1) * base_per_billion as f64).ceil() as u64).max(1024))
}

fn apply_catalog_kv_cache_profile(config: &mut LoadConfig, artifact: &catalog::CatalogArtifact) {
    let Some(profile) = &artifact.kv_cache else {
        return;
    };
    config.kv_cache_dtype = Some(profile.dtype.clone());
    config.kv_cache_bits = Some(profile.bits);
    config.kv_cache_group_size = Some(profile.group_size);
    config.kv_cache_quantized_start_tokens = Some(profile.quantized_start_tokens);
}

fn provider_modality_capacities(
    model: &catalog::CatalogModel,
    artifact_name: &str,
    served_modalities: &[String],
    configured: &BTreeMap<String, ConfigProviderModalityLimits>,
) -> Result<BTreeMap<String, HeartbeatModalityCapacity>> {
    for modality in configured.keys() {
        ensure!(
            model.adapter.modality_set.contains(modality),
            "provider modality limit {modality} is not declared by catalog model {}",
            model.model_id
        );
        ensure!(
            modality != "text",
            "text does not use media capacity limits"
        );
    }
    let profiles = model
        .modality_assessment
        .resource_profiles
        .get(artifact_name);
    let mut capacities = BTreeMap::new();
    for modality in served_modalities
        .iter()
        .filter(|modality| modality.as_str() != "text")
    {
        let profile = profiles
            .and_then(|profiles| profiles.get(modality))
            .with_context(|| {
                format!(
                    "catalog artifact {artifact_name} has no calibrated resource profile for served modality {modality}"
                )
            })?;
        let configured = configured.get(modality);
        let max_inflight_items = configured
            .and_then(|limits| limits.max_inflight_items)
            .unwrap_or(profile.default_max_inflight_items);
        let max_items_per_request = configured
            .and_then(|limits| limits.max_items_per_request)
            .unwrap_or(profile.default_max_items_per_request);
        let max_item_bytes = configured
            .and_then(|limits| limits.max_item_bytes)
            .unwrap_or(profile.max_item_bytes);
        let max_item_units = configured
            .and_then(|limits| limits.max_item_units)
            .unwrap_or(profile.max_item_units);
        ensure!(
            (1..=MAX_PROVIDER_MODALITY_INFLIGHT_ITEMS).contains(&max_inflight_items),
            "provider {modality} concurrency must be between 1 and {MAX_PROVIDER_MODALITY_INFLIGHT_ITEMS}"
        );
        ensure!(
            (1..=MAX_PROVIDER_MODALITY_ITEMS_PER_REQUEST).contains(&max_items_per_request)
                && max_items_per_request <= max_inflight_items,
            "provider {modality} max items per request must be positive and no greater than its in-flight limit"
        );
        ensure!(
            (1..=MAX_PROVIDER_MODALITY_ITEM_BYTES).contains(&max_item_bytes),
            "provider {modality} max item bytes must be between 1 and {MAX_PROVIDER_MODALITY_ITEM_BYTES}"
        );
        ensure!(
            (1..=MAX_PROVIDER_MODALITY_ITEM_UNITS).contains(&max_item_units),
            "provider {modality} max item units must be between 1 and {MAX_PROVIDER_MODALITY_ITEM_UNITS}"
        );
        let by_bytes = multiply_ratio_ceil(
            profile.measured_working_set_bytes,
            max_item_bytes,
            profile.measured_item_bytes,
        );
        let by_units = multiply_ratio_ceil(
            profile.measured_working_set_bytes,
            max_item_units,
            profile.measured_item_units,
        );
        capacities.insert(
            modality.clone(),
            HeartbeatModalityCapacity {
                unit: profile.unit.clone(),
                max_inflight_items,
                active_items: 0,
                max_items_per_request,
                max_item_bytes,
                max_item_units,
                working_set_bytes_per_item: by_bytes.max(by_units).max(1),
            },
        );
    }
    Ok(capacities)
}

fn multiply_ratio_ceil(value: u64, numerator: u64, denominator: u64) -> u64 {
    if denominator == 0 {
        return u64::MAX;
    }
    let scaled = u128::from(value)
        .saturating_mul(u128::from(numerator))
        .saturating_add(u128::from(denominator).saturating_sub(1))
        / u128::from(denominator);
    u64::try_from(scaled).unwrap_or(u64::MAX)
}

fn provider_modality_reserved_bytes(
    capacities: &BTreeMap<String, HeartbeatModalityCapacity>,
) -> u64 {
    capacities.values().fold(0_u64, |total, capacity| {
        total.saturating_add(
            capacity
                .working_set_bytes_per_item
                .saturating_mul(u64::from(capacity.max_inflight_items)),
        )
    })
}

fn provider_memory_estimate(
    enclave: &LedgerEnclave,
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    served_modalities: &[String],
    configured_modalities: &BTreeMap<String, ConfigProviderModalityLimits>,
    served_ctx: u64,
) -> Result<ProviderMemoryEstimate> {
    let weights_bytes = catalog_artifact_resident_bytes(artifact);
    let kv_bytes =
        served_ctx.saturating_mul(provider_kv_bytes_per_token(enclave, model, artifact)?);
    let overhead_bytes = (weights_bytes / 5).max(512 * 1024 * 1024);
    let media_bytes = provider_modality_reserved_bytes(&provider_modality_capacities(
        model,
        artifact_name,
        served_modalities,
        configured_modalities,
    )?);
    Ok(ProviderMemoryEstimate {
        required_bytes: weights_bytes
            .saturating_add(kv_bytes)
            .saturating_add(overhead_bytes)
            .saturating_add(media_bytes),
        weights_bytes,
        kv_bytes,
        overhead_bytes,
        media_bytes,
    })
}

fn provider_model_memory_fit(
    enclave: &LedgerEnclave,
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    served_modalities: &[String],
    configured_modalities: &BTreeMap<String, ConfigProviderModalityLimits>,
    usable_bytes: u64,
    requested_ctx: u64,
) -> Result<mayhem_hwprobe::ModelMemoryFit> {
    let weights_bytes = catalog_artifact_resident_bytes(artifact);
    let overhead_bytes = (weights_bytes / 5).max(512 * 1024 * 1024).saturating_add(
        provider_modality_reserved_bytes(&provider_modality_capacities(
            model,
            artifact_name,
            served_modalities,
            configured_modalities,
        )?),
    );
    Ok(model_memory_fit(
        usable_bytes,
        weights_bytes,
        overhead_bytes,
        provider_kv_bytes_per_token(enclave, model, artifact)?,
        requested_ctx,
    ))
}

fn provider_bucket_aligned_ctx_candidates(
    model_ctx_max: u64,
    requested_ctx: u64,
    schedule: &CtxBracketSchedule,
    at: u64,
) -> Vec<u64> {
    if model_ctx_max == 0 || requested_ctx == 0 {
        return Vec::new();
    }
    let desired = requested_ctx.clamp(1, model_ctx_max);
    let table = ctx_bracket_table_at(schedule, at);
    let mut candidates = vec![desired];
    for bracket in &table.brackets {
        let ctx = bracket.max_ctx.unwrap_or(model_ctx_max).min(model_ctx_max);
        if ctx > 0 && ctx <= desired {
            candidates.push(ctx);
        }
    }
    candidates.sort_unstable();
    candidates.dedup();
    candidates.sort_unstable_by(|a, b| b.cmp(a));
    candidates
}

fn provider_memory_claims_dir(home: &Path) -> PathBuf {
    home.join("provider-memory-claims")
}

fn provider_memory_claim_lock_path(home: &Path) -> PathBuf {
    provider_memory_claims_dir(home).join(".admission.lock")
}

fn lock_provider_memory_claim_admission(home: &Path) -> Result<fs::File> {
    let dir = provider_memory_claims_dir(home);
    fs::create_dir_all(&dir).with_context(|| format!("creating {}", dir.display()))?;
    let path = provider_memory_claim_lock_path(home);
    let lock = fs::OpenOptions::new()
        .create(true)
        .truncate(false)
        .read(true)
        .write(true)
        .open(&path)
        .with_context(|| format!("opening {}", path.display()))?;
    fs2::FileExt::lock_exclusive(&lock).with_context(|| format!("locking {}", path.display()))?;
    Ok(lock)
}

fn remove_provider_memory_claims_for_pid(home: &Path, pid: u32) -> Result<()> {
    let dir = provider_memory_claims_dir(home);
    if !dir.exists() {
        return Ok(());
    }
    for entry in fs::read_dir(&dir).with_context(|| format!("reading {}", dir.display()))? {
        let entry = entry.with_context(|| format!("reading {}", dir.display()))?;
        let path = entry.path();
        if path.extension().and_then(OsStr::to_str) != Some("json") {
            continue;
        }
        let Ok(text) = fs::read_to_string(&path) else {
            continue;
        };
        let Ok(record) = serde_json::from_str::<ProviderMemoryClaimRecord>(&text) else {
            continue;
        };
        if record.pid == pid {
            let _ = fs::remove_file(path);
        }
    }
    Ok(())
}

fn provider_memory_claim_is_resident(home: &Path, record: &ProviderMemoryClaimRecord) -> bool {
    let path = home.join("provider-load-progress").join(format!(
        "{}-{}.json",
        safe_path_component(&record.provider),
        safe_path_component(&record.enclave_id)
    ));
    let Ok(progress) = read_json_file(&path) else {
        return false;
    };
    if progress.get("provider").and_then(Value::as_str) != Some(record.provider.as_str())
        || progress.get("enclave_id").and_then(Value::as_str) != Some(record.enclave_id.as_str())
        || progress.get("phase").and_then(Value::as_str) != Some("serving")
        || progress.get("status").and_then(Value::as_str) != Some("complete")
    {
        return false;
    }
    match progress.get("pid").and_then(Value::as_u64) {
        Some(pid) => pid == u64::from(record.pid),
        None => true,
    }
}

fn read_provider_memory_claimed_bytes(
    home: Option<&Path>,
    available_reflects_resident_memory: bool,
) -> Result<u64> {
    let Some(home) = home else {
        return Ok(0);
    };
    let dir = provider_memory_claims_dir(home);
    if !dir.exists() {
        return Ok(0);
    }
    let now = unix_epoch_seconds().unwrap_or(0);
    let mut unique =
        BTreeMap::<(u32, String, String), (u64, PathBuf, ProviderMemoryClaimRecord)>::new();
    for entry in fs::read_dir(&dir).with_context(|| format!("reading {}", dir.display()))? {
        let entry = entry.with_context(|| format!("reading {}", dir.display()))?;
        let path = entry.path();
        if path.extension().and_then(OsStr::to_str) != Some("json") {
            continue;
        }
        let text = match fs::read_to_string(&path) {
            Ok(text) => text,
            Err(_) => continue,
        };
        let Ok(record) = serde_json::from_str::<ProviderMemoryClaimRecord>(&text) else {
            let _ = fs::remove_file(&path);
            continue;
        };
        if now.saturating_sub(record.created_at) > F13_MEMORY_CLAIM_TTL_SECONDS {
            let _ = fs::remove_file(&path);
            continue;
        }
        if !process_is_running(record.pid) {
            let _ = fs::remove_file(&path);
            continue;
        }
        if available_reflects_resident_memory && provider_memory_claim_is_resident(home, &record) {
            let _ = fs::remove_file(&path);
            continue;
        }
        let key = (
            record.pid,
            record.provider.clone(),
            record.enclave_id.clone(),
        );
        match unique.entry(key) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert((record.created_at, path, record));
            }
            std::collections::btree_map::Entry::Occupied(mut entry) => {
                let existing = entry.get();
                if (record.created_at, &path) > (existing.0, &existing.1) {
                    let (_, duplicate, _) = entry.insert((record.created_at, path, record));
                    let _ = fs::remove_file(duplicate);
                } else {
                    let _ = fs::remove_file(path);
                }
            }
        }
    }
    Ok(unique.values().fold(0_u64, |total, (_, _, record)| {
        total.saturating_add(record.claimed_bytes)
    }))
}

fn write_provider_memory_claim(
    home: &Path,
    provider: &str,
    selected: &ProviderCandidate,
) -> Result<Option<ProviderMemoryClaimGuard>> {
    let claimed_bytes = selected.feasibility.estimated_required_bytes;
    if claimed_bytes == 0 {
        return Ok(None);
    }
    let dir = provider_memory_claims_dir(home);
    fs::create_dir_all(&dir).with_context(|| format!("creating {}", dir.display()))?;
    let now = unix_epoch_seconds()?;
    let budget = &selected.feasibility.memory_budget;
    let release_after_load =
        provider_memory_pool_available_reflects_resident_memory(&budget.pool, budget.unified);
    let record = ProviderMemoryClaimRecord {
        schema_version: 1,
        pid: std::process::id(),
        provider: provider.to_owned(),
        enclave_id: selected.enclave.enclave_id.clone(),
        model_id: selected.enclave.model_id.clone(),
        backend: selected.enclave.backend.clone(),
        served_ctx: selected.served_ctx,
        claimed_bytes,
        created_at: now,
    };
    let path = dir.join(format!(
        "{}-{}-{}.json",
        short_hash(provider),
        short_hash(&selected.enclave.enclave_id),
        std::process::id()
    ));
    write_json_file(&path, &serde_json::to_value(&record)?)
        .with_context(|| format!("writing {}", path.display()))?;
    Ok(Some(ProviderMemoryClaimGuard {
        path: Some(path),
        release_after_load,
    }))
}

fn provider_context_feasibility(
    enclave: &LedgerEnclave,
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    served_modalities: &[String],
    verdict: &BackendVerdict,
    hardware: &HardwareReport,
    args: &ProviderStartArgs,
    schedule: &CtxBracketSchedule,
    at: u64,
) -> Result<ProviderCtxFeasibility> {
    let requested_ctx = resolve_provider_served_ctx(model, args.ctx)?;
    if enclave.model_class != DEFAULT_MODEL_CLASS || requested_ctx == 0 {
        let memory_budget = provider_memory_budget(hardware, verdict, enclave, args)?;
        let estimate = provider_memory_estimate(
            enclave,
            model,
            artifact_name,
            artifact,
            served_modalities,
            &args.modality_limits,
            requested_ctx,
        )?;
        let fit = provider_model_memory_fit(
            enclave,
            model,
            artifact_name,
            artifact,
            served_modalities,
            &args.modality_limits,
            memory_budget.budget_bytes,
            requested_ctx,
        )?;
        if estimate.required_bytes > memory_budget.budget_bytes {
            bail!(
                "model {} needs {} (weights {}, working memory {}, overhead {}, modality reserve {}) but only {} is usable after reserve {} and local claims {} in {}",
                model.model_id,
                human_bytes(estimate.required_bytes),
                human_bytes(estimate.weights_bytes),
                human_bytes(estimate.kv_bytes),
                human_bytes(estimate.overhead_bytes),
                human_bytes(estimate.media_bytes),
                human_bytes(memory_budget.budget_bytes),
                human_bytes(memory_budget.reserve_bytes),
                human_bytes(memory_budget.claimed_bytes),
                memory_budget.pool
            );
        }
        return Ok(ProviderCtxFeasibility {
            requested_ctx,
            served_ctx: requested_ctx,
            max_safe_context: fit.max_safe_context,
            catalog_ctx_max: model.caps.ctx_max,
            fallback_applied: false,
            message: None,
            estimated_required_bytes: estimate.required_bytes,
            estimated_weights_bytes: estimate.weights_bytes,
            estimated_kv_bytes: estimate.kv_bytes,
            estimated_overhead_bytes: estimate.overhead_bytes,
            estimated_media_bytes: estimate.media_bytes,
            memory_budget,
        });
    }
    let memory_budget = provider_memory_budget(hardware, verdict, enclave, args)?;
    let requested_fit = provider_model_memory_fit(
        enclave,
        model,
        artifact_name,
        artifact,
        served_modalities,
        &args.modality_limits,
        memory_budget.budget_bytes,
        requested_ctx,
    )?;
    let candidates = if args.ctx.is_some() {
        vec![requested_ctx]
    } else {
        provider_bucket_aligned_ctx_candidates(model.caps.ctx_max, requested_ctx, schedule, at)
    };
    let Some(min_ctx) = candidates.last().copied() else {
        bail!(
            "no active context bucket can serve model {}",
            model.model_id
        );
    };
    let mut min_estimate = provider_memory_estimate(
        enclave,
        model,
        artifact_name,
        artifact,
        served_modalities,
        &args.modality_limits,
        min_ctx,
    )?;
    for served_ctx in candidates {
        let estimate = provider_memory_estimate(
            enclave,
            model,
            artifact_name,
            artifact,
            served_modalities,
            &args.modality_limits,
            served_ctx,
        )?;
        if served_ctx == min_ctx {
            min_estimate = estimate;
        }
        if estimate.required_bytes <= memory_budget.budget_bytes {
            let fallback_applied = served_ctx != requested_ctx;
            let message = fallback_applied.then(|| {
                format!(
                    "Context auto-fallback: requested/default {} tokens did not fit {}; serving {} tokens from the active admin context table so the working set fits without spilling.",
                    requested_ctx,
                    provider_context_budget_label(hardware, &memory_budget),
                    served_ctx
                )
            });
            return Ok(ProviderCtxFeasibility {
                requested_ctx,
                served_ctx,
                max_safe_context: requested_fit.max_safe_context,
                catalog_ctx_max: model.caps.ctx_max,
                fallback_applied,
                message,
                estimated_required_bytes: estimate.required_bytes,
                estimated_weights_bytes: estimate.weights_bytes,
                estimated_kv_bytes: estimate.kv_bytes,
                estimated_overhead_bytes: estimate.overhead_bytes,
                estimated_media_bytes: estimate.media_bytes,
                memory_budget,
            });
        }
    }
    if args.ctx.is_some() {
        bail!(
            "explicit --ctx {} cannot fit: estimated required {} (weights {}, KV {}, overhead {}) exceeds usable {} after reserve {} and local claims {} in {}; choose a fitting context explicitly or change the admin enclave profile",
            requested_ctx,
            human_bytes(min_estimate.required_bytes),
            human_bytes(min_estimate.weights_bytes),
            human_bytes(min_estimate.kv_bytes),
            human_bytes(min_estimate.overhead_bytes),
            human_bytes(memory_budget.budget_bytes),
            human_bytes(memory_budget.reserve_bytes),
            human_bytes(memory_budget.claimed_bytes),
            memory_budget.pool
        );
    }
    bail!(
        "minimum context {} tokens cannot fit: estimated required {} (weights {}, KV {}, overhead {}) exceeds usable {} after reserve {} and local claims {} in {}",
        min_ctx,
        human_bytes(min_estimate.required_bytes),
        human_bytes(min_estimate.weights_bytes),
        human_bytes(min_estimate.kv_bytes),
        human_bytes(min_estimate.overhead_bytes),
        human_bytes(memory_budget.budget_bytes),
        human_bytes(memory_budget.reserve_bytes),
        human_bytes(memory_budget.claimed_bytes),
        memory_budget.pool
    )
}

fn enclave_cap_u32(caps: &Value, key: &'static str, default: u32) -> Result<u32> {
    match caps.get(key) {
        None => Ok(default),
        Some(value) => value
            .as_u64()
            .and_then(|value| u32::try_from(value).ok())
            .filter(|value| *value > 0)
            .with_context(|| format!("enclave caps {key} must be a positive u32")),
    }
}

fn enclave_tp_degree(caps: &Value) -> Result<u32> {
    enclave_cap_u32(caps, "tp_degree", 1)
}

fn enclave_max_batch_size(caps: &Value) -> Result<Option<u32>> {
    match caps.get("max_batch_size") {
        None => Ok(None),
        Some(_) => Ok(Some(enclave_cap_u32(caps, "max_batch_size", 1)?)),
    }
}

fn enclave_max_num_tokens(caps: &Value) -> Result<Option<u32>> {
    match caps.get("max_num_tokens") {
        None => Ok(None),
        Some(_) => Ok(Some(enclave_cap_u32(caps, "max_num_tokens", 1)?)),
    }
}

fn enclave_vllm_gpu_memory_utilization_pct(caps: &Value) -> Result<u32> {
    match caps.get("vllm_gpu_memory_utilization_pct") {
        None => Ok(VLLM_ADMIN_MEMORY_UTILIZATION_MAX_PCT),
        Some(_) => {
            let pct = enclave_cap_u32(
                caps,
                "vllm_gpu_memory_utilization_pct",
                VLLM_ADMIN_MEMORY_UTILIZATION_MAX_PCT,
            )?;
            ensure!(
                pct <= VLLM_ADMIN_MEMORY_UTILIZATION_MAX_PCT,
                "enclave caps vllm_gpu_memory_utilization_pct must be between 1 and {}",
                VLLM_ADMIN_MEMORY_UTILIZATION_MAX_PCT
            );
            Ok(pct)
        }
    }
}

#[derive(Debug, Clone, Copy, Eq, PartialEq, Serialize)]
struct VllmMemoryUtilizationPlan {
    target_pct: u32,
    floor_pct: u32,
    max_pct: u32,
}

fn validate_provider_vllm_memory_utilization_pct(pct: u32) -> Result<u32> {
    ensure!(
        (1..=VLLM_ADMIN_MEMORY_UTILIZATION_MAX_PCT).contains(&pct),
        "vLLM memory utilization must be between 1 and {} percent",
        VLLM_ADMIN_MEMORY_UTILIZATION_MAX_PCT
    );
    Ok(pct)
}

fn provider_vllm_memory_utilization(
    selected: &ProviderCandidate,
    local_target_pct: Option<u32>,
) -> Result<VllmMemoryUtilizationPlan> {
    let total_bytes = selected.feasibility.memory_budget.total_bytes;
    ensure!(
        total_bytes > 0,
        "cannot derive vLLM memory utilization without a non-zero accelerator memory total"
    );
    let required_bytes = selected.feasibility.estimated_required_bytes;
    let budget_bytes = selected.feasibility.memory_budget.budget_bytes;
    ensure!(
        required_bytes <= budget_bytes,
        "vLLM model and context require {}, exceeding the usable memory budget {}",
        human_bytes(required_bytes),
        human_bytes(budget_bytes)
    );

    let floor_pct =
        u32::try_from((u128::from(required_bytes) * 100).div_ceil(u128::from(total_bytes)))
            .unwrap_or(u32::MAX)
            .max(1);
    let mut budget_pct = u32::try_from((u128::from(budget_bytes) * 100) / u128::from(total_bytes))
        .unwrap_or(u32::MAX);
    let next_budget_pct = budget_pct.saturating_add(1);
    let next_budget_bytes =
        u64::try_from((u128::from(total_bytes) * u128::from(next_budget_pct)) / 100)
            .unwrap_or(u64::MAX);
    if next_budget_pct <= 100 && next_budget_bytes <= budget_bytes {
        budget_pct = next_budget_pct;
    }
    let admin_max_pct = enclave_vllm_gpu_memory_utilization_pct(&selected.enclave.caps)?;
    let max_pct = budget_pct
        .min(admin_max_pct)
        .min(VLLM_ADMIN_MEMORY_UTILIZATION_MAX_PCT);
    ensure!(
        floor_pct <= max_pct,
        "vLLM model and context require at least {floor_pct}% GPU memory, but the F13/admin ceiling is {max_pct}%"
    );
    let target_pct = if let Some(pct) = local_target_pct {
        let pct = validate_provider_vllm_memory_utilization_pct(pct)?;
        ensure!(
            pct >= floor_pct,
            "local vLLM memory utilization {pct}% is below the estimated {floor_pct}% required for this model and context"
        );
        ensure!(
            pct <= max_pct,
            "local vLLM memory utilization {pct}% exceeds the current usable ceiling {max_pct}%"
        );
        pct
    } else {
        floor_pct
            .saturating_add(VLLM_MEMORY_UTILIZATION_CUSHION_PCT)
            .min(max_pct)
    };
    Ok(VllmMemoryUtilizationPlan {
        target_pct,
        floor_pct,
        max_pct,
    })
}

fn provider_vllm_memory_utilization_for_candidates(
    candidates: &[ProviderCandidate],
    local_target_pct: Option<u32>,
) -> Result<Option<VllmMemoryUtilizationPlan>> {
    let mut floor_pct = 0;
    let mut max_pct = VLLM_ADMIN_MEMORY_UTILIZATION_MAX_PCT;
    let mut count = 0usize;
    for candidate in candidates
        .iter()
        .filter(|candidate| candidate.artifact.engine == "vllm")
    {
        let plan = provider_vllm_memory_utilization(candidate, None)?;
        floor_pct = floor_pct.max(plan.floor_pct);
        max_pct = max_pct.min(plan.max_pct);
        count += 1;
    }
    if count == 0 {
        return Ok(None);
    }
    ensure!(
        floor_pct <= max_pct,
        "admitted vLLM workers have no common safe memory utilization: require at least {floor_pct}% but permit at most {max_pct}%"
    );
    let target_pct = if let Some(pct) = local_target_pct {
        let pct = validate_provider_vllm_memory_utilization_pct(pct)?;
        ensure!(
            pct >= floor_pct,
            "local vLLM memory utilization {pct}% is below the admitted {floor_pct}% fit floor"
        );
        ensure!(
            pct <= max_pct,
            "local vLLM memory utilization {pct}% exceeds the admitted safe ceiling {max_pct}%"
        );
        pct
    } else {
        floor_pct
            .saturating_add(VLLM_MEMORY_UTILIZATION_CUSHION_PCT)
            .min(max_pct)
    };
    let mut pool_allocations = BTreeMap::<String, (u64, u64)>::new();
    for candidate in candidates
        .iter()
        .filter(|candidate| candidate.artifact.engine == "vllm")
    {
        let budget = &candidate.feasibility.memory_budget;
        let reserved_bytes =
            u64::try_from((u128::from(budget.total_bytes) * u128::from(target_pct)) / 100)
                .unwrap_or(u64::MAX);
        let allocation = pool_allocations
            .entry(budget.pool.clone())
            .or_insert((0, budget.budget_bytes));
        allocation.0 = allocation.0.saturating_add(reserved_bytes);
        allocation.1 = allocation.1.min(budget.budget_bytes);
    }
    for (pool, (reserved_bytes, budget_bytes)) in pool_allocations {
        ensure!(
            reserved_bytes <= budget_bytes,
            "vLLM memory utilization {target_pct}% would reserve {} across workers in {pool}, exceeding the admitted shared budget {}; select fewer co-resident vLLM workers or lower their admitted memory requirements",
            human_bytes(reserved_bytes),
            human_bytes(budget_bytes)
        );
    }
    Ok(Some(VllmMemoryUtilizationPlan {
        target_pct,
        floor_pct,
        max_pct,
    }))
}

fn configured_provider_vllm_memory_utilization_pct(config: &toml::Value) -> Result<Option<u32>> {
    let Some(value) = toml_get_path(config, "provider.limits.vllm_memory_utilization_pct") else {
        return Ok(None);
    };
    let pct = value
        .as_integer()
        .and_then(|value| u32::try_from(value).ok())
        .context("provider.limits.vllm_memory_utilization_pct must be a positive integer")?;
    Ok(Some(validate_provider_vllm_memory_utilization_pct(pct)?))
}

fn ensure_provider_vllm_memory_utilization_config(
    home: &Path,
    candidates: &[ProviderCandidate],
    requested_target_pct: Option<u32>,
) -> Result<Option<VllmMemoryUtilizationPlan>> {
    if !candidates
        .iter()
        .any(|candidate| candidate.artifact.engine == "vllm")
    {
        return Ok(None);
    }
    let path = config_path_for_home(home);
    let mut config = read_config_toml_value(&path)?;
    let configured_target_pct = configured_provider_vllm_memory_utilization_pct(&config)?;
    let plan = provider_vllm_memory_utilization_for_candidates(
        candidates,
        requested_target_pct.or(configured_target_pct),
    )?
    .context("vLLM admission did not produce a memory utilization plan")?;
    if configured_target_pct != Some(plan.target_pct) {
        let limits = ensure_toml_table_path(&mut config, &["provider", "limits"])?;
        toml_table_set_u64(
            limits,
            "vllm_memory_utilization_pct",
            u64::from(plan.target_pct),
        )?;
        write_config_toml_value(&path, &config)?;
    }
    let persisted =
        configured_provider_vllm_memory_utilization_pct(&read_config_toml_value(&path)?)?;
    ensure!(
        persisted == Some(plan.target_pct),
        "persisted vLLM memory utilization does not match the admitted {}%",
        plan.target_pct
    );
    Ok(Some(plan))
}

fn tensor_parallel_capable_gpu_count(hardware: &HardwareReport) -> usize {
    hardware
        .gpus
        .iter()
        .filter(|gpu| gpu.supports_tensor_parallel)
        .count()
}

fn provider_hardware_quote_config(
    args: &ProviderStartArgs,
) -> Result<Option<ProviderHardwareQuoteConfig>> {
    match (&args.hardware_quote_kind, &args.hardware_quote_command) {
        (None, None) => Ok(None),
        (Some(_), None) => {
            bail!("--hardware-quote-kind requires --hardware-quote-command")
        }
        (None, Some(_)) => {
            bail!("--hardware-quote-command requires --hardware-quote-kind")
        }
        (Some(kind), Some(command)) => {
            if args.hardware_quote_timeout_seconds == 0 {
                bail!("--hardware-quote-timeout-seconds must be positive");
            }
            let kind = parse_hardware_quote_kind(kind)?;
            Ok(Some(ProviderHardwareQuoteConfig {
                kind,
                command: resolve_provider_quote_command(command)?,
                timeout: Duration::from_secs(args.hardware_quote_timeout_seconds),
                tpm_state_dir: None,
            }))
        }
    }
}

fn bind_provider_tpm_state_dir(
    config: Option<&mut ProviderHardwareQuoteConfig>,
    home: &Path,
    provider_pubkey: &str,
) -> Result<()> {
    let Some(config) = config else {
        return Ok(());
    };
    if config.kind != HardwareQuoteKind::Tpm2QuoteEk {
        ensure!(
            config.tpm_state_dir.is_none(),
            "non-TPM hardware quote config must not carry TPM state"
        );
        return Ok(());
    }
    ensure!(
        is_hex_len(provider_pubkey, 64),
        "provider public key must be 32-byte hexadecimal before binding TPM state"
    );
    let state_dir = absolutize(
        home.join("attestation")
            .join("tpm2-provider")
            .join(provider_pubkey.to_ascii_lowercase()),
    )?;
    config.tpm_state_dir = Some(state_dir);
    Ok(())
}

fn provider_hardware_quote_config_for_enclave(
    config: Option<ProviderHardwareQuoteConfig>,
    enclave: &LedgerEnclave,
) -> Result<Option<ProviderHardwareQuoteConfig>> {
    if enclave.att_tier == mayhem_proto::TIER1_SOFTWARE_ATTESTATION_TIER {
        return Ok(None);
    }
    let config = config.with_context(|| {
        format!(
            "selected admin enclave {} requires Tier-{} proof; provide an explicit matching --hardware-quote-kind and --hardware-quote-command",
            enclave.enclave_id, enclave.att_tier
        )
    })?;
    let quote_tier = config.kind.attestation_tier();
    ensure!(
        quote_tier == enclave.att_tier,
        "selected admin enclave {} requires Tier-{} proof, but --hardware-quote-kind generates Tier-{quote_tier}; choose a matching canonical tier market or proof kind",
        enclave.enclave_id,
        enclave.att_tier,
    );
    Ok(Some(config))
}

fn resolve_provider_quote_command(command: &Path) -> Result<PathBuf> {
    if command.components().count() == 1 {
        return Ok(command.to_path_buf());
    }
    absolutize(command.to_path_buf())
}

fn parse_hardware_quote_kind(value: &str) -> Result<HardwareQuoteKind> {
    let normalized = value.trim().to_ascii_lowercase().replace('-', "_");
    serde_json::from_value(Value::String(normalized.clone()))
        .with_context(|| format!("unsupported hardware quote kind {value:?}"))
}

fn hardware_quote_kind_name(kind: &HardwareQuoteKind) -> String {
    serde_json::to_value(kind)
        .ok()
        .and_then(|value| value.as_str().map(ToOwned::to_owned))
        .unwrap_or_else(|| format!("{kind:?}"))
}

fn provider_quote_generation_attestation_tier(args: &ProviderStartArgs) -> Result<u8> {
    Ok(provider_hardware_quote_config(args)?
        .map(|config| config.kind.attestation_tier())
        .unwrap_or(mayhem_proto::TIER1_SOFTWARE_ATTESTATION_TIER))
}

async fn collect_provider_hardware_quote(
    config: &ProviderHardwareQuoteConfig,
    identity: &CatalogEnclaveIdentity,
    runtime_keypair: &RuntimeKeypair,
    provider_signing_seed: [u8; 32],
    binary_path: &Path,
    measured_binary_hash: Option<&str>,
    boot_epoch: u64,
    report_ts: u64,
    nonce_u: &str,
    runtime_config: &AttestationRuntimeConfig,
    policy_binding: Option<&HardwareQuoteRoutePolicyBinding>,
) -> Result<CollectedProviderHardwareQuote> {
    let binding_options = HardwareQuoteBindingOptions {
        identity: identity.clone(),
        runtime_keypair: runtime_keypair.clone(),
        provider_signing_seed,
        binary_path: binary_path.to_path_buf(),
        boot_epoch,
        report_ts,
        nonce_u: nonce_u.to_owned(),
        hw_quote_kind: config.kind.clone(),
        runtime_config: runtime_config.clone(),
    };
    let binding = match measured_binary_hash {
        Some(binary_hash) => {
            prepare_hardware_quote_binding_for_measured_binary(&binding_options, binary_hash)
        }
        None => prepare_hardware_quote_binding(&binding_options),
    }
    .context("preparing Mayhem hardware quote binding")?;
    let evidence_nonce = match policy_binding {
        Some(policy) => {
            ensure!(
                policy.kind == config.kind,
                "buyer attestation policy kind does not match provider quote kind"
            );
            let enclave_id = catalog_enclave_id(identity);
            let evidence_binding = EvidenceBinding::new(
                policy,
                nonce_u,
                enclave_id,
                policy.device_id.clone(),
                binding.clone(),
            )
            .context("binding hardware evidence to the buyer's authenticated route policy")?;
            hex_encode(
                &evidence_binding
                    .digest()
                    .context("hashing hardware evidence policy binding")?,
            )
        }
        None => binding.clone(),
    };
    let kind_name = hardware_quote_kind_name(&config.kind);
    let (program, mut program_args) =
        provider_hardware_quote_invocation(&config.command, cfg!(windows));
    if config.kind == HardwareQuoteKind::Tpm2QuoteEk {
        program_args.push("quote".to_owned());
    }
    let mut command = Command::new(program);
    command
        .args(program_args)
        .env("MAYHEM_HW_QUOTE_KIND", &kind_name)
        .env("MAYHEM_HW_QUOTE_BINDING", &binding)
        .env("MAYHEM_HW_QUOTE_NONCE", &evidence_nonce)
        .env("MAYHEM_HW_QUOTE_EVIDENCE_BINDING", &evidence_nonce)
        .env("MAYHEM_ATTESTATION_NONCE_U", nonce_u)
        .env(
            "MAYHEM_ATTESTATION_ENCLAVE_ID",
            catalog_enclave_id(identity),
        )
        .env("MAYHEM_ATTESTATION_BINARY_HASH", &identity.binary_hash)
        .env("MAYHEM_ATTESTATION_MANIFEST_HASH", &identity.manifest_hash);
    if config.kind == HardwareQuoteKind::Tpm2QuoteEk {
        let state_dir = config
            .tpm_state_dir
            .as_ref()
            .context("TPM quote state directory is not bound to the provider identity")?;
        command
            .env("MAYHEM_TPM2_STATE_DIR", state_dir)
            .env("MAYHEM_TPM2_QUOTE_EXTRA_DATA", &evidence_nonce);
    } else {
        ensure!(
            config.tpm_state_dir.is_none(),
            "non-TPM hardware quote config must not carry TPM state"
        );
    }
    let output =
        run_provider_hardware_quote_command(&mut command, &config.command, config.timeout).await?;
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);
    if !output.status.success() {
        bail!(
            "hardware quote command {} failed with status {}; stdout: {}; stderr: {}",
            config.command.display(),
            output.status,
            truncate_log_for_error(stdout.trim()),
            truncate_log_for_error(stderr.trim())
        );
    }
    parse_hardware_quote_command_output(&config.kind, &binding, stdout.trim()).with_context(|| {
        format!(
            "parsing hardware quote command {}",
            config.command.display()
        )
    })
}

async fn run_provider_hardware_quote_command(
    command: &mut Command,
    command_path: &Path,
    command_timeout: Duration,
) -> Result<std::process::Output> {
    run_provider_helper_command(
        command,
        command_path,
        command_timeout,
        None,
        MAX_HARDWARE_QUOTE_COMMAND_STDOUT_BYTES,
    )
    .await
}

async fn run_provider_tpm_activation_command(
    config: &ProviderHardwareQuoteConfig,
    challenge: &mayhem_proto::TpmActivateCredentialChallenge,
) -> Result<mayhem_proto::TpmActivateCredentialResponse> {
    ensure!(
        config.kind == HardwareQuoteKind::Tpm2QuoteEk,
        "TPM activation requires a tpm2_quote_ek helper"
    );
    let state_dir = config
        .tpm_state_dir
        .as_ref()
        .context("TPM activation state directory is not bound to the provider identity")?;
    let now = unix_epoch_seconds()?;
    ensure!(
        challenge.issued_at_unix <= now && now < challenge.expires_at_unix,
        "TPM activation challenge is not currently valid"
    );
    let remaining = challenge.expires_at_unix.saturating_sub(now);
    let command_timeout = config.timeout.min(Duration::from_secs(remaining));
    ensure!(
        !command_timeout.is_zero(),
        "TPM activation challenge expired before helper execution"
    );
    let input = serde_json::to_vec(challenge).context("serializing TPM activation helper input")?;
    ensure!(
        input.len() <= MAX_TPM_ACTIVATION_COMMAND_INPUT_BYTES,
        "TPM activation challenge exceeds {} bytes",
        MAX_TPM_ACTIVATION_COMMAND_INPUT_BYTES
    );

    let (program, mut program_args) =
        provider_hardware_quote_invocation(&config.command, cfg!(windows));
    program_args.push("activate_credential".to_owned());
    let mut command = Command::new(program);
    command
        .args(program_args)
        .env("MAYHEM_TPM2_STATE_DIR", state_dir);
    let output = run_provider_helper_command(
        &mut command,
        &config.command,
        command_timeout,
        Some(&input),
        MAX_TPM_ACTIVATION_COMMAND_OUTPUT_BYTES,
    )
    .await?;
    if !output.status.success() {
        bail!(
            "TPM activation helper {} failed with status {}; stderr: {}",
            config.command.display(),
            output.status,
            truncate_log_for_error(String::from_utf8_lossy(&output.stderr).trim())
        );
    }
    let response =
        serde_json::from_slice::<mayhem_proto::TpmActivateCredentialResponse>(&output.stdout)
            .context("TPM activation helper returned invalid response JSON")?;
    ensure!(
        response.schema_version == mayhem_proto::TPM_ACTIVATE_CREDENTIAL_SCHEMA_VERSION,
        "TPM activation response schema version is unsupported"
    );
    ensure!(
        response.challenge_id == challenge.challenge_id
            && response.ak_name_b64 == challenge.ak_name_b64
            && response.quote_binding == challenge.quote_binding,
        "TPM activation response does not match the challenge"
    );
    Ok(response)
}

async fn run_provider_helper_command(
    command: &mut Command,
    command_path: &Path,
    command_timeout: Duration,
    input: Option<&[u8]>,
    stdout_limit: usize,
) -> Result<std::process::Output> {
    if let Some(input) = input {
        ensure!(
            input.len() <= MAX_TPM_ACTIVATION_COMMAND_INPUT_BYTES,
            "hardware helper input exceeds {} bytes",
            MAX_TPM_ACTIVATION_COMMAND_INPUT_BYTES
        );
    }
    command
        .kill_on_drop(true)
        .stdin(if input.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    #[cfg(unix)]
    command.as_std_mut().process_group(0);

    let mut child = command
        .spawn()
        .with_context(|| format!("running hardware quote command {}", command_path.display()))?;
    let child_pid = child.id();
    let mut stdout = child
        .stdout
        .take()
        .context("hardware quote command stdout pipe is missing")?;
    let mut stderr = child
        .stderr
        .take()
        .context("hardware quote command stderr pipe is missing")?;
    let stdout_task = tokio::spawn(async move {
        read_bounded_provider_helper_stream(&mut stdout, stdout_limit).await
    });
    let stderr_task = tokio::spawn(async move {
        read_bounded_provider_helper_stream(&mut stderr, MAX_HARDWARE_QUOTE_COMMAND_STDERR_BYTES)
            .await
    });
    if let Some(input) = input {
        let mut stdin = child
            .stdin
            .take()
            .context("hardware helper stdin pipe is missing")?;
        if let Err(err) = stdin.write_all(input).await {
            terminate_hardware_quote_process_tree(child_pid);
            let _ = child.kill().await;
            stdout_task.abort();
            stderr_task.abort();
            return Err(err).with_context(|| {
                format!(
                    "writing input to hardware helper {}",
                    command_path.display()
                )
            });
        }
        if let Err(err) = stdin.shutdown().await {
            terminate_hardware_quote_process_tree(child_pid);
            let _ = child.kill().await;
            stdout_task.abort();
            stderr_task.abort();
            return Err(err).with_context(|| {
                format!(
                    "closing input to hardware helper {}",
                    command_path.display()
                )
            });
        }
    }

    let status = match timeout(command_timeout, child.wait()).await {
        Ok(Ok(status)) => status,
        Ok(Err(err)) => {
            terminate_hardware_quote_process_tree(child_pid);
            let _ = child.kill().await;
            stdout_task.abort();
            stderr_task.abort();
            return Err(err).with_context(|| {
                format!(
                    "waiting for hardware quote command {}",
                    command_path.display()
                )
            });
        }
        Err(_) => {
            terminate_hardware_quote_process_tree(child_pid);
            let _ = child.kill().await;
            let _ = timeout(Duration::from_secs(5), child.wait()).await;
            stdout_task.abort();
            stderr_task.abort();
            bail!(
                "hardware quote command {} timed out after {}s; its process tree was terminated",
                command_path.display(),
                command_timeout.as_secs()
            );
        }
    };
    let stdout = stdout_task
        .await
        .context("joining hardware quote stdout reader")?
        .context("reading hardware quote stdout")?;
    let stderr = stderr_task
        .await
        .context("joining hardware quote stderr reader")?
        .context("reading hardware quote stderr")?;
    Ok(std::process::Output {
        status,
        stdout,
        stderr,
    })
}

async fn read_bounded_provider_helper_stream(
    reader: &mut (impl tokio::io::AsyncRead + Unpin),
    limit: usize,
) -> io::Result<Vec<u8>> {
    let read_limit = u64::try_from(limit).unwrap_or(u64::MAX).saturating_add(1);
    let mut bytes = Vec::new();
    reader.take(read_limit).read_to_end(&mut bytes).await?;
    if bytes.len() > limit {
        return Err(io::Error::other(format!(
            "hardware helper output exceeds {limit} bytes"
        )));
    }
    Ok(bytes)
}

fn terminate_hardware_quote_process_tree(pid: Option<u32>) {
    let Some(pid) = pid else {
        return;
    };
    #[cfg(unix)]
    {
        let Some(pid) = unix_process_id(pid) else {
            return;
        };
        let _ = std::process::Command::new("kill")
            .arg("-KILL")
            .arg("--")
            .arg(format!("-{pid}"))
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
    }
    #[cfg(windows)]
    {
        let _ = std::process::Command::new("taskkill")
            .args(["/PID", &pid.to_string(), "/T", "/F"])
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
    }
    #[cfg(not(any(unix, windows)))]
    let _ = pid;
}

fn provider_hardware_quote_invocation(command: &Path, windows: bool) -> (PathBuf, Vec<String>) {
    if windows
        && command
            .extension()
            .and_then(OsStr::to_str)
            .is_some_and(|extension| extension.eq_ignore_ascii_case("ps1"))
    {
        return (
            PathBuf::from("powershell.exe"),
            vec![
                "-NoProfile".to_owned(),
                "-NonInteractive".to_owned(),
                "-ExecutionPolicy".to_owned(),
                "Bypass".to_owned(),
                "-File".to_owned(),
                command.display().to_string(),
            ],
        );
    }
    (command.to_path_buf(), Vec::new())
}

fn parse_hardware_quote_command_output(
    expected_kind: &HardwareQuoteKind,
    expected_binding: &str,
    stdout: &str,
) -> Result<CollectedProviderHardwareQuote> {
    if stdout.is_empty() {
        bail!("hardware quote command printed no evidence");
    }
    let parsed = serde_json::from_str::<HardwareQuoteCommandOutput>(stdout)
        .or_else(|_| {
            stdout
                .match_indices('{')
                .find_map(|(idx, _)| {
                    serde_json::from_str::<HardwareQuoteCommandOutput>(stdout[idx..].trim()).ok()
                })
                .ok_or_else(|| serde_json::Error::io(std::io::Error::other("not JSON")))
        })
        .ok();
    let Some(parsed) = parsed else {
        ensure!(
            expected_kind != &HardwareQuoteKind::Tpm2QuoteEk,
            "TPM 2.0 quote command must emit the typed Mayhem helper envelope"
        );
        return Ok(CollectedProviderHardwareQuote {
            quote: HardwareQuote {
                kind: expected_kind.clone(),
                evidence: stdout.to_owned(),
                binding: expected_binding.to_owned(),
                endorsements: Vec::new(),
                metadata: Value::Null,
            },
            device_key: None,
            tpm_activation_hello: None,
        });
    };
    let typed_envelope = parsed.hardware_quote.is_some();
    let quote = if let Some(quote) = parsed.hardware_quote.clone() {
        ensure!(
            parsed.kind.is_none()
                && parsed.evidence.is_none()
                && parsed.evidence_path.is_none()
                && parsed.binding.is_none()
                && parsed.endorsements.is_empty()
                && parsed.metadata.is_null()
                && parsed.platform.is_none()
                && parsed.platform_id.is_none()
                && parsed.region.is_none()
                && parsed.snp_chip_family.is_none()
                && parsed.snp_chip_id.is_none()
                && parsed.snp_tcb.is_none()
                && parsed.snp_firmware_svn.is_none()
                && parsed.snp.is_null()
                && parsed.gpu_model.is_none()
                && parsed.gpu_driver.is_none()
                && parsed.gpu_vbios.is_none()
                && parsed.gpu.is_null()
                && parsed.tpm.is_null(),
            "typed hardware quote envelope must not mix nested and legacy quote fields"
        );
        quote
    } else {
        let kind = match parsed.kind.as_deref() {
            Some(kind) => parse_hardware_quote_kind(kind)?,
            None => expected_kind.clone(),
        };
        let evidence = match (parsed.evidence.as_deref(), parsed.evidence_path.as_deref()) {
            (Some(evidence), None) => evidence.to_owned(),
            (None, Some(path)) => {
                let path = absolutize(PathBuf::from(path))?;
                fs::read_to_string(&path).with_context(|| {
                    format!("reading hardware quote evidence {}", path.display())
                })?
            }
            (Some(_), Some(_)) => {
                bail!("hardware quote command JSON must set only one of evidence or evidence_path")
            }
            (None, None) => bail!("hardware quote command JSON missing evidence"),
        };
        HardwareQuote {
            kind,
            evidence,
            binding: parsed
                .binding
                .clone()
                .unwrap_or_else(|| expected_binding.to_owned()),
            endorsements: parsed.endorsements.clone(),
            metadata: hardware_quote_command_metadata(&parsed),
        }
    };
    ensure!(
        &quote.kind == expected_kind,
        "hardware quote command returned kind {}, expected {}",
        hardware_quote_kind_name(&quote.kind),
        hardware_quote_kind_name(expected_kind)
    );
    ensure!(
        quote.binding == expected_binding,
        "hardware quote command returned a binding different from Mayhem's binding"
    );
    ensure!(
        !quote.evidence.trim().is_empty(),
        "hardware quote command returned empty evidence"
    );

    let declared_device_key = hardware_quote_command_declared_device_key(&parsed)?;
    let metadata_device_key = hardware_quote_device_key(&quote)?;
    if let (Some(declared), Some(metadata)) = (
        declared_device_key.as_deref(),
        metadata_device_key.as_deref(),
    ) {
        ensure!(
            declared == metadata,
            "hardware quote command returned conflicting device keys"
        );
    }
    let device_key = declared_device_key.or(metadata_device_key);
    let tpm_activation_hello = parsed.tpm_activate_credential_hello.clone();
    if expected_kind == &HardwareQuoteKind::Tpm2QuoteEk {
        ensure!(
            typed_envelope,
            "TPM 2.0 quote command must emit the typed Mayhem helper envelope"
        );
        ensure!(
            quote.metadata.is_null(),
            "TPM 2.0 hardware quote metadata must be null"
        );
        ensure!(
            device_key.is_some(),
            "TPM 2.0 quote command must return the EK-backed device_key"
        );
        let hello = tpm_activation_hello
            .as_ref()
            .context("TPM 2.0 quote command must return tpm_activate_credential_hello")?;
        ensure!(
            hello.schema_version == mayhem_proto::TPM_ACTIVATE_CREDENTIAL_SCHEMA_VERSION,
            "TPM activation hello schema version is unsupported"
        );
        ensure!(
            hello.quote_binding == expected_binding,
            "TPM activation hello is bound to a different quote"
        );
    } else {
        ensure!(
            tpm_activation_hello.is_none(),
            "TPM activation hello is only valid for tpm2_quote_ek"
        );
    }

    Ok(CollectedProviderHardwareQuote {
        quote,
        device_key,
        tpm_activation_hello,
    })
}

fn hardware_quote_command_declared_device_key(
    parsed: &HardwareQuoteCommandOutput,
) -> Result<Option<String>> {
    let mut normalized = None::<String>;
    for value in [
        parsed.device_key.as_deref(),
        parsed.ek_fingerprint.as_deref(),
        parsed.tpm_ek_sha256.as_deref(),
    ]
    .into_iter()
    .flatten()
    {
        let value = value.trim().to_ascii_lowercase();
        ensure!(
            is_hex_len(&value, 64),
            "hardware quote device_key must be a 32-byte hexadecimal digest"
        );
        if let Some(existing) = normalized.as_deref() {
            ensure!(
                existing == value,
                "hardware quote command returned conflicting device keys"
            );
        } else {
            normalized = Some(value);
        }
    }
    Ok(normalized)
}

fn hardware_quote_command_metadata(parsed: &HardwareQuoteCommandOutput) -> Value {
    let mut metadata = parsed.metadata.clone();
    if !metadata.is_object() {
        metadata = json!({});
    }
    let object = metadata
        .as_object_mut()
        .expect("metadata was set to object");
    if let Some(platform) = parsed
        .platform_id
        .as_deref()
        .or(parsed.platform.as_deref())
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        object.insert("platform_id".to_owned(), json!(platform));
    }
    if let Some(region) = parsed
        .region
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        object.insert("region".to_owned(), json!(region));
    }
    if !parsed.snp.is_null() {
        object.insert("snp".to_owned(), parsed.snp.clone());
    }
    if parsed.snp_chip_family.is_some()
        || parsed.snp_chip_id.is_some()
        || parsed.snp_tcb.is_some()
        || parsed.snp_firmware_svn.is_some()
    {
        let snp = object.entry("snp".to_owned()).or_insert_with(|| json!({}));
        if !snp.is_object() {
            *snp = json!({});
        }
        let snp = snp.as_object_mut().expect("snp was set to object");
        if let Some(value) = parsed.snp_chip_family.as_deref() {
            snp.insert("chip_family".to_owned(), json!(value));
        }
        if let Some(value) = parsed.snp_chip_id.as_deref() {
            snp.insert("chip_id".to_owned(), json!(value));
        }
        if let Some(value) = parsed.snp_tcb.as_deref() {
            snp.insert("tcb".to_owned(), json!(value));
        }
        if let Some(value) = parsed.snp_firmware_svn.as_deref() {
            snp.insert("firmware_svn".to_owned(), json!(value));
        }
    }
    if !parsed.gpu.is_null() {
        object.insert("gpu".to_owned(), parsed.gpu.clone());
    }
    if parsed.gpu_model.is_some() || parsed.gpu_driver.is_some() || parsed.gpu_vbios.is_some() {
        let gpu = object.entry("gpu".to_owned()).or_insert_with(|| json!({}));
        if !gpu.is_object() {
            *gpu = json!({});
        }
        let gpu = gpu.as_object_mut().expect("gpu was set to object");
        if let Some(value) = parsed.gpu_model.as_deref() {
            gpu.insert("model".to_owned(), json!(value));
        }
        if let Some(value) = parsed.gpu_driver.as_deref() {
            gpu.insert("driver".to_owned(), json!(value));
        }
        if let Some(value) = parsed.gpu_vbios.as_deref() {
            gpu.insert("vbios".to_owned(), json!(value));
        }
    }
    if !parsed.tpm.is_null() {
        object.insert("tpm".to_owned(), parsed.tpm.clone());
    }
    if let Some(device_key) = parsed
        .device_key
        .as_deref()
        .or(parsed.ek_fingerprint.as_deref())
        .or(parsed.tpm_ek_sha256.as_deref())
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let normalized = device_key.to_ascii_lowercase();
        object.insert("device_key".to_owned(), json!(normalized));
        let tpm = object.entry("tpm".to_owned()).or_insert_with(|| json!({}));
        if !tpm.is_object() {
            *tpm = json!({});
        }
        let tpm = tpm.as_object_mut().expect("tpm was set to object");
        tpm.insert(
            "ek_sha256".to_owned(),
            json!(device_key.to_ascii_lowercase()),
        );
    }
    metadata
}

fn hardware_quote_device_key(quote: &HardwareQuote) -> Result<Option<String>> {
    let Some(device_key) = quote
        .metadata
        .get("device_key")
        .or_else(|| quote.metadata.get("ek_fingerprint"))
        .or_else(|| quote.metadata.get("tpm_ek_sha256"))
        .and_then(Value::as_str)
        .or_else(|| {
            quote
                .metadata
                .get("tpm")
                .and_then(|tpm| {
                    tpm.get("device_key")
                        .or_else(|| tpm.get("ek_fingerprint"))
                        .or_else(|| tpm.get("ek_sha256"))
                })
                .and_then(Value::as_str)
        })
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(None);
    };
    if !is_hex_len(device_key, 64) {
        bail!("hardware quote device_key must be a 32-byte hex digest");
    }
    Ok(Some(device_key.to_ascii_lowercase()))
}

async fn provider_attestation_report(
    quote_config: Option<&ProviderHardwareQuoteConfig>,
    identity: CatalogEnclaveIdentity,
    runtime_keypair: &RuntimeKeypair,
    provider_pubkey: &str,
    provider_signing_seed: Option<[u8; 32]>,
    keypair_path: &Path,
    password: &str,
    binary_path: &Path,
    measured_binary_hash: Option<&str>,
    boot_epoch: u64,
    report_ts: u64,
    nonce_u: String,
    runtime_config: AttestationRuntimeConfig,
    policy_binding: Option<&HardwareQuoteRoutePolicyBinding>,
) -> Result<ProviderAttestationMaterial> {
    if let Some(config) = quote_config {
        let provider_signing_seed = provider_signing_seed
            .context("hardware quote attestation requires provider signing seed")?;
        let collected = collect_provider_hardware_quote(
            config,
            &identity,
            runtime_keypair,
            provider_signing_seed,
            binary_path,
            measured_binary_hash,
            boot_epoch,
            report_ts,
            &nonce_u,
            &runtime_config,
            policy_binding,
        )
        .await?;
        let report_options = HardwareAttestationOptions {
            identity,
            runtime_keypair: runtime_keypair.clone(),
            provider_signing_seed,
            binary_path: binary_path.to_path_buf(),
            boot_epoch,
            report_ts,
            nonce_u,
            hw_quote: collected.quote,
            runtime_config,
        };
        let report = match measured_binary_hash {
            Some(binary_hash) => {
                build_hardware_attestation_report_for_measured_binary(&report_options, binary_hash)
            }
            None => build_hardware_attestation_report(&report_options),
        }
        .context("building hardware provider attestation report")?;
        return Ok(ProviderAttestationMaterial {
            report,
            device_key: collected.device_key,
            tpm_activation_hello: collected.tpm_activation_hello,
        });
    }

    let report_options = Tier1ExternalProviderAttestationOptions {
        identity,
        runtime_keypair: runtime_keypair.clone(),
        provider_pubkey: provider_pubkey.to_owned(),
        binary_path: binary_path.to_path_buf(),
        boot_epoch,
        report_ts,
        nonce_u,
        runtime_config,
    };
    let draft = match measured_binary_hash {
        Some(binary_hash) => {
            prepare_tier1_attestation_report_for_measured_binary(&report_options, binary_hash)
        }
        None => prepare_tier1_attestation_report(&report_options),
    }?;
    let provider_attestation_sig =
        sign_hex(keypair_path, password, &draft.provider_signing_message_hex).await?;
    let report = finalize_tier1_attestation_report(draft, provider_attestation_sig)
        .context("finalizing provider attestation")?;
    Ok(ProviderAttestationMaterial {
        report,
        device_key: None,
        tpm_activation_hello: None,
    })
}

fn merge_model_caps(target: &mut ModelCaps, next: &ModelCaps) {
    target.tools |= next.tools;
    target.json |= next.json;
    target.vision |= next.vision;
    target.ctx = target.ctx.max(next.ctx);
}

fn usize_to_u32(value: usize) -> u32 {
    u32::try_from(value).unwrap_or(u32::MAX)
}

fn build_provider_candidates(
    contract: &ContractCatalog,
    catalog_doc: &catalog::CatalogDocument,
    hardware: &HardwareReport,
    args: &ProviderStartArgs,
) -> Result<Vec<ProviderCandidate>> {
    let requested_backend = requested_backend(args, hardware)?;
    let requested_enclave = args.enclave.as_deref();
    let provider_attestation_tier = provider_quote_generation_attestation_tier(args)?;
    let mut candidates = Vec::new();
    let mut rejections = Vec::new();
    let mut version_gates = BTreeMap::new();
    let now = unix_epoch_seconds()?;
    for enclave in contract.enclaves.iter().filter(|enclave| {
        enclave.status == "active" && admin_role_marker_ok(enclave.created_by_role.as_deref())
    }) {
        if !ledger_enclave_identity_is_self_consistent(enclave) {
            rejections.push(provider_rejection(
                enclave,
                "ledger enclave_id does not match its immutable admin/model/artifact identity"
                    .to_owned(),
                None,
            ));
            continue;
        }
        if let Some(requested) = &requested_backend {
            if &enclave.backend != requested {
                rejections.push(provider_rejection(
                    enclave,
                    format!(
                        "requested backend {requested}, but enclave uses {}",
                        enclave.backend
                    ),
                    None,
                ));
                continue;
            }
        }
        if enclave.att_tier > provider_attestation_tier {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "attestation tier mismatch: enclave requires tier {}, but this provider path can currently generate verified Tier {} reports; hardware probe tier {} is only a signal and is not advertised without real quote generation",
                    enclave.att_tier, provider_attestation_tier, hardware.tee.tier
                ),
                None,
            ));
            continue;
        }
        let Some(model) = catalog_doc
            .models
            .iter()
            .find(|model| model.model_id == enclave.model_id)
        else {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "model {} is not present in the signed admin catalog",
                    enclave.model_id
                ),
                None,
            ));
            continue;
        };
        if enclave.model_class != model.model_class {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "model_class mismatch: ledger has {}, signed catalog has {}",
                    enclave.model_class, model.model_class
                ),
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        }
        if let Some(gate) =
            model_app_version_gate(&model.model_id, model.min_app_version.as_deref())?
        {
            if args
                .enclave
                .as_deref()
                .is_some_and(|requested| requested_provider_enclave_matches(requested, enclave))
            {
                bail!("{}", gate.message);
            }
            version_gates
                .entry(gate.model_id.clone())
                .or_insert_with(|| gate.clone());
            rejections.push(provider_rejection(
                enclave,
                gate.message.clone(),
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        }
        let Some(verdict) = hardware
            .backend_verdicts
            .iter()
            .find(|verdict| verdict.backend == enclave.backend)
        else {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "backend {} is not reported by hwprobe on this host",
                    enclave.backend
                ),
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        };
        if verdict.status == VerdictStatus::Insufficient {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "{}; {}",
                    backend_requirement_hint(&enclave.backend),
                    verdict
                        .reason
                        .as_deref()
                        .unwrap_or("hwprobe marked this backend insufficient")
                ),
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        }
        if matches!(enclave.backend.as_str(), "trt-llm" | "vllm") {
            let Ok(tp_degree) = enclave_tp_degree(&enclave.caps) else {
                rejections.push(provider_rejection(
                    enclave,
                    format!(
                        "{} enclave caps are missing a valid tp_degree",
                        enclave.backend
                    ),
                    compatible_catalog_artifact_suggestion(model, hardware, None),
                ));
                continue;
            };
            if tp_degree > 1
                && tensor_parallel_capable_gpu_count(hardware)
                    < usize::try_from(tp_degree).unwrap_or(usize::MAX)
            {
                rejections.push(provider_rejection(
                    enclave,
                    format!(
                        "tensor-parallel mismatch: enclave requires tp_degree {tp_degree}, local hardware has {} matching tensor-parallel GPU(s)",
                        tensor_parallel_capable_gpu_count(hardware)
                    ),
                    compatible_catalog_artifact_suggestion(model, hardware, None),
                ));
                continue;
            }
        }
        let Some((artifact_name, artifact)) =
            select_catalog_artifact_for_enclave(model, enclave, hardware)
        else {
            let backend_artifacts = model
                .artifacts
                .iter()
                .filter(|(_, artifact)| artifact.engine == enclave.backend)
                .map(|(name, artifact)| {
                    let compatibility =
                        artifact_hardware_compatibility(model, name, artifact, hardware);
                    format!("{name}: {}", compatibility.reason)
                })
                .collect::<Vec<_>>();
            let reason = if backend_artifacts.is_empty() {
                format!(
                    "signed catalog has no artifact for backend {} on model {}",
                    enclave.backend, model.model_id
                )
            } else {
                format!(
                    "no local-compatible artifact for backend {} on model {}; {}",
                    enclave.backend,
                    model.model_id,
                    backend_artifacts.join("; ")
                )
            };
            rejections.push(provider_rejection(
                enclave,
                reason,
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        };
        if !ledger_enclave_matches_catalog_artifact(enclave, &artifact) {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "ledger artifact binding does not match signed catalog artifact {artifact_name} ({})",
                    artifact.engine
                ),
                compatible_catalog_artifact_suggestion(model, hardware, Some(&artifact_name)),
            ));
            continue;
        }
        let served_modalities = match provider_served_modalities(model, &args.disable_modalities) {
            Ok(modalities) => modalities,
            Err(err) => {
                rejections.push(provider_rejection(
                    enclave,
                    format!("resolving served modalities: {err:#}"),
                    None,
                ));
                continue;
            }
        };
        let catalog_specialities = catalog_provider_speciality_levels(model, &artifact);
        let ledger_specialities = match ledger_enclave_speciality_levels(enclave) {
            Ok(specialities) => specialities,
            Err(err) => {
                rejections.push(provider_rejection(
                    enclave,
                    format!("reading admin enclave speciality levels: {err:#}"),
                    None,
                ));
                continue;
            }
        };
        if ledger_specialities != catalog_specialities {
            rejections.push(provider_rejection(
                enclave,
                "admin enclave speciality levels do not match the signed catalog".to_owned(),
                None,
            ));
            continue;
        }
        let served_specialities =
            match ledger_enclave_served_specialities(enclave, &args.speciality_levels) {
                Ok(specialities) => specialities,
                Err(err) => {
                    rejections.push(provider_rejection(
                        enclave,
                        format!("resolving served specialities: {err:#}"),
                        None,
                    ));
                    continue;
                }
            };
        let feasibility = match provider_context_feasibility(
            enclave,
            model,
            &artifact_name,
            &artifact,
            &served_modalities,
            verdict,
            hardware,
            args,
            &contract.ctx_bracket_schedule,
            now,
        ) {
            Ok(feasibility) => feasibility,
            Err(err) => {
                rejections.push(provider_rejection(
                    enclave,
                    format!("{err:#}"),
                    compatible_catalog_artifact_suggestion(model, hardware, Some(&artifact_name)),
                ));
                continue;
            }
        };
        let served_ctx = feasibility.served_ctx;
        if let Err(err) = validate_provider_speciality_fit(model, &served_specialities, served_ctx)
        {
            rejections.push(provider_rejection(
                enclave,
                format!("speciality fit is invalid: {err:#}"),
                None,
            ));
            continue;
        }
        let modality_capacities = match provider_modality_capacities(
            model,
            &artifact_name,
            &served_modalities,
            &args.modality_limits,
        ) {
            Ok(capacities) => capacities,
            Err(err) => {
                rejections.push(provider_rejection(
                    enclave,
                    format!("resolving modality capacity: {err:#}"),
                    None,
                ));
                continue;
            }
        };
        let price_ctx_bracket = price_ctx_bracket_for_model_class(
            &enclave.model_class,
            served_ctx,
            &contract.ctx_bracket_schedule,
            now,
        )?;
        let Some(price) = find_current_au_usd_price_schedule(
            &contract.prices,
            &enclave.enclave_id,
            price_ctx_bracket.as_deref(),
        )
        .cloned() else {
            rejections.push(provider_rejection(
                enclave,
                match price_ctx_bracket.as_deref() {
                    Some(ctx_bracket) => format!(
                        "missing current au_usd admin price for context bracket {ctx_bracket}"
                    ),
                    None => "missing current au_usd admin price for this enclave".to_owned(),
                },
                None,
            ));
            continue;
        };
        candidates.push(ProviderCandidate {
            enclave: enclave.clone(),
            model: model.clone(),
            artifact_name,
            artifact,
            verdict: verdict.clone(),
            price: Some(price),
            served_ctx,
            served_modalities,
            served_specialities,
            modality_capacities,
            feasibility,
            ctx_bracket_schedule: contract.ctx_bracket_schedule.clone(),
        });
    }
    if let Some(requested) = requested_enclave {
        if !candidates
            .iter()
            .any(|candidate| requested_provider_enclave_matches(requested, &candidate.enclave))
        {
            let relevant = rejections
                .iter()
                .filter(|rejection| requested_provider_rejection_matches(requested, rejection))
                .collect::<Vec<_>>();
            if !relevant.is_empty() {
                bail!("{}", provider_rejection_summary(requested, &relevant));
            }
        }
    }
    if candidates.is_empty() {
        if !version_gates.is_empty() {
            let gates = version_gates.into_values().collect::<Vec<_>>();
            bail!("{}", version_gate_summary("serve", &gates));
        }
        if !rejections.is_empty() {
            let relevant = rejections.iter().collect::<Vec<_>>();
            bail!("{}", provider_rejection_summary("auto", &relevant));
        }
        bail!(
            "no feasible active admin-created enclaves with a current au_usd admin price found in contract state; providers can only join priced enclaves the admin already registered"
        );
    }
    if env::var_os("MAYHEM_PROVIDER_CANDIDATE_DEBUG").is_some() {
        for candidate in &candidates {
            provider_log(
                args,
                &format!(
                    "Candidate {} via {} ({}) enclave {}",
                    candidate.enclave.model_id,
                    candidate.enclave.backend,
                    candidate.artifact_name,
                    short_hash(&candidate.enclave.enclave_id)
                ),
            );
        }
        for rejection in &rejections {
            provider_log(
                args,
                &format!(
                    "Rejected {} via {} enclave {}: {}{}",
                    rejection.model_id,
                    rejection.backend,
                    short_hash(&rejection.enclave_id),
                    rejection.reason,
                    rejection
                        .suggestion
                        .as_ref()
                        .map(|suggestion| format!("; suggestion: {suggestion}"))
                        .unwrap_or_default()
                ),
            );
        }
    }
    Ok(candidates)
}

fn normalize_provider_modality(value: &str) -> Result<String> {
    let modality = value.trim().to_ascii_lowercase();
    if !matches!(
        modality.as_str(),
        "text" | "embedding" | "image" | "video" | "audio"
    ) {
        bail!("unsupported provider modality {value:?}; expected text, embedding, image, video, or audio");
    }
    Ok(modality)
}

fn normalized_provider_disabled_modalities(values: &[String]) -> Result<BTreeSet<String>> {
    let mut disabled = BTreeSet::new();
    for value in values {
        let modality = normalize_provider_modality(value)?;
        if !disabled.insert(modality.clone()) {
            bail!("provider modality {modality} is disabled more than once");
        }
    }
    Ok(disabled)
}

fn provider_core_modalities(model_class: &str) -> BTreeSet<&'static str> {
    match model_class {
        DEFAULT_MODEL_CLASS => BTreeSet::from(["text"]),
        MODEL_CLASS_EMBEDDING => BTreeSet::from(["embedding"]),
        MODEL_CLASS_IMAGE_GENERATION => BTreeSet::from(["image"]),
        MODEL_CLASS_VIDEO_GENERATION => BTreeSet::from(["audio", "video"]),
        MODEL_CLASS_STT => BTreeSet::from(["audio", "text"]),
        MODEL_CLASS_TTS | MODEL_CLASS_AUDIO_GENERATION | MODEL_CLASS_MUSIC_GENERATION => {
            BTreeSet::from(["audio"])
        }
        _ => BTreeSet::new(),
    }
}

fn resolve_provider_served_modalities(
    model_class: &str,
    enabled: &[String],
    disabled_values: &[String],
) -> Result<Vec<String>> {
    if enabled.is_empty() {
        bail!(
            "catalog modality_set is empty; the admin must publish an explicit modality assessment"
        );
    }
    let disabled = normalized_provider_disabled_modalities(disabled_values)?;
    let core = provider_core_modalities(model_class);
    if let Some(modality) = disabled
        .iter()
        .find(|modality| core.contains(modality.as_str()) && enabled.contains(modality))
    {
        bail!("provider cannot disable core {modality} modality for model class {model_class}");
    }
    let served = enabled
        .iter()
        .filter(|modality| !disabled.contains(modality.as_str()))
        .cloned()
        .collect::<Vec<_>>();
    if served.is_empty() {
        bail!("provider modality opt-out would leave no served modalities");
    }
    Ok(served)
}

fn provider_served_modalities(
    model: &catalog::CatalogModel,
    disabled: &[String],
) -> Result<Vec<String>> {
    resolve_provider_served_modalities(&model.model_class, &model.adapter.modality_set, disabled)
}

fn valid_provider_speciality_component(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 128
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'.' | b'-'))
}

fn catalog_provider_speciality_levels(
    model: &catalog::CatalogModel,
    artifact: &catalog::CatalogArtifact,
) -> BTreeMap<String, Vec<String>> {
    catalog::artifact_effective_speciality_levels(model, artifact)
}

fn ledger_enclave_speciality_levels(
    enclave: &LedgerEnclave,
) -> Result<BTreeMap<String, Vec<String>>> {
    enclave
        .caps
        .get("speciality_levels")
        .cloned()
        .map(serde_json::from_value)
        .transpose()
        .context("admin enclave caps speciality_levels must map names to level arrays")
        .map(Option::unwrap_or_default)
}

fn parse_provider_speciality_level_overrides(
    values: &[String],
) -> Result<BTreeMap<String, Vec<String>>> {
    let mut overrides = BTreeMap::new();
    for value in values {
        let (name, levels) = value.split_once('=').with_context(|| {
            format!(
                "invalid --speciality-levels {value:?}; expected NAME=LEVEL or NAME=LEVEL,LEVEL"
            )
        })?;
        let name = name.trim();
        if !valid_provider_speciality_component(name) {
            bail!("invalid provider speciality name {name:?}");
        }
        if overrides.contains_key(name) {
            bail!("provider speciality {name} is configured more than once");
        }
        let mut seen = BTreeSet::new();
        let levels = levels
            .split(',')
            .map(str::trim)
            .map(|level| {
                if !valid_provider_speciality_component(level) {
                    bail!("invalid level {level:?} for provider speciality {name}");
                }
                if !seen.insert(level.to_owned()) {
                    bail!("provider speciality {name} repeats level {level}");
                }
                Ok(level.to_owned())
            })
            .collect::<Result<Vec<_>>>()?;
        if levels.is_empty() || levels.len() > 16 {
            bail!("provider speciality {name} must retain between 1 and 16 levels");
        }
        overrides.insert(name.to_owned(), levels);
    }
    Ok(overrides)
}

fn resolve_provider_served_specialities(
    available: &BTreeMap<String, Vec<String>>,
    configured: &[String],
) -> Result<BTreeMap<String, Vec<String>>> {
    let mut served = available.clone();
    for (name, selected) in parse_provider_speciality_level_overrides(configured)? {
        let available_levels = available
            .get(&name)
            .with_context(|| format!("admin catalog does not define provider speciality {name}"))?;
        for level in &selected {
            if !available_levels.contains(level) {
                bail!(
                    "admin catalog speciality {name} does not define level {level}; available: {}",
                    available_levels.join(",")
                );
            }
        }
        let selected_set = selected.iter().map(String::as_str).collect::<BTreeSet<_>>();
        served.insert(
            name,
            available_levels
                .iter()
                .filter(|level| selected_set.contains(level.as_str()))
                .cloned()
                .collect(),
        );
    }
    Ok(served)
}

fn ledger_enclave_served_specialities(
    enclave: &LedgerEnclave,
    configured: &[String],
) -> Result<BTreeMap<String, Vec<String>>> {
    resolve_provider_served_specialities(&ledger_enclave_speciality_levels(enclave)?, configured)
}

fn validate_provider_speciality_fit(
    model: &catalog::CatalogModel,
    served: &BTreeMap<String, Vec<String>>,
    served_ctx: u64,
) -> Result<()> {
    for descriptor in &model.adapter.specialities {
        let levels = served.get(&descriptor.name).with_context(|| {
            format!("provider speciality selection omitted {}", descriptor.name)
        })?;
        if levels.is_empty() {
            bail!(
                "provider speciality {} has no served levels",
                descriptor.name
            );
        }
        for level_name in levels {
            let level = descriptor
                .levels
                .iter()
                .find(|level| &level.name == level_name)
                .with_context(|| {
                    format!(
                        "provider speciality {} selected unknown level {level_name}",
                        descriptor.name
                    )
                })?;
            if let Some(max_output_tokens) = level.default_max_output_tokens {
                ensure!(
                    u64::from(max_output_tokens) <= served_ctx,
                    "provider speciality {} level {} output cap {} exceeds served context {}",
                    descriptor.name,
                    level.name,
                    max_output_tokens,
                    served_ctx
                );
            }
        }
    }
    Ok(())
}

fn requested_provider_enclave_matches(requested: &str, enclave: &LedgerEnclave) -> bool {
    if is_32_byte_hex(requested) {
        enclave.enclave_id == requested
    } else {
        enclave.model_id == requested
    }
}

fn provider_rejection(
    enclave: &LedgerEnclave,
    reason: String,
    suggestion: Option<String>,
) -> ProviderCandidateRejection {
    ProviderCandidateRejection {
        enclave_id: enclave.enclave_id.clone(),
        model_id: enclave.model_id.clone(),
        backend: enclave.backend.clone(),
        reason,
        suggestion,
    }
}

fn requested_provider_rejection_matches(
    requested: &str,
    rejection: &ProviderCandidateRejection,
) -> bool {
    if is_32_byte_hex(requested) {
        rejection.enclave_id == requested
    } else {
        rejection.model_id == requested
    }
}

fn provider_rejection_summary(
    requested: &str,
    rejections: &[&ProviderCandidateRejection],
) -> String {
    let mut lines = Vec::new();
    let prefix = if requested == "auto" {
        "no feasible active admin-created enclaves for this hardware".to_owned()
    } else {
        format!("requested enclave/model {requested} is not feasible on this hardware")
    };
    lines.push(prefix);
    for rejection in rejections.iter().take(6) {
        lines.push(format!(
            "- {} via {} (enclave {}): {}",
            rejection.model_id,
            rejection.backend,
            short_hash(&rejection.enclave_id),
            rejection.reason
        ));
        if let Some(suggestion) = &rejection.suggestion {
            lines.push(format!("  suggestion: {suggestion}"));
        }
    }
    if rejections.len() > 6 {
        lines.push(format!(
            "- ... {} more rejected enclave(s)",
            rejections.len() - 6
        ));
    }
    lines.join("\n")
}

fn ledger_enclave_matches_catalog_artifact(
    enclave: &LedgerEnclave,
    artifact: &catalog::CatalogArtifact,
) -> bool {
    enclave.artifact_root == artifact.artifact_root
        && enclave.artifact_root_kind == artifact.artifact_root_kind
        && enclave.artifact_source.kind == artifact.source.kind
        && enclave.artifact_source.repo == artifact.source.repo
        && enclave.artifact_source.revision == artifact.source.revision
        && enclave.artifact_source.path == artifact.path
        && enclave.source_sha256 == artifact.source_sha256
        && ledger_sidecars_match_catalog(&enclave.artifact_sidecars, &artifact.sidecars)
}

fn ledger_sidecars_match_catalog(
    ledger: &BTreeMap<String, LedgerArtifactSidecar>,
    catalog: &BTreeMap<String, catalog::CatalogArtifactSidecar>,
) -> bool {
    ledger.len() == catalog.len()
        && catalog.iter().all(|(name, catalog_sidecar)| {
            ledger.get(name).is_some_and(|ledger_sidecar| {
                ledger_sidecar.source.kind == catalog_sidecar.source.kind
                    && ledger_sidecar.source.repo == catalog_sidecar.source.repo
                    && ledger_sidecar.source.revision == catalog_sidecar.source.revision
                    && ledger_sidecar.source.path == catalog_sidecar.path
                    && ledger_sidecar.path == catalog_sidecar.path
                    && ledger_sidecar.artifact_root == catalog_sidecar.artifact_root
                    && ledger_sidecar.artifact_root_kind == catalog_sidecar.artifact_root_kind
                    && ledger_sidecar.weights_bytes == catalog_sidecar.weights_bytes
                    && ledger_sidecar
                        .source_sha256
                        .eq_ignore_ascii_case(&catalog_sidecar.source_sha256)
            })
        })
}

fn enclave_artifact_sidecar_roots(enclave: &LedgerEnclave) -> BTreeMap<String, String> {
    enclave
        .artifact_sidecars
        .iter()
        .map(|(name, sidecar)| (name.clone(), sidecar.artifact_root.clone()))
        .collect()
}

fn ledger_enclave_identity_is_self_consistent(enclave: &LedgerEnclave) -> bool {
    catalog_enclave_id(&CatalogEnclaveIdentity {
        admin_pubkey: enclave.created_by.clone(),
        model_id: enclave.model_id.clone(),
        artifact_root: enclave.artifact_root.clone(),
        artifact_sidecar_roots: enclave_artifact_sidecar_roots(enclave),
        manifest_hash: enclave.manifest_hash.clone(),
        binary_hash: enclave.binary_hash.clone(),
    }) == enclave.enclave_id
}

fn enclave_approved_binary_hashes(enclave: &LedgerEnclave) -> BTreeSet<String> {
    std::iter::once(enclave.binary_hash.to_ascii_lowercase())
        .chain(
            enclave
                .approved_binary_hashes
                .iter()
                .map(|hash| hash.to_ascii_lowercase()),
        )
        .collect()
}

fn requested_backend(
    args: &ProviderStartArgs,
    hardware: &HardwareReport,
) -> Result<Option<String>> {
    let requested = args.engine_backend.trim();
    if requested.eq_ignore_ascii_case("auto") {
        return Ok(None);
    }
    let valid = hardware
        .backend_verdicts
        .iter()
        .any(|verdict| verdict.backend == requested);
    if !valid {
        bail!("unknown backend {requested}; expected auto or a backend reported by hwprobe");
    }
    Ok(Some(requested.to_owned()))
}

fn select_catalog_artifact_for_enclave(
    model: &catalog::CatalogModel,
    enclave: &LedgerEnclave,
    hardware: &HardwareReport,
) -> Option<(String, catalog::CatalogArtifact)> {
    model
        .artifacts
        .iter()
        .filter(|(_, artifact)| artifact.engine == enclave.backend)
        .filter(|(name, artifact)| {
            artifact_hardware_compatibility_base(model, name, artifact, hardware).compatible
        })
        .find(|(_, artifact)| ledger_enclave_matches_catalog_artifact(enclave, artifact))
        .map(|(name, artifact)| (name.clone(), artifact.clone()))
}

fn select_provider_candidate(
    candidates: &[ProviderCandidate],
    requested: Option<&str>,
) -> Result<ProviderCandidate> {
    if let Some(requested) = requested {
        let by_id = is_32_byte_hex(requested);
        return candidates
            .iter()
            .filter(|candidate| {
                if by_id {
                    candidate.enclave.enclave_id == requested
                } else {
                    candidate.enclave.model_id == requested
                }
            })
            .max_by_key(|candidate| {
                if by_id {
                    (0, 0)
                } else {
                    (
                        candidate.enclave.att_tier,
                        backend_rank(&candidate.enclave.backend),
                    )
                }
            })
            .cloned()
            .with_context(|| {
                format!(
                    "requested enclave {requested} is not an active feasible admin-created enclave"
                )
            });
    }

    candidates
        .iter()
        .max_by_key(|candidate| {
            (
                backend_rank(&candidate.enclave.backend),
                candidate.enclave.att_tier,
            )
        })
        .cloned()
        .context("no provider candidate available")
}

fn select_provider_candidate_with_config_defaults(
    contract: &ContractCatalog,
    catalog: &catalog::CatalogDocument,
    hardware: &HardwareReport,
    args: &mut ProviderStartArgs,
    config: Option<&MayhemConfig>,
    requested: Option<&str>,
) -> Result<ProviderCandidate> {
    let candidates = build_provider_candidates(contract, catalog, hardware, args)?;
    let initial_selected = select_provider_candidate(&candidates, requested)?;
    rebuild_provider_candidate_with_config_defaults(
        contract,
        catalog,
        hardware,
        args,
        config,
        &initial_selected,
    )
}

fn rebuild_provider_candidate_with_config_defaults(
    contract: &ContractCatalog,
    catalog: &catalog::CatalogDocument,
    hardware: &HardwareReport,
    args: &mut ProviderStartArgs,
    config: Option<&MayhemConfig>,
    initial_selected: &ProviderCandidate,
) -> Result<ProviderCandidate> {
    apply_provider_config_defaults(args, config, initial_selected);
    let candidates = build_provider_candidates(contract, catalog, hardware, args)?;
    select_provider_candidate(
        &candidates,
        Some(initial_selected.enclave.enclave_id.as_str()),
    )
}

fn provider_candidates_with_config_defaults(
    contract: &ContractCatalog,
    catalog: &catalog::CatalogDocument,
    hardware: &HardwareReport,
    base_args: &ProviderStartArgs,
    config: Option<&MayhemConfig>,
    initial_candidates: &[ProviderCandidate],
) -> Result<Vec<ProviderCandidate>> {
    let mut candidates = Vec::with_capacity(initial_candidates.len());
    let mut rejections = Vec::new();
    for initial in initial_candidates {
        let mut scoped_args = base_args.clone();
        scoped_args.enclave = Some(initial.enclave.enclave_id.clone());
        match rebuild_provider_candidate_with_config_defaults(
            contract,
            catalog,
            hardware,
            &mut scoped_args,
            config,
            initial,
        ) {
            Ok(candidate) => candidates.push(candidate),
            Err(error) => rejections.push(format!(
                "{} ({}): {error:#}",
                initial.enclave.model_id, initial.enclave.enclave_id
            )),
        }
    }
    if candidates.is_empty() {
        bail!(
            "no provider candidates remain after applying enclave-scoped provider limits: {}",
            rejections.join("; ")
        );
    }
    Ok(candidates)
}

fn select_provider_auto_fit_set(
    candidates: &[ProviderCandidate],
) -> Result<ProviderAutoFitSelection> {
    if candidates.is_empty() {
        bail!("no provider candidates available for auto-fit");
    }
    let mut ranked = candidates.iter().collect::<Vec<_>>();
    ranked.sort_by(|a, b| {
        provider_auto_fit_candidate_score(b)
            .partial_cmp(&provider_auto_fit_candidate_score(a))
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.enclave.enclave_id.cmp(&b.enclave.enclave_id))
    });
    let exact_len = ranked.len().min(20);
    let ranked = &ranked[..exact_len];
    let mut best: Option<ProviderAutoFitSelection> = None;
    for mask in 1_u64..(1_u64 << exact_len) {
        let set = ranked
            .iter()
            .enumerate()
            .filter_map(|(index, candidate)| ((mask & (1_u64 << index)) != 0).then_some(*candidate))
            .collect::<Vec<_>>();
        let Some(selection) = provider_auto_fit_selection_from_set(&set) else {
            continue;
        };
        let replace = best
            .as_ref()
            .map(|current| {
                selection
                    .score
                    .partial_cmp(&current.score)
                    .unwrap_or(std::cmp::Ordering::Equal)
                    .is_gt()
                    || ((selection.score - current.score).abs() < f64::EPSILON
                        && selection.candidates.len() > current.candidates.len())
            })
            .unwrap_or(true);
        if replace {
            best = Some(selection);
        }
    }
    best.context("no auto-fit candidate set fits the shared provider memory budget")
}

fn select_provider_explicit_set(
    candidates: &[ProviderCandidate],
    requested: &[String],
) -> Result<ProviderAutoFitSelection> {
    let mut selected = Vec::new();
    let mut seen_enclaves = BTreeSet::new();
    for request in requested {
        let candidate = select_provider_candidate(candidates, Some(request))?;
        if !seen_enclaves.insert(candidate.enclave.enclave_id.clone()) {
            bail!(
                "requested enclave/model {request} resolves to a duplicate admin enclave {}; pass each enclave only once",
                candidate.enclave.enclave_id
            );
        }
        selected.push(candidate);
    }
    let refs = selected.iter().collect::<Vec<_>>();
    let mut selection = provider_auto_fit_selection_from_set(&refs).with_context(|| {
        let required = selected.iter().fold(0_u64, |total, candidate| {
            total.saturating_add(candidate.feasibility.estimated_required_bytes)
        });
        let budget = selected
            .iter()
            .fold(BTreeMap::<String, u64>::new(), |mut pools, candidate| {
                pools
                    .entry(candidate.feasibility.memory_budget.pool.clone())
                    .and_modify(|value| {
                        *value = (*value).min(candidate.feasibility.memory_budget.budget_bytes)
                    })
                    .or_insert(candidate.feasibility.memory_budget.budget_bytes);
                pools
            })
            .values()
            .copied()
            .fold(0_u64, u64::saturating_add);
        format!(
            "requested provider enclave set does not fit the shared memory budget: needs {} against {} after one reserve and current local claims",
            human_bytes(required),
            human_bytes(budget)
        )
    })?;
    let model_names = selection
        .candidates
        .iter()
        .map(|candidate| candidate.enclave.model_id.as_str())
        .collect::<Vec<_>>()
        .join(" + ");
    let modality_label = if selection.modalities.is_empty() {
        "admin markets".to_owned()
    } else {
        selection.modalities.join(",")
    };
    selection.rationale = format!(
        "serving requested {model_names}: fits in {}/{} shared budget across {}; one OS reserve is applied to the set",
        human_bytes(selection.total_required_bytes),
        human_bytes(selection.total_budget_bytes),
        modality_label
    );
    Ok(selection)
}

fn provider_auto_fit_selection_from_set(
    set: &[&ProviderCandidate],
) -> Option<ProviderAutoFitSelection> {
    let mut seen_models = BTreeSet::new();
    let mut pool_budgets: BTreeMap<String, (u64, u64)> = BTreeMap::new();
    let mut modalities = BTreeSet::new();
    let mut score = 0.0_f64;
    for candidate in set {
        if !seen_models.insert(candidate.enclave.model_id.clone()) {
            return None;
        }
        for modality in provider_candidate_modalities(candidate) {
            modalities.insert(modality);
        }
        score += provider_auto_fit_candidate_score(candidate);
        let required = candidate.feasibility.estimated_required_bytes;
        if required == 0 {
            continue;
        }
        let budget = candidate.feasibility.memory_budget.budget_bytes;
        let entry = pool_budgets
            .entry(candidate.feasibility.memory_budget.pool.clone())
            .or_insert((0, budget));
        entry.0 = entry.0.saturating_add(required);
        entry.1 = entry.1.min(budget);
    }
    if pool_budgets
        .values()
        .any(|(required, budget)| required > budget)
    {
        return None;
    }
    let total_required_bytes = pool_budgets.values().fold(0_u64, |total, (required, _)| {
        total.saturating_add(*required)
    });
    let total_budget_bytes = pool_budgets
        .values()
        .fold(0_u64, |total, (_, budget)| total.saturating_add(*budget));
    let modalities = modalities.into_iter().collect::<Vec<_>>();
    let modality_bonus = 1.0 + (modalities.len().saturating_sub(1) as f64 * 0.05);
    let score = score * modality_bonus;
    let candidates = set
        .iter()
        .map(|candidate| (*candidate).clone())
        .collect::<Vec<_>>();
    let model_names = candidates
        .iter()
        .map(|candidate| candidate.enclave.model_id.as_str())
        .collect::<Vec<_>>()
        .join(" + ");
    let modality_label = if modalities.is_empty() {
        "admin markets".to_owned()
    } else {
        modalities.join(",")
    };
    let rationale = format!(
        "serving {model_names}: fits in {}/{} shared budget across {}; best current earnings mix",
        human_bytes(total_required_bytes),
        human_bytes(total_budget_bytes),
        modality_label
    );
    Some(ProviderAutoFitSelection {
        candidates,
        total_required_bytes,
        total_budget_bytes,
        modalities,
        score,
        rationale,
    })
}

fn provider_auto_fit_candidate_score(candidate: &ProviderCandidate) -> f64 {
    let price = candidate
        .price
        .as_ref()
        .and_then(|price| price.current.as_ref());
    let Some(price) = price else {
        return 0.0;
    };
    let per_unit_au = price
        .rate_map
        .iter()
        .map(|entry| entry.per_unit_au as f64 / entry.granularity.max(1) as f64)
        .sum::<f64>();
    let throughput = candidate
        .verdict
        .est_tok_s
        .filter(|value| value.is_finite() && *value > 0.0)
        .unwrap_or_else(|| provider_auto_fit_default_throughput(candidate));
    (per_unit_au * throughput).max((price.per_req_au + price.min_session_au) as f64)
}

fn provider_auto_fit_default_throughput(candidate: &ProviderCandidate) -> f64 {
    if candidate.enclave.model_class == DEFAULT_MODEL_CLASS {
        1.0
    } else {
        0.25
    }
}

fn provider_candidate_modalities(candidate: &ProviderCandidate) -> Vec<String> {
    let mut modalities = BTreeSet::new();
    for modality in &candidate.model.adapter.modality_set {
        if !modality.trim().is_empty() {
            modalities.insert(modality.trim().to_owned());
        }
    }
    for modality in &candidate.model.caps.output_modalities {
        if !modality.trim().is_empty() {
            modalities.insert(modality.trim().to_owned());
        }
    }
    if let Some(modality) = candidate.model.caps.output_modality.as_deref() {
        if !modality.trim().is_empty() {
            modalities.insert(modality.trim().to_owned());
        }
    }
    if candidate.model.caps.vision {
        modalities.insert("vision".to_owned());
    }
    if candidate.model.caps.image {
        modalities.insert("image".to_owned());
    }
    if candidate.model.caps.audio
        && !modalities
            .iter()
            .any(|modality| matches!(modality.as_str(), "audio" | "stt" | "tts"))
    {
        modalities.insert("audio".to_owned());
    }
    if modalities.is_empty() {
        modalities.insert(candidate.enclave.model_class.clone());
    }
    modalities.into_iter().collect()
}

fn backend_rank(backend: &str) -> u8 {
    match backend {
        "vllm" => 4,
        "trt-llm" => 3,
        "mlx" => 2,
        "ace-step" => 2,
        "chatterbox" => 2,
        "needle-cpu" => 1,
        "needle-gpu" => 2,
        "sulphur" => 2,
        "transformers-asr" => 2,
        "llama.cpp" => 1,
        "stable-diffusion.cpp" | "whisper.cpp" | "piper" => 0,
        _ => 0,
    }
}

fn select_provider_rooms(
    rooms: &[LedgerRoom],
    enclave: &LedgerEnclave,
    requested: &str,
) -> Result<Vec<LedgerRoom>> {
    if requested.trim().eq_ignore_ascii_case("auto") {
        let mut selected = rooms
            .iter()
            .filter(|room| {
                room.status == "open"
                    && admin_role_marker_ok(room.creator_role.as_deref())
                    && canonical_room_transport_ok(room)
                    && room_matches_enclave(room, enclave)
            })
            .cloned()
            .collect::<Vec<_>>();
        selected.sort_by(|a, b| a.room_id.cmp(&b.room_id));
        return Ok(selected);
    }

    let requested_ids = requested
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    if requested_ids.is_empty() {
        bail!("--rooms must be auto or a comma-separated list of room ids");
    }
    let mut selected = Vec::new();
    for room_id in requested_ids {
        let room = rooms
            .iter()
            .find(|room| room.room_id == room_id)
            .with_context(|| format!("room {room_id} is not in contract state"))?;
        if room.status != "open" {
            bail!("room {room_id} is not open");
        }
        require_admin_role_marker("room.creator_role", room.creator_role.as_deref())
            .with_context(|| format!("room {room_id} is not admin-created"))?;
        require_canonical_room_transport(room)?;
        if !room_matches_enclave(room, enclave) {
            bail!(
                "room {room_id} is for model {} / enclave {}, not model {} / enclave {}",
                room.model_id,
                room.enclave_id
                    .as_deref()
                    .unwrap_or("<missing-enclave-room>"),
                enclave.model_id,
                enclave.enclave_id
            );
        }
        selected.push(room.clone());
    }
    Ok(selected)
}

async fn derive_provider_secret(
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
) -> Result<Vec<u8>> {
    let sig = sign_message(
        keypair_path,
        password,
        &format!("mayhem-provider-sealing-v1:{}", wallet.public_key),
    )
    .await?;
    Ok(blake3::hash(sig.as_bytes()).as_bytes().to_vec())
}

async fn download_provider_artifact(
    args: &ProviderStartArgs,
    downloads_dir: &Path,
    selected: &ProviderCandidate,
) -> Result<ProviderArtifactPaths> {
    let args = args.clone();
    let downloads_dir = downloads_dir.to_path_buf();
    let selected = selected.clone();
    let result = tokio::task::spawn_blocking(move || {
        download_provider_artifact_blocking(&args, &downloads_dir, &selected)
    })
    .await
    .context("provider artifact download worker panicked")?;
    result
}

fn download_provider_artifact_blocking(
    args: &ProviderStartArgs,
    downloads_dir: &Path,
    selected: &ProviderCandidate,
) -> Result<ProviderArtifactPaths> {
    require_provider_merkle_artifact(selected)?;
    let primary = if let Some(path) = &args.artifact {
        let source = absolutize(path.clone())?;
        let mut progress =
            ProviderProgressBars::new(args, format!("{} local artifact", selected.artifact_name));
        let merkle = build_merkle_manifest_with_progress(&source, args.chunk_size, |event| {
            progress.update(event);
        })
        .with_context(|| {
            format!(
                "verifying local admin-approved artifact {}",
                source.display()
            )
        })?;
        progress.finish();
        if merkle.root != selected.enclave.artifact_root {
            bail!(
                "local artifact root mismatch for {}; expected admin enclave artifact_root {}, got {}",
                source.display(),
                selected.enclave.artifact_root,
                merkle.root
            );
        }
        verify_artifact_sha256(&source, &selected.artifact)?;
        source
    } else {
        let artifact_file = provider_primary_cache_file(selected);
        let destination = downloads_dir.join(artifact_file);
        let mut progress =
            ProviderProgressBars::new(args, format!("{} cached artifact", selected.artifact_name));
        if cached_provider_file_matches(
            &destination,
            args.chunk_size,
            &selected.enclave.artifact_root,
            selected.artifact.source_sha256.as_deref(),
            selected.artifact.weights_bytes,
            Some(&mut progress),
        )? {
            progress.finish();
            destination
        } else if let Some(cached) = find_cached_provider_download(
            downloads_dir,
            args.chunk_size,
            &selected.enclave.artifact_root,
            selected.artifact.source_sha256.as_deref(),
            selected.artifact.weights_bytes,
            &[&selected.artifact_name],
        )? {
            progress.finish();
            cached
        } else {
            progress.finish();
            download_provider_primary_artifact(args, selected, destination)?
        }
    };

    let mut sidecars = BTreeMap::new();
    for (name, sidecar) in &selected.artifact.sidecars {
        let ledger_sidecar = selected
            .enclave
            .artifact_sidecars
            .get(name)
            .with_context(|| format!("admin enclave is missing catalog sidecar {name}"))?;
        let path = download_provider_sidecar_artifact(
            args,
            downloads_dir,
            selected,
            name,
            sidecar,
            ledger_sidecar,
        )?;
        sidecars.insert(name.clone(), path);
    }

    Ok(ProviderArtifactPaths { primary, sidecars })
}

fn download_provider_primary_artifact(
    args: &ProviderStartArgs,
    selected: &ProviderCandidate,
    destination: PathBuf,
) -> Result<PathBuf> {
    if selected.artifact.source.kind != "huggingface" {
        bail!(
            "unsupported artifact source kind {}; pass --artifact with a local copy that matches the admin enclave artifact_root",
            selected.artifact.source.kind
        );
    }
    provider_download_disk_preflight(
        args,
        &destination,
        selected.artifact.weights_bytes,
        &format!("{} artifact", selected.artifact_name),
    )?;
    download_provider_huggingface_file(
        args,
        &selected.artifact.source,
        &selected.artifact.path,
        destination,
        selected.artifact.weights_bytes,
        &selected.enclave.artifact_root,
        selected.artifact.source_sha256.as_deref(),
        &format!("{} artifact", selected.artifact_name),
    )
}

fn download_provider_sidecar_artifact(
    args: &ProviderStartArgs,
    downloads_dir: &Path,
    selected: &ProviderCandidate,
    name: &str,
    sidecar: &catalog::CatalogArtifactSidecar,
    ledger_sidecar: &LedgerArtifactSidecar,
) -> Result<PathBuf> {
    if sidecar.artifact_root_kind != "blake3_merkle_v1" {
        bail!(
            "provider serving requires admin sidecar artifact_root_kind blake3_merkle_v1 for {}/{} sidecar {}; catalog has {}",
            selected.model.model_id,
            selected.artifact_name,
            name,
            sidecar.artifact_root_kind
        );
    }
    let artifact_file = provider_sidecar_cache_file(selected, name, ledger_sidecar);
    let destination = downloads_dir.join(artifact_file);
    let mut progress = ProviderProgressBars::new(
        args,
        format!("{}/{} cached sidecar", selected.artifact_name, name),
    );
    if cached_provider_file_matches(
        &destination,
        args.chunk_size,
        &ledger_sidecar.artifact_root,
        Some(&sidecar.source_sha256),
        ledger_sidecar.weights_bytes,
        Some(&mut progress),
    )? {
        progress.finish();
        return Ok(destination);
    }
    progress.finish();
    if let Some(cached) = find_cached_provider_download(
        downloads_dir,
        args.chunk_size,
        &ledger_sidecar.artifact_root,
        Some(&sidecar.source_sha256),
        ledger_sidecar.weights_bytes,
        &[&selected.artifact_name, name],
    )? {
        return Ok(cached);
    }
    if sidecar.source.kind != "huggingface" {
        bail!(
            "unsupported sidecar source kind {}; sidecar {name} must be an admin-pinned Hugging Face artifact",
            sidecar.source.kind
        );
    }
    provider_download_disk_preflight(
        args,
        &destination,
        ledger_sidecar.weights_bytes,
        &format!("{}/{} sidecar", selected.artifact_name, name),
    )?;
    download_provider_huggingface_file(
        args,
        &sidecar.source,
        &sidecar.path,
        destination,
        ledger_sidecar.weights_bytes,
        &ledger_sidecar.artifact_root,
        Some(&sidecar.source_sha256),
        &format!("{}/{} sidecar", selected.artifact_name, name),
    )
}

#[allow(clippy::too_many_arguments)]
fn download_provider_huggingface_file(
    args: &ProviderStartArgs,
    source: &catalog::SourceRef,
    remote_path: &str,
    destination: PathBuf,
    expected_bytes: u64,
    expected_root: &str,
    expected_sha256: Option<&str>,
    label: &str,
) -> Result<PathBuf> {
    let (owner, repo_name) = source
        .repo
        .split_once('/')
        .with_context(|| format!("invalid admin-pinned Hugging Face repo {}", source.repo))?;
    let parent = destination
        .parent()
        .context("provider artifact destination has no parent directory")?;
    let staging_hash = blake3::hash(destination.to_string_lossy().as_bytes()).to_hex();
    let staging_dir = parent.join(format!(".hf-download-{}", &staging_hash[..16]));
    if staging_dir.exists() {
        fs::remove_dir_all(&staging_dir).with_context(|| {
            format!(
                "removing stale Hugging Face staging directory {}",
                staging_dir.display()
            )
        })?;
    }
    fs::create_dir_all(&staging_dir).with_context(|| {
        format!(
            "creating Hugging Face staging directory {}",
            staging_dir.display()
        )
    })?;

    let result = (|| -> Result<PathBuf> {
        let token = read_optional_token(args.hf_token_file.as_deref())?;
        let user_agent = format!("openmayhem/{}", env!("CARGO_PKG_VERSION"));
        let build_client = || -> Result<HFClientSync> {
            let mut client_builder = HFClient::builder()
                .cache_enabled(false)
                .user_agent(&user_agent);
            if let Some(token) = token.as_ref() {
                client_builder = client_builder.token(token);
            }
            HFClientSync::from_inner(client_builder.build()?)
                .context("starting the Hugging Face transfer client")
        };

        let standard_client = build_client()?;
        let repository = standard_client.model(owner, repo_name);
        let metadata = repository
            .get_paths_info()
            .paths(vec![remote_path.to_owned()])
            .revision(source.revision.clone())
            .send()
            .with_context(|| {
                format!(
                    "reading immutable Hugging Face artifact metadata for {}/{}@{}:{}",
                    owner, repo_name, source.revision, remote_path
                )
            })?
            .into_iter()
            .find_map(|entry| match entry {
                RepoTreeEntry::File {
                    path,
                    size,
                    xet_hash,
                    ..
                } if path == remote_path => Some((size, xet_hash)),
                _ => None,
            })
            .with_context(|| {
                format!(
                    "admin-pinned Hugging Face artifact is missing at {}/{}@{}:{}",
                    owner, repo_name, source.revision, remote_path
                )
            })?;
        if metadata.0 != expected_bytes {
            bail!(
                "Hugging Face reports {label} as {} bytes; admin catalog requires {expected_bytes}",
                metadata.0
            );
        }

        let progress = Arc::new(HuggingFaceProviderProgress::new(
            args,
            label,
            expected_bytes,
        ));
        let download = if let Some(xet_hash) = metadata.1 {
            download_provider_huggingface_xet_file(
                owner,
                repo_name,
                &source.revision,
                &xet_hash,
                expected_bytes,
                token.as_deref(),
                &user_agent,
                &staging_dir.join("payload"),
                Arc::clone(&progress),
            )
        } else {
            standard_client
                .model(owner, repo_name)
                .download_file()
                .filename(remote_path.to_owned())
                .revision(source.revision.clone())
                .local_dir(staging_dir.clone())
                .progress(Arc::clone(&progress))
                .send()
                .map_err(anyhow::Error::from)
        };
        let download = download.with_context(|| {
            format!(
                "downloading admin-pinned Hugging Face artifact {}/{}@{}:{}",
                owner, repo_name, source.revision, remote_path
            )
        });
        progress.finish(download.is_ok());
        let downloaded = download?;

        let actual_bytes = fs::metadata(&downloaded)
            .with_context(|| format!("reading downloaded artifact {}", downloaded.display()))?
            .len();
        if actual_bytes != expected_bytes {
            bail!(
                "downloaded {label} has {actual_bytes} bytes; admin catalog requires {expected_bytes}"
            );
        }

        let mut verify_progress = ProviderProgressBars::new(args, label);
        let manifest = build_merkle_manifest_with_progress(&downloaded, args.chunk_size, |event| {
            verify_progress.update(event);
        });
        verify_progress.finish();
        let manifest = manifest.with_context(|| {
            format!(
                "verifying downloaded Hugging Face artifact {}",
                downloaded.display()
            )
        })?;
        if manifest.root != expected_root {
            bail!(
                "downloaded {label} root mismatch; expected admin artifact root {expected_root}, got {}",
                manifest.root
            );
        }
        if let Some(expected_sha256) = expected_sha256 {
            let actual_sha256 = file_sha256_hex(&downloaded)?;
            if !actual_sha256.eq_ignore_ascii_case(expected_sha256) {
                bail!(
                    "downloaded {label} sha256 mismatch; expected admin catalog source_sha256 {expected_sha256}, got {actual_sha256}"
                );
            }
        }

        if destination.exists() {
            fs::remove_file(&destination).with_context(|| {
                format!("removing invalid cached artifact {}", destination.display())
            })?;
        }
        fs::rename(&downloaded, &destination).with_context(|| {
            format!(
                "installing verified artifact {} at {}",
                downloaded.display(),
                destination.display()
            )
        })?;
        Ok(destination.clone())
    })();

    let cleanup = fs::remove_dir_all(&staging_dir);
    if result.is_ok() {
        cleanup.with_context(|| {
            format!(
                "removing Hugging Face staging directory {}",
                staging_dir.display()
            )
        })?;
    }
    result
}

#[allow(clippy::too_many_arguments)]
fn download_provider_huggingface_xet_file(
    owner: &str,
    repo_name: &str,
    revision: &str,
    xet_hash: &str,
    expected_bytes: u64,
    token: Option<&str>,
    user_agent: &str,
    destination: &Path,
    progress: Arc<HuggingFaceProviderProgress>,
) -> Result<PathBuf> {
    let token_url =
        format!("https://huggingface.co/api/models/{owner}/{repo_name}/xet-read-token/{revision}");
    let http_client = reqwest::blocking::Client::builder()
        .user_agent(user_agent)
        .build()
        .context("building the Hugging Face Xet token client")?;
    let mut request = http_client.get(&token_url);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let connection = request
        .send()
        .context("requesting a Hugging Face Xet read token")?
        .error_for_status()
        .context("Hugging Face refused the Xet read-token request")?
        .json::<HuggingFaceXetConnection>()
        .context("decoding the Hugging Face Xet read-token response")?;
    let cas_url =
        reqwest::Url::parse(&connection.cas_url).context("parsing the Hugging Face Xet CAS URL")?;
    ensure!(
        cas_url.scheme() == "https" && cas_url.host_str().is_some(),
        "Hugging Face returned an unsafe Xet CAS URL"
    );
    let cas_endpoint = cas_url.as_str().trim_end_matches('/').to_owned();

    let mut refresh_headers = reqwest::header::HeaderMap::new();
    refresh_headers.insert(
        reqwest::header::USER_AGENT,
        reqwest::header::HeaderValue::from_str(user_agent)
            .context("building the Hugging Face Xet user-agent header")?,
    );
    if let Some(token) = token {
        refresh_headers.insert(
            reqwest::header::AUTHORIZATION,
            reqwest::header::HeaderValue::from_str(&format!("Bearer {token}"))
                .context("building the Hugging Face Xet authorization header")?,
        );
    }

    let xet_hash = xet_hash.to_owned();
    let destination = destination.to_path_buf();
    std::thread::spawn(move || -> Result<PathBuf> {
        // This thread intentionally has no ambient Tokio handle. hf-xet's
        // blocking API then owns its runtime instead of selecting External mode.
        if std::env::var_os("HF_XET_LOG_DEST").is_some()
            || std::env::var_os("HF_XET_LOG_FILE").is_some()
        {
            HF_XET_LOGGING_INIT.call_once(|| {
                xet::init_logging(format!("openmayhem/{}", env!("CARGO_PKG_VERSION")));
            });
        }
        let session = XetSessionBuilder::new()
            .build()
            .context("starting the Hugging Face Xet session")?;
        let group = session
            .new_file_download_group()
            .context("creating the Hugging Face Xet download group")?
            .with_endpoint(cas_endpoint)
            .with_token_info(connection.access_token, connection.exp)
            .with_token_refresh_url(token_url, refresh_headers)
            .build_blocking()
            .context("authorizing the Hugging Face Xet download group")?;
        let handle = group
            .download_file_to_path_blocking(
                XetFileInfo::new(xet_hash, expected_bytes),
                destination.clone(),
            )
            .context("starting the Hugging Face Xet artifact download")?;

        let poll_done = Arc::new(AtomicBool::new(false));
        let poller = {
            let handle = handle.clone();
            let poll_done = Arc::clone(&poll_done);
            std::thread::spawn(move || {
                while !poll_done.load(Ordering::Relaxed) {
                    if let Some(report) = handle.progress() {
                        progress.record(report.bytes_completed, report.total_bytes, "running");
                    }
                    if handle.result().is_some() {
                        break;
                    }
                    std::thread::sleep(Duration::from_millis(250));
                }
                if let Some(report) = handle.progress() {
                    progress.record(report.bytes_completed, report.total_bytes, "running");
                }
            })
        };
        let result = group
            .finish_blocking()
            .context("finishing the Hugging Face Xet artifact download");
        poll_done.store(true, Ordering::Relaxed);
        let _ = poller.join();
        result?;
        Ok(destination)
    })
    .join()
    .map_err(|_| anyhow!("Hugging Face Xet worker thread panicked"))?
}

fn provider_download_partial_path(destination: &Path) -> PathBuf {
    let mut path = destination.to_path_buf();
    let file_name = destination
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("artifact");
    path.set_file_name(format!("{file_name}.part"));
    path
}

fn provider_download_disk_preflight(
    args: &ProviderStartArgs,
    destination: &Path,
    expected_bytes: u64,
    label: &str,
) -> Result<()> {
    if expected_bytes == 0 {
        bail!(
            "admin catalog is missing weights_bytes for {label}; cannot safely pre-check disk space before download"
        );
    }
    let part = provider_download_partial_path(destination);
    let mut partial_bytes = fs::metadata(&part)
        .ok()
        .filter(|metadata| metadata.is_file())
        .map(|metadata| metadata.len())
        .unwrap_or(0);
    if partial_bytes > expected_bytes {
        let _ = fs::remove_file(&part);
        partial_bytes = 0;
    }
    let remaining_bytes = expected_bytes.saturating_sub(partial_bytes);
    let (reserve_bytes, reserve_source) =
        provider_disk_reserve_bytes(args.disk_reserve.as_deref())?;
    let available_bytes = available_bytes_for_path(destination)?.with_context(|| {
        format!(
            "checking available disk space for {}",
            destination.display()
        )
    })?;
    let required_bytes = remaining_bytes.saturating_add(reserve_bytes);
    if available_bytes < required_bytes {
        bail!(
            "Not enough disk space to download {label}: need {} remaining download bytes plus {} reserve ({reserve_source}), but only {} is free at {}. Free space, choose a different --downloads-dir, or adjust --disk-reserve.",
            human_bytes(remaining_bytes),
            human_bytes(reserve_bytes),
            human_bytes(available_bytes),
            destination.display()
        );
    }
    Ok(())
}

fn provider_primary_cache_file(selected: &ProviderCandidate) -> String {
    let sha = selected
        .artifact
        .source_sha256
        .as_deref()
        .unwrap_or("no-source-sha256");
    format!(
        "root-{}-sha-{}-{}",
        safe_path_component(&selected.enclave.artifact_root),
        safe_path_component(sha),
        safe_path_component(&selected.artifact_name)
    )
}

fn provider_sidecar_cache_file(
    selected: &ProviderCandidate,
    name: &str,
    sidecar: &LedgerArtifactSidecar,
) -> String {
    format!(
        "root-{}-sha-{}-{}-{}",
        safe_path_component(&sidecar.artifact_root),
        safe_path_component(&sidecar.source_sha256),
        safe_path_component(&selected.artifact_name),
        safe_path_component(name)
    )
}

fn cached_provider_file_matches(
    path: &Path,
    chunk_size: usize,
    expected_root: &str,
    expected_sha256: Option<&str>,
    expected_bytes: u64,
    progress: Option<&mut ProviderProgressBars>,
) -> Result<bool> {
    let Ok(metadata) = fs::metadata(path) else {
        return Ok(false);
    };
    if !metadata.is_file() {
        return Ok(false);
    }
    if expected_bytes > 0 && metadata.len() != expected_bytes {
        return Ok(false);
    }
    let merkle = if let Some(progress) = progress {
        build_merkle_manifest_with_progress(path, chunk_size, |event| {
            progress.update(event);
        })?
    } else {
        build_merkle_manifest(path, chunk_size)?
    };
    if merkle.root != expected_root {
        return Ok(false);
    }
    if let Some(expected_sha256) = expected_sha256 {
        if !file_sha256_hex(&path.to_path_buf())?.eq_ignore_ascii_case(expected_sha256) {
            return Ok(false);
        }
    }
    Ok(true)
}

fn find_cached_provider_download(
    downloads_dir: &Path,
    chunk_size: usize,
    expected_root: &str,
    expected_sha256: Option<&str>,
    expected_bytes: u64,
    name_hints: &[&str],
) -> Result<Option<PathBuf>> {
    let Ok(entries) = fs::read_dir(downloads_dir) else {
        return Ok(None);
    };
    for entry in entries {
        let entry = entry?;
        let path = entry.path();
        let Some(file_name) = path.file_name().and_then(|name| name.to_str()) else {
            continue;
        };
        if file_name.ends_with(".part")
            || !name_hints
                .iter()
                .all(|hint| file_name.contains(&safe_path_component(hint)))
        {
            continue;
        }
        if cached_provider_file_matches(
            &path,
            chunk_size,
            expected_root,
            expected_sha256,
            expected_bytes,
            None,
        )? {
            return Ok(Some(path));
        }
    }
    Ok(None)
}

fn require_provider_merkle_artifact(selected: &ProviderCandidate) -> Result<()> {
    if selected.artifact.artifact_root_kind != "blake3_merkle_v1" {
        bail!(
            "provider serving requires admin artifact_root_kind blake3_merkle_v1 for {}/{}; catalog has {}",
            selected.model.model_id,
            selected.artifact_name,
            selected.artifact.artifact_root_kind
        );
    }
    Ok(())
}

fn artifact_sha256_matches(path: &Path, artifact: &catalog::CatalogArtifact) -> Result<bool> {
    let Some(expected) = &artifact.source_sha256 else {
        return Ok(true);
    };
    if path.is_dir() {
        return Ok(true);
    }
    Ok(file_sha256_hex(path)? == expected.to_ascii_lowercase())
}

fn verify_artifact_sha256(path: &Path, artifact: &catalog::CatalogArtifact) -> Result<()> {
    if artifact_sha256_matches(path, artifact)? {
        return Ok(());
    }
    bail!(
        "artifact sha256 mismatch for {}; expected admin catalog source_sha256 {}",
        path.display(),
        artifact.source_sha256.as_deref().unwrap_or("<missing>")
    )
}

fn file_sha256_hex(path: &Path) -> Result<String> {
    let mut file = fs::File::open(path).with_context(|| format!("opening {}", path.display()))?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 1024 * 64];
    loop {
        let read = file
            .read(&mut buffer)
            .with_context(|| format!("reading {}", path.display()))?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Ok(format!("{:x}", hasher.finalize()))
}

fn sha256_bytes_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("{:x}", hasher.finalize())
}

fn read_optional_token(path: Option<&Path>) -> Result<Option<String>> {
    if let Some(path) = path {
        return fs::read_to_string(path)
            .with_context(|| format!("reading token file {}", path.display()))
            .map(|value| Some(value.trim().to_owned()));
    }
    Ok(env::var("HF_TOKEN")
        .ok()
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty()))
}

fn serve_state_matches_context_terms(
    existing: &Value,
    serve_terms: &ProviderJoinContextTerms,
) -> bool {
    if existing.get("served_ctx").and_then(Value::as_u64) != Some(serve_terms.served_ctx) {
        return false;
    }
    let existing_modalities = existing
        .get("served_modalities")
        .and_then(Value::as_array)
        .map(|values| values.iter().filter_map(Value::as_str).collect::<Vec<_>>());
    let expected_modalities = serve_terms
        .served_modalities
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    if existing_modalities.as_deref() != Some(expected_modalities.as_slice()) {
        return false;
    }
    let existing_specialities = existing
        .get("served_specialities")
        .cloned()
        .and_then(|value| serde_json::from_value(value).ok());
    if existing_specialities.as_ref() != Some(&serve_terms.served_specialities) {
        return false;
    }
    let existing_ctx_bracket = existing.get("ctx_bracket").and_then(Value::as_str);
    if existing_ctx_bracket != serve_terms.ctx_bracket.as_deref() {
        return false;
    }
    let existing_ctx_bracket_table_ver = existing
        .get("ctx_bracket_table_ver")
        .and_then(Value::as_u64)
        .and_then(|value| u32::try_from(value).ok());
    existing_ctx_bracket_table_ver == serve_terms.ctx_bracket_table_ver
}

fn seal_provider_artifact(
    artifact_path: &Path,
    sealed_store: &Path,
    key_context: &KeyContext,
    provider_secret: &[u8],
    chunk_size: usize,
) -> Result<DownloadReport> {
    if sealed_store.join(SEALED_STORE_MANIFEST).exists() {
        let manifest = read_sealed_manifest(sealed_store)?;
        if &manifest.key_context != key_context {
            bail!(
                "sealed store context mismatch for {}",
                sealed_store.display()
            );
        }
        if manifest.merkle.root != key_context.artifact_root {
            bail!(
                "sealed store artifact root mismatch for {}: expected {}, got {}",
                sealed_store.display(),
                key_context.artifact_root,
                manifest.merkle.root
            );
        }
        return Ok(DownloadReport {
            destination: sealed_store.to_path_buf(),
            resumed_from: 0,
            bytes_written: 0,
            total_bytes: manifest.merkle.total_bytes,
            merkle: manifest.merkle,
        });
    }

    let mut options = SealOptions::new(
        artifact_path,
        sealed_store,
        key_context.clone(),
        provider_secret.to_vec(),
    );
    options.chunk_size = chunk_size;
    options.expected_merkle_root = Some(key_context.artifact_root.clone());
    let report = seal_artifact(&options)?;
    let manifest = read_sealed_manifest(&report.store_dir)?;
    Ok(DownloadReport {
        destination: report.store_dir,
        resumed_from: 0,
        bytes_written: report.total_bytes,
        total_bytes: report.total_bytes,
        merkle: manifest.merkle,
    })
}

async fn ensure_provider_registered(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    sim: bool,
) -> Result<Value> {
    let key = format!("prov/{}", wallet.public_key);
    if let Some(existing) = read_state_value(rpc, &key).await? {
        let status = existing.get("status").and_then(Value::as_str).unwrap_or("");
        if status == "active" {
            return Ok(
                json!({ "skipped": true, "reason": "already_registered", "state": existing }),
            );
        }
        bail!("provider registration exists but is not active: {existing}");
    }

    let submitted = submit_provider_lifecycle_feature(
        ProviderLifecycleSubmitContext {
            rpc,
            keypair_path,
            password,
            wallet,
            sim,
        },
        "register_provider",
        None,
        None,
    )
    .await?;
    if sim {
        return Ok(submitted);
    }
    let state = wait_for_state(rpc, &key, |value| {
        value.get("status").and_then(Value::as_str) == Some("active")
    })
    .await?;
    Ok(json!({ "skipped": false, "feature": submitted, "state": state }))
}

async fn ensure_joined_enclave(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    enclave: &LedgerEnclave,
    serve_terms: &ProviderJoinContextTerms,
    hardware_fingerprint: Option<&str>,
    device_key: Option<&str>,
    attestation: &ProviderJoinAttestationEvidence,
    sim: bool,
) -> Result<Value> {
    let key = format!("serve/{}/{}", wallet.public_key, enclave.enclave_id);
    if let Some(existing) = read_state_value(rpc, &key).await? {
        if existing.get("status").and_then(Value::as_str) == Some("active") {
            if !serve_state_matches_context_terms(&existing, serve_terms) {
                bail!(
                    "provider is already joined to enclave {} with missing or different committed context terms; leave and rejoin before serving paid sessions",
                    enclave.enclave_id
                );
            }
            return Ok(
                json!({ "skipped": true, "reason": "already_joined_enclave", "state": existing }),
            );
        }
    }
    let submitted = submit_provider_lifecycle_feature_with_anchors(
        ProviderLifecycleSubmitContext {
            rpc,
            keypair_path,
            password,
            wallet,
            sim,
        },
        "join_enclave",
        Some(&enclave.enclave_id),
        None,
        hardware_fingerprint,
        device_key,
        Some(serve_terms),
        Some(attestation),
    )
    .await?;
    if sim {
        return Ok(submitted);
    }
    let state = wait_for_state(rpc, &key, |value| {
        value.get("status").and_then(Value::as_str) == Some("active")
    })
    .await?;
    Ok(json!({ "skipped": false, "feature": submitted, "state": state }))
}

async fn ensure_joined_rooms(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    enclave: &LedgerEnclave,
    rooms: &[LedgerRoom],
    sim: bool,
) -> Result<Vec<Value>> {
    let mut reports = Vec::new();
    for room in rooms {
        let key = format!(
            "roomserve/{}/{}/{}",
            room.room_id, wallet.public_key, enclave.enclave_id
        );
        if let Some(existing) = read_state_value(rpc, &key).await? {
            if existing.get("status").and_then(Value::as_str) == Some("active") {
                reports.push(json!({
                    "room_id": room.room_id,
                    "skipped": true,
                    "reason": "already_joined_room",
                    "state": existing,
                }));
                continue;
            }
        }
        let submitted = submit_provider_lifecycle_feature(
            ProviderLifecycleSubmitContext {
                rpc,
                keypair_path,
                password,
                wallet,
                sim,
            },
            "join_room",
            Some(&enclave.enclave_id),
            Some(&room.room_id),
        )
        .await?;
        if sim {
            reports.push(json!({ "room_id": room.room_id, "feature": submitted }));
            continue;
        }
        let state = wait_for_state(rpc, &key, |value| {
            value.get("status").and_then(Value::as_str) == Some("active")
        })
        .await?;
        reports.push(
            json!({ "room_id": room.room_id, "skipped": false, "feature": submitted, "state": state }),
        );
    }
    Ok(reports)
}

fn admin_contract_tx_feature(
    tx: &str,
    prepared_command: &Value,
    address: &str,
    signature: &str,
    nonce: &str,
    sim: bool,
    context: &Value,
) -> Result<Value> {
    ensure!(
        is_hex_len(tx, 64),
        "prepared admin transaction id must be 32-byte hexadecimal"
    );
    ensure!(
        is_hex_len(address, 64),
        "admin signing address must be 32-byte hexadecimal"
    );
    ensure!(
        is_hex_len(signature, 128),
        "admin transaction signature must be 64-byte hexadecimal"
    );
    ensure!(
        is_hex_len(nonce, 64),
        "admin transaction nonce must be 32-byte hexadecimal"
    );
    prepared_command
        .get("type")
        .and_then(Value::as_str)
        .context("prepared admin command is missing type")?;
    ensure!(
        prepared_command.get("value").is_some(),
        "prepared admin command is missing value"
    );
    Ok(json!({
        "feature": "mayhem",
        "key": format!("admin/contract-tx/{tx}"),
        "value": {
            "op": "admin_contract_tx",
            "tx": tx,
            "prepared_command": prepared_command,
            "address": address,
            "signature": signature,
            "nonce": nonce,
            "sim": sim,
            "context": context,
        },
    }))
}

fn admin_contract_tx_digest(
    prepared_command: &Value,
    address: &str,
    nonce: &str,
    sim: bool,
    context: &Value,
) -> String {
    stable_value_hash(&json!({
        "address": address.to_ascii_lowercase(),
        "context": context,
        "domain": "mayhem-admin-contract-tx-v1",
        "nonce": nonce.to_ascii_lowercase(),
        "prepared_command": prepared_command,
        "sim": sim,
    }))
}

async fn submit_contract_command(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    tx_type: &str,
    value: Value,
    sim: bool,
) -> Result<Value> {
    let prepared_command = json!({
        "type": tx_type,
        "value": value,
    });
    let admin = read_state_value(rpc, "admin")
        .await?
        .and_then(|value| value.as_str().map(str::to_ascii_lowercase))
        .context("contract admin is not initialized")?;
    ensure!(
        is_hex_len(&admin, 64),
        "contract admin must be 32-byte hexadecimal"
    );
    ensure!(
        wallet.public_key.eq_ignore_ascii_case(&admin),
        "admin command signing wallet does not match the current contract admin"
    );
    let status = rpc
        .status()
        .await
        .context("reading local Intercom transport for admin submission")?;
    let peer = status
        .get("peer")
        .and_then(Value::as_object)
        .context("local Intercom status is missing peer identity")?;
    let transport = peer
        .get("pubKeyHex")
        .and_then(Value::as_str)
        .map(str::to_ascii_lowercase)
        .context("local Intercom status is missing transport identity")?;
    ensure!(
        is_hex_len(&transport, 64),
        "local Intercom transport must be 32-byte hexadecimal"
    );
    let status_admin = peer
        .get("admin")
        .and_then(Value::as_str)
        .map(str::to_ascii_lowercase)
        .context("local Intercom status is missing canonical admin identity")?;
    ensure!(
        status_admin == admin,
        "local Intercom and contract state disagree on admin identity"
    );
    let base_writable = peer
        .get("baseWritable")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let subnet_bootstrap = peer
        .get("subnetBootstrapHex")
        .and_then(Value::as_str)
        .map(str::to_ascii_lowercase)
        .context("local Intercom status is missing the canonical subnet bootstrap")?;
    ensure!(
        is_hex_len(&subnet_bootstrap, 64),
        "canonical subnet bootstrap must be 32-byte hexadecimal"
    );
    let msb = status
        .get("msb")
        .and_then(Value::as_object)
        .context("local Intercom status is missing MSB network identity")?;
    let msb_bootstrap = msb
        .get("bootstrapHex")
        .and_then(Value::as_str)
        .map(str::to_ascii_lowercase)
        .context("local Intercom status is missing the MSB bootstrap")?;
    ensure!(
        is_hex_len(&msb_bootstrap, 64),
        "MSB bootstrap must be 32-byte hexadecimal"
    );
    let network_id = msb
        .get("networkId")
        .and_then(Value::as_u64)
        .context("local Intercom status is missing the MSB network id")?;
    let health = rpc
        .health()
        .await
        .context("reading verified Intercom contract identity")?;
    let contract_version = health
        .get("contract_version")
        .and_then(Value::as_u64)
        .context("Intercom health is missing the verified contract version")?;
    let context = json!({
        "contract_version": contract_version,
        "msb_bootstrap": msb_bootstrap,
        "network_id": network_id,
        "subnet_bootstrap": subnet_bootstrap,
    });
    let nonce_response = rpc
        .contract_nonce()
        .await
        .context("requesting contract nonce")?;
    let nonce = nonce_response
        .get("nonce")
        .and_then(Value::as_str)
        .context("RPC nonce response did not include nonce")?;
    ensure!(
        is_hex_len(nonce, 64),
        "RPC nonce response must contain a 32-byte hexadecimal nonce"
    );
    let tx = admin_contract_tx_digest(&prepared_command, &admin, nonce, sim, &context);
    let command_hash = stable_value_hash(&prepared_command);
    let signature = sign_hex(keypair_path, password, &tx).await?;
    let signed_tx = json!({
        "tx": tx,
        "prepared_command": prepared_command.clone(),
        "address": admin,
        "signature": signature,
        "nonce": nonce,
        "sim": sim,
    });
    let feature = admin_contract_tx_feature(
        signed_tx["tx"].as_str().unwrap_or_default(),
        &signed_tx["prepared_command"],
        signed_tx["address"].as_str().unwrap_or_default(),
        signed_tx["signature"].as_str().unwrap_or_default(),
        signed_tx["nonce"].as_str().unwrap_or_default(),
        sim,
        &context,
    )?;
    let submitted = rpc
        .submit_feature(&feature)
        .await
        .with_context(|| format!("submitting signed {tx_type} through the Mayhem admin feature"))?;
    let submission_transport = if base_writable && transport == admin {
        "admin_feature_direct"
    } else {
        "admin_feature_relay"
    };
    if submitted.get("ok").and_then(Value::as_bool) == Some(false) {
        bail!("contract {tx_type} rejected command: {submitted}");
    }
    let result = submitted
        .get("result")
        .cloned()
        .unwrap_or_else(|| submitted.clone());
    let accepted = result.get("ok").and_then(Value::as_bool) == Some(true)
        || (result.get("local").and_then(Value::as_bool) == Some(true)
            && result.get("txo").is_some());
    if !accepted {
        bail!("contract {tx_type} rejected command: {result}");
    }
    Ok(json!({
        "tx": signed_tx["tx"],
        "command_hash": command_hash,
        "transport": submission_transport,
        "transport_peer": transport,
        "result": result,
    }))
}

struct ProviderLifecycleSubmitContext<'a> {
    rpc: &'a PeerRpcClient,
    keypair_path: &'a Path,
    password: &'a str,
    wallet: &'a WalletInfo,
    sim: bool,
}

async fn submit_provider_lifecycle_feature(
    ctx: ProviderLifecycleSubmitContext<'_>,
    op: &str,
    enclave_id: Option<&str>,
    room_id: Option<&str>,
) -> Result<Value> {
    submit_provider_lifecycle_feature_with_anchors(
        ctx, op, enclave_id, room_id, None, None, None, None,
    )
    .await
}

async fn submit_provider_lifecycle_feature_with_anchors(
    ctx: ProviderLifecycleSubmitContext<'_>,
    op: &str,
    enclave_id: Option<&str>,
    room_id: Option<&str>,
    hardware_fingerprint: Option<&str>,
    device_key: Option<&str>,
    join_terms: Option<&ProviderJoinContextTerms>,
    attestation: Option<&ProviderJoinAttestationEvidence>,
) -> Result<Value> {
    let intent = provider_lifecycle_intent_with_anchors(
        &ctx.wallet.public_key,
        op,
        enclave_id,
        room_id,
        hardware_fingerprint,
        device_key,
        join_terms,
        attestation,
    )?;
    submit_provider_lifecycle_intent(ctx, intent).await
}

async fn submit_provider_lifecycle_intent(
    ctx: ProviderLifecycleSubmitContext<'_>,
    intent: Value,
) -> Result<Value> {
    let op = intent
        .get("op")
        .and_then(Value::as_str)
        .context("provider lifecycle intent missing op")?
        .to_owned();
    let feature = signed_provider_lifecycle_feature(&ctx, &intent).await?;
    if ctx.sim {
        return Ok(json!({
            "feature": feature["feature"].clone(),
            "key": feature["key"].clone(),
            "value": feature["value"].clone(),
            "sim": true,
            "submitted": false,
        }));
    }
    ensure!(
        !matches!(op.as_str(), "leave_room" | "leave_enclave"),
        "provider leave submissions must use the durable leave outbox"
    );
    let submitted = ctx
        .rpc
        .submit_feature(feature.clone())
        .await
        .with_context(|| format!("submitting free provider lifecycle feature {op}"))?;
    if submitted.get("ok").and_then(Value::as_bool) != Some(true) {
        bail!("provider lifecycle feature {op} was not accepted: {submitted}");
    }
    Ok(json!({
        "feature": feature["feature"].clone(),
        "key": feature["key"].clone(),
        "value": feature["value"].clone(),
        "result": submitted,
    }))
}

async fn signed_provider_lifecycle_feature(
    ctx: &ProviderLifecycleSubmitContext<'_>,
    intent: &Value,
) -> Result<Value> {
    let sig = sign_message(
        ctx.keypair_path,
        ctx.password,
        &provider_lifecycle_intent_message(intent),
    )
    .await?;
    let key = provider_lifecycle_feature_key(intent)?;
    let value = json!({
        "op": "provider_lifecycle",
        "intent": intent,
        "sig": sig,
    });
    Ok(json!({
        "feature": "mayhem",
        "key": key,
        "value": value,
    }))
}

async fn queue_signed_provider_leave(
    ctx: &ProviderTxContext,
    op: ProviderLeaveOp,
    enclave_id: &str,
    room_id: Option<&str>,
) -> Result<SignedProviderLeaveOutboxEntry> {
    ensure!(
        matches!(
            (op, room_id),
            (ProviderLeaveOp::Room, Some(_)) | (ProviderLeaveOp::Enclave, None)
        ),
        "provider leave outbox op and room scope do not match"
    );
    let mut pending = load_provider_leave_outbox(&ctx.home)?
        .into_iter()
        .filter(|entry| {
            entry.provider == ctx.wallet.public_key
                && entry.op == op
                && entry.enclave_id == enclave_id
                && entry.room_id.as_deref() == room_id
        })
        .collect::<Vec<_>>();
    ensure!(
        pending.len() <= 1,
        "provider leave outbox contains duplicate pending entries for {}",
        op.as_str()
    );
    if let Some(entry) = pending.pop() {
        return Ok(entry);
    }
    let intent = provider_lifecycle_intent_with_anchors(
        &ctx.wallet.public_key,
        op.as_str(),
        Some(enclave_id),
        room_id,
        None,
        None,
        None,
        None,
    )?;
    let submit_context = ProviderLifecycleSubmitContext {
        rpc: &ctx.rpc,
        keypair_path: &ctx.keypair_path,
        password: &ctx.password,
        wallet: &ctx.wallet,
        sim: false,
    };
    let feature = signed_provider_lifecycle_feature(&submit_context, &intent).await?;
    persist_provider_leave_outbox_feature(&ctx.home, &feature, &ctx.wallet.public_key)
}

async fn read_state_value(rpc: &PeerRpcClient, key: &str) -> Result<Option<Value>> {
    let state = rpc
        .state(Some(key), Some(false))
        .await
        .with_context(|| format!("reading {key} from peer RPC"))?;
    Ok(state.get("value").cloned().filter(|value| !value.is_null()))
}

async fn read_confirmed_state_value(rpc: &PeerRpcClient, key: &str) -> Result<Option<Value>> {
    let state = rpc
        .state(Some(key), Some(true))
        .await
        .with_context(|| format!("reading confirmed {key} from peer RPC"))?;
    ensure!(
        state.get("confirmed").and_then(Value::as_bool) == Some(true)
            && state.get("signed_length").and_then(Value::as_u64).is_some()
            && state.get("key").and_then(Value::as_str) == Some(key),
        "peer RPC returned mismatched confirmed state evidence for {key}"
    );
    Ok(state.get("value").cloned().filter(|value| !value.is_null()))
}

async fn read_state_value_at(
    rpc: &PeerRpcClient,
    key: &str,
    signed_length: u64,
) -> Result<Option<Value>> {
    let state = rpc
        .state_at(Some(key), Some(true), Some(signed_length))
        .await
        .with_context(|| {
            format!("reading {key} at confirmed signed length {signed_length} from peer RPC")
        })?;
    ensure!(
        state.get("confirmed").and_then(Value::as_bool) == Some(true)
            && state.get("signed_length").and_then(Value::as_u64) == Some(signed_length)
            && state.get("key").and_then(Value::as_str) == Some(key),
        "peer RPC returned mismatched exact state evidence for {key}"
    );
    Ok(state.get("value").cloned().filter(|value| !value.is_null()))
}

async fn confirmed_snapshot_signed_length(rpc: &PeerRpcClient, prefix: &str) -> Result<u64> {
    let response = rpc
        .state_prefix_page(prefix, Some(true), Some(1), None, None)
        .await
        .with_context(|| format!("reading current confirmed signed length for {prefix}*"))?;
    let parsed: PrefixStateResponse =
        serde_json::from_value(response).context("parsing confirmed snapshot evidence")?;
    ensure!(
        parsed.confirmed && parsed.prefix == prefix,
        "peer RPC returned invalid confirmed snapshot evidence"
    );
    Ok(parsed.signed_length)
}

async fn ensure_confirmed_snapshot_current(
    rpc: &PeerRpcClient,
    prefix: &str,
    expected_signed_length: u64,
) -> Result<()> {
    let current = confirmed_snapshot_signed_length(rpc, prefix).await?;
    ensure!(
        current == expected_signed_length,
        "confirmed ledger snapshot advanced from signed length {expected_signed_length} to {current}; re-plan before any external payout side effect"
    );
    Ok(())
}

async fn epoch_apply_anchor_at(
    rpc: &PeerRpcClient,
    epoch: u64,
    signed_length: u64,
) -> Result<String> {
    let key = format!("epoch/apply-anchor/{epoch}");
    let anchor = read_state_value_at(rpc, &key, signed_length)
        .await?
        .with_context(|| format!("{key} not found; apply the requested epoch before settlement"))?;
    ensure!(
        anchor.get("type").and_then(Value::as_str) == Some("epoch_apply_anchor")
            && anchor.get("epoch").and_then(Value::as_u64) == Some(epoch)
            && anchor
                .get("applied_at")
                .and_then(Value::as_str)
                .is_some_and(|value| !value.is_empty()),
        "{key} is invalid"
    );
    Ok(anchor
        .get("apply_hash")
        .and_then(Value::as_str)
        .filter(|hash| is_hex_len(hash, 64))
        .with_context(|| format!("{key} is missing its 32-byte apply hash"))?
        .to_ascii_lowercase())
}

async fn wait_for_state<F>(rpc: &PeerRpcClient, key: &str, predicate: F) -> Result<Value>
where
    F: Fn(&Value) -> bool,
{
    let mut last = Value::Null;
    for _ in 0..120 {
        last = read_state_value(rpc, key).await?.unwrap_or(Value::Null);
        if predicate(&last) {
            return Ok(last);
        }
        sleep(Duration::from_millis(500)).await;
    }
    bail!("timed out waiting for {key}; last value: {last}");
}

async fn wait_for_confirmed_state<F>(rpc: &PeerRpcClient, key: &str, predicate: F) -> Result<Value>
where
    F: Fn(&Value) -> bool,
{
    let mut last = Value::Null;
    for _ in 0..120 {
        last = read_confirmed_state_value(rpc, key)
            .await?
            .unwrap_or(Value::Null);
        if predicate(&last) {
            return Ok(last);
        }
        sleep(Duration::from_millis(500)).await;
    }
    bail!("timed out waiting for confirmed {key}; last value: {last}");
}

async fn sc_bridge_transport_peer(bridge: &mut ScBridgeClient) -> Result<String> {
    let info = bridge
        .info()
        .await
        .context("reading SC-Bridge local peer info")?;
    let peer = info
        .pointer("/info/peerPubkey")
        .and_then(Value::as_str)
        .or_else(|| info.pointer("/info/peer_pubkey").and_then(Value::as_str))
        .or_else(|| info.pointer("/info/peer").and_then(Value::as_str))
        .or_else(|| info.get("peer").and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| is_hex_len(value, 64))
        .ok_or_else(|| anyhow!("SC-Bridge info did not expose a 32-byte peer public key"))?;
    Ok(peer.to_owned())
}

async fn emit_provider_heartbeats(ctx: HeartbeatContext<'_>) -> Result<Vec<Value>> {
    let sc_bridge_url = ctx.args.sc_bridge_url.clone().or_else(|| {
        ctx.config
            .as_ref()
            .and_then(|config| config.network.as_ref())
            .and_then(|network| network.sc_bridge_url.clone())
    });
    let sc_bridge_token = ctx.args.sc_bridge_token.clone().or_else(|| {
        ctx.config
            .as_ref()
            .and_then(|config| config.network.as_ref())
            .and_then(|network| network.sc_bridge_token.clone())
    });
    let (Some(url), Some(token)) = (sc_bridge_url, sc_bridge_token) else {
        provider_log(
            ctx.args,
            "SC-Bridge URL/token not configured; skipping live heartbeat send",
        );
        return Ok(Vec::new());
    };
    let mut bridge = ScBridgeClient::connect(ScBridgeConfig::new(url, token)?)
        .await
        .context("connecting to SC-Bridge for provider heartbeats")?;
    bridge
        .mute_sidechannel_events()
        .await
        .context("muting inbound sidechannels for the provider heartbeat sender")?;
    let transport_peer = sc_bridge_transport_peer(&mut bridge).await?;
    let mut sent = Vec::new();
    let count = u64::from(ctx.args.heartbeat_count.max(1));
    let protection = ProviderProtectionConfig::from_provider_args(ctx.args, ctx.selected)?;
    for seq in 0..count {
        sent.extend(
            send_provider_heartbeat_round(
                &mut bridge,
                ctx.keypair_path,
                ctx.password,
                &ctx.wallet.public_key,
                ctx.selected,
                ctx.rooms,
                ctx.attestation,
                ctx.attestation_head,
                ctx.identity_anchor,
                ctx.tpm_activation_hello,
                ctx.args.min_ask_au,
                protection.max_sessions,
                Some(transport_peer.as_str()),
                seq,
                seq == 0,
                ProviderLoadSnapshot::idle(protection.max_sessions),
            )
            .await?,
        );
    }
    Ok(sent)
}

async fn send_provider_heartbeat_round(
    bridge: &mut ScBridgeClient,
    keypair_path: &Path,
    password: &str,
    provider_pubkey: &str,
    selected: &ProviderCandidate,
    rooms: &[LedgerRoom],
    attestation: &Tier1AttestationReport,
    attestation_head: &str,
    identity_anchor: &str,
    tpm_activation_hello: Option<&mayhem_proto::TpmActivateCredentialHello>,
    min_ask_au: MoneyAu,
    max_sessions: u32,
    transport_peer: Option<&str>,
    seq: u64,
    join_rooms: bool,
    load: ProviderLoadSnapshot,
) -> Result<Vec<Value>> {
    let mut sent = Vec::new();
    let caps = provider_heartbeat_caps(selected);
    let (tok_s, tok_s_source) = provider_heartbeat_tok_s(&load, selected.verdict.est_tok_s);
    let mut modality_capacity = selected.modality_capacities.clone();
    for (modality, active_items) in &load.modality_active_items {
        let capacity = modality_capacity
            .get_mut(modality)
            .with_context(|| format!("heartbeat load references unknown modality {modality}"))?;
        ensure!(
            *active_items <= capacity.max_inflight_items,
            "heartbeat active {modality} items exceed configured in-flight limit"
        );
        capacity.active_items = *active_items;
    }
    for room in rooms {
        if join_rooms {
            bridge
                .join(&room.sidechannel)
                .await
                .with_context(|| format!("joining sidechannel {}", room.sidechannel))?;
        }
        let ts = unix_epoch_millis()?;
        let mut heartbeat = json!({
            "t": "hb",
            "v": HEARTBEAT_SCHEMA_VERSION,
            "contract_version": CONTRACT_VERSION,
            "provider": provider_pubkey,
            "enclave_id": selected.enclave.enclave_id,
            "model_id": selected.enclave.model_id,
            "room_id": room.room_id,
            "identity_anchor": identity_anchor,
            "accepting_new": load.accepting_new,
            "sat": if load.modality_at_capacity {
                1.0
            } else {
                provider_saturation(load.active_slots, max_sessions)
            },
            "slots": {
                "active": load.active_slots,
                "active_requests": load.active_requests,
                "max": max_sessions,
            },
            "q": {
                "free_slots": load.free_slots,
                "engine_backlog": load.engine_backlog,
                "est_wait_ms": load.est_wait_ms,
            },
            "perf": {
                "tok_s": tok_s,
                "tok_s_source": tok_s_source,
                "ttft_ms": load.ttft_ms,
            },
            "price_ver": selected
                .price
                .as_ref()
                .and_then(|price| price.current.as_ref())
                .map(|price| price.ver)
                .unwrap_or(0),
            "min_ask_au": money_au_json(min_ask_au),
            "caps": {
                "tools": caps.tools,
                "json": caps.json,
                "ctx": caps.ctx,
                "vision": caps.vision,
                "served_modalities": &selected.served_modalities,
                "served_specialities": &selected.served_specialities,
                "modality_capacity": &modality_capacity,
            },
            "att": {
                "epoch": attestation.report.boot_epoch,
                "head": attestation_head,
            },
            "ts": ts,
            "nonce": blake3::hash(format!("{}:{}:{}:{}", room.room_id, provider_pubkey, ts, seq).as_bytes()).to_hex().to_string(),
        });
        project_provider_heartbeat_attestation(&mut heartbeat, attestation, tpm_activation_hello)?;
        if let Some(transport_peer) = transport_peer {
            heartbeat["transport_peer"] = json!(transport_peer);
        }
        let signing_payload = String::from_utf8(heartbeat_signing_payload(&heartbeat)?)
            .context("heartbeat signing payload was not UTF-8")?;
        let sig = sign_message(keypair_path, password, &signing_payload).await?;
        heartbeat["sig"] = json!(sig);
        bridge
            .send(&room.sidechannel, &heartbeat)
            .await
            .with_context(|| format!("sending heartbeat to {}", room.sidechannel))?;
        sent.push(json!({
            "room_id": room.room_id,
            "sidechannel": room.sidechannel,
            "seq": seq,
            "min_ask_au": money_au_json(min_ask_au),
            "max_sessions": max_sessions,
            "transport_peer": transport_peer,
            "accepting_new": load.accepting_new,
            "identity_anchor": identity_anchor,
            "served_modalities": &selected.served_modalities,
            "served_specialities": &selected.served_specialities,
        }));
    }
    Ok(sent)
}

fn project_provider_heartbeat_attestation(
    heartbeat: &mut Value,
    attestation: &Tier1AttestationReport,
    tpm_activation_hello: Option<&mayhem_proto::TpmActivateCredentialHello>,
) -> Result<()> {
    if let Some(quote) = attestation.report.hw_quote.as_ref() {
        heartbeat["att"]["quote_kind"] = serde_json::to_value(&quote.kind)
            .context("serializing provider heartbeat quote kind")?;
        if let Some(platform) = provider_hardware_quote_platform(quote)? {
            heartbeat["att"]["declared_platform"] = json!(platform);
        }
    }
    if let Some(hello) = tpm_activation_hello {
        ensure!(
            attestation
                .report
                .hw_quote
                .as_ref()
                .is_some_and(|quote| quote.kind == HardwareQuoteKind::Tpm2QuoteEk),
            "TPM activation hello requires a TPM 2.0 hardware quote"
        );
        heartbeat["att"]["tpm_activation_hello"] =
            serde_json::to_value(hello).context("serializing TPM activation hello")?;
    }
    Ok(())
}

fn provider_hardware_quote_platform(quote: &HardwareQuote) -> Result<Option<&str>> {
    let platform = quote
        .metadata
        .get("platform_id")
        .or_else(|| quote.metadata.get("platform"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if let Some(platform) = platform {
        ensure!(
            platform.len() <= 128
                && platform.bytes().enumerate().all(|(index, byte)| {
                    byte.is_ascii_lowercase()
                        || byte.is_ascii_digit()
                        || (index > 0 && matches!(byte, b'.' | b'_' | b'-'))
                }),
            "hardware quote platform must be a safe lowercase identifier"
        );
    }
    Ok(platform)
}

fn provider_heartbeat_tok_s(
    load: &ProviderLoadSnapshot,
    cold_start_prior: Option<f64>,
) -> (Option<f64>, &'static str) {
    if let Some(measured) = load.measured_tok_s_milli {
        return (Some(measured as f64 / 1000.0), "measured");
    }
    (cold_start_prior, "hwprobe_cold_start_prior")
}

fn spawn_provider_session_heartbeat_task(
    ctx: ProviderSessionHeartbeatTask,
) -> tokio::task::JoinHandle<Result<()>> {
    tokio::spawn(run_provider_session_heartbeats(ctx))
}

fn provider_panic_message(panic: Box<dyn std::any::Any + Send>) -> String {
    if let Some(message) = panic.downcast_ref::<&str>() {
        return (*message).to_owned();
    }
    if let Some(message) = panic.downcast_ref::<String>() {
        return message.clone();
    }
    "non-string panic payload".to_owned()
}

fn contain_provider_request<T>(request: impl FnOnce() -> Result<T>) -> Result<T> {
    catch_unwind(AssertUnwindSafe(request)).unwrap_or_else(|panic| {
        Err(anyhow!(
            "provider engine panicked while serving this request: {}",
            provider_panic_message(panic)
        ))
    })
}

#[derive(Debug)]
struct ProviderSessionRequestError(String);

impl std::fmt::Display for ProviderSessionRequestError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(&self.0)
    }
}

impl std::error::Error for ProviderSessionRequestError {}

#[derive(Debug)]
struct ProviderSessionOutputError(String);

impl std::fmt::Display for ProviderSessionOutputError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(&self.0)
    }
}

impl std::error::Error for ProviderSessionOutputError {}

fn provider_session_request_error(message: impl Into<String>) -> anyhow::Error {
    anyhow::Error::new(ProviderSessionRequestError(message.into()))
}

fn provider_session_request_result<T>(result: Result<T>) -> Result<T> {
    result.map_err(|error| provider_session_request_error(format!("{error:#}")))
}

fn provider_session_output_error(message: impl Into<String>) -> anyhow::Error {
    anyhow::Error::new(ProviderSessionOutputError(message.into()))
}

fn provider_response_error_code(error: &anyhow::Error) -> &'static str {
    if error.chain().any(|cause| {
        cause.is::<ProviderSessionRequestError>()
            || cause.downcast_ref::<EngineError>().is_some_and(|error| {
                matches!(
                    error,
                    EngineError::InvalidRequest(_) | EngineError::PromptTooLong { .. }
                )
            })
    }) {
        "request_invalid"
    } else if error.chain().any(|cause| {
        cause.is::<ProviderSessionOutputError>()
            || cause
                .downcast_ref::<EngineError>()
                .is_some_and(|error| matches!(error, EngineError::InvalidOutput(_)))
    }) {
        "model_output_invalid"
    } else {
        "provider_response_failed"
    }
}

fn provider_response_error_message(error: &anyhow::Error) -> String {
    error
        .chain()
        .find_map(|cause| {
            cause
                .downcast_ref::<ProviderSessionRequestError>()
                .map(|error| error.0.clone())
                .or_else(|| {
                    cause
                        .downcast_ref::<ProviderSessionOutputError>()
                        .map(|error| error.0.clone())
                })
                .or_else(|| {
                    cause.downcast_ref::<EngineError>().and_then(|error| {
                        matches!(
                            error,
                            EngineError::InvalidRequest(_)
                                | EngineError::InvalidOutput(_)
                                | EngineError::PromptTooLong { .. }
                        )
                        .then(|| error.to_string())
                    })
                })
        })
        .unwrap_or_else(|| error.to_string())
}

async fn run_provider_session_heartbeats(ctx: ProviderSessionHeartbeatTask) -> Result<()> {
    let mut retry_delay = ctx.heartbeat_reconnect_initial;
    while !ctx.load.is_stopped() {
        match run_provider_session_heartbeat_connection(&ctx).await {
            Ok(()) => return Ok(()),
            Err(err) => {
                provider_session_debug(format!(
                    "live provider heartbeat bridge failed; reconnecting: {err:#}"
                ));
                if ctx.load.is_stopped() {
                    return Ok(());
                }
                sleep(retry_delay).await;
                retry_delay = (retry_delay * 2).min(ctx.heartbeat_reconnect_max);
            }
        }
    }
    Ok(())
}

async fn run_provider_session_heartbeat_connection(
    ctx: &ProviderSessionHeartbeatTask,
) -> Result<()> {
    let mut bridge = timeout(
        ctx.bridge_operation_timeout,
        ScBridgeClient::connect(ScBridgeConfig::new(
            &ctx.sc_bridge_url,
            ctx.sc_bridge_token.clone(),
        )?),
    )
    .await
    .context("timed out connecting to SC-Bridge for live provider session heartbeats")??;
    timeout(
        ctx.bridge_operation_timeout,
        bridge.mute_sidechannel_events(),
    )
    .await
    .context("timed out muting inbound sidechannels for the live provider heartbeat sender")??;
    let transport_peer = timeout(
        ctx.bridge_operation_timeout,
        sc_bridge_transport_peer(&mut bridge),
    )
    .await
    .context("timed out reading the live provider transport peer")??;
    let mut seq = 0_u64;
    let mut join_rooms = true;
    let mut heartbeat_cache_updated_at = None::<Instant>;
    let mut load_changes = ctx.load.subscribe_changes();
    while !ctx.load.is_stopped() {
        load_changes.borrow_and_update();
        let round_started = Instant::now();
        let sent = timeout(
            ctx.bridge_operation_timeout,
            send_provider_heartbeat_round(
                &mut bridge,
                &ctx.keypair_path,
                &ctx.password,
                &ctx.provider_pubkey,
                &ctx.selected,
                &ctx.rooms,
                &ctx.attestation,
                &ctx.attestation_head,
                &ctx.identity_anchor,
                ctx.tpm_activation_hello.as_ref(),
                ctx.min_ask_au,
                ctx.max_sessions,
                Some(transport_peer.as_str()),
                seq,
                join_rooms,
                ctx.load.snapshot(ctx.max_sessions),
            ),
        )
        .await
        .with_context(|| format!("timed out sending live provider heartbeat seq {seq}"))??;
        let refresh_cache = heartbeat_cache_updated_at
            .map(|updated_at| updated_at.elapsed() >= ctx.heartbeat_ttl / 2)
            .unwrap_or(true);
        if refresh_cache {
            if let Err(err) = write_provider_heartbeat_cache(
                &ctx.home,
                &ctx.provider_pubkey,
                &ctx.selected.enclave.enclave_id,
                &sent,
            ) {
                provider_session_debug(format!(
                    "refreshing provider heartbeat health cache failed: {err:#}"
                ));
            } else {
                heartbeat_cache_updated_at = Some(Instant::now());
            }
        }
        join_rooms = false;
        seq = seq.saturating_add(1);
        // Back-pressure sentinel: heartbeats must never fall behind silently
        // again (stale beats at the gateway drop the provider from routing).
        // A late round skips its sleep instead of stacking further delay, and
        // the lag is reported even without session debug enabled.
        let round_elapsed = round_started.elapsed();
        match ctx.heartbeat_interval.checked_sub(round_elapsed) {
            Some(remaining) => {
                tokio::select! {
                    _ = sleep(remaining) => {}
                    changed = load_changes.changed() => {
                        if changed.is_err() {
                            bail!("provider heartbeat load-change channel closed");
                        }
                    }
                }
            }
            None => eprintln!(
                "warning: provider heartbeat pipeline is behind: seq {} took {}ms against a {}ms interval; sending the next beat immediately",
                seq.saturating_sub(1),
                round_elapsed.as_millis(),
                ctx.heartbeat_interval.as_millis()
            ),
        }
    }
    Ok(())
}

fn provider_saturation(active_slots: u64, max_sessions: u32) -> f64 {
    if max_sessions == 0 {
        return 0.0;
    }
    (active_slots as f64 / f64::from(max_sessions)).min(1.0)
}

fn provider_heartbeat_caps(selected: &ProviderCandidate) -> ModelCaps {
    let mut caps = gateway_caps_from_contract(&selected.enclave.caps);
    caps.ctx = u32::try_from(selected.served_ctx).unwrap_or(u32::MAX);
    if !backend_supports_tool_calls(&selected.enclave.backend) {
        caps.tools = false;
    }
    if !selected
        .served_modalities
        .iter()
        .any(|modality| modality == "image")
    {
        caps.vision = false;
    }
    caps
}

async fn serve_provider_sessions(
    ctx: ProviderSessionContext<'_>,
    runtime: ProviderSessionRuntime<'_>,
    mut responder: Box<dyn ProviderSessionResponder>,
) -> Result<()> {
    let terms = provider_session_terms(&ctx)?;
    let configured_protection =
        ProviderProtectionConfig::from_provider_args(ctx.args, ctx.selected)?;
    let protection_config =
        configured_protection.limit_to_execution_capacity(responder.concurrent_session_capacity());
    let (sc_bridge_url, sc_bridge_token) = resolve_cli_sc_bridge(
        ctx.args.home.as_ref(),
        ctx.args.sc_bridge_url.as_deref(),
        ctx.args.sc_bridge_token.as_deref(),
    )?;
    let admin_transport_peer = provider_admin_transport_peer(runtime.rpc).await?;
    let bridge_operation_timeout = Duration::from_millis(configured_positive_millis(
        None,
        "MAYHEM_PROVIDER_SC_BRIDGE_OPERATION_TIMEOUT_MS",
        DEFAULT_PROVIDER_SC_BRIDGE_OPERATION_TIMEOUT_MILLIS,
        "provider SC-Bridge operation timeout",
    )?);
    let bridge_liveness_interval = Duration::from_millis(configured_positive_millis(
        None,
        "MAYHEM_PROVIDER_SC_BRIDGE_LIVENESS_INTERVAL_MS",
        DEFAULT_PROVIDER_SC_BRIDGE_LIVENESS_INTERVAL_MILLIS,
        "provider SC-Bridge liveness interval",
    )?);
    let provider_heartbeat_interval = Duration::from_millis(configured_positive_millis(
        None,
        "MAYHEM_PROVIDER_HEARTBEAT_INTERVAL_MS",
        DEFAULT_PROVIDER_HEARTBEAT_INTERVAL_MILLIS,
        "provider heartbeat interval",
    )?);
    let provider_heartbeat_reconnect_initial = Duration::from_millis(configured_positive_millis(
        None,
        "MAYHEM_PROVIDER_HEARTBEAT_RECONNECT_INITIAL_MS",
        DEFAULT_PROVIDER_HEARTBEAT_RECONNECT_INITIAL_MILLIS,
        "provider heartbeat initial reconnect delay",
    )?);
    let provider_heartbeat_reconnect_max = Duration::from_millis(configured_positive_millis(
        None,
        "MAYHEM_PROVIDER_HEARTBEAT_RECONNECT_MAX_MS",
        DEFAULT_PROVIDER_HEARTBEAT_RECONNECT_MAX_MILLIS,
        "provider heartbeat maximum reconnect delay",
    )?);
    ensure!(
        provider_heartbeat_reconnect_initial <= provider_heartbeat_reconnect_max,
        "provider heartbeat initial reconnect delay must not exceed its maximum reconnect delay"
    );
    let provider_heartbeat_ttl = Duration::from_millis(configured_positive_millis(
        None,
        "MAYHEM_PROVIDER_HEARTBEAT_TTL_MS",
        DEFAULT_PROVIDER_HEARTBEAT_TTL_MILLIS,
        "provider heartbeat TTL",
    )?);
    let component_poll_interval =
        provider_heartbeat_reconnect_initial.min(bridge_liveness_interval);
    let request_stall_timeout = provider_session_request_timeout()?;
    let admission_timeout = provider_session_admission_timeout()?;
    let session_bridge_operation_deadline = provider_session_bridge_operation_deadline()?;
    let (max_request_bytes, max_payload_chunks) = provider_session_request_limits(&terms)?;
    let mut bridge = reconnect_provider_session_bridge(
        &sc_bridge_url,
        &sc_bridge_token,
        &admin_transport_peer,
        None,
        provider_heartbeat_reconnect_initial,
        provider_heartbeat_reconnect_max,
        session_bridge_operation_deadline,
    )
    .await?;

    provider_log(
        ctx.args,
            &format!(
            "Provider session server listening on {} for enclave {} across {} canonical room(s) with {} at startup price v{} {} ctx_bracket {} table v{} min_ask ${} max_sessions {}{}",
            sc_bridge_url,
            terms.enclave_id,
            ctx.rooms.len(),
            responder.mode(),
            terms.price_ver,
            format_rate_map(&terms.rate_map),
            terms.ctx_bracket.as_deref().unwrap_or("base"),
            terms.ctx_bracket_table_ver.unwrap_or(0),
            au_to_usd_amount(terms.min_ask_au),
            protection_config.max_sessions,
            if protection_config.max_sessions < configured_protection.max_sessions {
                format!(
                    " (configured {}, limited by responder execution capacity)",
                    configured_protection.max_sessions
                )
            } else {
                String::new()
            }
        ),
    );

    let heartbeat_enabled = !ctx.args.no_heartbeat && !ctx.rooms.is_empty();
    let heartbeat_load = ProviderHeartbeatLoad::new(&ctx.selected.modality_capacities);
    let runtime_floor_monitor = ProviderRuntimeFloorMonitor::new(ctx.args, ctx.home, ctx.selected)?;
    let engine_watchdog_restart_after_millis = configured_nonnegative_millis(
        "MAYHEM_PROVIDER_ENGINE_WATCHDOG_RESTART_AFTER_MS",
        DEFAULT_PROVIDER_ENGINE_WATCHDOG_RESTART_AFTER_MILLIS,
    )?;
    let engine_watchdog_restart_cooldown = Duration::from_millis(configured_positive_millis(
        None,
        "MAYHEM_PROVIDER_ENGINE_WATCHDOG_RESTART_COOLDOWN_MS",
        DEFAULT_PROVIDER_ENGINE_WATCHDOG_RESTART_COOLDOWN_MILLIS,
        "provider engine watchdog restart cooldown",
    )?);
    let mut engine_watchdog = ProviderEngineWatchdog::new(
        ctx.selected,
        (engine_watchdog_restart_after_millis > 0)
            .then(|| Duration::from_millis(engine_watchdog_restart_after_millis)),
        engine_watchdog_restart_cooldown,
    );
    let heartbeat_task_config = heartbeat_enabled.then(|| ProviderSessionHeartbeatTask {
        home: ctx.home.to_path_buf(),
        sc_bridge_url: sc_bridge_url.clone(),
        sc_bridge_token: sc_bridge_token.clone(),
        keypair_path: ctx.keypair_path.to_path_buf(),
        password: ctx.password.to_owned(),
        provider_pubkey: ctx.wallet.public_key.clone(),
        selected: ctx.selected.clone(),
        rooms: ctx.rooms.to_vec(),
        attestation: ctx.attestation.clone(),
        attestation_head: ctx.attestation_head.to_owned(),
        identity_anchor: ctx.identity_anchor.to_owned(),
        tpm_activation_hello: ctx.tpm_activation_hello.cloned(),
        min_ask_au: ctx.args.min_ask_au,
        max_sessions: protection_config.max_sessions,
        load: heartbeat_load.clone(),
        bridge_operation_timeout,
        heartbeat_interval: provider_heartbeat_interval,
        heartbeat_reconnect_initial: provider_heartbeat_reconnect_initial,
        heartbeat_reconnect_max: provider_heartbeat_reconnect_max,
        heartbeat_ttl: provider_heartbeat_ttl,
    });
    let mut heartbeat_task = heartbeat_task_config
        .clone()
        .map(spawn_provider_session_heartbeat_task);
    let mut heartbeat_restart_at = None::<Instant>;
    let deadline = (ctx.args.serve_sessions_seconds > 0)
        .then(|| Instant::now() + Duration::from_secs(ctx.args.serve_sessions_seconds));
    let mut sessions = HashMap::new();
    let mut rejected_sessions = HashMap::new();
    let mut pending_requests = HashMap::new();
    let mut pending_payloads = HashMap::new();
    let mut protection = ProviderProtectionState::new(protection_config);
    let mut tpm_activation_limiter = ProviderTpmActivationLimiter::from_environment()?;
    let mut draining = false;
    let mut local_drain_request = None::<ProviderDrainRequest>;
    let mut runtime_floor_reject: Option<ProviderRuntimeFloorRejection> = None;
    let mut engine_watchdog_reject: Option<ProviderRuntimeFloorRejection> = None;
    let mut engine_recovery = ProviderEngineRecovery::new(
        provider_heartbeat_reconnect_initial,
        provider_heartbeat_reconnect_max,
    );
    let drain_paths = provider_drain_flag_paths(
        ctx.home,
        &ctx.wallet.public_key,
        &ctx.selected.enclave.enclave_id,
    );
    let serve_result: Result<()> = async {
        loop {
            if heartbeat_task
                .as_ref()
                .is_some_and(tokio::task::JoinHandle::is_finished)
            {
                if let Some(finished) = heartbeat_task.take() {
                    match finished.await {
                        Ok(Ok(())) => provider_session_debug(
                            "live provider heartbeat component stopped unexpectedly; scheduling restart",
                        ),
                        Ok(Err(err)) => provider_session_debug(format!(
                            "live provider heartbeat component failed; scheduling restart: {err:#}"
                        )),
                        Err(err) => provider_session_debug(format!(
                            "live provider heartbeat component panicked; scheduling restart: {err}"
                        )),
                    }
                    heartbeat_restart_at =
                        Some(Instant::now() + provider_heartbeat_reconnect_initial);
                }
            }
            if heartbeat_task.is_none()
                && heartbeat_restart_at.is_some_and(|restart_at| Instant::now() >= restart_at)
            {
                if let Some(config) = heartbeat_task_config.clone() {
                    provider_session_debug("restarting live provider heartbeat component");
                    heartbeat_task = Some(spawn_provider_session_heartbeat_task(config));
                    heartbeat_restart_at = None;
                }
            }
            if !engine_recovery.pending() && !responder.component_healthy() {
                heartbeat_load.set_accepting_new(false);
                engine_recovery.mark_failed(
                    "provider engine child exited while idle; no user session caused the failure",
                );
            }
            if engine_recovery.retry_due(Instant::now()) {
                heartbeat_load.set_accepting_new(false);
                let reason = engine_recovery
                    .reason()
                    .unwrap_or("engine component failure")
                    .to_owned();
                provider_session_debug(format!(
                    "reloading provider engine after contained component failure: {reason}"
                ));
                match reload_provider_session_responder(
                    &mut responder,
                    reason.clone(),
                    || {
                        provider_session_responder_with_modality_health(&ctx)
                            .map(|(responder, _)| responder)
                    },
                ) {
                    Ok(()) => {
                        engine_recovery.mark_recovered();
                        engine_watchdog.reset_after_restart();
                        engine_watchdog_reject = None;
                        provider_log(
                            ctx.args,
                            "Provider engine reloaded after a contained component failure; heartbeats and session admission will resume.",
                        );
                    }
                    Err(err) => {
                        let failure = format!(
                            "provider engine reload failed after {reason}: {err:#}"
                        );
                        provider_session_debug(&failure);
                        engine_recovery.mark_reload_failed(failure, Instant::now());
                    }
                }
            }
            expire_provider_pending_sessions(
                &mut bridge,
                &mut sessions,
                &mut pending_requests,
                &mut pending_payloads,
                &heartbeat_load,
            )
            .await;
            let next_runtime_floor_reject = if draining {
                None
            } else {
                runtime_floor_monitor.check()
            };
            if next_runtime_floor_reject != runtime_floor_reject {
                match &next_runtime_floor_reject {
                    Some(reject) => provider_session_debug(format!(
                        "runtime floor active; refusing new sessions with {}: {}",
                        reject.code, reject.reason
                    )),
                    None if runtime_floor_reject.is_some() => provider_session_debug(
                        "runtime floor cleared; accepting new sessions again",
                    ),
                    None => {}
                }
                runtime_floor_reject = next_runtime_floor_reject;
            }
            let watchdog_action = if draining || engine_recovery.pending() {
                ProviderEngineWatchdogAction::Healthy
            } else {
                let rss =
                    provider_engine_rss_observation(responder.as_ref(), engine_watchdog.limit_bytes);
                engine_watchdog.check(
                    runtime_floor_monitor.memory_check(),
                    rss,
                    sessions.len(),
                    Instant::now(),
                )
            };
            match watchdog_action {
                ProviderEngineWatchdogAction::Healthy => {
                    if !engine_recovery.pending() && engine_watchdog_reject.take().is_some() {
                        provider_session_debug(
                            "engine watchdog pressure cleared; accepting new sessions again when other floors allow",
                        );
                    }
                }
                ProviderEngineWatchdogAction::RefuseNew(reject) => {
                    if engine_watchdog_reject.as_ref() != Some(&reject) {
                        provider_session_debug(format!(
                            "engine watchdog active; refusing new sessions with {}: {}",
                            reject.code, reject.reason
                        ));
                    }
                    engine_watchdog_reject = Some(reject);
                }
                ProviderEngineWatchdogAction::RestartNow(reject) => {
                    provider_session_debug(format!(
                        "engine watchdog restarting session engine after sustained pressure: {}",
                        reject.reason
                    ));
                    heartbeat_load.set_accepting_new(false);
                    let restart_reason = reject.reason.clone();
                    engine_watchdog_reject = Some(reject);
                    match reload_provider_session_responder(
                        &mut responder,
                        restart_reason,
                        || {
                            provider_session_responder_with_modality_health(&ctx)
                                .map(|(responder, _)| responder)
                        },
                    ) {
                        Ok(()) => {
                            engine_watchdog.reset_after_restart();
                            engine_watchdog_reject = None;
                            provider_log(
                                ctx.args,
                                "Provider engine watchdog reloaded the local engine after sustained memory pressure.",
                            );
                        }
                        Err(err) => {
                            let failure = format!(
                                "engine watchdog reload failed; continuing to refuse new sessions: {err:#}"
                            );
                            provider_session_debug(&failure);
                            engine_recovery.mark_reload_failed(failure, Instant::now());
                        }
                    }
                }
            }
            if !draining {
                heartbeat_load.set_accepting_new(
                    runtime_floor_reject.is_none()
                        && engine_watchdog_reject.is_none()
                        && !engine_recovery.pending(),
                );
            }
            if !draining {
                match provider_drain_request(&drain_paths) {
                    Ok(Some(request)) => {
                        provider_session_debug(format!(
                            "local drain flag {} observed; refusing new sessions",
                            request.path.display()
                        ));
                        heartbeat_load.set_accepting_new(false);
                        draining = true;
                        local_drain_request = Some(request);
                        if sessions.is_empty() {
                            break;
                        }
                    }
                    Ok(None) => {}
                    Err(err) => provider_session_debug(format!(
                        "reading local drain flag failed: {err:#}"
                    )),
                }
            }
            if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
                if !draining {
                    provider_session_debug(
                        "serve window elapsed; entering graceful drain and refusing new sessions",
                    );
                    heartbeat_load.set_accepting_new(false);
                    draining = true;
                }
                if sessions.is_empty() {
                    break;
                }
            }
            let wait = deadline
                .map(|deadline| deadline.saturating_duration_since(Instant::now()))
                .filter(|remaining| !remaining.is_zero())
                .map(|remaining| remaining.min(component_poll_interval))
                .unwrap_or(component_poll_interval);
            let wait = if draining {
                component_poll_interval
            } else {
                wait
            };
            if wait.is_zero() {
                continue;
            }
            match bridge.next_session_event(wait).await {
                Ok(event) => {
                    if event.get("type").and_then(Value::as_str) == Some("session_closed") {
                        let session_id = event
                            .get("session_id")
                            .and_then(Value::as_str)
                            .unwrap_or("");
                        let reason = event
                            .get("reason")
                            .and_then(Value::as_str)
                            .unwrap_or("transport closed");
                        if discard_pre_request_provider_session_on_close(
                            &mut sessions,
                            &mut pending_requests,
                            &mut pending_payloads,
                            &heartbeat_load,
                            &event,
                        ) {
                            provider_session_debug(format!(
                                "direct transport closed before s.req for session {session_id}; released admission slot: {reason}"
                            ));
                        } else {
                            provider_session_debug(format!(
                                "direct transport closed for session {session_id}; preserving admission state for an identical s.open replay: {reason}"
                            ));
                        }
                        continue;
                    }
                    let frame_type = event
                        .get("frame")
                        .and_then(|frame| frame.get("t"))
                        .and_then(Value::as_str)
                        .unwrap_or("frame");
                    provider_session_debug(format!(
                        "received session event {} type {frame_type}",
                        event
                            .get("session_id")
                            .and_then(Value::as_str)
                            .unwrap_or("")
                    ));
                    let event_session_id = event
                        .get("session_id")
                        .and_then(Value::as_str)
                        .or_else(|| {
                            event
                                .get("frame")
                                .and_then(|frame| frame.get("session_id"))
                                .and_then(Value::as_str)
                        })
                        .unwrap_or("")
                        .to_owned();
                    let event_remote = event
                        .get("remote")
                        .and_then(Value::as_str)
                        .unwrap_or("")
                        .to_owned();
                    let session_reject = runtime_floor_reject
                        .clone()
                        .or_else(|| engine_watchdog_reject.clone())
                        .or_else(|| engine_recovery.rejection());
                    let event_belongs_to_process = provider_session_event_belongs_to_process(
                        &event,
                        &sessions,
                        &terms,
                    );
                    if let Err(err) = handle_provider_session_frame(
                        &mut bridge,
                        &mut sessions,
                        &mut rejected_sessions,
                        &mut pending_requests,
                        &mut pending_payloads,
                        &heartbeat_load,
                        &mut protection,
                        &mut tpm_activation_limiter,
                        &terms,
                        &runtime,
                        &sc_bridge_url,
                        &sc_bridge_token,
                        session_bridge_operation_deadline,
                        admission_timeout,
                        responder.as_mut(),
                        &mut engine_recovery,
                        session_reject,
                        request_stall_timeout,
                        max_request_bytes,
                        max_payload_chunks,
                        event,
                    )
                    .await
                    {
                        provider_session_debug(format!(
                            "session {event_session_id} failed without stopping provider serving: {err:#}"
                        ));
                        let owns_session = sessions
                            .get(&event_session_id)
                            .is_some_and(|active| active.remote == event_remote);
                        if event_belongs_to_process
                            && is_hex_len(&event_remote, 64)
                            && is_hex_len(&event_session_id, 64)
                        {
                            let _ = bridge
                                .session_close(&event_remote, &event_session_id)
                                .await;
                        }
                        if owns_session {
                            discard_provider_session_state(
                                &mut sessions,
                                &mut pending_requests,
                                &mut pending_payloads,
                                &event_session_id,
                            );
                        }
                        heartbeat_load.set_active_sessions(sessions.len());
                    }
                }
                Err(BridgeError::Timeout) => {
                    expire_provider_pending_sessions(
                        &mut bridge,
                        &mut sessions,
                        &mut pending_requests,
                        &mut pending_payloads,
                        &heartbeat_load,
                    )
                    .await;
                    if draining && sessions.is_empty() {
                        break;
                    }
                }
                Err(BridgeError::Closed) | Err(BridgeError::WebSocket(_)) => {
                    let dropped = clear_provider_sessions_after_bridge_drop(
                        &mut sessions,
                        &mut pending_requests,
                        &mut pending_payloads,
                        &heartbeat_load,
                    );
                    provider_session_debug(format!(
                        "SC-Bridge closed provider session stream; dropped {dropped} active session(s), reconnecting"
                    ));
                    bridge =
                        reconnect_provider_session_bridge(
                            &sc_bridge_url,
                            &sc_bridge_token,
                            &admin_transport_peer,
                            deadline,
                            provider_heartbeat_reconnect_initial,
                            provider_heartbeat_reconnect_max,
                            session_bridge_operation_deadline,
                        )
                        .await?;
                }
                Err(err) => {
                    let dropped = clear_provider_sessions_after_bridge_drop(
                        &mut sessions,
                        &mut pending_requests,
                        &mut pending_payloads,
                        &heartbeat_load,
                    );
                    provider_session_debug(format!(
                        "SC-Bridge provider session reader failed ({err}); dropped {dropped} active session(s), reconnecting without stopping the provider"
                    ));
                    bridge = reconnect_provider_session_bridge(
                        &sc_bridge_url,
                        &sc_bridge_token,
                        &admin_transport_peer,
                        deadline,
                        provider_heartbeat_reconnect_initial,
                        provider_heartbeat_reconnect_max,
                        session_bridge_operation_deadline,
                    )
                    .await?;
                }
            }
        }
        Ok(())
    }
    .await;
    heartbeat_load.stop();
    if let Some(task) = heartbeat_task {
        match tokio::time::timeout(Duration::from_secs(5), task).await {
            Ok(Ok(Ok(()))) => {}
            Ok(Ok(Err(err))) => {
                provider_session_debug(format!("live provider heartbeat task failed: {err:#}"));
            }
            Ok(Err(err)) => {
                provider_session_debug(format!("live provider heartbeat task join failed: {err}"));
            }
            Err(_) => {
                provider_session_debug("live provider heartbeat task did not stop before timeout");
            }
        }
    }
    if serve_result.is_ok() {
        if let Some(request) = local_drain_request.as_ref() {
            complete_provider_drain_request(
                ctx.home,
                &ctx.wallet.public_key,
                &ctx.selected.enclave.enclave_id,
                request,
            )?;
        }
    }
    serve_result
}

async fn connect_provider_session_bridge(
    sc_bridge_url: &str,
    sc_bridge_token: &str,
    admin_transport_peer: &str,
    operation_deadline: Option<Duration>,
) -> Result<ScBridgeClient> {
    provider_session_debug(format!("connecting to SC-Bridge {sc_bridge_url}"));
    let mut bridge = ScBridgeClient::connect(
        ScBridgeConfig::new(sc_bridge_url, sc_bridge_token.to_owned())?
            .with_operation_deadline(operation_deadline),
    )
    .await
    .context("connecting to SC-Bridge for provider session serving")?;
    provider_session_debug("subscribing to all direct session frames");
    let subscription = bridge
        .session_subscribe_all()
        .await
        .context("subscribing to all direct session frames")?;
    if !subscription
        .get("all_sessions")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        bail!("SC-Bridge does not support all-session subscription; update the local Intercom app");
    }
    provider_session_debug(format!(
        "pinning outbound direct connection to admin transport peer {admin_transport_peer}"
    ));
    bridge
        .peer_connect(
            admin_transport_peer,
            Duration::from_millis(DEFAULT_OPEN_TIMEOUT_MILLIS),
        )
        .await
        .context("pinning the provider's outbound direct connection to the canonical admin")?;
    provider_session_debug("session frame subscription ready");
    Ok(bridge)
}

async fn reconnect_provider_session_bridge(
    sc_bridge_url: &str,
    sc_bridge_token: &str,
    admin_transport_peer: &str,
    deadline: Option<Instant>,
    initial_delay: Duration,
    max_delay: Duration,
    operation_deadline: Option<Duration>,
) -> Result<ScBridgeClient> {
    let mut delay = initial_delay;
    loop {
        if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
            bail!("provider session serving deadline reached while reconnecting to SC-Bridge");
        }
        match connect_provider_session_bridge(
            sc_bridge_url,
            sc_bridge_token,
            admin_transport_peer,
            operation_deadline,
        )
        .await
        {
            Ok(bridge) => return Ok(bridge),
            Err(err) => {
                provider_session_debug(format!(
                    "provider session bridge reconnect failed: {err:#}"
                ));
                let sleep = deadline
                    .map(|deadline| {
                        deadline
                            .saturating_duration_since(Instant::now())
                            .min(delay)
                    })
                    .unwrap_or(delay);
                if !sleep.is_zero() {
                    tokio::time::sleep(sleep).await;
                }
                delay = (delay * 2).min(max_delay);
            }
        }
    }
}

struct ProviderSessionLivenessMonitor {
    cancellation: CancellationToken,
    stop: Option<tokio::sync::oneshot::Sender<()>>,
    task: tokio::task::JoinHandle<Result<()>>,
}

impl ProviderSessionLivenessMonitor {
    async fn start(
        sc_bridge_url: &str,
        sc_bridge_token: &str,
        session_id: &str,
        remote: &str,
        operation_deadline: Option<Duration>,
    ) -> Result<Self> {
        let mut bridge = ScBridgeClient::connect(
            ScBridgeConfig::new(sc_bridge_url, sc_bridge_token.to_owned())?
                .with_operation_deadline(operation_deadline),
        )
        .await
        .context("connecting the provider session liveness monitor to SC-Bridge")?;
        let subscription = bridge
            .session_subscribe([session_id])
            .await
            .context("subscribing the provider session liveness monitor")?;
        ensure!(
            subscription
                .get("session_ids")
                .and_then(Value::as_array)
                .is_some_and(|ids| ids.iter().any(|id| id.as_str() == Some(session_id))),
            "SC-Bridge did not confirm the provider session liveness subscription"
        );

        let cancellation = CancellationToken::new();
        let task_cancellation = cancellation.clone();
        let session_id = session_id.to_owned();
        let remote = remote.to_owned();
        let (stop, mut stopped) = tokio::sync::oneshot::channel();
        let task = tokio::spawn(async move {
            loop {
                tokio::select! {
                    _ = &mut stopped => return Ok(()),
                    event = bridge.next_session_event_for(&session_id, None) => {
                        let event = match event {
                            Ok(event) => event,
                            Err(error) => {
                                task_cancellation.cancel();
                                return Err(anyhow!(error))
                                    .context("provider session liveness stream stopped");
                            }
                        };
                        if event.get("remote").and_then(Value::as_str) != Some(remote.as_str()) {
                            continue;
                        }
                        let transport_closed = event.get("type").and_then(Value::as_str)
                            == Some("session_closed");
                        let peer_closed = event
                            .get("frame")
                            .and_then(|frame| frame.get("t"))
                            .and_then(Value::as_str)
                            == Some("s.close");
                        if transport_closed || peer_closed {
                            task_cancellation.cancel();
                            return Ok(());
                        }
                    }
                }
            }
        });
        Ok(Self {
            cancellation,
            stop: Some(stop),
            task,
        })
    }

    fn cancellation(&self) -> CancellationToken {
        self.cancellation.clone()
    }

    async fn stop(mut self) -> Result<()> {
        if let Some(stop) = self.stop.take() {
            let _ = stop.send(());
        }
        self.task
            .await
            .context("provider session liveness monitor task panicked")?
    }
}

async fn provider_admin_transport_peer(rpc: &PeerRpcClient) -> Result<String> {
    let admin = read_state_value(rpc, "admin")
        .await?
        .and_then(|value| value.as_str().map(str::trim).map(str::to_owned))
        .filter(|value| is_hex_len(value, 64))
        .context("contract state admin is missing or is not a 32-byte peer public key")?;
    Ok(admin)
}

fn clear_provider_sessions_after_bridge_drop(
    sessions: &mut HashMap<String, ActiveProviderSession>,
    pending_requests: &mut HashMap<String, Instant>,
    pending_payloads: &mut HashMap<String, PendingProviderPayload>,
    heartbeat_load: &ProviderHeartbeatLoad,
) -> usize {
    let dropped = sessions.len();
    sessions.clear();
    pending_requests.clear();
    pending_payloads.clear();
    heartbeat_load.set_active_sessions(0);
    dropped
}

fn discard_provider_session_state(
    sessions: &mut HashMap<String, ActiveProviderSession>,
    pending_requests: &mut HashMap<String, Instant>,
    pending_payloads: &mut HashMap<String, PendingProviderPayload>,
    session_id: &str,
) {
    sessions.remove(session_id);
    pending_requests.remove(session_id);
    remove_provider_session_pending_payloads(pending_payloads, session_id);
}

fn discard_pre_request_provider_session_on_close(
    sessions: &mut HashMap<String, ActiveProviderSession>,
    pending_requests: &mut HashMap<String, Instant>,
    pending_payloads: &mut HashMap<String, PendingProviderPayload>,
    heartbeat_load: &ProviderHeartbeatLoad,
    event: &Value,
) -> bool {
    let Some(session_id) = event.get("session_id").and_then(Value::as_str) else {
        return false;
    };
    let Some(remote) = event.get("remote").and_then(Value::as_str) else {
        return false;
    };
    let Some(active) = sessions.get(session_id) else {
        return false;
    };
    if active.remote != remote || !pending_requests.contains_key(session_id) {
        return false;
    }
    discard_provider_session_state(sessions, pending_requests, pending_payloads, session_id);
    heartbeat_load.set_active_sessions(sessions.len());
    true
}

async fn expire_provider_pending_sessions(
    bridge: &mut ScBridgeClient,
    sessions: &mut HashMap<String, ActiveProviderSession>,
    pending_requests: &mut HashMap<String, Instant>,
    pending_payloads: &mut HashMap<String, PendingProviderPayload>,
    heartbeat_load: &ProviderHeartbeatLoad,
) {
    let expired = provider_session_expired_pending_ids(pending_requests, Instant::now());
    if expired.is_empty() {
        return;
    }
    for session_id in expired {
        pending_requests.remove(&session_id);
        remove_provider_session_pending_payloads(pending_payloads, &session_id);
        let Some(active) = sessions.remove(&session_id) else {
            continue;
        };
        provider_session_debug(format!(
            "closing stale accepted session {} after no s.req arrived before request timeout",
            active.session_id
        ));
        if let Err(err) = send_provider_session_close(
            bridge,
            &active.remote,
            &active.session_id,
            "err:request_timeout",
        )
        .await
        {
            provider_session_debug(format!(
                "sending request-timeout close failed for session {}: {err:#}",
                active.session_id
            ));
        }
    }
    heartbeat_load.set_active_sessions(sessions.len());
}

fn provider_session_expired_pending_ids(
    pending_requests: &HashMap<String, Instant>,
    now: Instant,
) -> Vec<String> {
    let mut expired = pending_requests
        .iter()
        .filter_map(|(session_id, deadline)| (*deadline <= now).then(|| session_id.clone()))
        .collect::<Vec<_>>();
    expired.sort();
    expired
}

fn provider_session_payload_key(session_id: &str, request_id: &str, payload_id: &str) -> String {
    format!("{session_id}:{request_id}:{payload_id}")
}

fn provider_session_request_id(frame: &Value) -> String {
    frame
        .get("rid")
        .and_then(Value::as_str)
        .filter(|rid| !rid.is_empty())
        .unwrap_or("missing-rid")
        .to_owned()
}

fn remove_provider_session_pending_payloads(
    pending_payloads: &mut HashMap<String, PendingProviderPayload>,
    session_id: &str,
) {
    let prefix = format!("{session_id}:");
    pending_payloads.retain(|key, _| !key.starts_with(&prefix));
}

fn provider_session_collect_request_chunk(
    pending_payloads: &mut HashMap<String, PendingProviderPayload>,
    session_id: &str,
    frame: &Value,
    max_request_bytes: usize,
    max_payload_chunks: usize,
) -> Result<()> {
    let upload_timeout = provider_session_request_upload_timeout(max_request_bytes)?;
    let request_id = provider_session_request_id(frame);
    ensure!(request_id.len() <= 128, "s.req_chunk rid exceeds 128 bytes");
    let payload_id = frame
        .get("payload_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .context("s.req_chunk missing payload_id")?;
    ensure!(
        is_hex_len(payload_id, 64),
        "s.req_chunk payload_id must be a 32-byte hex digest"
    );
    let chunk: PayloadChunk = serde_json::from_value(
        frame
            .get("chunk")
            .cloned()
            .context("s.req_chunk missing chunk")?,
    )
    .context("decoding s.req_chunk chunk")?;
    let key = provider_session_payload_key(session_id, &request_id, payload_id);
    let prefix = format!("{session_id}:");
    ensure!(
        pending_payloads.contains_key(&key)
            || !pending_payloads
                .keys()
                .any(|existing| existing.starts_with(&prefix)),
        "session already has a different pending request payload"
    );
    let pending = pending_payloads
        .entry(key)
        .or_insert_with(|| PendingProviderPayload {
            request_id: request_id.clone(),
            payload_id: payload_id.to_owned(),
            collector: PayloadChunkCollector::new(max_request_bytes, max_payload_chunks),
            started_at: Instant::now(),
        });
    ensure!(
        pending.request_id == request_id,
        "request payload changed rid"
    );
    ensure!(
        pending.payload_id == payload_id,
        "request payload changed payload_id"
    );
    ensure!(
        pending.started_at.elapsed() <= upload_timeout,
        "request payload exceeded its upload lifetime"
    );
    pending
        .collector
        .push(chunk)
        .map_err(|err| anyhow::anyhow!("collecting s.req_chunk failed: {err}"))?;
    Ok(())
}

fn provider_session_request_upload_timeout(max_request_bytes: usize) -> Result<Duration> {
    if let Some(configured) = std::env::var("MAYHEM_PROVIDER_SESSION_REQUEST_UPLOAD_MAX_MS").ok() {
        let millis = configured.trim().parse::<u64>().with_context(|| {
            "MAYHEM_PROVIDER_SESSION_REQUEST_UPLOAD_MAX_MS must be a positive integer in milliseconds"
        })?;
        ensure!(
            millis > 0,
            "MAYHEM_PROVIDER_SESSION_REQUEST_UPLOAD_MAX_MS must be positive"
        );
        return Ok(Duration::from_millis(millis));
    }
    let seconds = max_request_bytes
        .saturating_add(DEFAULT_PROVIDER_SESSION_REQUEST_UPLOAD_MIN_BYTES_PER_SECOND - 1)
        / DEFAULT_PROVIDER_SESSION_REQUEST_UPLOAD_MIN_BYTES_PER_SECOND;
    let millis = u64::try_from(seconds)
        .unwrap_or(u64::MAX / 1000)
        .saturating_mul(1000)
        .max(DEFAULT_PROVIDER_SESSION_REQUEST_UPLOAD_MIN_MILLIS);
    Ok(Duration::from_millis(millis))
}

fn provider_session_request_body_from_frame(
    pending_payloads: &mut HashMap<String, PendingProviderPayload>,
    session_id: &str,
    frame: &Value,
    max_request_bytes: usize,
) -> Result<Value> {
    if let Some(body) = frame.get("body") {
        let body_len = serde_json::to_vec(body)
            .context("serializing inline s.req body")?
            .len();
        ensure!(
            body_len <= max_request_bytes,
            "inline s.req body {body_len} bytes exceeds {max_request_bytes}-byte limit"
        );
        return Ok(body.clone());
    }
    let manifest: PayloadChunkManifest = serde_json::from_value(
        frame
            .get("body_ref")
            .cloned()
            .context("s.req missing body or body_ref")?,
    )
    .context("decoding s.req body_ref manifest")?;
    let request_id = provider_session_request_id(frame);
    let key = provider_session_payload_key(session_id, &request_id, &manifest.blake3);
    let pending = pending_payloads
        .remove(&key)
        .with_context(|| format!("s.req body_ref {} has no received chunks", manifest.blake3))?;
    pending
        .collector
        .finish_json(&manifest)
        .map_err(|err| anyhow::anyhow!("reassembling s.req body_ref failed: {err}"))
}

fn validate_provider_session_modalities(required: &[String], served: &[String]) -> Result<()> {
    if required.is_empty() {
        bail!("spend voucher required_modalities must not be empty");
    }
    let mut seen = BTreeSet::new();
    for modality in required {
        let modality = normalize_provider_modality(modality)?;
        if !seen.insert(modality.clone()) {
            bail!("spend voucher required_modalities duplicates {modality}");
        }
        if !served.contains(&modality) {
            bail!("provider does not serve required {modality} modality");
        }
    }
    Ok(())
}

fn validate_provider_session_specialities(
    required: &BTreeMap<String, String>,
    served: &BTreeMap<String, Vec<String>>,
) -> Result<()> {
    ensure!(
        required.len() == served.len() && required.keys().eq(served.keys()),
        "spend voucher must bind every provider speciality exactly once"
    );
    for (name, level) in required {
        ensure!(
            valid_provider_speciality_component(name) && valid_provider_speciality_component(level),
            "spend voucher contains an invalid speciality selection"
        );
        ensure!(
            served
                .get(name)
                .is_some_and(|levels| levels.contains(level)),
            "provider does not serve speciality {name} level {level}"
        );
    }
    Ok(())
}

fn provider_request_speciality_selection(
    endpoint_family: &str,
    body: &Value,
    adapter: &catalog::CatalogAdapter,
) -> Result<BTreeMap<String, String>> {
    let contract = adapter
        .endpoint_families
        .iter()
        .find(|contract| contract.family == endpoint_family)
        .with_context(|| format!("catalog adapter has no endpoint family {endpoint_family}"))?;
    let mut selected = BTreeMap::new();
    for descriptor in &adapter.specialities {
        let mapping = contract
            .speciality_mappings
            .get(&descriptor.name)
            .with_context(|| {
                format!(
                    "endpoint family {endpoint_family} has no native mapping for speciality {}",
                    descriptor.name
                )
            })?;
        let submitted = provider_request_path_value(body, &mapping.request_path);
        let selection =
            mayhem_proto::endpoint_speciality_level_for_request(descriptor, mapping, submitted)
                .with_context(|| {
                    format!(
                        "model speciality {} does not support value {}",
                        descriptor.name,
                        submitted
                            .map(Value::to_string)
                            .unwrap_or_else(|| descriptor.default_level.clone())
                    )
                });
        let level = if submitted.is_some() {
            provider_session_request_result(selection)?
        } else {
            selection?
        };
        selected.insert(descriptor.name.clone(), level.name.clone());
    }
    Ok(selected)
}

fn provider_request_path_value<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
    path.split('.')
        .try_fold(value, |current, component| current.get(component))
}

fn provider_speciality_level<'a>(
    descriptor: &'a mayhem_proto::ModelSpecialityDescriptor,
    submitted: Option<&Value>,
) -> Option<&'a mayhem_proto::ModelSpecialityLevel> {
    match submitted {
        Some(submitted) => descriptor.levels.iter().find(|level| {
            submitted.as_str() == Some(level.name.as_str()) || submitted == &level.native_value
        }),
        None => descriptor
            .levels
            .iter()
            .find(|level| level.name == descriptor.default_level),
    }
}

fn provider_session_request_modalities(
    family: &str,
    body: &Value,
    output_modalities: &[String],
    modality_load: &BTreeMap<String, ModalityRequestLoad>,
) -> Result<Vec<String>> {
    let mut modalities = match provider_endpoint_transport_kind(family)? {
        "embedding" => vec!["embedding".to_owned()],
        "image_generation" => vec!["image".to_owned()],
        "audio_speech" | "audio_generation" | "music_generation" => vec!["audio".to_owned()],
        "audio_transcription" => vec!["audio".to_owned(), "text".to_owned()],
        "video_generation" => mayhem_proto::video_generation_required_modalities(
            output_modalities,
            modality_load.contains_key("image"),
        ),
        "chat" => vec!["text".to_owned()],
        other => bail!("unsupported provider request kind {other}"),
    };
    if provider_endpoint_transport_kind(family)? == "chat" {
        let messages = body
            .get("messages")
            .and_then(Value::as_array)
            .map(Vec::as_slice)
            .unwrap_or(&[]);
        for message in messages {
            let Some(parts) = message.get("content").and_then(Value::as_array) else {
                continue;
            };
            for part in parts {
                match part.get("type").and_then(Value::as_str) {
                    Some("image_url") if !modalities.iter().any(|value| value == "image") => {
                        modalities.push("image".to_owned());
                    }
                    Some("input_audio") if !modalities.iter().any(|value| value == "audio") => {
                        modalities.push("audio".to_owned());
                    }
                    Some("video") if !modalities.iter().any(|value| value == "video") => {
                        modalities.push("video".to_owned());
                    }
                    _ => {}
                }
            }
        }
    }
    Ok(modalities)
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct ProviderChatMediaStats {
    image_count: u32,
    image_max_bytes: u64,
    image_max_pixels: u64,
    audio_count: u32,
    audio_max_bytes: u64,
    audio_max_seconds: u64,
    audio_seconds: u64,
    video_count: u32,
    video_max_bytes: u64,
    video_max_frames: u64,
}

fn provider_chat_media_stats(body: &Value) -> Result<ProviderChatMediaStats> {
    let mut stats = ProviderChatMediaStats::default();
    let mut media_parts = 0_u64;
    for message in body
        .get("messages")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
    {
        let Some(parts) = message.get("content").and_then(Value::as_array) else {
            continue;
        };
        for part in parts {
            match part.get("type").and_then(Value::as_str) {
                Some("image_url") => {
                    media_parts = media_parts.saturating_add(1);
                    let url = part
                        .get("image_url")
                        .and_then(|image| image.get("url"))
                        .or_else(|| part.get("url"))
                        .and_then(Value::as_str)
                        .context("image_url content is missing image_url.url")?;
                    let (bytes, pixels) = validate_provider_chat_image_data_url(url)?;
                    stats.image_count = stats.image_count.saturating_add(1);
                    stats.image_max_bytes = stats.image_max_bytes.max(bytes);
                    stats.image_max_pixels = stats.image_max_pixels.max(pixels);
                }
                Some("input_audio") => {
                    media_parts = media_parts.saturating_add(1);
                    let audio = part
                        .get("input_audio")
                        .context("input_audio content is missing input_audio")?;
                    let (bytes, seconds) = validate_provider_chat_audio_input(audio)?;
                    stats.audio_count = stats.audio_count.saturating_add(1);
                    stats.audio_max_bytes = stats.audio_max_bytes.max(bytes);
                    stats.audio_max_seconds = stats.audio_max_seconds.max(seconds);
                    stats.audio_seconds = stats.audio_seconds.saturating_add(seconds);
                }
                Some("video") => {
                    media_parts = media_parts.saturating_add(1);
                    let video = part
                        .get("video")
                        .context("video content is missing video")?;
                    let (bytes, frames) = validate_provider_chat_video_input(video)?;
                    stats.video_count = stats.video_count.saturating_add(1);
                    stats.video_max_bytes = stats.video_max_bytes.max(bytes);
                    stats.video_max_frames = stats.video_max_frames.max(frames);
                }
                _ => {}
            }
        }
    }
    ensure!(
        media_parts <= u64::from(MAX_PROVIDER_MODALITY_ITEMS_PER_REQUEST),
        "chat request exceeds the provider media schema item ceiling"
    );
    Ok(stats)
}

fn validate_provider_chat_image_data_url(url: &str) -> Result<(u64, u64)> {
    let rest = url
        .strip_prefix("data:")
        .context("remote image URLs are not fetched; use a base64 image data URL")?;
    let (metadata, encoded) = rest
        .split_once(',')
        .context("image data URL is malformed")?;
    let mut metadata_parts = metadata.split(';');
    let content_type = metadata_parts.next().unwrap_or_default();
    ensure!(
        matches!(content_type, "image/png" | "image/jpeg")
            && metadata_parts.any(|entry| entry == "base64"),
        "image data URL must be base64 PNG or JPEG"
    );
    ensure!(
        encoded.len()
            <= usize::try_from(MAX_PROVIDER_MODALITY_ITEM_BYTES)
                .unwrap_or(usize::MAX / 4)
                .saturating_mul(4)
                .div_ceil(3)
                .saturating_add(4),
        "image input exceeds the provider media schema byte ceiling"
    );
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(encoded)
        .context("image data URL contains invalid base64")?;
    ensure!(
        !bytes.is_empty()
            && u64::try_from(bytes.len()).unwrap_or(u64::MAX) <= MAX_PROVIDER_MODALITY_ITEM_BYTES,
        "image input exceeds the provider media schema byte ceiling"
    );
    let (width, height) = ImageReader::new(io::Cursor::new(&bytes))
        .with_guessed_format()
        .context("image input format is invalid")?
        .into_dimensions()
        .context("image input cannot be decoded")?;
    let pixels = u64::from(width).saturating_mul(u64::from(height));
    ensure!(
        width > 0 && height > 0 && pixels <= MAX_PROVIDER_MODALITY_ITEM_UNITS,
        "image input exceeds the provider media schema pixel ceiling"
    );
    Ok((u64::try_from(bytes.len()).unwrap_or(u64::MAX), pixels))
}

fn validate_provider_chat_audio_input(audio: &Value) -> Result<(u64, u64)> {
    let format = audio
        .get("format")
        .and_then(Value::as_str)
        .unwrap_or("wav")
        .to_ascii_lowercase();
    ensure!(
        format == "wav",
        "input_audio currently requires format=wav for bounded decoding and exact metering"
    );
    let encoded = audio
        .get("data")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .context("input_audio.data is required")?;
    ensure!(
        encoded.len()
            <= usize::try_from(MAX_PROVIDER_MODALITY_ITEM_BYTES)
                .unwrap_or(usize::MAX / 4)
                .saturating_mul(4)
                .div_ceil(3)
                .saturating_add(4),
        "audio input exceeds the provider media schema byte ceiling"
    );
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(encoded)
        .context("input_audio.data contains invalid base64")?;
    ensure!(
        !bytes.is_empty()
            && u64::try_from(bytes.len()).unwrap_or(u64::MAX) <= MAX_PROVIDER_MODALITY_ITEM_BYTES,
        "audio input exceeds the provider media schema byte ceiling"
    );
    let seconds =
        wav_duration_seconds_ceil(&bytes).context("input_audio is not a valid bounded WAV")?;
    ensure!(
        (1..=MAX_PROVIDER_MODALITY_ITEM_UNITS).contains(&seconds),
        "audio input exceeds the provider media schema duration ceiling"
    );
    Ok((u64::try_from(bytes.len()).unwrap_or(u64::MAX), seconds))
}

fn validate_provider_chat_video_input(video: &Value) -> Result<(u64, u64)> {
    let encoded = video
        .get("data")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty());
    let decoded_frames = video.get("frames").and_then(Value::as_array);
    ensure!(
        encoded.is_some() != decoded_frames.is_some(),
        "video requires exactly one of data or decoded frames"
    );
    if let Some(frames) = decoded_frames {
        ensure!(
            video.get("content_type").is_none(),
            "video.content_type is only valid with video.data"
        );
        ensure!(
            !frames.is_empty()
                && u64::try_from(frames.len()).unwrap_or(u64::MAX)
                    <= MAX_PROVIDER_MODALITY_ITEM_UNITS,
            "video.frames exceeds the provider media schema frame ceiling"
        );
        let mut total_bytes = 0_u64;
        for frame in frames {
            let url = frame
                .as_str()
                .context("video.frames entries must be base64 image data URLs")?;
            let (bytes, _) = validate_provider_chat_image_data_url(url)?;
            total_bytes = total_bytes.saturating_add(bytes);
            ensure!(
                total_bytes <= MAX_PROVIDER_MODALITY_ITEM_BYTES,
                "decoded video frames exceed the provider media schema byte ceiling"
            );
        }
        let frame_count = u64::try_from(frames.len()).unwrap_or(u64::MAX);
        ensure!(
            video
                .get("num_frames")
                .and_then(Value::as_u64)
                .is_none_or(|declared| declared == frame_count),
            "video.num_frames must match video.frames length"
        );
        validate_provider_chat_video_fps(video)?;
        return Ok((total_bytes, frame_count));
    }

    let content_type = video
        .get("content_type")
        .and_then(Value::as_str)
        .context("video.content_type is required")?;
    ensure!(
        matches!(content_type, "video/mp4" | "video/webm" | "video/quicktime"),
        "video.content_type must be video/mp4, video/webm, or video/quicktime"
    );
    let encoded = encoded.expect("exactly one video representation was validated");
    ensure!(
        encoded.len()
            <= usize::try_from(MAX_PROVIDER_MODALITY_ITEM_BYTES)
                .unwrap_or(usize::MAX / 4)
                .saturating_mul(4)
                .div_ceil(3)
                .saturating_add(4),
        "video input exceeds the provider media schema byte ceiling"
    );
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(encoded)
        .context("video.data contains invalid base64")?;
    ensure!(
        !bytes.is_empty()
            && u64::try_from(bytes.len()).unwrap_or(u64::MAX) <= MAX_PROVIDER_MODALITY_ITEM_BYTES,
        "video input exceeds the provider media schema byte ceiling"
    );
    let frames = video
        .get("num_frames")
        .and_then(Value::as_u64)
        .filter(|frames| *frames > 0)
        .context("video.num_frames must be a positive integer")?;
    ensure!(
        frames <= MAX_PROVIDER_MODALITY_ITEM_UNITS,
        "video input exceeds the provider media schema frame ceiling"
    );
    validate_provider_chat_video_fps(video)?;
    Ok((u64::try_from(bytes.len()).unwrap_or(u64::MAX), frames))
}

fn validate_provider_chat_video_fps(video: &Value) -> Result<()> {
    if let Some(fps) = video.get("fps") {
        fps.as_f64()
            .filter(|fps| fps.is_finite() && *fps > 0.0 && *fps <= 240.0)
            .context("video.fps must be a finite number between 0 and 240")?;
    }
    Ok(())
}

fn validate_provider_session_request_modalities(
    active: &ActiveProviderSession,
    terms: &ProviderSessionTerms,
    body: &Value,
) -> Result<BTreeMap<String, u32>> {
    let verified = provider_verify_endpoint_request(body, Some(&terms.model_id), &terms.adapter)?;
    provider_session_request_result(validate_provider_session_modalities(
        &active.required_modalities,
        &terms.served_modalities,
    ))?;
    provider_session_request_result(validate_provider_session_specialities(
        &active.required_specialities,
        &terms.served_specialities,
    ))?;
    let actual_specialities =
        provider_request_speciality_selection(verified.family, verified.request, &terms.adapter)?;
    if actual_specialities != active.required_specialities {
        return Err(provider_session_request_error(format!(
            "request specialities {:?} do not match signed voucher specialities {:?}",
            actual_specialities, active.required_specialities
        )));
    }
    let load = provider_session_modality_load(
        verified.contract,
        verified.family,
        verified.request,
        body,
        &terms.output_modalities,
    )?;
    let actual = provider_session_request_modalities(
        verified.family,
        verified.request,
        &terms.output_modalities,
        &load,
    )?;
    if actual != active.required_modalities {
        return Err(provider_session_request_error(format!(
            "request modalities {:?} do not match signed voucher modalities {:?}",
            actual, active.required_modalities
        )));
    }
    for modality in actual.iter().filter(|modality| modality.as_str() != "text") {
        let request = load
            .get(modality)
            .with_context(|| format!("provider failed to measure {modality} request load"))?;
        let capacity = terms
            .modality_capacities
            .get(modality)
            .with_context(|| format!("provider has no advertised {modality} capacity"))?;
        ensure!(
            capacity.max_items_per_request > 0
                && capacity.max_item_bytes > 0
                && capacity.max_item_units > 0,
            "provider advertised invalid zero-valued {modality} request capacity"
        );
        if request.item_count == 0
            || request.item_count > capacity.max_items_per_request
            || request.max_item_bytes == 0
            || request.max_item_bytes > capacity.max_item_bytes
            || request.max_item_units == 0
            || request.max_item_units > capacity.max_item_units
        {
            return Err(provider_session_request_error(format!(
                "request exceeds provider {modality} capacity: items {} of {}, bytes {} of {}, units {} of {}",
                request.item_count,
                capacity.max_items_per_request,
                request.max_item_bytes,
                capacity.max_item_bytes,
                request.max_item_units,
                capacity.max_item_units
            )));
        }
    }
    Ok(load
        .into_iter()
        .map(|(modality, load)| (modality, load.item_count))
        .collect())
}

fn provider_video_conditioning_image_load(body: &Value) -> Result<Option<ModalityRequestLoad>> {
    let parameters = body.get("parameters").and_then(Value::as_object);
    let top_level = body.get("conditions").filter(|value| !value.is_null());
    let nested = parameters
        .and_then(|parameters| parameters.get("conditions"))
        .filter(|value| !value.is_null());
    ensure!(
        top_level.is_none() || nested.is_none(),
        "video generation conditions must appear at exactly one signed request path"
    );
    let Some(conditions) = top_level.or(nested) else {
        return Ok(None);
    };
    let conditions = conditions
        .as_array()
        .context("video generation conditions must be an ordered array")?;
    ensure!(
        conditions.len()
            <= usize::try_from(MAX_PROVIDER_MODALITY_ITEMS_PER_REQUEST).unwrap_or(usize::MAX),
        "video generation conditions exceed the provider image item ceiling"
    );
    let mut load = ModalityRequestLoad {
        item_count: 0,
        max_item_bytes: 0,
        max_item_units: 0,
    };
    for (index, condition) in conditions.iter().enumerate() {
        let image_url = condition
            .get("image_url")
            .and_then(Value::as_str)
            .with_context(|| {
                format!("video generation conditions[{index}] is missing image_url")
            })?;
        let (bytes, pixels) = validate_provider_chat_image_data_url(image_url)?;
        load.item_count = load.item_count.saturating_add(1);
        load.max_item_bytes = load.max_item_bytes.max(bytes);
        load.max_item_units = load.max_item_units.max(pixels);
    }
    Ok((load.item_count > 0).then_some(load))
}

fn provider_session_modality_load(
    contract: &mayhem_proto::EndpointFamilyContract,
    family: &str,
    body: &Value,
    transport_body: &Value,
    output_modalities: &[String],
) -> Result<BTreeMap<String, ModalityRequestLoad>> {
    match provider_endpoint_transport_kind(family)? {
        "chat" => {
            let media = provider_session_request_result(provider_chat_media_stats(body))?;
            let mut load = BTreeMap::new();
            if media.image_count > 0 {
                load.insert(
                    "image".to_owned(),
                    ModalityRequestLoad {
                        item_count: media.image_count,
                        max_item_bytes: media.image_max_bytes,
                        max_item_units: media.image_max_pixels,
                    },
                );
            }
            if media.audio_count > 0 {
                load.insert(
                    "audio".to_owned(),
                    ModalityRequestLoad {
                        item_count: media.audio_count,
                        max_item_bytes: media.audio_max_bytes,
                        max_item_units: media.audio_max_seconds,
                    },
                );
            }
            if media.video_count > 0 {
                load.insert(
                    "video".to_owned(),
                    ModalityRequestLoad {
                        item_count: media.video_count,
                        max_item_bytes: media.video_max_bytes,
                        max_item_units: media.video_max_frames,
                    },
                );
            }
            Ok(load)
        }
        "embedding" => {
            let inputs =
                provider_session_request_result(provider_embedding_input_texts_from_body(body))?;
            let max_item_bytes = inputs
                .iter()
                .map(|input| u64::try_from(input.len()).unwrap_or(u64::MAX))
                .max()
                .unwrap_or(1)
                .max(1);
            let max_item_units = inputs
                .iter()
                .map(|input| rough_text_tokens(input))
                .max()
                .unwrap_or(1)
                .max(1);
            Ok(BTreeMap::from([(
                "embedding".to_owned(),
                ModalityRequestLoad {
                    item_count: u32::try_from(inputs.len()).unwrap_or(u32::MAX).max(1),
                    max_item_bytes,
                    max_item_units,
                },
            )]))
        }
        "image_generation" => {
            let request = provider_session_request_result(
                provider_image_generation_request_from_body(family, body),
            )?;
            Ok(BTreeMap::from([(
                "image".to_owned(),
                ModalityRequestLoad {
                    item_count: request.image_count,
                    max_item_bytes: 1,
                    max_item_units: u64::from(request.width)
                        .saturating_mul(u64::from(request.height)),
                },
            )]))
        }
        "audio_transcription" => {
            let request = provider_session_request_result(
                provider_audio_transcription_request_from_body(family, body, transport_body),
            )?;
            Ok(BTreeMap::from([(
                "audio".to_owned(),
                ModalityRequestLoad {
                    item_count: 1,
                    max_item_bytes: u64::try_from(request.engine.audio.len())
                        .unwrap_or(u64::MAX)
                        .max(1),
                    max_item_units: request.audio_seconds.max(1),
                },
            )]))
        }
        "audio_speech" => {
            let request =
                provider_session_request_result(provider_speech_request_from_body(family, body))?;
            let estimated_seconds = u64::try_from(request.input.chars().count())
                .unwrap_or(u64::MAX)
                .div_ceil(12)
                .max(1);
            let reference_bytes = request
                .reference_audio
                .as_ref()
                .map(|reference| u64::try_from(reference.data.len()).unwrap_or(u64::MAX))
                .unwrap_or(0);
            let reference_seconds = request
                .reference_audio
                .as_ref()
                .and_then(|reference| wav_duration_seconds_ceil(&reference.data))
                .unwrap_or(0);
            Ok(BTreeMap::from([(
                "audio".to_owned(),
                ModalityRequestLoad {
                    item_count: 1,
                    max_item_bytes: reference_bytes.max(1),
                    max_item_units: estimated_seconds.max(reference_seconds),
                },
            )]))
        }
        "video_generation" => {
            let request = provider_session_request_result(
                provider_media_generation_request_from_body(family, body),
            )?;
            let (duration_seconds, frames) = provider_video_output_expectation(contract, &request)?;
            let output_item_count = provider_session_request_result(
                request
                    .request
                    .get("n")
                    .and_then(Value::as_u64)
                    .map(u32::try_from)
                    .transpose()
                    .context("video generation n overflowed u32"),
            )?
            .unwrap_or(1)
            .max(1);
            let mut load = BTreeMap::from([(
                "video".to_owned(),
                ModalityRequestLoad {
                    item_count: output_item_count,
                    max_item_bytes: 1,
                    max_item_units: frames,
                },
            )]);
            if output_modalities.iter().any(|modality| modality == "audio") {
                load.insert(
                    "audio".to_owned(),
                    ModalityRequestLoad {
                        item_count: output_item_count,
                        max_item_bytes: 1,
                        max_item_units: duration_seconds,
                    },
                );
            }
            if let Some(image_load) =
                provider_session_request_result(provider_video_conditioning_image_load(body))?
            {
                load.insert("image".to_owned(), image_load);
            }
            Ok(load)
        }
        "audio_generation" | "music_generation" => {
            let request = provider_session_request_result(
                provider_media_generation_request_from_body(family, body),
            )?;
            let output_item_count = provider_session_request_result(
                request
                    .request
                    .get("n")
                    .and_then(Value::as_u64)
                    .map(u32::try_from)
                    .transpose()
                    .context("media generation n overflowed u32"),
            )?
            .unwrap_or(1)
            .max(1);
            let inline_audio = provider_session_request_result(
                artifact_generation_inline_audio_load(&request.request).map_err(anyhow::Error::msg),
            )?;
            let item_count = output_item_count.max(inline_audio.item_count);
            let max_item_units = request
                .duration_seconds
                .unwrap_or(inline_audio.max_item_seconds.max(1))
                .max(inline_audio.max_item_seconds)
                .max(1);
            Ok(BTreeMap::from([(
                "audio".to_owned(),
                ModalityRequestLoad {
                    item_count,
                    max_item_bytes: inline_audio.max_item_bytes.max(1),
                    max_item_units,
                },
            )]))
        }
        other => bail!("unsupported provider request kind {other}"),
    }
}

fn provider_session_request_timeout() -> Result<Duration> {
    let configured = std::env::var("MAYHEM_PROVIDER_SESSION_REQUEST_STALL_TIMEOUT_MS").ok();
    provider_session_request_timeout_from(configured.as_deref())
}

fn provider_session_admission_timeout() -> Result<Duration> {
    provider_session_admission_timeout_from(
        std::env::var("MAYHEM_PROVIDER_ADMISSION_TIMEOUT_MS")
            .ok()
            .as_deref(),
    )
}

fn provider_session_admission_timeout_from(configured: Option<&str>) -> Result<Duration> {
    let millis = match configured {
        Some(value) => value.trim().parse::<u64>().with_context(|| {
            "MAYHEM_PROVIDER_ADMISSION_TIMEOUT_MS must be a positive integer in milliseconds"
        })?,
        None => DEFAULT_PROVIDER_ADMISSION_TIMEOUT_MILLIS,
    };
    ensure!(
        millis > 0,
        "MAYHEM_PROVIDER_ADMISSION_TIMEOUT_MS must be positive"
    );
    Ok(Duration::from_millis(millis))
}

/// Deadline for one loopback SC-Bridge request/reply on the provider session bridge.
/// This bounds control operations (session_send/session_open/peer_connect acks), NOT
/// inference or streaming duration; a reply that never arrives means the local
/// Intercom handler is stuck on a dead remote (2026-07-12 live wedge: one s.reject
/// send waiting forever on remote drain silenced the whole provider). The default
/// must stay above every peer-side bounded wait it can carry — the Intercom defaults
/// are 120s `--session-connect-max-wait-ms` / `--session-open-max-wait-ms` and the
/// 90s peer_connect open budget — so operators who raise those knobs must raise this
/// one too. `0` disables the deadline (historical wait-forever behavior).
const DEFAULT_PROVIDER_SESSION_BRIDGE_OP_TIMEOUT_MILLIS: u64 = 180_000;

fn provider_session_bridge_operation_deadline() -> Result<Option<Duration>> {
    provider_session_bridge_operation_deadline_from(
        std::env::var("MAYHEM_PROVIDER_SESSION_BRIDGE_OP_TIMEOUT_MS")
            .ok()
            .as_deref(),
    )
}

fn provider_session_bridge_operation_deadline_from(
    configured: Option<&str>,
) -> Result<Option<Duration>> {
    let millis = match configured {
        Some(value) => value.trim().parse::<u64>().with_context(|| {
            "MAYHEM_PROVIDER_SESSION_BRIDGE_OP_TIMEOUT_MS must be a non-negative integer in milliseconds (0 disables the deadline)"
        })?,
        None => DEFAULT_PROVIDER_SESSION_BRIDGE_OP_TIMEOUT_MILLIS,
    };
    Ok((millis > 0).then(|| Duration::from_millis(millis)))
}

fn provider_session_request_timeout_from(configured: Option<&str>) -> Result<Duration> {
    let millis = match configured {
        Some(value) => value.trim().parse::<u64>().with_context(|| {
            "MAYHEM_PROVIDER_SESSION_REQUEST_STALL_TIMEOUT_MS must be a positive integer in milliseconds"
        })?,
        None => DEFAULT_PROVIDER_SESSION_REQUEST_STALL_TIMEOUT_MILLIS,
    };
    ensure!(
        millis > 0,
        "MAYHEM_PROVIDER_SESSION_REQUEST_STALL_TIMEOUT_MS must be positive"
    );
    Ok(Duration::from_millis(millis))
}

fn provider_session_request_limits(terms: &ProviderSessionTerms) -> Result<(usize, usize)> {
    let (derived_max, derived_max_chunks) = provider_session_derived_request_limits(terms)?;
    let max_bytes = match std::env::var("MAYHEM_PROVIDER_SESSION_MAX_REQUEST_BYTES").ok() {
        Some(value) => value
            .trim()
            .parse::<usize>()
            .ok()
            .filter(|value| *value > 0)
            .context("MAYHEM_PROVIDER_SESSION_MAX_REQUEST_BYTES must be a positive integer")?,
        None => derived_max,
    };
    ensure!(
        max_bytes >= derived_max,
        "MAYHEM_PROVIDER_SESSION_MAX_REQUEST_BYTES ({max_bytes}) is below the {derived_max}-byte context + advertised modality transport budget"
    );
    let max_chunks = match std::env::var("MAYHEM_SESSION_MAX_PAYLOAD_CHUNKS").ok() {
        Some(value) => value
            .trim()
            .parse::<usize>()
            .ok()
            .filter(|value| *value > 0)
            .context("MAYHEM_SESSION_MAX_PAYLOAD_CHUNKS must be a positive integer")?,
        None => derived_max_chunks,
    };
    Ok((max_bytes, max_chunks))
}

fn provider_session_derived_request_limits(terms: &ProviderSessionTerms) -> Result<(usize, usize)> {
    let ctx = usize::try_from(terms.ctx).context("provider context exceeds platform range")?;
    let text_budget = ctx
        .checked_mul(DEFAULT_PROVIDER_SESSION_REQUEST_BYTES_PER_CTX_TOKEN)
        .context("provider request byte limit overflowed platform range")?;
    let media_budget = terms
        .modality_capacities
        .values()
        .map(|capacity| {
            let raw_bytes = capacity
                .max_item_bytes
                .saturating_mul(u64::from(capacity.max_items_per_request));
            provider_session_base64_encoded_len(raw_bytes)
        })
        .fold(0_u64, u64::saturating_add);
    let media_budget = usize::try_from(media_budget).unwrap_or(usize::MAX);
    let derived_max = text_budget
        .saturating_add(media_budget)
        .saturating_add(DEFAULT_PROVIDER_SESSION_REQUEST_JSON_OVERHEAD_BYTES)
        .max(DEFAULT_SESSION_MAX_REASSEMBLED_PAYLOAD_BYTES);
    let derived_max_chunks = derived_max
        .div_ceil(1024)
        .max(DEFAULT_SESSION_MAX_PAYLOAD_CHUNKS);
    Ok((derived_max, derived_max_chunks))
}

fn provider_session_base64_encoded_len(raw_bytes: u64) -> u64 {
    let full_groups = raw_bytes / 3;
    let remainder = raw_bytes % 3;
    full_groups
        .saturating_mul(4)
        .saturating_add(if remainder == 0 { 0 } else { 4 })
}

fn record_provider_session_request_progress(
    pending_requests: &mut HashMap<String, Instant>,
    session_id: &str,
    progressed_at: Instant,
    request_timeout: Duration,
) {
    pending_requests.insert(session_id.to_owned(), progressed_at + request_timeout);
}

async fn handle_provider_session_frame(
    bridge: &mut ScBridgeClient,
    sessions: &mut HashMap<String, ActiveProviderSession>,
    rejected_sessions: &mut HashMap<String, ProviderSessionRejectReplay>,
    pending_requests: &mut HashMap<String, Instant>,
    pending_payloads: &mut HashMap<String, PendingProviderPayload>,
    heartbeat_load: &ProviderHeartbeatLoad,
    protection: &mut ProviderProtectionState,
    tpm_activation_limiter: &mut ProviderTpmActivationLimiter,
    terms: &ProviderSessionTerms,
    runtime: &ProviderSessionRuntime<'_>,
    sc_bridge_url: &str,
    sc_bridge_token: &str,
    bridge_operation_deadline: Option<Duration>,
    admission_timeout: Duration,
    responder: &mut dyn ProviderSessionResponder,
    engine_recovery: &mut ProviderEngineRecovery,
    runtime_floor_reject: Option<ProviderRuntimeFloorRejection>,
    request_stall_timeout: Duration,
    max_request_bytes: usize,
    max_payload_chunks: usize,
    event: Value,
) -> Result<()> {
    let frame = event
        .get("frame")
        .cloned()
        .filter(Value::is_object)
        .context("provider session event frame must be an object")?;
    let session_id = event
        .get("session_id")
        .and_then(Value::as_str)
        .filter(|session_id| is_hex_len(session_id, 64))
        .context("provider session event has invalid session_id")?
        .to_owned();
    let remote = event
        .get("remote")
        .and_then(Value::as_str)
        .filter(|remote| is_hex_len(remote, 64))
        .context("provider session frame has invalid remote peer")?
        .to_owned();
    ensure!(
        frame
            .get("session_id")
            .and_then(Value::as_str)
            .is_none_or(|frame_session_id| frame_session_id == session_id),
        "provider session frame session_id mismatch"
    );
    let frame_type = frame
        .get("t")
        .and_then(Value::as_str)
        .filter(|frame_type| !frame_type.is_empty() && frame_type.len() <= 64)
        .context("provider session frame has invalid type")?;
    if !provider_session_event_belongs_to_process(&event, sessions, terms) {
        provider_session_debug(format!(
            "ignoring unowned provider session frame {frame_type} for {session_id} from {remote} on the shared SC-Bridge"
        ));
        return Ok(());
    }
    match frame_type {
        TPM_ACTIVATE_CREDENTIAL_CHALLENGE_FRAME_TYPE => {
            let challenge_frame: TpmActivateCredentialChallengeFrame =
                serde_json::from_value(frame.clone())
                    .context("TPM activation challenge frame is invalid")?;
            ensure!(
                challenge_frame.frame_type == TPM_ACTIVATE_CREDENTIAL_CHALLENGE_FRAME_TYPE
                    && challenge_frame.version == TPM_ACTIVATE_CREDENTIAL_FRAME_VERSION,
                "TPM activation challenge frame version is unsupported"
            );
            ensure!(
                challenge_frame.session_id == session_id
                    && challenge_frame.challenge.challenge_id == session_id,
                "TPM activation challenge session binding mismatch"
            );
            ensure!(
                challenge_frame.provider == terms.provider
                    && challenge_frame.enclave_id == terms.enclave_id
                    && terms.room_ids.contains(&challenge_frame.room_id),
                "TPM activation challenge targets a different provider route"
            );
            let hello = runtime
                .tpm_activation_hello
                .context("provider has no TPM activation material")?;
            ensure!(
                challenge_frame.challenge.ak_name_b64 == hello.ak_name_b64
                    && challenge_frame.challenge.quote_binding == hello.quote_binding,
                "TPM activation challenge does not match the signed provider hello"
            );
            tpm_activation_limiter.admit(&remote, Instant::now())?;
            let config = runtime
                .hardware_quote_config
                .as_ref()
                .filter(|config| config.kind == HardwareQuoteKind::Tpm2QuoteEk)
                .context("provider has no TPM 2.0 activation helper")?;
            open_provider_direct_session(bridge, &remote, &session_id)
                .await
                .context("opening provider side of TPM activation session")?;
            let response =
                run_provider_tpm_activation_command(config, &challenge_frame.challenge).await?;
            let response_frame = TpmActivateCredentialResponseFrame {
                frame_type: TPM_ACTIVATE_CREDENTIAL_RESPONSE_FRAME_TYPE.to_owned(),
                version: TPM_ACTIVATE_CREDENTIAL_FRAME_VERSION,
                session_id: session_id.clone(),
                provider: terms.provider.clone(),
                enclave_id: terms.enclave_id.clone(),
                room_id: challenge_frame.room_id,
                response,
            };
            let send_result = bridge
                .session_send(&remote, &session_id, response_frame)
                .await
                .context("sending TPM activation response");
            let _ = bridge.session_close(&remote, &session_id).await;
            send_result?;
        }
        "s.open" => {
            prune_provider_session_reject_replays(rejected_sessions, Instant::now());
            if let Some(replay) = rejected_sessions.get(&session_id) {
                match provider_session_reject_replay_decision(replay, &remote, &frame)? {
                    ProviderSessionReplayDecision::Cached(reject_frame) => {
                        provider_session_debug(format!(
                            "replaying cached s.reject for terminal session {session_id} after transport reconnect"
                        ));
                        open_provider_direct_session(bridge, &remote, &session_id)
                            .await
                            .context("reopening rejected provider session for replay")?;
                        let send_result = bridge
                            .session_send(&remote, &session_id, reject_frame)
                            .await
                            .context("replaying cached s.reject");
                        let _ = bridge.session_close(&remote, &session_id).await;
                        send_result?;
                    }
                    ProviderSessionReplayDecision::Conflict
                    | ProviderSessionReplayDecision::Pending => {
                        provider_session_debug(format!(
                            "refusing changed s.open replay for terminal session {session_id} from {remote}"
                        ));
                        let _ = bridge.session_close(&remote, &session_id).await;
                    }
                }
                return Ok(());
            }
            if let Some(existing) = sessions.get(&session_id) {
                if existing.remote != remote {
                    provider_session_debug(format!(
                        "refusing colliding s.open for active session {session_id} from {remote}"
                    ));
                    let _ = bridge.session_close(&remote, &session_id).await;
                } else {
                    match provider_session_replay_decision(existing, &frame)? {
                        ProviderSessionReplayDecision::Cached(accept_frame) => {
                            provider_session_debug(format!(
                                "replaying cached s.accept for active session {session_id} after transport reconnect"
                            ));
                            if let Err(err) = bridge
                                .session_send(&remote, &session_id, accept_frame)
                                .await
                            {
                                provider_session_debug(format!(
                                    "cached s.accept replay for session {session_id} is waiting for the next transport reconnect: {err}"
                                ));
                            }
                        }
                        ProviderSessionReplayDecision::Conflict => {
                            provider_session_debug(format!(
                                "refusing changed s.open replay for active session {session_id} from {remote}"
                            ));
                            let _ = bridge.session_close(&remote, &session_id).await;
                        }
                        ProviderSessionReplayDecision::Pending => {
                            provider_session_debug(format!(
                                "s.open replay for session {session_id} arrived before admission completed; preserving the original admission"
                            ));
                        }
                    }
                }
                return Ok(());
            }
            if !provider_session_open_targets_enclave(&frame, terms) {
                provider_session_debug(format!(
                    "ignoring s.open for session {session_id} from {remote}: frame targets a different enclave"
                ));
                return Ok(());
            }
            provider_session_debug(format!(
                "handling s.open for session {session_id} from {remote}"
            ));
            provider_session_debug(format!("opening provider side of session {session_id}"));
            if let Err(err) = open_provider_direct_session(bridge, &remote, &session_id).await {
                provider_session_debug(format!(
                    "could not open provider side of session {session_id}; leaving the provider online for a clean client retry: {err:#}"
                ));
                let _ = bridge.session_close(&remote, &session_id).await;
                return Ok(());
            }
            provider_session_debug(format!("provider side session {session_id} opened"));
            let session_rail = provider_session_frame_rail(&frame).unwrap_or_default();
            let contract = read_contract_catalog(runtime.rpc).await?;
            let validation_terms = ProviderSessionTerms {
                ctx_bracket_schedule: contract.ctx_bracket_schedule.clone(),
                ..terms.clone()
            };
            let policy_binding =
                provider_session_attestation_policy_binding(&frame, &validation_terms, runtime);
            let static_decision = match &policy_binding {
                Ok(_) => provider_session_open_decision(&frame, &validation_terms),
                Err(error) => ProviderSessionDecision::Reject {
                    code: "ATTESTATION_POLICY",
                    reason: error.to_string(),
                },
            };
            let decision = match static_decision {
                ProviderSessionDecision::Accept => {
                    let protection_decision = if let Some(reject) = runtime_floor_reject {
                        ProviderSessionDecision::Reject {
                            code: reject.code,
                            reason: reject.reason,
                        }
                    } else if !runtime
                        .receipt_settlement
                        .outbox
                        .admission_available()
                        .unwrap_or(false)
                    {
                        ProviderSessionDecision::Reject {
                            code: "SETTLEMENT_BACKPRESSURE",
                            reason: "provider receipt settlement outbox is near capacity; refusing new work until durable evidence is relayed".to_owned(),
                        }
                    } else if heartbeat_load.is_accepting_new() {
                        protection.acceptance_decision(sessions.len())
                    } else {
                        ProviderSessionDecision::Reject {
                            code: "DRAINING",
                            reason:
                                "provider is gracefully draining and not accepting new sessions"
                                    .to_owned(),
                        }
                    };
                    if !matches!(protection_decision, ProviderSessionDecision::Accept) {
                        protection_decision
                    } else {
                        provider_session_debug(
                            "s.open static decision accepted; rechecking contract",
                        );
                        let live_decision = provider_session_contract_decision(
                            &contract,
                            terms,
                            runtime.rooms,
                            &session_rail,
                        );
                        match live_decision {
                            ProviderSessionDecision::Accept => {
                                match tokio::time::timeout(
                                    admission_timeout,
                                    provider_session_spend_reservation_decision(
                                        runtime.rpc,
                                        runtime.keypair_path,
                                        runtime.password,
                                        &runtime.runtime_keypair.public_key_hex(),
                                        terms,
                                        &frame,
                                        &session_rail,
                                    ),
                                )
                                .await
                                {
                                    Ok(decision) => decision?,
                                    Err(_) => ProviderSessionDecision::Reject {
                                        code: "BALANCE",
                                        reason: format!(
                                            "spend reservation did not complete within the {} ms provider admission budget; no work was served",
                                            admission_timeout.as_millis()
                                        ),
                                    },
                                }
                            }
                            reject => reject,
                        }
                    }
                }
                reject => reject,
            };
            match decision {
                ProviderSessionDecision::Accept => {
                    provider_session_debug(format!("sending s.accept for session {session_id}"));
                    let spend_voucher: SpendVoucher = serde_json::from_value(
                        frame
                            .get("voucher")
                            .cloned()
                            .context("accepted s.open missing spend voucher")?,
                    )
                    .context("accepted s.open invalid spend voucher")?;
                    let checkpoint_every = provider_session_frame_checkpoint_policy(&frame)
                        .context("accepted s.open missing checkpoint policy")?;
                    let mut active = ActiveProviderSession {
                        remote: remote.clone(),
                        rail: session_rail.to_owned(),
                        user_pubkey: frame
                            .get("user")
                            .and_then(Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        session_id: session_id.clone(),
                        billing_id: spend_voucher.body.billing_id.clone(),
                        billing_attempt: spend_voucher.body.billing_attempt,
                        billing_prior_usage: spend_voucher.body.billing_prior_usage.clone(),
                        billing_prior_au_owed_cum: spend_voucher.body.billing_prior_au_owed_cum,
                        billing_epoch: spend_voucher.body.billing_epoch,
                        reservation_id: spend_voucher.body.reservation_id.clone(),
                        reservation_expires_after_epoch: spend_voucher
                            .body
                            .reservation_expires_after_epoch,
                        reservation_receipt_grace_epochs: spend_voucher
                            .body
                            .reservation_receipt_grace_epochs,
                        payout_revision: spend_voucher.body.payout_revision.clone(),
                        price_ver: spend_voucher.body.price_ver,
                        locked_rate_map: normalize_rate_map(
                            spend_voucher.body.locked_rate_map.clone(),
                        ),
                        locked_per_req_au: spend_voucher.body.locked_per_req_au,
                        locked_min_session_au: spend_voucher.body.locked_min_session_au,
                        served_ctx: spend_voucher.body.served_ctx,
                        required_modalities: spend_voucher.body.required_modalities.clone(),
                        required_specialities: spend_voucher.body.required_specialities.clone(),
                        ctx_bracket: spend_voucher.body.ctx_bracket.clone(),
                        ctx_bracket_table_ver: spend_voucher.body.ctx_bracket_table_ver,
                        checkpoint_every,
                        max_spend_au: spend_voucher.body.max_spend_au,
                        receipt_settlement: Some(runtime.receipt_settlement.clone()),
                        accept_replay: None,
                    };
                    let ts = unix_epoch_millis()?;
                    let open_head =
                        session_frame_head(&frame).context("hashing s.open frame for s.accept")?;
                    let att_nonce = frame
                        .get("att_nonce")
                        .and_then(Value::as_str)
                        .context("accepted s.open missing validated att_nonce")?;
                    let session_attestation = provider_session_attestation(
                        runtime,
                        terms,
                        att_nonce,
                        policy_binding
                            .as_ref()
                            .expect("accepted session policy binding was validated")
                            .as_ref(),
                    )
                    .await
                    .context("building per-session s.accept attestation")?;
                    let mut accept_frame = json!({
                        "t": "s.accept",
                        "v": 1,
                        "contract_version": terms.contract_version,
                        "session_id": session_id,
                        "open_head": open_head.clone(),
                        "att_nonce": att_nonce,
                        "att_report": session_attestation.report,
                        "engine": {
                            "ctx": terms.ctx,
                            "ctx_bracket": spend_voucher.body.ctx_bracket.clone(),
                            "ctx_bracket_table_ver": spend_voucher.body.ctx_bracket_table_ver,
                            "mode": "provider-session-server-v1",
                        },
                        "ts": ts,
                        "nonce": stable_value_hash(&json!({
                            "session_id": frame.get("session_id"),
                            "provider": terms.provider,
                            "kind": "accept",
                            "ts": ts,
                        })),
                    });
                    let accept_payload = session_accept_signing_bytes(&accept_frame)
                        .context("building s.accept signing payload")?;
                    let accept_sig = sign_hex(
                        runtime.keypair_path,
                        runtime.password,
                        &hex_encode(&accept_payload),
                    )
                    .await
                    .context("signing s.accept")?;
                    accept_frame["sig"] = json!(accept_sig);
                    active.accept_replay = Some(ProviderSessionAcceptReplay {
                        open_head,
                        accept_frame: accept_frame.clone(),
                    });
                    sessions.insert(session_id.clone(), active);
                    protection.record_accept();
                    heartbeat_load.set_active_sessions(sessions.len());
                    record_provider_session_request_progress(
                        pending_requests,
                        &session_id,
                        Instant::now(),
                        request_stall_timeout,
                    );
                    match bridge
                        .session_send(&remote, &session_id, accept_frame)
                        .await
                    {
                        Ok(_) => provider_session_debug(format!(
                            "sent s.accept for session {session_id}"
                        )),
                        Err(err) => provider_session_debug(format!(
                            "s.accept for session {session_id} is cached for replay after transport reconnect: {err}"
                        )),
                    }
                }
                ProviderSessionDecision::Reject { code, reason } => {
                    provider_session_debug(format!(
                        "sending s.reject {code} for session {session_id}: {reason}"
                    ));
                    let reject_frame = json!({
                        "t": "s.reject",
                        "v": 1,
                        "expected_contract_version": terms.contract_version,
                        "session_id": session_id,
                        "code": code,
                        "reason": reason,
                        "retry_after_ms": 0,
                        "alt_rooms": [],
                    });
                    cache_provider_session_reject(
                        rejected_sessions,
                        session_id.clone(),
                        remote.clone(),
                        &frame,
                        reject_frame.clone(),
                        Instant::now() + request_stall_timeout,
                    )?;
                    bridge
                        .session_send(&remote, &session_id, reject_frame)
                        .await
                        .context("sending s.reject")?;
                    bridge
                        .session_close(&remote, &session_id)
                        .await
                        .context("reclaiming rejected provider session")?;
                    provider_session_debug(format!("sent s.reject for session {session_id}"));
                }
            }
        }
        "s.req_chunk" => {
            provider_session_debug(format!("handling s.req_chunk for session {session_id}"));
            let Some(active) = sessions.get(&session_id) else {
                provider_session_debug(format!(
                    "refusing s.req_chunk for unknown session {session_id} from {remote}"
                ));
                let _ = bridge.session_close(&remote, &session_id).await;
                return Ok(());
            };
            if active.remote != remote {
                provider_session_debug(format!(
                    "refusing cross-peer s.req_chunk for session {session_id} from {remote}"
                ));
                let _ = bridge.session_close(&remote, &session_id).await;
                return Ok(());
            }
            if !pending_requests.contains_key(&session_id) {
                provider_session_debug(format!(
                    "refusing s.req_chunk after request dispatch for session {session_id}"
                ));
                let _ = bridge.session_close(&remote, &session_id).await;
                return Ok(());
            }
            if let Err(err) = provider_session_collect_request_chunk(
                pending_payloads,
                &session_id,
                &frame,
                max_request_bytes,
                max_payload_chunks,
            ) {
                let request_id = provider_session_request_id(&frame);
                provider_session_debug(format!(
                    "request chunk failed for session {session_id}: {err:#}"
                ));
                send_provider_session_error(
                    bridge,
                    &remote,
                    &session_id,
                    &request_id,
                    "request_chunk_failed",
                    &err.to_string(),
                )
                .await?;
                send_provider_session_close(
                    bridge,
                    &remote,
                    &session_id,
                    "err:request_chunk_failed",
                )
                .await?;
                sessions.remove(&session_id);
                pending_requests.remove(&session_id);
                remove_provider_session_pending_payloads(pending_payloads, &session_id);
                heartbeat_load.set_active_sessions(sessions.len());
            } else {
                record_provider_session_request_progress(
                    pending_requests,
                    &session_id,
                    Instant::now(),
                    request_stall_timeout,
                );
            }
        }
        "s.req" => {
            provider_session_debug(format!("handling s.req for session {session_id}"));
            let Some(active) = sessions.get(&session_id).cloned() else {
                provider_session_debug(format!(
                    "refusing s.req for unknown session {session_id} from {remote}"
                ));
                let _ = bridge.session_close(&remote, &session_id).await;
                return Ok(());
            };
            if active.remote != remote {
                provider_session_debug(format!(
                    "refusing cross-peer s.req for session {session_id} from {remote}"
                ));
                let _ = bridge.session_close(&remote, &session_id).await;
                return Ok(());
            }
            if pending_requests.remove(&session_id).is_none() {
                provider_session_debug(format!(
                    "refusing duplicate s.req for session {session_id} from {remote}"
                ));
                let _ = bridge.session_close(&remote, &session_id).await;
                return Ok(());
            }
            let request_id = frame
                .get("rid")
                .and_then(Value::as_str)
                .filter(|rid| !rid.is_empty())
                .unwrap_or("missing-rid");
            let body = match provider_session_request_body_from_frame(
                pending_payloads,
                &session_id,
                &frame,
                max_request_bytes,
            ) {
                Ok(body) => body,
                Err(err) => {
                    provider_session_debug(format!(
                        "request reassembly failed for session {session_id}: {err:#}"
                    ));
                    send_provider_session_error(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        request_id,
                        "request_reassembly_failed",
                        &err.to_string(),
                    )
                    .await?;
                    send_provider_session_close(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        "err:request_reassembly_failed",
                    )
                    .await?;
                    sessions.remove(&session_id);
                    pending_requests.remove(&session_id);
                    remove_provider_session_pending_payloads(pending_payloads, &session_id);
                    heartbeat_load.set_active_sessions(sessions.len());
                    return Ok(());
                }
            };
            let modality_items = match validate_provider_session_request_modalities(
                &active, terms, &body,
            ) {
                Ok(items) => items,
                Err(err) => {
                    provider_session_debug(format!(
                            "request modality/capacity validation failed for session {session_id}: {err:#}"
                        ));
                    let error_code = provider_response_error_code(&err);
                    let error_message = provider_response_error_message(&err);
                    send_provider_session_error(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        request_id,
                        error_code,
                        &error_message,
                    )
                    .await?;
                    send_provider_session_close(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        &format!("err:{error_code}"),
                    )
                    .await?;
                    sessions.remove(&session_id);
                    pending_requests.remove(&session_id);
                    remove_provider_session_pending_payloads(pending_payloads, &session_id);
                    heartbeat_load.set_active_sessions(sessions.len());
                    return Ok(());
                }
            };
            provider_session_debug(format!(
                "building response for session {session_id} request {request_id}"
            ));
            let mut request_load = match heartbeat_load.begin_request(modality_items) {
                Ok(load) => load,
                Err(err) => {
                    send_provider_session_error(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        request_id,
                        "capacity",
                        &err.to_string(),
                    )
                    .await?;
                    send_provider_session_close(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        "err:capacity",
                    )
                    .await?;
                    sessions.remove(&session_id);
                    pending_requests.remove(&session_id);
                    remove_provider_session_pending_payloads(pending_payloads, &session_id);
                    heartbeat_load.set_active_sessions(sessions.len());
                    return Ok(());
                }
            };
            let request_started = request_load.started();
            let liveness = ProviderSessionLivenessMonitor::start(
                sc_bridge_url,
                sc_bridge_token,
                &active.session_id,
                &active.remote,
                bridge_operation_deadline,
            )
            .await
            .context("starting in-session provider peer liveness")?;
            let cancellation = liveness.cancellation();
            if provider_session_client_disconnect_requested(bridge, &active).await? {
                cancellation.cancel();
            }
            let mut live_stream = responder.supports_live_text_streaming().then(|| {
                ProviderSessionLiveStream::new(
                    bridge,
                    &active,
                    request_id,
                    terms,
                    &body,
                    runtime.runtime_keypair,
                    request_started,
                    heartbeat_load.clone(),
                    &cancellation,
                )
            });
            let response = contain_provider_request(|| {
                let mut output = responder.respond_streaming(
                    terms,
                    &body,
                    live_stream.as_mut(),
                    &cancellation,
                )?;
                normalize_provider_visible_output_usage(&body, &mut output)?;
                cancellation
                    .check()
                    .context("provider request cancelled before response publication")?;
                validate_provider_session_output(terms, &body, &output)?;
                Ok(output)
            });
            let (output, measured_throughput) = match response {
                Ok(output) => {
                    if live_stream
                        .as_ref()
                        .and_then(|stream| stream.first_ttft_ms())
                        .is_none()
                    {
                        heartbeat_load
                            .record_ttft_ms(duration_millis_u64(request_started.elapsed()));
                    }
                    let measured_throughput = provider_session_measured_throughput(
                        &output,
                        request_started.elapsed(),
                        live_stream
                            .as_ref()
                            .and_then(ProviderSessionLiveStream::measured_generation_tok_s),
                    );
                    if let Some(stream) = live_stream.as_mut() {
                        if let Err(err) = stream.finish() {
                            let err_text = format!("{err:#}");
                            if err_text.contains(PROVIDER_SESSION_CLIENT_DISCONNECT_ABORT) {
                                request_load.finish();
                                provider_session_debug(format!(
                                    "client disconnected during live flush after partial receipt for session {session_id} request {request_id}"
                                ));
                                sessions.remove(&session_id);
                                pending_requests.remove(&session_id);
                                remove_provider_session_pending_payloads(
                                    pending_payloads,
                                    &session_id,
                                );
                                heartbeat_load.set_active_sessions(sessions.len());
                                return Ok(());
                            }
                            provider_session_debug(format!(
                                "flushing live response failed for session {session_id}: {err_text}"
                            ));
                            send_provider_session_error(
                                bridge,
                                &active.remote,
                                &active.session_id,
                                request_id,
                                "provider_response_failed",
                                &err.to_string(),
                            )
                            .await?;
                            send_provider_session_close(
                                bridge,
                                &active.remote,
                                &active.session_id,
                                "err:provider_response_failed",
                            )
                            .await?;
                            sessions.remove(&session_id);
                            pending_requests.remove(&session_id);
                            remove_provider_session_pending_payloads(pending_payloads, &session_id);
                            heartbeat_load.set_active_sessions(sessions.len());
                            return Ok(());
                        }
                    }
                    (output, measured_throughput)
                }
                Err(err) => {
                    request_load.finish();
                    let err_text = format!("{err:#}");
                    if cancellation.is_cancelled()
                        && !err_text.contains(PROVIDER_SESSION_CLIENT_DISCONNECT_ABORT)
                    {
                        if let Some(reason) =
                            provider_engine_component_failure_after_cancel(responder, &err)
                        {
                            heartbeat_load.set_accepting_new(false);
                            provider_session_debug(format!(
                                "provider engine component stopped while cancelling session {session_id}; scheduling isolated reload: {reason}"
                            ));
                            engine_recovery.mark_failed(reason);
                        }
                        let (usage, usage_attribution, receipt_seq) = live_stream
                            .as_ref()
                            .map(|stream| stream.cancellation_receipt_state())
                            .unwrap_or_else(|| (ReceiptUsage::default(), BTreeMap::new(), 1));
                        match settle_cancelled_provider_session(
                            bridge,
                            &active,
                            request_id,
                            terms,
                            &body,
                            usage,
                            usage_attribution,
                            receipt_seq,
                            runtime.runtime_keypair,
                        )
                        .await
                        {
                            Ok(receipt) => {
                                protection.record_usage(
                                    &receipt.body.usage,
                                    receipt.body.au_owed_cum,
                                );
                            }
                            Err(settlement_error) => provider_session_debug(format!(
                                "client-disconnect settlement failed for session {session_id}: {settlement_error:#}"
                            )),
                        }
                        sessions.remove(&session_id);
                        pending_requests.remove(&session_id);
                        remove_provider_session_pending_payloads(pending_payloads, &session_id);
                        heartbeat_load.set_active_sessions(sessions.len());
                        return Ok(());
                    }
                    if let Some(reason) = provider_engine_component_failure(responder, &err) {
                        heartbeat_load.set_accepting_new(false);
                        provider_session_debug(format!(
                            "provider engine component failed during session {session_id}; scheduling isolated reload: {reason}"
                        ));
                        engine_recovery.mark_failed(reason);
                    }
                    if err_text.contains(PROVIDER_SESSION_CLIENT_DISCONNECT_ABORT) {
                        provider_session_debug(format!(
                            "client disconnected after partial receipt for session {session_id} request {request_id}"
                        ));
                        sessions.remove(&session_id);
                        pending_requests.remove(&session_id);
                        remove_provider_session_pending_payloads(pending_payloads, &session_id);
                        heartbeat_load.set_active_sessions(sessions.len());
                        return Ok(());
                    }
                    provider_session_debug(format!(
                        "response failed for session {session_id}: {err_text}"
                    ));
                    let error_code = provider_response_error_code(&err);
                    let error_message = provider_response_error_message(&err);
                    send_provider_session_error(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        request_id,
                        error_code,
                        &error_message,
                    )
                    .await?;
                    send_provider_session_close(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        &format!("err:{error_code}"),
                    )
                    .await?;
                    sessions.remove(&session_id);
                    pending_requests.remove(&session_id);
                    remove_provider_session_pending_payloads(pending_payloads, &session_id);
                    heartbeat_load.set_active_sessions(sessions.len());
                    return Ok(());
                }
            };
            let provider_quality = provider_session_quality_value(
                &output,
                request_started.elapsed(),
                live_stream
                    .as_ref()
                    .and_then(|stream| stream.first_ttft_ms()),
                measured_throughput,
            );
            let live_stream_state = live_stream.and_then(ProviderSessionLiveStream::into_state);
            provider_session_debug(format!(
                "sending response for session {session_id} request {request_id}"
            ));
            let receipt = match send_provider_session_output(
                bridge,
                &active,
                request_id,
                terms,
                &body,
                &output,
                runtime.runtime_keypair,
                live_stream_state,
                provider_quality,
                &cancellation,
            )
            .await
            {
                Ok(receipt) => receipt,
                Err(err) => {
                    provider_session_debug(format!(
                        "sending response failed for session {session_id}: {err:#}"
                    ));
                    send_provider_session_error(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        request_id,
                        "provider_send_failed",
                        &err.to_string(),
                    )
                    .await
                    .ok();
                    send_provider_session_close(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        "err:provider_send_failed",
                    )
                    .await
                    .ok();
                    sessions.remove(&session_id);
                    pending_requests.remove(&session_id);
                    remove_provider_session_pending_payloads(pending_payloads, &session_id);
                    heartbeat_load.set_active_sessions(sessions.len());
                    return Ok(());
                }
            };
            protection.record_usage(&receipt.body.usage, receipt.body.au_owed_cum);
            provider_session_debug(format!(
                "waiting for receipt ack on session {session_id} request {request_id}"
            ));
            if wait_for_provider_receipt_ack(
                bridge,
                &active,
                &receipt,
                provider_session_receipt_ack_timeout(&active),
                None,
            )
            .await
            .is_err()
            {
                provider_session_debug(format!(
                    "receipt ack timeout on session {session_id} request {request_id}"
                ));
                send_provider_session_close(
                    bridge,
                    &active.remote,
                    &active.session_id,
                    "err:receipt_ack",
                )
                .await?;
                sessions.remove(&session_id);
                pending_requests.remove(&session_id);
                remove_provider_session_pending_payloads(pending_payloads, &session_id);
                heartbeat_load.set_active_sessions(sessions.len());
                return Ok(());
            }
            if let Err(error) = liveness.stop().await {
                provider_session_debug(format!(
                    "provider session liveness monitor stopped after receipt ack with an error: {error:#}"
                ));
            }
            request_load.finish_with_output(measured_throughput);
            provider_session_debug(format!(
                "receipt ack received on session {session_id} request {request_id}"
            ));
            send_provider_session_close(bridge, &active.remote, &active.session_id, "done").await?;
            sessions.remove(&session_id);
            pending_requests.remove(&session_id);
            remove_provider_session_pending_payloads(pending_payloads, &session_id);
            heartbeat_load.set_active_sessions(sessions.len());
        }
        "s.close" => {
            let owns_session = sessions
                .get(&session_id)
                .is_some_and(|active| active.remote == remote);
            if owns_session {
                discard_provider_session_state(
                    sessions,
                    pending_requests,
                    pending_payloads,
                    &session_id,
                );
            }
            let _ = bridge.session_close(&remote, &session_id).await;
            heartbeat_load.set_active_sessions(sessions.len());
        }
        _ => {
            provider_session_debug(format!(
                "refusing unsupported provider session frame {frame_type} for {session_id} from {remote}"
            ));
            let owns_session = sessions
                .get(&session_id)
                .is_some_and(|active| active.remote == remote);
            if owns_session {
                discard_provider_session_state(
                    sessions,
                    pending_requests,
                    pending_payloads,
                    &session_id,
                );
                heartbeat_load.set_active_sessions(sessions.len());
            }
            let _ = bridge.session_close(&remote, &session_id).await;
        }
    }
    Ok(())
}

fn provider_session_event_belongs_to_process(
    event: &Value,
    sessions: &HashMap<String, ActiveProviderSession>,
    terms: &ProviderSessionTerms,
) -> bool {
    let Some(session_id) = event.get("session_id").and_then(Value::as_str) else {
        return false;
    };
    let Some(remote) = event.get("remote").and_then(Value::as_str) else {
        return false;
    };
    if sessions
        .get(session_id)
        .is_some_and(|active| active.remote == remote)
    {
        return true;
    }
    let Some(frame) = event.get("frame") else {
        return false;
    };
    match frame.get("t").and_then(Value::as_str) {
        Some("s.open") => provider_session_open_targets_enclave(frame, terms),
        Some(TPM_ACTIVATE_CREDENTIAL_CHALLENGE_FRAME_TYPE) => {
            frame.get("provider").and_then(Value::as_str) == Some(terms.provider.as_str())
                && frame.get("enclave_id").and_then(Value::as_str)
                    == Some(terms.enclave_id.as_str())
                && frame
                    .get("room_id")
                    .and_then(Value::as_str)
                    .is_some_and(|room_id| terms.room_ids.iter().any(|owned| owned == room_id))
        }
        _ => false,
    }
}

async fn open_provider_direct_session(
    bridge: &mut ScBridgeClient,
    remote: &str,
    session_id: &str,
) -> Result<()> {
    match bridge.session_open(remote, session_id).await {
        Ok(_) => Ok(()),
        Err(err) if provider_bridge_error_missing_direct_connection(&err) => {
            provider_session_debug(format!(
                "direct connection to {remote} disappeared while opening session {session_id}; reconnecting through the official DHT"
            ));
            bridge
                .peer_connect(remote, Duration::from_millis(DEFAULT_OPEN_TIMEOUT_MILLIS))
                .await
                .context("reconnecting provider to direct session peer")?;
            bridge
                .session_open(remote, session_id)
                .await
                .context("opening provider side direct session after reconnect")?;
            Ok(())
        }
        Err(err) => Err(err).context("opening provider side direct session"),
    }
}

fn provider_bridge_error_missing_direct_connection(error: &BridgeError) -> bool {
    error.to_string().contains("No direct connection")
}

#[derive(Clone, Copy, Debug)]
struct ProviderSessionLiveStreamState {
    next_index: u64,
    receipt_seq: u64,
    last_checkpoint_metered_units: u64,
    delivered_metered_units: u64,
    reasoning_units: u64,
    prompt_tokens: u64,
}

struct ProviderSessionLiveStream<'a> {
    bridge: &'a mut ScBridgeClient,
    active: &'a ActiveProviderSession,
    request_id: &'a str,
    terms: &'a ProviderSessionTerms,
    body: &'a Value,
    runtime_keypair: &'a RuntimeKeypair,
    request_started: Instant,
    heartbeat_load: ProviderHeartbeatLoad,
    cancellation: &'a CancellationToken,
    next_index: u64,
    receipt_seq: u64,
    last_checkpoint_metered_units: u64,
    first_ttft_ms: Option<u64>,
    first_token_at: Option<Instant>,
    last_token_at: Option<Instant>,
    generated_tokens: u64,
    delivered_metered_units: u64,
    prompt_tokens: u64,
    streamed_any: bool,
    pending_text: String,
    pending_hidden_reasoning: String,
    pending_token_ids: Vec<i32>,
    visible_text: String,
    hidden_reasoning: String,
}

const PROVIDER_REASONING_OPEN_TAG: &str = "<think>";
const PROVIDER_REASONING_CLOSE_TAG: &str = "</think>";

#[derive(Clone, Copy)]
struct ProviderReasoningDelimiters {
    open: &'static str,
    close: &'static str,
}

const PROVIDER_QWEN_REASONING_DELIMITERS: ProviderReasoningDelimiters =
    ProviderReasoningDelimiters {
        open: PROVIDER_REASONING_OPEN_TAG,
        close: PROVIDER_REASONING_CLOSE_TAG,
    };
const PROVIDER_GEMMA4_REASONING_DELIMITERS: ProviderReasoningDelimiters =
    ProviderReasoningDelimiters {
        open: gemma4::THOUGHT_OPEN,
        close: gemma4::THOUGHT_CLOSE,
    };

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ProviderReasoningOutputMode {
    Preserve,
    StripPrefilled,
    StripTagged,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ProviderReasoningStreamState {
    Preserve,
    Probe,
    Suppress,
    Boundary,
    Passthrough,
}

struct ProviderReasoningOutputFilter {
    state: ProviderReasoningStreamState,
    pending: String,
    delimiters: ProviderReasoningDelimiters,
}

#[derive(Default)]
struct ProviderReasoningFilteredText {
    visible: String,
    hidden: String,
}

impl ProviderReasoningFilteredText {
    fn extend(&mut self, next: Self) {
        self.visible.push_str(&next.visible);
        self.hidden.push_str(&next.hidden);
    }
}

impl ProviderReasoningOutputFilter {
    #[cfg(test)]
    fn new(mode: ProviderReasoningOutputMode) -> Self {
        Self::with_delimiters(mode, PROVIDER_QWEN_REASONING_DELIMITERS)
    }

    fn with_delimiters(
        mode: ProviderReasoningOutputMode,
        delimiters: ProviderReasoningDelimiters,
    ) -> Self {
        let state = match mode {
            ProviderReasoningOutputMode::Preserve => ProviderReasoningStreamState::Preserve,
            ProviderReasoningOutputMode::StripPrefilled => ProviderReasoningStreamState::Suppress,
            ProviderReasoningOutputMode::StripTagged => ProviderReasoningStreamState::Probe,
        };
        Self {
            state,
            pending: String::new(),
            delimiters,
        }
    }

    fn push_split(&mut self, text: &str) -> ProviderReasoningFilteredText {
        match self.state {
            ProviderReasoningStreamState::Preserve | ProviderReasoningStreamState::Passthrough => {
                ProviderReasoningFilteredText {
                    visible: text.to_owned(),
                    hidden: String::new(),
                }
            }
            ProviderReasoningStreamState::Probe => {
                self.pending.push_str(text);
                self.resolve_probe_split()
            }
            ProviderReasoningStreamState::Suppress => {
                self.pending.push_str(text);
                self.resolve_suppressed_split()
            }
            ProviderReasoningStreamState::Boundary => self.resolve_boundary_split(text),
        }
    }

    fn finish_split(&mut self) -> ProviderReasoningFilteredText {
        match self.state {
            ProviderReasoningStreamState::Probe => {
                let trimmed = self.pending.trim_start();
                if !trimmed.is_empty()
                    && (self.delimiters.open.starts_with(trimmed)
                        || self.delimiters.close.starts_with(trimmed))
                {
                    return ProviderReasoningFilteredText {
                        visible: String::new(),
                        hidden: std::mem::take(&mut self.pending),
                    };
                }
                self.state = ProviderReasoningStreamState::Passthrough;
                ProviderReasoningFilteredText {
                    visible: std::mem::take(&mut self.pending),
                    hidden: String::new(),
                }
            }
            ProviderReasoningStreamState::Suppress => ProviderReasoningFilteredText {
                visible: String::new(),
                hidden: std::mem::take(&mut self.pending),
            },
            ProviderReasoningStreamState::Preserve
            | ProviderReasoningStreamState::Boundary
            | ProviderReasoningStreamState::Passthrough => ProviderReasoningFilteredText::default(),
        }
    }

    fn resolve_probe_split(&mut self) -> ProviderReasoningFilteredText {
        let trimmed = self.pending.trim_start();
        if trimmed.is_empty()
            || self.delimiters.open.starts_with(trimmed)
            || self.delimiters.close.starts_with(trimmed)
        {
            return ProviderReasoningFilteredText::default();
        }
        if let Some(rest) = trimmed.strip_prefix(self.delimiters.open) {
            let consumed = self.pending.len() - rest.len();
            let hidden = self.pending[..consumed].to_owned();
            self.pending = rest.to_owned();
            self.state = ProviderReasoningStreamState::Suppress;
            let mut filtered = ProviderReasoningFilteredText {
                visible: String::new(),
                hidden,
            };
            filtered.extend(self.resolve_suppressed_split());
            return filtered;
        }
        if let Some(rest) = trimmed.strip_prefix(self.delimiters.close) {
            let consumed = self.pending.len() - rest.len();
            let hidden = self.pending[..consumed].to_owned();
            let rest = rest.to_owned();
            self.pending.clear();
            let mut filtered = ProviderReasoningFilteredText {
                visible: String::new(),
                hidden,
            };
            filtered.extend(self.resolve_boundary_split(&rest));
            return filtered;
        }
        self.state = ProviderReasoningStreamState::Passthrough;
        ProviderReasoningFilteredText {
            visible: std::mem::take(&mut self.pending),
            hidden: String::new(),
        }
    }

    fn resolve_suppressed_split(&mut self) -> ProviderReasoningFilteredText {
        if let Some(index) = self.pending.find(self.delimiters.close) {
            let hidden_end = index + self.delimiters.close.len();
            let hidden = self.pending[..hidden_end].to_owned();
            let rest = self.pending[hidden_end..].to_owned();
            self.pending.clear();
            let mut filtered = ProviderReasoningFilteredText {
                visible: String::new(),
                hidden,
            };
            filtered.extend(self.resolve_boundary_split(&rest));
            return filtered;
        }

        let retained = (1..self.delimiters.close.len())
            .rev()
            .find(|length| self.pending.ends_with(&self.delimiters.close[..*length]))
            .unwrap_or(0);
        let hidden_end = self.pending.len() - retained;
        let hidden = self.pending[..hidden_end].to_owned();
        let tail = self.pending[hidden_end..].to_owned();
        self.pending = tail;
        ProviderReasoningFilteredText {
            visible: String::new(),
            hidden,
        }
    }

    fn resolve_boundary_split(&mut self, text: &str) -> ProviderReasoningFilteredText {
        let visible = trim_provider_reasoning_boundary(text);
        let hidden = text[..text.len() - visible.len()].to_owned();
        if visible.is_empty() {
            self.state = ProviderReasoningStreamState::Boundary;
            ProviderReasoningFilteredText {
                visible: String::new(),
                hidden,
            }
        } else {
            self.state = ProviderReasoningStreamState::Passthrough;
            ProviderReasoningFilteredText {
                visible: visible.to_owned(),
                hidden,
            }
        }
    }
}

fn trim_provider_reasoning_boundary(text: &str) -> &str {
    text.trim_start_matches(|character| matches!(character, '\r' | '\n'))
}

const PROVIDER_SESSION_CLIENT_DISCONNECT_ABORT: &str =
    "provider live stream cancelled after client disconnect";
const PROVIDER_ENGINE_REQUEST_CANCELLED: &str = "engine request cancelled";

impl<'a> ProviderSessionLiveStream<'a> {
    fn new(
        bridge: &'a mut ScBridgeClient,
        active: &'a ActiveProviderSession,
        request_id: &'a str,
        terms: &'a ProviderSessionTerms,
        body: &'a Value,
        runtime_keypair: &'a RuntimeKeypair,
        request_started: Instant,
        heartbeat_load: ProviderHeartbeatLoad,
        cancellation: &'a CancellationToken,
    ) -> Self {
        Self {
            bridge,
            active,
            request_id,
            terms,
            body,
            runtime_keypair,
            request_started,
            heartbeat_load,
            cancellation,
            next_index: 0,
            receipt_seq: 1,
            last_checkpoint_metered_units: 0,
            first_ttft_ms: None,
            first_token_at: None,
            last_token_at: None,
            generated_tokens: 0,
            delivered_metered_units: 0,
            prompt_tokens: 0,
            streamed_any: false,
            pending_text: String::new(),
            pending_hidden_reasoning: String::new(),
            pending_token_ids: Vec::new(),
            visible_text: String::new(),
            hidden_reasoning: String::new(),
        }
    }

    fn on_token(
        &mut self,
        chunk: TokenChunk,
        hidden_reasoning: &str,
        prompt_tokens: u64,
    ) -> Result<()> {
        self.prompt_tokens = prompt_tokens;
        let token_at = Instant::now();
        if self.first_ttft_ms.is_none() {
            let ttft_ms = duration_millis_u64(self.request_started.elapsed()).max(1);
            self.first_ttft_ms = Some(ttft_ms);
            self.first_token_at = Some(token_at);
            self.heartbeat_load.record_ttft_ms(ttft_ms);
        }
        self.last_token_at = Some(token_at);
        provider_session_debug(format!(
            "live buffering token #{} for session {} request {}",
            self.generated_tokens, self.active.session_id, self.request_id
        ));
        self.pending_text.push_str(&chunk.text);
        self.pending_hidden_reasoning.push_str(hidden_reasoning);
        self.pending_token_ids.push(chunk.token_id);
        self.generated_tokens = self.generated_tokens.saturating_add(1);

        let checkpoint_due = provider_session_checkpoint_due(
            self.projected_metered_units(),
            u64::MAX,
            self.last_checkpoint_metered_units,
            provider_session_checkpoint_tokens(self.active),
        );
        if self.next_index == 0
            || u64::try_from(self.pending_token_ids.len()).unwrap_or(u64::MAX)
                >= provider_session_delta_batch_tokens()
            || checkpoint_due
        {
            self.flush_pending_delta()?;
        }

        if checkpoint_due {
            let usage = ReceiptUsage::text(prompt_tokens, self.delivered_metered_units);
            let usage_attribution = provider_reasoning_usage_attribution(&self.hidden_reasoning);
            let receipt = provider_session_receipt_for_usage_attribution(
                self.terms,
                self.active,
                self.body,
                usage,
                usage_attribution,
                self.receipt_seq,
                false,
                self.runtime_keypair,
            )
            .context("building live provider session checkpoint receipt")?;
            tokio::task::block_in_place(|| {
                tokio::runtime::Handle::current().block_on(async {
                    send_provider_session_receipt_frame(
                        self.bridge,
                        self.active,
                        self.request_id,
                        &receipt,
                        "checkpoint",
                    )
                    .await?;
                    wait_for_provider_receipt_ack(
                        self.bridge,
                        self.active,
                        &receipt,
                        provider_session_receipt_ack_timeout(self.active),
                        Some(self.cancellation),
                    )
                    .await
                    .context("waiting for live checkpoint receipt ack")
                })
            })?;
            self.last_checkpoint_metered_units = self.delivered_metered_units;
            self.receipt_seq = self.receipt_seq.saturating_add(1);
        }
        self.poll_client_disconnect()?;
        Ok(())
    }

    fn append_filtered_text(&mut self, filtered: ProviderReasoningFilteredText) {
        self.pending_text.push_str(&filtered.visible);
        self.pending_hidden_reasoning.push_str(&filtered.hidden);
    }

    fn projected_metered_units(&self) -> u64 {
        let bytes = self
            .visible_text
            .len()
            .saturating_add(self.hidden_reasoning.len())
            .saturating_add(self.pending_text.len())
            .saturating_add(self.pending_hidden_reasoning.len());
        if bytes == 0 {
            0
        } else {
            u64::try_from(bytes)
                .unwrap_or(u64::MAX)
                .div_ceil(VISIBLE_OUTPUT_BYTES_PER_UNIT)
        }
    }

    fn first_ttft_ms(&self) -> Option<u64> {
        self.first_ttft_ms
    }

    fn measured_generation_tok_s(&self) -> Option<f64> {
        let token_intervals = self.generated_tokens.checked_sub(1)?;
        if token_intervals == 0 {
            return None;
        }
        let elapsed = self
            .last_token_at?
            .checked_duration_since(self.first_token_at?)?;
        let elapsed_seconds = elapsed.as_secs_f64();
        if elapsed_seconds <= 0.0 {
            return None;
        }
        let tok_s = token_intervals as f64 / elapsed_seconds;
        (tok_s.is_finite() && tok_s > 0.0).then_some(tok_s)
    }

    fn cancellation_receipt_state(&self) -> (ReceiptUsage, BTreeMap<String, u64>, u64) {
        let usage = if self.last_checkpoint_metered_units == 0 {
            ReceiptUsage::default()
        } else {
            ReceiptUsage::text(self.prompt_tokens, self.last_checkpoint_metered_units)
        };
        let usage_attribution = if self.last_checkpoint_metered_units == 0 {
            BTreeMap::new()
        } else {
            provider_reasoning_usage_attribution(&self.hidden_reasoning)
        };
        (usage, usage_attribution, self.receipt_seq)
    }

    fn finish(&mut self) -> Result<()> {
        self.flush_pending_delta()?;
        self.poll_client_disconnect()
    }

    fn flush_pending_delta(&mut self) -> Result<()> {
        if self.pending_text.is_empty()
            && self.pending_hidden_reasoning.is_empty()
            && self.pending_token_ids.is_empty()
        {
            return Ok(());
        }
        provider_session_debug(format!(
            "live streaming s.delta #{} ({} token(s)) for session {} request {}",
            self.next_index,
            self.pending_token_ids.len(),
            self.active.session_id,
            self.request_id
        ));
        let frame = json!({
            "t": "s.delta",
            "rid": self.request_id,
            "i": self.next_index,
            "d": &self.pending_text,
            "reasoning_evidence_delta": &self.pending_hidden_reasoning,
            "token_ids_delta": &self.pending_token_ids,
            "tools": null,
            "fin": null,
        });
        tokio::task::block_in_place(|| {
            tokio::runtime::Handle::current().block_on(async {
                self.bridge
                    .session_send(&self.active.remote, &self.active.session_id, frame)
                    .await
                    .context("sending live token s.delta")
            })
        })?;
        self.visible_text.push_str(&self.pending_text);
        self.hidden_reasoning
            .push_str(&self.pending_hidden_reasoning);
        self.delivered_metered_units =
            metered_output_units(&self.visible_text, &self.hidden_reasoning, &[]);
        self.streamed_any = true;
        self.pending_text.clear();
        self.pending_hidden_reasoning.clear();
        self.pending_token_ids.clear();
        self.next_index = self.next_index.saturating_add(1);
        Ok(())
    }

    fn poll_client_disconnect(&mut self) -> Result<()> {
        let event = tokio::task::block_in_place(|| {
            tokio::runtime::Handle::current().block_on(async {
                self.bridge
                    .next_session_frame(Duration::from_millis(0))
                    .await
            })
        });
        let event = match event {
            Ok(event) => event,
            Err(BridgeError::Timeout) => return Ok(()),
            Err(err) => return Err(err).context("polling provider session close"),
        };
        if event.get("session_id").and_then(Value::as_str) != Some(self.active.session_id.as_str())
        {
            self.bridge
                .requeue_event_front(event)
                .context("requeueing unrelated provider session event")?;
            return Ok(());
        }
        if event.get("remote").and_then(Value::as_str) != Some(self.active.remote.as_str()) {
            if let Some(remote) = event.get("remote").and_then(Value::as_str) {
                let _ = tokio::task::block_in_place(|| {
                    tokio::runtime::Handle::current().block_on(async {
                        self.bridge
                            .session_close(remote, &self.active.session_id)
                            .await
                    })
                });
            }
            return Ok(());
        }
        let frame = event.get("frame").cloned().unwrap_or(Value::Null);
        if frame.get("t").and_then(Value::as_str) == Some("s.close")
            && frame.get("reason").and_then(Value::as_str) == Some("client_disconnect")
        {
            self.send_client_disconnect_receipt()?;
            bail!("{PROVIDER_SESSION_CLIENT_DISCONNECT_ABORT}");
        }
        self.bridge
            .requeue_event_front(event)
            .context("requeueing provider session event after disconnect poll")?;
        Ok(())
    }

    fn send_client_disconnect_receipt(&mut self) -> Result<()> {
        if self.delivered_metered_units == 0
            || self.delivered_metered_units == self.last_checkpoint_metered_units
        {
            return Ok(());
        }
        let usage = ReceiptUsage::text(self.prompt_tokens, self.delivered_metered_units);
        let usage_attribution = provider_reasoning_usage_attribution(&self.hidden_reasoning);
        let receipt = provider_session_receipt_for_usage_attribution(
            self.terms,
            self.active,
            self.body,
            usage,
            usage_attribution,
            self.receipt_seq,
            false,
            self.runtime_keypair,
        )
        .context("building client-disconnect provider session receipt")?;
        tokio::task::block_in_place(|| {
            tokio::runtime::Handle::current().block_on(async {
                send_provider_session_receipt_frame(
                    self.bridge,
                    self.active,
                    self.request_id,
                    &receipt,
                    "client_disconnect",
                )
                .await?;
                let _ = wait_for_provider_receipt_ack(
                    self.bridge,
                    self.active,
                    &receipt,
                    Duration::from_secs(5),
                    None,
                )
                .await;
                Ok::<(), anyhow::Error>(())
            })
        })?;
        self.last_checkpoint_metered_units = self.delivered_metered_units;
        self.receipt_seq = self.receipt_seq.saturating_add(1);
        Ok(())
    }

    fn into_state(self) -> Option<ProviderSessionLiveStreamState> {
        self.streamed_any.then_some(ProviderSessionLiveStreamState {
            next_index: self.next_index,
            receipt_seq: self.receipt_seq,
            last_checkpoint_metered_units: self.last_checkpoint_metered_units,
            delivered_metered_units: self.delivered_metered_units,
            reasoning_units: metered_output_units("", &self.hidden_reasoning, &[]),
            prompt_tokens: self.prompt_tokens,
        })
    }
}

async fn settle_cancelled_provider_session(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    request_id: &str,
    terms: &ProviderSessionTerms,
    body: &Value,
    usage: ReceiptUsage,
    usage_attribution: BTreeMap<String, u64>,
    receipt_seq: u64,
    runtime_keypair: &RuntimeKeypair,
) -> Result<ProviderSignedSessionReceipt> {
    let receipt = provider_cancelled_session_receipt(
        terms,
        active,
        body,
        usage,
        usage_attribution,
        receipt_seq,
        runtime_keypair,
    )
    .context("building cancelled provider session receipt")?;
    send_provider_session_receipt_frame(bridge, active, request_id, &receipt, "client_disconnect")
        .await?;
    wait_for_provider_receipt_ack(
        bridge,
        active,
        &receipt,
        provider_session_receipt_ack_timeout(active),
        None,
    )
    .await
    .context("waiting for cancelled provider session receipt ack")?;
    send_provider_session_close(
        bridge,
        &active.remote,
        &active.session_id,
        "client_disconnect_settled",
    )
    .await?;
    Ok(receipt)
}

fn provider_cancelled_session_receipt(
    terms: &ProviderSessionTerms,
    active: &ActiveProviderSession,
    body: &Value,
    metered_usage: ReceiptUsage,
    usage_attribution: BTreeMap<String, u64>,
    receipt_seq: u64,
    runtime_keypair: &RuntimeKeypair,
) -> Result<ProviderSignedSessionReceipt> {
    let usage = cancellation_settlement_usage(
        &active.locked_rate_map,
        active.locked_per_req_au,
        active.locked_min_session_au,
        &metered_usage,
    )
    .context(
        "admin-locked price schedule has no nonzero fixed fee or billable cancellation quantum",
    )?;
    provider_session_receipt_for_usage_attribution(
        terms,
        active,
        body,
        usage,
        usage_attribution,
        receipt_seq,
        true,
        runtime_keypair,
    )
}

async fn send_provider_session_output(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    request_id: &str,
    terms: &ProviderSessionTerms,
    body: &Value,
    output: &ProviderSessionOutput,
    runtime_keypair: &RuntimeKeypair,
    live_stream_state: Option<ProviderSessionLiveStreamState>,
    provider_quality: Value,
    cancellation: &CancellationToken,
) -> Result<ProviderSignedSessionReceipt> {
    cancellation
        .check()
        .context("provider response delivery cancelled before publication")?;
    let mut index = live_stream_state
        .as_ref()
        .map(|state| state.next_index)
        .unwrap_or(0);
    let mut receipt_seq = live_stream_state
        .as_ref()
        .map(|state| state.receipt_seq)
        .unwrap_or(1);
    let checkpoint_tokens = provider_session_checkpoint_tokens(active);
    let mut last_checkpoint_metered_units = live_stream_state
        .as_ref()
        .map(|state| state.last_checkpoint_metered_units)
        .unwrap_or(0);
    let mut token_ids_sent_in_deltas = live_stream_state.is_some();
    if live_stream_state.is_none() {
        let max_frame_bytes = provider_session_max_frame_bytes();
        let delta_bytes = provider_session_text_delta_bytes(max_frame_bytes);
        let parts = if output.tools.is_empty() {
            provider_stream_parts(&output.content, delta_bytes)
        } else {
            Vec::new()
        };
        let reasoning_parts = provider_stream_parts(&output.reasoning_evidence, delta_bytes);
        let token_part_count = output
            .token_ids
            .len()
            .div_ceil(PROVIDER_SESSION_MAX_TOKEN_IDS_PER_DELTA);
        let part_count = parts.len().max(reasoning_parts.len()).max(token_part_count);
        let mut delivered_metered_bytes = 0_u64;
        let mut delivered_reasoning_bytes = 0_u64;
        for part_index in 0..part_count {
            cancellation
                .check()
                .context("provider response delivery cancelled")?;
            let part = parts.get(part_index).copied().unwrap_or("");
            let reasoning_part = reasoning_parts.get(part_index).copied().unwrap_or("");
            provider_session_debug(format!(
                "sending content s.delta #{index} for session {} request {request_id}",
                active.session_id
            ));
            let token_ids_delta =
                provider_token_ids_delta_for_part(&output.token_ids, part_index, part_count);
            if !token_ids_delta.is_empty() {
                token_ids_sent_in_deltas = true;
            }
            let frame = provider_session_content_delta_frame(
                request_id,
                index,
                part,
                reasoning_part,
                token_ids_delta,
            );
            let frame_len = provider_session_frame_json_len(&frame)?;
            ensure!(
                frame_len <= max_frame_bytes,
                "content s.delta frame {frame_len} bytes exceeds session max {max_frame_bytes} bytes"
            );
            bridge
                .session_send(&active.remote, &active.session_id, frame)
                .await
                .context("sending content s.delta")?;
            cancellation
                .check()
                .context("provider response delivery cancelled")?;
            maybe_provider_session_delta_delay(&active.session_id, request_id, index).await;
            index = index.saturating_add(1);
            delivered_metered_bytes = delivered_metered_bytes
                .saturating_add(u64::try_from(part.len()).unwrap_or(u64::MAX))
                .saturating_add(u64::try_from(reasoning_part.len()).unwrap_or(u64::MAX));
            delivered_reasoning_bytes = delivered_reasoning_bytes
                .saturating_add(u64::try_from(reasoning_part.len()).unwrap_or(u64::MAX));
            let delivered_metered_units = if delivered_metered_bytes == 0 {
                0
            } else {
                delivered_metered_bytes.div_ceil(VISIBLE_OUTPUT_BYTES_PER_UNIT)
            };
            if provider_session_checkpoint_due(
                delivered_metered_units,
                output.usage.output_tokens(),
                last_checkpoint_metered_units,
                checkpoint_tokens,
            ) {
                let usage = ReceiptUsage::text(output.prompt_tokens, delivered_metered_units);
                let reasoning_units =
                    delivered_reasoning_bytes.div_ceil(VISIBLE_OUTPUT_BYTES_PER_UNIT);
                let usage_attribution = if reasoning_units == 0 {
                    BTreeMap::new()
                } else {
                    BTreeMap::from([("reasoning_output_tokens".to_owned(), reasoning_units)])
                };
                let receipt = provider_session_receipt_for_usage_attribution(
                    terms,
                    active,
                    body,
                    usage,
                    usage_attribution,
                    receipt_seq,
                    false,
                    runtime_keypair,
                )
                .context("building provider session checkpoint receipt")?;
                send_provider_session_receipt_frame(
                    bridge,
                    active,
                    request_id,
                    &receipt,
                    "checkpoint",
                )
                .await?;
                wait_for_provider_receipt_ack(
                    bridge,
                    active,
                    &receipt,
                    provider_session_receipt_ack_timeout(active),
                    Some(cancellation),
                )
                .await
                .context("waiting for checkpoint receipt ack")?;
                last_checkpoint_metered_units = delivered_metered_units;
                receipt_seq = receipt_seq.saturating_add(1);
            }
        }
    }

    index = send_provider_session_artifacts(
        bridge,
        active,
        request_id,
        index,
        &output.artifacts,
        provider_session_max_frame_bytes(),
        cancellation,
    )
    .await?;

    if let Some(state) = &live_stream_state {
        send_provider_client_disconnect_receipt_if_requested(
            bridge,
            active,
            request_id,
            terms,
            body,
            state,
            runtime_keypair,
        )
        .await?;
    }

    send_provider_session_final_output_frames(
        bridge,
        active,
        request_id,
        index,
        output,
        token_ids_sent_in_deltas,
        &provider_quality,
        provider_session_max_frame_bytes(),
        cancellation,
    )
    .await?;

    let receipt = provider_session_receipt_for_usage_attribution(
        terms,
        active,
        body,
        output.usage.clone(),
        output.usage_attribution.clone(),
        receipt_seq,
        true,
        runtime_keypair,
    )
    .context("building provider session receipt")?;
    send_provider_session_receipt_frame(bridge, active, request_id, &receipt, "final").await?;
    Ok(receipt)
}

async fn send_provider_client_disconnect_receipt_if_requested(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    request_id: &str,
    terms: &ProviderSessionTerms,
    body: &Value,
    state: &ProviderSessionLiveStreamState,
    runtime_keypair: &RuntimeKeypair,
) -> Result<()> {
    if !provider_session_client_disconnect_requested(bridge, active).await? {
        return Ok(());
    }
    if state.delivered_metered_units > 0
        && state.delivered_metered_units != state.last_checkpoint_metered_units
    {
        let usage = ReceiptUsage::text(state.prompt_tokens, state.delivered_metered_units);
        let usage_attribution = if state.reasoning_units == 0 {
            BTreeMap::new()
        } else {
            BTreeMap::from([("reasoning_output_tokens".to_owned(), state.reasoning_units)])
        };
        let receipt = provider_session_receipt_for_usage_attribution(
            terms,
            active,
            body,
            usage,
            usage_attribution,
            state.receipt_seq,
            false,
            runtime_keypair,
        )
        .context("building client-disconnect provider session receipt")?;
        send_provider_session_receipt_frame(
            bridge,
            active,
            request_id,
            &receipt,
            "client_disconnect",
        )
        .await?;
        let _ =
            wait_for_provider_receipt_ack(bridge, active, &receipt, Duration::from_secs(5), None)
                .await;
    }
    bail!("{PROVIDER_SESSION_CLIENT_DISCONNECT_ABORT}");
}

async fn provider_session_client_disconnect_requested(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
) -> Result<bool> {
    let event = match bridge.next_session_frame(Duration::from_millis(25)).await {
        Ok(event) => event,
        Err(BridgeError::Timeout) => return Ok(false),
        Err(err) => return Err(err).context("polling provider session close before final receipt"),
    };
    if event.get("session_id").and_then(Value::as_str) != Some(active.session_id.as_str()) {
        bridge
            .requeue_event_front(event)
            .context("requeueing unrelated provider session event")?;
        return Ok(false);
    }
    if event.get("remote").and_then(Value::as_str) != Some(active.remote.as_str()) {
        if let Some(remote) = event.get("remote").and_then(Value::as_str) {
            let _ = bridge.session_close(remote, &active.session_id).await;
        }
        return Ok(false);
    }
    let frame = event.get("frame").cloned().unwrap_or(Value::Null);
    if frame.get("t").and_then(Value::as_str) == Some("s.close")
        && frame.get("reason").and_then(Value::as_str) == Some("client_disconnect")
    {
        return Ok(true);
    }
    bridge
        .requeue_event_front(event)
        .context("requeueing provider session event after disconnect poll")?;
    Ok(false)
}

fn provider_session_checkpoint_tokens(active: &ActiveProviderSession) -> u64 {
    active.checkpoint_every.tokens.max(1)
}

fn provider_session_delta_batch_tokens() -> u64 {
    std::env::var("MAYHEM_PROVIDER_SESSION_DELTA_BATCH_TOKENS")
        .ok()
        .and_then(|raw| raw.parse::<u64>().ok())
        .filter(|tokens| *tokens > 0)
        .unwrap_or(8)
}

fn provider_session_max_frame_bytes() -> usize {
    std::env::var("MAYHEM_SESSION_MAX_FRAME_BYTES")
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|value| *value >= 8 * 1024)
        .unwrap_or(DEFAULT_SESSION_MAX_FRAME_BYTES)
}

fn provider_session_payload_chunk_bytes(max_frame_bytes: usize) -> usize {
    let safe_raw = max_frame_bytes.saturating_sub(4096) / 2;
    (64 * 1024).min(safe_raw.max(1024))
}

fn provider_session_text_delta_bytes(max_frame_bytes: usize) -> usize {
    let worst_case_json_text = max_frame_bytes.saturating_sub(4096) / 6;
    DEFAULT_SESSION_PAYLOAD_CHUNK_BYTES.min(worst_case_json_text.max(1024))
}

fn provider_session_frame_json_len(frame: &Value) -> Result<usize> {
    provider_session_serialized_len(frame)
}

fn provider_session_serialized_len<T: Serialize>(value: &T) -> Result<usize> {
    let mut counter = JsonLengthWriter::default();
    serde_json::to_writer(&mut counter, value).context("serializing provider session JSON")?;
    Ok(counter.len)
}

#[derive(Default)]
struct JsonLengthWriter {
    len: usize,
}

impl Write for JsonLengthWriter {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        self.len = self
            .len
            .checked_add(bytes.len())
            .ok_or_else(|| io::Error::other("JSON length overflow"))?;
        Ok(bytes.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

async fn send_provider_session_final_output_frames(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    request_id: &str,
    start_index: u64,
    output: &ProviderSessionOutput,
    token_ids_sent_in_deltas: bool,
    provider_quality: &Value,
    max_frame_bytes: usize,
    cancellation: &CancellationToken,
) -> Result<()> {
    cancellation
        .check()
        .context("provider final output delivery cancelled")?;
    let mut next_index = start_index;
    let mut final_frame = json!({
        "t": "s.delta",
        "rid": request_id,
        "i": next_index,
        "d": "",
        "tools": null,
        "embeddings": null,
        "transcription": null,
        "fin": output.finish_reason,
        "usage": output.usage,
        "usage_attribution": output.usage_attribution,
        "quality": provider_quality,
        "token_ids": null,
        "reasoning_evidence_delta": "",
        "artifacts": provider_session_artifact_summaries(&output.artifacts),
    });
    if !output.tools.is_empty() {
        attach_or_stream_provider_delta_field(
            bridge,
            active,
            request_id,
            &mut final_frame,
            "tools",
            serde_json::to_value(&output.tools).context("serializing provider tool outputs")?,
            &mut next_index,
            max_frame_bytes,
            cancellation,
        )
        .await?;
    }
    if let Some(embeddings) = &output.embeddings {
        attach_or_stream_provider_delta_field(
            bridge,
            active,
            request_id,
            &mut final_frame,
            "embeddings",
            serde_json::to_value(embeddings).context("serializing provider embeddings")?,
            &mut next_index,
            max_frame_bytes,
            cancellation,
        )
        .await?;
    }
    if let Some(transcription) = &output.transcription {
        attach_or_stream_provider_delta_field(
            bridge,
            active,
            request_id,
            &mut final_frame,
            "transcription",
            serde_json::to_value(transcription)
                .context("serializing provider transcription output")?,
            &mut next_index,
            max_frame_bytes,
            cancellation,
        )
        .await?;
    }
    if !token_ids_sent_in_deltas {
        attach_or_stream_provider_delta_field(
            bridge,
            active,
            request_id,
            &mut final_frame,
            "token_ids",
            serde_json::to_value(&output.token_ids).context("serializing provider token ids")?,
            &mut next_index,
            max_frame_bytes,
            cancellation,
        )
        .await?;
    }
    final_frame["i"] = json!(next_index);
    let final_len = provider_session_frame_json_len(&final_frame)?;
    ensure!(
        final_len <= max_frame_bytes,
        "final provider s.delta frame {final_len} bytes exceeds session max {max_frame_bytes} bytes after streaming large fields"
    );
    provider_session_debug(format!(
        "sending final s.delta #{next_index} for session {} request {request_id}",
        active.session_id
    ));
    bridge
        .session_send(&active.remote, &active.session_id, final_frame)
        .await
        .context("sending final response frame")?;
    Ok(())
}

async fn attach_or_stream_provider_delta_field(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    request_id: &str,
    final_frame: &mut Value,
    field: &'static str,
    value: Value,
    next_index: &mut u64,
    max_frame_bytes: usize,
    cancellation: &CancellationToken,
) -> Result<()> {
    cancellation
        .check()
        .context("provider structured output delivery cancelled")?;
    final_frame[field] = value;
    if provider_session_frame_json_len(final_frame)? <= max_frame_bytes {
        return Ok(());
    }
    let value = final_frame
        .as_object_mut()
        .context("final provider s.delta frame must be an object")?
        .insert(field.to_owned(), Value::Null)
        .context("provider session field disappeared while chunking")?;
    let bytes = stable_json_bytes(&value)
        .with_context(|| format!("serializing provider session {field} field"))?;
    let chunk_size = provider_session_payload_chunk_bytes(max_frame_bytes);
    let manifest = payload_chunk_manifest(&bytes, chunk_size)
        .map_err(|err| anyhow::anyhow!("planning provider session {field} chunks failed: {err}"))?;
    for chunk_index in 0..manifest.chunk_count {
        cancellation
            .check()
            .context("provider structured output delivery cancelled")?;
        let chunk = payload_chunk_at(&bytes, chunk_size, chunk_index)
            .map_err(|err| {
                anyhow::anyhow!("building provider session {field} chunk failed: {err}")
            })?
            .context("planned provider session payload chunk was missing")?;
        let frame = json!({
            "t": "s.delta_chunk",
            "v": 1,
            "rid": request_id,
            "i": *next_index,
            "field": field,
            "payload_id": manifest.blake3,
            "chunk": chunk,
        });
        let len = provider_session_frame_json_len(&frame)?;
        ensure!(
            len <= max_frame_bytes,
            "chunked provider s.delta {field} frame {len} bytes exceeds session max {max_frame_bytes} bytes"
        );
        bridge
            .session_send(&active.remote, &active.session_id, frame)
            .await
            .with_context(|| format!("sending provider session {field} chunk"))?;
        cancellation
            .check()
            .context("provider structured output delivery cancelled")?;
        *next_index = next_index
            .checked_add(1)
            .context("provider delta index overflow")?;
    }
    let object = final_frame
        .as_object_mut()
        .context("final provider s.delta frame must be an object")?;
    object.insert(format!("{field}_ref"), json!(manifest));
    ensure!(
        provider_session_frame_json_len(final_frame)? <= max_frame_bytes,
        "provider session {field} manifest does not fit the session frame limit"
    );
    Ok(())
}

#[cfg(test)]
fn provider_session_final_delta_frames(
    request_id: &str,
    start_index: u64,
    output: &ProviderSessionOutput,
    token_ids_sent_in_deltas: bool,
    provider_quality: &Value,
    max_frame_bytes: usize,
) -> Result<Vec<Value>> {
    let mut final_frame = json!({
        "t": "s.delta",
        "rid": request_id,
        "i": start_index,
        "d": "",
        "tools": (!output.tools.is_empty()).then_some(&output.tools),
        "embeddings": output.embeddings.as_ref(),
        "transcription": output.transcription.as_ref(),
        "fin": output.finish_reason,
        "usage": output.usage,
        "quality": provider_quality,
        "token_ids": (!token_ids_sent_in_deltas).then_some(&output.token_ids),
        "reasoning_evidence_delta": "",
        "artifacts": provider_session_artifact_summaries(&output.artifacts),
    });
    if provider_session_frame_json_len(&final_frame)? <= max_frame_bytes {
        return Ok(vec![final_frame]);
    }

    let mut frames = Vec::new();
    let mut next_index = start_index;
    if !output.tools.is_empty() {
        provider_session_add_delta_ref_frames(
            &mut frames,
            &mut final_frame,
            request_id,
            "tools",
            json!(output.tools),
            &mut next_index,
            max_frame_bytes,
        )?;
    }
    if let Some(embeddings) = &output.embeddings {
        provider_session_add_delta_ref_frames(
            &mut frames,
            &mut final_frame,
            request_id,
            "embeddings",
            json!(embeddings),
            &mut next_index,
            max_frame_bytes,
        )?;
    }
    if let Some(transcription) = &output.transcription {
        provider_session_add_delta_ref_frames(
            &mut frames,
            &mut final_frame,
            request_id,
            "transcription",
            json!(transcription),
            &mut next_index,
            max_frame_bytes,
        )?;
    }
    if !token_ids_sent_in_deltas && !output.token_ids.is_empty() {
        provider_session_add_delta_ref_frames(
            &mut frames,
            &mut final_frame,
            request_id,
            "token_ids",
            json!(output.token_ids),
            &mut next_index,
            max_frame_bytes,
        )?;
    }
    final_frame["i"] = json!(next_index);
    let final_len = provider_session_frame_json_len(&final_frame)?;
    if final_len > max_frame_bytes {
        bail!(
            "final provider s.delta frame {final_len} bytes exceeds session max {max_frame_bytes} bytes after chunking large fields"
        );
    }
    frames.push(final_frame);
    Ok(frames)
}

#[cfg(test)]
fn provider_session_add_delta_ref_frames(
    frames: &mut Vec<Value>,
    final_frame: &mut Value,
    request_id: &str,
    field: &'static str,
    value: Value,
    next_index: &mut u64,
    max_frame_bytes: usize,
) -> Result<()> {
    let (manifest, chunks) = chunk_json_payload(
        &value,
        provider_session_payload_chunk_bytes(max_frame_bytes),
    )
    .with_context(|| format!("chunking provider session {field} field"))?;
    let payload_id = manifest.blake3.clone();
    for chunk in chunks {
        let frame = json!({
            "t": "s.delta_chunk",
            "v": 1,
            "rid": request_id,
            "i": *next_index,
            "field": field,
            "payload_id": payload_id.clone(),
            "chunk": chunk,
        });
        let len = provider_session_frame_json_len(&frame)?;
        if len > max_frame_bytes {
            bail!(
                "chunked provider s.delta {field} frame {len} bytes exceeds session max {max_frame_bytes} bytes"
            );
        }
        frames.push(frame);
        *next_index = next_index.saturating_add(1);
    }
    let object = final_frame
        .as_object_mut()
        .context("final provider s.delta frame must be an object")?;
    object.insert(field.to_owned(), Value::Null);
    object.insert(format!("{field}_ref"), json!(manifest));
    Ok(())
}

fn provider_session_receipt_ack_timeout(active: &ActiveProviderSession) -> Duration {
    Duration::from_millis(
        active
            .checkpoint_every
            .ms
            .saturating_add(5_000)
            .max(120_000),
    )
}

fn provider_session_checkpoint_due(
    delivered_tokens: u64,
    total_completion_tokens: u64,
    last_checkpoint_tokens: u64,
    checkpoint_tokens: u64,
) -> bool {
    delivered_tokens > 0
        && delivered_tokens < total_completion_tokens
        && delivered_tokens.saturating_sub(last_checkpoint_tokens) >= checkpoint_tokens
}

fn provider_session_content_delta_frame(
    request_id: &str,
    index: u64,
    part: &str,
    reasoning_evidence_delta: &str,
    token_ids_delta: &[i32],
) -> Value {
    json!({
        "t": "s.delta",
        "rid": request_id,
        "i": index,
        "d": part,
        "reasoning_evidence_delta": reasoning_evidence_delta,
        "token_ids_delta": token_ids_delta,
        "tools": null,
        "fin": null,
    })
}

fn provider_token_ids_delta_for_part<'a>(
    token_ids: &'a [i32],
    part_index: usize,
    part_count: usize,
) -> &'a [i32] {
    if token_ids.is_empty() || part_count == 0 {
        return &[];
    }
    let start = part_index.saturating_mul(token_ids.len()) / part_count;
    let end = part_index.saturating_add(1).saturating_mul(token_ids.len()) / part_count;
    &token_ids[start.min(token_ids.len())..end.min(token_ids.len())]
}

async fn send_provider_session_receipt_frame(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    request_id: &str,
    receipt: &ProviderSignedSessionReceipt,
    kind: &str,
) -> Result<()> {
    provider_session_debug(format!(
        "sending {kind} s.receipt seq {} for session {} request {request_id}",
        receipt.body.seq, active.session_id
    ));
    bridge
        .session_send(
            &active.remote,
            &active.session_id,
            json!({
                "t": "s.receipt",
                "v": 1,
                "session_id": &active.session_id,
                "seq": receipt.body.seq,
                "receipt": receipt,
            }),
        )
        .await
        .context("sending s.receipt")?;
    Ok(())
}

async fn send_provider_session_artifacts(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    request_id: &str,
    start_index: u64,
    artifacts: &[ProviderSessionArtifact],
    max_frame_bytes: usize,
    cancellation: &CancellationToken,
) -> Result<u64> {
    let mut index = start_index;
    for artifact in artifacts {
        cancellation
            .check()
            .context("provider artifact delivery cancelled")?;
        let digest = blake3_bytes_hex(&artifact.bytes);
        if artifact.bytes.is_empty() {
            let frame = provider_session_artifact_delta_frame(
                request_id,
                index,
                artifact,
                &digest,
                0,
                &[],
                true,
            );
            send_provider_session_artifact_frame(
                bridge,
                active,
                request_id,
                frame,
                max_frame_bytes,
            )
            .await?;
            cancellation
                .check()
                .context("provider artifact delivery cancelled")?;
            index = index
                .checked_add(1)
                .context("artifact delta index overflow")?;
            continue;
        }
        for (chunk_index, chunk) in artifact
            .bytes
            .chunks(PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE)
            .enumerate()
        {
            cancellation
                .check()
                .context("provider artifact delivery cancelled")?;
            let offset = chunk_index
                .checked_mul(PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE)
                .context("artifact chunk offset overflow")?;
            let final_chunk = offset.saturating_add(chunk.len()) >= artifact.bytes.len();
            let frame = provider_session_artifact_delta_frame(
                request_id,
                index,
                artifact,
                &digest,
                offset,
                chunk,
                final_chunk,
            );
            send_provider_session_artifact_frame(
                bridge,
                active,
                request_id,
                frame,
                max_frame_bytes,
            )
            .await?;
            cancellation
                .check()
                .context("provider artifact delivery cancelled")?;
            index = index
                .checked_add(1)
                .context("artifact delta index overflow")?;
        }
    }
    Ok(index)
}

async fn send_provider_session_artifact_frame(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    request_id: &str,
    frame: Value,
    max_frame_bytes: usize,
) -> Result<()> {
    let index = frame.get("i").and_then(Value::as_u64).unwrap_or(0);
    let frame_len = provider_session_frame_json_len(&frame)?;
    ensure!(
        frame_len <= max_frame_bytes,
        "artifact s.delta frame {frame_len} bytes exceeds session max {max_frame_bytes} bytes"
    );
    provider_session_debug(format!(
        "sending artifact s.delta #{index} for session {} request {request_id}",
        active.session_id,
    ));
    bridge
        .session_send(&active.remote, &active.session_id, frame)
        .await
        .context("sending artifact s.delta")?;
    Ok(())
}

#[cfg(test)]
fn provider_session_artifact_delta_frames(
    request_id: &str,
    start_index: u64,
    artifacts: &[ProviderSessionArtifact],
) -> Vec<Value> {
    let mut frames = Vec::new();
    let mut index = start_index;
    for artifact in artifacts {
        let total_len = artifact.bytes.len();
        let digest = blake3_bytes_hex(&artifact.bytes);
        if artifact.bytes.is_empty() {
            frames.push(provider_session_artifact_delta_frame(
                request_id,
                index,
                artifact,
                &digest,
                0,
                &[],
                true,
            ));
            index = index.saturating_add(1);
            continue;
        }
        for (chunk_index, chunk) in artifact
            .bytes
            .chunks(PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE)
            .enumerate()
        {
            let offset = chunk_index * PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE;
            let final_chunk = offset + chunk.len() >= total_len;
            frames.push(provider_session_artifact_delta_frame(
                request_id,
                index,
                artifact,
                &digest,
                offset,
                chunk,
                final_chunk,
            ));
            index = index.saturating_add(1);
        }
    }
    frames
}

fn provider_session_artifact_delta_frame(
    request_id: &str,
    index: u64,
    artifact: &ProviderSessionArtifact,
    digest: &str,
    offset: usize,
    chunk: &[u8],
    final_chunk: bool,
) -> Value {
    json!({
        "t": "s.delta",
        "rid": request_id,
        "i": index,
        "d": "",
        "reasoning_evidence_delta": "",
        "tools": null,
        "fin": null,
        "artifact": {
            "id": artifact.id,
            "content_type": artifact.content_type,
            "encoding": "hex",
            "offset": offset,
            "len": chunk.len(),
            "total_len": artifact.bytes.len(),
            "blake3": digest,
            "data": hex_encode(chunk),
            "final": final_chunk,
        },
    })
}

fn provider_session_artifact_summaries(artifacts: &[ProviderSessionArtifact]) -> Vec<Value> {
    artifacts
        .iter()
        .map(|artifact| {
            json!({
                "id": artifact.id,
                "content_type": artifact.content_type,
                "bytes": artifact.bytes.len(),
                "blake3": blake3_bytes_hex(&artifact.bytes),
            })
        })
        .collect()
}

async fn maybe_provider_session_delta_delay(session_id: &str, request_id: &str, index: u64) {
    let Some(delay) = provider_session_delta_delay() else {
        return;
    };
    if index >= provider_session_delta_delay_count() {
        return;
    }
    provider_session_debug(format!(
        "delaying after content s.delta #{index} for session {session_id} request {request_id} by {}ms",
        delay.as_millis()
    ));
    tokio::time::sleep(delay).await;
}

fn provider_session_delta_delay() -> Option<Duration> {
    let millis = std::env::var("MAYHEM_PROVIDER_SESSION_DELTA_DELAY_MS")
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .unwrap_or(0);
    (millis > 0).then(|| Duration::from_millis(millis.min(60_000)))
}

fn provider_session_delta_delay_count() -> u64 {
    std::env::var("MAYHEM_PROVIDER_SESSION_DELTA_DELAY_COUNT")
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .unwrap_or(1)
}

async fn send_provider_session_error(
    bridge: &mut ScBridgeClient,
    remote: &str,
    session_id: &str,
    request_id: &str,
    code: &str,
    message: &str,
) -> Result<()> {
    bridge
        .session_send(
            remote,
            session_id,
            json!({
                "t": "s.error",
                "v": 1,
                "session_id": session_id,
                "rid": request_id,
                "code": code,
                "message": message,
            }),
        )
        .await
        .with_context(|| format!("sending s.error for {session_id}"))?;
    Ok(())
}

async fn provider_receipt_settlement_feature(
    settlement: &ProviderReceiptSettlement,
    receipt: &ProviderSignedSessionReceipt,
    receipt_ack: &ReceiptAck,
) -> Result<Value> {
    let receipt = SessionReceipt {
        body: receipt.body.clone(),
        enclave_sig: receipt.enclave_sig.clone(),
        enclave_pubkey: settlement.enclave_pubkey.clone(),
        user_sig: receipt_ack.user_sig.clone(),
    };
    let key = record_usage_receipt_feature_key(&receipt);
    let receipt_envelope = record_usage_receipt_envelope(&receipt);
    let mut value = json!({
        "op": "record_usage_receipt",
        "contract_version": CONTRACT_VERSION,
        "epoch": receipt.body.billing_epoch,
        "payout_revision": receipt.body.payout_revision,
        "receipt": receipt_envelope,
    });
    let signing_bytes = record_usage_receipt_signing_bytes(&key, &value)
        .context("building provider receipt settlement signature payload")?;
    let provider_signature = sign_hex(
        &settlement.keypair_path,
        &settlement.password,
        &hex_encode(&signing_bytes),
    )
    .await
    .context("signing provider receipt settlement")?;
    value["provider_sig"] = json!(provider_signature);
    let feature = json!({
        "feature": "mayhem",
        "key": key,
        "value": value,
    });
    validate_receipt_settlement_feature(&feature)?;
    Ok(feature)
}

async fn queue_and_send_provider_receipt_settlement(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    receipt: &ProviderSignedSessionReceipt,
    receipt_ack: &ReceiptAck,
) -> Result<()> {
    let settlement = active
        .receipt_settlement
        .as_ref()
        .context("provider receipt settlement outbox is not configured")?;
    let feature = provider_receipt_settlement_feature(settlement, receipt, receipt_ack).await?;
    settlement
        .outbox
        .persist(&feature)
        .context("durably queueing provider receipt settlement")?;
    let frame = json!({
        "t": "s.receipt_settlement",
        "v": 1,
        "session_id": &active.session_id,
        "seq": receipt.body.seq,
        "feature": feature,
    });
    ensure!(
        serde_json::to_vec(&frame)?.len() <= DEFAULT_SESSION_MAX_FRAME_BYTES,
        "signed receipt settlement exceeds the bounded direct-session frame size"
    );
    bridge
        .session_send(&active.remote, &active.session_id, frame)
        .await
        .context("sending durable provider receipt settlement to buyer")
        .map(|_| ())
}

async fn wait_for_provider_receipt_ack(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    receipt: &ProviderSignedSessionReceipt,
    wait: Duration,
    cancellation: Option<&CancellationToken>,
) -> Result<ReceiptAck> {
    let deadline = Instant::now() + wait;
    loop {
        if let Some(cancellation) = cancellation {
            cancellation
                .check()
                .context("provider receipt acknowledgement wait cancelled")?;
        }
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            bail!(
                "timed out waiting for s.receipt_ack on {}",
                active.session_id
            );
        }
        let poll_wait = if cancellation.is_some() {
            remaining.min(Duration::from_millis(250))
        } else {
            remaining
        };
        match bridge
            .next_session_frame_for(&active.session_id, Some(poll_wait))
            .await
        {
            Ok(event) => {
                if event.get("remote").and_then(Value::as_str) != Some(active.remote.as_str()) {
                    if let Some(remote) = event.get("remote").and_then(Value::as_str) {
                        let _ = bridge.session_close(remote, &active.session_id).await;
                    }
                    continue;
                }
                let frame = event.get("frame").cloned().unwrap_or(Value::Null);
                match frame.get("t").and_then(Value::as_str) {
                    Some("s.receipt_ack") => {
                        let ack_seq = provider_session_receipt_ack_seq(&frame)?;
                        if ack_seq < receipt.body.seq {
                            provider_session_debug(format!(
                                "ignoring stale receipt ack seq {ack_seq} while waiting for seq {} on session {}",
                                receipt.body.seq, active.session_id
                            ));
                            continue;
                        }
                        let receipt_ack =
                            provider_session_receipt_ack_from_frame(&frame, active, receipt)?;
                        if active.receipt_settlement.is_some() {
                            queue_and_send_provider_receipt_settlement(
                                bridge,
                                active,
                                receipt,
                                &receipt_ack,
                            )
                            .await?;
                        }
                        return Ok(receipt_ack);
                    }
                    Some("s.close") => {
                        bail!("session {} closed before s.receipt_ack", active.session_id);
                    }
                    _ => {}
                }
            }
            Err(BridgeError::Timeout) => {
                if cancellation.is_some() && Instant::now() < deadline {
                    continue;
                }
                bail!(
                    "timed out waiting for s.receipt_ack on {}",
                    active.session_id
                );
            }
            Err(err) => return Err(err).context("reading s.receipt_ack"),
        }
    }
}

fn provider_session_receipt_ack_seq(frame: &Value) -> Result<u64> {
    frame
        .get("seq")
        .and_then(Value::as_u64)
        .context("receipt ack missing seq")
}

fn provider_session_receipt_ack_from_frame(
    frame: &Value,
    active: &ActiveProviderSession,
    receipt: &ProviderSignedSessionReceipt,
) -> Result<ReceiptAck> {
    if frame.get("t").and_then(Value::as_str) != Some("s.receipt_ack") {
        bail!("receipt ack frame must have t=s.receipt_ack");
    }
    if frame.get("session_id").and_then(Value::as_str) != Some(active.session_id.as_str()) {
        bail!("receipt ack session_id mismatch");
    }
    let ack = ReceiptAck {
        session_id: active.session_id.clone(),
        seq: provider_session_receipt_ack_seq(frame)?,
        user_sig: frame
            .get("user_sig")
            .and_then(Value::as_str)
            .context("receipt ack missing user_sig")?
            .to_owned(),
    };
    if ack.seq != receipt.body.seq {
        bail!("receipt ack seq mismatch");
    }
    verify_provider_session_receipt_ack(&ack, &active.user_pubkey, &receipt.body)?;
    Ok(ack)
}

fn verify_provider_session_receipt_ack(
    ack: &ReceiptAck,
    user_pubkey: &str,
    body: &ReceiptBody,
) -> Result<()> {
    let key_bytes = hex_decode_array::<32>(user_pubkey, "receipt ack user pubkey")?;
    let sig_bytes = hex_decode_array::<64>(&ack.user_sig, "receipt ack user signature")?;
    let verifying_key =
        VerifyingKey::from_bytes(&key_bytes).context("invalid receipt ack user pubkey")?;
    let signature = Signature::from_bytes(&sig_bytes);
    let payload = receipt_signing_bytes(body)?;
    verifying_key
        .verify_strict(&payload, &signature)
        .context("receipt ack user signature failed")
}

async fn send_provider_session_close(
    bridge: &mut ScBridgeClient,
    remote: &str,
    session_id: &str,
    reason: &str,
) -> Result<()> {
    let send_result = bridge
        .session_send(
            remote,
            session_id,
            json!({
                "t": "s.close",
                "v": 1,
                "session_id": session_id,
                "reason": reason,
            }),
        )
        .await;
    let close_result = bridge.session_close(remote, session_id).await;
    send_result.with_context(|| format!("sending s.close for {session_id}"))?;
    close_result.with_context(|| format!("reclaiming direct session {session_id}"))?;
    Ok(())
}

#[cfg(test)]
fn provider_session_receipt(
    terms: &ProviderSessionTerms,
    active: &ActiveProviderSession,
    body: &Value,
    output: &ProviderSessionOutput,
    runtime_keypair: &RuntimeKeypair,
) -> Result<ProviderSignedSessionReceipt> {
    provider_session_receipt_for_usage_attribution(
        terms,
        active,
        body,
        output.usage.clone(),
        output.usage_attribution.clone(),
        1,
        true,
        runtime_keypair,
    )
}

fn provider_session_receipt_for_usage(
    terms: &ProviderSessionTerms,
    active: &ActiveProviderSession,
    body: &Value,
    usage: ReceiptUsage,
    seq: u64,
    final_receipt: bool,
    runtime_keypair: &RuntimeKeypair,
) -> Result<ProviderSignedSessionReceipt> {
    provider_session_receipt_for_usage_attribution(
        terms,
        active,
        body,
        usage,
        BTreeMap::new(),
        seq,
        final_receipt,
        runtime_keypair,
    )
}

fn provider_session_receipt_for_usage_attribution(
    terms: &ProviderSessionTerms,
    active: &ActiveProviderSession,
    body: &Value,
    usage: ReceiptUsage,
    usage_attribution: BTreeMap<String, u64>,
    seq: u64,
    final_receipt: bool,
    runtime_keypair: &RuntimeKeypair,
) -> Result<ProviderSignedSessionReceipt> {
    let usage = provider_session_logical_usage(active, &usage);
    let au_owed_cum = provider_session_au_owed(active, &usage)
        .context("logical receipt usage regressed from its signed billing baseline")?;
    let incremental_au = au_owed_cum
        .checked_sub(active.billing_prior_au_owed_cum)
        .context("logical receipt amount regressed from its signed billing baseline")?;
    ensure!(
        incremental_au <= active.max_spend_au,
        "provider receipt exceeds the signed incremental spend maximum"
    );
    let receipt_body = ReceiptBody {
        schema_version: SESSION_RECEIPT_SCHEMA_VERSION,
        session_id: active.session_id.clone(),
        billing_id: active.billing_id.clone(),
        billing_attempt: active.billing_attempt,
        billing_prior_usage: active.billing_prior_usage.clone(),
        billing_prior_au_owed_cum: active.billing_prior_au_owed_cum,
        billing_epoch: active.billing_epoch,
        reservation_id: active.reservation_id.clone(),
        reservation_expires_after_epoch: active.reservation_expires_after_epoch,
        reservation_receipt_grace_epochs: active.reservation_receipt_grace_epochs,
        payout_revision: active.payout_revision.clone(),
        seq,
        final_receipt,
        rail: active.rail.clone(),
        user: active.user_pubkey.clone(),
        provider: terms.provider.clone(),
        enclave_id: terms.enclave_id.clone(),
        model_id: terms.model_id.clone(),
        price_ver: active.price_ver,
        locked_rate_map: active.locked_rate_map.clone(),
        locked_per_req_au: active.locked_per_req_au,
        locked_min_session_au: active.locked_min_session_au,
        served_ctx: active.served_ctx,
        ctx_bracket: active.ctx_bracket.clone(),
        ctx_bracket_table_ver: active.ctx_bracket_table_ver,
        rules_ver: terms.rules_ver,
        usage: usage.clone(),
        usage_attribution,
        au_owed_cum,
        prompt_hash: provider_session_prompt_hash(body),
        ts: unix_epoch_millis()?,
    };
    let payload = receipt_signing_bytes(&receipt_body).context("building receipt signing bytes")?;
    Ok(ProviderSignedSessionReceipt {
        body: receipt_body,
        enclave_sig: runtime_keypair.sign_hex(&payload),
    })
}

fn provider_session_logical_usage(
    active: &ActiveProviderSession,
    attempt_usage: &ReceiptUsage,
) -> ReceiptUsage {
    if active.billing_prior_au_owed_cum == 0 {
        return attempt_usage.clone();
    }
    let incremental = ReceiptUsage::from_units(
        attempt_usage
            .units()
            .iter()
            .filter(|(unit, _)| {
                !matches!(
                    unit.as_str(),
                    USAGE_INPUT_TOKEN | USAGE_CACHED_INPUT_TOKEN | USAGE_INPUT_CHARACTER
                )
            })
            .map(|(unit, count)| (unit.clone(), *count)),
    );
    active.billing_prior_usage.saturating_add(&incremental)
}

fn provider_session_au_owed(
    active: &ActiveProviderSession,
    usage: &ReceiptUsage,
) -> Option<MoneyAu> {
    logical_cumulative_priced_usage_au(
        &active.locked_rate_map,
        active.locked_per_req_au,
        active.locked_min_session_au,
        &active.billing_prior_usage,
        active.billing_prior_au_owed_cum,
        usage,
    )
}

fn provider_session_prompt_hash(body: &Value) -> String {
    let endpoint_family = body
        .get("mayhem_contract")
        .and_then(|value| value.get("endpoint_family"))
        .and_then(Value::as_str);
    if endpoint_family.is_some_and(provider_receipt_binds_contract_request) {
        return mayhem_proto::endpoint_request_fingerprint(
            body.get("contract_request").unwrap_or(body),
        );
    }
    blake3::hash(provider_session_prompt_text(body).as_bytes())
        .to_hex()
        .to_string()
}

fn provider_receipt_binds_contract_request(endpoint_family: &str) -> bool {
    matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_OPENAI_IMAGE_GENERATIONS
            | mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE
            | mayhem_proto::ENDPOINT_OPENAI_AUDIO_TRANSCRIPTIONS
            | mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION
            | mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH
            | mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH
            | mayhem_proto::ENDPOINT_OPENAI_VIDEOS
            | mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO
            | mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS
            | mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS
            | mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO
    )
}

fn provider_session_prompt_text(body: &Value) -> String {
    let endpoint_family = body
        .get("mayhem_contract")
        .and_then(|value| value.get("endpoint_family"))
        .and_then(Value::as_str);
    let body = body.get("contract_request").unwrap_or(body);
    if matches!(
        endpoint_family,
        Some(
            mayhem_proto::ENDPOINT_OPENAI_EMBEDDINGS | mayhem_proto::ENDPOINT_HF_FEATURE_EXTRACTION
        )
    ) {
        return provider_embedding_prompt_text(body);
    }
    if matches!(
        endpoint_family,
        Some(
            mayhem_proto::ENDPOINT_OPENAI_IMAGE_GENERATIONS
                | mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE
        )
    ) {
        return stable_json_value(body).to_string();
    }
    if matches!(
        endpoint_family,
        Some(
            mayhem_proto::ENDPOINT_OPENAI_AUDIO_TRANSCRIPTIONS
                | mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION
                | mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH
                | mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH
                | mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS
                | mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS
                | mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO
        )
    ) {
        return stable_json_value(body).to_string();
    }
    endpoint_family
        .and_then(|family| provider_endpoint_messages(family, body).ok())
        .or_else(|| body.get("messages").and_then(Value::as_array).cloned())
        .map(|messages| {
            messages
                .iter()
                .map(provider_message_to_text)
                .collect::<Vec<_>>()
                .join("\n")
        })
        .unwrap_or_default()
}

fn provider_embedding_prompt_text(body: &Value) -> String {
    match provider_embedding_input_texts_from_body(body) {
        Ok(inputs) => stable_json_value(&json!({
            "kind": "embedding",
            "input": inputs,
        }))
        .to_string(),
        Err(_) => String::new(),
    }
}

fn provider_embedding_input_texts_from_body(body: &Value) -> Result<Vec<String>> {
    let input = body
        .get("input")
        .or_else(|| body.get("inputs"))
        .context("embedding request missing input")?;
    provider_embedding_input_texts_from_value(input)
}

fn provider_embedding_input_texts_from_value(value: &Value) -> Result<Vec<String>> {
    match value {
        Value::String(text) => {
            if text.is_empty() {
                bail!("embedding input must not be empty");
            }
            Ok(vec![text.clone()])
        }
        Value::Array(items) => {
            if items.is_empty() {
                bail!("embedding input array must not be empty");
            }
            let mut inputs = Vec::with_capacity(items.len());
            for item in items {
                match item {
                    Value::String(text) if !text.is_empty() => inputs.push(text.clone()),
                    Value::String(_) => bail!("embedding input strings must not be empty"),
                    _ => bail!("embedding input must be a string or an array of strings"),
                }
            }
            Ok(inputs)
        }
        _ => bail!("embedding input must be a string or an array of strings"),
    }
}

fn provider_embedding_input_token_count(inputs: &[String]) -> u64 {
    inputs
        .iter()
        .map(|input| rough_text_tokens(input))
        .fold(0_u64, u64::saturating_add)
}

fn provider_session_attestation_policy_binding(
    frame: &Value,
    terms: &ProviderSessionTerms,
    runtime: &ProviderSessionRuntime<'_>,
) -> Result<Option<HardwareQuoteRoutePolicyBinding>> {
    let raw = frame.get("attestation_policy_binding");
    let Some(config) = runtime.hardware_quote_config.as_ref() else {
        ensure!(
            raw.is_none_or(Value::is_null),
            "Tier-1 session must not carry a higher-tier attestation policy binding"
        );
        return Ok(None);
    };
    let value = raw
        .filter(|value| !value.is_null())
        .context("Tier-2/Tier-3 session is missing attestation_policy_binding")?;
    let binding: HardwareQuoteRoutePolicyBinding = serde_json::from_value(value.clone())
        .context("session attestation_policy_binding is invalid")?;
    ensure!(
        binding.kind == config.kind,
        "session attestation policy kind does not match the provider quote kind"
    );
    ensure!(
        binding.enclave_id == terms.enclave_id,
        "session attestation policy targets a different enclave"
    );
    ensure!(
        binding.policy_sequence > 0
            && is_hex_len(&binding.policy_digest, 64)
            && is_hex_len(&binding.device_id, 64)
            && binding.evidence_schema_version > 0,
        "session attestation policy binding is incomplete"
    );
    Ok(Some(binding))
}

async fn provider_session_attestation(
    runtime: &ProviderSessionRuntime<'_>,
    terms: &ProviderSessionTerms,
    att_nonce: &str,
    policy_binding: Option<&HardwareQuoteRoutePolicyBinding>,
) -> Result<Tier1AttestationReport> {
    let report_ts = unix_epoch_seconds()?;
    provider_attestation_report(
        runtime.hardware_quote_config.as_ref(),
        runtime.attestation_identity.clone(),
        runtime.runtime_keypair,
        &terms.provider,
        runtime.provider_signing_seed,
        runtime.keypair_path,
        runtime.password,
        runtime.binary_path,
        Some(runtime.attestation_identity.binary_hash.as_str()),
        runtime.boot_epoch,
        report_ts,
        att_nonce.to_owned(),
        runtime.runtime_config.clone(),
        policy_binding,
    )
    .await
    .map(|material| material.report)
    .context("preparing per-session provider attestation")
}

#[cfg(test)]
struct ProviderSessionAttestationInput<'a> {
    identity: &'a CatalogEnclaveIdentity,
    runtime_keypair: &'a RuntimeKeypair,
    provider_pubkey: &'a str,
    binary_path: &'a Path,
    boot_epoch: u64,
    report_ts: u64,
    att_nonce: &'a str,
    runtime_config: AttestationRuntimeConfig,
}

#[cfg(test)]
fn prepare_provider_session_attestation(
    input: ProviderSessionAttestationInput<'_>,
) -> Result<mayhem_enclave::Tier1AttestationDraft> {
    prepare_tier1_attestation_report(&Tier1ExternalProviderAttestationOptions {
        identity: input.identity.clone(),
        runtime_keypair: input.runtime_keypair.clone(),
        provider_pubkey: input.provider_pubkey.to_owned(),
        binary_path: input.binary_path.to_path_buf(),
        boot_epoch: input.boot_epoch,
        report_ts: input.report_ts,
        nonce_u: input.att_nonce.to_owned(),
        runtime_config: input.runtime_config,
    })
    .context("preparing per-session provider attestation")
}

fn provider_session_responder(
    ctx: &ProviderSessionContext<'_>,
) -> Result<Box<dyn ProviderSessionResponder>> {
    if ctx.args.dev_session_shim {
        if !ctx.args.dev_skip_catalog_verify {
            bail!("--dev-session-shim requires --dev-skip-catalog-verify and is never canonical");
        }
        return Ok(Box::new(DeterministicProviderSessionResponder));
    }

    provider_log(
        ctx.args,
        &format!(
            "Loading {} session engine from verified admin artifact {}",
            ctx.selected.artifact.engine,
            ctx.artifact_paths.primary.display()
        ),
    );
    let load_config = provider_engine_load_config(
        ctx.args,
        ctx.selected,
        ctx.artifact_paths,
        ctx.backend_runtime,
    )?;
    match ctx.selected.artifact.engine.as_str() {
        "llama.cpp" => {
            let mut backend = match ctx.backend_runtime.python.as_ref() {
                Some(python) => mayhem_engine::LlamaCppBackend::with_media_python(python),
                None => mayhem_engine::LlamaCppBackend::new(),
            }
            .context("initializing llama.cpp provider session engine")?;
            with_provider_progress_spinner(ctx.args, "llama.cpp engine load", || {
                backend
                    .load(load_config)
                    .context("loading llama.cpp provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "mlx" => {
            let python = ctx
                .backend_runtime
                .python
                .as_ref()
                .context("MLX runtime preflight did not resolve Python")?;
            let mut backend = mayhem_engine::MlxBackend::with_python(python)
                .context("initializing MLX provider session engine")?;
            with_provider_progress_spinner(ctx.args, "MLX engine load", || {
                backend
                    .load(load_config)
                    .context("loading MLX provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "trt-llm" => {
            let python = ctx
                .backend_runtime
                .python
                .as_ref()
                .context("TensorRT-LLM runtime preflight did not resolve Python")?;
            let mut backend = mayhem_engine::TrtLlmBackend::with_python(python)
                .context("initializing TensorRT-LLM provider session engine")?;
            with_provider_progress_spinner(ctx.args, "TensorRT-LLM engine load", || {
                backend
                    .load(load_config)
                    .context("loading TensorRT-LLM provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "vllm" => {
            let python = ctx
                .backend_runtime
                .python
                .as_ref()
                .context("vLLM runtime preflight did not resolve Python")?;
            let mut backend = mayhem_engine::VllmBackend::with_python(python)
                .context("initializing vLLM provider session engine")?;
            with_provider_progress_spinner(ctx.args, "vLLM engine load", || {
                backend
                    .load(load_config)
                    .context("loading vLLM provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "stable-diffusion.cpp" => {
            let binary = ctx
                .backend_runtime
                .external_binary
                .as_ref()
                .context("stable-diffusion.cpp runtime preflight did not resolve sd-cli")?;
            let mut backend = mayhem_engine::StableDiffusionCppBackend::with_binary(binary);
            with_provider_progress_spinner(ctx.args, "stable-diffusion.cpp engine load", || {
                backend
                    .load(load_config)
                    .context("loading stable-diffusion.cpp provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "ace-step" => {
            let python = ctx
                .backend_runtime
                .python
                .as_ref()
                .context("ACE-Step runtime preflight did not resolve Python")?;
            let mut backend = mayhem_engine::AceStepBackend::with_python(python)
                .context("initializing ACE-Step provider session engine")?;
            with_provider_progress_spinner(ctx.args, "ACE-Step engine load", || {
                backend
                    .load(load_config)
                    .context("loading ACE-Step provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "chatterbox" => {
            let python = ctx
                .backend_runtime
                .python
                .as_ref()
                .context("Chatterbox runtime preflight did not resolve Python")?;
            let device = ctx
                .backend_runtime
                .chatterbox_device
                .context("Chatterbox runtime preflight did not select an execution device")?;
            let mut backend =
                mayhem_engine::ChatterboxBackend::with_python_for_device(python, device.as_str())
                    .context("initializing Chatterbox provider session engine")?;
            with_provider_progress_spinner(ctx.args, "Chatterbox engine load", || {
                backend
                    .load(load_config)
                    .context("loading Chatterbox provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "needle-cpu" | "needle-gpu" => {
            let python = ctx
                .backend_runtime
                .python
                .as_ref()
                .context("Needle runtime preflight did not resolve Python")?;
            let requested_device = needle_device_for_engine(ctx.selected.artifact.engine.as_str())
                .context("Needle provider engine did not select a device")?;
            let device = python_runtime::resolve_needle_device_for_request(requested_device)
                .context("Needle provider host did not resolve a supported device")?;
            let mut backend =
                mayhem_engine::NeedleBackend::with_python_for_device(python, device)
                    .context("initializing Needle provider session engine")?;
            with_provider_progress_spinner(ctx.args, "Needle engine load", || {
                backend
                    .load(load_config)
                    .context("loading Needle provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "sulphur" => {
            let python = ctx
                .backend_runtime
                .python
                .as_ref()
                .context("Sulphur runtime preflight did not resolve Python")?;
            let mut backend = mayhem_engine::SulphurBackend::with_python(python)
                .context("initializing Sulphur provider session engine")?;
            with_provider_progress_spinner(ctx.args, "Sulphur engine load", || {
                backend
                    .load(load_config)
                    .context("loading Sulphur provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "transformers-asr" => {
            let python = ctx
                .backend_runtime
                .python
                .as_ref()
                .context("Transformers ASR runtime preflight did not resolve Python")?;
            let mut backend = mayhem_engine::TransformersAsrBackend::with_python(python)
                .context("initializing Transformers ASR provider session engine")?;
            with_provider_progress_spinner(ctx.args, "Transformers ASR engine load", || {
                backend
                    .load(load_config)
                    .context("loading Transformers ASR provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "whisper.cpp" => {
            let binary = ctx
                .backend_runtime
                .external_binary
                .as_ref()
                .context("whisper.cpp runtime preflight did not resolve whisper-cli")?;
            let mut backend = mayhem_engine::WhisperCppBackend::with_binary(binary);
            with_provider_progress_spinner(ctx.args, "whisper.cpp engine load", || {
                backend
                    .load(load_config)
                    .context("loading whisper.cpp provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "piper" => {
            let binary = ctx
                .backend_runtime
                .external_binary
                .as_ref()
                .context("Piper runtime preflight did not resolve piper")?;
            let mut backend = mayhem_engine::PiperBackend::with_binary(binary);
            with_provider_progress_spinner(ctx.args, "piper engine load", || {
                backend
                    .load(load_config)
                    .context("loading piper provider session engine")
            })?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        other => bail!(
            "provider session engine for {other} is not wired locally yet; do not serve this enclave until its admin-approved engine adapter is available"
        ),
    }
}

#[derive(Clone, Debug, Serialize)]
struct ProviderModalityHealthReport {
    prompt_id: String,
    modalities: Vec<String>,
    engine: String,
    ok: bool,
}

#[derive(Clone, Debug)]
struct ProviderModalitySelfTestCase {
    prompt_id: String,
    modalities: Vec<String>,
    body: Value,
}

fn provider_modality_self_test_plan(
    ctx: &ProviderSessionContext<'_>,
    canaries_dir: &Path,
) -> Result<Vec<ProviderModalitySelfTestCase>> {
    let prompts = load_canary_prompts_checked(
        Some(canaries_dir),
        &ctx.selected.model.canary.set_id,
        None,
        false,
    )?;
    let served = ctx
        .selected
        .served_modalities
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let mut missing = served.clone();
    let mut candidates = prompts
        .iter()
        .filter_map(|prompt| {
            let modalities = provider_canary_prompt_modalities(&ctx.selected.model, prompt);
            (!modalities.is_empty() && modalities.iter().all(|modality| served.contains(modality)))
                .then_some((prompt, modalities))
        })
        .collect::<Vec<_>>();
    let mut selected = Vec::new();
    while !missing.is_empty() {
        candidates.sort_by_key(|(_, modalities)| {
            std::cmp::Reverse(
                modalities
                    .iter()
                    .filter(|modality| missing.contains(*modality))
                    .count(),
            )
        });
        let Some((prompt, modalities)) = candidates
            .iter()
            .find(|(_, modalities)| modalities.iter().any(|modality| missing.contains(modality)))
            .cloned()
        else {
            bail!(
                "provider cannot advertise modalities {}: canary set {} has no functional prompt covering {}",
                served.iter().cloned().collect::<Vec<_>>().join(","),
                ctx.selected.model.canary.set_id,
                missing.iter().cloned().collect::<Vec<_>>().join(",")
            );
        };
        for modality in &modalities {
            missing.remove(modality);
        }
        selected.push((prompt, modalities));
    }

    selected
        .into_iter()
        .map(|(prompt, modalities)| {
            let body = provider_canary_self_test_body(&ctx.selected.model, prompt)?;
            let body = provider_seal_local_contract_request(
                &body,
                &ctx.selected.model.adapter,
                &ctx.selected.model.model_id,
            )
            .with_context(|| {
                format!(
                    "functional modality canary {} violates its signed endpoint contract",
                    prompt.id
                )
            })?;
            Ok(ProviderModalitySelfTestCase {
                prompt_id: prompt.id.clone(),
                modalities: modalities.into_iter().collect(),
                body,
            })
        })
        .collect()
}

fn provider_modality_self_test(
    ctx: &ProviderSessionContext<'_>,
    terms: &ProviderSessionTerms,
    responder: &mut dyn ProviderSessionResponder,
    cases: Vec<ProviderModalitySelfTestCase>,
) -> Result<Vec<ProviderModalityHealthReport>> {
    let mut reports = Vec::new();
    for case in cases {
        let output = responder
            .respond(terms, &case.body, &CancellationToken::new())
            .with_context(|| format!("functional modality canary {} failed", case.prompt_id))?;
        validate_provider_canary_self_test_output(&ctx.selected.model, &output).with_context(
            || {
                format!(
                    "functional modality canary {} returned invalid output",
                    case.prompt_id
                )
            },
        )?;
        reports.push(ProviderModalityHealthReport {
            prompt_id: case.prompt_id,
            modalities: case.modalities,
            engine: ctx.selected.artifact.engine.clone(),
            ok: true,
        });
    }
    ensure!(
        responder.component_healthy(),
        "provider engine became unhealthy during functional modality self-test"
    );
    Ok(reports)
}

fn provider_session_responder_with_modality_health(
    ctx: &ProviderSessionContext<'_>,
) -> Result<(
    Box<dyn ProviderSessionResponder>,
    Vec<ProviderModalityHealthReport>,
)> {
    let terms = provider_session_terms(ctx)?;
    let cases = provider_modality_self_test_plan(ctx, ctx.canaries_dir)?;
    let mut responder = provider_session_responder(ctx)?;
    let health = provider_modality_self_test(ctx, &terms, responder.as_mut(), cases)?;
    Ok((responder, health))
}

fn provider_canary_prompt_modalities(
    model: &catalog::CatalogModel,
    prompt: &CanaryPrompt,
) -> BTreeSet<String> {
    match model.model_class.as_str() {
        DEFAULT_MODEL_CLASS => {
            let mut modalities = BTreeSet::new();
            if !prompt.messages.is_empty() {
                modalities.insert("text".to_owned());
            }
            for message in &prompt.messages {
                for part in message
                    .get("content")
                    .and_then(Value::as_array)
                    .into_iter()
                    .flatten()
                {
                    match part.get("type").and_then(Value::as_str) {
                        Some("image_url") => {
                            modalities.insert("image".to_owned());
                        }
                        Some("input_audio") => {
                            modalities.insert("audio".to_owned());
                        }
                        Some("video") | Some("video_url") | Some("input_video") => {
                            modalities.insert("video".to_owned());
                        }
                        _ => {}
                    }
                }
            }
            modalities
        }
        "embedding" => BTreeSet::from(["embedding".to_owned()]),
        "image-generation" => BTreeSet::from(["image".to_owned()]),
        "video-generation" => {
            let mut modalities = BTreeSet::from(["audio".to_owned(), "video".to_owned()]);
            if canary_video_attributes_have_conditioning_image(&prompt.endpoint_attributes) {
                modalities.insert("image".to_owned());
            }
            modalities
        }
        "stt" => BTreeSet::from(["audio".to_owned(), "text".to_owned()]),
        "tts" | "audio-generation" | "music-generation" => BTreeSet::from(["audio".to_owned()]),
        _ => BTreeSet::new(),
    }
}

fn provider_canary_self_test_body(
    model: &catalog::CatalogModel,
    prompt: &CanaryPrompt,
) -> Result<Value> {
    match model.model_class.as_str() {
        DEFAULT_MODEL_CLASS => {
            let mut body = json!({
                "messages": &prompt.messages,
                "max_tokens": prompt.max_tokens.unwrap_or(4).clamp(1, 4),
                "stream": false,
            });
            let object = body.as_object_mut().expect("text canary body is an object");
            if let Some(tools) = prompt.tools.as_ref().filter(|tools| !tools.is_empty()) {
                object.insert("tools".to_owned(), json!(tools));
            }
            for (name, level) in &prompt.specialities {
                object.insert(name.clone(), json!(level));
            }
            provider_canary_self_test_disable_reasoning(model, object);
            for (name, value) in [
                ("temperature", prompt.temperature.map(Value::from)),
                ("top_p", prompt.top_p.map(Value::from)),
                ("top_k", prompt.top_k.map(Value::from)),
                ("min_p", prompt.min_p.map(Value::from)),
                ("seed", prompt.seed.map(Value::from)),
            ] {
                if let Some(value) = value {
                    object.insert(name.to_owned(), value);
                }
            }
            let family = provider_canary_self_test_endpoint_family(model, &mut body)?;
            body["endpoint_family"] = json!(family);
            Ok(body)
        }
        "embedding" => Ok(json!({
            "kind": "embedding",
            "input": canary_prompt_text(prompt)?,
        })),
        "image-generation" => {
            let mut body = json!({
                "kind": "image_generation",
                "prompt": canary_prompt_text(prompt)?,
            });
            let object = body
                .as_object_mut()
                .expect("image canary body is an object");
            for (name, value) in [
                ("size", prompt.size.clone().map(Value::from)),
                ("steps", prompt.steps.map(Value::from)),
                ("cfg_scale", prompt.cfg_scale.map(Value::from)),
                ("shift", prompt.shift.map(Value::from)),
                ("seed", prompt.seed.map(Value::from)),
            ] {
                if let Some(value) = value {
                    object.insert(name.to_owned(), value);
                }
            }
            Ok(body)
        }
        "video-generation" => {
            let family = provider_video_canary_endpoint_family(model, prompt)?;
            let mut request = prompt.endpoint_attributes.clone();
            request.remove("endpoint_family");
            match family.as_str() {
                mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO => {
                    request
                        .entry("inputs".to_owned())
                        .or_insert(json!(canary_prompt_text(prompt)?));
                    let parameters = request
                        .entry("parameters".to_owned())
                        .or_insert_with(|| json!({}))
                        .as_object_mut()
                        .context("video canary parameters must be an object")?;
                    if let Some(seed) = prompt.seed {
                        parameters.entry("seed".to_owned()).or_insert(json!(seed));
                    }
                    if let Some(steps) = prompt.steps {
                        parameters
                            .entry("num_inference_steps".to_owned())
                            .or_insert(json!(steps));
                    }
                    if let Some(size) = prompt.size.as_deref() {
                        let (width, height) = parse_canary_image_size(size)?;
                        parameters.entry("width".to_owned()).or_insert(json!(width));
                        parameters
                            .entry("height".to_owned())
                            .or_insert(json!(height));
                    }
                    if let Some(num_frames) = prompt.num_frames {
                        parameters
                            .entry("num_frames".to_owned())
                            .or_insert(json!(num_frames));
                    }
                    if let Some(fps) = prompt.fps {
                        parameters.entry("fps".to_owned()).or_insert(json!(fps));
                    }
                    if let Some(negative_prompt) = &prompt.negative_prompt {
                        parameters
                            .entry("negative_prompt".to_owned())
                            .or_insert_with(|| negative_prompt.clone());
                    }
                }
                mayhem_proto::ENDPOINT_OPENAI_VIDEOS => {
                    request
                        .entry("model".to_owned())
                        .or_insert(json!(&model.model_id));
                    request
                        .entry("prompt".to_owned())
                        .or_insert(json!(canary_prompt_text(prompt)?));
                    if let Some(duration) = prompt.duration_seconds {
                        request
                            .entry("seconds".to_owned())
                            .or_insert(json!(duration.to_string()));
                    }
                    if let Some(size) = prompt.size.as_deref() {
                        request.entry("size".to_owned()).or_insert(json!(size));
                    }
                    if let Some(num_frames) = prompt.num_frames {
                        request
                            .entry("num_frames".to_owned())
                            .or_insert(json!(num_frames));
                    }
                    if let Some(fps) = prompt.fps {
                        request.entry("fps".to_owned()).or_insert(json!(fps));
                    }
                    if let Some(negative_prompt) = &prompt.negative_prompt {
                        request
                            .entry("negative_prompt".to_owned())
                            .or_insert_with(|| negative_prompt.clone());
                    }
                }
                _ => unreachable!("video canary endpoint family was validated"),
            }
            request.insert("kind".to_owned(), json!("video_generation"));
            request.insert("endpoint_family".to_owned(), json!(family));
            Ok(Value::Object(request.into_iter().collect()))
        }
        "stt" => {
            let audio = base64::engine::general_purpose::STANDARD
                .decode(
                    prompt
                        .audio_b64
                        .as_deref()
                        .context("STT modality canary is missing audio_b64")?,
                )
                .context("STT modality canary audio_b64 is invalid")?;
            let audio_seconds = audio_duration_seconds_ceil(&audio)
                .context("STT modality canary is not a valid bounded WAV or FLAC")?;
            let content_type = prompt.content_type.clone().unwrap_or_else(|| {
                detected_audio_content_type(&audio)
                    .unwrap_or("audio/wav")
                    .to_owned()
            });
            let filename = prompt.filename.clone().unwrap_or_else(|| {
                if content_type == "audio/flac" {
                    "test.flac".to_owned()
                } else {
                    "test.wav".to_owned()
                }
            });
            let mut body = json!({
                "kind": "audio_transcription",
                "audio": {
                    "encoding": "base64",
                    "data": base64::engine::general_purpose::STANDARD.encode(&audio),
                    "content_type": content_type,
                    "filename": filename,
                },
                "audio_seconds": audio_seconds,
            });
            if let Some(language) = &prompt.language {
                body["language"] = json!(language);
            }
            Ok(body)
        }
        "tts" => {
            let family = provider_tts_canary_endpoint_family(model, prompt)?;
            let mut request = prompt.endpoint_attributes.clone();
            request.remove("endpoint_family");
            let reference_audio = prompt.audio_b64.as_ref().map(|data| {
                json!({
                    "data": data,
                    "encoding": "base64",
                    "content_type": prompt.content_type.as_deref().unwrap_or("audio/wav"),
                })
            });
            match family.as_str() {
                mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH => {
                    request
                        .entry("input".to_owned())
                        .or_insert(json!(canary_prompt_text(prompt)?));
                    if let Some(voice) = &prompt.voice {
                        request.entry("voice".to_owned()).or_insert(json!(voice));
                    }
                    if let Some(response_format) = &prompt.response_format {
                        request
                            .entry("response_format".to_owned())
                            .or_insert(json!(response_format));
                    }
                    if let Some(reference_audio) = reference_audio {
                        request
                            .entry("reference_audio".to_owned())
                            .or_insert(reference_audio);
                    }
                    for (name, value) in [
                        ("temperature", prompt.temperature.map(Value::from)),
                        ("min_p", prompt.min_p.map(Value::from)),
                        ("top_p", prompt.top_p.map(Value::from)),
                        ("repetition_penalty", prompt.repeat_penalty.map(Value::from)),
                        ("seed", prompt.seed.map(Value::from)),
                    ] {
                        if let Some(value) = value {
                            request.entry(name.to_owned()).or_insert(value);
                        }
                    }
                }
                mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH => {
                    let top_level_reference_audio = request.remove("reference_audio");
                    let top_level_exaggeration = request.remove("exaggeration");
                    let top_level_cfg_weight = request.remove("cfg_weight");
                    let top_level_temperature = request.remove("temperature");
                    let top_level_min_p = request.remove("min_p");
                    let top_level_top_p = request.remove("top_p");
                    let top_level_repetition_penalty = request.remove("repetition_penalty");
                    request
                        .entry("inputs".to_owned())
                        .or_insert(json!(canary_prompt_text(prompt)?));
                    let parameters = request
                        .entry("parameters".to_owned())
                        .or_insert_with(|| json!({}))
                        .as_object_mut()
                        .context("TTS canary parameters must be an object")?;
                    if let Some(voice) = &prompt.voice {
                        parameters.entry("voice".to_owned()).or_insert(json!(voice));
                    }
                    if let Some(reference_audio) = reference_audio.or(top_level_reference_audio) {
                        parameters
                            .entry("reference_audio".to_owned())
                            .or_insert(reference_audio);
                    }
                    if let Some(exaggeration) = top_level_exaggeration {
                        parameters
                            .entry("exaggeration".to_owned())
                            .or_insert(exaggeration);
                    }
                    if let Some(cfg_weight) = top_level_cfg_weight {
                        parameters
                            .entry("cfg_weight".to_owned())
                            .or_insert(cfg_weight);
                    }
                    if let Some(seed) = prompt.seed {
                        parameters.entry("seed".to_owned()).or_insert(json!(seed));
                    }
                    let generation_parameters = parameters
                        .entry("generation_parameters".to_owned())
                        .or_insert_with(|| json!({}))
                        .as_object_mut()
                        .context("TTS canary generation_parameters must be an object")?;
                    for (name, value) in [
                        (
                            "temperature",
                            prompt
                                .temperature
                                .map(Value::from)
                                .or(top_level_temperature),
                        ),
                        ("min_p", prompt.min_p.map(Value::from).or(top_level_min_p)),
                        ("top_p", prompt.top_p.map(Value::from).or(top_level_top_p)),
                        (
                            "repetition_penalty",
                            prompt
                                .repeat_penalty
                                .map(Value::from)
                                .or(top_level_repetition_penalty),
                        ),
                    ] {
                        if let Some(value) = value {
                            generation_parameters
                                .entry(name.to_owned())
                                .or_insert(value);
                        }
                    }
                }
                _ => unreachable!("TTS canary endpoint family was validated"),
            }
            request.insert("kind".to_owned(), json!("audio_speech"));
            request.insert("endpoint_family".to_owned(), json!(family));
            Ok(Value::Object(request.into_iter().collect()))
        }
        "audio-generation" => {
            let mut body = json!({
                "kind": "audio_generation",
                "prompt": canary_prompt_text(prompt)?,
            });
            let object = body
                .as_object_mut()
                .expect("audio-generation canary body is an object");
            for (name, value) in [
                ("duration_seconds", prompt.duration_seconds.map(Value::from)),
                (
                    "response_format",
                    prompt.response_format.clone().map(Value::from),
                ),
                ("temperature", prompt.temperature.map(Value::from)),
                ("top_k", prompt.top_k.map(Value::from)),
                ("top_p", prompt.top_p.map(Value::from)),
                ("guidance_scale", prompt.guidance_scale.map(Value::from)),
                ("seed", prompt.seed.map(Value::from)),
            ] {
                if let Some(value) = value {
                    object.insert(name.to_owned(), value);
                }
            }
            Ok(body)
        }
        "music-generation" => {
            let mut body = json!({
                "kind": "music_generation",
                "prompt": canary_prompt_text(prompt)?,
            });
            let object = body
                .as_object_mut()
                .expect("music-generation canary body is an object");
            for (name, value) in [
                ("lyrics", prompt.lyrics.clone().map(Value::from)),
                ("instrumental", prompt.instrumental.map(Value::from)),
                ("duration_seconds", prompt.duration_seconds.map(Value::from)),
                ("bpm", prompt.bpm.map(Value::from)),
                ("keyscale", prompt.keyscale.clone().map(Value::from)),
                (
                    "timesignature",
                    prompt.timesignature.clone().map(Value::from),
                ),
                ("task_type", prompt.task_type.clone().map(Value::from)),
                ("thinking", prompt.thinking.map(Value::from)),
                ("steps", prompt.steps.map(Value::from)),
                ("n", prompt.n.map(Value::from)),
                ("temperature", prompt.temperature.map(Value::from)),
                ("top_k", prompt.top_k.map(Value::from)),
                ("top_p", prompt.top_p.map(Value::from)),
                ("guidance_scale", prompt.guidance_scale.map(Value::from)),
                (
                    "response_format",
                    prompt.response_format.clone().map(Value::from),
                ),
                ("seed", prompt.seed.map(Value::from)),
            ] {
                if let Some(value) = value {
                    object.insert(name.to_owned(), value);
                }
            }
            Ok(body)
        }
        other => bail!("functional modality self-test is not wired for model_class {other}"),
    }
}

fn provider_tts_canary_endpoint_family(
    model: &catalog::CatalogModel,
    prompt: &CanaryPrompt,
) -> Result<String> {
    let requested = prompt
        .endpoint_attributes
        .get("endpoint_family")
        .and_then(Value::as_str);
    let family = if let Some(requested) = requested {
        ensure!(
            matches!(
                requested,
                mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH
                    | mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH
            ),
            "TTS canary prompt {} has unsupported endpoint_family {requested}",
            prompt.id
        );
        requested
    } else if model
        .adapter
        .endpoint_families
        .iter()
        .any(|contract| contract.family == mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH)
    {
        mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH
    } else {
        mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH
    };
    ensure!(
        model
            .adapter
            .endpoint_families
            .iter()
            .any(|contract| contract.family == family),
        "TTS canary prompt {} selects endpoint family {family}, but the signed model adapter does not expose it",
        prompt.id
    );
    Ok(family.to_owned())
}

fn provider_canary_self_test_disable_reasoning(
    model: &catalog::CatalogModel,
    body: &mut serde_json::Map<String, Value>,
) {
    // Startup modality probes are intentionally tiny, so use a signed direct-answer level.
    for speciality in &model.adapter.specialities {
        let controls_reasoning =
            provider_reasoning_speciality_control(&speciality.name, &speciality.name)
                || model.adapter.endpoint_families.iter().any(|contract| {
                    contract
                        .speciality_mappings
                        .get(&speciality.name)
                        .is_some_and(|mapping| {
                            provider_reasoning_speciality_control(
                                &speciality.name,
                                &mapping.native_path,
                            )
                        })
                });
        if !controls_reasoning {
            continue;
        }
        let Some(level) = speciality
            .levels
            .iter()
            .find(|level| provider_reasoning_level_disabled(&level.name, &level.native_value))
        else {
            continue;
        };
        body.insert(speciality.name.clone(), json!(&level.name));
    }
}

fn provider_canary_self_test_endpoint_family(
    model: &catalog::CatalogModel,
    body: &mut Value,
) -> Result<String> {
    let kind = body.get("kind").and_then(Value::as_str).unwrap_or("chat");
    let transport_kind = provider_endpoint_transport_kind(provider_local_endpoint_family(kind))?;
    let mut request = body.clone();
    if let Some(object) = request.as_object_mut() {
        object.remove("kind");
        object.remove("endpoint_family");
        object
            .entry("model")
            .or_insert_with(|| json!(&model.model_id));
    }
    let mut first_violations = None;
    for contract in model.adapter.endpoint_families.iter().filter(|contract| {
        provider_endpoint_transport_kind(&contract.family).ok() == Some(transport_kind)
    }) {
        let mut candidate = request.clone();
        for name in ["max_tokens", "max_completion_tokens", "max_output_tokens"] {
            let Some(requested) = candidate.get(name).and_then(Value::as_u64) else {
                continue;
            };
            let Some(spec) = contract.request_attribute_specs.get(name) else {
                continue;
            };
            let adjusted = mayhem_proto::canonicalize_positive_integer_for_spec(requested, spec)
                .map_err(anyhow::Error::msg)?;
            candidate[name] = json!(adjusted);
        }
        match mayhem_proto::validate_endpoint_request(contract, &candidate) {
            Ok(()) => {
                for name in ["max_tokens", "max_completion_tokens", "max_output_tokens"] {
                    if let Some(value) = candidate.get(name) {
                        body[name] = value.clone();
                    }
                }
                return Ok(contract.family.clone());
            }
            Err(violations) if first_violations.is_none() => {
                first_violations = Some(violations);
            }
            Err(_) => {}
        }
    }
    let details = first_violations
        .unwrap_or_default()
        .into_iter()
        .take(4)
        .map(|violation| format!("{}: {}", violation.path, violation.reason))
        .collect::<Vec<_>>()
        .join("; ");
    bail!(
        "canary request has no compatible signed {transport_kind} endpoint family for {}{}",
        model.model_id,
        if details.is_empty() {
            String::new()
        } else {
            format!(": {details}")
        }
    )
}

const VIDEO_CANARY_FRAME_ATTRIBUTES: &[&str] =
    &["num_frames", "frame_count", "frameCount", "frames"];
const VIDEO_CANARY_FPS_ATTRIBUTES: &[&str] = &["fps", "frame_rate", "frameRate"];
const MEDIA_GENERATION_DURATION_ATTRIBUTES: &[&str] =
    &["seconds", "duration_seconds", "duration", "target_duration"];
const VIDEO_CANARY_IMAGE_ATTRIBUTES: &[&str] = &[
    "input_reference",
    "input_image",
    "conditioning_image",
    "init_image",
    "image",
];

fn provider_video_canary_endpoint_family(
    model: &catalog::CatalogModel,
    prompt: &CanaryPrompt,
) -> Result<String> {
    let requested = prompt
        .endpoint_attributes
        .get("endpoint_family")
        .map(|value| {
            value
                .as_str()
                .filter(|value| !value.is_empty())
                .context("video canary endpoint_family must be a non-empty string")
        })
        .transpose()?;
    let family = requested
        .map(str::to_owned)
        .or_else(|| {
            [
                mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO,
                mayhem_proto::ENDPOINT_OPENAI_VIDEOS,
            ]
            .into_iter()
            .find(|family| {
                model
                    .adapter
                    .endpoint_families
                    .iter()
                    .any(|contract| contract.family == *family)
            })
            .map(str::to_owned)
        })
        .context("video canary model has no signed video-generation endpoint family")?;
    ensure!(
        matches!(
            family.as_str(),
            mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO | mayhem_proto::ENDPOINT_OPENAI_VIDEOS
        ),
        "video canary endpoint_family {family} is not a video-generation family"
    );
    ensure!(
        model
            .adapter
            .endpoint_families
            .iter()
            .any(|contract| contract.family == family),
        "video canary endpoint_family {family} is not present in the signed model adapter"
    );
    Ok(family)
}

fn canary_value_at_path<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
    path.split('.')
        .try_fold(value, |current, segment| current.get(segment))
}

fn provider_video_canary_attribute<'a>(
    contract: &mayhem_proto::EndpointFamilyContract,
    request: &'a Value,
    aliases: &[&str],
) -> Option<&'a Value> {
    contract.request_attributes.iter().find_map(|path| {
        let leaf = path.rsplit('.').next().unwrap_or(path);
        aliases
            .contains(&leaf)
            .then(|| canary_value_at_path(request, path))
            .flatten()
    })
}

fn provider_video_canary_fixed_shape(
    contract: &mayhem_proto::EndpointFamilyContract,
    request: &Value,
) -> Result<(u64, f64)> {
    let frames = provider_video_canary_attribute(contract, request, VIDEO_CANARY_FRAME_ATTRIBUTES)
        .and_then(Value::as_u64)
        .filter(|frames| *frames > 0)
        .context("video canary must resolve a fixed positive num_frames through its signed endpoint family")?;
    let fps = provider_video_canary_attribute(contract, request, VIDEO_CANARY_FPS_ATTRIBUTES)
        .and_then(Value::as_f64)
        .filter(|fps| fps.is_finite() && *fps > 0.0 && *fps <= 240.0)
        .context("video canary must resolve a fixed fps through its signed endpoint family")?;
    Ok((frames, fps))
}

fn provider_video_canary_conditioning_image(
    contract: &mayhem_proto::EndpointFamilyContract,
    request: &Value,
) -> Result<Option<(u64, u64)>> {
    let Some(value) =
        provider_video_canary_attribute(contract, request, VIDEO_CANARY_IMAGE_ATTRIBUTES)
    else {
        return Ok(None);
    };
    let data_url = match value {
        Value::String(value) => value.as_str(),
        Value::Object(value) => value
            .get("image_url")
            .or_else(|| value.get("url"))
            .and_then(Value::as_str)
            .context("video canary conditioning image object must contain image_url")?,
        _ => bail!("video canary conditioning image must be an inline image data URL"),
    };
    validate_provider_chat_image_data_url(data_url).map(Some)
}

fn canary_video_attributes_have_conditioning_image(attributes: &BTreeMap<String, Value>) -> bool {
    fn contains(value: &Value) -> bool {
        value.as_object().is_some_and(|object| {
            object.iter().any(|(key, child)| {
                (VIDEO_CANARY_IMAGE_ATTRIBUTES.contains(&key.as_str()) && !child.is_null())
                    || contains(child)
            })
        })
    }
    contains(&Value::Object(attributes.clone().into_iter().collect()))
}

fn validate_provider_canary_self_test_output(
    model: &catalog::CatalogModel,
    output: &ProviderSessionOutput,
) -> Result<()> {
    match model.model_class.as_str() {
        DEFAULT_MODEL_CLASS | "stt" => ensure!(
            !output.content.trim().is_empty() || !output.tools.is_empty(),
            "text modality canary produced no text or tool output"
        ),
        "embedding" => ensure!(
            output
                .embeddings
                .as_ref()
                .is_some_and(|embeddings| !embeddings.is_empty()
                    && embeddings.iter().all(|row| !row.is_empty())),
            "embedding modality canary produced no embedding vectors"
        ),
        "image-generation" => ensure!(
            output
                .artifacts
                .iter()
                .any(|artifact| artifact.content_type.starts_with("image/")),
            "image modality canary produced no image artifact"
        ),
        "video-generation" => ensure!(
            output
                .artifacts
                .iter()
                .any(|artifact| artifact.content_type.starts_with("video/")),
            "video modality canary produced no video artifact"
        ),
        "tts" | "audio-generation" | "music-generation" => ensure!(
            output
                .artifacts
                .iter()
                .any(|artifact| artifact.content_type.starts_with("audio/")),
            "audio modality canary produced no audio artifact"
        ),
        other => {
            bail!("functional modality output validation is not wired for model_class {other}")
        }
    }
    Ok(())
}

fn provider_engine_load_config(
    args: &ProviderStartArgs,
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
    backend_runtime: &ProviderBackendRuntime,
) -> Result<LoadConfig> {
    let ctx_size = u32::try_from(selected.served_ctx).with_context(|| {
        format!(
            "served ctx {} for {} exceeds engine ctx_size range",
            selected.served_ctx, selected.model.model_id
        )
    })?;
    let mut artifact_path_buf = artifact_paths.primary.clone();
    let mut materialized_trt_engine_dir = None;
    if selected.artifact.engine == "trt-llm" {
        let layout = materialize_trt_llm_artifacts(selected, artifact_paths)?;
        artifact_path_buf = layout.checkpoint_dir;
        materialized_trt_engine_dir = Some(layout.engine_dir);
    } else if selected.artifact.engine == "vllm" {
        artifact_path_buf = materialize_vllm_artifacts(selected, artifact_paths)?;
    } else if selected.artifact.engine == "mlx" {
        artifact_path_buf = materialize_mlx_artifacts(selected, artifact_paths)?;
    } else if selected.artifact.engine == "ace-step" {
        let cache_dir = backend_runtime
            .cache_dir
            .as_deref()
            .context("ACE-Step provider runtime cache was not resolved")?;
        artifact_path_buf = materialize_ace_step_artifacts(selected, artifact_paths, cache_dir)?;
    } else if selected.artifact.engine == "chatterbox" {
        let cache_dir = backend_runtime
            .cache_dir
            .as_deref()
            .context("Chatterbox provider runtime cache was not resolved")?;
        artifact_path_buf = materialize_chatterbox_artifacts(selected, artifact_paths, cache_dir)?;
    } else if selected.artifact.engine == "sulphur" {
        let cache_dir = backend_runtime
            .cache_dir
            .as_deref()
            .context("Sulphur provider runtime cache was not resolved")?;
        artifact_path_buf = materialize_sulphur_artifacts(selected, artifact_paths, cache_dir)?;
    } else if needle_device_for_engine(&selected.artifact.engine).is_some() {
        let cache_dir = backend_runtime
            .cache_dir
            .as_deref()
            .context("Needle provider runtime cache was not resolved")?;
        artifact_path_buf = materialize_needle_artifacts(selected, artifact_paths, cache_dir)?;
    } else if selected.artifact.engine == "transformers-asr" {
        artifact_path_buf = materialize_transformers_asr_artifacts(selected, artifact_paths)?;
    }
    let artifact_path = artifact_path_buf.as_path();
    let mut artifact = match selected.artifact.engine.as_str() {
        "llama.cpp" => ModelArtifact::gguf(artifact_path),
        "mlx" => ModelArtifact::mlx_safetensors(artifact_path),
        "trt-llm" => ModelArtifact::trt_llm_checkpoint(artifact_path),
        "vllm" => ModelArtifact::vllm_safetensors(artifact_path),
        "stable-diffusion.cpp" => ModelArtifact::stable_diffusion_checkpoint(artifact_path),
        "ace-step" => ModelArtifact::ace_step_safetensors(artifact_path),
        "chatterbox" => ModelArtifact::chatterbox_safetensors(artifact_path),
        "needle-cpu" | "needle-gpu" => ModelArtifact::transformers_safetensors(artifact_path),
        "sulphur" => sulphur_load_config(artifact_path)?.artifact,
        "transformers-asr" => ModelArtifact::transformers_safetensors(artifact_path),
        "whisper.cpp" => ModelArtifact::whisper_ggml(artifact_path),
        "piper" => ModelArtifact::piper_voice(artifact_path),
        other => bail!("unsupported local provider session engine {other}"),
    };
    if selected.artifact.engine == "sulphur" {
        bind_sulphur_primary_hash_path(&mut artifact, &selected.artifact)?;
    }
    let artifact = if let Some(sha256) = &selected.artifact.source_sha256 {
        artifact.with_sha256(sha256.clone())
    } else {
        artifact
    };
    let mut config = match selected.artifact.engine.as_str() {
        "llama.cpp" => LoadConfig::gguf(artifact_path),
        "mlx" => LoadConfig::mlx_safetensors(artifact_path),
        "trt-llm" => LoadConfig::trt_llm_checkpoint(artifact_path),
        "vllm" => LoadConfig::vllm_safetensors(artifact_path),
        "stable-diffusion.cpp" => LoadConfig::stable_diffusion_checkpoint(artifact_path),
        "ace-step" => LoadConfig::ace_step_safetensors(artifact_path),
        "chatterbox" => LoadConfig::chatterbox_safetensors(artifact_path),
        "needle-cpu" | "needle-gpu" => LoadConfig::transformers_safetensors(artifact_path),
        "sulphur" => sulphur_load_config(artifact_path)?,
        "transformers-asr" => LoadConfig::transformers_safetensors(artifact_path),
        "whisper.cpp" => LoadConfig::whisper_ggml(artifact_path),
        "piper" => LoadConfig::piper_voice(artifact_path),
        other => bail!("unsupported local provider session engine {other}"),
    };
    apply_catalog_kv_cache_profile(&mut config, &selected.artifact);
    config.mlx_runtime = selected.artifact.mlx_runtime;
    config.artifact = artifact;
    config.ctx_size = ctx_size.max(1);
    config.gpu_layers = if selected.artifact.engine == "llama.cpp" {
        resolve_provider_llama_execution_plan(
            &selected.artifact.engine,
            args.gpu_layers,
            &selected.verdict,
        )
        .and_then(|plan| plan.gpu_layers)
    } else {
        selected.verdict.n_layers_gpu
    };
    config.memory_limit_bytes = (selected.feasibility.memory_budget.worker_limit_bytes > 0)
        .then_some(selected.feasibility.memory_budget.worker_limit_bytes);
    config.backend_cache_dir = backend_runtime.cache_dir.clone();
    config.stable_diffusion_backend = backend_runtime.stable_diffusion_backend.clone();
    if selected.artifact.engine == "stable-diffusion.cpp" {
        config.stable_diffusion_cpp = selected
            .artifact
            .stable_diffusion_cpp
            .context("stable-diffusion.cpp catalog artifact is missing signed runtime semantics")?;
        if let Some(path) = artifact_paths.sidecars.get("text_encoder") {
            let sidecar = selected
                .artifact
                .sidecars
                .get("text_encoder")
                .context("downloaded text_encoder is missing from selected catalog artifact")?;
            config.stable_diffusion_llm = Some(
                ModelArtifact::stable_diffusion_checkpoint(path)
                    .with_sha256(sidecar.source_sha256.clone()),
            );
        }
        if let Some(path) = artifact_paths.sidecars.get("vae") {
            let sidecar = selected
                .artifact
                .sidecars
                .get("vae")
                .context("downloaded VAE is missing from selected catalog artifact")?;
            config.stable_diffusion_vae = Some(
                ModelArtifact::stable_diffusion_checkpoint(path)
                    .with_sha256(sidecar.source_sha256.clone()),
            );
        }
    }
    if let Some(mmproj_path) = artifact_paths.sidecars.get("mmproj") {
        let sidecar = selected
            .artifact
            .sidecars
            .get("mmproj")
            .context("downloaded mmproj sidecar is missing from selected catalog artifact")?;
        config.vision_projector =
            Some(ModelArtifact::gguf(mmproj_path).with_sha256(sidecar.source_sha256.clone()));
    }
    if selected.artifact.engine == "sulphur"
        && selected
            .served_specialities
            .get("prompt_enhancer")
            .is_some_and(|levels| levels.iter().any(|level| level == "on"))
    {
        apply_sulphur_prompt_enhancer_load_config(
            &mut config,
            &selected.artifact,
            &artifact_paths.sidecars,
        )?;
    }
    if let Some(piper_config_path) = artifact_paths.sidecars.get("piper_config") {
        let sidecar =
            selected.artifact.sidecars.get("piper_config").context(
                "downloaded piper_config sidecar is missing from selected catalog artifact",
            )?;
        config.piper_config = Some(
            ModelArtifact::piper_config(piper_config_path)
                .with_sha256(sidecar.source_sha256.clone()),
        );
    }
    if selected.artifact.engine == "trt-llm" {
        config.trt_engine_dir = materialized_trt_engine_dir
            .or_else(|| Some(trt_engine_cache_dir(artifact_path, &selected.artifact_name)));
        config.trt_tensor_parallel = Some(enclave_tp_degree(&selected.enclave.caps)?);
        if let Some(max_batch_size) = enclave_max_batch_size(&selected.enclave.caps)? {
            config.batch_size = max_batch_size;
        }
        if let Some(max_num_tokens) = enclave_max_num_tokens(&selected.enclave.caps)? {
            config.ubatch_size = max_num_tokens.max(config.ctx_size);
        }
        config.trt_kv_cache_dtype =
            trt_kv_cache_dtype_for_artifact(&selected.artifact_name, &selected.artifact);
        config.trt_require_engine_dir = true;
    }
    if selected.artifact.engine == "vllm" {
        config.vllm_tensor_parallel = Some(enclave_tp_degree(&selected.enclave.caps)?);
        if let Some(max_batch_size) = enclave_max_batch_size(&selected.enclave.caps)? {
            config.batch_size = max_batch_size;
        }
        if let Some(max_num_tokens) = enclave_max_num_tokens(&selected.enclave.caps)? {
            config.ubatch_size = max_num_tokens.max(1);
        }
        config.vllm_dtype = selected
            .enclave
            .caps
            .get("vllm_dtype")
            .and_then(Value::as_str)
            .map(str::to_owned);
        let utilization = provider_vllm_memory_utilization(selected, args.vllm_memory_utilization)?;
        config.vllm_gpu_memory_utilization_pct = Some(utilization.target_pct);
        config.vllm_gpu_memory_utilization_floor_pct = Some(utilization.floor_pct);
    }
    Ok(config)
}

