fn materialize_vllm_artifacts(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
) -> Result<PathBuf> {
    let checkpoint_dir =
        vllm_checkpoint_cache_dir(&artifact_paths.primary, &selected.artifact_name);
    fs::create_dir_all(&checkpoint_dir).with_context(|| {
        format!(
            "creating vLLM checkpoint layout {}",
            checkpoint_dir.display()
        )
    })?;
    let payload_name = catalog_path_file_name(&selected.artifact.path, "vLLM primary artifact")?;
    link_or_copy_file(&artifact_paths.primary, &checkpoint_dir.join(payload_name))?;
    for (sidecar_name, filename) in VLLM_REQUIRED_SIDECARS {
        let sidecar = selected
            .artifact
            .sidecars
            .get(*sidecar_name)
            .with_context(|| {
                format!(
                    "vLLM artifact {}/{} requires admin catalog sidecar {}",
                    selected.model.model_id, selected.artifact_name, sidecar_name
                )
            })?;
        if sidecar.path != *filename {
            bail!(
                "vLLM artifact {}/{} sidecar {} must use path {}, got {}",
                selected.model.model_id,
                selected.artifact_name,
                sidecar_name,
                filename,
                sidecar.path
            );
        }
    }
    for (sidecar_name, sidecar) in &selected.artifact.sidecars {
        let source = artifact_paths.sidecars.get(sidecar_name).with_context(|| {
            format!(
                "downloaded vLLM artifact {}/{} is missing admin sidecar {}",
                selected.model.model_id, selected.artifact_name, sidecar_name
            )
        })?;
        let relative = validate_catalog_artifact_relative_path(&sidecar.path)?;
        let destination = checkpoint_dir.join(relative);
        link_or_copy_file(source, &destination).with_context(|| {
            format!(
                "materializing vLLM sidecar {} at {}",
                sidecar_name,
                destination.display()
            )
        })?;
    }
    Ok(checkpoint_dir)
}

fn materialize_mlx_artifacts(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
) -> Result<PathBuf> {
    materialize_mlx_layout(
        &format!("{}/{}", selected.model.model_id, selected.artifact_name),
        &selected.artifact_name,
        &selected.artifact,
        artifact_paths,
    )
}

fn materialize_mlx_layout(
    label: &str,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    artifact_paths: &ProviderArtifactPaths,
) -> Result<PathBuf> {
    let model_dir = mlx_model_cache_dir(&artifact_paths.primary, artifact_name, artifact);
    fs::create_dir_all(&model_dir)
        .with_context(|| format!("creating MLX model layout {}", model_dir.display()))?;

    let primary_relative = validate_catalog_artifact_relative_path(&artifact.path)?;
    let primary = model_dir.join(&primary_relative);
    link_or_copy_file(&artifact_paths.primary, &primary).with_context(|| {
        format!(
            "materializing MLX primary artifact {label} at {}",
            primary.display()
        )
    })?;

    let mut occupied_paths = BTreeSet::from([primary_relative]);
    for (sidecar_name, sidecar) in &artifact.sidecars {
        let relative = validate_catalog_artifact_relative_path(&sidecar.path)?;
        ensure!(
            occupied_paths.insert(relative.clone()),
            "MLX artifact {label} declares duplicate path {}",
            sidecar.path
        );
        let source = artifact_paths.sidecars.get(sidecar_name).with_context(|| {
            format!("downloaded MLX artifact {label} is missing admin sidecar {sidecar_name}")
        })?;
        let destination = model_dir.join(relative);
        link_or_copy_file(source, &destination).with_context(|| {
            format!(
                "materializing MLX sidecar {} at {}",
                sidecar_name,
                destination.display()
            )
        })?;
    }
    Ok(primary)
}

fn materialize_transformers_asr_artifacts(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
) -> Result<PathBuf> {
    materialize_transformers_asr_layout(
        &format!("{}/{}", selected.model.model_id, selected.artifact_name),
        &selected.artifact_name,
        &selected.artifact,
        artifact_paths,
    )
}

fn materialize_transformers_asr_layout(
    label: &str,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    artifact_paths: &ProviderArtifactPaths,
) -> Result<PathBuf> {
    let model_dir = transformers_asr_checkpoint_cache_dir(&artifact_paths.primary, artifact_name);
    fs::create_dir_all(&model_dir).with_context(|| {
        format!(
            "creating Transformers ASR model layout {}",
            model_dir.display()
        )
    })?;
    let payload_name = catalog_path_file_name(&artifact.path, "Transformers ASR primary artifact")?;
    link_or_copy_file(&artifact_paths.primary, &model_dir.join(payload_name))?;
    for (sidecar_name, filename) in TRANSFORMERS_ASR_REQUIRED_SIDECARS {
        let sidecar = artifact.sidecars.get(*sidecar_name).with_context(|| {
            format!(
                "Transformers ASR artifact {label} requires admin catalog sidecar {sidecar_name}"
            )
        })?;
        ensure!(
            sidecar.path == *filename,
            "Transformers ASR artifact {label} sidecar {} must use path {}, got {}",
            sidecar_name,
            filename,
            sidecar.path
        );
        let source = artifact_paths.sidecars.get(*sidecar_name).with_context(|| {
            format!(
                "downloaded Transformers ASR artifact {label} is missing admin sidecar {sidecar_name}"
            )
        })?;
        link_or_copy_file(source, &model_dir.join(filename)).with_context(|| {
            format!(
                "materializing Transformers ASR sidecar {} at {}",
                sidecar_name,
                model_dir.join(filename).display()
            )
        })?;
    }
    Ok(model_dir)
}

fn materialize_needle_artifacts(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
    cache_dir: &Path,
) -> Result<PathBuf> {
    materialize_needle_layout(
        &format!("{}/{}", selected.model.model_id, selected.artifact_name),
        &selected.artifact_name,
        &selected.artifact,
        artifact_paths,
        cache_dir,
    )
}

fn materialize_needle_layout(
    label: &str,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    artifact_paths: &ProviderArtifactPaths,
    cache_dir: &Path,
) -> Result<PathBuf> {
    ensure!(
        needle_source_binds_canonical_upstream(
            &artifact.source,
            artifact.upstream_source.as_ref(),
            NEEDLE_MODEL_REPO,
            mayhem_engine::NEEDLE_MODEL_REVISION,
        ) && artifact.path == NEEDLE_PRIMARY_PATH,
        "Needle artifact {label} must bind canonical upstream {NEEDLE_MODEL_REPO}@{} path {NEEDLE_PRIMARY_PATH}",
        mayhem_engine::NEEDLE_MODEL_REVISION
    );
    ensure!(
        artifact.sidecars.len() == NEEDLE_REQUIRED_SIDECARS.len()
            && artifact_paths.sidecars.len() == NEEDLE_REQUIRED_SIDECARS.len(),
        "Needle artifact {label} requires its exact seven signed sidecars and no extras"
    );

    let model_root = needle_checkpoint_cache_dir(cache_dir, artifact_name, artifact);
    fs::create_dir_all(&model_root)
        .with_context(|| format!("creating Needle model layout {}", model_root.display()))?;
    let primary = model_root.join(NEEDLE_PRIMARY_PATH);
    materialize_verified_ace_step_file(
        &artifact_paths.primary,
        &primary,
        artifact.weights_bytes,
        artifact
            .source_sha256
            .as_deref()
            .context("Needle primary artifact is missing source_sha256")?,
        "Needle primary artifact",
    )?;

    for (sidecar_name, expected_path, repo, revision) in NEEDLE_REQUIRED_SIDECARS {
        let sidecar = artifact
            .sidecars
            .get(*sidecar_name)
            .with_context(|| format!("Needle artifact {label} requires sidecar {sidecar_name}"))?;
        ensure!(
            needle_source_binds_canonical_upstream(
                &sidecar.source,
                sidecar.upstream_source.as_ref(),
                repo,
                revision,
            ) && sidecar.path == *expected_path,
            "Needle artifact {label} sidecar {sidecar_name} must bind {repo}@{revision} path {expected_path}"
        );
        let source = artifact_paths
            .sidecars
            .get(*sidecar_name)
            .with_context(|| {
                format!("downloaded Needle artifact {label} is missing sidecar {sidecar_name}")
            })?;
        materialize_verified_ace_step_file(
            source,
            &model_root.join(expected_path),
            sidecar.weights_bytes,
            &sidecar.source_sha256,
            &format!("Needle sidecar {sidecar_name}"),
        )?;
    }
    Ok(primary)
}

fn materialize_chatterbox_artifacts(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
    cache_dir: &Path,
) -> Result<PathBuf> {
    materialize_chatterbox_layout(
        &format!("{}/{}", selected.model.model_id, selected.artifact_name),
        &selected.artifact_name,
        &selected.artifact,
        artifact_paths,
        cache_dir,
    )
}

fn materialize_chatterbox_layout(
    label: &str,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    artifact_paths: &ProviderArtifactPaths,
    cache_dir: &Path,
) -> Result<PathBuf> {
    ensure!(
        chatterbox_source_binds_canonical_upstream(
            &artifact.source,
            artifact.upstream_source.as_ref()
        )
            && artifact.path == CHATTERBOX_PRIMARY_PATH,
        "Chatterbox artifact {label} must bind canonical upstream {CHATTERBOX_MODEL_REPO}@{} path {CHATTERBOX_PRIMARY_PATH}",
        mayhem_engine::CHATTERBOX_MODEL_REVISION
    );
    ensure!(
        artifact.sidecars.len() == CHATTERBOX_REQUIRED_SIDECARS.len()
            && artifact_paths.sidecars.len() == CHATTERBOX_REQUIRED_SIDECARS.len(),
        "Chatterbox artifact {label} requires its exact four signed sidecars and no extras"
    );

    let model_root = chatterbox_checkpoint_cache_dir(cache_dir, artifact_name, artifact);
    fs::create_dir_all(&model_root)
        .with_context(|| format!("creating Chatterbox model layout {}", model_root.display()))?;
    let primary = model_root.join(CHATTERBOX_PRIMARY_PATH);
    materialize_verified_ace_step_file(
        &artifact_paths.primary,
        &primary,
        artifact.weights_bytes,
        artifact
            .source_sha256
            .as_deref()
            .context("Chatterbox primary artifact is missing source_sha256")?,
        "Chatterbox primary artifact",
    )?;

    for (sidecar_name, expected_path) in CHATTERBOX_REQUIRED_SIDECARS {
        let sidecar = artifact.sidecars.get(*sidecar_name).with_context(|| {
            format!("Chatterbox artifact {label} requires sidecar {sidecar_name}")
        })?;
        ensure!(
            sidecar.source == artifact.source
                && chatterbox_source_binds_canonical_upstream(
                    &sidecar.source,
                    sidecar.upstream_source.as_ref()
                )
                && sidecar.path == *expected_path,
            "Chatterbox artifact {label} sidecar {sidecar_name} must share the primary release source and bind {CHATTERBOX_MODEL_REPO}@{} path {expected_path}",
            mayhem_engine::CHATTERBOX_MODEL_REVISION
        );
        let source = artifact_paths
            .sidecars
            .get(*sidecar_name)
            .with_context(|| {
                format!("downloaded Chatterbox artifact {label} is missing sidecar {sidecar_name}")
            })?;
        materialize_verified_ace_step_file(
            source,
            &model_root.join(expected_path),
            sidecar.weights_bytes,
            &sidecar.source_sha256,
            &format!("Chatterbox sidecar {sidecar_name}"),
        )?;
    }
    Ok(primary)
}

