fn materialize_ace_step_layout(
    label: &str,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    artifact_paths: &ProviderArtifactPaths,
    cache_dir: &Path,
) -> Result<PathBuf> {
    ensure!(
        artifact.path == "model.safetensors",
        "ACE-Step primary artifact must use path model.safetensors"
    );
    let model_root = ace_step_checkpoint_cache_dir(cache_dir, artifact_name, artifact);
    fs::create_dir_all(&model_root)
        .with_context(|| format!("creating ACE-Step model layout {}", model_root.display()))?;

    let primary = model_root.join(validate_catalog_artifact_relative_path(
        ACE_STEP_PRIMARY_DESTINATION,
    )?);
    materialize_verified_ace_step_file(
        &artifact_paths.primary,
        &primary,
        artifact.weights_bytes,
        artifact
            .source_sha256
            .as_deref()
            .context("ACE-Step primary artifact is missing source_sha256")?,
        "ACE-Step primary artifact",
    )?;

    for (sidecar_name, expected_source_path, destination_path) in ACE_STEP_REQUIRED_SIDECARS {
        let sidecar = artifact.sidecars.get(*sidecar_name).with_context(|| {
            format!("ACE-Step artifact {label} requires admin catalog sidecar {sidecar_name}")
        })?;
        ensure!(
            sidecar.path == *expected_source_path,
            "ACE-Step artifact {label} sidecar {} must use source path {}, got {}",
            sidecar_name,
            expected_source_path,
            sidecar.path
        );
        let source = artifact_paths
            .sidecars
            .get(*sidecar_name)
            .with_context(|| {
                format!(
                    "downloaded ACE-Step artifact {label} is missing admin sidecar {sidecar_name}"
                )
            })?;
        let destination =
            model_root.join(validate_catalog_artifact_relative_path(destination_path)?);
        materialize_verified_ace_step_file(
            source,
            &destination,
            sidecar.weights_bytes,
            &sidecar.source_sha256,
            sidecar_name,
        )
        .with_context(|| {
            format!(
                "materializing ACE-Step sidecar {} at {}",
                sidecar_name,
                destination.display()
            )
        })?;
    }
    ensure!(
        artifact.sidecars.len() == ACE_STEP_REQUIRED_SIDECARS.len(),
        "ACE-Step artifact {label} contains unapproved sidecars",
    );
    Ok(primary)
}

fn materialize_sulphur_artifacts(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
    cache_dir: &Path,
) -> Result<PathBuf> {
    materialize_sulphur_layout(
        &format!("{}/{}", selected.model.model_id, selected.artifact_name),
        &selected.artifact_name,
        &selected.artifact,
        artifact_paths,
        cache_dir,
    )
}

fn materialize_sulphur_layout(
    label: &str,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    artifact_paths: &ProviderArtifactPaths,
    cache_dir: &Path,
) -> Result<PathBuf> {
    let execution_flavor = sulphur_execution_flavor(artifact)
        .with_context(|| format!("Sulphur artifact {label} has an invalid execution flavor"))?;
    let primary_extension = Path::new(&artifact.path)
        .extension()
        .and_then(OsStr::to_str)
        .map(str::to_ascii_lowercase)
        .context("Sulphur primary artifact path has no extension")?;
    ensure!(
        primary_extension == execution_flavor.primary_extension(),
        "Sulphur artifact {label} signed execution flavor {} requires a .{} primary artifact, got .{primary_extension}",
        execution_flavor.runtime_manifest_path(),
        execution_flavor.primary_extension()
    );
    ensure!(
        artifact_paths.sidecars.len() == artifact.sidecars.len(),
        "downloaded Sulphur artifact {label} has an incomplete or unapproved sidecar set"
    );

    let model_root = sulphur_checkpoint_cache_dir(cache_dir, artifact_name, artifact);
    fs::create_dir_all(&model_root)
        .with_context(|| format!("creating Sulphur model layout {}", model_root.display()))?;

    let primary_relative = validate_catalog_artifact_relative_path(&artifact.path)?;
    let primary = model_root.join(&primary_relative);
    materialize_verified_ace_step_file(
        &artifact_paths.primary,
        &primary,
        artifact.weights_bytes,
        artifact
            .source_sha256
            .as_deref()
            .context("Sulphur primary artifact is missing source_sha256")?,
        "Sulphur primary artifact",
    )?;

    let mut occupied_paths = BTreeSet::from([primary_relative]);
    for (sidecar_name, sidecar) in &artifact.sidecars {
        let relative = validate_catalog_artifact_relative_path(&sidecar.path)?;
        ensure!(
            occupied_paths.insert(relative.clone()),
            "Sulphur artifact {label} declares duplicate path {}",
            sidecar.path
        );
        let source = artifact_paths.sidecars.get(sidecar_name).with_context(|| {
            format!("downloaded Sulphur artifact {label} is missing admin sidecar {sidecar_name}")
        })?;
        materialize_verified_ace_step_file(
            source,
            &model_root.join(relative),
            sidecar.weights_bytes,
            &sidecar.source_sha256,
            &format!("Sulphur sidecar {sidecar_name}"),
        )?;
    }

    if execution_flavor == SulphurExecutionFlavor::CudaGguf {
        Ok(primary)
    } else {
        let artifact_root = primary
            .parent()
            .context("Sulphur MLX primary artifact has no artifact root")?;
        ensure!(
            artifact_root != model_root,
            "Sulphur MLX primary artifact must live in its signed inner artifact directory"
        );
        Ok(artifact_root.to_path_buf())
    }
}

fn sulphur_load_config(artifact_path: &Path) -> Result<LoadConfig> {
    if artifact_path.is_dir() {
        return Ok(LoadConfig::mlx_safetensors(artifact_path));
    }
    match artifact_path
        .extension()
        .and_then(OsStr::to_str)
        .map(str::to_ascii_lowercase)
        .as_deref()
    {
        Some("gguf") => Ok(LoadConfig::gguf(artifact_path)),
        Some("safetensors") => Ok(LoadConfig::mlx_safetensors(artifact_path)),
        _ => bail!(
            "Sulphur materialized artifact {} is neither GGUF nor an MLX safetensors layout",
            artifact_path.display()
        ),
    }
}

fn bind_sulphur_primary_hash_path(
    load_artifact: &mut ModelArtifact,
    catalog_artifact: &catalog::CatalogArtifact,
) -> Result<()> {
    if !load_artifact.path.is_dir() {
        return Ok(());
    }
    let primary_name = Path::new(&catalog_artifact.path)
        .file_name()
        .context("Sulphur MLX primary artifact path has no file name")?;
    let primary_path = load_artifact.path.join(primary_name);
    ensure!(
        primary_path.is_file(),
        "Sulphur MLX primary artifact is missing from materialized layout {}",
        primary_path.display()
    );
    load_artifact.sha256_path = Some(primary_path);
    Ok(())
}

fn apply_sulphur_prompt_enhancer_load_config(
    config: &mut LoadConfig,
    artifact: &catalog::CatalogArtifact,
    sidecar_paths: &BTreeMap<String, PathBuf>,
) -> Result<()> {
    let model = artifact
        .sidecars
        .get(SULPHUR_PROMPT_ENHANCER_MODEL_SIDECAR)
        .context("Sulphur artifact is missing its signed prompt enhancer GGUF")?;
    ensure!(
        model.path == SULPHUR_PROMPT_ENHANCER_MODEL_PATH,
        "Sulphur prompt enhancer must use path {SULPHUR_PROMPT_ENHANCER_MODEL_PATH}, got {}",
        model.path
    );
    let projector = artifact
        .sidecars
        .get(SULPHUR_PROMPT_ENHANCER_PROJECTOR_SIDECAR)
        .context("Sulphur artifact is missing its signed prompt enhancer mmproj")?;
    ensure!(
        projector.path == SULPHUR_PROMPT_ENHANCER_PROJECTOR_PATH,
        "Sulphur prompt enhancer projector must use path {SULPHUR_PROMPT_ENHANCER_PROJECTOR_PATH}, got {}",
        projector.path
    );
    let model_path = sidecar_paths
        .get(SULPHUR_PROMPT_ENHANCER_MODEL_SIDECAR)
        .context("verified Sulphur prompt enhancer GGUF is unavailable")?;
    let projector_path = sidecar_paths
        .get(SULPHUR_PROMPT_ENHANCER_PROJECTOR_SIDECAR)
        .context("verified Sulphur prompt enhancer mmproj is unavailable")?;
    config.prompt_enhancer_model =
        Some(ModelArtifact::gguf(model_path).with_sha256(model.source_sha256.clone()));
    config.prompt_enhancer_projector =
        Some(ModelArtifact::gguf(projector_path).with_sha256(projector.source_sha256.clone()));
    Ok(())
}

fn materialize_verified_ace_step_file(
    source: &Path,
    destination: &Path,
    expected_bytes: u64,
    expected_sha256: &str,
    label: &str,
) -> Result<()> {
    if destination.exists() {
        let metadata = fs::symlink_metadata(destination).with_context(|| {
            format!(
                "inspecting existing materialized {label} {}",
                destination.display()
            )
        })?;
        ensure!(
            metadata.file_type().is_file(),
            "existing materialized {label} {} is not a regular file",
            destination.display()
        );
        if verify_materialized_ace_step_file(destination, expected_bytes, expected_sha256, label)
            .is_ok()
        {
            return Ok(());
        }
        make_materialized_file_replaceable(destination, &metadata, label)?;
        fs::remove_file(destination).with_context(|| {
            format!(
                "removing invalid materialized {label} {}",
                destination.display()
            )
        })?;
    }

    link_or_copy_file(source, destination)?;
    verify_materialized_ace_step_file(destination, expected_bytes, expected_sha256, label)
}

fn make_materialized_file_replaceable(
    path: &Path,
    metadata: &fs::Metadata,
    label: &str,
) -> Result<()> {
    #[cfg(windows)]
    {
        let mut permissions = metadata.permissions();
        if permissions.readonly() {
            permissions.set_readonly(false);
            fs::set_permissions(path, permissions).with_context(|| {
                format!(
                    "making invalid materialized {label} replaceable at {}",
                    path.display()
                )
            })?;
        }
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;

        let mut permissions = metadata.permissions();
        if permissions.readonly() {
            permissions.set_mode(permissions.mode() | 0o200);
            fs::set_permissions(path, permissions).with_context(|| {
                format!(
                    "making invalid materialized {label} replaceable at {}",
                    path.display()
                )
            })?;
        }
    }
    #[cfg(not(any(unix, windows)))]
    {
        let mut permissions = metadata.permissions();
        if permissions.readonly() {
            permissions.set_readonly(false);
            fs::set_permissions(path, permissions).with_context(|| {
                format!(
                    "making invalid materialized {label} replaceable at {}",
                    path.display()
                )
            })?;
        }
    }
    Ok(())
}

fn verify_materialized_ace_step_file(
    path: &Path,
    expected_bytes: u64,
    expected_sha256: &str,
    label: &str,
) -> Result<()> {
    let metadata = fs::metadata(path)
        .with_context(|| format!("reading materialized {label} {}", path.display()))?;
    ensure!(metadata.is_file(), "{label} is not a regular file");
    ensure!(
        metadata.len() == expected_bytes,
        "{label} size mismatch: expected {expected_bytes}, got {}",
        metadata.len()
    );
    let actual_sha256 = file_sha256_hex(path)?;
    ensure!(
        actual_sha256.eq_ignore_ascii_case(expected_sha256),
        "{label} SHA-256 mismatch: expected {expected_sha256}, got {actual_sha256}"
    );
    let mut permissions = metadata.permissions();
    permissions.set_readonly(true);
    fs::set_permissions(path, permissions)
        .with_context(|| format!("making materialized {label} read-only"))?;
    Ok(())
}

fn materialize_trt_llm_artifacts(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
) -> Result<TrtLlmMaterializedLayout> {
    let checkpoint_dir = if artifact_paths.primary.is_dir() {
        artifact_paths.primary.clone()
    } else {
        let checkpoint_dir =
            trt_checkpoint_cache_dir(&artifact_paths.primary, &selected.artifact_name);
        fs::create_dir_all(&checkpoint_dir).with_context(|| {
            format!(
                "creating TensorRT-LLM checkpoint layout {}",
                checkpoint_dir.display()
            )
        })?;
        let payload_name = catalog_path_file_name(
            &selected.artifact.path,
            "TensorRT-LLM primary checkpoint artifact",
        )?;
        link_or_copy_file(&artifact_paths.primary, &checkpoint_dir.join(payload_name))?;
        checkpoint_dir
    };

    for (sidecar, filename) in TRT_CHECKPOINT_REQUIRED_SIDECARS {
        materialize_trt_sidecar(
            selected,
            artifact_paths,
            sidecar,
            &checkpoint_dir,
            filename,
            true,
        )?;
    }
    for (sidecar, filename) in TRT_CHECKPOINT_OPTIONAL_SIDECARS {
        materialize_trt_sidecar(
            selected,
            artifact_paths,
            sidecar,
            &checkpoint_dir,
            filename,
            false,
        )?;
    }

    let engine_dir = trt_engine_cache_dir(&artifact_paths.primary, &selected.artifact_name);
    fs::create_dir_all(&engine_dir).with_context(|| {
        format!(
            "creating TensorRT-LLM engine layout {}",
            engine_dir.display()
        )
    })?;
    materialize_trt_sidecar(
        selected,
        artifact_paths,
        TRT_ENGINE_CONFIG_SIDECAR,
        &engine_dir,
        "config.json",
        true,
    )?;
    let tp_degree = enclave_tp_degree(&selected.enclave.caps)?;
    for rank in 0..tp_degree {
        let sidecar = format!("trt_engine_rank{rank}");
        let filename = format!("rank{rank}.engine");
        materialize_trt_sidecar(
            selected,
            artifact_paths,
            &sidecar,
            &engine_dir,
            &filename,
            true,
        )?;
    }

    Ok(TrtLlmMaterializedLayout {
        checkpoint_dir,
        engine_dir,
    })
}

fn materialize_trt_sidecar(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
    sidecar: &str,
    target_dir: &Path,
    filename: &str,
    required: bool,
) -> Result<()> {
    let destination = target_dir.join(filename);
    if destination.is_file() {
        return Ok(());
    }
    let Some(source) = artifact_paths.sidecars.get(sidecar) else {
        if required {
            bail!(
                "TensorRT-LLM artifact {}/{} requires admin catalog sidecar {} -> {}",
                selected.model.model_id,
                selected.artifact_name,
                sidecar,
                filename
            );
        }
        return Ok(());
    };
    link_or_copy_file(source, &destination).with_context(|| {
        format!(
            "materializing TensorRT-LLM sidecar {} at {}",
            sidecar,
            destination.display()
        )
    })
}

fn catalog_path_file_name(path: &str, label: &str) -> Result<String> {
    Path::new(path)
        .file_name()
        .and_then(OsStr::to_str)
        .filter(|name| !name.is_empty())
        .map(ToOwned::to_owned)
        .with_context(|| format!("{label} path {path} has no file name"))
}

fn link_or_copy_file(source: &Path, destination: &Path) -> Result<()> {
    if !source.is_file() {
        bail!("{} is not a file", source.display());
    }
    if let Some(parent) = destination.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    if destination.exists() {
        if same_canonical_path(source, destination) {
            return Ok(());
        }
        fs::remove_file(destination)
            .with_context(|| format!("removing stale {}", destination.display()))?;
    }
    if fs::hard_link(source, destination).is_err() {
        fs::copy(source, destination).with_context(|| {
            format!("copying {} to {}", source.display(), destination.display())
        })?;
    }
    Ok(())
}

fn same_canonical_path(left: &Path, right: &Path) -> bool {
    match (left.canonicalize(), right.canonicalize()) {
        (Ok(left), Ok(right)) => left == right,
        _ => false,
    }
}

fn provider_attestation_runtime_config(
    selected: &ProviderCandidate,
) -> Result<AttestationRuntimeConfig> {
    let ctx = u32::try_from(selected.served_ctx).with_context(|| {
        format!(
            "served ctx {} for {} exceeds attestation runtime config range",
            selected.served_ctx, selected.model.model_id
        )
    })?;
    let tp_degree = if matches!(selected.artifact.engine.as_str(), "trt-llm" | "vllm") {
        enclave_tp_degree(&selected.enclave.caps)?
    } else {
        1
    };
    let max_num_tokens = enclave_max_num_tokens(&selected.enclave.caps)?.map(|tokens| {
        if selected.artifact.engine == "trt-llm" {
            tokens.max(ctx)
        } else {
            tokens.max(1)
        }
    });
    Ok(AttestationRuntimeConfig {
        model_class: selected.enclave.model_class.clone(),
        backend: selected.artifact.engine.clone(),
        ctx,
        tp_degree,
        max_batch_size: enclave_max_batch_size(&selected.enclave.caps)?,
        max_num_tokens,
    })
}

fn trt_engine_cache_dir(artifact_path: &Path, artifact_name: &str) -> PathBuf {
    let base = if artifact_path.is_dir() {
        artifact_path.to_path_buf()
    } else {
        artifact_path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."))
    };
    base.join(".trtllm-engines")
        .join(safe_path_component(artifact_name))
}

fn trt_checkpoint_cache_dir(artifact_path: &Path, artifact_name: &str) -> PathBuf {
    let base = if artifact_path.is_dir() {
        artifact_path.to_path_buf()
    } else {
        artifact_path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."))
    };
    base.join(".trtllm-checkpoints")
        .join(safe_path_component(artifact_name))
}

fn vllm_checkpoint_cache_dir(artifact_path: &Path, artifact_name: &str) -> PathBuf {
    let base = if artifact_path.is_dir() {
        artifact_path.to_path_buf()
    } else {
        artifact_path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."))
    };
    base.join(".vllm-checkpoints")
        .join(safe_path_component(artifact_name))
}

fn mlx_model_cache_dir(
    artifact_path: &Path,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
) -> PathBuf {
    let base = if artifact_path.is_dir() {
        artifact_path.to_path_buf()
    } else {
        artifact_path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."))
    };
    let mut identity = blake3::Hasher::new();
    identity.update(b"mayhem/mlx/materialized-layout/v2\0");
    identity.update(artifact.artifact_root.as_bytes());
    identity.update(&(artifact.path.len() as u64).to_be_bytes());
    identity.update(artifact.path.as_bytes());
    for (name, sidecar) in &artifact.sidecars {
        identity.update(&(name.len() as u64).to_be_bytes());
        identity.update(name.as_bytes());
        identity.update(sidecar.artifact_root.as_bytes());
        identity.update(&(sidecar.path.len() as u64).to_be_bytes());
        identity.update(sidecar.path.as_bytes());
    }
    base.join(".mlx-models")
        .join(safe_path_component(artifact_name))
        .join(identity.finalize().to_hex().as_str())
}

fn transformers_asr_checkpoint_cache_dir(artifact_path: &Path, artifact_name: &str) -> PathBuf {
    let base = if artifact_path.is_dir() {
        artifact_path.to_path_buf()
    } else {
        artifact_path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."))
    };
    base.join(".transformers-asr-models")
        .join(safe_path_component(artifact_name))
}

fn needle_checkpoint_cache_dir(
    cache_dir: &Path,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
) -> PathBuf {
    let mut identity = blake3::Hasher::new();
    identity.update(b"mayhem/needle/materialized-layout/v1\0");
    identity.update(artifact.artifact_root.as_bytes());
    identity.update(&(artifact.path.len() as u64).to_be_bytes());
    identity.update(artifact.path.as_bytes());
    for (name, sidecar) in &artifact.sidecars {
        identity.update(&(name.len() as u64).to_be_bytes());
        identity.update(name.as_bytes());
        identity.update(sidecar.artifact_root.as_bytes());
        identity.update(&(sidecar.path.len() as u64).to_be_bytes());
        identity.update(sidecar.path.as_bytes());
    }
    cache_dir
        .join("models")
        .join(safe_path_component(artifact_name))
        .join(identity.finalize().to_hex().as_str())
}

