fn trt_kv_cache_dtype_for_artifact(
    _artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
) -> Option<String> {
    let mut haystack = String::new();
    if let Some(notes) = &artifact.notes {
        haystack.push_str(&notes.to_ascii_lowercase());
    }
    if haystack.contains("kv_cache_dtype=nvfp4")
        || haystack.contains("kv-cache-dtype=nvfp4")
        || haystack.contains("kv_cache_dtype: nvfp4")
        || haystack.contains("kv-cache-dtype: nvfp4")
    {
        Some("nvfp4".to_owned())
    } else if haystack.contains("kv_cache_dtype=fp8")
        || haystack.contains("kv-cache-dtype=fp8")
        || haystack.contains("kv_cache_dtype: fp8")
        || haystack.contains("kv-cache-dtype: fp8")
    {
        Some("fp8".to_owned())
    } else {
        None
    }
}

fn provider_session_terms(ctx: &ProviderSessionContext<'_>) -> Result<ProviderSessionTerms> {
    let price = ctx
        .selected
        .price
        .as_ref()
        .and_then(current_au_usd_price)
        .context("selected provider enclave has no current admin price")?;
    let started_at = unix_epoch_seconds()?;
    let served_ctx = u32::try_from(ctx.selected.served_ctx).unwrap_or(u32::MAX);
    let (ctx_bracket, ctx_bracket_table_ver) = if ctx.selected.enclave.model_class
        == DEFAULT_MODEL_CLASS
    {
        let (ctx_bracket, ctx_bracket_table_ver) = ctx_bracket_for_tokens_in_schedule(
            served_ctx,
            &ctx.selected.ctx_bracket_schedule,
            started_at,
        )
        .context("selected provider context is not covered by the active context bracket table")?;
        if price.ctx_bracket.as_deref() != Some(ctx_bracket.as_str()) {
            bail!(
                "selected provider enclave price is for context {:?}, but served context resolves to {ctx_bracket}",
                price.ctx_bracket
            );
        }
        (Some(ctx_bracket), Some(ctx_bracket_table_ver))
    } else {
        if price.ctx_bracket.is_some() {
            bail!("selected non-text provider enclave has an unexpected context-bracket price");
        }
        (None, None)
    };
    Ok(ProviderSessionTerms {
        contract_version: CONTRACT_VERSION,
        provider: ctx.wallet.public_key.clone(),
        enclave_id: ctx.selected.enclave.enclave_id.clone(),
        model_id: ctx.selected.enclave.model_id.clone(),
        adapter: ctx.selected.model.adapter.clone(),
        sampling: ctx.selected.model.sampling.clone(),
        output_modalities: if ctx.selected.model.caps.output_modalities.is_empty() {
            ctx.selected
                .model
                .caps
                .output_modality
                .iter()
                .cloned()
                .collect()
        } else {
            ctx.selected.model.caps.output_modalities.clone()
        },
        served_modalities: ctx.selected.served_modalities.clone(),
        served_specialities: ctx.selected.served_specialities.clone(),
        modality_capacities: ctx.selected.modality_capacities.clone(),
        room_ids: ctx.rooms.iter().map(|room| room.room_id.clone()).collect(),
        price_ver: price.ver,
        rate_map: price.rate_map.clone(),
        per_req_au: price.per_req_au,
        min_session_au: price.min_session_au,
        min_ask_au: ctx.args.min_ask_au,
        rules_ver: ctx.rules.ver,
        ctx: ctx.selected.served_ctx,
        ctx_bracket,
        ctx_bracket_table_ver,
        ctx_bracket_schedule: ctx.selected.ctx_bracket_schedule.clone(),
    })
}

fn provider_session_contract_decision(
    contract: &ContractCatalog,
    terms: &ProviderSessionTerms,
    startup_rooms: &[LedgerRoom],
    rail: &str,
) -> ProviderSessionDecision {
    let reject = |code, reason: String| ProviderSessionDecision::Reject { code, reason };
    if contract.rules.as_ref().map(|rules| rules.ver) != Some(terms.rules_ver) {
        return reject(
            "CONSENT",
            "current contract rules version no longer matches provider startup terms".to_owned(),
        );
    }
    let Some(provider_record) = contract
        .providers
        .iter()
        .find(|provider| provider.provider == terms.provider)
    else {
        return reject(
            "BANNED",
            "provider is no longer active in contract state".to_owned(),
        );
    };
    if provider_record.status != "active" {
        return reject(
            "BANNED",
            "provider is no longer active in contract state".to_owned(),
        );
    }
    if !provider_record
        .accepted_rails
        .iter()
        .any(|accepted| accepted == rail)
    {
        return reject(
            "RAIL",
            format!("provider does not accept the {rail} payment rail in contract state"),
        );
    }
    let Some(enclave) = contract
        .enclaves
        .iter()
        .find(|enclave| enclave.enclave_id == terms.enclave_id)
    else {
        return reject(
            "ENCLAVE",
            "admin enclave is no longer present in contract state".to_owned(),
        );
    };
    if enclave.status != "active" || enclave.model_id != terms.model_id {
        return reject(
            "ENCLAVE",
            "admin enclave is no longer active for this model".to_owned(),
        );
    }
    if !admin_role_marker_ok(enclave.created_by_role.as_deref()) {
        return reject(
            "ENCLAVE",
            "enclave record is explicitly not admin-created".to_owned(),
        );
    }
    let active_serve = contract.serves.iter().find(|serve| {
        serve.provider == terms.provider
            && serve.enclave_id == terms.enclave_id
            && serve.status == "active"
    });
    if active_serve.is_none() {
        return reject(
            "SERVE",
            "provider is no longer actively serving this admin enclave".to_owned(),
        );
    }
    if active_serve.map(|serve| serve.served_modalities.as_slice())
        != Some(terms.served_modalities.as_slice())
    {
        return reject(
            "SERVE",
            "provider committed modalities changed; restart against current contract state"
                .to_owned(),
        );
    }
    if active_serve.map(|serve| &serve.served_specialities) != Some(&terms.served_specialities) {
        return reject(
            "SERVE",
            "provider committed speciality levels changed; restart against current contract state"
                .to_owned(),
        );
    }
    let Some(schedule) = contract
        .prices
        .iter()
        .find(|price| price.enclave_id == terms.enclave_id)
    else {
        return reject(
            "PRICE_VER",
            "admin price schedule is no longer present for this enclave".to_owned(),
        );
    };
    if current_au_usd_price(schedule).is_none() {
        return reject(
            "PRICE_VER",
            "admin price schedule is no longer current au_usd".to_owned(),
        );
    };

    let startup_room_ids = terms.room_ids.iter().collect::<BTreeSet<_>>();
    let startup_rooms_by_id = startup_rooms
        .iter()
        .map(|room| (room.room_id.as_str(), room))
        .collect::<BTreeMap<_, _>>();
    let live_rooms_by_id = contract
        .rooms
        .iter()
        .map(|room| (room.room_id.as_str(), room))
        .collect::<BTreeMap<_, _>>();
    let has_active_roomserve = contract.roomserve.iter().any(|serving| {
        if serving.provider != terms.provider
            || serving.enclave_id != terms.enclave_id
            || serving.status != "active"
            || !startup_room_ids.contains(&serving.room_id)
        {
            return false;
        }
        let Some(startup_room) = startup_rooms_by_id.get(serving.room_id.as_str()) else {
            return false;
        };
        let Some(live_room) = live_rooms_by_id.get(serving.room_id.as_str()) else {
            return false;
        };
        live_room.status == "open"
            && admin_role_marker_ok(live_room.creator_role.as_deref())
            && admin_role_marker_ok(startup_room.creator_role.as_deref())
            && canonical_room_transport_ok(live_room)
            && canonical_room_transport_ok(startup_room)
            && room_matches_enclave(live_room, enclave)
            && room_matches_enclave(startup_room, enclave)
    });
    if !has_active_roomserve {
        return reject(
            "ROOM",
            "provider is no longer active in any startup canonical room".to_owned(),
        );
    }
    ProviderSessionDecision::Accept
}

async fn provider_session_spend_reservation_decision(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    enclave_pubkey: &str,
    terms: &ProviderSessionTerms,
    frame: &Value,
    rail: &str,
) -> Result<ProviderSessionDecision> {
    let reject = |reason: String| ProviderSessionDecision::Reject {
        code: "BALANCE",
        reason,
    };
    let voucher: SpendVoucher = match frame
        .get("voucher")
        .cloned()
        .context("s.open missing spend voucher")
        .and_then(|value| serde_json::from_value(value).context("invalid spend voucher"))
    {
        Ok(voucher) => voucher,
        Err(err) => return Ok(reject(format!("invalid spend reservation: {err:#}"))),
    };
    let active_epoch = active_billing_epoch(rpc).await?;
    if let Err(error) = validate_provider_session_voucher_epoch(&voucher, active_epoch) {
        return Ok(reject(error.to_string()));
    }
    let epoch = voucher.body.billing_epoch;
    let at = match provider_session_open_at(frame) {
        Ok(at) => at,
        Err(err) => return Ok(reject(format!("invalid spend reservation: {err:#}"))),
    };
    let payout_revision =
        match active_provider_payout_revision(rpc, &terms.provider, rail, epoch).await {
            Ok(revision) => revision,
            Err(err) => {
                return Ok(reject(format!(
                    "provider has no active verified {rail} payout binding: {err:#}"
                )))
            }
        };
    if payout_revision != voucher.body.payout_revision {
        return Ok(reject(
            "signed payout revision does not match the canonical active provider binding"
                .to_owned(),
        ));
    }
    let mut value = match provider_session_spend_reservation_value(
        terms,
        frame,
        rail,
        epoch,
        at,
        &payout_revision,
        enclave_pubkey,
    ) {
        Ok(value) => value,
        Err(err) => return Ok(reject(format!("invalid spend reservation: {err:#}"))),
    };
    let message = targeted_spend_reservation_message(&value);
    let provider_sig = sign_message(keypair_path, password, &message)
        .await
        .context("signing provider spend reservation")?;
    value["provider_sig"] = json!(provider_sig);
    let key = targeted_spend_reservation_feature_key(&value)?;
    // The local relay comes up shortly after the peer process; an admission that
    // races that window should wait it out (bounded) instead of rejecting the
    // session outright (observed live 2026-07-12: s.reject BALANCE on a relay that
    // became ready seconds later). Only relay-readiness errors retry; every other
    // failure rejects immediately as before.
    let retry_window = configured_nonnegative_millis(
        "MAYHEM_PROVIDER_ADMISSION_RELAY_RETRY_WINDOW_MS",
        DEFAULT_PROVIDER_ADMISSION_RELAY_RETRY_WINDOW_MILLIS,
    )?;
    let retry_interval = Duration::from_millis(configured_positive_millis(
        None,
        "MAYHEM_PROVIDER_ADMISSION_RELAY_RETRY_INTERVAL_MS",
        DEFAULT_PROVIDER_ADMISSION_RELAY_RETRY_INTERVAL_MILLIS,
        "provider admission relay retry interval",
    )?);
    let retry_deadline = Instant::now() + Duration::from_millis(retry_window);
    let submitted = loop {
        match rpc
            .submit_feature(json!({
                "feature": "mayhem",
                "key": key.clone(),
                "value": value.clone(),
            }))
            .await
        {
            Ok(submitted) => break submitted,
            Err(err) => {
                let message = format!("{err:#}");
                let relay_not_ready = message.contains("relay is not ready");
                if relay_not_ready && Instant::now() < retry_deadline {
                    provider_session_debug(format!(
                        "spend reservation waiting for local relay readiness; retrying: {message}"
                    ));
                    tokio::time::sleep(retry_interval).await;
                    continue;
                }
                return Ok(reject(format!(
                    "could not reserve user balance on contract before serving: {err}"
                )));
            }
        }
    };
    if submitted.get("ok").and_then(Value::as_bool) == Some(true) {
        return Ok(ProviderSessionDecision::Accept);
    }
    let reason = submitted
        .get("message")
        .and_then(Value::as_str)
        .map(str::to_owned)
        .or_else(|| {
            submitted
                .get("result")
                .and_then(|result| result.get("message"))
                .and_then(Value::as_str)
                .map(str::to_owned)
        })
        .unwrap_or_else(|| submitted.to_string());
    Ok(reject(format!(
        "contract spend reservation rejected before serving: {reason}"
    )))
}

fn validate_provider_session_voucher_epoch(
    voucher: &SpendVoucher,
    active_epoch: u64,
) -> Result<()> {
    ensure!(
        active_epoch > 0 && voucher.body.billing_epoch == active_epoch,
        "signed billing epoch {} is not the canonical active epoch {active_epoch}",
        voucher.body.billing_epoch
    );
    Ok(())
}

async fn active_billing_epoch(rpc: &PeerRpcClient) -> Result<u64> {
    let state = read_state_value(rpc, "epoch/apply/state").await?;
    active_billing_epoch_from_state(state.as_ref())
}

async fn active_provider_payout_revision(
    rpc: &PeerRpcClient,
    provider: &str,
    rail: &str,
    epoch: u64,
) -> Result<String> {
    ensure!(
        is_hex_len(provider, 64) && provider == provider.to_ascii_lowercase(),
        "provider payout identity must be 32-byte lower-case hexadecimal"
    );
    ensure!(
        matches!(rail, "tap" | "tnk" | "fiat"),
        "provider payout rail must be tap, tnk, or fiat"
    );
    let pointer_key = format!("payout/current/{rail}/{provider}");
    let pointer = read_state_value(rpc, &pointer_key)
        .await?
        .context("provider payout pointer is missing")?;
    let revision = payout_pointer_revision_at_epoch(&pointer, epoch)
        .context("provider payout pointer has no active revision")?
        .to_ascii_lowercase();
    ensure!(
        is_hex_len(&revision, 64),
        "provider payout pointer active revision is invalid"
    );
    let binding_key = format!("payout/binding/{rail}/{provider}/{revision}");
    let binding = read_state_value(rpc, &binding_key)
        .await?
        .context("active provider payout binding is missing")?;
    ensure!(
        binding.get("verified").and_then(Value::as_bool) == Some(true)
            && binding.get("provider").and_then(Value::as_str) == Some(provider)
            && binding.get("rail").and_then(Value::as_str) == Some(rail)
            && binding.get("revision").and_then(Value::as_str) == Some(revision.as_str())
            && binding
                .get("activation_epoch")
                .and_then(Value::as_u64)
                .is_some_and(|activation_epoch| activation_epoch <= epoch),
        "active provider payout binding does not match its immutable pointer"
    );
    if rail == "fiat" {
        ensure!(
            stripe_payout_binding_currently_ready(rpc, provider, &binding).await?,
            "active provider Stripe payout binding is not currently ready"
        );
    }
    Ok(revision)
}

async fn stripe_payout_binding_currently_ready(
    rpc: &PeerRpcClient,
    provider: &str,
    binding: &Value,
) -> Result<bool> {
    stripe_payout_binding_currently_ready_at(rpc, provider, binding, None).await
}

async fn stripe_payout_binding_currently_ready_at(
    rpc: &PeerRpcClient,
    provider: &str,
    binding: &Value,
    signed_length: Option<u64>,
) -> Result<bool> {
    async fn read(
        rpc: &PeerRpcClient,
        key: &str,
        signed_length: Option<u64>,
    ) -> Result<Option<Value>> {
        match signed_length {
            Some(signed_length) => read_state_value_at(rpc, key, signed_length).await,
            None => read_state_value(rpc, key).await,
        }
    }

    let Some(target) = binding.get("target").and_then(Value::as_str) else {
        return Ok(false);
    };
    let Some(pointer) = read(
        rpc,
        &format!("payout/stripe-verified/target/{provider}/{target}"),
        signed_length,
    )
    .await?
    else {
        return Ok(false);
    };
    if pointer.get("ready").and_then(Value::as_bool) != Some(true)
        || pointer.get("target").and_then(Value::as_str)
            != binding.get("target").and_then(Value::as_str)
        || pointer.get("processor_revision").and_then(Value::as_str)
            != binding
                .get("stripe_processor_revision")
                .and_then(Value::as_str)
    {
        return Ok(false);
    }
    let Some(record_key) = pointer.get("record_key").and_then(Value::as_str) else {
        return Ok(false);
    };
    let Some(record) = read(rpc, record_key, signed_length).await? else {
        return Ok(false);
    };
    Ok(
        record.get("type").and_then(Value::as_str) == Some("stripe_payout_verification")
            && record.get("provider").and_then(Value::as_str) == Some(provider)
            && record.get("target").and_then(Value::as_str) == Some(target)
            && record.get("currency").and_then(Value::as_str)
                == binding.get("currency").and_then(Value::as_str)
            && record.get("ready").and_then(Value::as_bool) == Some(true)
            && record.get("processor_revision").and_then(Value::as_str)
                == binding
                    .get("stripe_processor_revision")
                    .and_then(Value::as_str),
    )
}

fn payout_pointer_revision_at_epoch(pointer: &Value, epoch: u64) -> Option<&str> {
    pointer
        .get("pending_revision")
        .and_then(Value::as_str)
        .zip(
            pointer
                .get("pending_activation_epoch")
                .and_then(Value::as_u64),
        )
        .filter(|(_, activation_epoch)| *activation_epoch <= epoch)
        .map(|(revision, _)| revision)
        .or_else(|| pointer.get("current_revision").and_then(Value::as_str))
}

fn active_billing_epoch_from_state(state: Option<&Value>) -> Result<u64> {
    let updated_epoch = state
        .context(
            "epoch/apply/state is unavailable; the read-only contract replica is not synchronized",
        )?
        .get("updated_epoch")
        .and_then(Value::as_u64)
        .context("epoch/apply/state missing updated_epoch")?;
    updated_epoch
        .checked_add(1)
        .context("active billing epoch overflowed")
}

fn provider_session_spend_reservation_value(
    terms: &ProviderSessionTerms,
    frame: &Value,
    rail: &str,
    epoch: u64,
    at: u64,
    payout_revision: &str,
    enclave_pubkey: &str,
) -> Result<Value> {
    let session_id = frame
        .get("session_id")
        .and_then(Value::as_str)
        .context("s.open missing session_id")?;
    let user = frame
        .get("user")
        .and_then(Value::as_str)
        .context("s.open missing user")?;
    let voucher = frame
        .get("voucher")
        .cloned()
        .context("s.open missing spend voucher")?;
    let spend_voucher: SpendVoucher =
        serde_json::from_value(voucher.clone()).context("invalid spend voucher")?;
    ensure!(
        is_hex_len(payout_revision, 64) && payout_revision == payout_revision.to_ascii_lowercase(),
        "active payout revision must be 32-byte lower-case hexadecimal"
    );
    ensure!(
        is_hex_len(enclave_pubkey, 64) && enclave_pubkey == enclave_pubkey.to_ascii_lowercase(),
        "runtime enclave public key must be 32-byte lower-case hexadecimal"
    );
    Ok(json!({
        "op": "spend_reserve_targeted",
        "payout_revision": payout_revision,
        "reservation_id": spend_voucher.body.reservation_id,
        "reservation_expires_after_epoch": spend_voucher.body.reservation_expires_after_epoch,
        "reservation_receipt_grace_epochs": spend_voucher.body.reservation_receipt_grace_epochs,
        "contract_version": CONTRACT_VERSION,
        "session_id": session_id,
        "epoch": epoch,
        "at": at,
        "rail": rail,
        "user": user,
        "provider": terms.provider,
        "enclave_id": terms.enclave_id,
        "enclave_pubkey": enclave_pubkey,
        "model_id": terms.model_id,
        "price_ver": spend_voucher.body.price_ver,
        "rules_ver": terms.rules_ver,
        "served_ctx": spend_voucher.body.served_ctx,
        "required_modalities": spend_voucher.body.required_modalities,
        "required_specialities": spend_voucher.body.required_specialities,
        "ctx_bracket": spend_voucher.body.ctx_bracket,
        "ctx_bracket_table_ver": spend_voucher.body.ctx_bracket_table_ver,
        "max_spend_au": money_au_json(spend_voucher.body.max_spend_au),
        "voucher": voucher,
        "provider_sig": "",
    }))
}

fn spend_reservation_evidence(value: &Value) -> Value {
    let mut voucher = stable_json_value(value.get("voucher").unwrap_or(&Value::Null));
    if let Value::Object(voucher) = &mut voucher {
        if voucher
            .get("required_specialities")
            .and_then(Value::as_object)
            .is_some_and(Map::is_empty)
        {
            voucher.remove("required_specialities");
        }
    }
    let mut evidence = json!({
        "contract_version": value.get("contract_version").cloned().unwrap_or(Value::Null),
        "session_id": value.get("session_id").cloned().unwrap_or(Value::Null),
        "reservation_id": value.get("reservation_id").cloned().unwrap_or(Value::Null),
        "reservation_expires_after_epoch": value.get("reservation_expires_after_epoch").cloned().unwrap_or(Value::Null),
        "reservation_receipt_grace_epochs": value.get("reservation_receipt_grace_epochs").cloned().unwrap_or(Value::Null),
        "epoch": value.get("epoch").cloned().unwrap_or(Value::Null),
        "at": value.get("at").cloned().unwrap_or(Value::Null),
        "rail": value.get("rail").cloned().unwrap_or(Value::Null),
        "user": value.get("user").cloned().unwrap_or(Value::Null),
        "provider": value.get("provider").cloned().unwrap_or(Value::Null),
        "enclave_id": value.get("enclave_id").cloned().unwrap_or(Value::Null),
        "enclave_pubkey": value.get("enclave_pubkey").cloned().unwrap_or(Value::Null),
        "model_id": value.get("model_id").cloned().unwrap_or(Value::Null),
        "price_ver": value.get("price_ver").cloned().unwrap_or(Value::Null),
        "rules_ver": value.get("rules_ver").cloned().unwrap_or(Value::Null),
        "served_ctx": value.get("served_ctx").cloned().unwrap_or(Value::Null),
        "required_modalities": value.get("required_modalities").cloned().unwrap_or(Value::Null),
        "ctx_bracket": value.get("ctx_bracket").cloned().unwrap_or(Value::Null),
        "ctx_bracket_table_ver": value.get("ctx_bracket_table_ver").cloned().unwrap_or(Value::Null),
        "max_spend_au": value.get("max_spend_au").cloned().unwrap_or(Value::Null),
        "voucher": voucher,
    });
    if value
        .get("required_specialities")
        .and_then(Value::as_object)
        .is_some_and(|specialities| !specialities.is_empty())
    {
        evidence["required_specialities"] =
            stable_json_value(value.get("required_specialities").unwrap());
    }
    evidence
}

fn targeted_spend_reservation_message(value: &Value) -> String {
    format!(
        "mayhem-targeted-spend-reservation-v1{}",
        stable_json_value(&json!({
            "payout_revision": value.get("payout_revision").cloned().unwrap_or(Value::Null),
            "reservation": spend_reservation_evidence(value),
        }))
    )
}

fn targeted_spend_reservation_feature_key(value: &Value) -> Result<String> {
    let rail = value
        .get("rail")
        .and_then(Value::as_str)
        .context("spend reservation missing rail")?;
    let user = value
        .get("user")
        .and_then(Value::as_str)
        .context("spend reservation missing user")?;
    let epoch = value
        .get("epoch")
        .and_then(Value::as_u64)
        .context("spend reservation missing epoch")?;
    let session_id = value
        .get("session_id")
        .and_then(Value::as_str)
        .context("spend reservation missing session_id")?;
    let payout_revision = value
        .get("payout_revision")
        .and_then(Value::as_str)
        .filter(|revision| is_hex_len(revision, 64) && *revision == revision.to_ascii_lowercase())
        .context("targeted spend reservation missing payout revision")?;
    let digest = stable_value_hash(&json!({
        "domain": "mayhem-targeted-spend-reservation-feature-v1",
        "value": {
            "payout_revision": payout_revision,
            "reservation": spend_reservation_evidence(value),
        },
    }));
    Ok(format!(
        "hold/targeted/{rail}/{user}/{epoch}/{session_id}/{digest}"
    ))
}

fn provider_session_open_at(frame: &Value) -> Result<u64> {
    frame
        .get("at")
        .and_then(Value::as_u64)
        .context("s.open missing contract policy timestamp at")
}

fn provider_session_open_targets_enclave(frame: &Value, terms: &ProviderSessionTerms) -> bool {
    frame.get("enclave_id").and_then(Value::as_str) == Some(terms.enclave_id.as_str())
}

fn provider_session_open_decision(
    frame: &Value,
    terms: &ProviderSessionTerms,
) -> ProviderSessionDecision {
    let reject = |code, reason: String| ProviderSessionDecision::Reject { code, reason };
    if frame.get("t").and_then(Value::as_str) != Some("s.open") {
        return reject("SCHEMA", "session open frame must have t=s.open".to_owned());
    }
    let actual_contract_version = frame_contract_version(frame);
    if actual_contract_version != Some(terms.contract_version) {
        return reject(
            "UPGRADE_REQUIRED",
            contract_upgrade_required_reason(terms.contract_version, actual_contract_version),
        );
    }
    let session_id = frame
        .get("session_id")
        .and_then(Value::as_str)
        .unwrap_or("");
    if !is_hex_len(session_id, 64) {
        return reject("SCHEMA", "session_id must be 32 bytes of hex".to_owned());
    }
    let user = frame.get("user").and_then(Value::as_str).unwrap_or("");
    if !is_hex_len(user, 64) {
        return reject("USER", "session user must be 32 bytes of hex".to_owned());
    }
    let att_nonce = frame.get("att_nonce").and_then(Value::as_str).unwrap_or("");
    if !is_hex_len(att_nonce, 64) {
        return reject(
            "ATTESTATION",
            "att_nonce must be 32 bytes of hex".to_owned(),
        );
    }
    if !provider_session_open_targets_enclave(frame, terms) {
        return reject(
            "ENCLAVE",
            "session enclave_id is not this admin-created enclave".to_owned(),
        );
    }
    let Some(frame_price_ver) = frame.get("price_ver").and_then(Value::as_u64) else {
        return reject("PRICE_VER", "session price_ver is missing".to_owned());
    };
    if frame_price_ver != terms.price_ver {
        return reject(
            "PRICE_VER",
            "session price_ver does not match this admin-created enclave".to_owned(),
        );
    }
    let Some(opened_at) = frame.get("at").and_then(Value::as_u64) else {
        return reject(
            "SCHEMA",
            "session open frame is missing contract policy timestamp at".to_owned(),
        );
    };
    if frame.get("rules_ver").and_then(Value::as_u64) != Some(terms.rules_ver) {
        return reject(
            "CONSENT",
            "session rules_ver does not match current rules".to_owned(),
        );
    }
    let rail = provider_session_frame_rail(frame).unwrap_or("");
    if !matches!(rail, "fiat" | "tap" | "tnk") {
        return reject(
            "RAIL",
            "session rail must be one of fiat, tap, or tnk".to_owned(),
        );
    }
    let voucher = match frame
        .get("voucher")
        .cloned()
        .ok_or_else(|| anyhow::anyhow!("missing voucher"))
        .and_then(|voucher| {
            serde_json::from_value::<SpendVoucher>(voucher).context("invalid spend voucher")
        }) {
        Ok(voucher) => voucher,
        Err(err) => return reject("VOUCHER", format!("{err:#}")),
    };
    if voucher.body.session_id.as_str() != session_id {
        return reject("VOUCHER", "voucher session_id mismatch".to_owned());
    }
    if !is_hex_len(&voucher.body.billing_id, 64) {
        return reject(
            "VOUCHER",
            "voucher billing_id must be 32 bytes of hex".to_owned(),
        );
    }
    if voucher.body.billing_attempt == 0
        && (voucher.body.billing_prior_usage != ReceiptUsage::default()
            || voucher.body.billing_prior_au_owed_cum != 0)
    {
        return reject(
            "VOUCHER",
            "initial billing attempt must have an empty cumulative baseline".to_owned(),
        );
    }
    if voucher.body.billing_prior_au_owed_cum == 0
        && voucher.body.billing_prior_usage != ReceiptUsage::default()
    {
        return reject(
            "VOUCHER",
            "billing prior usage requires a nonzero cumulative amount".to_owned(),
        );
    }
    if voucher.body.billing_epoch == 0 {
        return reject(
            "VOUCHER",
            "voucher billing_epoch must be positive".to_owned(),
        );
    }
    if !is_hex_len(&voucher.body.reservation_id, 64)
        || voucher.body.reservation_id != voucher.body.reservation_id.to_ascii_lowercase()
    {
        return reject(
            "VOUCHER",
            "voucher reservation_id must be 32-byte lower-case hexadecimal".to_owned(),
        );
    }
    if voucher.body.user != user {
        return reject("VOUCHER", "voucher user mismatch".to_owned());
    }
    if voucher.body.provider != terms.provider {
        return reject("VOUCHER", "voucher provider mismatch".to_owned());
    }
    if !is_hex_len(&voucher.body.payout_revision, 64)
        || voucher.body.payout_revision != voucher.body.payout_revision.to_ascii_lowercase()
    {
        return reject(
            "VOUCHER",
            "voucher payout_revision must be 32-byte lower-case hexadecimal".to_owned(),
        );
    }
    if voucher.body.model_id != terms.model_id {
        return reject("VOUCHER", "voucher model_id mismatch".to_owned());
    }
    if voucher.body.rules_ver != terms.rules_ver {
        return reject("VOUCHER", "voucher rules_ver mismatch".to_owned());
    }
    if voucher.body.rail.as_str() != rail {
        return reject("VOUCHER", "voucher rail mismatch".to_owned());
    }
    if voucher.body.enclave_id.as_str() != terms.enclave_id.as_str() {
        return reject("VOUCHER", "voucher enclave_id mismatch".to_owned());
    }
    if voucher.body.price_ver != frame_price_ver {
        return reject("VOUCHER", "voucher price_ver mismatch".to_owned());
    }
    if voucher.body.locked_rate_map.is_empty() {
        return reject("VOUCHER", "voucher locked_rate_map is empty".to_owned());
    }
    if normalize_rate_map(voucher.body.locked_rate_map.clone()) != voucher.body.locked_rate_map {
        return reject(
            "VOUCHER",
            "voucher locked_rate_map must be canonical".to_owned(),
        );
    }
    if voucher.body.locked_rate_map != normalize_rate_map(terms.rate_map.clone()) {
        return reject(
            "VOUCHER",
            "voucher locked_rate_map does not match admin price".to_owned(),
        );
    }
    if voucher.body.locked_per_req_au != terms.per_req_au {
        return reject(
            "VOUCHER",
            "voucher locked_per_req_au does not match admin price".to_owned(),
        );
    }
    if voucher.body.locked_min_session_au != terms.min_session_au {
        return reject(
            "VOUCHER",
            "voucher locked_min_session_au does not match admin price".to_owned(),
        );
    }
    if u64::from(voucher.body.served_ctx) != terms.ctx {
        return reject(
            "VOUCHER",
            "voucher served_ctx does not match provider committed context".to_owned(),
        );
    }
    if let Err(err) = validate_provider_session_modalities(
        &voucher.body.required_modalities,
        &terms.served_modalities,
    ) {
        return reject("MODALITY", err.to_string());
    }
    if let Err(err) = validate_provider_session_specialities(
        &voucher.body.required_specialities,
        &terms.served_specialities,
    ) {
        return reject("SPECIALITY", err.to_string());
    }
    if frame.get("served_ctx").and_then(Value::as_u64) != Some(u64::from(voucher.body.served_ctx)) {
        return reject("VOUCHER", "frame served_ctx mismatch".to_owned());
    }
    let frame_ctx_bracket = match frame.get("ctx_bracket").unwrap_or(&Value::Null) {
        Value::Null => None,
        Value::String(value) => Some(value.clone()),
        _ => return reject("VOUCHER", "frame ctx_bracket mismatch".to_owned()),
    };
    if frame_ctx_bracket != voucher.body.ctx_bracket {
        return reject("VOUCHER", "frame ctx_bracket mismatch".to_owned());
    }
    let frame_ctx_bracket_table_ver = match frame
        .get("ctx_bracket_table_ver")
        .unwrap_or(&Value::Null)
    {
        Value::Null => None,
        Value::Number(value) => match value.as_u64().and_then(|value| u32::try_from(value).ok()) {
            Some(value) => Some(value),
            None => return reject("VOUCHER", "frame ctx_bracket_table_ver mismatch".to_owned()),
        },
        _ => return reject("VOUCHER", "frame ctx_bracket_table_ver mismatch".to_owned()),
    };
    if frame_ctx_bracket_table_ver != voucher.body.ctx_bracket_table_ver {
        return reject("VOUCHER", "frame ctx_bracket_table_ver mismatch".to_owned());
    }
    if voucher.body.ctx_bracket != terms.ctx_bracket {
        return reject(
            "VOUCHER",
            "voucher ctx_bracket does not match provider price context".to_owned(),
        );
    }
    if voucher.body.ctx_bracket_table_ver != terms.ctx_bracket_table_ver {
        return reject(
            "VOUCHER",
            "voucher ctx_bracket_table_ver does not match provider price context".to_owned(),
        );
    }
    if let (Some(_), Some(_)) = (&terms.ctx_bracket, terms.ctx_bracket_table_ver) {
        let Some((expected_ctx_bracket, expected_ctx_bracket_table_ver)) =
            ctx_bracket_for_tokens_in_schedule(
                voucher.body.served_ctx,
                &terms.ctx_bracket_schedule,
                opened_at,
            )
        else {
            return reject(
                "VOUCHER",
                "active context bracket table does not cover served_ctx".to_owned(),
            );
        };
        if voucher.body.ctx_bracket.as_deref() != Some(expected_ctx_bracket.as_str()) {
            return reject(
                "VOUCHER",
                "voucher ctx_bracket does not match active admin context table".to_owned(),
            );
        }
        if voucher.body.ctx_bracket_table_ver != Some(expected_ctx_bracket_table_ver) {
            return reject(
                "VOUCHER",
                "voucher ctx_bracket_table_ver does not match active admin context table"
                    .to_owned(),
            );
        }
    }
    if voucher.body.max_spend_au == 0 {
        return reject(
            "BALANCE",
            "voucher max_spend_au must be positive".to_owned(),
        );
    }
    let market_rate_au = rate_gate_basis_au(
        &voucher.body.locked_rate_map,
        voucher.body.locked_per_req_au,
        voucher.body.locked_min_session_au,
    );
    if market_rate_au < terms.min_ask_au {
        return reject(
            "PRICE_FLOOR",
            format!(
                "market rate basis {} is below provider minimum ask {}",
                au_to_usd_amount(market_rate_au),
                au_to_usd_amount(terms.min_ask_au)
            ),
        );
    }
    if frame.get("sig").and_then(Value::as_str) != Some(voucher.user_sig.as_str()) {
        return reject(
            "SIGNATURE",
            "session open signature must match voucher user_sig".to_owned(),
        );
    }
    if let Err(err) = verify_provider_session_spend_voucher(&voucher, user) {
        return reject("SIGNATURE", format!("{err:#}"));
    }
    ProviderSessionDecision::Accept
}

fn provider_session_frame_rail(frame: &Value) -> Option<&str> {
    frame.get("rail").and_then(Value::as_str)
}

fn provider_session_frame_checkpoint_policy(frame: &Value) -> Option<CheckpointPolicy> {
    frame
        .get("voucher")
        .and_then(|voucher| voucher.get("checkpoint_every"))
        .cloned()
        .and_then(|policy| serde_json::from_value::<CheckpointPolicy>(policy).ok())
}

fn frame_contract_version(frame: &Value) -> Option<u32> {
    frame
        .get("contract_version")
        .and_then(Value::as_u64)
        .and_then(|version| u32::try_from(version).ok())
}

fn contract_upgrade_required_reason(expected: u32, actual: Option<u32>) -> String {
    let actual = actual
        .map(|version| version.to_string())
        .unwrap_or_else(|| "missing/outdated".to_owned());
    format!(
        "contract upgrade required: expected CONTRACT_VERSION {expected}, got {actual}; update Mayhem on the out-of-sync node before opening sessions"
    )
}

fn verify_provider_session_spend_voucher(voucher: &SpendVoucher, user_pubkey: &str) -> Result<()> {
    ensure!(
        voucher.body.schema_version == SESSION_RECEIPT_SCHEMA_VERSION,
        "spend voucher schema_version must be {SESSION_RECEIPT_SCHEMA_VERSION}"
    );
    let key_bytes = hex_decode_array::<32>(user_pubkey, "spend voucher user pubkey")?;
    let sig_bytes = hex_decode_array::<64>(&voucher.user_sig, "spend voucher user signature")?;
    let verifying_key =
        VerifyingKey::from_bytes(&key_bytes).context("invalid spend voucher user pubkey")?;
    let signature = Signature::from_bytes(&sig_bytes);
    let payload = spend_voucher_signing_bytes(&voucher.body)?;
    verifying_key
        .verify_strict(&payload, &signature)
        .context("spend voucher user signature failed")
}

#[derive(Clone, Debug, PartialEq)]
struct ProviderSessionArtifact {
    id: String,
    content_type: String,
    bytes: Vec<u8>,
}

#[derive(Debug)]
struct ProviderSessionArtifactBuilder {
    content_type: String,
    bytes: Vec<u8>,
    next_index: u32,
    final_seen: bool,
}

#[derive(Debug)]
struct ProviderSessionArtifactCollector {
    artifacts: BTreeMap<String, ProviderSessionArtifactBuilder>,
    total_bytes: usize,
    max_bytes: usize,
    max_artifacts: usize,
}

impl ProviderSessionArtifactCollector {
    fn configured() -> Self {
        Self {
            artifacts: BTreeMap::new(),
            total_bytes: 0,
            max_bytes: provider_session_configured_limit(
                "MAYHEM_SESSION_MAX_ARTIFACT_BYTES",
                DEFAULT_PROVIDER_SESSION_MAX_ARTIFACT_BYTES,
            ),
            max_artifacts: provider_session_configured_limit(
                "MAYHEM_SESSION_MAX_ARTIFACTS",
                DEFAULT_PROVIDER_SESSION_MAX_ARTIFACTS,
            ),
        }
    }

    #[cfg(test)]
    fn with_limits(max_bytes: usize, max_artifacts: usize) -> Self {
        Self {
            artifacts: BTreeMap::new(),
            total_bytes: 0,
            max_bytes,
            max_artifacts,
        }
    }

    fn push(&mut self, chunk: ArtifactChunk) -> mayhem_engine::Result<()> {
        let artifact_id = chunk.artifact_id.trim();
        if artifact_id.is_empty() {
            return Err(EngineError::InvalidConfig(
                "provider engine emitted artifact chunk with empty id".to_owned(),
            ));
        }
        if chunk.content_type.trim().is_empty() {
            return Err(EngineError::InvalidConfig(format!(
                "provider engine emitted artifact {artifact_id} with empty content type"
            )));
        }
        if !self.artifacts.contains_key(artifact_id) && self.artifacts.len() >= self.max_artifacts {
            return Err(EngineError::InvalidConfig(format!(
                "provider engine emitted more than {} session artifacts",
                self.max_artifacts
            )));
        }
        let next_total = self
            .total_bytes
            .checked_add(chunk.bytes.len())
            .ok_or_else(|| {
                EngineError::InvalidConfig(
                    "provider engine artifact byte count overflow".to_owned(),
                )
            })?;
        if next_total > self.max_bytes {
            return Err(EngineError::InvalidConfig(format!(
                "provider engine artifacts exceed the session byte budget of {} bytes",
                self.max_bytes
            )));
        }

        let builder = self
            .artifacts
            .entry(chunk.artifact_id.clone())
            .or_insert_with(|| ProviderSessionArtifactBuilder {
                content_type: chunk.content_type.clone(),
                bytes: Vec::new(),
                next_index: 0,
                final_seen: false,
            });
        if builder.final_seen {
            return Err(EngineError::InvalidConfig(format!(
                "provider engine artifact {artifact_id} emitted data after its final chunk"
            )));
        }
        if builder.content_type != chunk.content_type {
            return Err(EngineError::InvalidConfig(format!(
                "provider engine artifact {artifact_id} changed content type mid-stream"
            )));
        }
        if builder.next_index != chunk.index {
            return Err(EngineError::InvalidConfig(format!(
                "provider engine artifact {artifact_id} chunk index gap: expected {}, got {}",
                builder.next_index, chunk.index
            )));
        }
        builder.bytes.extend_from_slice(&chunk.bytes);
        builder.next_index = builder.next_index.checked_add(1).ok_or_else(|| {
            EngineError::InvalidConfig(format!(
                "provider engine artifact {artifact_id} chunk index overflow"
            ))
        })?;
        builder.final_seen = chunk.final_chunk;
        self.total_bytes = next_total;
        Ok(())
    }

    fn finish(self) -> Result<Vec<ProviderSessionArtifact>> {
        self.artifacts
            .into_iter()
            .map(|(id, artifact)| {
                ensure!(
                    artifact.final_seen,
                    "provider engine artifact {id} missing final chunk marker"
                );
                Ok(ProviderSessionArtifact {
                    id,
                    content_type: artifact.content_type,
                    bytes: artifact.bytes,
                })
            })
            .collect()
    }
}

#[derive(Clone, Debug, PartialEq)]
struct ProviderSessionOutput {
    content: String,
    reasoning_evidence: String,
    tools: Vec<Value>,
    embeddings: Option<Vec<Vec<f32>>>,
    transcription: Option<TranscriptionResult>,
    artifacts: Vec<ProviderSessionArtifact>,
    finish_reason: String,
    prompt_tokens: u64,
    completion_tokens: u64,
    token_ids: Vec<i32>,
    usage: ReceiptUsage,
    usage_attribution: BTreeMap<String, u64>,
}

fn provider_visible_tool_calls(tools: &[Value]) -> Result<Vec<VisibleToolCall>> {
    tools
        .iter()
        .map(|tool| {
            Ok(VisibleToolCall {
                id: tool
                    .get("id")
                    .and_then(Value::as_str)
                    .context("provider tool output missing id")?
                    .to_owned(),
                name: tool
                    .get("name")
                    .and_then(Value::as_str)
                    .context("provider tool output missing name")?
                    .to_owned(),
                arguments: tool
                    .get("arguments")
                    .and_then(Value::as_str)
                    .context("provider tool output missing arguments")?
                    .to_owned(),
            })
        })
        .collect()
}

fn normalize_provider_visible_output_usage(
    body: &Value,
    output: &mut ProviderSessionOutput,
) -> Result<()> {
    let endpoint_family = body
        .get("mayhem_contract")
        .and_then(|value| value.get("endpoint_family"))
        .and_then(Value::as_str);
    let is_text_generation = body.get("kind").is_none()
        || matches!(
            endpoint_family,
            Some(
                mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS
                    | mayhem_proto::ENDPOINT_OPENAI_COMPLETIONS
                    | mayhem_proto::ENDPOINT_OPENAI_RESPONSES
                    | mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT
            )
        );
    if !is_text_generation {
        return Ok(());
    }
    let tools = provider_visible_tool_calls(&output.tools)?;
    let metered_units = metered_output_units(&output.content, &output.reasoning_evidence, &tools);
    output.completion_tokens = metered_units;
    output.usage = ReceiptUsage::from_units(
        output
            .usage
            .units()
            .iter()
            .filter(|(unit, _)| unit.as_str() != USAGE_OUTPUT_TOKEN)
            .map(|(unit, count)| (unit.clone(), *count))
            .chain([(USAGE_OUTPUT_TOKEN.to_owned(), metered_units)]),
    );
    let reasoning_units = metered_output_units("", &output.reasoning_evidence, &[]);
    if reasoning_units > 0 {
        output
            .usage_attribution
            .insert("reasoning_output_tokens".to_owned(), reasoning_units);
    } else {
        output.usage_attribution.remove("reasoning_output_tokens");
    }
    Ok(())
}

fn provider_reasoning_usage_attribution(reasoning_evidence: &str) -> BTreeMap<String, u64> {
    let reasoning_units = metered_output_units("", reasoning_evidence, &[]);
    if reasoning_units == 0 {
        BTreeMap::new()
    } else {
        BTreeMap::from([("reasoning_output_tokens".to_owned(), reasoning_units)])
    }
}

fn validate_provider_session_output(
    terms: &ProviderSessionTerms,
    body: &Value,
    output: &ProviderSessionOutput,
) -> Result<()> {
    let payload_limit = provider_session_configured_limit(
        "MAYHEM_SESSION_MAX_REASSEMBLED_PAYLOAD_BYTES",
        DEFAULT_SESSION_MAX_REASSEMBLED_PAYLOAD_BYTES,
    );
    if body.get("kind").and_then(Value::as_str).is_none() {
        let available_tokens = terms.ctx.saturating_sub(output.prompt_tokens);
        let max_output_tokens = provider_requested_max_output_tokens(body)
            .unwrap_or(available_tokens)
            .min(available_tokens);
        let max_visible_output_units =
            max_output_tokens.saturating_mul(MAX_VISIBLE_OUTPUT_UNITS_PER_REQUEST_TOKEN);
        ensure!(
            output.completion_tokens <= max_visible_output_units,
            "provider visible output exceeded the selected session byte-derived unit budget"
        );
        ensure!(
            u64::try_from(output.token_ids.len()).unwrap_or(u64::MAX) <= max_output_tokens,
            "provider token ids exceeded the selected session token budget"
        );
    } else {
        ensure!(
            output.content.len() <= payload_limit,
            "provider modality text output exceeds the session payload budget"
        );
    }
    if !output.tools.is_empty() {
        ensure!(
            provider_session_serialized_len(&output.tools)? <= payload_limit,
            "provider tool outputs exceed the session payload budget"
        );
    }
    if let Some(embeddings) = output.embeddings.as_ref() {
        ensure!(
            provider_session_serialized_len(embeddings)? <= payload_limit,
            "provider embeddings exceed the session payload budget"
        );
    }
    if let Some(transcription) = output.transcription.as_ref() {
        mayhem_proto::validate_transcription_result(
            transcription,
            TranscriptionResultLimits {
                max_bytes: payload_limit,
                ..TranscriptionResultLimits::default()
            },
        )
        .map_err(|err| anyhow::anyhow!("provider transcription output is invalid: {err}"))?;
        ensure!(
            transcription.text.trim() == output.content.trim(),
            "provider transcription metadata does not match streamed transcript text"
        );
    }
    let max_artifacts = provider_session_configured_limit(
        "MAYHEM_SESSION_MAX_ARTIFACTS",
        DEFAULT_PROVIDER_SESSION_MAX_ARTIFACTS,
    );
    ensure!(
        output.artifacts.len() <= max_artifacts,
        "provider artifact count exceeds the session budget"
    );
    let max_artifact_bytes = provider_session_configured_limit(
        "MAYHEM_SESSION_MAX_ARTIFACT_BYTES",
        DEFAULT_PROVIDER_SESSION_MAX_ARTIFACT_BYTES,
    );
    let artifact_bytes = output
        .artifacts
        .iter()
        .try_fold(0_usize, |total, artifact| {
            total
                .checked_add(artifact.bytes.len())
                .context("provider artifact byte count overflow")
        })?;
    ensure!(
        artifact_bytes <= max_artifact_bytes,
        "provider artifacts exceed the session byte budget"
    );
    for axis in output.usage_attribution.keys() {
        ensure!(
            matches!(
                axis.as_str(),
                "reasoning_output_tokens" | "vision_input_tokens" | "audio_input_tokens"
            ),
            "provider output contains unsupported usage attribution {axis}"
        );
    }
    ensure!(
        output
            .usage_attribution
            .get("reasoning_output_tokens")
            .copied()
            .unwrap_or(0)
            <= output.usage.output_tokens(),
        "provider reasoning attribution exceeds billed output tokens"
    );
    ensure!(
        output
            .usage_attribution
            .get("vision_input_tokens")
            .copied()
            .unwrap_or(0)
            <= output.usage.input_tokens(),
        "provider vision attribution exceeds billed input tokens"
    );
    ensure!(
        output
            .usage_attribution
            .get("audio_input_tokens")
            .copied()
            .unwrap_or(0)
            <= output.usage.input_tokens(),
        "provider audio attribution exceeds billed input tokens"
    );
    ensure!(
        output
            .usage_attribution
            .get("vision_input_tokens")
            .copied()
            .unwrap_or(0)
            .saturating_add(
                output
                    .usage_attribution
                    .get("audio_input_tokens")
                    .copied()
                    .unwrap_or(0)
            )
            <= output.usage.input_tokens(),
        "provider media attribution exceeds billed input tokens"
    );
    Ok(())
}

fn provider_session_configured_limit(name: &str, default: usize) -> usize {
    std::env::var(name)
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(default)
}

struct ProviderVerifiedEndpointRequest<'a> {
    family: &'a str,
    request: &'a Value,
    contract: &'a mayhem_proto::EndpointFamilyContract,
}

fn provider_verify_endpoint_request<'a>(
    transport_body: &'a Value,
    expected_model_id: Option<&str>,
    adapter: &'a catalog::CatalogAdapter,
) -> Result<ProviderVerifiedEndpointRequest<'a>> {
    let metadata = provider_session_request_result(
        transport_body
            .get("mayhem_contract")
            .and_then(Value::as_object)
            .context("provider request missing mayhem_contract envelope"),
    )?;
    if metadata.get("schema_version").and_then(Value::as_u64) != Some(1) {
        return Err(provider_session_request_error(
            "provider request has unsupported mayhem_contract schema_version",
        ));
    }
    let family = provider_session_request_result(
        metadata
            .get("endpoint_family")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .context("provider request missing endpoint_family"),
    )?;
    let contract = adapter
        .endpoint_families
        .iter()
        .find(|contract| contract.family == family)
        .with_context(|| format!("provider model does not expose endpoint family {family}"))?;
    let declared_contract_fingerprint = provider_session_request_result(
        metadata
            .get("endpoint_contract_fingerprint")
            .and_then(Value::as_str)
            .context("provider request missing endpoint contract fingerprint"),
    )?;
    if declared_contract_fingerprint != mayhem_proto::endpoint_contract_fingerprint(contract) {
        return Err(provider_session_request_error(
            "provider request endpoint contract fingerprint does not match the local signed catalog",
        ));
    }
    let request = provider_session_request_result(
        transport_body
            .get("contract_request")
            .context("provider request missing normalized contract_request"),
    )?;
    let declared_request_fingerprint = provider_session_request_result(
        metadata
            .get("normalized_request_fingerprint")
            .and_then(Value::as_str)
            .context("provider request missing normalized request fingerprint"),
    )?;
    if declared_request_fingerprint != mayhem_proto::endpoint_request_fingerprint(request) {
        return Err(provider_session_request_error(
            "provider normalized request fingerprint mismatch",
        ));
    }
    let mut transport = transport_body.clone();
    if let Some(object) = transport.as_object_mut() {
        object.remove("mayhem_contract");
        object.remove("contract_request");
    }
    let declared_transport_fingerprint = provider_session_request_result(
        metadata
            .get("transport_request_fingerprint")
            .and_then(Value::as_str)
            .context("provider request missing transport request fingerprint"),
    )?;
    if declared_transport_fingerprint != stable_value_hash(&transport) {
        return Err(provider_session_request_error(
            "provider transport request fingerprint mismatch",
        ));
    }
    provider_session_request_result(
        mayhem_proto::validate_endpoint_request(contract, request).map_err(|violations| {
            anyhow::anyhow!(
                "provider request violates signed endpoint contract: {}",
                violations
                    .iter()
                    .take(4)
                    .map(|violation| format!("{}: {}", violation.path, violation.reason))
                    .collect::<Vec<_>>()
                    .join("; ")
            )
        }),
    )?;
    let request_with_defaults =
        mayhem_proto::materialize_endpoint_request_defaults(contract, request)
            .map_err(anyhow::Error::msg)?;
    if &request_with_defaults != request {
        return Err(provider_session_request_error(
            "provider request omitted an admin-signed endpoint default",
        ));
    }
    if let Some(expected_model_id) = expected_model_id.filter(|_| {
        contract
            .request_attributes
            .iter()
            .any(|path| path == "model")
    }) {
        if request.get("model").and_then(Value::as_str) != Some(expected_model_id) {
            return Err(provider_session_request_error(
                "provider request model does not match the loaded canonical model",
            ));
        }
    }
    let transport_kind = provider_endpoint_transport_kind(family)?;
    if transport_body.get("kind").and_then(Value::as_str) != Some(transport_kind) {
        return Err(provider_session_request_error(format!(
            "provider request transport kind does not match endpoint family {family}"
        )));
    }
    Ok(ProviderVerifiedEndpointRequest {
        family,
        request,
        contract,
    })
}

fn provider_endpoint_transport_kind(family: &str) -> Result<&'static str> {
    match family {
        mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS
        | mayhem_proto::ENDPOINT_OPENAI_COMPLETIONS
        | mayhem_proto::ENDPOINT_OPENAI_RESPONSES
        | mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT => Ok("chat"),
        mayhem_proto::ENDPOINT_OPENAI_EMBEDDINGS | mayhem_proto::ENDPOINT_HF_FEATURE_EXTRACTION => {
            Ok("embedding")
        }
        mayhem_proto::ENDPOINT_OPENAI_IMAGE_GENERATIONS
        | mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE => Ok("image_generation"),
        mayhem_proto::ENDPOINT_OPENAI_AUDIO_TRANSCRIPTIONS
        | mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION => Ok("audio_transcription"),
        mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH | mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH => {
            Ok("audio_speech")
        }
        mayhem_proto::ENDPOINT_OPENAI_VIDEOS | mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO => {
            Ok("video_generation")
        }
        mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS
        | mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO => Ok("audio_generation"),
        mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS => Ok("music_generation"),
        _ => bail!("unsupported provider endpoint family {family}"),
    }
}

fn provider_seal_local_contract_request(
    body: &Value,
    adapter: &catalog::CatalogAdapter,
    model_id: &str,
) -> Result<Value> {
    let kind = body.get("kind").and_then(Value::as_str).unwrap_or("chat");
    let family = body
        .get("endpoint_family")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| provider_local_endpoint_family(kind));
    let contract = adapter
        .endpoint_families
        .iter()
        .find(|contract| contract.family == family)
        .with_context(|| format!("test adapter missing endpoint family {family}"))?;
    let mut request = body.clone();
    if let Some(object) = request.as_object_mut() {
        object.remove("kind");
        object.remove("endpoint_family");
        object.remove("mayhem_contract");
        object.remove("contract_request");
        if contract
            .request_attributes
            .iter()
            .any(|path| path == "model")
        {
            object.entry("model").or_insert_with(|| json!(model_id));
        }
    }
    if family == mayhem_proto::ENDPOINT_OPENAI_AUDIO_TRANSCRIPTIONS {
        let audio = body
            .get("audio")
            .and_then(|value| value.get("data"))
            .and_then(Value::as_str)
            .map(|value| {
                base64::engine::general_purpose::STANDARD
                    .decode(value)
                    .context("test audio is not valid base64")
            })
            .transpose()?
            .unwrap_or_default();
        let mut public = json!({
            "model": request.get("model").cloned().unwrap_or_else(|| json!("test/model")),
            "file": {
                "filename": body.get("audio").and_then(|value| value.get("filename")).and_then(Value::as_str).unwrap_or("test.wav"),
                "content_type": body.get("audio").and_then(|value| value.get("content_type")).and_then(Value::as_str).unwrap_or("audio/wav"),
                "bytes": audio.len(),
                "blake3": blake3::hash(&audio).to_hex().to_string(),
            }
        });
        for key in [
            "response_format",
            "language",
            "prompt",
            "temperature",
            "timestamp_granularities",
            "stream",
        ] {
            if let Some(value) = request.get(key) {
                public[key] = value.clone();
            }
        }
        request = public;
    }
    request = mayhem_proto::materialize_endpoint_request_defaults(contract, &request)
        .map_err(anyhow::Error::msg)?;
    mayhem_proto::validate_endpoint_request(contract, &request).map_err(|violations| {
        anyhow::anyhow!(
            "local provider request violates signed endpoint contract: {}",
            violations
                .iter()
                .take(4)
                .map(|violation| format!("{}: {}", violation.path, violation.reason))
                .collect::<Vec<_>>()
                .join("; ")
        )
    })?;
    let mut transport = json!({"kind": provider_endpoint_transport_kind(family)?});
    for key in ["audio", "audio_seconds"] {
        if let Some(value) = body.get(key) {
            transport[key] = value.clone();
        }
    }
    let transport_fingerprint = stable_value_hash(&transport);
    transport["contract_request"] = request.clone();
    transport["mayhem_contract"] = json!({
        "schema_version": 1,
        "endpoint_family": family,
        "endpoint_contract_fingerprint": mayhem_proto::endpoint_contract_fingerprint(contract),
        "normalized_request_fingerprint": mayhem_proto::endpoint_request_fingerprint(&request),
        "transport_request_fingerprint": transport_fingerprint,
    });
    Ok(transport)
}

fn provider_local_endpoint_family(kind: &str) -> &'static str {
    match kind {
        "embedding" => mayhem_proto::ENDPOINT_OPENAI_EMBEDDINGS,
        "image_generation" => mayhem_proto::ENDPOINT_OPENAI_IMAGE_GENERATIONS,
        "audio_transcription" => mayhem_proto::ENDPOINT_OPENAI_AUDIO_TRANSCRIPTIONS,
        "audio_speech" => mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH,
        "video_generation" => mayhem_proto::ENDPOINT_OPENAI_VIDEOS,
        "audio_generation" => mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS,
        "music_generation" => mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS,
        _ => mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS,
    }
}

fn provider_reasoning_output_mode(
    adapter: &catalog::CatalogAdapter,
    request: &GenerateRequest,
) -> ProviderReasoningOutputMode {
    if adapter.reasoning_passthrough == "preserve" {
        return ProviderReasoningOutputMode::Preserve;
    }
    if provider_reasoning_speciality_enabled(request) == Some(true) {
        ProviderReasoningOutputMode::StripPrefilled
    } else {
        ProviderReasoningOutputMode::StripTagged
    }
}

fn provider_reasoning_speciality_enabled(request: &GenerateRequest) -> Option<bool> {
    request.speciality_parameters.iter().find_map(|speciality| {
        if !provider_reasoning_speciality_control(&speciality.name, &speciality.native_path) {
            return None;
        }
        Some(!provider_reasoning_level_disabled(
            &speciality.level,
            &speciality.value,
        ))
    })
}

fn provider_reasoning_speciality_control(name: &str, native_path: &str) -> bool {
    let haystack = format!(
        "{} {}",
        name.to_ascii_lowercase(),
        native_path.to_ascii_lowercase()
    );
    (haystack.contains("reason") || haystack.contains("think"))
        && !["preserve", "history", "retain"]
            .iter()
            .any(|marker| haystack.contains(marker))
}

fn provider_reasoning_level_disabled(level: &str, value: &Value) -> bool {
    matches!(
        level.to_ascii_lowercase().as_str(),
        "none" | "off" | "disabled"
    ) || value == &Value::Bool(false)
        || value.as_u64() == Some(0)
        || value.as_str().is_some_and(|value| {
            matches!(
                value.to_ascii_lowercase().as_str(),
                "none" | "off" | "disabled" | "false"
            )
        })
}

#[cfg(test)]
fn provider_reasoning_visible_output(text: &str, mode: ProviderReasoningOutputMode) -> String {
    provider_reasoning_visible_output_with_delimiters(
        text,
        mode,
        PROVIDER_QWEN_REASONING_DELIMITERS,
    )
}

fn provider_reasoning_visible_output_with_delimiters(
    text: &str,
    mode: ProviderReasoningOutputMode,
    delimiters: ProviderReasoningDelimiters,
) -> String {
    provider_reasoning_output_parts_with_delimiters(text, mode, delimiters).visible
}

fn provider_reasoning_output_parts_with_delimiters(
    text: &str,
    mode: ProviderReasoningOutputMode,
    delimiters: ProviderReasoningDelimiters,
) -> ProviderReasoningFilteredText {
    let mut filter = ProviderReasoningOutputFilter::with_delimiters(mode, delimiters);
    let mut filtered = filter.push_split(text);
    filtered.extend(filter.finish_split());
    filtered
}

fn provider_reasoning_delimiters(adapter: &catalog::CatalogAdapter) -> ProviderReasoningDelimiters {
    if adapter.chat_template_id == "gemma4-instruct" {
        PROVIDER_GEMMA4_REASONING_DELIMITERS
    } else {
        PROVIDER_QWEN_REASONING_DELIMITERS
    }
}

fn provider_engine_tool_parse_text(
    text: &str,
    output_mode: ProviderReasoningOutputMode,
    reasoning_enabled: Option<bool>,
    delimiters: ProviderReasoningDelimiters,
) -> String {
    let parse_mode = if output_mode == ProviderReasoningOutputMode::Preserve {
        if reasoning_enabled == Some(true) {
            ProviderReasoningOutputMode::StripPrefilled
        } else {
            ProviderReasoningOutputMode::StripTagged
        }
    } else {
        output_mode
    };
    provider_reasoning_visible_output_with_delimiters(text, parse_mode, delimiters)
}

fn provider_engine_tool_call_outputs_after_reasoning(
    text: &str,
    output_mode: ProviderReasoningOutputMode,
    reasoning_enabled: Option<bool>,
    delimiters: ProviderReasoningDelimiters,
    strategy: ProviderEngineToolStrategy,
    tools: &[ToolSpec],
) -> Option<Vec<Value>> {
    let visible = provider_engine_tool_parse_text(text, output_mode, reasoning_enabled, delimiters);
    if let Some(calls) = provider_engine_tool_call_outputs(&visible, strategy, tools) {
        return Some(calls);
    }
    if visible == text {
        return None;
    }
    // A tool grammar may return only the canonical call without the reasoning
    // close marker prefilled by the chat template. Keep the raw fallback
    // fail-closed through the same advertised-tool parser and validator.
    provider_engine_tool_call_outputs(text, strategy, tools)
}

#[cfg(test)]
fn provider_test_seal_contract_request(
    body: &Value,
    adapter: &catalog::CatalogAdapter,
) -> Result<Value> {
    provider_seal_local_contract_request(body, adapter, "test/model@4bit")
}

#[cfg(test)]
fn provider_test_endpoint_family(kind: &str) -> &'static str {
    provider_local_endpoint_family(kind)
}

#[cfg(test)]
fn provider_engine_session_response(
    backend: &mut dyn EngineBackend,
    adapter: &catalog::CatalogAdapter,
    body: &Value,
    live_stream: Option<&mut ProviderSessionLiveStream<'_>>,
) -> Result<ProviderSessionOutput> {
    let mut adapter = adapter.clone();
    let kind = body.get("kind").and_then(Value::as_str).unwrap_or("chat");
    let family = provider_test_endpoint_family(kind);
    if !adapter
        .endpoint_families
        .iter()
        .any(|contract| contract.family == family)
    {
        adapter.endpoint_families.push(
            catalog::endpoint_contract_template(family).with_context(|| {
                format!("test endpoint family {family} has no built-in contract")
            })?,
        );
    }
    let sealed = provider_test_seal_contract_request(body, &adapter)?;
    provider_engine_session_response_with_sampling(
        backend,
        None,
        &adapter,
        &catalog::CatalogSamplingProfile::default(),
        &sealed,
        live_stream,
        &CancellationToken::new(),
    )
}

fn provider_engine_session_response_with_sampling(
    backend: &mut dyn EngineBackend,
    expected_model_id: Option<&str>,
    adapter: &catalog::CatalogAdapter,
    sampling: &catalog::CatalogSamplingProfile,
    body: &Value,
    live_stream: Option<&mut ProviderSessionLiveStream<'_>>,
    cancellation: &CancellationToken,
) -> Result<ProviderSessionOutput> {
    provider_engine_session_response_with_sampling_bounded(
        backend,
        expected_model_id,
        adapter,
        sampling,
        body,
        live_stream,
        None,
        cancellation,
    )
}

fn provider_protocol_prompt_tokens(
    contract: &mayhem_proto::EndpointFamilyContract,
    request: &Value,
) -> Result<Option<u64>> {
    let tools_required = contract
        .required_request_attributes
        .iter()
        .any(|attribute| attribute == "tools")
        && contract
            .request_attribute_specs
            .get("tools")
            .and_then(|spec| spec.min_items)
            .is_some_and(|min_items| min_items > 0);
    if !tools_required {
        return Ok(None);
    }
    if !request
        .get("tools")
        .and_then(Value::as_array)
        .is_some_and(|tools| !tools.is_empty())
    {
        return Err(provider_session_request_error(
            "signed tools-only endpoint requires at least one normalized tool",
        ));
    }
    let prompt_tokens = provider_session_request_result(
        tools_only_model_input_prompt_units(&contract.family, request)
            .map_err(anyhow::Error::msg)
            .context("metering tools-only provider model input"),
    )?;
    if prompt_tokens == 0 {
        return Err(provider_session_request_error(
            "tools-only provider model input produced zero prompt units",
        ));
    }
    Ok(Some(prompt_tokens))
}

fn provider_engine_session_response_with_sampling_bounded(
    backend: &mut dyn EngineBackend,
    expected_model_id: Option<&str>,
    adapter: &catalog::CatalogAdapter,
    sampling: &catalog::CatalogSamplingProfile,
    body: &Value,
    mut live_stream: Option<&mut ProviderSessionLiveStream<'_>>,
    output_token_cap: Option<u32>,
    cancellation: &CancellationToken,
) -> Result<ProviderSessionOutput> {
    cancellation.check().context("provider request cancelled")?;
    let verified = provider_verify_endpoint_request(body, expected_model_id, adapter)?;
    let endpoint_family = verified.family;
    let request_body = verified.request;
    let protocol_prompt_tokens = provider_protocol_prompt_tokens(verified.contract, request_body)?;
    if matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_OPENAI_AUDIO_TRANSCRIPTIONS
            | mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION
    ) {
        let request = provider_session_request_result(
            provider_audio_transcription_request_from_body(endpoint_family, request_body, body),
        )?;
        let audio_seconds = request.audio_seconds;
        let output = backend
            .transcribe(request.engine, cancellation)
            .context("transcribing provider session audio with mayhem-engine")?;
        let transcription = TranscriptionResult {
            schema_version: mayhem_proto::TRANSCRIPTION_RESULT_SCHEMA_VERSION,
            text: output.text.clone(),
            detected_language: output.detected_language,
            duration_seconds: output.duration_seconds,
            words: output
                .words
                .into_iter()
                .map(|word| TranscriptionTimestamp {
                    text: word.text,
                    start: word.start,
                    end: word.end,
                })
                .collect(),
            segments: output
                .segments
                .into_iter()
                .map(|segment| TranscriptionTimestamp {
                    text: segment.text,
                    start: segment.start,
                    end: segment.end,
                })
                .collect(),
        };
        return Ok(ProviderSessionOutput {
            content: transcription.text.clone(),
            reasoning_evidence: String::new(),
            tools: Vec::new(),
            embeddings: None,
            transcription: Some(transcription),
            artifacts: Vec::new(),
            finish_reason: "stop".to_owned(),
            prompt_tokens: 0,
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage: provider_audio_transcription_usage(audio_seconds),
            usage_attribution: BTreeMap::new(),
        });
    }

    if matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH | mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH
    ) {
        let request = provider_session_request_result(provider_speech_request_from_body(
            endpoint_family,
            request_body,
        ))?;
        let input_characters = provider_session_request_result(
            u64::try_from(request.input.chars().count())
                .context("audio_speech input character count overflowed u64"),
        )?;
        let mut artifact_chunks = ProviderSessionArtifactCollector::configured();
        let output = backend
            .synthesize_speech(
                request,
                &mut |chunk: ArtifactChunk| artifact_chunks.push(chunk),
                cancellation,
            )
            .context("synthesizing provider session speech with mayhem-engine")?;
        let artifacts = artifact_chunks.finish()?;
        if artifacts.is_empty() {
            bail!("provider speech engine produced no audio artifact");
        }
        return Ok(ProviderSessionOutput {
            content: String::new(),
            reasoning_evidence: String::new(),
            tools: Vec::new(),
            embeddings: None,
            transcription: None,
            artifacts,
            finish_reason: "stop".to_owned(),
            prompt_tokens: 0,
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage: provider_audio_speech_usage(input_characters, output.audio_seconds),
            usage_attribution: BTreeMap::new(),
        });
    }

    if matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_OPENAI_IMAGE_GENERATIONS | mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE
    ) {
        let request = provider_session_request_result(
            provider_image_generation_request_from_body(endpoint_family, request_body),
        )?;
        let image_count = request.image_count;
        let steps = u64::from(request.steps);
        let width = request.width;
        let height = request.height;
        let mut artifact_chunks = ProviderSessionArtifactCollector::configured();
        let output = backend
            .generate_image(
                request,
                &mut |chunk: ArtifactChunk| artifact_chunks.push(chunk),
                cancellation,
            )
            .context("generating provider session image artifact with mayhem-engine")?;
        ensure!(
            output.image_count == image_count && u64::from(output.steps) == steps,
            "provider image engine changed the requested image count or step count"
        );
        let artifacts = artifact_chunks.finish()?;
        if artifacts.is_empty() {
            bail!("provider image generation engine produced no image artifacts");
        }
        let usage = provider_image_generation_usage(artifacts.len() as u64, steps, width, height);
        if artifacts.len() as u32 != image_count {
            bail!(
                "provider image generation engine produced {} artifact(s), expected {image_count}",
                artifacts.len()
            );
        }
        return Ok(ProviderSessionOutput {
            content: String::new(),
            reasoning_evidence: String::new(),
            tools: Vec::new(),
            embeddings: None,
            transcription: None,
            artifacts,
            finish_reason: "stop".to_owned(),
            prompt_tokens: 0,
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage,
            usage_attribution: BTreeMap::new(),
        });
    }

    if matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_OPENAI_VIDEOS | mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO
    ) {
        let mut request = provider_session_request_result(
            provider_media_generation_request_from_body(endpoint_family, request_body),
        )?;
        let (expected_duration, expected_frames) =
            provider_video_output_expectation(verified.contract, &request)?;
        request.frame_count = Some(expected_frames);
        provider_canonicalize_video_engine_request(
            verified.contract,
            &mut request,
            expected_frames,
        )?;
        let mut artifact_chunks = ProviderSessionArtifactCollector::configured();
        let output = backend
            .generate_video(
                request,
                &mut |chunk: ArtifactChunk| artifact_chunks.push(chunk),
                cancellation,
            )
            .context("generating provider session video artifact with mayhem-engine")?;
        ensure!(
            output.duration_seconds > 0 && output.frame_count > 0,
            "provider video engine returned zero duration or frames"
        );
        ensure!(
            output.duration_seconds == expected_duration,
            "provider video engine returned {} seconds, expected {expected_duration}",
            output.duration_seconds
        );
        ensure!(
            output.frame_count == expected_frames,
            "provider video engine returned {} frames, expected {expected_frames}",
            output.frame_count
        );
        let artifacts = artifact_chunks.finish()?;
        ensure!(
            !artifacts.is_empty()
                && artifacts
                    .iter()
                    .all(|artifact| artifact.content_type.starts_with("video/")),
            "provider video generation engine produced no valid video artifact"
        );
        return Ok(ProviderSessionOutput {
            content: String::new(),
            reasoning_evidence: String::new(),
            tools: Vec::new(),
            embeddings: None,
            transcription: None,
            artifacts,
            finish_reason: "stop".to_owned(),
            prompt_tokens: 0,
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage: provider_video_generation_usage(output.duration_seconds, output.frame_count),
            usage_attribution: BTreeMap::new(),
        });
    }

    if matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS
            | mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS
            | mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO
    ) {
        let request = provider_session_request_result(
            provider_media_generation_request_from_body(endpoint_family, request_body),
        )?;
        let requested_duration = request.duration_seconds;
        let input_characters =
            provider_media_generation_input_characters(endpoint_family, &request.request)?;
        let mut artifact_chunks = ProviderSessionArtifactCollector::configured();
        let output = if endpoint_family == mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS {
            backend
                .generate_music(
                    request,
                    &mut |chunk: ArtifactChunk| artifact_chunks.push(chunk),
                    cancellation,
                )
                .context("generating provider session music artifact with mayhem-engine")?
        } else {
            backend
                .generate_audio(
                    request,
                    &mut |chunk: ArtifactChunk| artifact_chunks.push(chunk),
                    cancellation,
                )
                .context("generating provider session audio artifact with mayhem-engine")?
        };
        ensure!(
            output.duration_seconds > 0,
            "provider audio engine returned zero duration"
        );
        if let Some(expected) = requested_duration {
            ensure!(
                output.duration_seconds.abs_diff(expected) <= 1,
                "provider audio engine returned {} seconds, expected approximately {expected}",
                output.duration_seconds
            );
        }
        let artifacts = artifact_chunks.finish()?;
        ensure!(
            !artifacts.is_empty()
                && artifacts
                    .iter()
                    .all(|artifact| artifact.content_type.starts_with("audio/")),
            "provider audio generation engine produced no valid audio artifact"
        );
        let mut measured_audio_seconds = 0_u64;
        for artifact in &artifacts {
            let metadata = validated_audio_metadata(&artifact.bytes).with_context(|| {
                format!(
                    "provider audio engine returned invalid {} bytes",
                    artifact.content_type
                )
            })?;
            ensure!(
                provider_audio_content_type_matches_format(&artifact.content_type, metadata.format),
                "provider audio engine content type {} does not match the encoded audio format",
                artifact.content_type
            );
            ensure!(
                output
                    .duration_seconds
                    .abs_diff(metadata.duration_seconds_ceil)
                    <= 1,
                "provider audio engine reported {} seconds but encoded artifact measures {} seconds",
                output.duration_seconds,
                metadata.duration_seconds_ceil
            );
            if let Some(expected) = requested_duration {
                ensure!(
                    expected.abs_diff(metadata.duration_seconds_ceil) <= 1,
                    "provider audio artifact measures {} seconds, expected {expected}",
                    metadata.duration_seconds_ceil
                );
            }
            measured_audio_seconds =
                measured_audio_seconds.saturating_add(metadata.duration_seconds_ceil);
        }
        if endpoint_family == mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO {
            ensure!(
                artifacts.iter().all(|artifact| {
                    artifact.content_type == "audio/wav"
                        && wav_sample_rate(&artifact.bytes).is_some()
                }),
                "HF text-to-audio requires a valid WAV artifact with a declared sample rate"
            );
        }
        return Ok(ProviderSessionOutput {
            content: String::new(),
            reasoning_evidence: String::new(),
            tools: Vec::new(),
            embeddings: None,
            transcription: None,
            artifacts,
            finish_reason: "stop".to_owned(),
            prompt_tokens: 0,
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage: provider_audio_generation_usage(input_characters, measured_audio_seconds),
            usage_attribution: BTreeMap::new(),
        });
    }

    if matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_OPENAI_EMBEDDINGS | mayhem_proto::ENDPOINT_HF_FEATURE_EXTRACTION
    ) {
        let inputs = provider_session_request_result(provider_embedding_input_texts_from_body(
            request_body,
        ))?;
        let prompt_tokens = provider_embedding_input_token_count(&inputs);
        let dimensions = provider_session_request_result(
            request_body
                .get("dimensions")
                .and_then(Value::as_u64)
                .map(|value| usize::try_from(value).context("embedding dimensions overflow usize"))
                .transpose(),
        )?;
        let output = backend
            .embed(
                mayhem_engine::EmbeddingRequest { inputs, dimensions },
                cancellation,
            )
            .context("generating provider session embeddings with mayhem-engine")?;
        return Ok(ProviderSessionOutput {
            content: String::new(),
            reasoning_evidence: String::new(),
            tools: Vec::new(),
            embeddings: Some(output.embeddings),
            transcription: None,
            artifacts: Vec::new(),
            finish_reason: "stop".to_owned(),
            prompt_tokens,
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage: ReceiptUsage::text(prompt_tokens, 0),
            usage_attribution: BTreeMap::new(),
        });
    }

    ensure!(
        matches!(
            endpoint_family,
            mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS
                | mayhem_proto::ENDPOINT_OPENAI_COMPLETIONS
                | mayhem_proto::ENDPOINT_OPENAI_RESPONSES
                | mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT
        ),
        "provider endpoint family {endpoint_family} has no engine execution path"
    );

    let tool_mode = provider_engine_tool_request(request_body, adapter)?;
    let mut request = provider_engine_request_from_endpoint_body_with_sampling(
        endpoint_family,
        request_body,
        adapter,
        sampling,
    )?;
    if let Some(cap) = output_token_cap {
        request.max_new_tokens = request.max_new_tokens.min(cap.max(1));
    }
    let reasoning_speciality_enabled = provider_reasoning_speciality_enabled(&request);
    let reasoning_output_mode = provider_reasoning_output_mode(adapter, &request);
    let reasoning_delimiters = provider_reasoning_delimiters(adapter);
    let mut reasoning_stream_filter =
        ProviderReasoningOutputFilter::with_delimiters(reasoning_output_mode, reasoning_delimiters);
    let mut token_ids = Vec::new();
    let mut artifact_chunks = ProviderSessionArtifactCollector::configured();
    // Existing text models keep the established request-text estimate. A signed
    // tools-only endpoint is metered from the model-visible query and selected
    // tools so buyer and provider agree without charging transport metadata.
    let estimated_prompt_tokens = rough_text_tokens(&provider_session_prompt_text(body));
    let output = backend
        .generate_with_artifacts(
            request,
            &mut |chunk: mayhem_engine::TokenChunk| {
                if tool_mode.is_none() {
                    if let Some(stream) = live_stream.as_deref_mut() {
                        let filtered = reasoning_stream_filter.push_split(&chunk.text);
                        let mut visible_chunk = chunk.clone();
                        visible_chunk.text = filtered.visible;
                        stream
                            .on_token(visible_chunk, &filtered.hidden, estimated_prompt_tokens)
                            .map_err(|err| {
                                mayhem_engine::EngineError::InvalidConfig(format!(
                                    "provider live stream failed: {err:#}"
                                ))
                            })?;
                    }
                }
                token_ids.push(chunk.token_id);
                Ok(())
            },
            &mut |chunk: ArtifactChunk| artifact_chunks.push(chunk),
            cancellation,
        )
        .context("generating provider session response with mayhem-engine")?;
    if tool_mode.is_none() {
        let trailing = reasoning_stream_filter.finish_split();
        if !trailing.visible.is_empty() || !trailing.hidden.is_empty() {
            if let Some(stream) = live_stream.as_deref_mut() {
                stream.append_filtered_text(trailing);
            }
        }
    }
    let artifacts = artifact_chunks.finish()?;
    let tools = tool_mode
        .as_ref()
        .and_then(|mode| {
            provider_engine_tool_call_outputs_after_reasoning(
                &output.text,
                reasoning_output_mode,
                reasoning_speciality_enabled,
                reasoning_delimiters,
                mode.strategy,
                &mode.tools,
            )
        })
        .unwrap_or_default();
    if tool_mode
        .as_ref()
        .is_some_and(|mode| !mode.parallel && tools.len() > 1)
    {
        return Err(provider_session_output_error(format!(
            "provider engine returned {} tool calls while parallel_tool_calls=false",
            tools.len()
        )));
    }
    if tool_mode.as_ref().is_some_and(|mode| mode.required) && tools.is_empty() {
        return Err(provider_session_output_error(format!(
            "provider engine did not return a valid required tool call: {}",
            output.text.trim()
        )));
    }
    let completion_tokens = u64::from(output.usage.completion_tokens);
    let reasoning_tokens = u64::from(output.usage.reasoning_tokens).min(completion_tokens);
    let vision_tokens = u64::from(output.usage.vision_tokens);
    let audio_tokens = u64::from(output.usage.audio_tokens);
    let prompt_tokens = protocol_prompt_tokens.unwrap_or(estimated_prompt_tokens);
    let billed_prompt_tokens = prompt_tokens
        .saturating_add(vision_tokens)
        .saturating_add(audio_tokens);
    let mut usage_attribution = BTreeMap::new();
    if reasoning_tokens > 0 {
        usage_attribution.insert("reasoning_output_tokens".to_owned(), reasoning_tokens);
    }
    if vision_tokens > 0 {
        usage_attribution.insert("vision_input_tokens".to_owned(), vision_tokens);
    }
    if audio_tokens > 0 {
        usage_attribution.insert("audio_input_tokens".to_owned(), audio_tokens);
    }
    let finish_reason = if tools.is_empty() {
        output.finish_reason.to_string()
    } else {
        "tool_calls".to_owned()
    };
    let filtered_output = provider_reasoning_output_parts_with_delimiters(
        &output.text,
        reasoning_output_mode,
        reasoning_delimiters,
    );
    Ok(ProviderSessionOutput {
        usage: provider_chat_receipt_usage(request_body, billed_prompt_tokens, completion_tokens),
        content: if tools.is_empty() {
            filtered_output.visible
        } else {
            String::new()
        },
        reasoning_evidence: filtered_output.hidden,
        tools,
        embeddings: None,
        transcription: None,
        artifacts,
        finish_reason,
        prompt_tokens: billed_prompt_tokens,
        completion_tokens,
        token_ids,
        usage_attribution,
    })
}

struct ProviderAudioTranscriptionRequest {
    engine: EngineAudioTranscriptionRequest,
    audio_seconds: u64,
}

fn provider_audio_transcription_request_from_body(
    endpoint_family: &str,
    body: &Value,
    transport_body: &Value,
) -> Result<ProviderAudioTranscriptionRequest> {
    let audio = transport_body
        .get("audio")
        .context("audio_transcription request missing audio")?;
    let encoding = audio
        .get("encoding")
        .and_then(Value::as_str)
        .context("audio_transcription audio.encoding missing")?;
    if encoding != "base64" {
        bail!("audio_transcription audio.encoding must be base64");
    }
    let encoded = audio
        .get("data")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .context("audio_transcription audio.data missing")?;
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(encoded)
        .context("audio_transcription audio.data is not valid base64")?;
    if endpoint_family == mayhem_proto::ENDPOINT_HF_AUTOMATIC_SPEECH_RECOGNITION {
        match body.get("inputs") {
            Some(Value::String(contract_input)) => {
                let contract_bytes = base64::engine::general_purpose::STANDARD
                    .decode(contract_input)
                    .context("HF ASR inputs are not valid base64")?;
                ensure!(
                    contract_bytes == bytes,
                    "HF ASR transported audio differs from the signed contract input"
                );
            }
            Some(Value::Object(descriptor)) => {
                ensure!(
                    descriptor.get("encoding").and_then(Value::as_str) == Some("raw"),
                    "HF ASR raw input descriptor has an unsupported encoding"
                );
                ensure!(
                    descriptor.get("bytes").and_then(Value::as_u64)
                        == Some(
                            u64::try_from(bytes.len())
                                .context("HF ASR audio byte count overflowed u64")?
                        ),
                    "HF ASR raw input byte count does not match transported audio"
                );
                let digest = blake3::hash(&bytes).to_hex().to_string();
                ensure!(
                    descriptor.get("blake3").and_then(Value::as_str) == Some(digest.as_str()),
                    "HF ASR raw input digest does not match transported audio"
                );
                if let Some(expected_content_type) =
                    descriptor.get("content_type").and_then(Value::as_str)
                {
                    ensure!(
                        audio.get("content_type").and_then(Value::as_str)
                            == Some(expected_content_type),
                        "HF ASR raw input content type does not match transported audio"
                    );
                }
            }
            _ => bail!("HF ASR contract request is missing a supported audio input"),
        }
    } else {
        let file = body
            .get("file")
            .and_then(Value::as_object)
            .context("audio_transcription contract request missing file descriptor")?;
        ensure!(
            file.get("bytes").and_then(Value::as_u64)
                == Some(u64::try_from(bytes.len()).context("audio byte count overflowed u64")?),
            "audio_transcription file byte count does not match transported audio"
        );
        let bytes_blake3 = blake3::hash(&bytes).to_hex().to_string();
        ensure!(
            file.get("blake3").and_then(Value::as_str) == Some(bytes_blake3.as_str()),
            "audio_transcription file digest does not match transported audio"
        );
        if let Some(expected_content_type) = file.get("content_type").and_then(Value::as_str) {
            ensure!(
                audio.get("content_type").and_then(Value::as_str) == Some(expected_content_type),
                "audio_transcription content type does not match transported audio"
            );
        }
        if let Some(expected_filename) = file.get("filename").and_then(Value::as_str) {
            ensure!(
                audio.get("filename").and_then(Value::as_str) == Some(expected_filename),
                "audio_transcription filename does not match transported audio"
            );
        }
    }
    let audio_seconds = audio_duration_seconds_ceil(&bytes)
        .context("audio_transcription audio is not a valid bounded WAV or FLAC")?
        .max(1);
    if let Some(declared) = transport_body.get("audio_seconds").and_then(Value::as_u64) {
        ensure!(
            declared == audio_seconds,
            "audio_transcription declared {declared} seconds but bounded audio is {audio_seconds} seconds"
        );
    }
    Ok(ProviderAudioTranscriptionRequest {
        engine: EngineAudioTranscriptionRequest {
            audio: bytes,
            content_type: audio
                .get("content_type")
                .and_then(Value::as_str)
                .map(str::to_owned),
            language: body
                .get("language")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .map(str::to_owned),
            prompt: body
                .get("prompt")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .map(str::to_owned),
        },
        audio_seconds,
    })
}

const MAX_INLINE_SPEECH_REFERENCE_AUDIO_BYTES: usize = 16 * 1024 * 1024;
const MAX_INLINE_SPEECH_REFERENCE_AUDIO_SECONDS: u64 = 10;

fn provider_speech_request_from_body(endpoint_family: &str, body: &Value) -> Result<SpeechRequest> {
    let parameters = body.get("parameters").and_then(Value::as_object);
    let (input_key, generation_parameters) = match endpoint_family {
        mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH => ("input", None),
        mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH => (
            "inputs",
            parameters
                .and_then(|parameters| parameters.get("generation_parameters"))
                .and_then(Value::as_object),
        ),
        other => bail!("unsupported speech endpoint family {other}"),
    };
    let input = body
        .get(input_key)
        .and_then(Value::as_str)
        .filter(|input| !input.trim().is_empty())
        .context("audio_speech request missing input")?
        .to_owned();

    let mut request = SpeechRequest::new(input);
    if endpoint_family == mayhem_proto::ENDPOINT_HF_TEXT_TO_SPEECH {
        request.voice = optional_nonempty_string(
            parameters.and_then(|parameters| {
                parameters
                    .get("voice")
                    .or_else(|| parameters.get("speaker_id"))
            }),
            "parameters.voice",
        )?;
        request.response_format = Some("wav".to_owned());
        request.speed = optional_f64(
            parameters.and_then(|parameters| parameters.get("speed")),
            "parameters.speed",
        )?;
        request.reference_audio = optional_speech_reference_audio(
            parameters.and_then(|parameters| parameters.get("reference_audio")),
            "parameters.reference_audio",
        )?;
        request.exaggeration = optional_f32(
            parameters.and_then(|parameters| parameters.get("exaggeration")),
            "parameters.exaggeration",
        )?;
        request.cfg_weight = optional_f32(
            parameters.and_then(|parameters| parameters.get("cfg_weight")),
            "parameters.cfg_weight",
        )?;
        request.seed = optional_u32(
            parameters.and_then(|parameters| parameters.get("seed")),
            "parameters.seed",
        )?;
        request.temperature = optional_f32(
            generation_parameters.and_then(|parameters| parameters.get("temperature")),
            "parameters.generation_parameters.temperature",
        )?;
        request.min_p = optional_f32(
            generation_parameters.and_then(|parameters| parameters.get("min_p")),
            "parameters.generation_parameters.min_p",
        )?;
        request.top_p = optional_f32(
            generation_parameters.and_then(|parameters| parameters.get("top_p")),
            "parameters.generation_parameters.top_p",
        )?;
        request.repetition_penalty = optional_f32(
            generation_parameters.and_then(|parameters| parameters.get("repetition_penalty")),
            "parameters.generation_parameters.repetition_penalty",
        )?;
    } else {
        request.voice = optional_nonempty_string(body.get("voice"), "voice")?;
        request.response_format = Some(
            body.get("response_format")
                .map(|value| {
                    value
                        .as_str()
                        .filter(|value| !value.is_empty())
                        .context("response_format must be a non-empty string")
                        .map(str::to_owned)
                })
                .transpose()?
                .unwrap_or_else(|| "wav".to_owned()),
        );
        request.speed = optional_f64(body.get("speed"), "speed")?;
        request.reference_audio =
            optional_speech_reference_audio(body.get("reference_audio"), "reference_audio")?;
        request.exaggeration = optional_f32(body.get("exaggeration"), "exaggeration")?;
        request.cfg_weight = optional_f32(body.get("cfg_weight"), "cfg_weight")?;
        request.seed = optional_u32(body.get("seed"), "seed")?;
        request.temperature = optional_f32(body.get("temperature"), "temperature")?;
        request.min_p = optional_f32(body.get("min_p"), "min_p")?;
        request.top_p = optional_f32(body.get("top_p"), "top_p")?;
        request.repetition_penalty =
            optional_f32(body.get("repetition_penalty"), "repetition_penalty")?;
    }
    Ok(request)
}

fn optional_nonempty_string(value: Option<&Value>, label: &str) -> Result<Option<String>> {
    value
        .map(|value| {
            value
                .as_str()
                .filter(|value| !value.is_empty())
                .with_context(|| format!("{label} must be a non-empty string"))
                .map(str::to_owned)
        })
        .transpose()
}

fn optional_f64(value: Option<&Value>, label: &str) -> Result<Option<f64>> {
    value
        .map(|value| {
            value
                .as_f64()
                .filter(|value| value.is_finite())
                .with_context(|| format!("{label} must be a finite number"))
        })
        .transpose()
}

fn optional_f32(value: Option<&Value>, label: &str) -> Result<Option<f32>> {
    optional_f64(value, label)?
        .map(|value| {
            let value = value as f32;
            ensure!(value.is_finite(), "{label} exceeds the f32 range");
            Ok(value)
        })
        .transpose()
}

fn optional_u32(value: Option<&Value>, label: &str) -> Result<Option<u32>> {
    value
        .map(|value| {
            let value = value
                .as_u64()
                .with_context(|| format!("{label} must be an unsigned integer"))?;
            u32::try_from(value).with_context(|| format!("{label} exceeds the u32 range"))
        })
        .transpose()
}

fn optional_speech_reference_audio(
    value: Option<&Value>,
    label: &str,
) -> Result<Option<SpeechReferenceAudio>> {
    let Some(value) = value else {
        return Ok(None);
    };
    let reference = value
        .as_object()
        .with_context(|| format!("{label} must be an inline audio object"))?;
    let encoding = reference
        .get("encoding")
        .and_then(Value::as_str)
        .with_context(|| format!("{label}.encoding is required"))?;
    ensure!(
        encoding == "base64",
        "{label}.encoding must be exactly base64"
    );
    let content_type = reference
        .get("content_type")
        .and_then(Value::as_str)
        .with_context(|| format!("{label}.content_type is required"))?;
    ensure!(
        content_type == "audio/wav",
        "{label}.content_type must be exactly audio/wav"
    );
    let encoded = reference
        .get("data")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .with_context(|| format!("{label}.data is required"))?;
    let max_encoded_bytes = MAX_INLINE_SPEECH_REFERENCE_AUDIO_BYTES
        .div_ceil(3)
        .saturating_mul(4)
        .saturating_add(4);
    ensure!(
        encoded.len() <= max_encoded_bytes,
        "{label}.data exceeds the {} byte decoded limit",
        MAX_INLINE_SPEECH_REFERENCE_AUDIO_BYTES
    );
    let data = base64::engine::general_purpose::STANDARD
        .decode(encoded)
        .with_context(|| format!("{label}.data is not valid base64"))?;
    ensure!(
        !data.is_empty() && data.len() <= MAX_INLINE_SPEECH_REFERENCE_AUDIO_BYTES,
        "{label}.data must decode to 1..={} bytes",
        MAX_INLINE_SPEECH_REFERENCE_AUDIO_BYTES
    );
    let metadata = validated_wav_audio_metadata(&data)
        .with_context(|| format!("{label}.data does not match content_type audio/wav"))?;
    ensure!(
        metadata.duration_seconds_ceil <= MAX_INLINE_SPEECH_REFERENCE_AUDIO_SECONDS,
        "{label}.data exceeds the {} second limit",
        MAX_INLINE_SPEECH_REFERENCE_AUDIO_SECONDS
    );
    Ok(Some(SpeechReferenceAudio {
        content_type: Some(content_type.to_owned()),
        data,
    }))
}

fn provider_image_generation_request_from_body(
    endpoint_family: &str,
    body: &Value,
) -> Result<EngineImageGenerationRequest> {
    let parameters = body.get("parameters").and_then(Value::as_object);
    let prompt_key = if endpoint_family == mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE {
        "inputs"
    } else {
        "prompt"
    };
    let prompt = body
        .get(prompt_key)
        .or_else(|| body.get("caption"))
        .and_then(Value::as_str)
        .filter(|prompt| !prompt.trim().is_empty())
        .context("image_generation request missing prompt")?
        .to_owned();
    let image_count = if endpoint_family == mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE {
        u32::try_from(
            parameters
                .and_then(|parameters| parameters.get("num_images_per_prompt"))
                .and_then(Value::as_u64)
                .unwrap_or(1),
        )
        .context("image_generation num_images_per_prompt overflowed u32")?
    } else {
        u32::try_from(
            body.get("n")
                .and_then(Value::as_u64)
                .context("signed image endpoint defaults did not resolve n")?,
        )
        .context("image_generation n overflowed u32")?
    };
    let steps = body
        .get("steps")
        .and_then(Value::as_u64)
        .or_else(|| {
            parameters
                .and_then(|parameters| parameters.get("num_inference_steps"))
                .and_then(Value::as_u64)
        })
        .context("signed image endpoint defaults did not resolve steps")?;
    let cfg_scale = body
        .get("cfg_scale")
        .and_then(Value::as_f64)
        .or_else(|| {
            parameters
                .and_then(|parameters| parameters.get("guidance_scale"))
                .and_then(Value::as_f64)
        })
        .context("signed image endpoint defaults did not resolve guidance scale")?
        as f32;
    let (width, height) = if endpoint_family == mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE {
        (
            parameters
                .and_then(|parameters| parameters.get("width"))
                .and_then(Value::as_u64)
                .map(u32::try_from)
                .transpose()
                .context("image_generation width overflowed u32")?
                .context("signed image endpoint defaults did not resolve width")?,
            parameters
                .and_then(|parameters| parameters.get("height"))
                .and_then(Value::as_u64)
                .map(u32::try_from)
                .transpose()
                .context("image_generation height overflowed u32")?
                .context("signed image endpoint defaults did not resolve height")?,
        )
    } else if body.get("width").is_some() || body.get("height").is_some() {
        let width = body
            .get("width")
            .and_then(Value::as_u64)
            .context("image_generation width is missing or invalid")?;
        let height = body
            .get("height")
            .and_then(Value::as_u64)
            .context("image_generation height is missing or invalid")?;
        (
            u32::try_from(width).context("image_generation width overflowed u32")?,
            u32::try_from(height).context("image_generation height overflowed u32")?,
        )
    } else {
        provider_image_generation_size(body)?
    };
    let mut request = EngineImageGenerationRequest::new(prompt);
    request.image_count = image_count;
    request.steps = u32::try_from(steps).context("image_generation steps overflowed u32")?;
    request.guidance_scale = cfg_scale;
    request.flow_shift = body
        .get("shift")
        .or_else(|| parameters.and_then(|parameters| parameters.get("shift")))
        .and_then(Value::as_f64)
        .map(|value| value as f32);
    request.width = width;
    request.height = height;
    request.negative_prompt = body
        .get("negative_prompt")
        .or_else(|| parameters.and_then(|parameters| parameters.get("negative_prompt")))
        .and_then(Value::as_str)
        .map(str::to_owned);
    request.scheduler = body
        .get("scheduler")
        .or_else(|| parameters.and_then(|parameters| parameters.get("scheduler")))
        .and_then(Value::as_str)
        .map(str::to_owned);
    let seed = body
        .get("seed")
        .or_else(|| parameters.and_then(|parameters| parameters.get("seed")))
        .and_then(Value::as_u64);
    if let Some(seed) = seed {
        request.seed = Some(u32::try_from(seed).context("image_generation seed exceeds u32")?);
    }
    request.validate()?;
    Ok(request)
}

fn provider_image_generation_size(body: &Value) -> Result<(u32, u32)> {
    let size = body
        .get("size")
        .and_then(Value::as_str)
        .context("signed image endpoint defaults did not resolve size")?;
    let (width, height) = size
        .split_once('x')
        .context("image_generation size must be WIDTHxHEIGHT")?;
    let width = width
        .parse::<u32>()
        .context("image_generation width is not a positive integer")?;
    let height = height
        .parse::<u32>()
        .context("image_generation height is not a positive integer")?;
    if width == 0 || height == 0 {
        bail!("image_generation dimensions must be greater than zero");
    }
    Ok((width, height))
}

fn provider_media_generation_request_from_body(
    endpoint_family: &str,
    body: &Value,
) -> Result<EngineMediaGenerationRequest> {
    let parameters = body.get("parameters").and_then(Value::as_object);
    let generation_parameters = parameters
        .and_then(|parameters| parameters.get("generation_parameters"))
        .and_then(Value::as_object);
    let prompt_key = if matches!(
        endpoint_family,
        mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO | mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO
    ) {
        "inputs"
    } else {
        "prompt"
    };
    let prompt = body
        .get(prompt_key)
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_owned();
    ensure!(
        !prompt.trim().is_empty()
            || endpoint_family == mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS,
        "media generation request missing prompt"
    );
    let duration_seconds = body
        .get("duration_seconds")
        .and_then(provider_duration_seconds_ceil)
        .or_else(|| {
            body.get("duration")
                .and_then(provider_duration_seconds_ceil)
        })
        .or_else(|| {
            parameters
                .and_then(|parameters| parameters.get("duration_seconds"))
                .and_then(provider_duration_seconds_ceil)
        })
        .or_else(|| body.get("seconds").and_then(provider_duration_seconds_ceil));
    let frame_count = provider_consistent_positive_u64_alias(
        body,
        parameters,
        VIDEO_CANARY_FRAME_ATTRIBUTES,
        "media generation frame count",
    )?;
    let fps = provider_consistent_positive_f64_alias(
        body,
        parameters,
        VIDEO_CANARY_FPS_ATTRIBUTES,
        "media generation fps",
    )?;
    let duration_seconds = duration_seconds.or_else(|| {
        let frames = frame_count?;
        let fps = fps?;
        Some(((frames as f64) / fps).ceil().max(1.0) as u64)
    });
    let step_count = parameters
        .and_then(|parameters| parameters.get("num_inference_steps"))
        .and_then(Value::as_u64)
        .or_else(|| body.get("inference_steps").and_then(Value::as_u64))
        .or_else(|| body.get("steps").and_then(Value::as_u64))
        .or_else(|| {
            generation_parameters
                .and_then(|parameters| parameters.get("max_new_tokens"))
                .and_then(Value::as_u64)
        })
        .or_else(|| body.get("max_new_tokens").and_then(Value::as_u64));
    let response_format = body
        .get("response_format")
        .or_else(|| body.get("format"))
        .and_then(Value::as_str)
        .map(str::to_owned);
    let request = EngineMediaGenerationRequest {
        endpoint_family: endpoint_family.to_owned(),
        prompt,
        request: body.clone(),
        duration_seconds,
        frame_count,
        step_count,
        response_format,
    };
    request.validate()?;
    Ok(request)
}

fn provider_consistent_positive_u64_alias(
    body: &Value,
    parameters: Option<&serde_json::Map<String, Value>>,
    aliases: &[&str],
    label: &str,
) -> Result<Option<u64>> {
    let mut selected: Option<u64> = None;
    for object in [body.as_object(), parameters].into_iter().flatten() {
        for alias in aliases {
            let Some(value) = object.get(*alias) else {
                continue;
            };
            let value = value
                .as_u64()
                .filter(|value| *value > 0)
                .with_context(|| format!("{label} {alias} must be a positive integer"))?;
            if let Some(previous) = selected {
                ensure!(
                    previous == value,
                    "{label} aliases conflict: {previous} versus {value}"
                );
            } else {
                selected = Some(value);
            }
        }
    }
    Ok(selected)
}

fn provider_consistent_positive_f64_alias(
    body: &Value,
    parameters: Option<&serde_json::Map<String, Value>>,
    aliases: &[&str],
    label: &str,
) -> Result<Option<f64>> {
    let mut selected: Option<f64> = None;
    for object in [body.as_object(), parameters].into_iter().flatten() {
        for alias in aliases {
            let Some(value) = object.get(*alias) else {
                continue;
            };
            let value = value
                .as_f64()
                .or_else(|| value.as_str().and_then(|value| value.parse::<f64>().ok()))
                .filter(|value| value.is_finite() && *value > 0.0)
                .with_context(|| format!("{label} {alias} must be a positive finite number"))?;
            if let Some(previous) = selected {
                ensure!(
                    (previous - value).abs()
                        <= f64::EPSILON * previous.abs().max(value.abs()).max(1.0),
                    "{label} aliases conflict: {previous} versus {value}"
                );
            } else {
                selected = Some(value);
            }
        }
    }
    Ok(selected)
}

fn provider_video_output_expectation(
    contract: &mayhem_proto::EndpointFamilyContract,
    request: &EngineMediaGenerationRequest,
) -> Result<(u64, u64)> {
    let body = request
        .request
        .as_object()
        .context("video generation request body must be an object")?;
    let parameters = body.get("parameters").and_then(Value::as_object);
    let fps = provider_video_frame_rate(contract, request)?;
    let requested_duration = provider_consistent_positive_f64_alias(
        &request.request,
        parameters,
        MEDIA_GENERATION_DURATION_ATTRIBUTES,
        "media generation duration",
    )?;

    let expected_frames = if let Some(frames) = request.frame_count {
        frames
    } else {
        let duration = requested_duration
            .or_else(|| request.duration_seconds.map(|value| value as f64))
            .or_else(|| (contract.family == mayhem_proto::ENDPOINT_OPENAI_VIDEOS).then_some(4.0))
            .context("video generation request resolved neither duration nor frame count")?;
        let requested_frames = duration * fps;
        ensure!(
            requested_frames.is_finite()
                && requested_frames >= 1.0
                && requested_frames <= u64::MAX as f64,
            "video duration/fps produced an invalid frame count"
        );
        let requested_frames = requested_frames.floor().max(1.0) as u64;
        provider_video_request_attribute_spec(contract, VIDEO_CANARY_FRAME_ATTRIBUTES)
            .map(|spec| {
                mayhem_proto::canonicalize_positive_integer_at_most_for_spec(requested_frames, spec)
                    .map_err(anyhow::Error::msg)
            })
            .transpose()?
            .unwrap_or(requested_frames)
    };
    ensure!(
        expected_frames > 0,
        "video generation request resolved a zero frame count"
    );
    let expected_duration_f64 = (expected_frames as f64) / fps;
    ensure!(
        expected_duration_f64.is_finite()
            && expected_duration_f64 > 0.0
            && expected_duration_f64 <= u64::MAX as f64,
        "video frame count/fps produced an invalid duration"
    );
    Ok((
        expected_duration_f64.ceil().max(1.0) as u64,
        expected_frames,
    ))
}

fn provider_video_frame_rate(
    contract: &mayhem_proto::EndpointFamilyContract,
    request: &EngineMediaGenerationRequest,
) -> Result<f64> {
    let parameters = request.request.get("parameters").and_then(Value::as_object);
    let fps = provider_consistent_positive_f64_alias(
        &request.request,
        parameters,
        VIDEO_CANARY_FPS_ATTRIBUTES,
        "media generation fps",
    )?
    .unwrap_or(
        if contract.family == mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO {
            8.0
        } else {
            DEFAULT_VIDEO_GENERATION_FPS as f64
        },
    );
    ensure!(
        fps.is_finite() && fps > 0.0 && fps <= 240.0,
        "media generation fps must be finite and between 0 and 240"
    );
    Ok(fps)
}

fn provider_canonicalize_video_engine_request(
    contract: &mayhem_proto::EndpointFamilyContract,
    request: &mut EngineMediaGenerationRequest,
    expected_frames: u64,
) -> Result<()> {
    let fps = provider_video_frame_rate(contract, request)?;
    let body = request
        .request
        .as_object()
        .context("video generation request body must be an object")?;
    let parameters = body.get("parameters").and_then(Value::as_object);
    let explicit_frames = provider_consistent_positive_u64_alias(
        &request.request,
        parameters,
        VIDEO_CANARY_FRAME_ATTRIBUTES,
        "media generation frame count",
    )?;
    let requested_duration = provider_consistent_positive_f64_alias(
        &request.request,
        parameters,
        MEDIA_GENERATION_DURATION_ATTRIBUTES,
        "media generation duration",
    )?;

    let body = request
        .request
        .as_object_mut()
        .context("video generation request body must be an object")?;
    let mut parameters = body
        .remove("parameters")
        .and_then(|value| value.as_object().cloned())
        .unwrap_or_default();
    for alias in VIDEO_CANARY_FRAME_ATTRIBUTES
        .iter()
        .chain(VIDEO_CANARY_FPS_ATTRIBUTES)
        .chain(MEDIA_GENERATION_DURATION_ATTRIBUTES)
    {
        body.remove(*alias);
        parameters.remove(*alias);
    }

    if contract.family == mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO {
        parameters.insert("num_frames".to_owned(), Value::from(expected_frames));
        parameters.insert("fps".to_owned(), Value::from(fps));
        body.insert("parameters".to_owned(), Value::Object(parameters));
    } else {
        ensure!(
            contract.family == mayhem_proto::ENDPOINT_OPENAI_VIDEOS,
            "unsupported video endpoint family {}",
            contract.family
        );
        ensure!(
            parameters.is_empty(),
            "OpenAI video request retained unsupported nested engine controls"
        );
        body.insert("fps".to_owned(), Value::from(fps));
        if explicit_frames.is_some() {
            body.insert("num_frames".to_owned(), Value::from(expected_frames));
        } else if let Some(duration) = requested_duration {
            body.insert("seconds".to_owned(), Value::from(duration));
        }
    }
    Ok(())
}

fn provider_video_request_attribute_spec<'a>(
    contract: &'a mayhem_proto::EndpointFamilyContract,
    aliases: &[&str],
) -> Option<&'a mayhem_proto::EndpointAttributeSpec> {
    let nested_first = contract.family == mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO;
    for nested in [nested_first, !nested_first] {
        for alias in aliases {
            let path = if nested {
                format!("parameters.{alias}")
            } else {
                (*alias).to_owned()
            };
            if let Some(spec) = contract.request_attribute_specs.get(&path) {
                return Some(spec);
            }
        }
    }
    None
}

fn provider_duration_seconds_ceil(value: &Value) -> Option<u64> {
    value
        .as_f64()
        .or_else(|| value.as_str()?.parse::<f64>().ok())
        .filter(|value| value.is_finite() && *value > 0.0 && *value <= u64::MAX as f64)
        .map(|value| value.ceil() as u64)
}

fn provider_image_generation_usage(
    image_count: u64,
    steps: u64,
    width: u32,
    height: u32,
) -> ReceiptUsage {
    let pixels = u64::from(width).saturating_mul(u64::from(height)).max(1);
    let resolution_scale = pixels.div_ceil(512 * 512).max(1);
    ReceiptUsage::from_units([
        (USAGE_IMAGE, image_count),
        (
            USAGE_STEP,
            image_count
                .saturating_mul(steps)
                .saturating_mul(resolution_scale),
        ),
    ])
}

fn provider_audio_transcription_usage(audio_seconds: u64) -> ReceiptUsage {
    ReceiptUsage::from_units([(USAGE_AUDIO_SECOND, audio_seconds)])
}

fn provider_audio_speech_usage(input_characters: u64, audio_seconds: u64) -> ReceiptUsage {
    ReceiptUsage::from_units([
        (USAGE_INPUT_CHARACTER, input_characters),
        (USAGE_AUDIO_SECOND, audio_seconds),
    ])
}

fn provider_media_generation_input_characters(
    endpoint_family: &str,
    request: &Value,
) -> Result<u64> {
    Ok(mayhem_proto::artifact_generation_input_characters(
        endpoint_family,
        request,
    ))
}

fn provider_audio_content_type_matches_format(
    content_type: &str,
    format: mayhem_proto::ValidatedAudioFormat,
) -> bool {
    match format {
        mayhem_proto::ValidatedAudioFormat::Wav => {
            matches!(content_type, "audio/wav" | "audio/x-wav")
        }
        mayhem_proto::ValidatedAudioFormat::Flac => content_type == "audio/flac",
        mayhem_proto::ValidatedAudioFormat::Mp3 => {
            matches!(content_type, "audio/mpeg" | "audio/mp3")
        }
        mayhem_proto::ValidatedAudioFormat::Opus => {
            matches!(content_type, "audio/ogg" | "audio/opus")
        }
        mayhem_proto::ValidatedAudioFormat::Aac => {
            matches!(
                content_type,
                "audio/aac" | "audio/m4a" | "audio/mp4" | "audio/x-m4a"
            )
        }
    }
}

fn provider_video_generation_usage(video_seconds: u64, frame_count: u64) -> ReceiptUsage {
    ReceiptUsage::from_units([
        (USAGE_VIDEO_SECOND, video_seconds),
        (USAGE_FRAME, frame_count),
    ])
}

fn provider_audio_generation_usage(input_characters: u64, audio_seconds: u64) -> ReceiptUsage {
    ReceiptUsage::from_units([
        (USAGE_INPUT_CHARACTER, input_characters),
        (USAGE_AUDIO_SECOND, audio_seconds),
    ])
}

fn provider_engine_request_from_endpoint_body_with_sampling(
    endpoint_family: &str,
    body: &Value,
    adapter: &catalog::CatalogAdapter,
    sampling: &catalog::CatalogSamplingProfile,
) -> Result<GenerateRequest> {
    let endpoint_messages =
        provider_session_request_result(provider_endpoint_messages(endpoint_family, body))?;
    let messages = provider_session_request_result(provider_engine_template_messages(
        endpoint_messages,
        adapter,
    ))?;
    let (speciality_parameters, speciality_output_cap) =
        provider_engine_speciality_parameters(endpoint_family, body, adapter)?;
    let tool_request = provider_engine_tool_request(body, adapter)?;
    let template_tools = tool_request
        .as_ref()
        .map(|request| provider_engine_template_tools(&request.tools))
        .unwrap_or_default();
    let prompt =
        provider_engine_prompt(&messages, &template_tools, &speciality_parameters, adapter)?;
    let mut request = GenerateRequest::new(prompt);
    request.messages = messages.clone();
    request.media = provider_engine_media_inputs(&messages);
    request.tools = template_tools;
    request.parallel_tool_calls = tool_request
        .as_ref()
        .map(|tool_request| tool_request.parallel);
    request.speciality_parameters = speciality_parameters;
    if let Some(max_tokens) = provider_requested_max_output_tokens(body) {
        request.max_new_tokens = provider_session_request_result(
            u32::try_from(max_tokens).context("max_tokens exceeds provider engine request range"),
        )?;
    } else if let Some(default_cap) = speciality_output_cap {
        request.max_new_tokens = default_cap;
    }
    request.temperature =
        provider_session_request_result(provider_optional_f64(body, "temperature"))?
            .or(sampling.temperature)
            .map(|value| value as f32);
    request.top_p = provider_session_request_result(provider_optional_f64(body, "top_p"))?
        .or(sampling.top_p)
        .map(|value| value as f32);
    request.top_k =
        provider_session_request_result(provider_optional_i32(body, "top_k"))?.or(sampling.top_k);
    request.min_p = provider_session_request_result(provider_optional_f64(body, "min_p"))?
        .or(sampling.min_p)
        .map(|value| value as f32);
    request.repeat_penalty =
        provider_session_request_result(provider_repeat_penalty(body, sampling))?
            .map(|value| value as f32);
    request.frequency_penalty =
        provider_session_request_result(provider_optional_f64(body, "frequency_penalty"))?
            .or(sampling.frequency_penalty)
            .map(|value| value as f32);
    request.presence_penalty =
        provider_session_request_result(provider_optional_f64(body, "presence_penalty"))?
            .or(sampling.presence_penalty)
            .map(|value| value as f32);
    request.stop = provider_session_request_result(provider_stop_sequences(body))?;
    request.seed = provider_session_request_result(provider_optional_u32(body, "seed"))?;
    request.validate_sampling()?;
    if let Some(tool_request) = tool_request {
        if tool_request.required {
            match tool_request.strategy {
                ProviderEngineToolStrategy::MayhemJson
                | ProviderEngineToolStrategy::QwenFunctionXml
                | ProviderEngineToolStrategy::GemmaFunctionCall => {
                    request.grammar = Some(GrammarSpec::ToolCall {
                        tools: tool_request.tools,
                    });
                }
                ProviderEngineToolStrategy::OpenAiToolCalls => {
                    request.grammar = Some(GrammarSpec::JsonSchema {
                        schema: provider_openai_tool_calls_json_schema(
                            &tool_request.tools,
                            tool_request.parallel,
                        ),
                    });
                }
            }
        }
    } else if provider_wants_json(body) {
        request.grammar = Some(GrammarSpec::JsonSchema {
            schema: provider_response_json_schema(body),
        });
    }
    Ok(request)
}

fn provider_requested_max_output_tokens(body: &Value) -> Option<u64> {
    body.get("max_tokens")
        .filter(|value| !value.is_null())
        .or_else(|| {
            body.get("max_completion_tokens")
                .filter(|value| !value.is_null())
        })
        .or_else(|| {
            body.get("max_output_tokens")
                .filter(|value| !value.is_null())
        })
        .and_then(Value::as_u64)
}

fn provider_engine_template_messages(
    mut messages: Vec<Value>,
    adapter: &catalog::CatalogAdapter,
) -> Result<Vec<Value>> {
    if adapter.chat_template_id == "gemma4-instruct" {
        for message in &mut messages {
            if let Some(parts) = message.get_mut("content").and_then(Value::as_array_mut) {
                parts.sort_by_key(gemma4_content_part_order);
            }
        }
        return Ok(messages);
    }
    if adapter.chat_template_id != "qwen3.5-instruct" {
        return Ok(messages);
    }
    for (message_index, message) in messages.iter_mut().enumerate() {
        let Some(tool_calls) = message.get_mut("tool_calls").and_then(Value::as_array_mut) else {
            continue;
        };
        for (call_index, tool_call) in tool_calls.iter_mut().enumerate() {
            let Some(call) = tool_call.as_object_mut() else {
                continue;
            };
            let arguments = if call.get("function").is_some_and(Value::is_object) {
                call.get_mut("function")
                    .and_then(Value::as_object_mut)
                    .and_then(|function| function.get_mut("arguments"))
            } else {
                call.get_mut("arguments")
            };
            let Some(arguments) = arguments else {
                continue;
            };
            if let Some(encoded) = arguments.as_str() {
                let parsed = serde_json::from_str::<Value>(encoded).with_context(|| {
                    format!(
                        "qwen3.5 tool call arguments at message {message_index}, call {call_index} are not valid JSON"
                    )
                })?;
                ensure!(
                    parsed.is_object(),
                    "qwen3.5 tool call arguments at message {message_index}, call {call_index} must encode a JSON object"
                );
                *arguments = parsed;
            } else {
                ensure!(
                    arguments.is_object(),
                    "qwen3.5 tool call arguments at message {message_index}, call {call_index} must be a JSON object or an encoded JSON object"
                );
            }
        }
    }
    Ok(messages)
}

fn gemma4_content_part_order(part: &Value) -> u8 {
    match part.get("type").and_then(Value::as_str) {
        Some("image" | "image_url" | "video") => 0,
        Some("audio" | "input_audio") => 2,
        _ => 1,
    }
}

fn provider_engine_template_tools(tools: &[ToolSpec]) -> Vec<Value> {
    tools
        .iter()
        .map(|tool| {
            let mut function = serde_json::Map::from_iter([
                ("name".to_owned(), json!(&tool.name)),
                ("parameters".to_owned(), tool.parameters.clone()),
            ]);
            if let Some(description) = &tool.description {
                function.insert("description".to_owned(), json!(description));
            }
            json!({"type": "function", "function": function})
        })
        .collect()
}

fn provider_engine_speciality_parameters(
    endpoint_family: &str,
    body: &Value,
    adapter: &catalog::CatalogAdapter,
) -> Result<(Vec<GenerateSpecialityParameter>, Option<u32>)> {
    let contract = adapter
        .endpoint_families
        .iter()
        .find(|contract| contract.family == endpoint_family)
        .with_context(|| format!("catalog adapter has no endpoint family {endpoint_family}"))?;
    let selected = body.get("specialities").and_then(Value::as_object);
    let mut parameters = Vec::new();
    let mut reasoning_output_cap = None;
    for descriptor in &adapter.specialities {
        let submitted = selected
            .and_then(|values| values.get(&descriptor.name))
            .or_else(|| body.get(&descriptor.name));
        let selection = provider_speciality_level(descriptor, submitted).with_context(|| {
            format!(
                "model speciality {} does not support value {}",
                descriptor.name,
                submitted
                    .map(Value::to_string)
                    .unwrap_or_else(|| descriptor.default_level.clone())
            )
        });
        let level = if submitted.is_some() {
            provider_session_request_result(selection)?
        } else {
            selection?
        };
        let mapping = contract
            .speciality_mappings
            .get(&descriptor.name)
            .with_context(|| {
                format!(
                    "endpoint family {endpoint_family} has no native mapping for speciality {}",
                    descriptor.name
                )
            })?;
        let target = match mapping.target {
            mayhem_proto::EndpointSpecialityTarget::ChatTemplateKwarg => {
                GenerateSpecialityTarget::ChatTemplateKwarg
            }
            mayhem_proto::EndpointSpecialityTarget::SamplingParameter => {
                GenerateSpecialityTarget::SamplingParameter
            }
            mayhem_proto::EndpointSpecialityTarget::PromptSuffix => {
                GenerateSpecialityTarget::PromptSuffix
            }
            mayhem_proto::EndpointSpecialityTarget::BackendParameter => {
                GenerateSpecialityTarget::BackendParameter
            }
        };
        parameters.push(GenerateSpecialityParameter {
            name: descriptor.name.clone(),
            level: level.name.clone(),
            target,
            native_path: mapping.native_path.clone(),
            value: level.native_value.clone(),
            max_reasoning_tokens: level.max_reasoning_tokens,
        });
        if descriptor.name == "reasoning_effort" {
            reasoning_output_cap = level.default_max_output_tokens;
        }
    }
    Ok((parameters, reasoning_output_cap))
}

#[cfg(test)]
fn provider_engine_request_from_body(
    body: &Value,
    adapter: &catalog::CatalogAdapter,
) -> Result<GenerateRequest> {
    provider_engine_request_from_endpoint_body_with_sampling(
        mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS,
        body,
        adapter,
        &catalog::CatalogSamplingProfile::default(),
    )
}

fn provider_endpoint_messages(endpoint_family: &str, body: &Value) -> Result<Vec<Value>> {
    match endpoint_family {
        mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS
        | mayhem_proto::ENDPOINT_HF_MULTIMODAL_CHAT => Ok(body
            .get("messages")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default()),
        mayhem_proto::ENDPOINT_OPENAI_COMPLETIONS => {
            let prompt = provider_prompt_value_text(
                body.get("prompt")
                    .context("completion request missing prompt")?,
            );
            ensure!(!prompt.is_empty(), "completion prompt must not be empty");
            Ok(vec![json!({"role":"user", "content":prompt})])
        }
        mayhem_proto::ENDPOINT_OPENAI_RESPONSES => {
            let input = body
                .get("input")
                .context("Responses request missing input")?;
            match input {
                Value::String(text) if !text.trim().is_empty() => {
                    Ok(vec![json!({"role":"user", "content":text})])
                }
                Value::Array(items) if !items.is_empty() => Ok(items.clone()),
                _ => bail!("Responses input must be a non-empty string or message array"),
            }
        }
        other => bail!("endpoint family {other} is not a conversational text surface"),
    }
}

fn provider_prompt_value_text(prompt: &Value) -> String {
    match prompt {
        Value::String(text) => text.clone(),
        Value::Array(items) => items
            .iter()
            .map(|item| {
                item.as_str()
                    .map(str::to_owned)
                    .unwrap_or_else(|| item.to_string())
            })
            .collect::<Vec<_>>()
            .join("\n"),
        value => value.to_string(),
    }
}

fn provider_stop_sequences(body: &Value) -> Result<Vec<String>> {
    match body.get("stop") {
        None | Some(Value::Null) => Ok(Vec::new()),
        Some(Value::String(value)) if !value.is_empty() => Ok(vec![value.clone()]),
        Some(Value::Array(values)) => values
            .iter()
            .map(|value| {
                value
                    .as_str()
                    .filter(|value| !value.is_empty())
                    .map(str::to_owned)
                    .context("stop array entries must be non-empty strings")
            })
            .collect(),
        Some(_) => bail!("stop must be a string, an array of strings, or null"),
    }
}

fn provider_optional_f64(body: &Value, field: &str) -> Result<Option<f64>> {
    match body.get(field) {
        None | Some(Value::Null) => Ok(None),
        Some(value) => value
            .as_f64()
            .map(Some)
            .with_context(|| format!("{field} must be a JSON number")),
    }
}

fn provider_optional_i32(body: &Value, field: &str) -> Result<Option<i32>> {
    match body.get(field) {
        None | Some(Value::Null) => Ok(None),
        Some(value) => value
            .as_i64()
            .context(format!("{field} must be a JSON integer"))
            .and_then(|value| {
                i32::try_from(value)
                    .map(Some)
                    .with_context(|| format!("{field} exceeds the signed 32-bit range"))
            }),
    }
}

fn provider_optional_u32(body: &Value, field: &str) -> Result<Option<u32>> {
    match body.get(field) {
        None | Some(Value::Null) => Ok(None),
        Some(value) => value
            .as_u64()
            .context(format!("{field} must be a non-negative JSON integer"))
            .and_then(|value| {
                u32::try_from(value)
                    .map(Some)
                    .with_context(|| format!("{field} exceeds the unsigned 32-bit range"))
            }),
    }
}

fn provider_repeat_penalty(
    body: &Value,
    sampling: &catalog::CatalogSamplingProfile,
) -> Result<Option<f64>> {
    let submitted = provider_optional_f64(body, "repeat_penalty")?;
    match (submitted, sampling.repeat_penalty) {
        (None, expected) => Ok(expected),
        (Some(submitted), Some(expected))
            if (submitted - expected).abs()
                <= f64::EPSILON * submitted.abs().max(expected.abs()).max(1.0) =>
        {
            Ok(Some(expected))
        }
        (Some(_), Some(_)) => {
            bail!("repeat_penalty is server-controlled and must match the signed model profile")
        }
        (Some(_), None) => {
            bail!("repeat_penalty is server-controlled and is not enabled for this model")
        }
    }
}

fn provider_engine_media_inputs(messages: &[Value]) -> Vec<MediaInput> {
    messages
        .iter()
        .filter_map(|message| message.get("content").and_then(Value::as_array))
        .flat_map(|parts| parts.iter())
        .flat_map(provider_content_part_media_inputs)
        .collect()
}

fn provider_content_part_media_inputs(part: &Value) -> Vec<MediaInput> {
    match part.get("type").and_then(Value::as_str) {
        Some("image_url") => {
            let Some(url) = part
                .get("image_url")
                .and_then(|image| image.get("url"))
                .or_else(|| part.get("url"))
                .and_then(Value::as_str)
                .map(str::to_owned)
            else {
                return Vec::new();
            };
            vec![MediaInput {
                kind: "image".to_owned(),
                content_type: data_url_content_type(&url),
                url: Some(url),
                data: None,
                frames: Vec::new(),
                num_frames: None,
                fps: None,
            }]
        }
        Some("input_audio") => {
            let Some(audio) = part.get("input_audio") else {
                return Vec::new();
            };
            let Some(data) = audio.get("data").and_then(Value::as_str).map(str::to_owned) else {
                return Vec::new();
            };
            if data.is_empty() {
                return Vec::new();
            }
            let format = audio.get("format").and_then(Value::as_str).unwrap_or("wav");
            vec![MediaInput {
                kind: "audio".to_owned(),
                content_type: Some(audio_content_type(format).to_owned()),
                url: None,
                data: Some(data),
                frames: Vec::new(),
                num_frames: None,
                fps: None,
            }]
        }
        Some("video") => {
            let Some(video) = part.get("video") else {
                return Vec::new();
            };
            if let Some(frames) = video.get("frames").and_then(Value::as_array) {
                let frames = frames
                    .iter()
                    .filter_map(Value::as_str)
                    .map(str::to_owned)
                    .collect::<Vec<_>>();
                return vec![MediaInput {
                    kind: "video".to_owned(),
                    content_type: None,
                    url: None,
                    data: None,
                    num_frames: u32::try_from(frames.len()).ok(),
                    frames,
                    fps: video
                        .get("fps")
                        .and_then(Value::as_f64)
                        .map(|value| value as f32),
                }];
            }
            let Some(data) = video.get("data").and_then(Value::as_str).map(str::to_owned) else {
                return Vec::new();
            };
            if data.is_empty() {
                return Vec::new();
            }
            vec![MediaInput {
                kind: "video".to_owned(),
                content_type: video
                    .get("content_type")
                    .and_then(Value::as_str)
                    .map(str::to_owned),
                url: None,
                data: Some(data),
                frames: Vec::new(),
                num_frames: video
                    .get("num_frames")
                    .and_then(Value::as_u64)
                    .and_then(|value| u32::try_from(value).ok()),
                fps: video
                    .get("fps")
                    .and_then(Value::as_f64)
                    .map(|value| value as f32),
            }]
        }
        _ => Vec::new(),
    }
}

fn data_url_content_type(url: &str) -> Option<String> {
    let rest = url.strip_prefix("data:")?;
    let (content_type, _) = rest.split_once(';')?;
    (!content_type.trim().is_empty()).then(|| content_type.to_owned())
}

fn audio_content_type(format: &str) -> &'static str {
    match format {
        "mp3" => "audio/mpeg",
        "opus" => "audio/ogg",
        "aac" => "audio/aac",
        "flac" => "audio/flac",
        "pcm" => "audio/L16",
        _ => "audio/wav",
    }
}

fn provider_engine_prompt(
    messages: &[Value],
    tools: &[Value],
    specialities: &[GenerateSpecialityParameter],
    adapter: &catalog::CatalogAdapter,
) -> Result<String> {
    match adapter.chat_template_id.as_str() {
        "generic_chatml" | "qwen2.5-instruct" => {
            Ok(provider_engine_generic_chatml_prompt(messages, adapter))
        }
        "qwen3.5-instruct" => provider_engine_qwen3_prompt(messages, tools, specialities, adapter),
        "llama3-instruct" => Ok(provider_engine_llama3_prompt(messages, adapter)),
        "smolvlm2-instruct" => Ok(provider_engine_smolvlm2_prompt(messages, adapter)),
        "gemma4-instruct" => gemma4::render_prompt(messages, tools, specialities),
        other => bail!("unsupported catalog adapter.chat_template_id: {other}"),
    }
}

fn provider_engine_qwen3_prompt(
    messages: &[Value],
    tools: &[Value],
    specialities: &[GenerateSpecialityParameter],
    adapter: &catalog::CatalogAdapter,
) -> Result<String> {
    let enable_thinking = provider_engine_speciality_bool(specialities, "enable_thinking", true)?;
    let preserve_thinking =
        provider_engine_speciality_bool(specialities, "preserve_thinking", false)?;
    let mut prompt = String::new();
    let first_system = messages
        .first()
        .filter(|message| message.get("role").and_then(Value::as_str) == Some("system"));
    if tools.is_empty() {
        if let Some(system) = first_system {
            let content = provider_message_to_text_for_adapter(system, adapter);
            let _ = write!(prompt, "<|im_start|>system\n{content}<|im_end|>\n");
        }
    } else {
        prompt.push_str(
            "<|im_start|>system\n# Tools\n\nYou have access to the following functions:\n\n<tools>",
        );
        for tool in tools {
            let encoded = serde_json::to_string(tool)
                .context("serializing qwen tool definition for the native chat template")?;
            let _ = write!(prompt, "\n{encoded}");
        }
        prompt.push_str(
            "\n</tools>\n\nIf you choose to call a function ONLY reply in the following format with NO suffix:\n\n<tool_call>\n<function=example_function_name>\n<parameter=example_parameter_1>\nvalue_1\n</parameter>\n</function>\n</tool_call>\n\n<IMPORTANT>\nReminder:\n- Function calls MUST follow the specified format: an inner <function=...></function> block must be nested within <tool_call></tool_call> XML tags\n- Required parameters MUST be specified\n- You may provide optional reasoning for your function call in natural language BEFORE the function call, but NOT after\n- If there is no function call available, answer the question like normal with your current knowledge and do not tell the user about function calls\n</IMPORTANT>",
        );
        if let Some(system) = first_system {
            let content = provider_message_to_text_for_adapter(system, adapter);
            if !content.trim().is_empty() {
                let _ = write!(prompt, "\n\n{content}");
            }
        }
        prompt.push_str("<|im_end|>\n");
    }

    let mut tool_group_open = false;
    for (index, message) in messages.iter().enumerate() {
        let role = message
            .get("role")
            .and_then(Value::as_str)
            .unwrap_or("user");
        if role == "system" {
            ensure!(index == 0, "qwen system message must be first");
            continue;
        }
        let content = provider_message_to_text_for_adapter(message, adapter);
        match role {
            "user" => {
                if tool_group_open {
                    prompt.push_str("<|im_end|>\n");
                    tool_group_open = false;
                }
                let _ = write!(prompt, "<|im_start|>user\n{content}<|im_end|>\n");
            }
            "assistant" => {
                if tool_group_open {
                    prompt.push_str("<|im_end|>\n");
                    tool_group_open = false;
                }
                prompt.push_str("<|im_start|>assistant\n");
                if preserve_thinking {
                    if let Some(reasoning) = message
                        .get("reasoning_content")
                        .or_else(|| message.get("reasoning"))
                        .and_then(Value::as_str)
                        .filter(|value| !value.trim().is_empty())
                    {
                        let _ = write!(prompt, "<think>\n{}\n</think>\n\n", reasoning.trim());
                    }
                }
                if preserve_thinking {
                    prompt.push_str(&content);
                } else {
                    prompt.push_str(qwen_visible_assistant_content(&content));
                }
                provider_engine_qwen3_tool_calls(&mut prompt, message)?;
                prompt.push_str("<|im_end|>\n");
            }
            "tool" => {
                if !tool_group_open {
                    prompt.push_str("<|im_start|>user");
                    tool_group_open = true;
                }
                let _ = write!(prompt, "\n<tool_response>\n{content}\n</tool_response>");
            }
            other => bail!("unsupported qwen chat role {other}"),
        }
    }
    if tool_group_open {
        prompt.push_str("<|im_end|>\n");
    }
    prompt.push_str("<|im_start|>assistant\n");
    if enable_thinking {
        prompt.push_str("<think>\n");
    } else {
        prompt.push_str("<think>\n\n</think>\n\n");
    }
    Ok(prompt)
}

fn qwen_visible_assistant_content(content: &str) -> &str {
    let mut last_close = None;
    for close in ["</think>", "<|/think|>"] {
        if let Some(index) = content.rfind(close) {
            let end = index + close.len();
            if last_close.is_none_or(|current| end > current) {
                last_close = Some(end);
            }
        }
    }
    if let Some(end) = last_close {
        return content[end..].trim_start();
    }
    if content.contains("<think>") || content.contains("<|think|>") {
        return "";
    }
    content
}

fn provider_engine_speciality_bool(
    specialities: &[GenerateSpecialityParameter],
    native_path: &str,
    default: bool,
) -> Result<bool> {
    let Some(parameter) = specialities
        .iter()
        .find(|parameter| parameter.native_path == native_path)
    else {
        return Ok(default);
    };
    parameter.value.as_bool().with_context(|| {
        format!(
            "speciality {} native path {native_path} must map to a boolean",
            parameter.name
        )
    })
}

fn provider_engine_qwen3_tool_calls(prompt: &mut String, message: &Value) -> Result<()> {
    let Some(tool_calls) = message.get("tool_calls").and_then(Value::as_array) else {
        return Ok(());
    };
    for tool_call in tool_calls {
        let call = tool_call.get("function").unwrap_or(tool_call);
        let name = call
            .get("name")
            .and_then(Value::as_str)
            .context("qwen assistant tool call is missing function.name")?;
        let _ = write!(prompt, "\n<tool_call>\n<function={name}>\n");
        if let Some(arguments) = call.get("arguments").and_then(Value::as_object) {
            for (name, value) in arguments {
                let value = match value {
                    Value::String(value) => value.clone(),
                    value => serde_json::to_string(value)
                        .context("serializing qwen assistant tool-call argument")?,
                };
                let _ = write!(prompt, "<parameter={name}>\n{value}\n</parameter>\n");
            }
        }
        prompt.push_str("</function>\n</tool_call>");
    }
    Ok(())
}

fn provider_engine_generic_chatml_prompt(
    messages: &[Value],
    adapter: &catalog::CatalogAdapter,
) -> String {
    let mut prompt = String::new();
    for message in messages {
        let role = message
            .get("role")
            .and_then(Value::as_str)
            .unwrap_or("user");
        let content = provider_message_to_text_for_adapter(message, adapter);
        let _ = writeln!(prompt, "{role}: {content}");
    }
    prompt.push_str("assistant:");
    prompt
}

fn provider_engine_llama3_prompt(messages: &[Value], adapter: &catalog::CatalogAdapter) -> String {
    let mut prompt = String::new();
    for message in messages {
        let role = message
            .get("role")
            .and_then(Value::as_str)
            .unwrap_or("user");
        let content = provider_message_to_text_for_adapter(message, adapter);
        let _ = write!(
            prompt,
            "<|start_header_id|>{role}<|end_header_id|>\n\n{content}<|eot_id|>"
        );
    }
    prompt.push_str("<|start_header_id|>assistant<|end_header_id|>\n\n");
    prompt
}

fn provider_engine_smolvlm2_prompt(
    messages: &[Value],
    adapter: &catalog::CatalogAdapter,
) -> String {
    let mut prompt = String::new();
    for message in messages {
        let role = smolvlm2_role(
            message
                .get("role")
                .and_then(Value::as_str)
                .unwrap_or("user"),
        );
        let content = provider_message_to_text_for_adapter(message, adapter);
        if provider_message_starts_with_image(message) && adapter_supports_image_input(adapter) {
            let _ = write!(prompt, "<|im_start|>{role}:{content}<end_of_utterance>\n");
        } else {
            let _ = write!(prompt, "<|im_start|>{role}: {content}<end_of_utterance>\n");
        }
    }
    prompt.push_str("Assistant:");
    prompt
}

fn smolvlm2_role(role: &str) -> &'static str {
    match role {
        "assistant" => "Assistant",
        "system" => "System",
        _ => "User",
    }
}

fn provider_message_starts_with_image(message: &Value) -> bool {
    message
        .get("content")
        .and_then(Value::as_array)
        .and_then(|parts| parts.first())
        .and_then(|part| part.get("type"))
        .and_then(Value::as_str)
        == Some("image_url")
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ProviderEngineToolStrategy {
    MayhemJson,
    OpenAiToolCalls,
    QwenFunctionXml,
    GemmaFunctionCall,
}

#[derive(Clone, Debug)]
struct ProviderEngineToolRequest {
    strategy: ProviderEngineToolStrategy,
    tools: Vec<ToolSpec>,
    required: bool,
    parallel: bool,
}

fn provider_engine_tool_request(
    body: &Value,
    adapter: &catalog::CatalogAdapter,
) -> Result<Option<ProviderEngineToolRequest>> {
    let tool_choice = body.get("tool_choice");
    if tool_choice.and_then(Value::as_str) == Some("none") {
        return Ok(None);
    }
    let required = match tool_choice {
        None | Some(Value::Null) => false,
        Some(Value::String(choice)) if choice == "auto" => false,
        Some(Value::String(choice)) if matches!(choice.as_str(), "required" | "any") => true,
        Some(Value::Object(choice)) if provider_engine_named_tool_choice(choice).is_some() => true,
        Some(other) => {
            return Err(provider_session_request_error(format!(
                "unsupported tool_choice value: {other}"
            )));
        }
    };
    let parallel = match body.get("parallel_tool_calls") {
        None | Some(Value::Null) => true,
        Some(Value::Bool(parallel)) => *parallel,
        Some(_) => {
            return Err(provider_session_request_error(
                "parallel_tool_calls must be a boolean",
            ));
        }
    };
    let advertised_tools = body
        .get("tools")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    if advertised_tools.is_empty() {
        return Ok(None);
    }
    let tools = provider_session_request_result(provider_engine_tool_specs(body))?;
    if tools.is_empty() {
        ensure!(
            !required,
            "tool_choice requires a function that is present in tools"
        );
        return Ok(None);
    }
    let strategy = match adapter.tool_call_strategy.as_str() {
        "mayhem_json" => ProviderEngineToolStrategy::MayhemJson,
        "openai_tool_calls" => ProviderEngineToolStrategy::OpenAiToolCalls,
        "qwen_function_xml" => ProviderEngineToolStrategy::QwenFunctionXml,
        "gemma_function_call" => ProviderEngineToolStrategy::GemmaFunctionCall,
        "none" => {
            ensure!(
                !required,
                "tool_choice requires a model adapter with tool-call support"
            );
            return Ok(None);
        }
        other => bail!("unsupported catalog adapter.tool_call_strategy: {other}"),
    };
    Ok(Some(ProviderEngineToolRequest {
        strategy,
        tools,
        required,
        parallel,
    }))
}

fn provider_engine_tool_specs(body: &Value) -> Result<Vec<ToolSpec>> {
    let chosen = body
        .get("tool_choice")
        .and_then(Value::as_object)
        .and_then(provider_engine_named_tool_choice);
    let tools = body
        .get("tools")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    let mut specs = Vec::new();
    for tool in tools {
        let Some(function) = provider_engine_tool_definition(tool) else {
            continue;
        };
        let Some(name) = function.get("name").and_then(Value::as_str) else {
            continue;
        };
        if chosen.is_some_and(|chosen| chosen != name) {
            continue;
        }
        let parameters = function
            .get("parameters")
            .cloned()
            .unwrap_or_else(|| json!({ "type": "object", "additionalProperties": true }));
        let mut spec = ToolSpec::new(name, parameters);
        spec.description = function
            .get("description")
            .and_then(Value::as_str)
            .map(str::to_owned);
        specs.push(spec);
    }
    Ok(specs)
}

fn provider_engine_tool_definition(tool: &Value) -> Option<&serde_json::Map<String, Value>> {
    tool.get("function").and_then(Value::as_object).or_else(|| {
        (tool.get("type").and_then(Value::as_str) == Some("function"))
            .then(|| tool.as_object())
            .flatten()
            .filter(|tool| tool.get("name").is_some())
    })
}

fn provider_engine_named_tool_choice(choice: &serde_json::Map<String, Value>) -> Option<&str> {
    choice
        .get("function")
        .and_then(|function| function.get("name"))
        .and_then(Value::as_str)
        .or_else(|| choice.get("name").and_then(Value::as_str))
}

fn provider_openai_tool_calls_json_schema(tools: &[ToolSpec], parallel: bool) -> Value {
    let names = tools
        .iter()
        .map(|tool| Value::String(tool.name.clone()))
        .collect::<Vec<_>>();
    let mut schema = json!({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "OpenAIToolCalls",
        "type": "object",
        "additionalProperties": false,
        "required": ["tool_calls"],
        "properties": {
            "tool_calls": {
                "type": "array",
                "minItems": 1,
                "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "required": ["id", "type", "function"],
                    "properties": {
                        "id": { "type": "string" },
                        "type": { "const": "function" },
                        "function": {
                            "type": "object",
                            "additionalProperties": false,
                            "required": ["name", "arguments"],
                            "properties": {
                                "name": { "type": "string", "enum": names },
                                "arguments": { "type": "string" },
                            },
                        },
                    },
                },
            },
        },
    });
    if !parallel {
        schema["properties"]["tool_calls"]["maxItems"] = json!(1);
    }
    schema
}

fn provider_response_json_schema(body: &Value) -> Value {
    body.get("response_format")
        .and_then(|format| format.get("json_schema"))
        .and_then(|json_schema| json_schema.get("schema"))
        .or_else(|| {
            body.get("text")
                .and_then(|text| text.get("format"))
                .and_then(|format| format.get("schema"))
        })
        .cloned()
        .unwrap_or_else(|| json!({ "type": "object", "additionalProperties": true }))
}

fn provider_engine_tool_call_outputs(
    text: &str,
    strategy: ProviderEngineToolStrategy,
    tools: &[ToolSpec],
) -> Option<Vec<Value>> {
    let mut calls = match strategy {
        ProviderEngineToolStrategy::MayhemJson => provider_mayhem_json_tool_call_outputs(text),
        ProviderEngineToolStrategy::OpenAiToolCalls => provider_openai_tool_call_outputs(text),
        ProviderEngineToolStrategy::QwenFunctionXml => {
            provider_qwen_function_xml_tool_call_outputs(text)
                .or_else(|| provider_mayhem_json_tool_call_outputs(text))
        }
        ProviderEngineToolStrategy::GemmaFunctionCall => gemma4::parse_tool_calls(text)
            .map(|calls| {
                calls
                    .into_iter()
                    .map(|(name, arguments)| {
                        provider_normalized_tool_call(None, name, arguments.to_string())
                    })
                    .collect()
            })
            .or_else(|| provider_mayhem_json_tool_call_outputs(text)),
    }?;
    if calls.is_empty()
        || calls.iter().any(|call| {
            let Some(name) = call.get("name").and_then(Value::as_str) else {
                return true;
            };
            !tools.iter().any(|candidate| candidate.name == name)
        })
    {
        return None;
    }
    make_provider_tool_call_ids_unique(&mut calls)?;
    Some(calls)
}

fn provider_mayhem_json_tool_call_outputs(text: &str) -> Option<Vec<Value>> {
    let value: Value = serde_json::from_str(text.trim()).ok()?;
    let calls = value
        .get("tool_calls")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .or_else(|| value.as_array().map(Vec::as_slice));
    if let Some(calls) = calls {
        if calls.is_empty() {
            return None;
        }
        return calls
            .iter()
            .map(provider_mayhem_json_tool_call_value)
            .collect();
    }
    Some(vec![provider_mayhem_json_tool_call_value(&value)?])
}

fn provider_mayhem_json_tool_call_value(value: &Value) -> Option<Value> {
    let function = value.get("function").unwrap_or(value);
    let name = value
        .get("tool")
        .or_else(|| value.get("name"))
        .or_else(|| function.get("name"))
        .and_then(Value::as_str)?
        .to_owned();
    let arguments = provider_tool_arguments_string(
        function
            .get("arguments")
            .cloned()
            .unwrap_or_else(|| json!({})),
    );
    let id = value.get("id").and_then(Value::as_str).map(str::to_owned);
    Some(provider_normalized_tool_call(id, name, arguments))
}

fn provider_openai_tool_call_outputs(text: &str) -> Option<Vec<Value>> {
    let value: Value = serde_json::from_str(text.trim()).ok()?;
    if let Some(calls) = value.get("tool_calls").and_then(Value::as_array) {
        if calls.is_empty() {
            return None;
        }
        return calls.iter().map(provider_openai_tool_call_value).collect();
    }
    Some(vec![provider_openai_tool_call_value(&value)?])
}

fn provider_openai_tool_call_value(call: &Value) -> Option<Value> {
    let function = call.get("function")?;
    let name = function.get("name").and_then(Value::as_str)?.to_owned();
    let arguments = provider_tool_arguments_string(
        function
            .get("arguments")
            .cloned()
            .unwrap_or_else(|| json!({})),
    );
    let id = call.get("id").and_then(Value::as_str).map(str::to_owned);
    Some(provider_normalized_tool_call(id, name, arguments))
}

fn provider_qwen_function_xml_tool_call_outputs(text: &str) -> Option<Vec<Value>> {
    const TOOL_OPEN: &str = "<tool_call>";
    const TOOL_CLOSE: &str = "</tool_call>";

    let first_tool = text.find(TOOL_OPEN)?;
    let mut remaining = &text[first_tool..];
    let mut calls = Vec::new();
    while !remaining.trim().is_empty() {
        remaining = remaining.trim_start();
        let tool_body = remaining.strip_prefix(TOOL_OPEN)?;
        let tool_end = tool_body.find(TOOL_CLOSE)?;
        calls.push(provider_qwen_function_xml_tool_call_body(
            tool_body[..tool_end].trim(),
        )?);
        remaining = &tool_body[tool_end + TOOL_CLOSE.len()..];
    }
    (!calls.is_empty()).then_some(calls)
}

fn provider_qwen_function_xml_tool_call_body(tool_body: &str) -> Option<Value> {
    const FUNCTION_OPEN: &str = "<function=";
    const FUNCTION_CLOSE: &str = "</function>";
    const PARAMETER_OPEN: &str = "<parameter=";
    const PARAMETER_CLOSE: &str = "</parameter>";

    let function_start = tool_body.find(FUNCTION_OPEN)? + FUNCTION_OPEN.len();
    if !tool_body[..function_start - FUNCTION_OPEN.len()]
        .trim()
        .is_empty()
    {
        return None;
    }
    let function_name_end = tool_body[function_start..].find('>')? + function_start;
    let function_name = tool_body[function_start..function_name_end].trim();
    if function_name.is_empty() {
        return None;
    }
    let function_body_start = function_name_end + 1;
    let function_body_end_relative = tool_body[function_body_start..].rfind(FUNCTION_CLOSE)?;
    let function_body_end = function_body_start + function_body_end_relative;
    if !tool_body[function_body_end + FUNCTION_CLOSE.len()..]
        .trim()
        .is_empty()
    {
        return None;
    }

    let mut arguments = serde_json::Map::new();
    let mut remaining = tool_body[function_body_start..function_body_end].trim();
    while !remaining.is_empty() {
        if !remaining.starts_with(PARAMETER_OPEN) {
            return None;
        }
        let name_start = PARAMETER_OPEN.len();
        let name_end = remaining[name_start..].find('>')? + name_start;
        let name = remaining[name_start..name_end].trim();
        if name.is_empty() || arguments.contains_key(name) {
            return None;
        }
        let value_start = name_end + 1;
        let value_end = remaining[value_start..].find(PARAMETER_CLOSE)? + value_start;
        let raw_value = remaining[value_start..value_end].trim();
        let value =
            serde_json::from_str(raw_value).unwrap_or_else(|_| Value::String(raw_value.to_owned()));
        arguments.insert(name.to_owned(), value);
        remaining = remaining[value_end + PARAMETER_CLOSE.len()..].trim();
    }

    Some(provider_normalized_tool_call(
        None,
        function_name.to_owned(),
        Value::Object(arguments).to_string(),
    ))
}

fn make_provider_tool_call_ids_unique(calls: &mut [Value]) -> Option<()> {
    let mut seen = BTreeSet::new();
    for (index, call) in calls.iter_mut().enumerate() {
        let object = call.as_object_mut()?;
        let current = object.get("id").and_then(Value::as_str)?.to_owned();
        if seen.insert(current) {
            continue;
        }
        let name = object.get("name").and_then(Value::as_str)?;
        let arguments = object.get("arguments").and_then(Value::as_str)?;
        let id = format!(
            "call-{}",
            stable_value_hash(&json!({
                "tool": name,
                "arguments": arguments,
                "occurrence": index,
            }))
        );
        if !seen.insert(id.clone()) {
            return None;
        }
        object.insert("id".to_owned(), Value::String(id));
    }
    Some(())
}

fn provider_tool_arguments_string(arguments: Value) -> String {
    arguments
        .as_str()
        .map(str::to_owned)
        .unwrap_or_else(|| arguments.to_string())
}

fn provider_normalized_tool_call(id: Option<String>, name: String, arguments: String) -> Value {
    let id = id.unwrap_or_else(|| {
        format!(
            "call-{}",
            stable_value_hash(&json!({ "tool": name, "arguments": arguments }))
        )
    });
    json!({
        "id": id,
        "name": name,
        "arguments": arguments,
    })
}

fn provider_session_response(terms: &ProviderSessionTerms, body: &Value) -> ProviderSessionOutput {
    let messages = body
        .get("messages")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    let prompt = messages
        .iter()
        .map(provider_message_to_text)
        .collect::<Vec<_>>()
        .join("\n");
    let prompt_tokens = rough_text_tokens(&prompt);
    if let Some(tool_result) = messages
        .iter()
        .rev()
        .find(|message| message.get("role").and_then(Value::as_str) == Some("tool"))
        .map(provider_message_to_text)
    {
        let content = format!("Tool result received: {tool_result}");
        let completion_tokens = rough_text_tokens(&content);
        return ProviderSessionOutput {
            usage: provider_chat_receipt_usage(body, prompt_tokens, completion_tokens),
            completion_tokens,
            token_ids: synthetic_provider_token_ids(completion_tokens),
            content,
            reasoning_evidence: String::new(),
            tools: Vec::new(),
            embeddings: None,
            transcription: None,
            artifacts: Vec::new(),
            finish_reason: "stop".to_owned(),
            prompt_tokens,
            usage_attribution: BTreeMap::new(),
        };
    }
    let prompt_lower = prompt.to_lowercase();
    if prompt.contains(OPENCODE_TEST_MARKER) || prompt_lower.contains("bash tool") {
        return ProviderSessionOutput {
            usage: provider_chat_receipt_usage(body, prompt_tokens, 1),
            content: String::new(),
            reasoning_evidence: String::new(),
            tools: vec![json!({
                "id": format!("call-{}", stable_value_hash(&json!({ "tool": "bash", "prompt": prompt }))),
                "name": "bash",
                "arguments": provider_tool_arguments("bash"),
            })],
            finish_reason: "tool_calls".to_owned(),
            embeddings: None,
            transcription: None,
            artifacts: Vec::new(),
            prompt_tokens,
            completion_tokens: 1,
            token_ids: Vec::new(),
            usage_attribution: BTreeMap::new(),
        };
    }
    if let Some(tool_name) = provider_requested_tool_name(body) {
        return ProviderSessionOutput {
            usage: provider_chat_receipt_usage(body, prompt_tokens, 1),
            content: String::new(),
            reasoning_evidence: String::new(),
            tools: vec![json!({
                "id": format!("call-{}", stable_value_hash(&json!({ "tool": tool_name, "prompt": prompt }))),
                "name": tool_name,
                "arguments": provider_tool_arguments(&tool_name),
            })],
            finish_reason: "tool_calls".to_owned(),
            embeddings: None,
            transcription: None,
            artifacts: Vec::new(),
            prompt_tokens,
            completion_tokens: 1,
            token_ids: Vec::new(),
            usage_attribution: BTreeMap::new(),
        };
    }
    let content = if provider_wants_json(body) {
        json!({
            "ok": true,
            "model": &terms.model_id,
            "provider": &terms.provider,
        })
        .to_string()
    } else {
        format!(
            "Mayhem provider response from {}: {}",
            terms.model_id,
            provider_last_user_text(messages)
        )
    };
    let completion_tokens = rough_text_tokens(&content);
    ProviderSessionOutput {
        usage: provider_chat_receipt_usage(body, prompt_tokens, completion_tokens),
        completion_tokens,
        token_ids: synthetic_provider_token_ids(completion_tokens),
        content,
        reasoning_evidence: String::new(),
        tools: Vec::new(),
        embeddings: None,
        transcription: None,
        artifacts: Vec::new(),
        finish_reason: "stop".to_owned(),
        prompt_tokens,
        usage_attribution: BTreeMap::new(),
    }
}

fn provider_chat_receipt_usage(
    body: &Value,
    prompt_tokens: u64,
    completion_tokens: u64,
) -> ReceiptUsage {
    let _ = provider_chat_media_stats(body);
    ReceiptUsage::from_units([
        (INPUT_TOKEN_UNIT, prompt_tokens),
        (OUTPUT_TOKEN_UNIT, completion_tokens),
    ])
}

fn provider_requested_tool_name(body: &Value) -> Option<String> {
    if body.get("tool_choice").and_then(Value::as_str) == Some("none") {
        return None;
    }
    if let Some(name) = body
        .get("tool_choice")
        .and_then(|choice| choice.get("function"))
        .and_then(|function| function.get("name"))
        .and_then(Value::as_str)
    {
        return Some(name.to_owned());
    }
    body.get("tools")?.as_array()?.iter().find_map(|tool| {
        tool.get("function")?
            .get("name")?
            .as_str()
            .map(str::to_owned)
    })
}

fn provider_tool_arguments(name: &str) -> String {
    match name {
        "bash" => json!({ "command": "printf mayhem-opencode-tool-ok" }).to_string(),
        "write" => {
            json!({ "filePath": "mayhem-opencode-tool-ok.txt", "content": "mayhem-opencode-tool-ok" })
                .to_string()
        }
        _ => "{}".to_owned(),
    }
}

fn provider_wants_json(body: &Value) -> bool {
    matches!(
        body.get("response_format")
            .and_then(|format| format.get("type"))
            .or_else(|| {
                body.get("text")
                    .and_then(|text| text.get("format"))
                    .and_then(|format| format.get("type"))
            })
            .and_then(Value::as_str),
        Some("json_object" | "json_schema")
    )
}

fn provider_last_user_text(messages: &[Value]) -> String {
    messages
        .iter()
        .rev()
        .find(|message| message.get("role").and_then(Value::as_str) == Some("user"))
        .map(provider_message_to_text)
        .unwrap_or_default()
}

fn provider_message_to_text(message: &Value) -> String {
    provider_content_to_text(message.get("content").unwrap_or(&Value::Null))
}

fn provider_message_to_text_for_adapter(
    message: &Value,
    adapter: &catalog::CatalogAdapter,
) -> String {
    let content = provider_content_to_text_for_adapter(
        message.get("content").unwrap_or(&Value::Null),
        adapter,
    );
    if adapter.reasoning_passthrough != "preserve" {
        return content;
    }
    let Some(reasoning) = message.get("reasoning").and_then(Value::as_str) else {
        return content;
    };
    if content.trim().is_empty() {
        reasoning.to_owned()
    } else {
        format!("{reasoning}\n{content}")
    }
}

fn provider_content_to_text_for_adapter(
    value: &Value,
    adapter: &catalog::CatalogAdapter,
) -> String {
    match value {
        Value::Null => String::new(),
        Value::String(text) => text.clone(),
        Value::Array(parts) => parts
            .iter()
            .map(|part| provider_content_part_to_text_for_adapter(part, adapter))
            .collect::<Vec<_>>()
            .join(""),
        other => other.to_string(),
    }
}

fn provider_content_part_to_text_for_adapter(
    part: &Value,
    adapter: &catalog::CatalogAdapter,
) -> String {
    match part.get("type").and_then(Value::as_str) {
        Some("image_url") if adapter_supports_input(adapter, "image") => {
            return MTMD_MEDIA_MARKER.to_owned();
        }
        Some("input_audio") if adapter_supports_input(adapter, "audio") => {
            return MTMD_MEDIA_MARKER.to_owned();
        }
        Some("video") if adapter_supports_input(adapter, "video") => {
            let frame_count = part
                .get("video")
                .and_then(|video| video.get("frames"))
                .and_then(Value::as_array)
                .map(Vec::len)
                .or_else(|| {
                    part.get("video")
                        .and_then(|video| video.get("num_frames"))
                        .and_then(Value::as_u64)
                        .and_then(|value| usize::try_from(value).ok())
                })
                .unwrap_or(1);
            return MTMD_MEDIA_MARKER.repeat(frame_count);
        }
        _ => {}
    }
    provider_content_part_to_text(part)
}

fn adapter_supports_image_input(adapter: &catalog::CatalogAdapter) -> bool {
    adapter_supports_input(adapter, "image")
}

fn adapter_supports_input(adapter: &catalog::CatalogAdapter, requested: &str) -> bool {
    adapter
        .modality_set
        .iter()
        .any(|modality| modality == requested || (requested == "image" && modality == "vision"))
}

fn provider_content_to_text(value: &Value) -> String {
    match value {
        Value::Null => String::new(),
        Value::String(text) => text.clone(),
        Value::Array(parts) => parts
            .iter()
            .map(provider_content_part_to_text)
            .collect::<Vec<_>>()
            .join(""),
        other => other.to_string(),
    }
}

fn provider_content_part_to_text(part: &Value) -> String {
    match part.get("type").and_then(Value::as_str) {
        Some("text") => part
            .get("text")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned(),
        Some("image_url") => {
            let url = part
                .get("image_url")
                .and_then(|image| image.get("url"))
                .or_else(|| part.get("url"))
                .and_then(Value::as_str)
                .unwrap_or_default();
            format!("[image:{}]", blake3::hash(url.as_bytes()).to_hex())
        }
        Some("input_audio") => {
            let audio = part.get("input_audio").unwrap_or(&Value::Null);
            let format = audio
                .get("format")
                .and_then(Value::as_str)
                .unwrap_or("unknown");
            let data = audio
                .get("data")
                .and_then(Value::as_str)
                .unwrap_or_default();
            format!(
                "[audio:{format}:{}]",
                blake3::hash(data.as_bytes()).to_hex()
            )
        }
        _ => part
            .get("text")
            .and_then(Value::as_str)
            .map(str::to_owned)
            .unwrap_or_else(|| provider_content_to_text(part)),
    }
}

#[derive(Default)]
struct IncrementalRoughTokenCounter {
    count: u64,
    in_token: bool,
}

impl IncrementalRoughTokenCounter {
    fn observe(&mut self, text: &str) {
        for character in text.chars() {
            if character.is_whitespace() {
                self.in_token = false;
            } else if !self.in_token {
                self.count = self.count.saturating_add(1);
                self.in_token = true;
            }
        }
    }
}

fn provider_stream_parts(content: &str, max_part_bytes: usize) -> Vec<&str> {
    if content.is_empty() {
        return Vec::new();
    }
    let max_part_bytes = max_part_bytes.max(4);
    let mut parts = Vec::with_capacity(content.len().div_ceil(max_part_bytes));
    let mut start = 0;
    while start < content.len() {
        let mut end = start.saturating_add(max_part_bytes).min(content.len());
        while end > start && !content.is_char_boundary(end) {
            end -= 1;
        }
        if end == start {
            end = content[start..]
                .char_indices()
                .nth(1)
                .map(|(offset, _)| start + offset)
                .unwrap_or(content.len());
        }
        parts.push(&content[start..end]);
        start = end;
    }
    parts
}

fn rough_text_tokens(text: &str) -> u64 {
    if text.trim().is_empty() {
        0
    } else {
        text.split_whitespace().count() as u64
    }
}

fn synthetic_provider_token_ids(count: u64) -> Vec<i32> {
    let count = usize::try_from(count.min(i32::MAX as u64)).unwrap_or(i32::MAX as usize);
    (0..count)
        .map(|idx| i32::try_from(idx).unwrap_or(i32::MAX))
        .collect()
}

fn is_hex_len(value: &str, len: usize) -> bool {
    value.len() == len && value.as_bytes().iter().all(|byte| byte.is_ascii_hexdigit())
}

fn is_safe_key_part(value: &str) -> bool {
    !value.is_empty()
        && !value.starts_with('-')
        && value.len() <= 128
        && value
            .as_bytes()
            .iter()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b':' | b'-'))
}

fn is_false(value: &bool) -> bool {
    !*value
}

fn hex_encode(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(HEX[(byte >> 4) as usize] as char);
        out.push(HEX[(byte & 0x0f) as usize] as char);
    }
    out
}

fn hex_decode_array<const N: usize>(value: &str, label: &str) -> Result<[u8; N]> {
    if value.len() != N * 2 {
        bail!("{label} must be {N} bytes of hex");
    }
    let mut out = [0_u8; N];
    let bytes = value.as_bytes();
    for index in 0..N {
        let high = hex_nibble(bytes[index * 2]).with_context(|| format!("{label} is not hex"))?;
        let low =
            hex_nibble(bytes[index * 2 + 1]).with_context(|| format!("{label} is not hex"))?;
        out[index] = (high << 4) | low;
    }
    Ok(out)
}

fn hex_decode_vec(value: &str, label: &str) -> Result<Vec<u8>> {
    if value.len() % 2 != 0 {
        bail!("{label} must be even-length hex");
    }
    let bytes = value.as_bytes();
    let mut out = Vec::with_capacity(bytes.len() / 2);
    for index in (0..bytes.len()).step_by(2) {
        let high = hex_nibble(bytes[index]).with_context(|| format!("{label} is not hex"))?;
        let low = hex_nibble(bytes[index + 1]).with_context(|| format!("{label} is not hex"))?;
        out.push((high << 4) | low);
    }
    Ok(out)
}

fn hex_nibble(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

fn wav_sample_rate(bytes: &[u8]) -> Option<u32> {
    Some(validated_wav_audio_metadata(bytes)?.sample_rate)
}

fn wav_duration_seconds_ceil(bytes: &[u8]) -> Option<u64> {
    Some(validated_wav_audio_metadata(bytes)?.duration_seconds_ceil)
}

fn audio_duration_seconds_ceil(bytes: &[u8]) -> Option<u64> {
    Some(validated_audio_metadata(bytes)?.duration_seconds_ceil)
}

fn detected_audio_content_type(bytes: &[u8]) -> Option<&'static str> {
    match validated_audio_metadata(bytes)?.format {
        ValidatedAudioFormat::Wav => Some("audio/wav"),
        ValidatedAudioFormat::Flac => Some("audio/flac"),
        ValidatedAudioFormat::Mp3 => Some("audio/mpeg"),
        ValidatedAudioFormat::Opus => Some("audio/ogg"),
        ValidatedAudioFormat::Aac => Some("audio/mp4"),
    }
}

fn repeat_wav_audio(bytes: &[u8], repeat_count: u32) -> Result<Vec<u8>> {
    validated_wav_audio_metadata(bytes).context("audio fixture is not a valid bounded WAV file")?;
    ensure!(repeat_count > 0, "WAV repeat count must be positive");
    if repeat_count == 1 {
        return Ok(bytes.to_vec());
    }

    let mut offset = 12usize;
    let mut data_chunk = None;
    while offset
        .checked_add(8)
        .is_some_and(|chunk_header_end| chunk_header_end <= bytes.len())
    {
        let chunk_len = usize::try_from(u32::from_le_bytes(
            bytes[offset + 4..offset + 8]
                .try_into()
                .context("WAV chunk length is malformed")?,
        ))
        .context("WAV chunk length overflowed usize")?;
        let chunk_start = offset
            .checked_add(8)
            .context("WAV chunk start overflowed")?;
        let chunk_end = chunk_start
            .checked_add(chunk_len)
            .context("WAV chunk end overflowed")?;
        ensure!(chunk_end <= bytes.len(), "WAV chunk exceeds file length");
        let padded_end = chunk_end
            .checked_add(chunk_len % 2)
            .context("WAV padded chunk end overflowed")?;
        ensure!(padded_end <= bytes.len(), "WAV chunk padding is truncated");
        if &bytes[offset..offset + 4] == b"data" {
            ensure!(data_chunk.is_none(), "WAV fixture has multiple data chunks");
            data_chunk = Some((offset, chunk_start, chunk_end, padded_end));
        }
        offset = padded_end;
    }
    let (data_header, data_start, data_end, padded_end) =
        data_chunk.context("WAV fixture has no data chunk")?;
    let source_data = &bytes[data_start..data_end];
    ensure!(!source_data.is_empty(), "WAV fixture data chunk is empty");
    let repeated_len = source_data
        .len()
        .checked_mul(usize::try_from(repeat_count).context("WAV repeat count overflowed usize")?)
        .context("repeated WAV data length overflowed")?;
    let repeated_len_u32 =
        u32::try_from(repeated_len).context("repeated WAV data exceeds the RIFF 32-bit limit")?;
    let repeated_padded_len = repeated_len
        .checked_add(repeated_len % 2)
        .context("repeated WAV padded length overflowed")?;
    let output_len = data_start
        .checked_add(repeated_padded_len)
        .and_then(|len| len.checked_add(bytes.len().saturating_sub(padded_end)))
        .context("repeated WAV file length overflowed")?;
    ensure!(
        output_len <= 256 * 1024 * 1024,
        "repeated WAV fixture exceeds the 256 MiB calibration limit"
    );

    let mut output = Vec::with_capacity(output_len);
    output.extend_from_slice(&bytes[..data_start]);
    for _ in 0..repeat_count {
        output.extend_from_slice(source_data);
    }
    if repeated_len % 2 == 1 {
        output.push(0);
    }
    output.extend_from_slice(&bytes[padded_end..]);
    output[data_header + 4..data_header + 8].copy_from_slice(&repeated_len_u32.to_le_bytes());
    let riff_len = u32::try_from(output.len().saturating_sub(8))
        .context("repeated WAV RIFF length exceeds the 32-bit limit")?;
    output[4..8].copy_from_slice(&riff_len.to_le_bytes());
    ensure!(
        wav_duration_seconds_ceil(&output).is_some(),
        "repeated WAV fixture failed duration validation"
    );
    Ok(output)
}

fn safe_path_component(value: &str) -> String {
    value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.') {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

fn is_32_byte_hex(value: &str) -> bool {
    value.len() == 64 && value.as_bytes().iter().all(u8::is_ascii_hexdigit)
}

fn unix_epoch_seconds() -> Result<u64> {
    Ok(SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system time is before Unix epoch")?
        .as_secs())
}

fn unix_epoch_millis() -> Result<u64> {
    let millis = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system time is before Unix epoch")?
        .as_millis();
    u64::try_from(millis).context("Unix epoch milliseconds overflowed u64")
}

fn default_home() -> Result<PathBuf> {
    if let Ok(home) = env::var("MAYHEM_HOME") {
        let home = home.trim();
        if !home.is_empty() {
            return Ok(PathBuf::from(home));
        }
    }

    let user_home = env::var("HOME").context("HOME is not set; pass --home")?;
    Ok(PathBuf::from(user_home).join(".mayhem"))
}

fn user_home_dir() -> Result<PathBuf> {
    if let Ok(home) = env::var("HOME") {
        let home = home.trim();
        if !home.is_empty() {
            return Ok(PathBuf::from(home));
        }
    }
    if let Ok(home) = env::var("USERPROFILE") {
        let home = home.trim();
        if !home.is_empty() {
            return Ok(PathBuf::from(home));
        }
    }
    bail!("HOME/USERPROFILE is not set; pass an explicit path")
}

fn default_rules_path() -> Result<PathBuf> {
    if let Ok(repo_rules) = repo_path("RULES.md") {
        if repo_rules.exists() {
            return absolutize(repo_rules);
        }
    }
    let cwd_rules = PathBuf::from("RULES.md");
    if cwd_rules.exists() {
        return absolutize(cwd_rules);
    }
    bail!(
        "RULES.md was not found; set MAYHEM_ASSET_DIR to the Mayhem release/share directory or pass --rules-path"
    )
}

fn repo_path(relative: &str) -> Result<PathBuf> {
    let relative_path = validate_asset_relative_path(relative)?;
    Ok(mayhem_asset_root()?.join(relative_path))
}

fn validate_asset_relative_path(relative: &str) -> Result<PathBuf> {
    let path = PathBuf::from(relative);
    if path.as_os_str().is_empty() || path.is_absolute() {
        bail!("asset path must be relative: {relative:?}");
    }
    for component in path.components() {
        match component {
            Component::Normal(_) => {}
            _ => bail!("asset path must not contain traversal: {relative:?}"),
        }
    }
    Ok(path)
}

fn mayhem_asset_root() -> Result<PathBuf> {
    if let Some(value) = env::var_os("MAYHEM_ASSET_DIR") {
        let root = absolutize(PathBuf::from(value))?;
        if mayhem_asset_root_marker(&root) {
            return Ok(asset_root_for_child_process(root));
        }
        bail!(
            "MAYHEM_ASSET_DIR={} does not look like a Mayhem asset directory",
            root.display()
        );
    }

    let mut candidates = Vec::new();
    if let Ok(exe) = env::current_exe() {
        if let Some(dir) = exe.parent() {
            push_asset_root_candidates(&mut candidates, dir);
        }
    }
    if let Ok(cwd) = env::current_dir() {
        push_asset_root_candidates(&mut candidates, &cwd);
    }

    for candidate in candidates {
        if mayhem_asset_root_marker(&candidate) {
            return Ok(asset_root_for_child_process(candidate));
        }
    }

    bail!(
        "Mayhem assets were not found; set MAYHEM_ASSET_DIR to the release/share directory or run from a Mayhem checkout"
    )
}

fn asset_root_for_child_process(root: PathBuf) -> PathBuf {
    let canonical = fs::canonicalize(&root).unwrap_or(root);
    let Some(text) = canonical.to_str() else {
        return canonical;
    };
    if let Some(rest) = text.strip_prefix(r"\\?\UNC\") {
        return PathBuf::from(format!(r"\\{rest}"));
    }
    if let Some(rest) = text.strip_prefix(r"\\?\") {
        return PathBuf::from(rest);
    }
    canonical
}

fn push_asset_root_candidates(out: &mut Vec<PathBuf>, start: &Path) {
    for ancestor in start.ancestors().take(6) {
        push_unique_path(out, ancestor.join("share").join("mayhem"));
        push_unique_path(out, ancestor.join("share"));
        push_unique_path(out, ancestor.to_path_buf());
    }
}

fn push_unique_path(out: &mut Vec<PathBuf>, path: PathBuf) {
    if !out.iter().any(|existing| existing == &path) {
        out.push(path);
    }
}

fn mayhem_asset_root_marker(root: &Path) -> bool {
    root.join("catalog").join("models.json").is_file()
        || root.join("intercom").join("package.json").is_file()
        || root.join("RULES.md").is_file()
}

fn absolutize(path: PathBuf) -> Result<PathBuf> {
    if path.is_absolute() {
        return Ok(path);
    }
    Ok(env::current_dir()?.join(path))
}

fn read_mayhem_config(home: &Path) -> Result<Option<MayhemConfig>> {
    let config_path = home.join("config.toml");
    if !config_path.exists() {
        return Ok(None);
    }
    let text = fs::read_to_string(&config_path)
        .with_context(|| format!("reading {}", config_path.display()))?;
    let config =
        toml::from_str(&text).with_context(|| format!("parsing {}", config_path.display()))?;
    Ok(Some(config))
}

fn config_path_for_home(home: &Path) -> PathBuf {
    home.join("config.toml")
}

fn read_config_toml_value(path: &Path) -> Result<toml::Value> {
    if !path.exists() {
        return Ok(toml::Value::Table(toml::map::Map::new()));
    }
    let text = fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    if text.trim().is_empty() {
        return Ok(toml::Value::Table(toml::map::Map::new()));
    }
    let value: toml::Value =
        toml::from_str(&text).with_context(|| format!("parsing {}", path.display()))?;
    if !value.is_table() {
        bail!("{} must contain a TOML table", path.display());
    }
    Ok(value)
}

fn write_config_toml_value(path: &Path, value: &toml::Value) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    write_private_file(path, toml::to_string_pretty(value)?.as_bytes())
        .with_context(|| format!("writing {}", path.display()))?;
    Ok(())
}

fn write_private_file(path: &Path, bytes: &[u8]) -> Result<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};

        let mut file = fs::OpenOptions::new()
            .create(true)
            .truncate(true)
            .write(true)
            .mode(0o600)
            .open(path)?;
        file.write_all(bytes)?;
        file.set_permissions(fs::Permissions::from_mode(0o600))?;
        return Ok(());
    }
    #[cfg(not(unix))]
    {
        fs::write(path, bytes)?;
        Ok(())
    }
}

fn canonical_config_key(key: &str) -> Result<&'static str> {
    let normalized = key.trim().replace('-', "_");
    match normalized.as_str() {
        "home" | "mayhem_home" => {
            bail!("home selects the config location and is not stored inside config.toml")
        }
        "network" | "network.name" | "trac_network" | "network.trac_network" => {
            Ok("network.name")
        }
        "rpc_url" | "network.rpc_url" => Ok("network.rpc_url"),
        "gateway_url" | "network.gateway_url" => Ok("network.gateway_url"),
        "sc_bridge_url" | "network.sc_bridge_url" => Ok("network.sc_bridge_url"),
        "sc_bridge_token" | "network.sc_bridge_token" => Ok("network.sc_bridge_token"),
        "tnk_treasury_address" | "network.tnk_treasury_address" => {
            Ok("network.tnk_treasury_address")
        }
        "admin_peer_pubkey" | "network.admin_peer_pubkey" => {
            Ok("network.admin_peer_pubkey")
        }
        "subnet_channel" | "network.subnet_channel" => Ok("network.subnet_channel"),
        "subnet_bootstrap" | "network.subnet_bootstrap" => Ok("network.subnet_bootstrap"),
        "msb_channel" | "network.msb_channel" => Ok("network.msb_channel"),
        "msb_bootstrap" | "network.msb_bootstrap" => Ok("network.msb_bootstrap"),
        "keypair_path" | "identity.keypair_path" => Ok("identity.keypair_path"),
        "store_name" | "identity.store_name" => Ok("identity.store_name"),
        "engine_backend" | "provider.engine_backend" => Ok("provider.engine_backend"),
        "memory_reserve"
        | "provider_memory_reserve"
        | "provider.memory_reserve"
        | "provider.limits.memory_reserve" => Ok("provider.limits.memory_reserve"),
        "disk_reserve"
        | "provider_disk_reserve"
        | "provider.disk_reserve"
        | "provider.limits.disk_reserve" => Ok("provider.limits.disk_reserve"),
        "max_price" | "max_price_au" | "user.max_price" | "user.max_price_au" => {
            Ok("user.max_price_au")
        }
        "max_wait" | "max_wait_seconds" | "user.max_wait" | "user.max_wait_seconds" => {
            Ok("user.max_wait_seconds")
        }
        "min_ctx" | "user.min_ctx" => Ok("user.min_ctx"),
        "rail" | "user.rail" => Ok("user.rail"),
        "role" | "role.mode" => Ok("role.mode"),
        "" => bail!("config key must not be empty"),
        _ => bail!("unsupported config key {key}; supported keys are network, rpc_url, gateway_url, sc_bridge_url, sc_bridge_token, tnk_treasury_address, admin_peer_pubkey, subnet_channel, subnet_bootstrap, msb_channel, msb_bootstrap, identity.keypair_path, identity.store_name, provider.engine_backend, provider.limits.memory_reserve, provider.limits.disk_reserve, user.rail, user.max_price_au, user.max_wait_seconds, user.min_ctx, and role.mode"),
    }
}

fn toml_get_path<'a>(value: &'a toml::Value, key: &str) -> Option<&'a toml::Value> {
    let mut cursor = value;
    for segment in key.split('.') {
        cursor = cursor.as_table()?.get(segment)?;
    }
    Some(cursor)
}

fn toml_set_string(value: &mut toml::Value, key: &str, new_value: String) -> Result<()> {
    let segments = key.split('.').collect::<Vec<_>>();
    let Some((last, parents)) = segments.split_last() else {
        bail!("config key must not be empty");
    };
    let mut table = value
        .as_table_mut()
        .context("config root must contain a TOML table")?;
    for segment in parents {
        let entry = table
            .entry((*segment).to_owned())
            .or_insert_with(|| toml::Value::Table(toml::map::Map::new()));
        if !entry.is_table() {
            bail!("{segment} exists in config.toml but is not a table");
        }
        table = entry.as_table_mut().expect("checked table");
    }
    table.insert((*last).to_owned(), toml::Value::String(new_value));
    Ok(())
}

fn toml_set_u64(value: &mut toml::Value, key: &str, new_value: u64) -> Result<()> {
    let segments = key.split('.').collect::<Vec<_>>();
    let Some((last, parents)) = segments.split_last() else {
        bail!("config key must not be empty");
    };
    let table = ensure_toml_table_path(value, parents)?;
    table.insert(
        (*last).to_owned(),
        toml::Value::Integer(i64::try_from(new_value).context("config integer exceeds i64")?),
    );
    Ok(())
}

fn toml_set_money_au(value: &mut toml::Value, key: &str, new_value: MoneyAu) -> Result<()> {
    toml_set_string(value, key, new_value.to_string())
}

fn toml_table_set_u64(
    table: &mut toml::map::Map<String, toml::Value>,
    key: &str,
    new_value: u64,
) -> Result<()> {
    table.insert(
        key.to_owned(),
        toml::Value::Integer(i64::try_from(new_value).context("config integer exceeds i64")?),
    );
    Ok(())
}

fn toml_table_set_money_au(
    table: &mut toml::map::Map<String, toml::Value>,
    key: &str,
    new_value: MoneyAu,
) -> Result<()> {
    table.insert(key.to_owned(), toml::Value::String(new_value.to_string()));
    Ok(())
}

fn toml_table_set_string(
    table: &mut toml::map::Map<String, toml::Value>,
    key: &str,
    new_value: String,
) {
    table.insert(key.to_owned(), toml::Value::String(new_value));
}

fn toml_remove_path(value: &mut toml::Value, key: &str) -> Result<()> {
    let segments = key.split('.').collect::<Vec<_>>();
    let Some((last, parents)) = segments.split_last() else {
        bail!("config key must not be empty");
    };
    let mut table = value
        .as_table_mut()
        .context("config root must contain a TOML table")?;
    for segment in parents {
        let Some(next) = table.get_mut(*segment) else {
            return Ok(());
        };
        if !next.is_table() {
            return Ok(());
        }
        table = next.as_table_mut().expect("checked table");
    }
    table.remove(*last);
    Ok(())
}

fn ensure_toml_table_path<'a>(
    value: &'a mut toml::Value,
    segments: &[&str],
) -> Result<&'a mut toml::map::Map<String, toml::Value>> {
    let mut table = value
        .as_table_mut()
        .context("config root must contain a TOML table")?;
    for segment in segments {
        let entry = table
            .entry((*segment).to_owned())
            .or_insert_with(|| toml::Value::Table(toml::map::Map::new()));
        if !entry.is_table() {
            bail!("{segment} exists in config.toml but is not a table");
        }
        table = entry.as_table_mut().expect("checked table");
    }
    Ok(table)
}

fn remove_local_state_path(path: &Path) -> Result<bool> {
    if !path.exists() {
        return Ok(false);
    }
    let metadata =
        fs::symlink_metadata(path).with_context(|| format!("reading {}", path.display()))?;
    let file_type = metadata.file_type();
    if file_type.is_dir() && !file_type.is_symlink() {
        fs::remove_dir_all(path).with_context(|| format!("removing {}", path.display()))?;
    } else {
        fs::remove_file(path).with_context(|| format!("removing {}", path.display()))?;
    }
    Ok(true)
}

fn read_rules_doc(path: Option<&Path>) -> Result<RulesDoc> {
    let path = match path {
        Some(path) => absolutize(path.to_path_buf())?,
        None => default_rules_path()?,
    };
    let path = fs::canonicalize(&path).unwrap_or(path);
    let bytes = fs::read(&path).with_context(|| format!("reading {}", path.display()))?;
    let text = String::from_utf8(bytes.clone())
        .with_context(|| format!("{} must be valid UTF-8", path.display()))?;
    let hash = blake3::hash(&bytes).to_hex().to_string();
    Ok(RulesDoc {
        path,
        text,
        hash,
        bytes: bytes.len(),
    })
}

fn rules_state_dir(home: &Path) -> PathBuf {
    home.join("rules")
}

fn read_current_accepted_rules(home: &Path) -> Result<Option<String>> {
    let path = rules_state_dir(home).join("current.md");
    if !path.exists() {
        return Ok(None);
    }
    let text = fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
    Ok(Some(text))
}

fn portable_rules_metadata_path(path: &Path) -> String {
    let portable = env::current_dir()
        .ok()
        .and_then(|cwd| path.strip_prefix(cwd).ok().map(Path::to_path_buf))
        .or_else(|| path.file_name().map(PathBuf::from))
        .unwrap_or_else(|| path.to_path_buf());
    portable.to_string_lossy().replace('\\', "/")
}

fn persist_rules_acceptance(home: &Path, rules_doc: &RulesDoc, rules: &RulesRef) -> Result<()> {
    let dir = rules_state_dir(home);
    fs::create_dir_all(&dir).with_context(|| format!("creating {}", dir.display()))?;
    let versioned_name = format!("accepted-{}-{}.md", rules.ver, rules.hash);
    let versioned_path = dir.join(&versioned_name);
    fs::write(&versioned_path, &rules_doc.text)
        .with_context(|| format!("writing {}", versioned_path.display()))?;
    fs::write(dir.join("current.md"), &rules_doc.text)
        .with_context(|| format!("writing {}", dir.join("current.md").display()))?;
    fs::write(
        dir.join("current.json"),
        serde_json::to_vec_pretty(&json!({
            "ver": rules.ver,
            "hash": rules.hash,
            "path": portable_rules_metadata_path(&rules_doc.path),
            "bytes": rules_doc.bytes,
            "accepted_text": versioned_name,
        }))?,
    )
    .with_context(|| format!("writing {}", dir.join("current.json").display()))?;
    Ok(())
}

fn print_rules_review(
    home: &Path,
    rules_doc: &RulesDoc,
    rules: &RulesRef,
    previous_rules: Option<&str>,
    prior_consent: Option<&Value>,
) -> Result<()> {
    println!("Mayhem rules review");
    println!("Home: {}", home.display());
    println!("Rules file: {}", rules_doc.path.display());
    println!("Rules version: {}", rules.ver);
    println!("BLAKE3(RULES.md): {}", rules_doc.hash);
    if let Some(consent) = prior_consent {
        let ver = consent.get("ver").and_then(Value::as_u64).unwrap_or(0);
        let hash = consent.get("hash").and_then(Value::as_str).unwrap_or("");
        println!("Existing consent: v{ver} {hash}");
    } else {
        println!("Existing consent: none");
    }

    match previous_rules {
        Some(previous) if previous == rules_doc.text => {
            println!();
            println!("Local accepted rules text is unchanged.");
        }
        Some(previous) => {
            println!();
            println!("Diff from locally accepted rules:");
            println!("{}", render_line_diff(previous, &rules_doc.text));
        }
        None => {
            println!();
            println!("No locally accepted rules text was found. Current rules text follows.");
            println!();
            println!("{}", rules_doc.text);
        }
    }
    Ok(())
}

fn render_line_diff(old: &str, new: &str) -> String {
    let old_lines = old.lines().collect::<Vec<_>>();
    let new_lines = new.lines().collect::<Vec<_>>();
    let max_len = old_lines.len().max(new_lines.len());
    let mut out = String::new();
    for i in 0..max_len {
        match (old_lines.get(i), new_lines.get(i)) {
            (Some(old), Some(new)) if old == new => {
                let _ = writeln!(out, "  {old}");
            }
            (Some(old), Some(new)) => {
                let _ = writeln!(out, "- {old}");
                let _ = writeln!(out, "+ {new}");
            }
            (Some(old), None) => {
                let _ = writeln!(out, "- {old}");
            }
            (None, Some(new)) => {
                let _ = writeln!(out, "+ {new}");
            }
            (None, None) => {}
        }
    }
    out
}

fn confirm_rules_acceptance(yes: bool) -> Result<()> {
    if yes {
        return Ok(());
    }
    if !io::stdin().is_terminal() {
        bail!("Pass --yes to accept and sign the current RULES.md in non-interactive mode.");
    }

    eprint!("Type 'agree' to sign consent for these rules: ");
    io::stderr().flush()?;
    let mut answer = String::new();
    io::stdin().read_line(&mut answer)?;
    if answer.trim() != "agree" {
        bail!("Rules consent was not signed.");
    }
    Ok(())
}

fn select_role(role: Option<Role>) -> Result<Role> {
    if let Some(role) = role {
        return Ok(role);
    }

    if !io::stdin().is_terminal() {
        bail!("Pass --role provider, --role user, or --role both for non-interactive setup.");
    }

    loop {
        print!("Choose role [provider/user/both]: ");
        io::stdout().flush()?;
        let mut answer = String::new();
        io::stdin().read_line(&mut answer)?;
        match answer.trim().to_lowercase().as_str() {
            "provider" | "prov" | "p" => return Ok(Role::Provider),
            "user" | "u" => return Ok(Role::User),
            "both" | "b" => return Ok(Role::Both),
            _ => eprintln!("Please enter provider, user, or both."),
        }
    }
}

async fn materialize_wallet(
    args: &SetupArgs,
    keypair_path: &Path,
    password: &str,
) -> Result<WalletInfo> {
    let exists = keypair_path.exists();
    let mnemonic = args
        .mnemonic
        .clone()
        .or_else(|| env::var("MAYHEM_WALLET_MNEMONIC").ok());
    match args.wallet {
        WalletMode::Auto => {
            if exists {
                inspect_wallet(keypair_path, password).await
            } else {
                create_wallet(
                    keypair_path,
                    password,
                    mnemonic.as_deref(),
                    false,
                    None,
                    None,
                )
                .await
            }
        }
        WalletMode::Create => {
            if exists && !args.force {
                bail!(
                    "{} already exists; use --wallet reuse or pass --force.",
                    keypair_path.display()
                );
            }
            create_wallet(
                keypair_path,
                password,
                mnemonic.as_deref(),
                args.force,
                None,
                None,
            )
            .await
        }
        WalletMode::Import => {
            if exists && !args.force {
                bail!(
                    "{} already exists; use --wallet reuse or pass --force.",
                    keypair_path.display()
                );
            }
            let mnemonic = mnemonic
                .as_deref()
                .context("--wallet import requires --mnemonic-file or MAYHEM_WALLET_MNEMONIC")?;
            create_wallet(keypair_path, password, Some(mnemonic), true, None, None).await
        }
        WalletMode::Reuse => {
            if !exists {
                bail!(
                    "{} does not exist; use --wallet create/import.",
                    keypair_path.display()
                );
            }
            inspect_wallet(keypair_path, password).await
        }
    }
}

async fn create_wallet(
    keypair_path: &Path,
    password: &str,
    mnemonic: Option<&str>,
    force: bool,
    ethereum_private_key: Option<&str>,
    ethereum_mnemonic: Option<&str>,
) -> Result<WalletInfo> {
    let mut args = vec!["--keypair".to_owned(), keypair_path.display().to_string()];
    if force {
        args.push("--force".to_owned());
    }
    run_wallet_helper(
        "create",
        args,
        WalletHelperSecrets {
            password: (!password.is_empty()).then(|| password.to_owned()),
            mnemonic: mnemonic.map(str::to_owned),
            ethereum_private_key: ethereum_private_key.map(str::to_owned),
            ethereum_mnemonic: ethereum_mnemonic.map(str::to_owned),
            ..WalletHelperSecrets::default()
        },
    )
    .await
}

