// One Pear wallet-helper spawn per signature froze busy providers: at a 2s
// heartbeat interval each ~1.5-3.5s spawn put the heartbeat pipeline permanently
// behind, so heartbeats arrived >60s stale and routing dropped the provider
// (2026-07-13 live incident). The helper is spawned once per keypair to extract
// the ed25519 seed (validated against its derived public key), then every
// signature is computed natively; trac-wallet signatures are plain ed25519 over
// the raw message bytes, so the output is byte-identical.
static WALLET_SIGNING_KEYS: std::sync::OnceLock<
    tokio::sync::Mutex<HashMap<(PathBuf, String), SigningKey>>,
> = std::sync::OnceLock::new();

async fn cached_wallet_signing_key(keypair_path: &Path, password: &str) -> Result<SigningKey> {
    let cache = WALLET_SIGNING_KEYS.get_or_init(|| tokio::sync::Mutex::new(HashMap::new()));
    let cache_key = (keypair_path.to_path_buf(), password.to_owned());
    let mut cache = cache.lock().await;
    if let Some(key) = cache.get(&cache_key) {
        return Ok(key.clone());
    }
    let args = vec!["--keypair".to_owned(), keypair_path.display().to_string()];
    let output: WalletSeedOutput = run_wallet_helper(
        "seed",
        args,
        WalletHelperSecrets {
            password: (!password.is_empty()).then(|| password.to_owned()),
            ..WalletHelperSecrets::default()
        },
    )
    .await?;
    let seed = hex_decode_array::<32>(&output.signing_seed_hex, "wallet signing seed")?;
    let key = SigningKey::from_bytes(&seed);
    let derived_public_key = hex_encode(&key.verifying_key().to_bytes());
    if !derived_public_key.eq_ignore_ascii_case(output.public_key.trim()) {
        bail!(
            "wallet signing seed derives public key {}, expected {}",
            derived_public_key,
            output.public_key
        );
    }
    cache.insert(cache_key, key.clone());
    Ok(key)
}

async fn sign_message(keypair_path: &Path, password: &str, message: &str) -> Result<String> {
    let key = cached_wallet_signing_key(keypair_path, password).await?;
    Ok(hex_encode(&key.sign(message.as_bytes()).to_bytes()))
}

async fn sign_hex(keypair_path: &Path, password: &str, message_hex: &str) -> Result<String> {
    let key = cached_wallet_signing_key(keypair_path, password).await?;
    let message = hex_decode_vec(message_hex, "sign message hex")?;
    Ok(hex_encode(&key.sign(&message).to_bytes()))
}

async fn wallet_signing_seed(
    keypair_path: &Path,
    password: &str,
    expected_public_key: &str,
) -> Result<[u8; 32]> {
    let args = vec!["--keypair".to_owned(), keypair_path.display().to_string()];
    let output: WalletSeedOutput = run_wallet_helper(
        "seed",
        args,
        WalletHelperSecrets {
            password: (!password.is_empty()).then(|| password.to_owned()),
            ..WalletHelperSecrets::default()
        },
    )
    .await?;
    if !output.public_key.eq_ignore_ascii_case(expected_public_key) {
        bail!(
            "wallet helper returned public key {}, expected {}",
            output.public_key,
            expected_public_key
        );
    }
    let seed = hex_decode_array::<32>(&output.signing_seed_hex, "wallet signing seed")?;
    let derived_public_key = hex_encode(&SigningKey::from_bytes(&seed).verifying_key().to_bytes());
    if !derived_public_key.eq_ignore_ascii_case(expected_public_key) {
        bail!(
            "wallet signing seed derives public key {}, expected {}",
            derived_public_key,
            expected_public_key
        );
    }
    Ok(seed)
}

async fn run_wallet_helper<T>(
    command: &str,
    helper_args: Vec<String>,
    mut secrets: WalletHelperSecrets,
) -> Result<T>
where
    T: for<'de> Deserialize<'de>,
{
    validate_wallet_helper_public_args(&helper_args)?;
    secrets.apply_environment_fallbacks();
    let intercom_app = repo_path("intercom")?;
    let pear_runtime = resolve_pear_runtime_path()?;
    let process_args = wallet_helper_runtime_args(command, &intercom_app, &helper_args);
    let mut process = Command::new(&pear_runtime);
    process
        .args(&process_args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = process.spawn().with_context(|| {
        format!(
            "running wallet helper via pear-runtime app {} with {}",
            intercom_app.display(),
            pear_runtime.display()
        )
    })?;
    let encoded_secrets =
        serde_json::to_vec(&secrets).context("serializing wallet helper secrets")?;
    let mut stdin = child
        .stdin
        .take()
        .context("wallet helper stdin pipe was not created")?;
    stdin
        .write_all(&encoded_secrets)
        .await
        .context("writing wallet helper secrets to stdin")?;
    stdin
        .shutdown()
        .await
        .context("closing wallet helper secret stdin")?;
    drop(stdin);
    let output = child
        .wait_with_output()
        .await
        .context("waiting for wallet helper")?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        let stdout = String::from_utf8_lossy(&output.stdout);
        bail!(
            "Pear wallet helper failed (status {}): stderr={} stdout={}",
            output.status,
            stderr.trim(),
            stdout.trim()
        );
    }

    parse_msb_transfer_helper_json(&output.stdout, &output.stderr)
        .context("parsing Pear wallet helper JSON output")
}

fn wallet_helper_runtime_args(
    command: &str,
    intercom_app: &Path,
    helper_args: &[String],
) -> Vec<OsString> {
    let mut args = vec![
        OsString::from("run"),
        intercom_app.as_os_str().to_os_string(),
        OsString::from(format!("--wallet-helper={command}")),
    ];
    args.extend(helper_args.iter().map(OsString::from));
    args
}

fn validate_wallet_helper_public_args(args: &[String]) -> Result<()> {
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if [
            "--password",
            "--password=",
            "--new-password",
            "--new-password=",
            "--mnemonic",
            "--mnemonic=",
            "--ethereum-private-key",
            "--ethereum-private-key=",
            "--ethereum-mnemonic",
            "--ethereum-mnemonic=",
        ]
        .iter()
        .any(|secret_arg| arg == secret_arg || arg.starts_with(secret_arg))
        {
            bail!("wallet helper secrets must use the typed stdin channel");
        }
        match arg.as_str() {
            "--keypair" | "--network-prefix" | "--message" | "--message-hex" => {
                let value = args
                    .get(index + 1)
                    .with_context(|| format!("{arg} requires a value"))?;
                ensure_external_helper_value(arg, value)?;
                index += 2;
            }
            "--force" => {
                index += 1;
            }
            _ => bail!("unsupported wallet helper argument {arg}"),
        }
    }
    Ok(())
}

fn write_config(
    home: &Path,
    store_path: &Path,
    wallet: &WalletInfo,
    role: Role,
    store_name: &str,
    rpc_url: &str,
) -> Result<PathBuf> {
    let config_path = home.join("config.toml");
    let address = wallet.address.as_deref().unwrap_or("");
    let derivation_path = wallet.derivation_path.as_deref().unwrap_or("");
    let contents = format!(
        concat!(
            "[identity]\n",
            "public_key = {}\n",
            "address = {}\n",
            "derivation_path = {}\n",
            "keypair_path = {}\n",
            "store_name = {}\n",
            "store_path = {}\n\n",
            "[role]\n",
            "mode = {}\n\n",
            "[network]\n",
            "rpc_url = {}\n",
            "gateway_url = {}\n"
        ),
        toml_string(&wallet.public_key),
        toml_string(address),
        toml_string(derivation_path),
        toml_string(&wallet.keypair_path),
        toml_string(store_name),
        toml_string(&store_path.display().to_string()),
        toml_string(role.as_str()),
        toml_string(rpc_url),
        toml_string(DEFAULT_GATEWAY_URL),
    );
    write_private_file(&config_path, contents.as_bytes())
        .with_context(|| format!("writing {}", config_path.display()))?;
    Ok(config_path)
}

fn toml_string(value: &str) -> String {
    let escaped = value.replace('\\', "\\\\").replace('"', "\\\"");
    format!("\"{escaped}\"")
}

async fn resolve_rules(
    rules_ver: Option<u64>,
    rules_hash: Option<&str>,
    rpc: &PeerRpcClient,
    rules_doc: Option<&RulesDoc>,
) -> Result<RulesRef> {
    let rules = match (rules_ver, rules_hash) {
        (Some(ver), Some(hash)) => {
            validate_rules_hash(hash)?;
            RulesRef {
                ver,
                hash: hash.to_owned(),
            }
        }
        (None, None) => {
            let state = rpc
                .state(Some("rules/current"), Some(false))
                .await
                .context("reading rules/current from peer RPC")?;
            let value = state
                .get("value")
                .filter(|value| !value.is_null())
                .context("rules/current is not set; ask the admin peer to set rules first")?;
            let ver = value
                .get("ver")
                .and_then(Value::as_u64)
                .context("rules/current.ver is missing or invalid")?;
            let hash = value
                .get("hash")
                .and_then(Value::as_str)
                .context("rules/current.hash is missing or invalid")?
                .to_owned();
            validate_rules_hash(&hash)?;
            RulesRef { ver, hash }
        }
        _ => bail!("--rules-ver and --rules-hash must be provided together."),
    };

    if let Some(rules_doc) = rules_doc {
        if rules.hash != rules_doc.hash {
            bail!(
                "contract rules hash {} does not match BLAKE3({}) {}",
                rules.hash,
                rules_doc.path.display(),
                rules_doc.hash
            );
        }
    }

    Ok(rules)
}

fn validate_rules_hash(hash: &str) -> Result<()> {
    if hash.len() != 64 || !hash.as_bytes().iter().all(u8::is_ascii_hexdigit) {
        bail!("rules hash must be a 32-byte hex BLAKE3 digest (64 characters).");
    }
    Ok(())
}

async fn read_consent_state(rpc: &PeerRpcClient, public_key: &str) -> Result<Option<Value>> {
    let key = format!("consent/{public_key}");
    let state = rpc
        .state(Some(&key), Some(false))
        .await
        .with_context(|| format!("reading {key} from peer RPC"))?;
    Ok(state.get("value").cloned().filter(|value| !value.is_null()))
}

fn consent_matches(consent: Option<&Value>, rules: &RulesRef) -> bool {
    consent.is_some_and(|state| {
        state.get("ver").and_then(Value::as_u64) == Some(rules.ver)
            && state.get("hash").and_then(Value::as_str) == Some(rules.hash.as_str())
    })
}

async fn ensure_current_rules_consent(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    sim: bool,
) -> Result<ConsentReport> {
    let rules = resolve_rules(None, None, rpc, None).await?;
    let prior = read_consent_state(rpc, &wallet.public_key).await?;
    if consent_matches(prior.as_ref(), &rules) {
        return Ok(ConsentReport {
            skipped: true,
            simulated: sim,
            rules: Some(rules),
            tx: None,
            command_hash: None,
            feature: None,
            result: None,
            state: prior,
        });
    }
    submit_consent(rpc, keypair_path, password, wallet, rules, sim).await
}

async fn submit_consent(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    rules: RulesRef,
    sim: bool,
) -> Result<ConsentReport> {
    let consent_sig = sign_message(keypair_path, password, &consent_message(&rules)).await?;
    let key = format!("consent/{}/{}/{}", wallet.public_key, rules.ver, rules.hash);
    let value = json!({
        "op": "consent",
        "sender": wallet.public_key,
        "ver": rules.ver,
        "hash": rules.hash,
        "sig": consent_sig,
    });
    let feature = json!({
        "feature": "mayhem",
        "key": key,
        "value": value,
    });
    let result = if sim {
        None
    } else {
        Some(
            rpc.submit_feature(&feature)
                .await
                .context("submitting free consent feature")?,
        )
    };

    let state = if sim {
        None
    } else {
        Some(wait_for_consent_state(rpc, &wallet.public_key, &rules).await?)
    };

    Ok(ConsentReport {
        skipped: false,
        simulated: sim,
        rules: Some(rules),
        tx: None,
        command_hash: None,
        feature: Some(feature),
        result,
        state,
    })
}

async fn wait_for_consent_state(
    rpc: &PeerRpcClient,
    public_key: &str,
    rules: &RulesRef,
) -> Result<Value> {
    let key = format!("consent/{public_key}");
    let mut last = Value::Null;
    for _ in 0..120 {
        let state = rpc
            .state(Some(&key), Some(false))
            .await
            .with_context(|| format!("reading {key} from peer RPC"))?;
        last = state.get("value").cloned().unwrap_or(Value::Null);
        if last.get("ver").and_then(Value::as_u64) == Some(rules.ver)
            && last.get("hash").and_then(Value::as_str) == Some(rules.hash.as_str())
        {
            return Ok(last);
        }
        sleep(Duration::from_millis(500)).await;
    }

    bail!("timed out waiting for persisted consent state; last value: {last}");
}

fn print_human_report(report: &Value) -> Result<()> {
    println!("Mayhem setup complete.");
    println!("Home: {}", report["home"].as_str().unwrap_or(""));
    println!("Role: {}", report["role"].as_str().unwrap_or(""));
    println!("Config: {}", report["config_path"].as_str().unwrap_or(""));
    println!(
        "Wallet: {}",
        if report["wallet"]["created"].as_bool().unwrap_or(false) {
            "created"
        } else {
            "reused"
        }
    );
    println!(
        "Public key: {}",
        report["wallet"]["public_key"].as_str().unwrap_or("")
    );
    if let Some(address) = report["wallet"]["address"].as_str() {
        println!("Trac address: {address}");
    }
    if let Some(address) = report["wallet"]["ethereum_address"].as_str() {
        println!("Ethereum address: {address}");
    }
    if let Some(mnemonic) = report["wallet"]["mnemonic"].as_str() {
        println!("Mnemonic (shown once): {mnemonic}");
    }
    if let Some(notice) = setup_admin_payout_notice(report["role"].as_str().unwrap_or_default()) {
        println!("{notice}");
    }

    let consent = &report["consent"];
    if consent["skipped"].as_bool().unwrap_or(false) {
        println!("Consent: skipped");
    } else if consent["simulated"].as_bool().unwrap_or(false) {
        println!(
            "Consent: simulated for rules v{}",
            consent["rules"]["ver"].as_u64().unwrap_or(0)
        );
    } else {
        println!(
            "Consent: submitted and observed for rules v{}",
            consent["rules"]["ver"].as_u64().unwrap_or(0)
        );
    }
    Ok(())
}

fn setup_admin_payout_notice(role: &str) -> Option<&'static str> {
    matches!(role, "provider" | "both").then_some(
        "Provider payouts: use 'mayhem provider payout set' for TAP/TNK; Stripe remains Connect-verification gated.",
    )
}

