    #[test]
    fn deposit_cli_parses_tap_status_and_withdraw() {
        let deposit = Cli::try_parse_from([
            "mayhem",
            "deposit",
            "tap",
            "--keypair",
            "/tmp/mayhem-wallet/db/keypair.json",
            "--amount",
            "1.25",
            "--eth-rpc",
            "http://127.0.0.1:61000",
            "--peer-rpc-url",
            "http://127.0.0.1:49223/v1",
            "--confirm",
            "--json",
        ])
        .unwrap();
        let Commands::Deposit { command } = deposit.command else {
            panic!("expected deposit command");
        };
        let DepositCommands::Tap(args) = command else {
            panic!("expected deposit tap command");
        };
        assert_eq!(args.amount_tap.as_deref(), Some("1.25"));
        assert_eq!(
            args.wallet.keypair.as_deref(),
            Some(Path::new("/tmp/mayhem-wallet/db/keypair.json"))
        );
        assert_eq!(args.eth_rpc.as_deref(), Some("http://127.0.0.1:61000"));
        assert_eq!(
            args.peer_rpc_url.as_deref(),
            Some("http://127.0.0.1:49223/v1")
        );
        assert!(!args.bind_only);
        assert!(args.confirm);
        assert!(args.json);

        let bind = Cli::try_parse_from([
            "mayhem",
            "deposit",
            "tap",
            "--bind-only",
            "--confirm",
            "--json",
        ])
        .unwrap();
        let Commands::Deposit { command } = bind.command else {
            panic!("expected deposit command");
        };
        let DepositCommands::Tap(args) = command else {
            panic!("expected deposit tap command");
        };
        assert!(args.bind_only);
        assert!(args.amount_tap.is_none());
        assert!(args.amount_wei.is_none());
        assert!(args.confirm);

        let status = Cli::try_parse_from([
            "mayhem",
            "deposit",
            "status",
            "--who",
            "user-a",
            "--deposit-binding",
            "aa",
            "--rail",
            "tnk",
            "--target-au",
            "1000",
            "--json",
        ])
        .unwrap();
        let Commands::Deposit { command } = status.command else {
            panic!("expected deposit command");
        };
        let DepositCommands::Status(args) = command else {
            panic!("expected deposit status command");
        };
        assert_eq!(args.who.as_deref(), Some("user-a"));
        assert_eq!(args.memo_hash.as_deref(), Some("aa"));
        assert_eq!(args.rail, Some(GatewayLedgerRail::Tnk));
        assert_eq!(args.target_au, Some(1000));

        let withdraw = Cli::try_parse_from([
            "mayhem",
            "withdraw",
            "--account",
            "0x1111111111111111111111111111111111111111",
            "--cumulative-wei",
            "100",
            "--proof",
            "[]",
            "--peer-rpc-url",
            "http://127.0.0.1:49223/v1",
            "--json",
        ])
        .unwrap();
        let Commands::Withdraw(args) = withdraw.command else {
            panic!("expected withdraw command");
        };
        assert_eq!(
            args.account.as_deref(),
            Some("0x1111111111111111111111111111111111111111")
        );
        assert_eq!(args.cumulative_wei.as_deref(), Some("100"));
        assert_eq!(args.proof.as_deref(), Some("[]"));
        assert_eq!(
            args.peer_rpc_url.as_deref(),
            Some("http://127.0.0.1:49223/v1")
        );
        assert!(!args.confirm);
        assert!(args.json);

        let local_withdraw = Cli::try_parse_from([
            "mayhem",
            "withdraw",
            "--keypair",
            "/tmp/mayhem-provider/db/keypair.json",
            "--settlement",
            "/tmp/epoch-1.settlement.json",
            "--confirm",
            "--json",
        ])
        .unwrap();
        let Commands::Withdraw(args) = local_withdraw.command else {
            panic!("expected local withdraw command");
        };
        assert!(args.account.is_none());
        assert_eq!(
            args.wallet.keypair.as_deref(),
            Some(Path::new("/tmp/mayhem-provider/db/keypair.json"))
        );
        assert!(args.confirm);
    }

