    #[tokio::test]
    async fn reset_requires_confirmation_and_removes_home() {
        let home = test_temp_dir("mayhem-reset");
        fs::create_dir_all(home.join("nested")).unwrap();
        fs::write(home.join("nested").join("state.json"), "{}").unwrap();
        assert!(reset(
            ResetArgs {
                home: Some(home.clone()),
                yes: false,
                force: false,
                timeout_seconds: 1,
                json: false,
            },
            "reset",
        )
        .await
        .is_err());
        assert!(home.exists());
        reset(
            ResetArgs {
                home: Some(home.clone()),
                yes: true,
                force: false,
                timeout_seconds: 1,
                json: false,
            },
            "reset",
        )
        .await
        .unwrap();
        assert!(!home.exists());
    }

    #[tokio::test]
    async fn down_removes_stale_pidfile() {
        let home = test_temp_dir("mayhem-down-stale");
        fs::write(mayhemd_pid_path(&home), "999999999").unwrap();
        let report = down_home(&home, 1, false).await.unwrap();
        assert_eq!(report["ok"].as_bool(), Some(true));
        assert_eq!(report["stale_pidfile_removed"].as_bool(), Some(true));
        assert!(!mayhemd_pid_path(&home).exists());
        fs::remove_dir_all(&home).unwrap();
    }

    #[tokio::test]
    async fn reset_refuses_live_mayhemd_without_force() {
        let home = test_temp_dir("mayhem-reset-live");
        fs::write(mayhemd_pid_path(&home), std::process::id().to_string()).unwrap();
        fs::write(home.join("state.json"), "{}").unwrap();
        let err = reset(
            ResetArgs {
                home: Some(home.clone()),
                yes: true,
                force: false,
                timeout_seconds: 1,
                json: false,
            },
            "reset",
        )
        .await
        .expect_err("reset must refuse a live mayhemd pid without --force");
        assert!(format!("{err:#}").contains("refusing to reset"), "{err:#}");
        assert!(home.exists());
        fs::remove_dir_all(&home).unwrap();
    }

    #[test]
    fn receipt_history_summarizes_filters_and_groups_sessions() {
        let latest = receipt_history_summary(&json!({
            "receipt": {
                "body": {
                    "session_id": "s1",
                    "seq": 2,
                    "model_id": "model-a",
                    "provider": "provider-a",
                    "user": "user-a",
                    "enclave_id": "enclave-a",
                    "au_owed_cum": "42",
                    "usage": {"output_token": 3},
                    "ts": 7200000,
                    "final": true
                }
            }
        }));
        assert_eq!(latest["session_id"].as_str(), Some("s1"));
        assert_eq!(latest["seq"].as_u64(), Some(2));
        assert_eq!(latest["provider"].as_str(), Some("provider-a"));
        assert_eq!(latest["model_id"].as_str(), Some("model-a"));
        assert_eq!(latest["au_owed_cum"].as_str(), Some("42"));
        assert_eq!(latest["final"].as_bool(), Some(true));

        let previous = receipt_history_summary(&json!({
            "body": {
                "session_id": "s1",
                "seq": 1,
                "model_id": "model-a",
                "provider": "provider-a",
                "au_owed_cum": "12"
            }
        }));
        let other = receipt_history_summary(&json!({
            "receipt": {
                "body": {
                    "session_id": "s2",
                    "seq": 1,
                    "model_id": "model-b",
                    "provider": "provider-b",
                    "au_owed_cum": "9"
                }
            }
        }));

        let matching_args = SessionHistoryArgs {
            gateway_url: None,
            home: None,
            session_id: Some("s1".to_owned()),
            provider: Some("provider-a".to_owned()),
            model: Some("model-a".to_owned()),
            limit: 20,
            json: false,
        };
        assert!(receipt_history_matches(&latest, &matching_args));
        assert!(!receipt_history_matches(&other, &matching_args));

        let groups = group_session_summaries(&[latest.clone(), other, previous]);
        assert_eq!(groups.len(), 2);
        assert_eq!(groups[0]["session_id"].as_str(), Some("s1"));
        assert_eq!(groups[0]["receipts"].as_u64(), Some(2));
        assert_eq!(groups[0]["latest"]["seq"].as_u64(), Some(2));
        assert_eq!(groups[1]["session_id"].as_str(), Some("s2"));
    }

    #[test]
    fn deposit_status_classifies_pending_and_confirmed() {
        assert_eq!(
            classify_deposit_status(0, None, None, None, false),
            "unknown"
        );
        assert_eq!(
            classify_deposit_status(0, None, Some(&json!({"status":"pending"})), None, false,),
            "pending"
        );
        assert_eq!(
            classify_deposit_status(999, Some(1000), None, None, false),
            "pending"
        );
        assert_eq!(
            classify_deposit_status(1000, Some(1000), None, None, false),
            "confirmed"
        );
        assert_eq!(
            classify_deposit_status(0, None, None, Some(&json!({"rail":"tap"})), true),
            "confirmed"
        );
        assert_eq!(
            classify_deposit_status(0, None, None, None, true),
            "pending"
        );
        assert_eq!(
            tap_deposit_identity_key(
                1,
                "0x2222222222222222222222222222222222222222",
                &format!("0x{}", "aa".repeat(32)),
                7,
                &format!("0x{}", "bb".repeat(32)),
            )
            .unwrap(),
            format!(
                "dep/tap/1/0x2222222222222222222222222222222222222222/0x{}/7/0x{}",
                "aa".repeat(32),
                "bb".repeat(32),
            )
        );
    }

