    fn gateway_models_are_built_from_canonical_contract_state() {
        let root = "aa".repeat(32);
        let mut contract = test_contract(&root);
        let enclave_id = contract.enclaves[0].enclave_id.clone();
        contract.price_derivations.push(json!({
            "type": "price_derivation",
            "schema_version": 1,
            "epoch": 7u64,
            "enclave_id": enclave_id.clone(),
            "ctx_bracket": ctx_bracket_for_tokens(8192),
            "ctx_bracket_table_ver": CTX_BRACKET_TABLE_VERSION,
            "model_id": "test/model@4bit",
            "denom": "au_usd",
            "price_ver": 1u64,
            "usage": {
                "usage_root": "66".repeat(32),
                "active_demand_au": "12345",
                "session_count": 2u64
            },
            "controller": {
                "source": "admin_seed_cold_start",
                "active_supply": 1u64,
                "utilization_bps": 1_000u64,
                "ema_utilization_bps": 1_000u64,
                "multiplier_bps": 10_000u64,
                "frozen": true,
                "frozen_reason": "cold_start"
            },
            "seed_price": {
                "ver": 1u64,
                "ctx_bracket": ctx_bracket_for_tokens(8192),
                "ctx_bracket_table_ver": CTX_BRACKET_TABLE_VERSION,
                "rate_map": [],
                "per_req_au": "0",
                "min_session_au": "0"
            },
            "result_price": {
                "ver": 1u64,
                "ctx_bracket": ctx_bracket_for_tokens(8192),
                "ctx_bracket_table_ver": CTX_BRACKET_TABLE_VERSION,
                "rate_map": [],
                "per_req_au": "0",
                "min_session_au": "0"
            },
            "derivation_hash": "77".repeat(32),
            "price_root": "88".repeat(32)
        }));
        let mut prior_derivation = contract.price_derivations[0].clone();
        prior_derivation["epoch"] = json!(5u64);
        prior_derivation["usage"]["active_demand_au"] = json!("8765");
        prior_derivation["derivation_hash"] = json!("76".repeat(32));
        contract.price_derivations.push(prior_derivation);
        let models = gateway_models_from_contract(&contract).unwrap();

        assert_eq!(models.len(), 1);
        assert_eq!(models[0].id, "test/model@4bit");
        assert_eq!(models[0].owned_by, "mayhem");
        assert_eq!(models[0].mayhem.source, "contract");
        assert_eq!(models[0].mayhem.providers_online, 1);
        assert_eq!(models[0].mayhem.rooms, 1);
        assert_eq!(models[0].mayhem.price_ref_au.denom, "au_usd");
        assert_eq!(models[0].mayhem.price_ref_au.ver, 1);
        assert_eq!(
            models[0].mayhem.price_ref_au.rate_map,
            normalize_rate_map(text_generation_rate_map(1, 2))
        );
        let derivation = models[0]
            .mayhem
            .price_ref_au
            .derivation
            .as_ref()
            .expect("contract price derivation is surfaced to gateway");
        assert_eq!(derivation["epoch"].as_u64(), Some(7));
        assert_eq!(
            derivation["usage"]["active_demand_au"].as_str(),
            Some("12345")
        );
        let expected_price_root = "88".repeat(32);
        assert_eq!(
            derivation["price_root"].as_str(),
            Some(expected_price_root.as_str())
        );
        let history_epochs = models[0]
            .mayhem
            .price_ref_au
            .history
            .iter()
            .map(|entry| entry["epoch"].as_u64().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(history_epochs, vec![5, 7]);
        assert_eq!(models[0].mayhem.attestation_tiers["T1"], 1);
        assert_eq!(models[0].mayhem.quant_buckets["int4"], 1);
        assert!(models[0].mayhem.kyb_identities.is_empty());
        assert!(models[0].mayhem.caps.tools);
        assert_eq!(models[0].mayhem.caps.ctx, 8192);
        assert_eq!(models[0].mayhem.markets.len(), 1);
        assert_eq!(models[0].mayhem.markets[0].att_tier, 1);
        assert_eq!(models[0].mayhem.markets[0].route_count, 1);
        assert_eq!(models[0].mayhem.markets[0].providers_online, 1);
        assert_eq!(models[0].mayhem.markets[0].availability, "routable");
        assert_eq!(models[0].mayhem.route_candidates.len(), 1);
        assert_eq!(models[0].mayhem.route_candidates[0].att_tier, 1);
        assert_eq!(models[0].mayhem.route_candidates[0].kyb, None);
        assert_eq!(models[0].mayhem.route_candidates[0].reputation_bps, 10_000);
        assert_eq!(models[0].mayhem.route_candidates[0].probation, None);
        assert_eq!(
            models[0].mayhem.route_candidates[0].provider,
            "55".repeat(32)
        );
        assert_eq!(models[0].mayhem.route_candidates[0].enclave_id, enclave_id);
        assert_eq!(
            models[0].mayhem.route_candidates[0].room_id,
            "aa".repeat(16)
        );
        assert_eq!(models[0].mayhem.route_candidates[0].price_ver, 1);
        assert_eq!(models[0].mayhem.route_candidates[0].quant, "int4");
        assert_eq!(models[0].mayhem.route_candidates[0].served_ctx, Some(4096));
        assert_eq!(
            models[0].mayhem.route_candidates[0].hardware_fingerprint,
            Some("77".repeat(32))
        );
        assert_eq!(
            models[0].mayhem.route_candidates[0].device_key,
            Some("88".repeat(32))
        );
        let route_price = models[0].mayhem.route_candidates[0]
            .price_ref_au
            .as_ref()
            .expect("route carries its own enclave market price");
        assert_eq!(route_price.denom, "au_usd");
        assert_eq!(route_price.ver, 1);
        assert_eq!(
            route_price.rate_map,
            normalize_rate_map(text_generation_rate_map(1, 2))
        );
        assert_eq!(
            route_price.derivation.as_ref().unwrap()["epoch"].as_u64(),
            Some(7)
        );
        let route_history_epochs = route_price
            .history
            .iter()
            .map(|entry| entry["epoch"].as_u64().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(route_history_epochs, vec![5, 7]);
        assert_eq!(
            models[0].mayhem.route_candidates[0].admin_pubkey,
            "44".repeat(32)
        );
        assert_eq!(models[0].mayhem.route_candidates[0].artifact_root, root);
        assert_eq!(
            models[0].mayhem.route_candidates[0].manifest_hash,
            "22".repeat(32)
        );
        assert_eq!(
            models[0].mayhem.route_candidates[0].binary_hash,
            "33".repeat(32)
        );

        contract.prices.clear();
        assert!(gateway_models_from_contract(&contract).unwrap().is_empty());

        let mut contract = test_contract(&root);
        contract.roomserve.clear();
        let models = gateway_models_from_contract(&contract).unwrap();
        assert_eq!(models.len(), 1);
        assert_eq!(models[0].mayhem.providers_online, 0);
        assert_eq!(models[0].mayhem.rooms, 1);
        assert!(models[0].mayhem.route_candidates.is_empty());
        assert_eq!(models[0].mayhem.markets.len(), 1);
        assert_eq!(models[0].mayhem.markets[0].route_count, 0);
        assert_eq!(models[0].mayhem.markets[0].providers_online, 0);
        assert_eq!(
            models[0].mayhem.markets[0].availability,
            "no_eligible_provider_yet"
        );

        let mut contract = test_contract(&root);
        contract.providers[0].status = "banned".to_owned();
        let models = gateway_models_from_contract(&contract).unwrap();
        assert_eq!(models.len(), 1);
        assert!(models[0].mayhem.route_candidates.is_empty());
        assert_eq!(models[0].mayhem.markets[0].route_count, 0);
        assert_eq!(
            models[0].mayhem.markets[0].availability,
            "no_eligible_provider_yet"
        );

        let mut missing_role = test_contract(&root);
        missing_role.enclaves[0].created_by_role = None;
        missing_role.rooms[0].creator_role = None;
        missing_role.prices[0].current.as_mut().unwrap().set_by_role = None;
        assert!(gateway_models_from_contract(&missing_role)
            .unwrap()
            .is_empty());

        let mut provider_created = test_contract(&root);
        provider_created.enclaves[0].created_by_role = Some("provider".to_owned());
        assert!(gateway_models_from_contract(&provider_created)
            .unwrap()
            .is_empty());

        let mut provider_room = test_contract(&root);
        provider_room.rooms[0].creator_role = Some("provider".to_owned());
        assert!(gateway_models_from_contract(&provider_room)
            .unwrap()
            .is_empty());

        let mut provider_priced = test_contract(&root);
        provider_priced.prices[0]
            .current
            .as_mut()
            .unwrap()
            .set_by_role = Some("provider".to_owned());
        assert!(gateway_models_from_contract(&provider_priced)
            .unwrap()
            .is_empty());

        let mut noncanonical_room_id = test_contract(&root);
        noncanonical_room_id.rooms[0].room_id = "provider-local-only".to_owned();
        noncanonical_room_id.rooms[0].sidechannel = "mx/room/provider-local-only".to_owned();
        noncanonical_room_id.roomserve[0].room_id = "provider-local-only".to_owned();
        noncanonical_room_id.serves[0].rooms = vec!["provider-local-only".to_owned()];
        assert!(gateway_models_from_contract(&noncanonical_room_id)
            .unwrap()
            .is_empty());

        let mut wrong_sidechannel = test_contract(&root);
        wrong_sidechannel.rooms[0].sidechannel = "mx/room/provider-made".to_owned();
        assert!(gateway_models_from_contract(&wrong_sidechannel)
            .unwrap()
            .is_empty());

        let mut wrong_same_model_enclave = test_contract(&root);
        let mut other_enclave = wrong_same_model_enclave.enclaves[0].clone();
        other_enclave.artifact_root = "77".repeat(32);
        let other_enclave_id = canonicalize_test_enclave_id(&mut other_enclave);
        wrong_same_model_enclave.enclaves.push(other_enclave);
        let mut other_price = wrong_same_model_enclave.prices[0].clone();
        other_price.enclave_id = other_enclave_id.clone();
        wrong_same_model_enclave.prices.push(other_price);
        wrong_same_model_enclave.roomserve[0].enclave_id = other_enclave_id;
        let models = gateway_models_from_contract(&wrong_same_model_enclave).unwrap();
        assert_eq!(models.len(), 1);
        assert!(models[0].mayhem.route_candidates.is_empty());
        assert_eq!(models[0].mayhem.markets.len(), 1);
        assert_eq!(
            models[0].mayhem.markets[0].enclave_id,
            wrong_same_model_enclave.enclaves[0].enclave_id
        );
        assert_eq!(models[0].mayhem.markets[0].route_count, 0);
    }

    #[test]
    fn gateway_routes_require_active_verified_payout_rails_at_billing_epoch() {
        let root = "aa".repeat(32);
        let provider = "55".repeat(32);
        let old_revision = "11".repeat(32);
        let new_revision = "22".repeat(32);
        let pointer = json!({
            "current_revision": old_revision,
            "pending_revision": new_revision,
            "pending_activation_epoch": 9,
        });
        assert_eq!(
            payout_pointer_revision_at_epoch(&pointer, 8),
            pointer["current_revision"].as_str()
        );
        assert_eq!(
            payout_pointer_revision_at_epoch(&pointer, 9),
            pointer["pending_revision"].as_str()
        );

        let mut contract = test_contract(&root);
        contract.active_payout_revisions.clear();
        let models = gateway_models_from_contract(&contract).unwrap();
        assert_eq!(contract.providers[0].accepted_rails, vec!["fiat"]);
        assert!(models[0].mayhem.route_candidates.is_empty());
        assert_eq!(models[0].mayhem.providers_online, 0);
        assert_eq!(
            models[0].mayhem.markets[0].availability,
            "no_eligible_provider_yet"
        );

        contract.active_payout_revisions.insert(
            provider,
            BTreeMap::from([("fiat".to_owned(), old_revision)]),
        );
        let models = gateway_models_from_contract(&contract).unwrap();
        assert_eq!(models[0].mayhem.route_candidates.len(), 1);
        assert_eq!(
            models[0].mayhem.route_candidates[0].accepted_rails,
            vec!["fiat"]
        );
    }

    #[test]
    fn gateway_model_version_gates_use_signed_catalog_requirements() {
        let root = "aa".repeat(32);
        let contract = test_contract(&root);
        let mut catalog = test_catalog(&root);

        catalog.models[0].min_app_version = Some(installed_app_version().to_owned());
        let models = gateway_models_from_contract(&contract).unwrap();
        let (allowed, blocked) = filter_gateway_models_by_app_version(models, &catalog).unwrap();
        assert_eq!(allowed.len(), 1);
        assert!(blocked.is_empty());
        assert_eq!(
            allowed[0].mayhem.min_app_version.as_deref(),
            Some(installed_app_version())
        );

        catalog.models[0].min_app_version = Some("9999.0.0".to_owned());
        let models = gateway_models_from_contract(&contract).unwrap();
        let err = filter_gateway_models_by_app_version(models, &catalog)
            .expect_err("gateway should refuse when every routable model is too new");
        let message = err.to_string();
        assert!(message.contains("upgrade required"));
        assert!(message.contains("route"));
        assert!(message.contains("Mayhem >= 9999.0.0"));
        assert!(message.contains("mayhem update"));
    }

