    #[test]
    fn provider_session_checkpoint_policy_bounds_unacked_output_window() {
        assert!(!provider_session_checkpoint_due(0, 10, 0, 2));
        assert!(!provider_session_checkpoint_due(1, 10, 0, 2));
        assert!(provider_session_checkpoint_due(2, 10, 0, 2));
        assert!(!provider_session_checkpoint_due(3, 10, 2, 2));
        assert!(provider_session_checkpoint_due(4, 10, 2, 2));
        assert!(!provider_session_checkpoint_due(10, 10, 8, 2));
        let mut active = ActiveProviderSession {
            remote: "peer-a".to_owned(),
            user_pubkey: "66".repeat(32),
            session_id: "aa".repeat(32),
            billing_id: "bb".repeat(32),
            billing_attempt: 0,
            billing_prior_usage: ReceiptUsage::default(),
            billing_prior_au_owed_cum: 0,
            billing_epoch: 7,
            reservation_id: "12".repeat(32),
            reservation_expires_after_epoch: 31,
            reservation_receipt_grace_epochs: 6,
            payout_revision: "34".repeat(32),
            receipt_settlement: None,
            rail: "fiat".to_owned(),
            price_ver: 1,
            locked_rate_map: text_generation_rate_map(1, 2),
            locked_per_req_au: 0,
            locked_min_session_au: 0,
            served_ctx: 8192,
            required_modalities: vec!["text".to_owned()],
            required_specialities: BTreeMap::new(),
            ctx_bracket: Some(ctx_bracket_for_tokens(8192).to_owned()),
            ctx_bracket_table_ver: Some(CTX_BRACKET_TABLE_VERSION),
            checkpoint_every: CheckpointPolicy { tokens: 2, ms: 0 },
            max_spend_au: MoneyAu::MAX,
            accept_replay: None,
        };
        assert_eq!(
            provider_session_receipt_ack_timeout(&active),
            Duration::from_secs(120)
        );
        active.checkpoint_every.ms = 30_000;
        assert_eq!(
            provider_session_receipt_ack_timeout(&active),
            Duration::from_secs(120)
        );
        active.checkpoint_every.ms = 180_000;
        assert_eq!(
            provider_session_receipt_ack_timeout(&active),
            Duration::from_secs(185)
        );
    }

    #[test]
    fn provider_session_receipt_ack_verifies_user_signature() {
        let terms = test_provider_session_terms();
        let user_seed = [41_u8; 32];
        let user_key = SigningKey::from_bytes(&user_seed);
        let active = ActiveProviderSession {
            remote: "peer-a".to_owned(),
            user_pubkey: hex_encode(&user_key.verifying_key().to_bytes()),
            session_id: "aa".repeat(32),
            billing_id: "bb".repeat(32),
            billing_attempt: 0,
            billing_prior_usage: ReceiptUsage::default(),
            billing_prior_au_owed_cum: 0,
            billing_epoch: 7,
            reservation_id: "12".repeat(32),
            reservation_expires_after_epoch: 31,
            reservation_receipt_grace_epochs: 6,
            payout_revision: "34".repeat(32),
            receipt_settlement: None,
            rail: "fiat".to_owned(),
            price_ver: terms.price_ver,
            locked_rate_map: normalize_rate_map(terms.rate_map.clone()),
            locked_per_req_au: terms.per_req_au,
            locked_min_session_au: terms.min_session_au,
            served_ctx: u32::try_from(terms.ctx).unwrap(),
            required_modalities: vec!["text".to_owned()],
            required_specialities: BTreeMap::new(),
            ctx_bracket: terms.ctx_bracket.clone(),
            ctx_bracket_table_ver: terms.ctx_bracket_table_ver,
            checkpoint_every: CheckpointPolicy { tokens: 1, ms: 0 },
            max_spend_au: MoneyAu::MAX,
            accept_replay: None,
        };
        let body = json!({
            "messages": [{ "role": "user", "content": "hello mayhem" }],
            "stream": true
        });
        let output = ProviderSessionOutput {
            content: "receipt ok".to_owned(),
            reasoning_evidence: String::new(),
            tools: Vec::new(),
            embeddings: None,
            transcription: None,
            artifacts: Vec::new(),
            finish_reason: "stop".to_owned(),
            prompt_tokens: 2,
            completion_tokens: 3,
            token_ids: vec![1, 2, 3],
            usage: ReceiptUsage::text(2, 3),
            usage_attribution: BTreeMap::new(),
        };
        let receipt = provider_session_receipt(
            &terms,
            &active,
            &body,
            &output,
            &RuntimeKeypair::from_seed([9; 32]),
        )
        .unwrap();
        let payload = receipt_signing_bytes(&receipt.body).unwrap();
        let user_sig = hex_encode(&user_key.sign(&payload).to_bytes());
        let frame = json!({
            "t": "s.receipt_ack",
            "v": 1,
            "session_id": &active.session_id,
            "seq": receipt.body.seq,
            "user_sig": user_sig,
        });

        let ack = provider_session_receipt_ack_from_frame(&frame, &active, &receipt).unwrap();
        assert_eq!(ack.session_id, active.session_id);
        assert_eq!(ack.seq, receipt.body.seq);

        let mut wrong_seq = frame.clone();
        wrong_seq["seq"] = json!(receipt.body.seq + 1);
        assert!(provider_session_receipt_ack_from_frame(&wrong_seq, &active, &receipt).is_err());

        let mut wrong_sig = frame;
        wrong_sig["user_sig"] = json!("11".repeat(64));
        assert!(provider_session_receipt_ack_from_frame(&wrong_sig, &active, &receipt).is_err());
    }

    #[test]
    fn provider_session_user_signatures_reject_low_order_forgeries() {
        let (weak_key, weak_signature) = weak_identity_key_and_signature();
        let terms = test_provider_session_terms();
        let mut active = test_active_provider_session(&terms, vec!["text".to_owned()]);
        active.user_pubkey = weak_key.clone();
        let receipt = provider_session_receipt_for_usage(
            &terms,
            &active,
            &json!({"messages": [{"role": "user", "content": "strict ack"}]}),
            ReceiptUsage::text(1, 1),
            1,
            true,
            &RuntimeKeypair::from_seed([9; 32]),
        )
        .unwrap();
        let ack_frame = json!({
            "t": "s.receipt_ack",
            "v": 1,
            "session_id": active.session_id,
            "seq": receipt.body.seq,
            "user_sig": weak_signature,
        });
        provider_session_receipt_ack_from_frame(&ack_frame, &active, &receipt)
            .expect_err("low-order receipt ack forgery must fail strict verification");

        let mut open_frame = test_session_open_frame(&terms);
        open_frame["user"] = json!(weak_key);
        open_frame["voucher"]["user_sig"] = json!(weak_signature);
        open_frame["sig"] = json!(weak_signature);
        assert!(matches!(
            provider_session_open_decision(&open_frame, &terms),
            ProviderSessionDecision::Reject {
                code: "SIGNATURE",
                ..
            }
        ));
    }

