    #[test]
    fn provider_engine_request_normalizes_gemma4_media_order_for_prompt_and_backend() {
        let mut adapter = catalog::CatalogAdapter::default();
        adapter.chat_template_id = "gemma4-instruct".to_owned();
        let body = json!({
            "messages": [{
                "role": "user",
                "content": [
                    {"type": "input_audio", "input_audio": {"data": "AAAA", "format": "wav"}},
                    {"type": "text", "text": "describe everything"},
                    {"type": "image_url", "image_url": {"url": "data:image/png;base64,AA=="}},
                    {"type": "video", "video": {
                        "frames": ["data:image/png;base64,AA=="],
                        "num_frames": 1,
                        "fps": 1.0
                    }}
                ]
            }]
        });

        let request = provider_engine_request_from_body(&body, &adapter).unwrap();

        let content_types = request.messages[0]["content"]
            .as_array()
            .unwrap()
            .iter()
            .map(|part| part["type"].as_str().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(content_types, ["image_url", "video", "text", "input_audio"]);
        assert_eq!(
            request
                .media
                .iter()
                .map(|media| media.kind.as_str())
                .collect::<Vec<_>>(),
            ["image", "video", "audio"]
        );
        let text_at = request.prompt.find("describe everything").unwrap();
        let marker_positions = request
            .prompt
            .match_indices(MTMD_MEDIA_MARKER)
            .map(|(index, _)| index)
            .collect::<Vec<_>>();
        assert_eq!(marker_positions.len(), 3);
        assert!(marker_positions[..2].iter().all(|index| *index < text_at));
        assert!(marker_positions[2] > text_at);
    }

    #[test]
    fn provider_engine_request_maps_signed_body_speciality_to_native_parameter() {
        let descriptor = mayhem_proto::ModelSpecialityDescriptor {
            name: "reasoning_effort".to_owned(),
            mechanism: "enum".to_owned(),
            default_level: "low".to_owned(),
            levels: vec![
                mayhem_proto::ModelSpecialityLevel {
                    name: "low".to_owned(),
                    rank: 0,
                    native_value: json!("low"),
                    default_max_output_tokens: Some(8),
                    max_reasoning_tokens: Some(4),
                },
                mayhem_proto::ModelSpecialityLevel {
                    name: "high".to_owned(),
                    rank: 1,
                    native_value: json!("high"),
                    default_max_output_tokens: Some(32),
                    max_reasoning_tokens: Some(24),
                },
            ],
            calibration_modalities: Vec::new(),
            research_evidence: vec!["test family documentation".to_owned()],
        };
        let mut adapter = catalog::CatalogAdapter::default();
        let contract = adapter
            .endpoint_families
            .iter_mut()
            .find(|contract| contract.family == mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS)
            .expect("chat endpoint contract");
        contract
            .request_attributes
            .push("reasoning_effort".to_owned());
        let mut spec =
            mayhem_proto::EndpointAttributeSpec::new(mayhem_proto::EndpointValueType::String);
        spec.default = Some(json!("low"));
        spec.enum_values = vec![json!("low"), json!("high")];
        spec.calibration_values = spec.enum_values.clone();
        contract
            .request_attribute_specs
            .insert("reasoning_effort".to_owned(), spec);
        contract.speciality_mappings.insert(
            "reasoning_effort".to_owned(),
            mayhem_proto::EndpointSpecialityMapping {
                request_path: "reasoning_effort".to_owned(),
                target: mayhem_proto::EndpointSpecialityTarget::ChatTemplateKwarg,
                native_path: "reasoning_effort".to_owned(),
                selector: mayhem_proto::EndpointSpecialitySelector::Exact,
            },
        );
        adapter.specialities.push(descriptor);
        let body = json!({
            "messages": [{ "role": "user", "content": "reason carefully" }],
            "reasoning_effort": "high",
            "specialities": { "reasoning_effort": "high" }
        });

        let request = provider_engine_request_from_body(&body, &adapter).unwrap();

        assert_eq!(request.max_new_tokens, 32);
        assert_eq!(request.speciality_parameters.len(), 1);
        let parameter = &request.speciality_parameters[0];
        assert_eq!(parameter.name, "reasoning_effort");
        assert_eq!(parameter.level, "high");
        assert_eq!(
            parameter.target,
            GenerateSpecialityTarget::ChatTemplateKwarg
        );
        assert_eq!(parameter.native_path, "reasoning_effort");
        assert_eq!(parameter.value, json!("high"));
    }

    #[test]
    fn provider_speciality_selection_uses_shared_non_empty_selector() {
        let descriptor = mayhem_proto::ModelSpecialityDescriptor {
            name: "optional_capability".to_owned(),
            mechanism: "boolean".to_owned(),
            default_level: "off".to_owned(),
            levels: vec![
                mayhem_proto::ModelSpecialityLevel {
                    name: "off".to_owned(),
                    rank: 0,
                    native_value: json!(false),
                    default_max_output_tokens: None,
                    max_reasoning_tokens: None,
                },
                mayhem_proto::ModelSpecialityLevel {
                    name: "on".to_owned(),
                    rank: 1,
                    native_value: json!(true),
                    default_max_output_tokens: None,
                    max_reasoning_tokens: None,
                },
            ],
            calibration_modalities: vec!["video".to_owned()],
            research_evidence: vec!["pinned enhancer fixture".to_owned()],
        };
        let mut adapter = catalog::CatalogAdapter::default();
        adapter.endpoint_families.push(
            mayhem_proto::endpoint_family_contract_template(
                mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO,
            )
            .expect("HF video endpoint contract"),
        );
        let contract = adapter.endpoint_families.last_mut().unwrap();
        contract.speciality_mappings.insert(
            descriptor.name.clone(),
            mayhem_proto::EndpointSpecialityMapping {
                request_path: "parameters.negative_prompt".to_owned(),
                target: mayhem_proto::EndpointSpecialityTarget::BackendParameter,
                native_path: "optional_capability".to_owned(),
                selector: mayhem_proto::EndpointSpecialitySelector::NonEmpty,
            },
        );
        adapter.specialities = vec![descriptor];

        let selected_on = provider_request_speciality_selection(
            mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO,
            &json!({"parameters": {"negative_prompt": "watermark"}}),
            &adapter,
        )
        .unwrap();
        assert_eq!(
            selected_on,
            BTreeMap::from([("optional_capability".to_owned(), "on".to_owned())])
        );
        for body in [
            json!({}),
            json!({"parameters": {}}),
            json!({"parameters": {"negative_prompt": null}}),
            json!({"parameters": {"negative_prompt": ""}}),
            json!({"parameters": {"negative_prompt": []}}),
            json!({"parameters": {"negative_prompt": {}}}),
        ] {
            assert_eq!(
                provider_request_speciality_selection(
                    mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO,
                    &body,
                    &adapter,
                )
                .unwrap(),
                BTreeMap::from([("optional_capability".to_owned(), "off".to_owned())])
            );
        }
    }

