    #[test]
    fn provider_engine_request_resolves_template_and_reasoning_policy() {
        let preserving_adapter = catalog::CatalogAdapter {
            chat_template_id: "llama3-instruct".to_owned(),
            reasoning_passthrough: "preserve".to_owned(),
            ..catalog::CatalogAdapter::default()
        };
        let body = json!({
            "model": "test/model@4bit",
            "messages": [{
                "role": "user",
                "reasoning": "scratchpad stays only for preserve adapters",
                "content": "final user content"
            }]
        });
        let request = provider_engine_request_from_body(&body, &preserving_adapter).unwrap();

        assert!(request
            .prompt
            .contains("<|start_header_id|>user<|end_header_id|>"));
        assert!(request
            .prompt
            .contains("scratchpad stays only for preserve adapters"));
        assert!(request.prompt.contains("final user content"));

        let stripped_request =
            provider_engine_request_from_body(&body, &catalog::CatalogAdapter::default()).unwrap();
        assert!(!stripped_request
            .prompt
            .contains("scratchpad stays only for preserve adapters"));
        assert!(stripped_request.prompt.contains("user: final user content"));
    }

    #[test]
    fn provider_reasoning_filter_strips_prefilled_output_across_stream_chunks() {
        let mut filter =
            ProviderReasoningOutputFilter::new(ProviderReasoningOutputMode::StripPrefilled);
        let chunks = [
            "private chain ",
            "of thought</thi",
            "nk>",
            "\n",
            "\npublic ",
            "answer",
        ];
        let mut filtered = ProviderReasoningFilteredText::default();
        for chunk in chunks {
            filtered.extend(filter.push_split(chunk));
        }
        filtered.extend(filter.finish_split());

        assert_eq!(filtered.visible, "public answer");
        assert_eq!(filtered.hidden, "private chain of thought</think>\n\n");
    }

    #[test]
    fn provider_reasoning_filter_preserves_plain_and_explicit_preserve_output() {
        assert_eq!(
            provider_reasoning_visible_output(
                "ordinary answer",
                ProviderReasoningOutputMode::StripTagged,
            ),
            "ordinary answer"
        );
        assert_eq!(
            provider_reasoning_visible_output(
                "<think>private</think>\nvisible",
                ProviderReasoningOutputMode::StripTagged,
            ),
            "visible"
        );
        assert_eq!(
            provider_reasoning_visible_output(
                "<think>published reasoning</think>\nanswer",
                ProviderReasoningOutputMode::Preserve,
            ),
            "<think>published reasoning</think>\nanswer"
        );
    }

    #[test]
    fn provider_reasoning_filter_never_leaks_unclosed_reasoning() {
        assert_eq!(
            provider_reasoning_visible_output(
                "private reasoning without a closing marker",
                ProviderReasoningOutputMode::StripPrefilled,
            ),
            ""
        );
        assert_eq!(
            provider_reasoning_visible_output(
                "<think>private reasoning without a closing marker",
                ProviderReasoningOutputMode::StripTagged,
            ),
            ""
        );
    }

