    #[test]
    fn qwen_native_prompt_honors_reasoning_effort_and_tool_schema() {
        let messages = vec![json!({"role": "user", "content": "Call the clock"})];
        let tools = vec![json!({
            "type": "function",
            "function": {
                "name": "clock",
                "parameters": {"type": "object", "properties": {}}
            }
        })];
        let adapter = catalog::CatalogAdapter {
            chat_template_id: "qwen3.5-instruct".to_owned(),
            tool_call_strategy: "qwen_function_xml".to_owned(),
            ..catalog::CatalogAdapter::default()
        };
        let enabled = GenerateSpecialityParameter {
            name: "reasoning_effort".to_owned(),
            level: "low".to_owned(),
            target: GenerateSpecialityTarget::ChatTemplateKwarg,
            native_path: "enable_thinking".to_owned(),
            value: json!(true),
            max_reasoning_tokens: Some(512),
        };

        let prompt = provider_engine_qwen3_prompt(
            &messages,
            &tools,
            std::slice::from_ref(&enabled),
            &adapter,
        )
        .unwrap();
        assert!(prompt.contains("<tools>"));
        assert!(prompt.contains("\"name\":\"clock\""));
        assert!(prompt.ends_with("<|im_start|>assistant\n<think>\n"));

        let disabled = GenerateSpecialityParameter {
            level: "off".to_owned(),
            value: json!(false),
            max_reasoning_tokens: Some(0),
            ..enabled
        };
        let prompt = provider_engine_qwen3_prompt(
            &messages,
            &tools,
            std::slice::from_ref(&disabled),
            &adapter,
        )
        .unwrap();
        assert!(prompt.ends_with("<think>\n\n</think>\n\n"));

        let history = vec![
            json!({"role": "user", "content": "Choose a private marker"}),
            json!({
                "role": "assistant",
                "content": "<think>copper-signal-731</think>Noted."
            }),
            json!({"role": "user", "content": "Continue"}),
        ];
        let latest_only = GenerateSpecialityParameter {
            name: "thinking_history".to_owned(),
            level: "latest_only".to_owned(),
            target: GenerateSpecialityTarget::ChatTemplateKwarg,
            native_path: "preserve_thinking".to_owned(),
            value: json!(false),
            max_reasoning_tokens: None,
        };
        let prompt = provider_engine_qwen3_prompt(
            &history,
            &[],
            &[disabled.clone(), latest_only.clone()],
            &adapter,
        )
        .unwrap();
        assert!(!prompt.contains("copper-signal-731"));
        assert!(prompt.contains("Noted."));

        let preserve = GenerateSpecialityParameter {
            level: "preserve".to_owned(),
            value: json!(true),
            ..latest_only
        };
        let prompt =
            provider_engine_qwen3_prompt(&history, &[], &[disabled, preserve], &adapter).unwrap();
        assert!(prompt.contains("copper-signal-731"));
    }

    #[test]
    fn provider_engine_request_preserves_multimodal_content_as_media() {
        let body = json!({
            "messages": [{
                "role": "user",
                "content": [
                    { "type": "text", "text": "describe this" },
                    { "type": "image_url", "image_url": { "url": "data:image/png;base64,aW1hZ2U=" } },
                    { "type": "input_audio", "input_audio": { "data": "UklGRg==", "format": "wav" } },
                    { "type": "video", "video": { "data": "dmlkZW8=", "content_type": "video/mp4", "num_frames": 8, "fps": 2.0 } }
                ]
            }]
        });

        let request =
            provider_engine_request_from_body(&body, &catalog::CatalogAdapter::default()).unwrap();

        assert_eq!(
            request.messages,
            body["messages"].as_array().unwrap().clone()
        );
        assert_eq!(request.media.len(), 3);
        assert_eq!(request.media[0].kind, "image");
        assert_eq!(request.media[0].content_type.as_deref(), Some("image/png"));
        assert_eq!(
            request.media[0].url.as_deref(),
            Some("data:image/png;base64,aW1hZ2U=")
        );
        assert_eq!(request.media[1].kind, "audio");
        assert_eq!(request.media[1].content_type.as_deref(), Some("audio/wav"));
        assert_eq!(request.media[1].data.as_deref(), Some("UklGRg=="));
        assert_eq!(request.media[2].kind, "video");
        assert_eq!(request.media[2].content_type.as_deref(), Some("video/mp4"));
        assert_eq!(request.media[2].data.as_deref(), Some("dmlkZW8="));
        assert_eq!(request.media[2].num_frames, Some(8));
        assert_eq!(request.media[2].fps, Some(2.0));
        assert!(request.prompt.contains("describe this"));
        assert!(request.prompt.contains("[image:"));
        assert!(request.prompt.contains("[audio:wav:"));
    }

    #[test]
    fn endpoint_calibration_bounds_backend_output_without_narrowing_the_contract() {
        let mut adapter = catalog::CatalogAdapter::default();
        adapter.endpoint_families.push(
            catalog::endpoint_contract_template(mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS)
                .unwrap(),
        );
        let body = json!({
            "model": "test/model",
            "messages": [{"role": "user", "content": "boundary probe"}],
            "max_tokens": 262_144
        });
        let sealed = provider_seal_local_contract_request(&body, &adapter, "test/model").unwrap();

        let mut production = FakeEngineBackend::new("ok");
        provider_engine_session_response_with_sampling(
            &mut production,
            Some("test/model"),
            &adapter,
            &catalog::CatalogSamplingProfile::default(),
            &sealed,
            None,
            &CancellationToken::new(),
        )
        .unwrap();
        assert_eq!(production.last_request.unwrap().max_new_tokens, 262_144);

        let mut calibration = FakeEngineBackend::new("ok");
        provider_engine_session_response_with_sampling_bounded(
            &mut calibration,
            Some("test/model"),
            &adapter,
            &catalog::CatalogSamplingProfile::default(),
            &sealed,
            None,
            Some(ENDPOINT_CALIBRATION_MAX_OUTPUT_TOKENS),
            &CancellationToken::new(),
        )
        .unwrap();
        assert_eq!(
            calibration.last_request.unwrap().max_new_tokens,
            ENDPOINT_CALIBRATION_MAX_OUTPUT_TOKENS
        );
    }

    #[test]
    fn live_catalog_modality_canaries_preflight_before_engine_load() {
        let catalog_path = repo_path("catalog/models.json").unwrap();
        let catalog = catalog::load_document(&catalog_path).unwrap();
        let model = catalog
            .models
            .iter()
            .find(|model| model.model_id == "hauhaucs/qwen3.6-35b-a3b-uncensored")
            .expect("live launch model");
        let canaries_dir = repo_path("catalog/canaries").unwrap();
        let prompts =
            load_canary_prompts_checked(Some(&canaries_dir), &model.canary.set_id, None, false)
                .unwrap();
        let served = model
            .adapter
            .modality_set
            .iter()
            .cloned()
            .collect::<BTreeSet<_>>();
        let mut covered = BTreeSet::new();

        for prompt in &prompts {
            let modalities = provider_canary_prompt_modalities(model, prompt);
            if modalities.is_empty() || !modalities.iter().all(|value| served.contains(value)) {
                continue;
            }
            let body = provider_canary_self_test_body(model, prompt)
                .unwrap_or_else(|error| panic!("{} body: {error:#}", prompt.id));
            let sealed =
                provider_seal_local_contract_request(&body, &model.adapter, &model.model_id)
                    .unwrap_or_else(|error| panic!("{} seal: {error:#}", prompt.id));
            let mut backend = FakeEngineBackend::new("modality preflight ready");
            provider_engine_session_response_with_sampling(
                &mut backend,
                Some(&model.model_id),
                &model.adapter,
                &model.sampling,
                &sealed,
                None,
                &CancellationToken::new(),
            )
            .unwrap_or_else(|error| panic!("{} translate: {error:#}", prompt.id));
            covered.extend(modalities);
        }

        assert_eq!(covered, served);
    }

