    #[test]
    fn provider_response_error_code_distinguishes_buyer_input_from_engine_failure() {
        let request_error =
            anyhow::Error::new(EngineError::InvalidRequest("bad tool schema".to_owned()))
                .context("generating provider response");
        assert_eq!(
            provider_response_error_code(&request_error),
            "request_invalid"
        );

        let common_request_error =
            provider_session_request_result::<()>(Err(anyhow!("invalid image dimensions")))
                .expect_err("request-phase failure");
        assert_eq!(
            provider_response_error_code(&common_request_error),
            "request_invalid"
        );
        assert_eq!(
            provider_response_error_message(&common_request_error),
            "invalid image dimensions"
        );

        let output_error =
            provider_session_output_error("model emitted malformed structured output")
                .context("generating provider response");
        assert_eq!(
            provider_response_error_code(&output_error),
            "model_output_invalid"
        );
        assert_eq!(
            provider_response_error_message(&output_error),
            "model emitted malformed structured output"
        );

        let engine_error = anyhow::Error::new(EngineError::Needle("worker exited".to_owned()))
            .context("generating provider response");
        assert_eq!(
            provider_response_error_code(&engine_error),
            "provider_response_failed"
        );
    }

    #[test]
    fn provider_engine_session_response_uses_backend_output() {
        let mut backend = FakeEngineBackend::new("engine says hi");
        let body = json!({
            "messages": [{
                "role": "user",
                "content": "Reply only: transport observer passed"
            }],
            "max_tokens": 8
        });
        let output = provider_engine_session_response(
            &mut backend,
            &catalog::CatalogAdapter::default(),
            &body,
            None,
        )
        .unwrap();

        assert_eq!(output.content, "engine says hi");
        assert!(output.tools.is_empty());
        assert_eq!(output.finish_reason, "stop");
        let request = backend.last_request.expect("engine request");
        let canonical_prompt_tokens = rough_text_tokens(&provider_session_prompt_text(&body));
        let rendered_prompt_tokens = rough_text_tokens(&request.prompt);
        assert_eq!(canonical_prompt_tokens, 5);
        assert_eq!(rendered_prompt_tokens, 7);
        assert_eq!(output.prompt_tokens, canonical_prompt_tokens);
        assert_eq!(output.completion_tokens, 2);
        assert_eq!(output.usage.input_tokens(), output.prompt_tokens);
        assert_eq!(output.usage.output_tokens(), 2);
        assert!(request
            .prompt
            .contains("user: Reply only: transport observer passed"));
        assert_eq!(request.max_new_tokens, 8);
        assert!(request.grammar.is_none());
    }

    #[test]
    fn tools_only_receipt_bills_buyer_verifiable_normalized_prompt_units() {
        let mut adapter = catalog::CatalogAdapter {
            tool_call_strategy: "mayhem_json".to_owned(),
            ..catalog::CatalogAdapter::default()
        };
        let mut tools_only_contract =
            catalog::endpoint_contract_template(mayhem_proto::ENDPOINT_OPENAI_CHAT_COMPLETIONS)
                .unwrap();
        tools_only_contract
            .required_request_attributes
            .push("tools".to_owned());
        tools_only_contract
            .request_attribute_specs
            .get_mut("tools")
            .unwrap()
            .min_items = Some(1);
        adapter.endpoint_families = vec![tools_only_contract];
        let body = json!({
            "messages": [{
                "role": "user",
                "content": "Find the weather in Berlin."
            }],
            "tools": [
                {
                    "type": "function",
                    "function": {
                        "name": "get_weather",
                        "description": "Return current weather observations for a city, country, unit system, and reporting station.",
                        "parameters": {
                            "type": "object",
                            "additionalProperties": false,
                            "required": ["city", "country", "units"],
                            "properties": {
                                "city": { "type": "string", "minLength": 1, "maxLength": 128 },
                                "country": { "type": "string", "pattern": "^[A-Z]{2}$" },
                                "units": { "type": "string", "enum": ["metric", "imperial"] },
                                "station": {
                                    "type": "object",
                                    "additionalProperties": false,
                                    "properties": {
                                        "id": { "type": "string" },
                                        "maximum_age_minutes": { "type": "integer", "minimum": 0, "maximum": 1440 }
                                    }
                                }
                            }
                        }
                    }
                },
                {
                    "type": "function",
                    "function": {
                        "name": "search_forecast_archive",
                        "description": "Search archived forecasts using a deliberately substantial schema.",
                        "parameters": {
                            "type": "object",
                            "additionalProperties": false,
                            "required": ["query"],
                            "properties": {
                                "query": { "type": "string" },
                                "years": {
                                    "type": "array",
                                    "items": { "type": "integer", "minimum": 1900, "maximum": 2100 },
                                    "maxItems": 25
                                }
                            }
                        }
                    }
                }
            ],
            "tool_choice": "required",
            "parallel_tool_calls": true,
            "max_tokens": 64
        });
        let sealed = provider_test_seal_contract_request(&body, &adapter).unwrap();
        let verified = provider_verify_endpoint_request(&sealed, None, &adapter).unwrap();
        let protocol_prompt_tokens =
            provider_protocol_prompt_tokens(verified.contract, verified.request)
                .unwrap()
                .unwrap();
        let mut needle = FakeEngineBackend::new(
            r#"{"tool":"get_weather","arguments":{"city":"Berlin","country":"DE","units":"metric"}}"#,
        )
        .with_backend_id("needle");
        needle.output.usage = mayhem_engine::UsageCounters::new(1, 9);

        let output = provider_engine_session_response(&mut needle, &adapter, &body, None).unwrap();
        assert_eq!(output.prompt_tokens, protocol_prompt_tokens);
        assert_eq!(output.usage.input_tokens(), protocol_prompt_tokens);

        let terms = test_provider_session_terms();
        let active = test_active_provider_session(&terms, vec!["text".to_owned()]);
        let receipt = provider_session_receipt(
            &terms,
            &active,
            &body,
            &output,
            &RuntimeKeypair::from_seed([9; 32]),
        )
        .unwrap();
        assert_eq!(receipt.body.usage.input_tokens(), protocol_prompt_tokens);

        let ordinary_adapter = catalog::CatalogAdapter {
            tool_call_strategy: "mayhem_json".to_owned(),
            ..catalog::CatalogAdapter::default()
        };
        let estimated = rough_text_tokens(&provider_session_prompt_text(&body));
        let mut ordinary = FakeEngineBackend::new(
            r#"{"tool":"get_weather","arguments":{"city":"Berlin","country":"DE","units":"metric"}}"#,
        );
        ordinary.output.usage = mayhem_engine::UsageCounters::new(1, 9);
        let ordinary_output =
            provider_engine_session_response(&mut ordinary, &ordinary_adapter, &body, None)
                .unwrap();
        assert_eq!(ordinary_output.prompt_tokens, estimated);
        assert_eq!(ordinary_output.usage.input_tokens(), estimated);
    }

    #[test]
    fn provider_engine_session_response_applies_signed_reasoning_output_policy() {
        let catalog_path = repo_path("catalog/models.json").unwrap();
        let catalog = catalog::load_document(&catalog_path).unwrap();
        let model = catalog
            .models
            .iter()
            .find(|model| model.model_id == "hauhaucs/qwen3.6-35b-a3b-uncensored")
            .expect("live Qwen model");
        let adapter = &model.adapter;
        let mut backend = FakeEngineBackend::new(
            "private reasoning that must stay internal</think>\n\npublic answer",
        );
        backend.output.usage.reasoning_tokens = 1;
        let body = json!({
            "model": model.model_id,
            "messages": [{"role": "user", "content": "answer the question"}]
        });
        let sealed = provider_seal_local_contract_request(&body, adapter, &model.model_id).unwrap();

        let output = provider_engine_session_response_with_sampling(
            &mut backend,
            Some(&model.model_id),
            adapter,
            &model.sampling,
            &sealed,
            None,
            &CancellationToken::new(),
        )
        .unwrap();

        assert_eq!(output.content, "public answer");
        assert_eq!(output.completion_tokens, 2);
        assert_eq!(
            output.usage_attribution.get("reasoning_output_tokens"),
            Some(&1)
        );
        assert_eq!(
            provider_reasoning_output_mode(
                adapter,
                backend.last_request.as_ref().expect("engine request")
            ),
            ProviderReasoningOutputMode::StripPrefilled
        );
    }

