    #[test]
    fn generation_calibration_maps_every_public_response_contract() {
        for (family, request, content_type, expected_artifact_field) in [
            (
                mayhem_proto::ENDPOINT_OPENAI_VIDEOS,
                json!({
                    "model": "test/video",
                    "prompt": "moving square",
                    "seconds": "4",
                    "size": "1280x720"
                }),
                "video/mp4",
                None,
            ),
            (
                mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO,
                json!({
                    "inputs": "moving square",
                    "parameters": {"num_frames": 8, "fps": 4.0}
                }),
                "video/mp4",
                Some("video"),
            ),
            (
                mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS,
                json!({"model": "test/audio", "prompt": "wind"}),
                "audio/wav",
                Some("audio"),
            ),
            (
                mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS,
                json!({"model": "test/music", "prompt": "piano"}),
                "audio/wav",
                Some("music"),
            ),
            (
                mayhem_proto::ENDPOINT_HF_TEXT_TO_AUDIO,
                json!({"inputs": "rain"}),
                "audio/wav",
                Some("audio"),
            ),
        ] {
            let usage = if content_type.starts_with("video/") {
                provider_video_generation_usage(4, 96)
            } else {
                provider_audio_generation_usage(5, 3)
            };
            let output = ProviderSessionOutput {
                content: String::new(),
                reasoning_evidence: String::new(),
                tools: Vec::new(),
                embeddings: None,
                transcription: None,
                artifacts: vec![ProviderSessionArtifact {
                    id: "calibration-artifact".to_owned(),
                    content_type: content_type.to_owned(),
                    bytes: if content_type.starts_with("audio/") {
                        tiny_wav_bytes(16_000)
                    } else {
                        b"calibration artifact".to_vec()
                    },
                }],
                finish_reason: "stop".to_owned(),
                prompt_tokens: 0,
                completion_tokens: 0,
                token_ids: Vec::new(),
                usage,
                usage_attribution: BTreeMap::new(),
            };
            let response = catalog_endpoint_calibration_response(family, &request, &output)
                .unwrap_or_else(|err| panic!("{family} response mapping failed: {err:#}"));
            let contract = mayhem_proto::endpoint_family_contract_template(family).unwrap();
            mayhem_proto::validate_endpoint_response(&contract, &response).unwrap_or_else(
                |violations| panic!("{family} response violations: {violations:?}"),
            );
            if let Some(field) = expected_artifact_field {
                assert!(response.get(field).is_some(), "{family} missing {field}");
            }
            if family == mayhem_proto::ENDPOINT_MAYHEM_AUDIO_GENERATIONS {
                assert!(response.get("music").is_none());
            }
            if family == mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS {
                assert!(response.get("audio").is_none());
            }
        }
    }

    #[test]
    fn provider_artifact_collector_bounds_and_assembles_during_generation() {
        let mut collector = ProviderSessionArtifactCollector::with_limits(5, 2);
        collector
            .push(ArtifactChunk {
                artifact_id: "video".to_owned(),
                content_type: "video/mp4".to_owned(),
                index: 0,
                bytes: vec![1, 2],
                final_chunk: false,
            })
            .unwrap();
        collector
            .push(ArtifactChunk {
                artifact_id: "audio".to_owned(),
                content_type: "audio/wav".to_owned(),
                index: 0,
                bytes: vec![4],
                final_chunk: true,
            })
            .unwrap();
        collector
            .push(ArtifactChunk {
                artifact_id: "video".to_owned(),
                content_type: "video/mp4".to_owned(),
                index: 1,
                bytes: vec![3, 4],
                final_chunk: true,
            })
            .unwrap();

        let artifacts = collector.finish().unwrap();
        assert_eq!(artifacts.len(), 2);
        assert_eq!(artifacts[0].id, "audio");
        assert_eq!(artifacts[0].bytes, vec![4]);
        assert_eq!(artifacts[1].id, "video");
        assert_eq!(artifacts[1].bytes, vec![1, 2, 3, 4]);
    }

    #[test]
    fn provider_artifact_collector_rejects_oversize_before_buffering() {
        let mut collector = ProviderSessionArtifactCollector::with_limits(3, 1);
        collector
            .push(ArtifactChunk {
                artifact_id: "video".to_owned(),
                content_type: "video/mp4".to_owned(),
                index: 0,
                bytes: vec![1, 2],
                final_chunk: false,
            })
            .unwrap();
        let error = collector
            .push(ArtifactChunk {
                artifact_id: "video".to_owned(),
                content_type: "video/mp4".to_owned(),
                index: 1,
                bytes: vec![3, 4],
                final_chunk: true,
            })
            .unwrap_err();

        assert!(error.to_string().contains("session byte budget"));
        assert_eq!(collector.total_bytes, 2);
        assert_eq!(collector.artifacts["video"].bytes, vec![1, 2]);
    }

    #[test]
    fn provider_session_artifact_delta_frames_are_chunked_and_addressed() {
        let artifact = ProviderSessionArtifact {
            id: "image-1".to_owned(),
            content_type: "image/png".to_owned(),
            bytes: vec![7; PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE + 3],
        };
        let frames =
            provider_session_artifact_delta_frames("rid-1", 2, std::slice::from_ref(&artifact));
        let expected_hash = blake3_bytes_hex(&artifact.bytes);

        assert_eq!(frames.len(), 2);
        assert_eq!(frames[0]["i"], 2);
        assert_eq!(frames[0]["artifact"]["id"], "image-1");
        assert_eq!(frames[0]["artifact"]["encoding"], "hex");
        assert_eq!(frames[0]["artifact"]["offset"], 0);
        assert_eq!(
            frames[0]["artifact"]["len"],
            PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE
        );
        assert_eq!(frames[0]["artifact"]["blake3"], expected_hash);
        assert_eq!(frames[0]["artifact"]["final"], false);
        assert_eq!(frames[1]["i"], 3);
        assert_eq!(
            frames[1]["artifact"]["offset"],
            PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE
        );
        assert_eq!(frames[1]["artifact"]["len"], 3);
        assert_eq!(frames[1]["artifact"]["blake3"], expected_hash);
        assert_eq!(frames[1]["artifact"]["final"], true);
    }

