    #[test]
    fn provider_session_failure_isolated_to_the_failed_session() {
        let mut sessions = HashMap::new();
        let mut pending_requests = HashMap::new();
        let mut pending_payloads = HashMap::new();
        for id in ["failed", "healthy"] {
            sessions.insert(
                id.to_owned(),
                ActiveProviderSession {
                    remote: format!("remote-{id}"),
                    rail: "tap".to_owned(),
                    user_pubkey: "aa".repeat(32),
                    session_id: id.to_owned(),
                    billing_id: "bb".repeat(32),
                    billing_attempt: 0,
                    billing_prior_usage: ReceiptUsage::default(),
                    billing_prior_au_owed_cum: 0,
                    billing_epoch: 7,
                    reservation_id: "12".repeat(32),
                    reservation_expires_after_epoch: 31,
                    reservation_receipt_grace_epochs: 6,
                    payout_revision: "34".repeat(32),
                    receipt_settlement: None,
                    price_ver: 1,
                    locked_rate_map: text_generation_rate_map(1, 2),
                    locked_per_req_au: 0,
                    locked_min_session_au: 0,
                    served_ctx: 8192,
                    required_modalities: vec!["text".to_owned()],
                    required_specialities: BTreeMap::new(),
                    ctx_bracket: Some(ctx_bracket_for_tokens(8192).to_owned()),
                    ctx_bracket_table_ver: Some(CTX_BRACKET_TABLE_VERSION),
                    checkpoint_every: CheckpointPolicy { tokens: 1, ms: 0 },
                    max_spend_au: MoneyAu::MAX,
                    accept_replay: None,
                },
            );
            pending_requests.insert(id.to_owned(), Instant::now() + Duration::from_secs(30));
            pending_payloads.insert(
                provider_session_payload_key(id, "r1", &"bb".repeat(32)),
                PendingProviderPayload::default(),
            );
        }

        discard_provider_session_state(
            &mut sessions,
            &mut pending_requests,
            &mut pending_payloads,
            "failed",
        );

        assert!(!sessions.contains_key("failed"));
        assert!(!pending_requests.contains_key("failed"));
        assert!(pending_payloads
            .keys()
            .all(|key| !key.starts_with("failed:")));
        assert!(sessions.contains_key("healthy"));
        assert!(pending_requests.contains_key("healthy"));
        assert!(pending_payloads
            .keys()
            .any(|key| key.starts_with("healthy:")));
    }

    #[test]
    fn provider_session_transport_close_before_request_releases_capacity() {
        let terms = test_provider_session_terms();
        let mut sessions = HashMap::new();
        let mut pending_requests = HashMap::new();
        let mut pending_payloads = HashMap::new();
        let active = test_active_provider_session(&terms, vec!["text".to_owned()]);
        let session_id = active.session_id.clone();
        let remote = active.remote.clone();
        sessions.insert(session_id.clone(), active);
        pending_requests.insert(session_id.clone(), Instant::now() + Duration::from_secs(30));
        pending_payloads.insert(
            provider_session_payload_key(&session_id, "rid", &"bb".repeat(32)),
            PendingProviderPayload::default(),
        );
        let load = ProviderHeartbeatLoad::default();
        load.set_active_sessions(sessions.len());

        let released = discard_pre_request_provider_session_on_close(
            &mut sessions,
            &mut pending_requests,
            &mut pending_payloads,
            &load,
            &json!({
                "type": "session_closed",
                "session_id": session_id,
                "remote": remote,
                "reason": "closed before request",
            }),
        );

        assert!(released);
        assert!(sessions.is_empty());
        assert!(pending_requests.is_empty());
        assert!(pending_payloads.is_empty());
        assert_eq!(load.snapshot(1).active_slots, 0);
        assert_eq!(load.snapshot(1).free_slots, 1);
    }

