    #[test]
    fn provider_rooms_auto_selects_only_open_matching_admin_rooms() {
        let root = "aa".repeat(32);
        let contract = test_contract(&root);
        let enclave = &contract.enclaves[0];
        let mut canonical_rooms = contract.rooms.clone();
        let other_model_room_id = "cc".repeat(16);
        let other_enclave_room_id = "dd".repeat(16);
        let provider_created_room_id = "ee".repeat(16);
        canonical_rooms.push(LedgerRoom {
            room_id: other_enclave_room_id.clone(),
            sidechannel: format!("mx/room/{other_enclave_room_id}"),
            enclave_id: Some("66".repeat(32)),
            model_id: enclave.model_id.clone(),
            label: "other-enclave".to_owned(),
            status: "open".to_owned(),
            creator_role: Some("admin".to_owned()),
        });
        canonical_rooms.push(LedgerRoom {
            room_id: provider_created_room_id.clone(),
            sidechannel: format!("mx/room/{provider_created_room_id}"),
            enclave_id: Some(enclave.enclave_id.clone()),
            model_id: enclave.model_id.clone(),
            label: "provider-created".to_owned(),
            status: "open".to_owned(),
            creator_role: Some("provider".to_owned()),
        });
        canonical_rooms.push(LedgerRoom {
            room_id: "provider-local-only".to_owned(),
            sidechannel: "mx/room/provider-local-only".to_owned(),
            enclave_id: Some(enclave.enclave_id.clone()),
            model_id: enclave.model_id.clone(),
            label: "raw-intercom".to_owned(),
            status: "open".to_owned(),
            creator_role: Some("admin".to_owned()),
        });
        let rooms = select_provider_rooms(&canonical_rooms, enclave, "auto").unwrap();

        assert_eq!(rooms.len(), 1);
        assert_eq!(rooms[0].room_id, "aa".repeat(16));
        assert!(select_provider_rooms(&canonical_rooms, enclave, &other_model_room_id).is_err());
        assert!(select_provider_rooms(&canonical_rooms, enclave, &other_enclave_room_id).is_err());
        let err = select_provider_rooms(&canonical_rooms, enclave, &provider_created_room_id)
            .unwrap_err();
        assert!(format!("{err:#}").contains("creator_role"));
        let err =
            select_provider_rooms(&canonical_rooms, enclave, "provider-local-only").unwrap_err();
        assert!(format!("{err:#}").contains("not a canonical contract room"));
    }

    #[test]
    fn epoch_receipt_messages_round_trip_gateway_receipts() {
        let receipt = json!({
            "voucher": { "session_id": "s1" },
            "receipt": {
                "schema_version": 1,
                "session_id": "s1",
                "seq": 2,
                "final": true,
                "user": "u",
                "provider": "p",
                "au_owed_cum": "100"
            },
            "receipt_ack": { "session_id": "s1", "seq": 2, "user_sig": "sig" }
        });
        let id = receipt_id(&receipt);
        assert_eq!(id, "s1:2");

        let message = epoch_receipt_messages(7, id.clone(), receipt.clone(), usize::MAX)
            .unwrap()
            .pop()
            .unwrap();
        assert_eq!(message["t"], "epoch.receipt");
        assert_eq!(message["epoch"], 7);
        assert_eq!(message["receipt_id"], id);

        let event = json!({
            "type": "sidechannel_message",
            "channel": "mx/epoch/7",
            "message": message,
        });
        let mut pending = PendingEpochReceiptPayloads::default();
        let (extracted_id, extracted) = collect_epoch_receipt_from_sidechannel_event_with_pending(
            &event,
            7,
            "mx/epoch/7",
            &mut pending,
        )
        .unwrap()
        .unwrap();
        assert_eq!(extracted_id, "s1:2");
        assert_eq!(extracted, receipt);
    }

    #[test]
    fn epoch_receipt_collector_filters_wrong_channel_epoch_and_type() {
        let receipt = json!({ "receipt": { "session_id": "s1", "seq": 1 } });
        let message = epoch_receipt_messages(7, receipt_id(&receipt), receipt, usize::MAX)
            .unwrap()
            .pop()
            .unwrap();
        let event = json!({
            "type": "sidechannel_message",
            "channel": "mx/epoch/7",
            "message": message,
        });
        let mut pending = PendingEpochReceiptPayloads::default();
        assert!(collect_epoch_receipt_from_sidechannel_event_with_pending(
            &event,
            7,
            "mx/epoch/7",
            &mut pending,
        )
        .unwrap()
        .is_some());
        assert!(collect_epoch_receipt_from_sidechannel_event_with_pending(
            &event,
            8,
            "mx/epoch/7",
            &mut pending,
        )
        .unwrap()
        .is_none());
        assert!(collect_epoch_receipt_from_sidechannel_event_with_pending(
            &event,
            7,
            "mx/epoch/8",
            &mut pending,
        )
        .unwrap()
        .is_none());

        let wrong_type = json!({
            "type": "sidechannel_message",
            "channel": "mx/epoch/7",
            "message": { "t": "hb", "epoch": 7, "receipt": {} },
        });
        assert!(collect_epoch_receipt_from_sidechannel_event_with_pending(
            &wrong_type,
            7,
            "mx/epoch/7",
            &mut pending,
        )
        .unwrap()
        .is_none());
    }

    #[test]
    fn epoch_receipt_messages_chunk_large_receipts_under_transport_limit() {
        let receipt = json!({
            "receipt": {
                "schema_version": 1,
                "session_id": "large-session",
                "seq": 9,
                "final": true,
                "user": "u",
                "provider": "p",
                "au_owed_cum": "100"
            },
            "receipt_ack": { "session_id": "large-session", "seq": 9, "user_sig": "sig" },
            "metadata": "x".repeat(96 * 1024),
        });
        let id = receipt_id(&receipt);
        let max_message_bytes = 12 * 1024;
        let messages =
            epoch_receipt_messages(9, id.clone(), receipt.clone(), max_message_bytes).unwrap();
        assert!(messages.len() > 2);
        assert!(messages
            .iter()
            .all(|message| epoch_receipt_message_json_len(message).unwrap() <= max_message_bytes));
        assert!(messages[..messages.len() - 1]
            .iter()
            .all(|message| message["t"] == "epoch.receipt_chunk"));
        assert_eq!(messages.last().unwrap()["t"], "epoch.receipt_ref");

        let mut pending = PendingEpochReceiptPayloads::default();
        let mut extracted = None;
        for message in messages {
            let event = json!({
                "type": "sidechannel_message",
                "channel": "mx/epoch/9",
                "message": message,
            });
            if let Some(result) = collect_epoch_receipt_from_sidechannel_event_with_pending(
                &event,
                9,
                "mx/epoch/9",
                &mut pending,
            )
            .unwrap()
            {
                extracted = Some(result);
            }
        }
        let (extracted_id, extracted_receipt) = extracted.unwrap();
        assert_eq!(extracted_id, id);
        assert_eq!(extracted_receipt, receipt);
    }

    #[test]
    fn epoch_receipt_collector_accepts_manifest_before_chunks() {
        let receipt = json!({
            "receipt": { "session_id": "large-session", "seq": 10 },
            "metadata": "y".repeat(64 * 1024),
        });
        let id = receipt_id(&receipt);
        let mut messages =
            epoch_receipt_messages(10, id.clone(), receipt.clone(), 12 * 1024).unwrap();
        let ref_message = messages.pop().unwrap();
        let mut pending = PendingEpochReceiptPayloads::default();
        let ref_event = json!({
            "type": "sidechannel_message",
            "channel": "mx/epoch/10",
            "message": ref_message,
        });
        assert!(collect_epoch_receipt_from_sidechannel_event_with_pending(
            &ref_event,
            10,
            "mx/epoch/10",
            &mut pending,
        )
        .unwrap()
        .is_none());

        let mut extracted = None;
        for message in messages {
            let event = json!({
                "type": "sidechannel_message",
                "channel": "mx/epoch/10",
                "message": message,
            });
            if let Some(result) = collect_epoch_receipt_from_sidechannel_event_with_pending(
                &event,
                10,
                "mx/epoch/10",
                &mut pending,
            )
            .unwrap()
            {
                extracted = Some(result);
            }
        }
        let (extracted_id, extracted_receipt) = extracted.unwrap();
        assert_eq!(extracted_id, id);
        assert_eq!(extracted_receipt, receipt);
    }

