    #[test]
    fn service_request_signing_message_matches_intercom_canonical_form() {
        let actor = "bb".repeat(32);
        let nonce = "12".repeat(32);
        let message = service_request_signing_message(
            "stripe_connect_status",
            &actor,
            &"aa".repeat(32),
            &"cc".repeat(32),
            &json!({
                "provider": actor.clone(),
                "request_nonce": nonce.clone(),
            }),
        );
        assert_eq!(
            message,
            format!(
                "{{\"actor\":\"{actor}\",\"admin\":\"{}\",\"domain\":\"mayhem-service-request\",\"payload\":{{\"provider\":\"{actor}\",\"request_nonce\":\"{nonce}\"}},\"service\":\"stripe_connect_status\",\"signing_version\":1,\"transport\":\"{}\"}}",
                "aa".repeat(32),
                "cc".repeat(32),
            )
        );

        let signing_key = SigningKey::from_bytes(&[1_u8; 32]);
        let actor = hex_encode(&signing_key.verifying_key().to_bytes());
        assert_eq!(
            actor,
            "8a88e3dd7409f195fd52db2d3cba5d72ca6709bf1d94121bf3748801b40f6f5c"
        );
        let message = service_request_signing_message(
            "stripe_connect_status",
            &actor,
            &"aa".repeat(32),
            &"cc".repeat(32),
            &json!({
                "provider": actor,
                "request_nonce": "12".repeat(32),
            }),
        );
        assert_eq!(
            hex_encode(&signing_key.sign(message.as_bytes()).to_bytes()),
            "75532c9727d07be74033c992d1ef38cda19553e4250a6d40d91f267c072f202361fd5860615bc731e271e048a612b4996eb60eefca8ccd2abce1057c1ce68e0b"
        );
    }

    #[test]
    fn provider_stripe_onboarding_requires_exact_connect_host_and_copy_paste_match() {
        let valid = json!({
            "ok": true,
            "rail": "fiat",
            "processor_rail": "stripe",
            "provider": "aa".repeat(32),
            "account": {
                "id": "acct_test_provider",
                "ready": false
            },
            "onboarding": {
                "url": "https://connect.stripe.com/setup/test"
            },
            "copy_paste": {
                "onboarding_url": "https://connect.stripe.com/setup/test"
            },
            "payout_binding": {
                "ok": true,
                "pending": true
            }
        });
        validate_provider_stripe_response(&valid, &"aa".repeat(32)).unwrap();
        let rejected = json!({
            "ok": false,
            "message": "connected account mode did not match paygate mode"
        });
        assert_eq!(
            validate_provider_stripe_response(&rejected, &"aa".repeat(32))
                .unwrap_err()
                .to_string(),
            "connected account mode did not match paygate mode"
        );
        assert_eq!(
            provider_stripe_onboarding_url(&valid).unwrap().as_deref(),
            Some("https://connect.stripe.com/setup/test")
        );

        let mut wrong_host = valid.clone();
        wrong_host["onboarding"]["url"] =
            json!("https://connect.stripe.com.evil.example/setup/test");
        assert!(provider_stripe_onboarding_url(&wrong_host).is_err());

        let mut mismatch = valid;
        mismatch["copy_paste"]["onboarding_url"] = json!("https://connect.stripe.com/setup/other");
        assert!(provider_stripe_onboarding_url(&mismatch).is_err());
    }

