    #[test]
    fn use_gateway_bind_addr_honors_config_port_and_defers_non_loopback_auth_check() {
        let config = MayhemConfig {
            identity: None,
            network: Some(ConfigNetwork {
                rpc_url: None,
                sc_bridge_url: None,
                sc_bridge_token: None,
                gateway_bind: None,
                gateway_url: Some("http://127.0.0.1:4242/v1".to_owned()),
                tnk_treasury_address: None,
                admin_peer_pubkey: None,
            }),
            provider: None,
            user: None,
            role: None,
        };

        let from_config = gateway_bind_addr(Some(&config), None, 11_435).unwrap();
        assert_eq!(from_config.to_string(), "127.0.0.1:4242");

        let explicit = gateway_bind_addr(Some(&config), Some("127.0.0.1:5252"), 11_435).unwrap();
        assert_eq!(explicit.to_string(), "127.0.0.1:5252");
        assert_eq!(gateway_public_url(explicit), "http://127.0.0.1:5252");

        let shared = gateway_bind_addr(Some(&config), Some("0.0.0.0:5252"), 11_435).unwrap();
        assert_eq!(shared.to_string(), "0.0.0.0:5252");
        assert!(validate_gateway_bind_access(shared, true, false).is_err());
        assert!(validate_gateway_bind_access(shared, true, true).is_ok());

        let lan = gateway_bind_addr(Some(&config), Some("192.168.1.5:5252"), 11_435).unwrap();
        assert_eq!(lan.to_string(), "192.168.1.5:5252");
    }

    #[test]
    fn gateway_tokens_create_persists_only_hash_metadata() {
        let home = temp_work_dir("mayhem-token-create").unwrap();
        tokens_create(TokenCreateArgs {
            home: Some(home.clone()),
            name: "agent-loop".to_owned(),
            expires: Some("none".to_owned()),
            budget: Some("10/day".to_owned()),
            max_rate: Some(60),
            models: Some("mayhem/dev-chat-tools,mayhem/dev-embed".to_owned()),
            json: true,
        })
        .unwrap();

        let store_path = gateway_token_store_path(&home);
        let raw = fs::read_to_string(&store_path).unwrap();
        assert!(!raw.contains("sk-mayhem-"));
        let store = read_gateway_token_store(&store_path).unwrap();
        assert_eq!(store.tokens.len(), 1);
        let token = &store.tokens[0];
        assert_eq!(token.name, "agent-loop");
        assert_eq!(token.budget_au, Some(10_000_000_000_000_000_000));
        assert_eq!(token.budget_period, Some(GatewayTokenBudgetPeriod::Day));
        assert_eq!(token.max_rate_per_minute, Some(60));
        assert_eq!(
            token.models,
            vec![
                "mayhem/dev-chat-tools".to_owned(),
                "mayhem/dev-embed".to_owned()
            ]
        );
        assert_eq!(token.token_hash.len(), 64);
        assert!(token.token_id.starts_with("tok_"));
    }

    #[test]
    fn opencode_uses_a_reusable_real_gateway_token() {
        let home = temp_work_dir("mayhem-opencode-token").unwrap();
        let config_path = home.join("opencode").join("opencode.json");
        let first = ensure_opencode_gateway_token(&home, &config_path).unwrap();
        assert!(first.starts_with("sk-mayhem-"));
        merge_mayhem_opencode_config(&config_path, "http://127.0.0.1:11435", None, false, &first)
            .unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = fs::metadata(&config_path).unwrap().permissions().mode() & 0o777;
            assert_eq!(mode, 0o600);
        }
        let second = ensure_opencode_gateway_token(&home, &config_path).unwrap();
        assert_eq!(second, first);

        let store_path = gateway_token_store_path(&home);
        let raw_store = fs::read_to_string(&store_path).unwrap();
        assert!(!raw_store.contains(&first));
        let store = read_gateway_token_store(&store_path).unwrap();
        assert_eq!(store.tokens.len(), 1);
        assert_eq!(store.tokens[0].name, OPENCODE_GATEWAY_TOKEN_NAME);
        assert_eq!(store.tokens[0].token_hash, gateway_token_hash(&first));

        let mut revoked = store;
        revoked.tokens[0].revoked_at = Some(unix_epoch_seconds().unwrap());
        write_gateway_token_store(&store_path, &revoked).unwrap();
        let replacement = ensure_opencode_gateway_token(&home, &config_path).unwrap();
        assert_ne!(replacement, first);
        merge_mayhem_opencode_config(
            &config_path,
            "http://127.0.0.1:11435",
            None,
            false,
            &replacement,
        )
        .unwrap();
        assert_eq!(
            read_opencode_gateway_token(&config_path)
                .unwrap()
                .as_deref(),
            Some(replacement.as_str())
        );

        let _ = fs::remove_dir_all(home);
    }

    #[test]
    fn use_gateway_accepts_wallet_and_rail_flags() {
        let temp = test_temp_dir("use-wallet-password-file");
        let password_path = temp.join("wallet-password");
        fs::write(&password_path, "secret\n").unwrap();
        let cli = Cli::try_parse_from(vec![
            "mayhem".to_owned(),
            "use".to_owned(),
            "--keypair".to_owned(),
            "/tmp/mayhem/stores/main/db/keypair.json".to_owned(),
            "--peer-store-name".to_owned(),
            "terminal".to_owned(),
            "--wallet-password-file".to_owned(),
            password_path.display().to_string(),
            "--rail".to_owned(),
            "tnk".to_owned(),
            "--min-ctx".to_owned(),
            "128000".to_owned(),
            "--canary-probe-min-interval-sessions".to_owned(),
            "1".to_owned(),
            "--canary-probe-max-interval-sessions".to_owned(),
            "1".to_owned(),
            "--canary-probe-epoch".to_owned(),
            "7".to_owned(),
            "--receipt-checkpoint-tokens".to_owned(),
            "32".to_owned(),
            "--receipt-checkpoint-ms".to_owned(),
            "2500".to_owned(),
        ])
        .unwrap();
        match cli.command {
            Commands::Use(args) => {
                assert_eq!(
                    args.keypair.as_deref(),
                    Some(Path::new("/tmp/mayhem/stores/main/db/keypair.json"))
                );
                assert_eq!(args.peer_store_name, "terminal");
                assert_eq!(args.wallet_password.as_deref(), Some("secret"));
                assert_eq!(args.rail, GatewayLedgerRail::Tnk);
                assert_eq!(args.min_ctx, Some(128_000));
                assert_eq!(args.canary_probe_min_interval_sessions, Some(1));
                assert_eq!(args.canary_probe_max_interval_sessions, Some(1));
                assert_eq!(args.canary_probe_epoch, Some(7));
                assert_eq!(args.receipt_checkpoint_tokens, Some(32));
                assert_eq!(args.receipt_checkpoint_ms, Some(2500));
            }
            other => panic!("expected use command, got {other:?}"),
        }
        fs::remove_dir_all(temp).unwrap();
    }

