    #[test]
    fn video_canary_uses_signed_hf_family_fixed_shape_and_bounded_i2v() {
        let mut model = test_catalog(&"aa".repeat(32)).models.remove(0);
        model.model_class = MODEL_CLASS_VIDEO_GENERATION.to_owned();
        let mut contract =
            catalog::endpoint_contract_template(mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO).unwrap();
        contract
            .request_attribute_specs
            .get_mut("parameters.num_frames")
            .unwrap()
            .enum_values = vec![json!(9)];
        contract
            .request_attributes
            .retain(|path| path != "parameters.num_inference_steps");
        contract
            .request_attribute_specs
            .remove("parameters.num_inference_steps");
        contract
            .request_attributes
            .push("parameters.input_image".to_owned());
        contract.request_attribute_specs.insert(
            "parameters.input_image".to_owned(),
            mayhem_proto::EndpointAttributeSpec::new(mayhem_proto::EndpointValueType::Object),
        );
        model.adapter.endpoint_families = vec![contract];
        let prompt: CanaryPrompt = serde_json::from_value(json!({
            "id": "bounded-i2v",
            "prompt": "animate this fixed launch image",
            "seed": 17,
            "endpoint_family": "hf_text_to_video",
            "parameters": {
                "num_frames": 9,
                "fps": 8,
                "seed": 17,
                "input_image": {"image_url": tiny_png_data_url()}
            }
        }))
        .unwrap();

        let body = provider_canary_self_test_body(&model, &prompt).unwrap();
        let sealed =
            provider_seal_local_contract_request(&body, &model.adapter, &model.model_id).unwrap();
        let verified =
            provider_verify_endpoint_request(&sealed, Some(&model.model_id), &model.adapter)
                .unwrap();
        let contract = model.adapter.endpoint_families.first().unwrap();

        assert_eq!(verified.family, mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO);
        assert_eq!(
            provider_video_canary_fixed_shape(contract, verified.request).unwrap(),
            (9, 8.0)
        );
        assert!(
            verified.request["parameters"]
                .get("num_inference_steps")
                .is_none(),
            "the output canary must not expose the backend-owned denoise schedule"
        );
        assert_eq!(
            provider_media_generation_request_from_body(&verified.family, verified.request)
                .unwrap()
                .step_count,
            None
        );
        assert!(
            provider_video_canary_conditioning_image(contract, verified.request)
                .unwrap()
                .is_some()
        );

        let mut remote = prompt;
        remote
            .endpoint_attributes
            .get_mut("parameters")
            .and_then(Value::as_object_mut)
            .unwrap()
            .insert(
                "input_image".to_owned(),
                json!({"image_url": "https://example.test/fixture.png"}),
            );
        let body = provider_canary_self_test_body(&model, &remote).unwrap();
        let sealed =
            provider_seal_local_contract_request(&body, &model.adapter, &model.model_id).unwrap();
        let verified =
            provider_verify_endpoint_request(&sealed, Some(&model.model_id), &model.adapter)
                .unwrap();
        assert!(
            provider_video_canary_conditioning_image(contract, verified.request)
                .unwrap_err()
                .to_string()
                .contains("remote image URLs are not fetched")
        );
    }

    #[test]
    fn sulphur_video_canary_propagates_direct_shape_for_each_endpoint_family() {
        let catalog = catalog::load_document(&repo_path("catalog/models.json").unwrap()).unwrap();
        let model = catalog
            .models
            .iter()
            .find(|model| model.model_id == "SulphurAI/Sulphur-2-base")
            .expect("Sulphur catalog model");

        for family in [
            mayhem_proto::ENDPOINT_OPENAI_VIDEOS,
            mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO,
        ] {
            let prompt: CanaryPrompt = serde_json::from_value(json!({
                "id": format!("direct-{family}"),
                "endpoint_family": family,
                "prompt": "A fixed direct-value video canary.",
                "size": "704x448",
                "seed": 11,
                "num_frames": 121,
                "fps": 24,
                "negative_prompt": "blur, watermark"
            }))
            .unwrap();

            let body = provider_canary_self_test_body(model, &prompt).unwrap();
            let (frames, fps, negative_prompt) = if family == mayhem_proto::ENDPOINT_OPENAI_VIDEOS {
                (
                    body["num_frames"].clone(),
                    body["fps"].clone(),
                    body["negative_prompt"].clone(),
                )
            } else {
                (
                    body["parameters"]["num_frames"].clone(),
                    body["parameters"]["fps"].clone(),
                    body["parameters"]["negative_prompt"].clone(),
                )
            };
            assert_eq!(frames, json!(121), "{family}");
            assert_eq!(fps, json!(24.0), "{family}");
            assert_eq!(negative_prompt, json!("blur, watermark"), "{family}");

            let sealed =
                provider_seal_local_contract_request(&body, &model.adapter, &model.model_id)
                    .unwrap();
            let verified =
                provider_verify_endpoint_request(&sealed, Some(&model.model_id), &model.adapter)
                    .unwrap();
            let request =
                provider_media_generation_request_from_body(&verified.family, verified.request)
                    .unwrap();
            assert_eq!(request.frame_count, Some(121), "{family}");
        }
    }

    #[test]
    fn video_canary_endpoint_attributes_override_direct_shape_for_each_family() {
        let catalog = catalog::load_document(&repo_path("catalog/models.json").unwrap()).unwrap();
        let model = catalog
            .models
            .iter()
            .find(|model| model.model_id == "SulphurAI/Sulphur-2-base")
            .expect("Sulphur catalog model");

        for family in [
            mayhem_proto::ENDPOINT_OPENAI_VIDEOS,
            mayhem_proto::ENDPOINT_HF_TEXT_TO_VIDEO,
        ] {
            let mut prompt: CanaryPrompt = serde_json::from_value(json!({
                "id": format!("precedence-{family}"),
                "endpoint_family": family,
                "prompt": "A fixed precedence video canary.",
                "size": "704x448",
                "seed": 11,
                "num_frames": 121,
                "fps": 24,
                "negative_prompt": "direct value"
            }))
            .unwrap();
            if family == mayhem_proto::ENDPOINT_OPENAI_VIDEOS {
                prompt
                    .endpoint_attributes
                    .insert("num_frames".to_owned(), json!(9));
                prompt
                    .endpoint_attributes
                    .insert("fps".to_owned(), json!(8));
                prompt
                    .endpoint_attributes
                    .insert("negative_prompt".to_owned(), json!("endpoint attribute"));
            } else {
                prompt.endpoint_attributes.insert(
                    "parameters".to_owned(),
                    json!({
                        "num_frames": 9,
                        "fps": 8,
                        "negative_prompt": "endpoint attribute"
                    }),
                );
            }

            let body = provider_canary_self_test_body(model, &prompt).unwrap();
            let (frames, fps, negative_prompt) = if family == mayhem_proto::ENDPOINT_OPENAI_VIDEOS {
                (
                    body["num_frames"].clone(),
                    body["fps"].clone(),
                    body["negative_prompt"].clone(),
                )
            } else {
                (
                    body["parameters"]["num_frames"].clone(),
                    body["parameters"]["fps"].clone(),
                    body["parameters"]["negative_prompt"].clone(),
                )
            };
            assert_eq!(frames, json!(9), "{family}");
            assert_eq!(fps, json!(8), "{family}");
            assert_eq!(negative_prompt, json!("endpoint attribute"), "{family}");

            let sealed =
                provider_seal_local_contract_request(&body, &model.adapter, &model.model_id)
                    .unwrap();
            let verified =
                provider_verify_endpoint_request(&sealed, Some(&model.model_id), &model.adapter)
                    .unwrap();
            let request =
                provider_media_generation_request_from_body(&verified.family, verified.request)
                    .unwrap();
            assert_eq!(request.frame_count, Some(9), "{family}");
        }
    }

