    #[test]
    fn aggregate_canary_fingerprint_is_prompt_order_and_id_bound() {
        let first = test_calibration_prompt("p1", "aa".repeat(32));
        let second = test_calibration_prompt("p2", "bb".repeat(32));
        let same_digest_different_id = test_calibration_prompt("p3", "aa".repeat(32));

        assert_eq!(
            aggregate_canary_fingerprint(&[first.clone(), second.clone()]),
            aggregate_canary_fingerprint(&[first.clone(), second.clone()])
        );
        assert_ne!(
            aggregate_canary_fingerprint(&[first.clone(), second.clone()]),
            aggregate_canary_fingerprint(&[second, first.clone()])
        );
        assert_ne!(
            aggregate_canary_fingerprint(&[first]),
            aggregate_canary_fingerprint(&[same_digest_different_id])
        );
    }

    #[test]
    fn non_token_canary_aggregate_matches_catalog_map_order() {
        let first = test_calibration_prompt("stt-z", "aa".repeat(32));
        let second = test_calibration_prompt("stt-a", "bb".repeat(32));

        assert_ne!(
            aggregate_canary_fingerprint_for_method(
                CANARY_VERIFICATION_TOKEN_FINGERPRINT,
                &[first.clone(), second.clone()],
            ),
            aggregate_canary_fingerprint_for_method(
                CANARY_VERIFICATION_TOKEN_FINGERPRINT,
                &[second.clone(), first.clone()],
            )
        );
        assert_eq!(
            aggregate_canary_fingerprint_for_method(
                CANARY_VERIFICATION_TRANSCRIPT_MATCH,
                &[first, second],
            ),
            aggregate_prompt_fingerprint_map([
                ("stt-a", "bb".repeat(32)),
                ("stt-z", "aa".repeat(32)),
            ])
        );
    }

    #[test]
    fn token_canary_reproducibility_derives_exact_common_prefix() {
        let mut expected = test_calibration_prompt("p1", canary_token_fingerprint([1, 2, 3]));
        expected.token_ids = vec![1, 2, 3];
        expected.token_prefix = expected.token_ids.clone();
        let mut drifted = expected.clone();
        drifted.token_ids = vec![1, 2, 9];

        merge_token_canary_prefix("base canary", &mut expected, &drifted).unwrap();
        assert_eq!(expected.token_prefix, vec![1, 2]);

        let mut first_token_drift = drifted;
        first_token_drift.token_ids = vec![9, 2, 3];
        let err = merge_token_canary_prefix("base canary", &mut expected, &first_token_drift)
            .expect_err("a prompt without a stable first token must fail");
        assert!(err.to_string().contains("no stable first token"));
    }

