    #[test]
    fn canary_matrix_accepts_seed_phash_and_attestation_descriptors() {
        let mut catalog = test_catalog(&"aa".repeat(32));
        catalog.models[0].tier = "launch".to_owned();
        make_test_catalog_endpoint_calibration_compatible(&mut catalog.models[0]);
        catalog.models[0].model_class = "image-generation".to_owned();
        catalog.models[0].canary.set_id = "test-image-canary".to_owned();
        catalog.models[0].canary.verification_method = "seed_perceptual_hash".to_owned();
        catalog.models[0].canary.verification_tolerance_bps = Some(1_500);
        catalog.models[0].canary.perceptual_hashes.insert(
            "gguf-q4_k_m".to_owned(),
            BTreeMap::from([("p1".to_owned(), "e0e0d8d8d8f83e56".to_owned())]),
        );
        add_test_model_modality_evidence(&mut catalog.models[0], "gguf-q4_k_m", "text");
        let canaries_dir = test_canary_dir("test-image-canary", 0.0);

        let report = catalog_canary_matrix_report(
            &catalog,
            PathBuf::from("catalog.json"),
            canaries_dir.clone(),
            true,
        );

        assert!(report.ok, "{:?}", report.errors);
        assert_eq!(
            report.entries[0].calibration_status,
            "seed-perceptual-hash-calibrated"
        );
        assert_eq!(report.entries[0].perceptual_hash_count, Some(1));

        catalog.models[0].model_class = "stt".to_owned();
        catalog.models[0].canary.verification_method = "attestation_of_compute".to_owned();
        catalog.models[0].canary.verification_tolerance_bps = None;
        catalog.models[0].canary.perceptual_hashes.clear();
        let report = catalog_canary_matrix_report(
            &catalog,
            PathBuf::from("catalog.json"),
            canaries_dir,
            true,
        );

        assert!(!report.ok);
        assert_eq!(
            report.entries[0].calibration_status,
            "attestation-of-compute-descriptor"
        );
        assert!(report.errors.iter().any(|error| error
            .contains("launch model_class stt requires output canary method transcript_match")));
    }

    #[test]
    fn non_text_canary_calibration_helpers_emit_typed_values() {
        let embedding_prompt: CanaryPrompt = serde_json::from_value(json!({
            "id": "embed-p1",
            "input": "embedding canary"
        }))
        .unwrap();
        let mut embedding_backend = FakeEngineBackend::new("unused");
        let embedding =
            calibrate_embedding_cosine_prompt(&mut embedding_backend, &embedding_prompt).unwrap();
        assert_eq!(embedding.embedding_vector, Some(vec![0.1, 0.2, 0.3]));
        assert_eq!(
            embedding.fingerprint,
            embedding_vector_fingerprint(&[0.1, 0.2, 0.3])
        );

        let wav = tiny_wav_bytes(16_000);
        let stt_prompt: CanaryPrompt = serde_json::from_value(json!({
            "id": "stt-p1",
            "audio_b64": base64::engine::general_purpose::STANDARD.encode(&wav),
            "content_type": "audio/wav",
            "language": "en",
            "expected_transcript": "hello mayhem",
            "minimum_audio_seconds": 1,
            "require_word_timestamps": true,
            "require_segment_timestamps": true
        }))
        .unwrap();
        let mut stt_backend = FakeEngineBackend::new("unused");
        let transcript =
            calibrate_transcript_match_prompt(&mut stt_backend, &stt_prompt, true).unwrap();
        assert_eq!(transcript.transcript.as_deref(), Some("hello mayhem"));
        assert_eq!(transcript.output_text.as_deref(), Some("hello mayhem"));
        assert_eq!(
            transcript.fingerprint,
            blake3_bytes_hex(normalize_canary_transcript("hello mayhem").as_bytes())
        );

        let mut punctuation_mismatch = stt_prompt;
        punctuation_mismatch.expected_transcript = Some("Hello, mayhem!".to_owned());
        assert!(
            calibrate_transcript_match_prompt(&mut stt_backend, &punctuation_mismatch, false)
                .unwrap_err()
                .to_string()
                .contains("does not exactly match")
        );

        let tts_wav = tiny_wav_bytes(24_000);
        let tts_prompt: CanaryPrompt = serde_json::from_value(json!({
            "id": "tts-p1",
            "input": "hello speech",
            "voice": "launch",
            "response_format": "wav"
        }))
        .unwrap();
        let mut tts_backend =
            FakeEngineBackend::new("").with_artifact_chunks(vec![ArtifactChunk {
                artifact_id: "speech-1".to_owned(),
                index: 0,
                content_type: "audio/wav".to_owned(),
                bytes: tts_wav.clone(),
                final_chunk: true,
            }]);
        let mut tts_model = test_catalog(&"aa".repeat(32)).models[0].clone();
        tts_model.model_class = "tts".to_owned();
        tts_model.adapter.endpoint_families =
            vec![mayhem_proto::endpoint_family_contract_template(
                mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH,
            )
            .expect("OpenAI speech endpoint contract")];
        let artifact_output = test_temp_dir("mayhem-calibration-artifacts");
        let speech = calibrate_audio_fingerprint_prompt(
            &mut tts_backend,
            &tts_model,
            &tts_prompt,
            Some(&artifact_output),
        )
        .unwrap();
        assert_eq!(
            speech.audio_fingerprint.as_deref(),
            Some(audio_fingerprint(&tts_wav).as_str())
        );
        assert_eq!(
            fs::read(artifact_output.join("tts-p1-0.wav")).unwrap(),
            tts_wav
        );
        fs::remove_dir_all(&artifact_output).unwrap();

        let mut music_model = test_catalog(&"aa".repeat(32)).models[0].clone();
        music_model.model_class = "music-generation".to_owned();
        music_model.adapter.endpoint_families =
            vec![mayhem_proto::endpoint_family_contract_template(
                mayhem_proto::ENDPOINT_MAYHEM_MUSIC_GENERATIONS,
            )
            .expect("music endpoint contract")];
        let contract = music_model.adapter.endpoint_families.first_mut().unwrap();
        for (name, value) in [
            ("duration_seconds", json!(12)),
            ("response_format", json!("wav")),
            ("steps", json!(50)),
            ("guidance_scale", json!(7.0)),
            ("seed", json!(99)),
            ("n", json!(1)),
        ] {
            contract
                .request_attribute_specs
                .get_mut(name)
                .unwrap_or_else(|| panic!("missing {name} music attribute"))
                .default = Some(value);
        }
        let music_prompt: CanaryPrompt = serde_json::from_value(json!({
            "id": "music-p1",
            "prompt": "an instrumental calibration cue"
        }))
        .unwrap();
        let music_wav = tiny_wav_bytes(12 * 16_000);
        let mut music_backend =
            FakeEngineBackend::new("").with_artifact_chunks(vec![ArtifactChunk {
                artifact_id: "music-1".to_owned(),
                index: 0,
                content_type: "audio/wav".to_owned(),
                bytes: music_wav,
                final_chunk: true,
            }]);
        let music = calibrate_audio_fingerprint_prompt(
            &mut music_backend,
            &music_model,
            &music_prompt,
            None,
        )
        .unwrap();
        assert_eq!(music.resource_items["audio"].item_units, 12);
        let request = music_backend
            .last_music_request
            .expect("music calibration request");
        assert_eq!(request.duration_seconds, Some(12));
        assert_eq!(request.response_format.as_deref(), Some("wav"));
        assert_eq!(request.step_count, Some(50));
        assert_eq!(request.request["guidance_scale"], 7.0);
        assert_eq!(request.request["seed"], 99);
    }

    #[test]
    fn chatterbox_audio_fingerprint_calibration_uses_signed_reference_and_controls() {
        let reference_wav = tiny_wav_bytes(8_000);
        let output_wav = tiny_wav_bytes(24_000);
        let reference_b64 = base64::engine::general_purpose::STANDARD.encode(&reference_wav);
        let prompt: CanaryPrompt = serde_json::from_value(json!({
            "id": "chatterbox-tts-p1",
            "input": "A fixed Chatterbox calibration sentence.",
            "voice": "default",
            "response_format": "wav",
            "audio_b64": reference_b64,
            "content_type": "audio/wav",
            "temperature": 0.8,
            "min_p": 0.05,
            "top_p": 0.95,
            "repeat_penalty": 1.2,
            "seed": 17,
            "exaggeration": 0.7,
            "cfg_weight": 0.4
        }))
        .unwrap();
        let mut model = test_catalog(&"aa".repeat(32)).models[0].clone();
        model.model_class = "tts".to_owned();
        model.artifacts.get_mut("gguf-q4_k_m").unwrap().engine = "chatterbox".to_owned();
        model.adapter.endpoint_families = vec![mayhem_proto::endpoint_family_contract_template(
            mayhem_proto::ENDPOINT_OPENAI_AUDIO_SPEECH,
        )
        .expect("OpenAI speech endpoint contract")];
        let mut backend = FakeEngineBackend::new("").with_artifact_chunks(vec![ArtifactChunk {
            artifact_id: "chatterbox-speech-1".to_owned(),
            index: 0,
            content_type: "audio/wav".to_owned(),
            bytes: output_wav,
            final_chunk: true,
        }]);

        let report =
            calibrate_audio_fingerprint_prompt(&mut backend, &model, &prompt, None).unwrap();
        let request = backend
            .last_speech_request
            .expect("Chatterbox calibration speech request");
        assert_eq!(
            request
                .reference_audio
                .as_ref()
                .expect("fixed reference WAV")
                .data,
            reference_wav
        );
        assert_eq!(request.exaggeration, Some(0.7));
        assert_eq!(request.cfg_weight, Some(0.4));
        assert_eq!(request.seed, Some(17));
        assert_eq!(request.temperature, Some(0.8));
        assert_eq!(request.min_p, Some(0.05));
        assert_eq!(request.top_p, Some(0.95));
        assert_eq!(request.repetition_penalty, Some(1.2));

        let serialized = serde_json::to_string(&report).unwrap();
        assert!(
            !serialized.contains(&base64::engine::general_purpose::STANDARD.encode(&reference_wav)),
            "calibration report retained the private reference audio"
        );

        let mut incomplete = prompt;
        incomplete.endpoint_attributes.remove("cfg_weight");
        let mut rejected_backend = FakeEngineBackend::new("");
        let error =
            calibrate_audio_fingerprint_prompt(&mut rejected_backend, &model, &incomplete, None)
                .expect_err("incomplete Chatterbox calibration controls must fail");
        assert!(format!("{error:#}").contains("signed control cfg_weight"));
        assert!(rejected_backend.last_speech_request.is_none());
    }

