    #[test]
    fn speciality_report_accepts_non_token_behavioral_fingerprints() {
        let mut catalog = test_catalog(&"aa".repeat(32));
        add_test_reasoning_speciality(&mut catalog.models[0]);
        let model = &mut catalog.models[0];
        model.canary.verification_method = CANARY_VERIFICATION_VIDEO_AV_FINGERPRINT.to_owned();
        let descriptor = &mut model.adapter.specialities[0];
        descriptor.name = "prompt_enhancer".to_owned();
        descriptor.mechanism = "boolean".to_owned();
        descriptor.default_level = "off".to_owned();
        descriptor.calibration_modalities = vec!["video".to_owned()];
        descriptor.levels = vec![
            mayhem_proto::ModelSpecialityLevel {
                name: "off".to_owned(),
                rank: 0,
                native_value: json!(false),
                default_max_output_tokens: None,
                max_reasoning_tokens: None,
            },
            mayhem_proto::ModelSpecialityLevel {
                name: "on".to_owned(),
                rank: 1,
                native_value: json!(true),
                default_max_output_tokens: None,
                max_reasoning_tokens: None,
            },
        ];
        for contract in &mut model.adapter.endpoint_families {
            contract.speciality_mappings.clear();
            contract.speciality_mappings.insert(
                "prompt_enhancer".to_owned(),
                mayhem_proto::EndpointSpecialityMapping {
                    request_path: "enhance_prompt".to_owned(),
                    target: mayhem_proto::EndpointSpecialityTarget::BackendParameter,
                    native_path: "enhance_prompt".to_owned(),
                    selector: mayhem_proto::EndpointSpecialitySelector::Exact,
                },
            );
        }
        let level_report = |marker: &str| {
            let fingerprint = format!(
                "videoav-v1:{}",
                hex_encode(
                    serde_json::to_vec(&json!({
                        "width": 256,
                        "height": 256,
                        "frame_count": 9,
                        "fps_milli": 8000,
                        "video_duration_ms": 1125,
                        "audio_duration_ms": 1125,
                        "frame_hashes": [marker.repeat(32)],
                        "audio_fingerprint": format!("audiospec-v1:1125:{}", marker.repeat(256)),
                    }))
                    .unwrap()
                    .as_slice()
                )
            );
            assert!(valid_video_av_fingerprint(&fingerprint));
            let mut prompt = test_calibration_prompt("video-p1", fingerprint.clone());
            prompt.max_tokens = 1;
            prompt.prompt_tokens = 0;
            prompt.completion_tokens = 0;
            prompt.reasoning_tokens = 0;
            prompt.token_count = 0;
            prompt.token_ids.clear();
            prompt.token_prefix.clear();
            prompt.video_fingerprint = Some(fingerprint);
            let prompts = vec![prompt];
            CanarySpecialityCalibrationReport {
                fingerprint: aggregate_canary_fingerprint_for_method(
                    CANARY_VERIFICATION_VIDEO_AV_FINGERPRINT,
                    &prompts,
                ),
                verification_method: CANARY_VERIFICATION_VIDEO_AV_FINGERPRINT.to_owned(),
                token_prefixes: BTreeMap::new(),
                output_tokens_min: 0,
                output_tokens_max: 0,
                reasoning_tokens_min: 0,
                reasoning_tokens_max: 0,
                prompts,
            }
        };
        let calibrated = BTreeMap::from([(
            "prompt_enhancer".to_owned(),
            BTreeMap::from([
                ("off".to_owned(), level_report("01")),
                ("on".to_owned(), level_report("02")),
            ]),
        )]);
        let mut errors = Vec::new();
        validate_speciality_calibration_report(
            model,
            "gguf-q4_k_m",
            &model.artifacts["gguf-q4_k_m"],
            &BTreeMap::from([("prompt_enhancer".to_owned(), vec!["video-p1".to_owned()])]),
            &calibrated,
            &mut errors,
        );
        assert!(errors.is_empty(), "{errors:?}");
        let compact = compact_speciality_calibration_report(&calibrated);
        assert_eq!(
            compact["prompt_enhancer"]["on"]
                .verification_method
                .as_deref(),
            Some(CANARY_VERIFICATION_VIDEO_AV_FINGERPRINT)
        );
        assert!(compact["prompt_enhancer"]["on"].token_prefixes.is_empty());
    }

    #[test]
    fn speciality_calibration_apply_and_verify_require_every_signed_level() {
        let mut catalog = test_catalog(&"aa".repeat(32));
        catalog.models[0].tier = "launch".to_owned();
        catalog.models[0].canary.set_id = "test-speciality-canary".to_owned();
        add_test_reasoning_speciality(&mut catalog.models[0]);
        let canaries_dir = test_canary_dir_with_prompts(
            "test-speciality-canary",
            json!([{
                "id": "p1",
                "messages": [{"role": "user", "content": "reason"}],
                "max_tokens": 8,
                "temperature": 0.0
            }]),
        );
        let base_tokens = vec![1; MIN_LAUNCH_CANARY_STABLE_PREFIX_TOKENS];
        let mut base_prompt =
            test_calibration_prompt("p1", canary_token_fingerprint(base_tokens.iter().copied()));
        base_prompt.max_tokens = u32::try_from(base_tokens.len()).unwrap();
        base_prompt.completion_tokens = u32::try_from(base_tokens.len()).unwrap();
        base_prompt.token_count = base_tokens.len();
        base_prompt.token_ids = base_tokens.clone();
        base_prompt.token_prefix = base_tokens.clone();
        let base_fingerprint = aggregate_canary_fingerprint(std::slice::from_ref(&base_prompt));
        let mut calibration = test_calibration_report(base_fingerprint.clone(), None);
        calibration.catalog_fingerprint = base_fingerprint.clone();
        calibration.model_id = catalog.models[0].model_id.clone();
        calibration.canary_set = "test-speciality-canary".to_owned();
        calibration.prompts = vec![base_prompt];
        calibration.speciality_calibrations = test_speciality_calibration_report_map();
        calibration.endpoint_calibration =
            test_endpoint_calibration_report_for_adapter(&catalog.models[0].adapter);
        stamp_test_calibration_report(&mut calibration, &canaries_dir);
        let full_report_path = write_temp_calibration_report(&calibration);

        let apply_report = catalog_canary_evidence_report(
            &catalog,
            PathBuf::from("catalog.json"),
            canaries_dir.clone(),
            true,
            std::slice::from_ref(&full_report_path),
            CatalogCanaryReportMode::ApplyToCatalog,
        );
        assert!(apply_report.ok, "{:?}", apply_report.errors);
        let mut catalog_value = json!({
            "models": [{
                "model_id": catalog.models[0].model_id.clone(),
                "modality_assessment": {},
                "speciality_assessment": {},
                "canary": {
                    "set_id": "test-speciality-canary",
                    "verification_method": "token_fingerprint"
                }
            }]
        });
        assert_eq!(
            apply_canary_report_fingerprints(&mut catalog_value, &apply_report).unwrap(),
            1
        );
        assert_eq!(
            catalog_value["models"][0]["speciality_assessment"]["calibrated"]["gguf-q4_k_m"]
                ["reasoning_effort"]["high"]["reasoning_tokens_max"],
            json!(1)
        );

        let compact = compact_speciality_calibration_report(&calibration.speciality_calibrations);
        catalog.models[0]
            .speciality_assessment
            .calibrated
            .insert("gguf-q4_k_m".to_owned(), compact);
        catalog.models[0]
            .canary
            .fingerprints
            .insert("gguf-q4_k_m".to_owned(), base_fingerprint);
        catalog.models[0].canary.token_prefixes.insert(
            "gguf-q4_k_m".to_owned(),
            BTreeMap::from([("p1".to_owned(), base_tokens)]),
        );
        catalog.models[0]
            .modality_assessment
            .calibrated_fingerprints
            .insert(
                "gguf-q4_k_m".to_owned(),
                BTreeMap::from([("text".to_owned(), "cc".repeat(32))]),
            );
        let mut incomplete = calibration;
        incomplete
            .speciality_calibrations
            .get_mut("reasoning_effort")
            .unwrap()
            .remove("high");
        let incomplete_report_path = write_temp_calibration_report(&incomplete);

        for mode in [
            CatalogCanaryReportMode::ApplyToCatalog,
            CatalogCanaryReportMode::VerifyMatchesCatalog,
        ] {
            let report = catalog_canary_evidence_report(
                &catalog,
                PathBuf::from("catalog.json"),
                canaries_dir.clone(),
                true,
                std::slice::from_ref(&incomplete_report_path),
                mode,
            );
            assert!(!report.ok);
            assert!(report
                .errors
                .iter()
                .any(|error| error.contains("missing level high")));
        }
    }

