        assert_eq!(
            entry.artifact_path,
            PathBuf::from(format!(
                "/tmp/mayhem-stage-artifacts/huggingface/test_model/{}/model.gguf",
                "1".repeat(40)
            ))
        );
        assert!(entry.stage_command.shell.contains("convert_hf_to_gguf.py"));
