    #[test]
    fn artifact_publish_plan_emits_upload_revision_metadata_and_followups() {
        let mut catalog = test_catalog(&"aa".repeat(32));
        catalog.models[0].tier = "launch".to_owned();
        let mut ignored = catalog.models[0].artifacts["gguf-q4_k_m"].clone();
        ignored.path = "ignored.gguf".to_owned();
        ignored.weights_bytes = 9_999;
        catalog.models[0]
            .artifacts
            .insert("ignored-artifact".to_owned(), ignored);
        let temp = env::temp_dir().join(format!(
            "mayhem-artifact-publish-plan-{}-{}",
            std::process::id(),
            now_millis_for_path()
        ));
        let artifact_base = temp.join("artifacts");
        let expected_artifact_path = artifact_base
            .join("huggingface")
            .join("test_model")
            .join("1".repeat(40))
            .join("model.gguf");
        fs::create_dir_all(expected_artifact_path.parent().unwrap()).unwrap();
        fs::write(&expected_artifact_path, b"publish-plan artifact").unwrap();
        let sign = CatalogCanaryPlanSignOptions {
            base_catalog_path: temp.join("catalog.json"),
            base_signature_path: temp.join("catalog.json.sig"),
            signature_output: temp.join("reports/models.json.sig"),
            key_id: "test-catalog-key".to_owned(),
            seed_file: temp.join("catalog-seed.hex"),
            keys_dir: temp.join("catalog-keys"),
            write_key: true,
            created_at: Some("2026-07-04T00:00:00Z".to_owned()),
        };
        let report_dir = temp.join("reports");

        let report = catalog_artifact_publish_plan_report(CatalogArtifactPublishPlanInput {
            catalog_doc: &catalog,
            catalog_path: temp.join("catalog.json"),
            artifact_base: artifact_base.clone(),
            report_dir: report_dir.clone(),
            catalog_output: report_dir.join("catalog.with-artifacts.json"),
            catalog_sign: Some(sign),
            hf_token_file: Some(temp.join("hf-token.txt")),
            launch_only: true,
            model_filter: Some("test/model@4bit".to_owned()),
            artifact_filter: Some("gguf-q4_k_m".to_owned()),
        });

        assert!(report.ok, "{:?}", report.errors);
        assert_eq!(report.model_count, 1);
        assert_eq!(report.artifact_count, 1);
        assert_eq!(report.catalog_expected_bytes, 42);
        assert_eq!(report.current_artifact_bytes, 21);
        assert_eq!(report.missing_artifact_bytes, 0);
        assert_eq!(report.artifact_base_space_ok, Some(true));
        assert!(report.preflight_command.shell.contains("command -v hf"));
        assert!(report.preflight_command.shell.contains("$HOME/.local/bin"));
        assert!(report.preflight_command.shell.contains("MAYHEM_HF_VENV"));
        assert!(report
            .preflight_command
            .shell
            .contains("import huggingface_hub"));
        assert!(report.preflight_command.shell.contains("hf-token.txt"));
        let entry = &report.publish_commands[0];
        assert_eq!(entry.current_artifact_path, expected_artifact_path);
        assert_eq!(entry.catalog_weights_bytes, 42);
        assert!(entry.current_artifact_exists);
        assert!(entry.current_artifact_is_file);
        assert_eq!(entry.current_artifact_bytes, Some(21));
        assert_eq!(
            entry.published_artifact_path_template,
            artifact_base
                .join("huggingface")
                .join("test_model")
                .join("<published-hf-commit-40-hex>")
                .join("model.gguf")
        );
        assert_eq!(entry.upload_command.argv[0], "hf");
        assert!(entry
            .upload_command
            .argv
            .windows(2)
            .any(|pair| { pair[0] == "--repo-type" && pair[1] == "model" }));
        assert!(entry
            .upload_command
            .shell
            .contains("HF_XET_HIGH_PERFORMANCE=1"));
        assert!(entry.upload_command.shell.contains("$HOME/.local/bin"));
        assert!(entry.upload_command.shell.contains("MAYHEM_HF_VENV"));
        assert!(entry.upload_command.shell.contains("hf-token.txt"));
        assert!(entry.revision_command.shell.contains("HfApi"));
        assert!(entry.revision_command.shell.contains("$HOME/.local/bin"));
        assert!(entry.revision_command.shell.contains("MAYHEM_HF_VENV"));
        assert!(entry.revision_command.shell.contains("hf-token.txt"));
        assert!(entry.metadata_command_template.argv.windows(2).any(|pair| {
            pair[0] == "--source-revision" && pair[1] == "<published-hf-commit-40-hex>"
        }));
        assert!(entry
            .metadata_after_publish_shell
            .contains("PUBLISHED_REVISION=$("));
        assert!(entry.metadata_after_publish_shell.contains("ln -sfn"));
        assert!(entry
            .metadata_after_publish_shell
            .contains("\"$PUBLISHED_ARTIFACT_PATH\""));
        let signature_command = report.signature_command.as_ref().unwrap();
        assert!(signature_command.shell.contains("'catalog' 'sign'"));
        assert!(signature_command
            .argv
            .windows(2)
            .any(|pair| pair[0] == "--base-catalog-path"
                && pair[1] == temp.join("catalog.json").display().to_string()));
        assert!(signature_command
            .argv
            .windows(2)
            .any(|pair| pair[0] == "--base-signature-path"
                && pair[1] == temp.join("catalog.json.sig").display().to_string()));
        let verify_command = report.verify_command.as_ref().unwrap();
        assert!(verify_command
            .argv
            .windows(2)
            .any(|pair| pair[0] == "--hf-token-file" && pair[1].ends_with("hf-token.txt")));

        let missing = catalog_artifact_publish_plan_report(CatalogArtifactPublishPlanInput {
            catalog_doc: &catalog,
            catalog_path: temp.join("catalog.json"),
            artifact_base,
            report_dir,
            catalog_output: temp.join("reports/catalog.with-artifacts.json"),
            catalog_sign: None,
            hf_token_file: None,
            launch_only: true,
            model_filter: Some("test/model@4bit".to_owned()),
            artifact_filter: Some("missing-artifact".to_owned()),
        });
        assert!(!missing.ok);
        assert!(missing.errors.iter().any(|error| error.contains(
            "catalog selection matched no launch artifact missing-artifact for model test/model@4bit"
        )));

        let _ = fs::remove_dir_all(temp);
    }

