    fn test_endpoint_calibration_report_for_adapter(
        adapter: &catalog::CatalogAdapter,
    ) -> EndpointCalibrationReport {
        let fixture_bytes = tiny_wav_bytes(8_000);
        let fixture_b64 = base64::engine::general_purpose::STANDARD.encode(&fixture_bytes);
        let report = run_endpoint_calibration_matrix(
            &adapter.endpoint_families,
            &BTreeMap::from([
                ("$MODEL".to_owned(), json!("test/model")),
                ("$MODEL_VALUE".to_owned(), json!("test/model")),
                ("$RESPONSE_VALUE".to_owned(), json!("json")),
                (
                    "$IMAGE_DATA_URL".to_owned(),
                    json!("data:image/png;base64,aGVsbG8="),
                ),
                ("$IMAGE_FILE".to_owned(), json!("fixture.png")),
                ("$AUDIO_BASE64".to_owned(), json!(fixture_b64)),
                ("$AUDIO_BYTES".to_owned(), json!(fixture_bytes.len())),
                (
                    "$AUDIO_BLAKE3".to_owned(),
                    json!(blake3::hash(&fixture_bytes).to_hex().to_string()),
                ),
                ("$AUDIO_CONTENT_TYPE".to_owned(), json!("audio/wav")),
                ("$AUDIO_FILENAME".to_owned(), json!("calibration.wav")),
                ("$VIDEO_BASE64".to_owned(), json!("aGVsbG8=")),
                ("$VOICE".to_owned(), json!("launch")),
            ]),
            |contract, _case, request| {
                Ok(EndpointCalibrationExecution {
                    provider_translation_fingerprint: "11".repeat(32),
                    handled_request_attributes: contract
                        .request_attributes
                        .iter()
                        .filter(|path| calibration_value_has_path(request, path))
                        .cloned()
                        .collect(),
                    backend_execution_fingerprint: "22".repeat(32),
                    backend_proof: EndpointCalibrationBackendProof {
                        kind: EndpointCalibrationBackendProofKind::FullInference,
                        behavioral_witness_fingerprint: None,
                    },
                    response: json!({
                        "id": "chatcmpl-test",
                        "object": "chat.completion",
                        "created": 1,
                        "model": "test/model",
                        "choices": [{
                            "index": 0,
                            "message": {"role": "assistant", "content": "ok"},
                            "finish_reason": "stop"
                        }],
                        "usage": {
                            "prompt_tokens": 1,
                            "completion_tokens": 1,
                            "total_tokens": 2
                        },
                        "mayhem": {}
                    }),
                })
            },
        );
        assert!(
            report.ok,
            "synthetic endpoint report failed: {:#?}",
            report
                .families
                .iter()
                .flat_map(|family| &family.cases)
                .find(|case| !case.ok)
        );
        report
    }

    #[test]
    fn endpoint_semantic_proof_requires_a_canonical_behavioral_witness() {
        let mut report = test_calibration_report("witness".to_owned(), None);
        let semantic_fingerprint = "bb".repeat(32);
        let accepted = report
            .endpoint_calibration
            .families
            .iter_mut()
            .flat_map(|family| &mut family.cases)
            .find(|case| case.expect_accept)
            .expect("accepted endpoint calibration row");
        accepted.backend_proof = Some(EndpointCalibrationBackendProof {
            kind: EndpointCalibrationBackendProofKind::WorkerSemanticValidation,
            behavioral_witness_fingerprint: Some(semantic_fingerprint.clone()),
        });

        let missing = validate_endpoint_behavioral_witness_links(&report);
        assert!(missing.iter().any(|error| {
            error.contains("absent from canonical canary evidence")
                && error.contains(&semantic_fingerprint)
        }));

        report.prompts[0].behavioral_output_fingerprint = Some(semantic_fingerprint);
        assert!(validate_endpoint_behavioral_witness_links(&report).is_empty());
    }

